INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-herath-kashmir', 'Herath (Maha Shivratri of Kashmir)', ARRAY['Har-ratri', 'Vatuk Puja']::TEXT[], 'Spiritual & Temple', 'Hinduism (Kashmiri Shaivism)', 'The primary festival of Kashmiri Pandits celebrating the divine wedding of Lord Shiva and Devi Parvati with distinctive walnut-filled clay pot rituals.', 'Rooted in Trika Kashmir Shaivism philosophical texts dating back to the 1st millennium CE.', 'Commemorates the manifestation of Shiva as Jwalalinga and his celestial union with Parvati.', 'To honor Lord Shiva (Bhairava) and seek wisdom, spiritual liberation, and family welfare.', 'Represents the unity of Shiva and Shakti through ascetic and tantric domestic rituals.', 'Sustained Kashmiri Hindu indigenous traditions through centuries of cultural transformation.', ARRAY['Vatuk Puja using water and walnut filled earthen pots', 'Doon Mavas walnut distribution', 'Nightlong recitation of Shiva Mahimna Stotra']::TEXT[], 'Families gather at home for nightlong pujas, offering walnuts steeped in water to relatives and neighbors.', ARRAY['Roganjosh', 'Dum Aloo', 'Chochwor', 'Walnut prasad', 'Modur Pulao']::TEXT[], 'Traditional Kashmiri Pheran with tilla embroidery and Taranga headdress.', 'Devotional Sufiana Kalam, Kashmiri Shiva stutis, and Santoor accompaniment.', 'Vatuk earthen pitchers, fresh walnuts, wild Bilva leaves, and floral alpana.', '3 Days', 'Hindu Lunisolar (Kashmiri Bikrami)', 'Krishna Paksha Trayodashi of Phalguna month', 'February - March', 'LUNISOLAR', 'Celebrated on the 13th night of Phalguna Krishna Paksha.', '2026-02-15', '2027-03-06', 'Kashmiri Pandit Sabha Panchang', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Srinagar', 'Jammu', 'Anantnag']::TEXT[], ARRAY['Shankaracharya Temple', 'Kheer Bhawani Shrine', 'Aap Shambhu Temple Jammu']::TEXT[], 'Evening during Vatuk Puja and morning of Doon Mavas', 2, 'Warm hospitality in Kashmiri homes, mystical winter ambiance, and soul-stirring hymns echoing over Dal Lake.', 'Local auto-rickshaws, pre-paid taxis, and Srinagar airport cabs.', 'Pre-book heated hotel rooms or Dal Lake houseboats with bukhari heating.', 'Peaceful family atmosphere; security check-posts active across shrines.', 'Remove footwear before entering puja rooms; accept walnut prasad with both hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.jktourism.jk.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tulip-festival-srinagar', 'Tulip Festival Srinagar', ARRAY['Indira Gandhi Memorial Tulip Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Nature', 'Asia''s largest tulip festival celebrating the blooming of over 1.5 million tulips in 60 varieties against the Zabarwan mountain range overlooking Dal Lake.', 'Inaugurated in 2007 by Jammu and Kashmir Tourism to promote spring valley tourism.', 'Celebrates the arrival of spring and blooming of alpine floral terraces.', 'To showcase Jammu & Kashmir''s botanical beauty and herald the spring travel season.', 'Symbol of revitalization, floral heritage, and community harmony in Kashmir.', 'Transformed Srinagar''s spring shoulder season into a premier global tourist window.', ARRAY['Floral exhibitions and garden walkthroughs', 'Folk art demonstrations', 'Kashmiri craft artisan stalls']::TEXT[], 'Visitors stroll through 30 hectares of terraced garden beds enjoying live music and handicrafts.', ARRAY['Kashmiri Kahwa with crushed almonds', 'Harissa', 'Seekh Tujji', 'Nadru Pakora']::TEXT[], 'Colorful pherans with embroidered collars and Kashmiri pashmina shawls.', 'Rouff dance by Kashmiri women ensembles, Santoor, and Rabab performances.', 'Rainbow-striped tulip rows, terraced fountains, and Zabarwan mountain backdrop.', '15 to 20 Days', 'Gregorian / Seasonal', 'Timing depends on springtime temperature and tulip bloom.', 'April', 'SEASONAL', 'Usually commences first week of April depending on bud blossoming.', '2026-04-05', '2027-04-03', 'Jammu & Kashmir Tourism Floriculture Department', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Srinagar']::TEXT[], ARRAY['Indira Gandhi Memorial Tulip Garden, Cheshmashahi']::TEXT[], 'Mid-morning or golden hour late afternoon', 2, 'Spectacular visual spectacle of 1.5 million vibrant blooms with snowy peaks framing Dal Lake.', 'Taxis, auto-rickshaws, and Dal lake shikaras connecting Boulevard Road.', 'Srinagar hotel rates peak during bloom; advance booking 6-8 weeks prior is essential.', 'Large tourist crowds on weekends; follow barricaded walking trails.', 'Do not step into tulip flowerbeds or pluck blooms; keep designated camera paths.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.jktourism.jk.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shikara-festival-kashmir', 'Shikara Festival Dal Lake', ARRAY['Dal Lake Shikara Carnival']::TEXT[], 'Art & Cultural Festival', 'Secular / Water Heritage', 'A vibrant aquatic festival on Dal Lake featuring colorfully adorned wooden boats, shikara racing, canoe polo, and floating craft markets.', 'Conceptualized by Kashmir Tourism to honor the iconic flat-bottomed boat that has sustained Dal Lake life for centuries.', 'Celebrates the centuries-old lifestyle of Dal Lake''s water-borne Hanji community.', 'To preserve traditional boat building crafts and promote Kashmiri water culture.', 'Emphasizes eco-tourism, pristine aquatic ecology, and artisanal livelihoods.', 'Showcases the living heritage of Kashmir''s iconic waterways to global travelers.', ARRAY['Grand Shikara boat races across Boulevard promenade', 'Floating cultural stage performances', 'Evening water light-and-sound parades']::TEXT[], 'Shikara boatmen decorate wooden canopies with chintz fabrics and compete in synchronized regattas.', ARRAY['Sheermal', 'Kashmiri Pink Nun Chai', 'Mutton Rogan Josh', 'Lotus Stem Kebabs']::TEXT[], 'Traditional Kurta Pajama with embroidered Nehru coats and Hanji boatman caps.', 'Sufi music performances on floating barges, Kashmiri Rabab, and Chakri folk singing.', 'Curved wooden prows, embroidered floral awnings, and heart-shaped boat oars.', '2 Days', 'Organizer Announced', 'Scheduled during peak summer/autumn season by J&K Tourism.', 'July - August', 'ORGANIZER_ANNOUNCED', 'Announced annually by Department of Tourism.', '2026-08-08', '2027-08-07', 'J&K Tourism Calendar', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Srinagar']::TEXT[], ARRAY['Dal Lake Boulevard Promenade', 'Nigeen Lake', 'Nehru Park']::TEXT[], 'Late afternoon into illuminated night parade', 2, 'Serene glide across mountain-ringed waters surrounded by floating flower markets and glowing lanterns.', 'Shikara boat rides from Boulevard Ghats 1 to 15.', 'Stay in heritage cedar-wood houseboats along Dal or Nigeen Lake.', 'Wear life-jackets during boat races; keep children seated securely.', 'Do not throw plastic or waste into the lake; support local boatmen fair pricing.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.jktourism.jk.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gurez-festival', 'Gurez Valley Festival', ARRAY['Dard-Shin Cultural Mahotsav']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Dardic Culture', 'A high-altitude celebration in Gurez Valley showcasing the unique heritage, language, and ancestral customs of the Dard-Shin community.', 'Celebrates the ancient Silk Route connector valley along the Kishanganga river.', 'Dardic pastoral migration and mountain solstice survival rituals.', 'To preserve Shina tribal language, customs, and boost border eco-tourism.', 'Highlights the endangered Dard ethnic identity and alpine lifestyle.', 'Reopened historic Himalayan borderlands to responsible cultural explorers.', ARRAY['Shina language folk ballads and war dances', 'Traditional trout angling competitions', 'Campfire storytelling beneath Habba Khatoon peak']::TEXT[], 'Villagers from Dawar and remote hamlets dress in woolens and present archery and dance performances.', ARRAY['Gurezi Trout fish fry', 'Buckwheat pancakes', 'Apricot kernels', 'Butter salted tea']::TEXT[], 'Thick woolen Gonchas, sheepskin coats, and floral silver trinkets.', 'Traditional flute, Damama drums, and rhythmic Dardic community round-dances.', 'Habba Khatoon pyramidal mountain peak, Kishanganga river waters, and birch-bark manuscripts.', '2 Days', 'Organizer Announced', 'Held during mid-summer when Razdan Pass is snow-free.', 'July - August', 'ORGANIZER_ANNOUNCED', 'Organized by Bandipora District Administration & J&K Tourism.', '2026-07-25', '2027-07-24', 'Bandipora District Portal', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Dawar (Gurez)', 'Bandipora']::TEXT[], ARRAY['Dawar Helipad Grounds', 'Habba Khatoon Spring', 'Kishanganga Riverfront']::TEXT[], 'Full daytime cultural hours and evening campfires', 3, 'Pure untouched Himalayan landscapes, wooden log houses, and heartwarming Dardic hospitality.', '4x4 Sumo/Scorpio taxis via Razdan Pass (11,672 ft) from Srinagar (6-7 hours).', 'Government tourist rest houses, local homestays in Dawar, and riverside glamping camps.', 'High-altitude mountain road with hairpin bends; travel during daylight only.', 'Carry valid government photo ID for security checkpoints; obtain permits where required.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bandipora.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-baisakhi-mughal-gardens', 'Baisakhi at Mughal Gardens Srinagar', ARRAY['Kashmir Baisakhi Mela']::TEXT[], 'Harvest & Agriculture', 'Hinduism / Sikhism / Cultural', 'Spring harvest celebration observed amidst blooming terraced fountains of Shalimar and Nishat Gardens.', 'Dating back to Mughal era when Jahangir and Shah Jahan laid out pleasure gardens that bloomed during Baisakhi.', 'Celebrates the ripening of the rabi crop and the formal opening of tourist season in the Kashmir valley.', 'To celebrate nature''s abundance, water channels, and multi-faith joy in Kashmir.', 'Living showcase of Mughal water engineering and Kashmir''s secular cultural syncretism.', 'Preserves the historical tradition of spring garden outings across diverse communities.', ARRAY['Community picnics under Chinar trees', 'Special illumination of Mughal water cascades', 'Family gatherings in Shalimar Bagh']::TEXT[], 'Families lay out carpets on garden terraces, brew Kahwa on portable samovars, and celebrate spring.', ARRAY['Nadroo Yakhni', 'Kashmiri Pulao', 'Phirni', 'Kulcha with Pink Tea']::TEXT[], 'Brightly colored festive salwar kameez and pherans.', 'Live Santoor, Kashmiri folk music, and children performing swings.', 'Mughal water cascades (chhadars), ancient Chinar leaves, and blooming pansies.', '1 Day', 'Solar', 'Celebrated on the first day of the solar month of Vaisakh (April 13 or 14).', 'April', 'SOLAR', 'Mesha Sankranti solar transition.', '2026-04-14', '2027-04-14', 'Official Solar Almanac', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Srinagar']::TEXT[], ARRAY['Shalimar Bagh', 'Nishat Bagh', 'Chashme Shahi']::TEXT[], 'Afternoon and evening on April 13/14', 1, 'Lounging on lush Mughal garden lawns with water fountains sparkling, surrounded by snowy mountain peaks.', 'Boulevard road city buses, taxis, and shikara connections.', 'Srinagar city hotels and Dal Lake houseboats.', 'High family footfall; orderly ticket counter queues.', 'Do not step into historic fountains or litter garden lawns.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.jktourism.jk.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-urs-shah-e-hamdan', 'Urs Shah-e-Hamdan Srinagar', ARRAY['Urs Mir Sayyid Ali Hamadani']::TEXT[], 'Spiritual & Temple', 'Islam (Sufism)', 'The revered annual Urs of Mir Sayyid Ali Hamadani, the 14th-century Persian Sufi saint who introduced Islam and Persian arts to Kashmir.', 'Mir Sayyid Ali Hamadani arrived in Kashmir from Hamadan, Iran, with 700 craft masters, introducing carpet weaving, pashmina, and papier-mâché.', 'Celebrates the saint''s passing (Wafat) and honors his monumental spiritual and economic contribution to Kashmir.', 'Deep spiritual reverence across Kashmir; marks the origin of Kashmir''s artisan guild traditions.', 'Foundational cultural event in the history of Kashmiri Islam and world-renowned handicraft industries.', 'Marks the historical synthesis of Persian aesthetic culture and Kashmiri lifestyle.', ARRAY['Special night congregational prayers (Shab Khawani)', 'Display of holy relics (Ziyarat)', 'Recitation of Awrad-e-Fathiyya']::TEXT[], 'Thousands congregate at Khanqah-e-Moula on the Jhelum river, chanting prayers in unison.', ARRAY['Halwa Paratha', 'Tahri (turmeric seasoned rice)', 'Kashmiri Kehwa', 'Bakarkhani']::TEXT[], 'Traditional Kurta Shalwar with Karakuli astrakhan cap or woolen headscarf.', 'Awrad-e-Fathiyya collective Sufi chanting and devotional Naat poetry.', 'Carved deodar wood architecture of Khanqah-e-Moula with papier-mâché ceiling.', '1 Day', 'Islamic Lunar (Hijri)', '6th day of Dhul Hijjah', 'May - June', 'LUNAR', 'Observed on 6th of Dhul Hijjah in the Islamic calendar.', '2026-05-23', '2027-05-12', 'Wakf Board Jammu & Kashmir', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Srinagar']::TEXT[], ARRAY['Khanqah-e-Moula Old City', 'Shah-e-Hamdan Shrine Tral']::TEXT[], 'Early morning Fajr prayers and afternoon congregational relic viewing', 1, 'Immersive spiritual energy inside a 600-year-old carved wooden pagoda-style Khanqah on the serene Jhelum river.', 'Local auto-rickshaws and foot navigation through historic Zaina Kadal lanes.', 'Heritage homestays and boutique boutique hotels in Srinagar old city or Rajbagh.', 'Dense crowds around the shrine courtyard; watch personal belongings.', 'Dress modestly covering head, remove footwear outside, maintain absolute silence inside sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://srinagar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-saffron-festival-pampore', 'Saffron Harvest Festival Pampore', ARRAY['Pampore Kong Posh Utsav']::TEXT[], 'Harvest & Agriculture', 'Secular / Agricultural Heritage', 'Autumn harvest festival celebrating the plucking of purple saffron crocuses in the world-famous karewa plateaus of Pampore.', 'Kashmiri saffron (Crocus sativus) has been cultivated in Pampore karewas for over 2,500 years and holds GI tag status.', 'Celebrates the blooming of purple saffron flowers and farmer community harvests.', 'To celebrate the most precious spice in the world and promote saffron agro-tourism.', 'Cultural pride of Kashmir''s agrarian identity and unique geo-climatic gift.', 'Pampore saffron cultivation represents one of the ancient continuous agricultural landscapes of South Asia.', ARRAY['Early morning flower plucking walks in violet fields', 'Hand-separation of crimson saffron stigmas (Lacha/Mongra)', 'Artisan saffron tea brewing sessions']::TEXT[], 'Farmers and visitors pick fragrant purple blossoms, listen to folk musicians, and savor saffron-infused delicacies.', ARRAY['Kong Phirni (Saffron rice pudding)', 'Saffron Kahwa', 'Modur Pulao', 'Badam Halwa']::TEXT[], 'Bright colorful pherans and traditional headscarves.', 'Kashmiri folk singing with tumbakhnari earthen drums and harmonium.', 'Purple saffron crocus blossom, golden stigmas, and wicker collection baskets.', '3 to 5 Days', 'Seasonal / Autumn', 'Late October to early November during crocus bloom.', 'October - November', 'SEASONAL', 'Peak flowering occurs during early November crisp mornings.', '2026-11-01', '2027-11-03', 'J&K Agriculture Department', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Pampore', 'Pulwama', 'Srinagar']::TEXT[], ARRAY['Pampore Saffron Karewas', 'Saffron Park Dusoo']::TEXT[], 'Early morning (7 AM to 11 AM) when flowers bloom fresh with dew', 1, 'Wandering through endless violet fields with snow-dusted Pir Panjal peaks in the backdrop and sweet fragrance in the air.', '15 km drive from Srinagar city center via Srinagar-Jammu National Highway.', 'Stay in Srinagar hotels and commute via morning car rental.', 'Walk only along furrow paths between plant beds; do not trample corms.', 'Buy saffron only with authentic GI seal and hologram from certified grower stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pulwama.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kheer-bhawani-mela', 'Kheer Bhawani Mela Tulmulla', ARRAY['Mata Ragnya Devi Yatra']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism)', 'The foremost annual pilgrimage of Kashmiri Pandits to the sacred spring shrine of Mata Ragnya Devi at Tulmulla.', 'Ancient spring shrine mentioned in Kalhana''s Rajatarangini; the water changes color reflecting spiritual fortunes.', 'Celebrates the miraculous spring associated with Goddess Ragnya Devi mentioned in Nilamata Purana.', 'To offer milk and rice pudding (kheer) to the sacred deity and pray for peace and communal return.', 'Supreme symbol of Kashmiri Pandit cultural identity, hope, and historical roots.', 'Catalyst for inter-faith harmony as local Kashmiri Muslims welcome and assist Hindu pilgrims.', ARRAY['Offering kheer, milk, and flowers into the sacred octagonal spring', 'Chanting of Bhavani Sahasranama', 'Community Mahabhog distribution']::TEXT[], 'Tens of thousands of devotees gather at Tulmulla, lighting incense sticks and chanting around the holy chinar trees.', ARRAY['Kheer (sweet rice pudding)', 'Luchi', 'Dum Aloo', 'Nadroo fritters']::TEXT[], 'Traditional Kashmiri attire, crisp white dhotis, and embroidered pherans.', 'Recitation of Kashmiri devotional verses by Lal Ded and Arnimal, shankhanaad, and temple cymbals.', 'Sacred subterranean spring, marble temple canopy, and grand centuries-old Chinar trees.', '1 Day', 'Hindu Lunisolar', 'Jyeshtha Ashtami (8th day of Shukla Paksha in Jyeshtha month)', 'May - June', 'LUNISOLAR', 'Observed on Shukla Ashtami of Jyeshtha.', '2026-06-22', '2027-06-11', 'Mata Kheer Bhawani Trust & District Administration Ganderbal', ARRAY['Jammu and Kashmir']::TEXT[], ARRAY['Tulmulla (Ganderbal)', 'Srinagar']::TEXT[], ARRAY['Kheer Bhawani Temple Complex Tulmulla']::TEXT[], 'Morning aarti and sacred spring pradakshina', 1, 'Emotional homecoming atmosphere with deep devotion, cool shade under giant chinars, and peaceful communal camaraderie.', '25 km north of Srinagar by taxi or state transport buses.', 'Free pilgrim dharamshalas at shrine complex or hotels in Srinagar.', 'High security presence; keep identity cards handy and maintain queue discipline.', 'Leather items strictly prohibited inside shrine premises; cover head respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ganderbal.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hemis-festival', 'Hemis Festival Ladakh', ARRAY['Hemis Tsechu']::TEXT[], 'Spiritual & Temple', 'Buddhism (Drukpa Kagyu)', 'Ladakh''s most famous monastic festival celebrating the birth anniversary of Guru Padmasambhava with hypnotic Cham mask dances in Hemis Monastery.', 'Founded in 1630 by King Sengge Namgyal and Stagsang Raspa Chempo at Hemis Gompa, the largest monastery in Ladakh.', 'Commemorates the triumph of Guru Padmasambhava (Guru Rinpoche) over evil spirits threatening the Himalayas.', 'To bestow spiritual protection, destroy spiritual negativities, and celebrate tantric Buddhist wisdom.', 'Living manifestation of Vajrayana Buddhist philosophy, sacred aesthetics, and monastic community cohesion.', 'Every 12th year (Tibetan Year of the Monkey), a colossal four-storey embroidered thangka of Guru Rinpoche is unfurled.', ARRAY['Monks perform sacred masked Cham dances in courtyard', 'Blowing of 10-foot long copper horns (Dungchen)', 'Unfurling of ancient silk thangkas']::TEXT[], 'Monks in elaborate brocade robes and terrifying masks dance slowly in circular rhythms to clashing cymbals and drum beats.', ARRAY['Tsampa (roasted barley flour)', 'Gur-Gur Cha (Butter Tea)', 'Thukpa', 'Skyu', 'Tingmo']::TEXT[], 'Ladakhi Goncha woolen coats, velvet tupi hats with upturned earflaps, and turquoise-encrusted perak headdresses.', 'Monastic music with Dungchen, gyaling oboes, damaru drums, and deep bass throat chanting.', 'Sacred wooden masks of wrathful deities, silk prayer flags, and Padmasambhava thangka.', '2 Days', 'Tibetan Lunisolar', '10th and 11th days of 5th Tibetan month', 'June - July', 'LUNISOLAR', '10th day of the 5th month of the Tibetan lunar calendar.', '2026-06-25', '2027-07-14', 'Hemis Monastery Administration & UT Ladakh Tourism', ARRAY['Ladakh']::TEXT[], ARRAY['Leh', 'Hemis']::TEXT[], ARRAY['Hemis Monastery Courtyard']::TEXT[], 'Morning session starting at 9 AM for the prime Cham dance sequences', 2, 'An unforgettable visual and acoustic sensory voyage into mystical Himalayan Tibetan Buddhist culture.', '45 km south of Leh city; easily reached by shared taxis, buses, or rented motorbikes.', 'Leh hotels and guesthouses; book 3-4 months in advance as international tourist influx is massive.', 'Arrive at monastery courtyard by 8 AM to secure seating; bring sun protection and warm layers.', 'Maintain respectful silence during ritual dances; do not touch monks'' sacred regalia or walk across dance mandala.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://leh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ladakh-festival', 'Ladakh Festival Leh', ARRAY['UT Ladakh Cultural Carnival']::TEXT[], 'Art & Cultural Festival', 'Secular / Multitribal Heritage', 'A spectacular week-long tourism and cultural festival organized across Leh showcasing polo matches, masked dances, archery, and tribal dances.', 'Initiated in 1993 by the Jammu and Kashmir Tourism Department to showcase Ladakh''s unique blend of Buddhist and Islamic Balti cultures.', 'Marks the celebration of harvest completion before the harsh Himalayan winter sets in.', 'To present the complete spectrum of Ladakh''s arts, sports, traditional dress, and music in one vibrant carnival.', 'Promotes cross-cultural dialogue between diverse ethnic communities of Leh, Nubra, Changthang, and Zanskar.', 'Catalyzed world recognition of Ladakh as a premier global cultural tourism destination.', ARRAY['Grand inaugural street procession down Leh Main Bazaar', 'Traditional polo tournament at Leh Polo Ground', 'Archery competitions with festive folk singing']::TEXT[], 'Hundreds of performers in traditional costumes parade through Leh streets singing celebratory folk anthems.', ARRAY['Khambir bread', 'Chhurpi cheese soup', 'Ladakhi momos', 'Apricot dessert']::TEXT[], 'Elaborate Ladakhi Goncha, Balti embroidered caps, and Brokpa floral headdresses.', 'Surna, Daman percussion ensembles, and energetic Chhab-skyan dance with brass pots.', 'Carved wooden balconies of Leh Old Town, Tibetan prayer wheels, and polo mallets.', '7 Days', 'Organizer Announced', 'Held annually in first week of September.', 'September', 'ORGANIZER_ANNOUNCED', 'Announced by Ladakh Tourism Department (usually Sep 1-7).', '2026-09-01', '2027-09-01', 'Department of Tourism Ladakh', ARRAY['Ladakh']::TEXT[], ARRAY['Leh']::TEXT[], ARRAY['Leh Main Bazaar', 'Leh Polo Ground', 'Sindhu Ghat']::TEXT[], 'Opening day street parade and afternoon polo matches', 3, 'Crisp autumn sunshine, vibrant tribal colors, thundering polo horses, and rhythmic drums echoing across Leh valley.', 'Walking around central Leh; local taxis for outlying monastery events.', 'Extensive options in Leh; September offers pleasant climate without extreme summer rush.', 'Good crowd control; Leh streets become pedestrianized during the parade.', 'Respect performers; ask before taking close-up portraits; keep Leh eco-friendly by avoiding single-use plastics.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.ladakh.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-losar-ladakh', 'Losar Festival Ladakh', ARRAY['Ladakhi New Year']::TEXT[], 'Seasonal & Nature', 'Buddhism / Cultural', 'The grand Ladakhi New Year festival celebrated with illuminated mountain ridges, dough-sculpture offerings, and joyful family reunions.', 'Originates from the 17th century when King Jamyang Namgyal decided to celebrate New Year two months early before marching into battle against Baltistan.', 'Celebrates the winter solstice, driving away past misfortunes, and welcoming prosperous cosmic energies.', 'To express gratitude for winter survival and invoke auspicious deities for crop fertility.', 'Unifies families across snowbound passes through shared feasting, house cleaning, and ancestral offerings.', 'Historic legacy of King Jamyang Namgyal''s military expedition that permanently altered Ladakh''s calendar.', ARRAY['Metho torchlight procession to ward off spirits', 'Lhabsang smoke purification with juniper boughs', 'Ibex dough image crafting']::TEXT[], 'Homes are painted with white auspicious symbols, rooftops illuminated with oil lamps, and elders visit homes exchanging blessings.', ARRAY['Guthuk noodle soup', 'Khabsay deep fried pastry', 'Chang (barley brew)', 'Roasted meat stew']::TEXT[], 'Freshly tailored sheepskin-lined Gonchas, silk waistbands, and fox-fur caps.', 'Jabro slow circular dances, dramatic comic skits, and Daman drumming.', 'White flour flour-swastika and sun-moon symbols on kitchen walls, flaming juniper torches.', '15 Days', 'Tibetan Lunisolar', 'Begins on the first day of the 11th Tibetan lunar month.', 'December', 'LUNISOLAR', 'Commences on the 1st day of the 11th month of the Tibetan calendar.', '2026-12-10', '2027-12-28', 'Ladakh Buddhist Association Calendar', ARRAY['Ladakh']::TEXT[], ARRAY['Leh', 'Nubra Valley', 'Zanskar', 'Kargil']::TEXT[], ARRAY['Leh Palace', 'Chowkhang Gompa', 'Village community halls']::TEXT[], 'First three days including Metho fire procession night', 4, 'Winter wonderland with snow-covered peaks, starry midnight torchlight parades, and intense warmth inside cozy Ladakhi kitchens.', 'Pre-arranged winterized 4x4 vehicles with snow chains.', 'Winter-ready hotels in Leh with central heating or electric blankets; homestays with bukhari stoves.', 'Sub-zero temperatures down to -20°C; pack expedition-grade down jackets, thermal innerwear, and insulated boots.', 'Never refuse a cup of hot butter tea or khabsay offered by hosts; greet everyone with ''Julley Losar!''.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.ladakh.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dosmochey-ladakh', 'Dosmochey Festival Leh & Likir', ARRAY['Festival of the Scapegoat']::TEXT[], 'Spiritual & Temple', 'Buddhism (Gelug & Drukpa)', 'The sacred purification festival of the scapegoat where monks erect intricate thread-cross effigies to trap negative energies and burn them.', 'Started by the royal rulers of Ladakh to purge evil forces and protect the kingdom from epidemics and war.', 'Celebrates the cosmic destruction of destructive karmic obstacles before spring arrival.', 'To eradicate bad luck, disease, and misfortune from the land and bless the coming year.', 'Profound tantric Buddhist ritual of transmutation of suffering through sacred mandalas.', 'Marks the traditional gathering of desert pastoralists and Leh townspeople during late winter.', ARRAY['Erection of colossal wooden mast adorned with thread-cross webs (Storma)', 'Cham sacred mask dances below Leh Palace', 'Ritual burning and tearing down of the evil-trapping mast']::TEXT[], 'Monks in ferocious masks dance in courtyard; on the final day, the effigy is marched to the city boundary and burned amidst cheers.', ARRAY['Thukpa', 'Khambir with butter', 'Steamed Tingmo', 'Gur-Gur Cha']::TEXT[], 'Heavy woolen Gonchas with vibrant orange and maroon sashes.', 'Monastic low-pitch chanting, gong strikes, and brass cymbal percussion.', 'Elaborate thread-cross webs (Dho), wooden totem mast, and butter-sculpted torma figures.', '2 Days', 'Tibetan Lunisolar', '28th and 29th days of the 12th Tibetan month', 'February', 'LUNISOLAR', 'Observed at the close of the 12th month of the Tibetan calendar.', '2026-02-14', '2027-02-04', 'Leh Monasteries Council', ARRAY['Ladakh']::TEXT[], ARRAY['Leh', 'Likir', 'Diskit (Nubra)']::TEXT[], ARRAY['Courtyard below Leh Palace', 'Likir Monastery']::TEXT[], 'Second day afternoon during the dramatic tearing down of the thread mast', 2, 'Thrilling winter spectacle of sacred dance against the imposing backdrop of the 9-storey Leh Palace.', 'Walkable within Leh town; taxis to Likir Monastery.', 'Leh guesthouses with winter heating facilities.', 'Freezing February temperatures; stand on sunlit sides of the courtyard.', 'Do not touch or cross beneath the thread-cross effigy; keep cameras steady without obstructing ritual procession.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://leh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sindhu-darshan', 'Sindhu Darshan Festival Shey', ARRAY['Indus River Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Patriotic & Spiritual', 'A national cultural festival celebrated on the banks of the sacred Indus (Sindhu) River at Shey, honoring India''s civilizational cradle.', 'Inaugurated in October 1997 to honor the river from which the words ''India'' and ''Hindu'' are etymologically derived.', 'Celebrates the ancient Indus Valley civilizational roots and unity in diversity.', 'To promote national integration, communal harmony, and reverence for Indian river waters.', 'Symbolizes civilizational pride, peaceful coexistence, and environmental stewardship.', 'Brought national cultural troupes from every Indian state to perform on Ladakh''s high-altitude plateau.', ARRAY['Offering water from rivers across all Indian states into the Indus River', 'Senior Buddhist and multi-faith prayer invocations', 'Grand national folk dance performances on riverside stage']::TEXT[], 'Devotees and cultural contingents bring river waters from the Ganga, Yamuna, Godavari, and Kaveri to blend into the Indus.', ARRAY['Multistate regional prasad', 'Ladakhi Apricot Juice', 'Traditional Ladakhi lunch']::TEXT[], 'Diverse regional dresses from 28 states alongside Ladakhi Goncha.', 'Folk dances from Punjab, Gujarat, Bengal, and Tamil Nadu performed alongside Ladakhi artists.', 'Pots of sacred river waters, Indus river Ghat pavilions, and fluttering Indian tricolour flags.', '3 Days', 'Guru Purnima Lunisolar', 'Full moon day of Ashadha month', 'June', 'LUNISOLAR', 'Celebrated on Ashadha Purnima (Guru Purnima).', '2026-06-29', '2027-07-18', 'Sindhu Darshan Yatra Samiti & UT Ladakh Tourism', ARRAY['Ladakh']::TEXT[], ARRAY['Shey', 'Leh']::TEXT[], ARRAY['Sindhu Ghat Shey']::TEXT[], 'Morning multi-river mingling ceremony and evening cultural gala', 2, 'Powerful sense of patriotic unity and civilizational depth amidst the gentle turquoise currents of the Indus river.', '12 km drive from Leh city along the Manali-Leh highway.', 'Hotels and resorts across Leh, Choglamsar, and Shey.', 'High daytime UV radiation; wear hats, sunglasses, and high-SPF sunscreen.', 'Treat the riverbank with reverence; do not leave flower wrappings or plastics in the stream.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.ladakh.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-taktok-festival', 'Tak Tok Festival', ARRAY['Tak Tok Tsechu']::TEXT[], 'Spiritual & Temple', 'Buddhism (Nyingma)', 'The only Nyingma monastic festival in Ladakh, celebrated inside and around a cave sanctuary where Guru Padmasambhava meditated.', 'Tak Tok (literally ''rock roof'') Gompa is built around an 8th-century natural cave used by Guru Rinpoche.', 'Commemorates the meditation retreats of Padmasambhava and tantric subduing of negative energies.', 'To invoke blessings of the primordial Buddha and celebrate ancient Nyingmapa esoteric practices.', 'Unique representation of the Nyingma ''Ancient'' school traditions in predominantly Gelug/Drukpa Ladakh.', 'Preserves 8th-century tantric ritual methods in their most pristine, unaltered cave shrine setting.', ARRAY['Cham dance performances outside rock cave entrance', 'Blessing with holy water and Padmasambhava cave darshan', 'Consecration of sacred medicinal pills']::TEXT[], 'Pilgrims climb the steep stone steps to enter the soot-blackened holy cave to touch the rock impressions left by Guru Rinpoche.', ARRAY['Tibetan butter tea', 'Steamed momos', 'Dry roasted barley', 'Chhurpi']::TEXT[], 'Brocade chupas, crimson monk robes, and distinctive red Nyingma lotus hats.', 'Cymbal rhythms, long horns, and dynamic, leaping sacred dance moves.', 'Sacred meditation cave, rocky overhang, and brightly painted tantric deity statues.', '2 Days', 'Tibetan Lunisolar', '9th and 10th days of the 6th Tibetan month', 'July - August', 'LUNISOLAR', 'Celebrated on the 10th day of the 6th Tibetan month.', '2026-07-24', '2027-08-12', 'Tak Tok Monastery Trust', ARRAY['Ladakh']::TEXT[], ARRAY['Sakti Village', 'Leh']::TEXT[], ARRAY['Tak Tok Gompa Sakti']::TEXT[], 'Morning session starting around 9:30 AM', 1, 'Authentic, intimate village monastic vibe far removed from commercial tourist crowds, set against dramatic granite cliffs.', '46 km east of Leh en route to Chang La pass; accessible by taxi.', 'Homestays in Sakti village or return to Leh city for hotel stay.', 'High altitude (3,800 m); take it slow on steep monastery stone stairs.', 'Crawl respectfully into the low-ceiling meditation cave without shoes; photography inside the cave is restricted.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://leh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-korzok-gustor', 'Korzok Gustor Festival Tso Moriri', ARRAY['Tsomoriri Monastic Festival']::TEXT[], 'Spiritual & Temple', 'Buddhism (Drukpa)', 'An exhilarating high-altitude monastic festival held on the shores of sapphire-blue Lake Tso Moriri by the Changpa nomads.', 'Korzok Monastery was founded 300 years ago under the patronage of the Rupshu chieftains.', 'Commemorates the triumph of virtue over evil and assassination of anti-Buddhist Tibetan king Langdarma.', 'To bring spiritual protection to the nomadic Changpa pastoralists and their Pashmina goat herds.', 'Vital cultural lifeline connecting scattered nomadic tribes across the remote Changthang plateau.', 'Maintains the ancient covenant between the monastery and the high-altitude nomadic pastoralists.', ARRAY['Cutting of the sacrificial cake (Storma) ending evil', 'Cham dances by lamas in heavy silk robes', 'Changpa nomad social gathering and horse displays']::TEXT[], 'Nomadic families travel across vast distances on horseback and motorbikes, setting up yak-wool rebo tents near the lake.', ARRAY['Yak butter tea', 'Dried yak meat stew', 'Tsampa balls', 'Fresh curd']::TEXT[], 'Heavy sheepskin Gonchas, silver amulet boxes (Gau), and coral-and-turquoise jewelry necklaces.', 'Fierce, athletic Cham dances accompanied by deep monastic brass horn blasts.', 'Tso Moriri''s shimmering blue waters, white chortens, and wind-whipped prayer flags.', '2 Days', 'Tibetan Lunisolar', 'First week of the 6th Tibetan month', 'July - August', 'LUNISOLAR', 'Occurs in early July based on Tibetan calendar.', '2026-07-13', '2027-07-31', 'Korzok Monastery Committee', ARRAY['Ladakh']::TEXT[], ARRAY['Korzok', 'Tso Moriri', 'Changthang']::TEXT[], ARRAY['Korzok Monastery Courtyard']::TEXT[], 'Both days during morning Cham dances', 2, 'Astonishing contrasts between monastic crimson robes, sapphire lake reflections, and snow-capped peaks at 4,595 meters.', '210 km from Leh via Chumathang; requires dedicated 4x4 SUV (6-7 hours).', 'Village homestays in Korzok or luxury seasonal tented camps along lake banks.', 'Extreme altitude (15,075 ft); mandatory 2-3 day acclimatization in Leh before traveling here.', 'Protected wildlife wetland; strictly no camping near bird-nesting shorelines; obtain Inner Line Permit.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://leh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-spituk-gustor', 'Spituk Gustor Festival', ARRAY['Spituk Monastic Fair']::TEXT[], 'Spiritual & Temple', 'Buddhism (Gelugpa)', 'The dramatic winter festival of Spituk Monastery where the giant statue of Goddess Kali / Palden Lhamo is unveiled once a year.', 'Spituk Gompa was founded in the 11th century by Od-de, elder brother of Lha Lama Changchub Od.', 'Commemorates the historic victory of righteousness over malevolence through divine wrathful manifestations.', 'To invoke the wrathful female protector Palden Lhamo for prosperity and peace throughout Ladakh.', 'Represents the supreme guardian rites of the Gelugpa Yellow Hat order in Ladakh.', 'Marks the first major monastic congregation of the cold winter months for residents of Leh valley.', ARRAY['Unveiling of the fierce Mahakala and Palden Lhamo statues', 'Sacred masked dances depicting the conquest of evil', 'Argham ritual offering of dough effigies']::TEXT[], 'Locals brave sub-zero temperatures to climb the hilltop monastery rock and receive blessings from unveiled deities.', ARRAY['Thukpa', 'Tingmo', 'Boiled lamb soup', 'Butter tea']::TEXT[], 'Thick winter Gonchas, wool scarves, and fur-lined boots.', 'Spiritual trumpets, bells, clashing cymbals, and sacred slow-motion circular monastic steps.', 'Hilltop rock fortress monastery, wind-whipped snow peaks, and wrathful deity thangkas.', '2 Days', 'Tibetan Lunisolar', '28th and 29th days of the 11th Tibetan lunar month', 'January', 'LUNISOLAR', 'Celebrated in the 11th Tibetan month (usually mid to late January).', '2026-01-16', '2027-01-06', 'Spituk Monastery Administration', ARRAY['Ladakh']::TEXT[], ARRAY['Spituk', 'Leh']::TEXT[], ARRAY['Spituk Monastery Courtyard']::TEXT[], 'Mid-day during the Cham dances when the winter sun is warmest', 2, 'Intense, authentic spiritual atmosphere with almost exclusively local Ladakhi attendees in winter attire.', '8 km from Leh center; easily reached by taxi or local shared bus.', 'Winter hotels in Leh city with reliable heating.', 'Severe cold (-10°C to -18°C); dress in multi-layered thermal clothing and windproof shell.', 'Maintain queue discipline when climbing narrow wooden steps to the Palden Lhamo sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://leh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kullu-dussehra', 'Kullu Dussehra', ARRAY['International Kullu Dussehra']::TEXT[], 'Historical & Royal', 'Hinduism (Folk Pahadi Shaktism & Vaishnavism)', 'A magnificent week-long congregation where over 300 village deities arrive in wooden palanquins to pay homage to Lord Raghunath on Dhalpur Maidan.', 'Instituted in 1660 CE by Raja Jagat Singh of Kullu after consecrating an idol of Lord Raghunath brought from Ayodhya.', 'Celebrates the victory of good over evil, uniquely beginning on the day Vijyadashami concludes elsewhere in India.', 'To reaffirm the divine sovereignty of Lord Raghunath as the celestial king of the Kullu Valley.', 'Living testament to the ancient Gram Devta (village deity) social and religious democracy of Himachal.', 'Declared an International Festival attracting cultural troupes and ambassadors from over 20 countries.', ARRAY['Rath Yatra of Lord Raghunath drawn by thousands of devotees', 'Assembly of 300+ palanquins (Raths) of village deities', 'Lanka Dahan burning of grass effigies on Beas riverbank']::TEXT[], 'Dhalpur Maidan transforms into an ocean of trumpeting Karnal horns, dancing palanquins, and bustling handicraft stalls.', ARRAY['Siddu with ghee and dal filling', 'Kullu Trout fish', 'Dhaam feast', 'Babru']::TEXT[], 'Himachali round Kullu Patti caps, Pattus (handwoven woolen shawls), and Cholas.', 'Hypnotic Pahadi Nati community circular dances and blasting bronze Karnal horns and Dhol-Nagada.', 'Wooden wooden rath with chhatris, colorful deity palanquins, and Dhalpur Maidan pavilions.', '7 Days', 'Hindu Lunisolar', 'Begins on Vijyadashami (Dashami of Ashwin Shukla Paksha)', 'October', 'LUNISOLAR', 'Begins on Dashami of Ashwin Shukla Paksha.', '2026-10-20', '2027-10-10', 'District Administration Kullu & Himachal Tourism', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Kullu', 'Manali']::TEXT[], ARRAY['Dhalpur Maidan Kullu']::TEXT[], 'Opening day for the majestic Rath Yatra and concluding Lanka Dahan day', 3, 'Thunderous resonance of hundreds of bronze horns, vibrating deity palanquins swaying in trance, and crisp autumn mountain breeze.', 'Buses from Chandigarh/Delhi to Kullu; Bhuntar Airport is just 10 km away.', 'Hotels and homestays in Kullu, Naggar, or Manali (40 km away).', 'Over 100,000 visitors; stay alert in moving crowds around the heavy wooden chariot.', 'Never touch the sacred deity palanquins without invitation; dress respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kulludussehra.hp.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mandi-shivratri', 'International Mandi Shivratri Fair', ARRAY['Mandi Mahashivratri Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism & Folk Deities)', 'A 500-year-old historic celebration where over 200 village deities (Devtas) assemble in the ''Varanasi of the Hills'' to pay respects to Lord Madho Rai.', 'Started in 1527 CE by Raja Ajber Sen who founded Mandi town and consecrated the Bhootnath temple.', 'Commemorates the eternal dance of Lord Shiva and celestial fellowship of mountain deities.', 'To honor Lord Shiva and Lord Madho Rai (Krishna) as celestial protectors of Mandi state.', 'Epic cultural synthesis of orthodox Shaivism, Vaishnavism, and indigenous Himalayan Shamanism.', 'Preserves the medieval royal Durbar etiquette where deities are formally welcomed by state administrators.', ARRAY['Shobha Yatra royal procession with deities marching to Paddal Ground', 'Offering of homage to Lord Madho Rai temple', 'Nightly cultural performances with classical and folk artists']::TEXT[], 'The Paddal Ground buzzes with deity palanquins, traditional shamans (Gurs) in trance, and sprawling rural trade fairs.', ARRAY['Mandi Sepu Vadi', 'Kachalooji curry', 'Himachali Dhaam', 'Jhol']::TEXT[], 'Traditional Pahadi suits, embroidered Mandi shawls, and woolen caps with monal feathers.', 'Lively Mandiyali Nati dances, Shehnai, Narsingha horn blasts, and Dhol-Damau.', 'Ornate brass and silver deity masks (Mohras), velvet palanquins, and Paddal maidan pavilions.', '7 Days', 'Hindu Lunisolar', 'Begins on Krishna Chaturdashi of Phalguna month', 'February - March', 'LUNISOLAR', 'Commences the day after Maha Shivratri in Phalguna.', '2026-02-16', '2027-03-07', 'Mandi Shivratri Fair Committee & HP Tourism', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Mandi']::TEXT[], ARRAY['Paddal Ground Mandi', 'Bhootnath Temple', 'Madho Rai Temple']::TEXT[], 'First day Shobha Yatra and concluding procession (Jaleb)', 3, 'Mesmerizing spectacle of medieval royalty and hill shamanism unfolding in a picturesque valley along the Beas River.', 'Well connected by highway from Chandigarh (180 km) and Kangra (150 km).', 'Hotels and government rest houses in Mandi city.', 'Dense crowds around Paddal Ground during royal processions; follow barricade paths.', 'Respect the Gurs (oracles) during trance states; maintain courteous distance.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mandi.hp.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-minjar-mela-chamba', 'Minjar Mela Chamba', ARRAY['Chamba Minjar Fair']::TEXT[], 'Harvest & Agriculture', 'Hinduism / Historic Royal', 'A historic monsoon harvest festival celebrating the emergence of maize shoots (Minjar) and victory of Chamba kings with silk tassel immersions in Ravi River.', 'Celebrated since 935 CE when Raja Sahil Varman defeated the king of Trigarta (Kangra) and returned victorious to Chamba.', 'Celebrates the blessing of maize and paddy crops and historical military triumphs.', 'To pray for agricultural prosperity and invoke Lord Varuna (God of Rain and Oceans).', 'Symbolizes communal brotherhood across religious lines, where Muslim families craft the royal silk Minjar tassels.', 'Living unbroken continuity of the 1,000-year-old Varman dynasty cultural institutions.', ARRAY['Distribution and pinning of silk and silver Minjar tassels on clothes', 'Grand Shobha Yatra from Akhand Chandi Palace to Ravi river', 'Ceremonial floating of coconut, betel nut, and Minjar tassels in Ravi River']::TEXT[], 'People wear Minjar tassels on their lapels, throng the historic Chaugan lawns, and participate in sports and musical galas.', ARRAY['Madra (kidney beans in curd gravy)', 'Chamba Chukh chutney', 'Mittha sweet rice', 'Bhaturu']::TEXT[], 'Chamba Pattus, embroidered Chamba Rumal kerchiefs, and traditional woolen caps.', 'Melodious Chamba folk songs (Ainchaliyan), classical raga renditions, and Kunjari-Malhar duets.', 'Golden silk Minjar tassels, Chaugan green, and Akhand Chandi palace flags.', '7 Days', 'Solar / Agricultural', 'Begins on the second Sunday of the Hindu month of Shravana.', 'July - August', 'SOLAR', 'Second Sunday of Shravan month.', '2026-07-26', '2027-08-08', 'Chamba District Administration & HP Tourism', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Chamba']::TEXT[], ARRAY['Historic Chaugan Ground Chamba', 'Ravi Riverbanks']::TEXT[], 'Opening Sunday and concluding immersion procession day', 3, 'Historic mountain town charm with emerald Chaugan grounds bordered by British and Rajput-era wooden palaces.', '120 km from Pathankot railway station; connected by mountain road.', 'Hotels, heritage homestays, and HPTDC properties in Chamba town.', 'Monsoon showers frequent; carry reliable umbrellas and water-resistant footwear.', 'Buy authentic hand-embroidered GI-tagged Chamba Rumal souvenirs from certified artisan cooperatives.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hpchamba.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-fagli-festival-lahaul', 'Fagli Festival Lahaul', ARRAY['Kus Festival Pattan Valley']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Himalayan Shamanism', 'A fascinating late-winter tribal festival celebrated in snowbound Pattan Valley of Lahaul with straw-masked dancers expelling winter spirits.', 'Centuries-old tribal animist festival documented in Himalayan anthropological surveys.', 'Marks the end of peak winter, victory of divine spirits over demons, and welcoming of spring.', 'To appease village protective deities and cast out evil spirits (Barni) from household hearths.', 'Deep ecological bond between mountain inhabitants, snow spirits, and agricultural renewal.', 'Preserves pre-Buddhist tribal shamanic practices in high Himalayan valleys.', ARRAY['Dressing in dried grass and straw coats (Barani) with wooden masks', 'Offering of snow pyramids (Totu) to deities', 'Visiting every village household with cedar bough blessings']::TEXT[], 'Villagers build high snow pyramids outside homes, illuminate oil lamps, and dance in heavy straw costumes.', ARRAY['Totu (snow-molded roasted barley flour)', 'Chhang barley liquor', 'Buckwheat pancakes', 'Butter broth']::TEXT[], 'Costumes made entirely of mountain grasses, straw boots, and carved deodar wooden masks.', 'Tribal horn blasts, drum beats, and circular village chanting dances.', 'Straw effigies, snow pyramids decorated with butter, and burning juniper incense.', '4 Days', 'Hindu-Tibetan Lunisolar', 'Celebrated on Amavasya (New Moon) of Phalguna month.', 'February', 'LUNISOLAR', 'Occurs on Phalguna Amavasya.', '2026-02-17', '2027-03-08', 'Lahaul Tribal Council', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Pattan Valley', 'Udaipur (Lahaul)', 'Keylong']::TEXT[], ARRAY['Village squares across Pattan Valley']::TEXT[], 'Day of the straw-masked procession', 2, 'Surreal winter wonderland experience amidst 4-foot snowdrifts, experiencing ancient Himalayan tribal warmth.', 'Accessible via Atal Tunnel Rohtang from Manali; requires 4x4 winter vehicles.', 'Local village homestays with heated bukhari stoves.', 'Extreme freezing weather; heavy thermal gear and crampons essential.', 'Show deep reverence for village elders and local deities; photography requires polite consent.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hplahaulspiti.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-halda-festival', 'Halda Festival Keylong', ARRAY['Lahauli Festival of Lights']::TEXT[], 'Seasonal & Nature', 'Lamaistic Buddhism & Indigenous Traditions', 'The mesmerizing winter festival of lights in Lahaul Valley where every family lights cedar torches and marches to a sacred crossroad.', 'Ancient Bon-influenced winter solstice rite celebrating the cleansing power of fire.', 'Marks the triumph of light over dark winter days and appeasement of the Goddess of Wealth Shiskar Apa.', 'To burn away family misfortunes of the past year and welcome prosperity.', 'Strengthens tribal solidarity across isolated snowed-in Himalayan valleys.', 'Living testament to the syncretic blend of Bon tribal animism and Tibetan Buddhism.', ARRAY['Crafting resin-rich cedar torches (Halda)', 'Lighting and carrying blazing torches through village lanes', 'Throwing blazing torches together into a giant bonfire while chanting curses at evil spirits']::TEXT[], 'Every household assembles at dark with burning cedar torches, shouting slogans and tossing them into a roaring community bonfire.', ARRAY['Mutton stew', 'Arak (distilled spirit)', 'Sidu', 'Chhang']::TEXT[], 'Heavy woolen Gonchas with embroidered waistbands and sheepskin boots.', 'Shamanic drum rhythms, conch blasts, and community folk cheers.', 'Blazing cedar torches, glowing bonfires against snowy cliffs, and juniper smoke.', '2 Days', 'Tibetan Lunisolar', 'Determined by lamas of Keylong and Kardang monasteries.', 'January', 'LUNISOLAR', 'Usually celebrated during mid-January.', '2026-01-22', '2027-01-18', 'Lahaul Cultural Preservation Forum', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Keylong', 'Ghar Valley', 'Guskar']::TEXT[], ARRAY['Village grounds near Keylong']::TEXT[], 'Night of the grand Halda torchlight bonfire', 2, 'Spectacular visual contrast of fiery cedar torches against pitch-black star-studded Himalayan skies and pristine snow.', 'Accessible from Manali through Atal Tunnel (Keylong is 75 km away).', 'Cozy winter homestays in Keylong and Sissu.', 'Sub-zero temperatures (-15°C); keep safe distance from flying torch sparks.', 'Follow village rules; do not disrupt the sacred bonfire assembly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hplahaulspiti.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-renuka-ji-fair', 'Renuka Ji Fair Sirmaur', ARRAY['International Shri Renuka Ji Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism)', 'An emotional annual congregation celebrating the sacred reunion of Lord Parashurama with his divine mother Goddess Renuka on the banks of holy Renuka Lake.', 'Dates back centuries, centered around the lake shaped naturally like the reclining figure of Goddess Renuka.', 'Celebrates the immortal bond between Lord Parashurama and his mother.', 'To take holy dips in Renuka Lake and receive blessings of maternal devotion and valor.', 'Exemplifies the deep integration of epic Puranic lore into rural Himachali community life.', 'Upgraded to an International Fair showcasing mountain cattle trading and handicraft exchanges.', ARRAY['Arrival of Lord Parashurama''s palanquin from Jamu Koti village', 'Ceremonial holy dip in the sacred waters of Renuka Lake', 'Deepdaan floating of thousands of leaf-boats with earthen lamps on lake surface']::TEXT[], 'Lakhs of pilgrims camp under starry skies on lake meadows, singing hymns and offering prayers at ancient temples.', ARRAY['Kheer', 'Malpua', 'Sirmauri Kadhi', 'Patande (Himachali crepes)']::TEXT[], 'Traditional Sirmauri colorful woolen waistcoats, silver ornaments, and headscarves.', 'Sirmauri Nati dances with Dhol, Shehnai, and harmonium.', 'Reclining lake contour, illuminated floating leaf lamps, and deity palanquins.', '6 Days', 'Hindu Lunisolar', 'Begins on Prabodhini Ekadashi of Kartika month', 'November', 'LUNISOLAR', 'Starts on Kartika Shukla Ekadashi.', '2026-11-20', '2027-11-10', 'Sirmaur District Administration & HP Tourism', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Renuka Ji', 'Nahan', 'Sirmaur']::TEXT[], ARRAY['Renuka Lake Banks', 'Parashurama Temple']::TEXT[], 'Evening Deepdaan ceremony on the lake waters', 2, 'Peaceful lake reflections surrounded by forested hills, echoing temple bells, and thousands of floating lights.', '40 km from Nahan; 120 km from Chandigarh; accessible by road.', 'HPTDC Hotel The Renuka on lake shores, forest rest houses, and tented accommodations.', 'Large rural gatherings; keep to designated safe bathing ghats.', 'Boating is restricted during ritual bathing hours; do not litter sacred lake waters.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hpsirmaur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-losar-lahaul-spiti', 'Losar Festival Lahaul & Spiti', ARRAY['Spitian New Year']::TEXT[], 'Seasonal & Nature', 'Tibetan Buddhism', 'The colorful winter New Year festival celebrated across the high-altitude moonscapes of Spiti Valley and Key Monastery.', 'Preserved by Spiti''s Gelugpa and Sakya monastic communities for over 1,000 years.', 'Marks the arrival of the new lunar year and revitalization of community life.', 'To celebrate friendship, longevity, good harvest, and monastic prayers.', 'Deep emotional renewal for high-altitude desert inhabitants during isolating sub-zero winters.', 'Safeguards century-old Buddhist folk literature, theatrical satires, and social customs.', ARRAY['Lhabsang smoke ceremonies on mud-plastered flat rooftops', 'Monastic Cham dances at Key and Tabo Gompas', 'Folk singing competitions between village clans']::TEXT[], 'Villagers in sheepskin robes visit every home, offering white silk Khata scarves and blessing bowls of barley.', ARRAY['Spitian Momos', 'Thukpa with dried yak cheese', 'Chhang', 'Sweet Tsampa dumplings']::TEXT[], 'Warm heavy woolen Gonchas, turquoise rings, and Spiti felt hats.', 'Graceful Spitian circle dances and comedic masked performances.', 'Sun-and-moon auspicious flour markings on fortress-like mud homes, fluttering prayer flags.', '15 Days', 'Tibetan Lunisolar', 'First day of the first Tibetan lunar month (or early in Spiti calendar)', 'February - March', 'LUNISOLAR', 'First day of the first Tibetan month.', '2026-02-18', '2027-02-08', 'Spiti Monasteries Association', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Kaza', 'Key', 'Tabo', 'Kibber']::TEXT[], ARRAY['Key Monastery', 'Tabo Monastery', 'Kaza Main Ground']::TEXT[], 'First three days for grand monastic gatherings', 3, 'Raw, otherworldly snow desert landscapes with 1,000-year-old mud monasteries glowing against blinding white snow.', 'Winter access via Shimla-Kinnaur-Kaza highway with 4x4 SUVs.', 'Winter homestays in Kaza with wood-fired stoves and dry toilets.', 'Extreme freezing cold (-20°C to -30°C); thermal base layers, heavy parkas, and altitude medication needed.', 'Present silk Khata scarves with both hands palms up; drink hot tea politely when hosted.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hplahaulspiti.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-suhi-mela-chamba', 'Suhi Mela Chamba', ARRAY['Rani Sunayana Martyrdom Fair']::TEXT[], 'Historical & Royal', 'Folk Legend / Women''s Honor', 'A poignant historic women-only fair commemorating the supreme self-sacrifice of Queen Sunayana who gave her life to bring drinking water to Chamba.', 'Dating back to the 10th century during the reign of King Sahil Varman of Chamba.', 'According to legend, the city''s water channel would not flow until Queen Sunayana buried herself alive in sacrifice.', 'To pay tribute to the immortal maternal sacrifice of Queen Sunayana (Rani Suhi).', 'Unique historical festival exclusively led and attended by women and children of Chamba.', 'Exemplifies heroic sacrifice for community welfare celebrated for over a millennium.', ARRAY['Solemn procession of women carrying the idol of Rani Suhi to her hilltop shrine', 'Singing of mournful yet celebratory Sukrat ballads', 'Community feast and distribution of prasad']::TEXT[], 'Dressed in their finest bridal attire, women and girls climb the stone steps singing ballads of the brave queen.', ARRAY['Kheer', 'Puri', 'Chana masala', 'Sweet Halwa']::TEXT[], 'Brilliant red, pink, and orange traditional Chamba suits with gold jewelry.', 'Folk singing of the heart-touching ''Sukrat'' ballad with Dholak accompaniment.', 'Rani Suhi''s whitewashed hilltop shrine, fresh flower garlands, and silver parasols.', '3 Days', 'Hindu Lunisolar', 'Chaitra Shukla Paksha (April)', 'April', 'LUNISOLAR', 'Celebrated from 1st to 3rd of Baisakh month.', '2026-04-13', '2027-04-13', 'Chamba Municipal Council', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Chamba']::TEXT[], ARRAY['Suhi Mata Temple Chamba']::TEXT[], 'Morning procession of women climbing to the hilltop temple', 1, 'Emotionally rich cultural experience highlighting women''s pride, historical memory, and valley folklore.', 'Climb via stone stairway from Chamba main bazaar.', 'Hotels and guesthouses in Chamba.', 'Only women and young children are permitted into the innermost shrine courtyard during peak rituals.', 'Maintain respectful decorum; avoid disrupting women singing traditional mourning ballads.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hpchamba.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-himalayan-festival-mcleodganj', 'International Himalayan Festival McLeod Ganj', ARRAY['Dharamshala Peace Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Peace & Heritage', 'A vibrant festival of cross-cultural friendship commemorating the Nobel Peace Prize conferment upon His Holiness the Dalai Lama in 1989.', 'Established in 1995 by the Central Tibetan Administration and Himachal Pradesh Tourism.', 'Celebrates universal peace, human rights, and the harmony between local Gaddi tribes and the Tibetan community.', 'To foster inter-community camaraderie and promote Tibetan cultural preservation.', 'Symbol of global peace, non-violence, and peaceful coexistence in the lap of the Dhauladhars.', 'Brings together Tibetan performing artists and indigenous Pahadi cultural troupes.', ARRAY['Inaugural prayer session led by Buddhist monks and Hindu priests', 'Traditional Tibetan opera (Lhamo) excerpts', 'Himachali Gaddi folk dances and acoustic fusion concerts']::TEXT[], 'Tsuglagkhang Temple complex and Mall Road come alive with multicultural food stalls, musical jams, and art exhibitions.', ARRAY['Tibetan Momos', 'Laphing', 'Kangra Dhaam', 'Butter Tea', 'Bakeproducts']::TEXT[], 'Tibetan Chupa dresses alongside Gaddi woolen Cholas with black ropes (Dora).', 'Tibetan classical Cham and folk dances alongside energetic Pahadi Nati.', 'Tibetan prayer wheels, Dhauladhar snow walls, and multi-faith unity flags.', '3 Days', 'Gregorian / Anniversary', 'Held around December 10 to mark Nobel Peace Prize day.', 'December', 'FIXED', 'Commences December 10 annually.', '2026-12-10', '2027-12-10', 'HP Tourism & Central Tibetan Administration', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['McLeod Ganj', 'Dharamshala']::TEXT[], ARRAY['Tsuglagkhang Main Temple Complex', 'Dharamshala Club Grounds']::TEXT[], 'Morning opening ceremony and afternoon cultural concerts', 2, 'Serene mountain vibes blending maroon-robed Buddhist lamas, Tibetan craft bazaars, and scenic cedar forests.', 'Taxis and auto-rickshaws from Kangra Airport (Gaggal - 18 km) or Pathankot railway station.', 'Boutique hotels, Tibetan guesthouses, and homestays in McLeod Ganj and Dharamkot.', 'Pleasant daytime, cold winter evenings; warm woolen layers recommended.', 'Spin prayer wheels in clockwise direction; remove footwear before entering Buddhist temple sanctums.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kangra.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-doongri-fair-manali', 'Doongri Fair Manali', ARRAY['Hadimba Temple Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Shaktism)', 'The lively birthday fair of Goddess Hadimba Devi celebrated amidst towering ancient deodar groves at her wooden pagoda temple in Manali.', 'Hadimba Devi temple was built in 1553 CE by Raja Bahadur Singh in the classical deodar-wood pagoda architectural style.', 'Celebrates the birthday of Goddess Hadimba, patron deity of the Kullu royal house and wife of Bhima from Mahabharata.', 'To seek blessings of Goddess Hadimba for family prosperity and protection from calamities.', 'Deeply rooted in tribal mountain animism, nature reverence, and Mahabharata folk traditions.', 'Marks the grand summer opening festival for village communities across the upper Beas valley.', ARRAY['Arrival of local deity palanquins from nearby villages with brass trumpets', 'Priestly pujas inside the natural rock cave sanctum', 'Energetic community Nati round dances under deodar trees']::TEXT[], 'Villagers in colorful traditional attire gather on temple lawns, enjoying joyrides, sweet shops, and musical competitions.', ARRAY['Siddu with walnut stuffing', 'Kullu trout', 'Mittha', 'Jalebi']::TEXT[], 'Traditional Kullu woolen caps, brightly colored shawls (Pattu), and silver jewellery.', 'Rhythmic Kulluvi Nati danced by concentric circles of men and women, Shehnai and Dhol.', 'Carved deodar wood pagoda temple roofs, brass horn bells, and ancient cedar trees.', '3 Days', 'Solar / Lunar', 'Celebrated from 1st to 3rd of Jyeshtha month (May).', 'May', 'LUNISOLAR', 'Celebrated during mid-May in Jyeshtha month.', '2026-05-14', '2027-05-14', 'Hadimba Temple Trust & Manali Municipal Council', ARRAY['Himachal Pradesh']::TEXT[], ARRAY['Manali']::TEXT[], ARRAY['Hadimba Devi Temple Complex Doongri Forest']::TEXT[], 'Afternoon sessions when folk dancing reaches peak energy under forest canopy', 2, 'Fairytale alpine atmosphere with fragrant pine needles underfoot, medieval wooden architecture, and cheerful mountain dancers.', '1.5 km walking distance from Manali Mall Road; accessible by auto-rickshaw.', 'Huge variety of hotels, riverside resorts, and backpacker hostels across Manali.', 'Heavy footfall; watch out for slippery tree roots along forest paths.', 'Do not carry leather items into the temple sanctum; photography inside the dark rock cave is prohibited.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kullu.hp.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-baisakhi-punjab', 'Vaisakhi / Baisakhi Amritsar', ARRAY['Khalsa Sajna Diwas']::TEXT[], 'Harvest & Agriculture', 'Sikhism & Hinduism', 'The premier festival of Punjab celebrating the golden wheat harvest and the historic founding of the Khalsa Panth by Guru Gobind Singh Ji in 1699.', 'On Vaisakhi in 1699 at Anandpur Sahib, Guru Gobind Singh Ji created the Khalsa and initiated the Panj Pyare (Five Beloved Ones).', 'Celebrates nature''s harvest abundance and the spiritual birth of the Sikh nation.', 'To express gratitude for abundant rabi crops and re-dedicate life to righteousness and courage.', 'Pinnacle of Sikh spiritual identity and the quintessential soul of Punjab''s agrarian vitality.', 'Also marks the tragic yet patriotic turning point of the 1919 Jallianwala Bagh massacre in India''s freedom struggle.', ARRAY['Holy dip (Amrit Snan) in the sacred Sarovar of Sri Harmandir Sahib', 'Continuous recitation of Sri Guru Granth Sahib Ji (Akhand Path)', 'Vibrant Bhangra and Giddha performances across rural fields']::TEXT[], 'Farmers celebrate across golden wheat fields, thousands join Nagar Kirtans, and Golden Temple glows with hundreds of thousands of oil lamps.', ARRAY['Sarson Ka Saag and Makki Di Roti', 'Karah Prasad', 'Lassi', 'Jalebi', 'Kheer']::TEXT[], 'Vibrant yellow and orange Kurtas, Chadras, and Turbans; women wear phulkari dupattas.', 'High-energy Bhangra with Dhol drum beats, chimta, algozey, and clapping Giddha.', 'Golden wheat stalks, Kirpan and Khanda emblems, and illuminated Golden Temple.', '1 to 2 Days', 'Solar (Nanakshahi / Bikrami)', 'First day of Vaisakh month (usually April 13 or 14).', 'April', 'SOLAR', 'Fixed solar calendar date (April 13 or 14).', '2026-04-14', '2027-04-14', 'Shiromani Gurdwara Parbandhak Committee (SGPC)', ARRAY['Punjab']::TEXT[], ARRAY['Amritsar', 'Anandpur Sahib', 'Bathinda', 'Ludhiana']::TEXT[], ARRAY['Sri Harmandir Sahib (Golden Temple)', 'Takht Sri Kesgarh Sahib', 'Talwandi Sabo']::TEXT[], 'Early morning at Golden Temple for Amrit Snan and evening fireworks', 2, 'Electrifying spiritual and cultural energy, golden wheat fields rippling in the breeze, and world-famous Punjabi hospitality.', 'Well connected by Amritsar International Airport, Shatabdi express trains, and GT Road.', 'Book hotels near Golden Temple months in advance; SGPC Sarai dharamshalas available.', 'Massive queues at Sri Harmandir Sahib; maintain patience and follow sewadar directions.', 'Cover head at all times, remove shoes and wash feet at entrance, no tobacco/alcohol allowed anywhere.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sgpc.net', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lohri-punjab', 'Lohri Statewide', ARRAY['Lohri Bonfire Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Sikhism / Hinduism', 'The quintessential winter bonfire festival of Punjab celebrating the passing of winter solstice and birth of sons and daughters.', 'Rooted in ancient folk legend of Dulla Bhatti, the Robin Hood of Punjab who rescued abducted girls and married them to suitable matches.', 'Celebrates the fertility of the land, solar transition toward Uttarayan, and harvest of sugarcane and mustard.', 'To welcome longer warmer days, offer gratitude to Agni (fire), and celebrate family milestones.', 'Strengthens joint family and village ties through collective song, storytelling, and dance.', 'Folk ballads of Dulla Bhatti preserve memories of heroic resistance against Mughal feudal oppression.', ARRAY['Kindling grand community bonfires at sunset', 'Offering sesame seeds, jaggery, peanuts, and popcorn into the flames', 'Singing traditional ''Sunder Mundariye'' folk ballads while circumambulating fire']::TEXT[], 'Families gather in courtyards around leaping bonfires, distributing prasad, tossing treats into flames, and dancing late into the night.', ARRAY['Gur (jaggery) Rewri', 'Gajak', 'Moongfali (peanuts)', 'Til Laddoo', 'Sarson ka Saag with Makki Di Roti']::TEXT[], 'Brightly colored festive salwar kameez, Phulkari shawls, Kurta-Chadhar with embroidered jackets.', 'Energetic community Bhangra and Giddha fueled by live Dhol rhythms.', 'Leaping golden bonfire flames, sugarcane stalks, and colorful kite strings.', '1 Day', 'Solar / Bikrami', 'Last day of the month of Paush (eve of Maghi / Makar Sankranti).', 'January', 'FIXED', 'Celebrated on January 13 annually.', '2026-01-13', '2027-01-13', 'Official Punjab Calendar', ARRAY['Punjab', 'Haryana', 'Delhi', 'Chandigarh']::TEXT[], ARRAY['Amritsar', 'Ludhiana', 'Jalandhar', 'Patiala']::TEXT[], ARRAY['Village chaupals', 'Community grounds', 'Residential courtyards']::TEXT[], 'Evening from 6 PM onwards around community bonfires', 1, 'Heartwarming winter warmth, crackling wood fire aromas, mouthwatering winter sweets, and infectious folk joy.', 'Easy travel across Punjab towns via auto-rickshaws and cabs.', 'Wide range of city hotels and authentic rural farmstays.', 'Stay mindful of flying embers around children; kite-flying on rooftops requires safety supervision.', 'Join in clapping and singing ''Sunder Mundariye''; accept offered rewri prasad graciously.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://punjabtourism.punjab.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hola-mohalla', 'Hola Mohalla Sri Anandpur Sahib', ARRAY['Hola Mahalla']::TEXT[], 'Historical & Royal', 'Sikhism (Khalsa Martial Tradition)', 'A breathtaking three-day display of martial arts, mock battles, horse riding, and swordsmanship created by Guru Gobind Singh Ji.', 'Instituted in 1701 CE by the tenth Sikh Guru at Anandpur Sahib following the playful Holi festival to instill martial spirit in the Khalsa.', 'Created to channel festive energy into discipline, physical courage, and battle preparedness.', 'To honor the saint-soldier (Sant-Sipahi) ideal of the Khalsa and demonstrate military prowess.', 'Living museum of medieval Indian martial sciences (Gatka) and chivalric brotherhood.', 'Preserved unbroken for over 300 years as the supreme assembly of the Nihang warrior orders.', ARRAY['Gatka martial arts demonstrations with swords, spears, and shields', 'Tent-pegging and acrobatic bareback horse riding by Nihang Singhs', 'Grand Mohalla military procession with decorated elephants and Nihang flags']::TEXT[], 'Over a million pilgrims congregate in Anandpur Sahib; Nihang warriors in indigo blue robes demonstrate awe-inspiring equestrian and weaponry feats.', ARRAY['Guru ka Langar served continuously to millions', 'Karah Prasad', 'Kheer', 'Almond-infused Shardai']::TEXT[], 'Traditional electric-blue and saffron robes of Nihang Sikhs with colossal multi-layered turbans (Dumaala) adorned with steel quoits (Chakkars).', 'Resounding martial war cries (''Bole So Nihal, Sat Sri Akal''), Dhol-Nagada, and battlefield bugles.', 'Steel quoits, crossed swords, blue Nihang flags, and Anandpur fort ramparts.', '3 Days', 'Hindu-Nanakshahi Lunisolar', 'Begins on the day following Holi (Chet Vadi 1)', 'March', 'LUNISOLAR', 'Begins the day after Holi in Phalguna/Chaitra.', '2026-03-04', '2027-03-23', 'SGPC Anandpur Sahib & Punjab Tourism', ARRAY['Punjab']::TEXT[], ARRAY['Sri Anandpur Sahib', 'Rupnagar']::TEXT[], ARRAY['Takht Sri Kesgarh Sahib', 'Charan Ganga Stadium']::TEXT[], 'Morning martial displays at Charan Ganga Stadium and grand concluding Mohalla procession', 3, 'Spectacular, adrenaline-charged martial spectacles of fearless horsemen, clashing steel swords, and boundless egalitarian Langar hospitality.', '85 km from Chandigarh via 4-lane highway; dedicated special trains run to Anandpur Sahib.', 'Huge rush; advance hotel booking or stay in SGPC Sarais or large pilgrim tented cities.', 'Extremely heavy crowds; stay behind safety barriers during horse riding and live weapon demonstrations.', 'Wear modest clothing covering head; respect Nihang customs; do not touch weapons without permission.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://rupnagar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gurpurab-guru-nanak', 'Prakash Purab Guru Nanak Dev Ji', ARRAY['Guru Nanak Jayanti']::TEXT[], 'Spiritual & Temple', 'Sikhism', 'The sacred birth anniversary celebration of Guru Nanak Dev Ji, founder of Sikhism, celebrated with illuminating prayer processions and continuous langars.', 'Marks the advent of Guru Nanak Dev Ji in 1469 CE at Rai Bhoi Di Talwandi (modern Nankana Sahib, Pakistan).', 'Celebrates the birth of the visionary spiritual reformer who preached universal brotherhood and one supreme creator (Ik Onkar).', 'To reflect upon Guru Nanak''s divine teachings of honest labor (Kirat Karo), sharing with others (Vand Chhako), and meditating on Naam (Naam Japo).', 'Foundation stone of the Sikh faith, emphasizing equality of all human beings regardless of caste, gender, or creed.', 'Inaugurated an egalitarian social revolution through the institutions of Sangat (holy congregation) and Pangat (free community dining).', ARRAY['48-hour unbroken recitation of Sri Guru Granth Sahib Ji (Akhand Path)', 'Grand morning Nagar Kirtan led by the Panj Pyare carrying the Nishan Sahib', 'Nightlong divine Gurbani Kirtan concluding at midnight']::TEXT[], 'Gurdwaras across Punjab are draped in fairy lights; millions sit together in equality to eat Langar and participate in Prabhat Pheris.', ARRAY['Karah Prasad (steamed sacred pudding of wheat flour, ghee, and sugar)', 'Dal Makhani', 'Kheer', 'Roti served in Guru ka Langar']::TEXT[], 'Fresh white, blue, or saffron traditional Kurta-Pajama with matching turbans; women wear modest Punjabi suits.', 'Heavenly celestial Gurbani Kirtan with traditional string instruments (Rababs, Taus, Dilruba) and harmonium.', 'Ek Onkar calligraphy, triangular saffron Nishan Sahib flag, and illuminated holy water Sarovar.', '3 Days', 'Hindu Lunisolar (Nanakshahi / Bikrami)', 'Kartik Purnima (full moon night of Kartik month)', 'November', 'LUNISOLAR', 'Full moon day of the Hindu lunar month of Kartik.', '2026-11-24', '2027-11-13', 'Shiromani Gurdwara Parbandhak Committee', ARRAY['Punjab']::TEXT[], ARRAY['Amritsar', 'Sultanpur Lodhi', 'Dera Baba Nanak', 'Patiala']::TEXT[], ARRAY['Sri Harmandir Sahib (Amritsar)', 'Gurdwara Ber Sahib (Sultanpur Lodhi)', 'Gurdwara Dukh Niwaran Sahib']::TEXT[], 'Evening at the Golden Temple during Deepmala illumination and midnight birth hour prayers', 2, 'profound spiritual peace as hundreds of thousands of oil lamps reflect in the calm waters of the Golden Temple Sarovar amidst soul-stirring hymns.', 'Shatabdi express trains from Delhi, Amritsar airport, and local auto-rickshaws.', 'Heavy pilgrim rush; book accommodation in Amritsar well in advance.', 'Immense gatherings; hold children''s hands firmly; keep personal belongings secure.', 'Head covering mandatory (scarves provided at entrance); take off footwear; wash feet in shallow water troughs before stepping on marble.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sgpc.net', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-maghi-mela-muktsar', 'Maghi Mela Sri Muktsar Sahib', ARRAY['Muktsar Mela']::TEXT[], 'Historical & Royal', 'Sikhism', 'The sacred annual fair commemorating the Forty Liberated Ones (Chali Mukte) who sacrificed their lives fighting the Mughal army in 1705.', 'Commemorates the Battle of Khidrana (1705 CE) where Guru Gobind Singh Ji forgave and blessed the forty disciples who died defending the faith.', 'Marks the supreme redemption, forgiveness, and battlefield martyrdom of the Chali Mukte.', 'To offer homage to the immortal martyrs and take a holy cleansing bath in the sacred Sarovar of Gurdwara Tibbi Sahib and Tuti Gandi Sahib.', 'Demonstrates the supreme spiritual bond between the Guru and his devoted disciples through divine forgiveness.', 'Transformed a barren desert outpost into a thriving holy city of pilgrimage and annual political conclaves.', ARRAY['Holy dip in the sacred Muktsar Sarovar on the dawn of Makar Sankranti', 'Grand Nagar Kirtan procession with holy flags and swords', 'Historical Nihang equestrian encampments and Gatka matches']::TEXT[], 'Pilgrims from across Punjab and Haryana bathe at sunrise, listen to Dhadi ballads singing of heroic battles, and visit the historical gurdwaras.', ARRAY['Jaggery Kheer (Rauh Di Kheer)', 'Sarson Ka Saag', 'Karah Prasad', 'Langar Dal']::TEXT[], 'Warm woolen coats, shawls, and turbans in shades of saffron and deep blue.', 'Traditional Dhadi Jathas performing heroic ballads with Sarangi and Dhad drums.', 'Historical sarovar waters, memorial cenotaphs of the forty martyrs, and Nishan Sahib.', '3 Days', 'Solar / Bikrami', 'First day of the solar month of Magh (Makar Sankranti).', 'January', 'FIXED', 'Celebrated on January 14 annually.', '2026-01-14', '2027-01-14', 'Muktsar District Administration & SGPC', ARRAY['Punjab']::TEXT[], ARRAY['Sri Muktsar Sahib']::TEXT[], ARRAY['Gurdwara Darbar Sahib (Tuti Gandi Sahib)', 'Gurdwara Tibbi Sahib']::TEXT[], 'Dawn of January 14 for the sacred holy bath', 2, 'Deep emotional reverence, rustic Punjabi fairground vibrancy with giant Ferris wheels, and stirring heroic poetry.', 'Connected by road and rail from Bathinda (50 km) and Ludhiana (130 km).', 'Local hotels, SGPC Sarais, and tented accommodations.', 'Freezing January dawn winds; pack warm thermal clothing and woolen caps.', 'Respect the sanctity of the bathing ghats; follow instructions of SGPC volunteer guards.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://muktsar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-harballabh-sangeet-sammelan', 'Harballabh Sangeet Sammelan Jalandhar', ARRAY['Shree Baba Harballabh Sangeet Mahasabha']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Music Heritage', 'The oldest unbroken festival of Indian classical music in the world, organized annually since 1875 near the Samadhi of saint-musician Baba Harballabh.', 'Initiated in 1875 by Baba Harballabh, a revered saint and master of Hindustani classical music at Devi Talab.', 'Organized to honor the saint and preserve the purest traditions of Hindustani classical vocal and instrumental music.', 'To provide a sanctified platform where top musical maestros perform as a spiritual offering without commercial fees.', 'Recognized by UNESCO and the Government of India as an invaluable intangible cultural heritage treasure.', 'Every great maestro of Indian classical music (Pt. Bhimsen Joshi, Ustad Bismillah Khan, Pt. Ravi Shankar) has considered performing here a crowning honor.', ARRAY['Evening lamp lighting and invocation to Goddess Saraswati', 'Consecutive nightlong classical vocal and instrumental concerts', 'Annual competition encouraging young prodigies in classical disciplines']::TEXT[], 'Music connoisseurs sit in pin-drop silence in a vast pandal from dusk till dawn, listening to legendary vocalists, sitarists, and sarod players.', ARRAY['Amritsari Kulcha', 'Makki Roti with Saag', 'Pinni', 'Hot Jalebi with Milk']::TEXT[], 'Refined formal attire: Kurta-pyjama with Nehru jackets, classical silk sarees, and shawls.', 'Unrivaled Hindustani classical ragas, Dhrupad, Khayal, Thumri, Sitar, Sarod, Santoor, and Tabla solos.', 'Bronze idol of Baba Harballabh, sacred tanpura instruments, and Devi Talab mandir reflection.', '3 Days', 'Gregorian / Heritage', 'Celebrated on the last weekend of December annually.', 'December', 'FIXED', 'Last Friday to Sunday of December.', '2026-12-25', '2027-12-24', 'Shree Baba Harballabh Sangeet Mahasabha', ARRAY['Punjab']::TEXT[], ARRAY['Jalandhar']::TEXT[], ARRAY['Devi Talab Mandir Complex Jalandhar']::TEXT[], 'Night sessions (8 PM to 4 AM) when meditative nocturnal ragas are performed', 3, 'Sublime acoustic ecstasy among thousands of passionate, knowledgeable classical music aficionados in a tranquil historic temple courtyard.', 'Centrally located in Jalandhar; easily reached by auto-rickshaw or taxi from Jalandhar City Railway Station.', 'Comfortable business and heritage hotels throughout Jalandhar city.', 'Chilly December nights inside the open-sided pandal; carry heavy woolen shawls, mufflers, and thermal jackets.', 'Strict concert etiquette: absolute silence during performances; no flash photography or entering/exiting mid-raga.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://harballabh.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chhapar-mela-ludhiana', 'Chhapar Mela Ludhiana', ARRAY['Gugga Pir Chhapar Mela']::TEXT[], 'Tribal & Folk Traditions', 'Folk Shamanism / Syncretic Hindu-Muslim-Sikh', 'A massive rural congregation in Chhapar village dedicated to Gugga Pir, the legendary snake deity protector revered by millions.', 'Dates back over 150 years, centered around the historic shrine (Mari) of Gugga Jahar Pir constructed in 1890.', 'Celebrates the protection from venomous snakebites and fertility of livestock granted by Gugga Pir.', 'To scoop earth (Mitti Kadhna) from the sacred pond to cure skin ailments and fulfill vows.', 'Extraordinary testament to rural syncretism where farmers across all religious lines revere the same protector.', 'One of the largest agrarian fairs in northern India, featuring traditional rural games, cattle trading, and folk theatre.', ARRAY['Mitti Kadhna ritual of digging earth seven times from the sacred pond', 'Offering of sweet vermicelli (Seviyan), milk, and raw sugar at the snake mound', 'Folk performances by Malwai Giddha troupes and folk balladeers']::TEXT[], 'Huge colorful fairgrounds spring up across rural fields with giant wooden swings, circus shows, cattle displays, and singing competitions.', ARRAY['Seviyan (vermicelli cooked in milk)', 'Jalebi', 'Pakoras', 'Sugarcane juice']::TEXT[], 'Vibrant rural Punjabi attire: colorful chadras, bright turbans, and kurta-pyjamas.', 'Malwai Giddha performed by elderly men with traditional folk instruments (Kato, Sapp, Tumbi, Chimta).', 'Snake idol on marble pedestal, red flags at Gugga Mari shrine, and sacred mound.', '3 Days', 'Hindu Lunisolar', 'Begins on Chaudas of Bhadrapada month (September)', 'September', 'LUNISOLAR', 'Observed on Anant Chaudas in Bhadrapada.', '2026-09-25', '2027-09-14', 'Ludhiana District Administration & Chhapar Panchayat', ARRAY['Punjab']::TEXT[], ARRAY['Chhapar', 'Ludhiana']::TEXT[], ARRAY['Gugga Mari Shrine Chhapar']::TEXT[], 'Daytime fair activities and afternoon Malwai Giddha sessions', 2, 'Authentic rustic Punjabi village mela atmosphere packed with genuine folk warmth, village banter, and timeless folk games.', '35 km from Ludhiana city; accessible by state transport buses and rural shared taxis.', 'Stay in Ludhiana hotels and visit Chhapar as a day trip.', 'Massive rural crowds (over 500,000 visitors); expect dusty fairground paths and tractor-trolley congestion.', 'Treat village customs with respect; follow queue lines at the sacred Mari.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ludhiana.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-baba-farid-aagman', 'Baba Farid Aagman Purb Faridkot', ARRAY['Farid Mela']::TEXT[], 'Spiritual & Temple', 'Sufism & Sikhism', 'A deeply reverent syncretic cultural festival commemorating the arrival of the great 12th-century Sufi poet Hazrat Baba Sheikh Farid to Faridkot.', 'Commemorates the historic visit of Baba Farid in the 13th century when he performed penance at Tilla Baba Farid and blessed the town.', 'Celebrates the timeless message of humility, love for humanity, and divine detachment preached by Baba Farid.', 'To honor the Sufi saint whose 134 sacred hymns are enshrined with eternal reverence in the Sikh holy scripture Sri Guru Granth Sahib Ji.', 'Supreme symbol of Punjabi linguistic pride and inter-faith harmony between Muslims, Sikhs, and Hindus.', 'Marks the conferment of the prestigious annual Baba Farid National Peace and Literature awards.', ARRAY['Grand Nagar Kirtan and peace march from Qila Mubarak to Tilla Baba Farid', 'Sufi musical evenings with world-renowned Qawwali singers', 'National seminar on Sufi philosophy and Punjabi literary heritage']::TEXT[], 'The entire historic city of Faridkot participates in peace processions, community langars, and all-night Sufi Mehfils.', ARRAY['Zarda sweet saffron rice', 'Langar Dal and Roti', 'Firni', 'Jalebi']::TEXT[], 'White Kurta-Pajama with green or yellow stoles, traditional Punjabi suits.', 'Heart-melting Qawwalis, rendition of Baba Farid''s Slokas, and classical Sufiana kalam.', 'Ancient deodar timber of Tilla Baba Farid, earthen lamps, and green velvet chadars.', '5 Days', 'Gregorian / Anniversary', 'September 19 to 23 annually.', 'September', 'FIXED', 'Observed September 19-23 every year.', '2026-09-19', '2027-09-19', 'Faridkot District Cultural Society & Punjab Tourism', ARRAY['Punjab']::TEXT[], ARRAY['Faridkot']::TEXT[], ARRAY['Tilla Baba Farid', 'Qila Mubarak Faridkot', 'Darbar Ganj']::TEXT[], 'Evening Sufi musical sessions at Darbar Ganj and the opening peace procession', 2, 'Deep spiritual peace, fragrant rosewater incense, sublime poetic recitations, and warm welcoming hospitality.', 'Well connected by train from Bathinda (65 km) and Firozpur (35 km).', 'Hotels, circuit house, and guest houses in Faridkot town.', 'Peaceful family crowd; maintain decorum during academic seminars and spiritual musical recitals.', 'Cover head before entering Tilla Baba Farid shrine; remove shoes at the portal.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://faridkot.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rauza-sharif-urs', 'Rauza Sharif Urs Sirhind', ARRAY['Urs Mubarak Shaikh Ahmad Sirhindi']::TEXT[], 'Spiritual & Temple', 'Islam (Naqshbandi Sufism)', 'The historic international Urs of Hazrat Shaikh Ahmad Faruqi Sirhindi (Mujaddid Alf-e-Sani), drawing thousands of Naqshbandi Sufi pilgrims.', 'Centuries-old Islamic gathering honoring the 16th-century reviver of the second millennium of Islam.', 'Celebrates the life, theological works, and spiritual legacy of Shaikh Ahmad Sirhindi.', 'To pray for spiritual enlightenment and pay homage at the magnificent Mughal-era terracotta mausoleum.', 'One of the most important centers of the Naqshbandi Sufi order in South Asia, drawing devotees from India, Pakistan, Afghanistan, and Central Asia.', 'Historical architectural treasure showcasing Akbar and Jahangir-era brick and red sandstone mausoleums.', ARRAY['Recitation of the Holy Quran and Naat poetry', 'Chadar poshi offering of embroidered velvet coverings on the holy mazar', 'Spiritual discourses on Naqshbandi meditation (Muraqaba)']::TEXT[], 'Pilgrims congregate in the serene domed brick courtyards, meditating in silent contemplation and partaking in communal meals.', ARRAY['Mutton Biryani', 'Zarda sweet rice', 'Sheermal', 'Sufi Halwa']::TEXT[], 'Traditional white Pathani suits, Kurta-pajamas, and embroidered prayer caps.', 'Silent Naqshbandi Zikr (meditation of the heart), soulful Naat recitations without instrumental music.', 'Red sandstone and brick ribbed domes of the Rauza, floral arabesques, and green ceremonial flags.', '3 Days', 'Islamic Lunar (Hijri)', 'Safar month of the Islamic calendar', 'August - September', 'LUNAR', 'Observed in the Islamic lunar month of Safar.', '2026-08-28', '2027-08-17', 'Rauza Sharif Dargah Committee & Punjab Tourism', ARRAY['Punjab']::TEXT[], ARRAY['Sirhind', 'Fatehgarh Sahib']::TEXT[], ARRAY['Dargah Rauza Sharif Complex Sirhind']::TEXT[], 'Morning congregational prayers and afternoon relic viewing', 2, 'Austere, dignified spiritual tranquility within magnificent 400-year-old Mughal architectural courtyards.', '50 km from Chandigarh via GT Road; 5 km from Sirhind Railway Station.', 'Dargah pilgrim guest accommodations, hotels in Sirhind and nearby Khanna.', 'Dignified international gathering; orderly lines maintained throughout.', 'Dress conservatively with legs and shoulders fully covered; head covering required for both men and women.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://fatehgarhsahib.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kila-raipur-sports', 'Kila Raipur Rural Olympics', ARRAY['Rural Olympics of Punjab']::TEXT[], 'Art & Cultural Festival', 'Rural Sports & Martial Athletics', 'The world-famous ''Rural Olympics'' showcasing awe-inspiring feats of rural strength, bullock cart races, tent-pegging, and folk endurance.', 'Founded in 1933 by philanthropist Inder Singh Grewal to channel the boundless physical energy of rural Punjabi youth into healthy sporting competitions.', 'Celebrates rural physical vigor, traditional athleticism, and community camaraderie after the winter harvest.', 'To preserve traditional indigenous sports, promote fitness, and identify grassroots athletic talent.', 'Globally celebrated showcase of rural Punjab''s indomitable courage, athletic grit, and colorful village culture.', 'Documented by international sporting broadcasters as one of the most unique indigenous sporting festivals on earth.', ARRAY['High-speed bullock cart and camel races across stadium turf', 'Unbelievable feats of strength (pulling tractors with teeth, lifting bicycles with jaws)', 'Traditional Punjabi Kabaddi and tug-of-war tournaments']::TEXT[], 'Thousands of spectators cheer from stadium embankments as daring youth and octogenarian athletes perform extraordinary stunts.', ARRAY['Pinni with dry fruits', 'Jalebi', 'Chana Kulcha', 'Fresh Lassi in giant steel glasses']::TEXT[], 'Athletic vests with track pants, colorful chadras, and bright yellow and red turbans.', 'Resounding Punjabi commentary, energetic Dhol drumming accompanying victory laps, and impromptu Bhangra.', 'Bullock cart wheels, polished brass bells on racing bull yokes, and sports victory trophies.', '3 Days', 'Gregorian / Winter', 'Held in the first week of February annually.', 'February', 'FIXED', 'First Friday to Sunday of February.', '2026-02-06', '2027-02-05', 'Grewal Sports Association Kila Raipur & Punjab Tourism', ARRAY['Punjab']::TEXT[], ARRAY['Kila Raipur', 'Ludhiana']::TEXT[], ARRAY['Grewal Sports Stadium Kila Raipur']::TEXT[], 'Mid-day from 11 AM to 4 PM for the most thrilling strength feats and chariot races', 2, 'Electrifying adrenaline rush, thunderous cheers, roaring tractor engines, and unforgettable displays of raw human physical endurance.', '18 km south of Ludhiana city; easily reached by taxi or special event shuttle buses.', 'Extensive hotel accommodations in Ludhiana city.', 'Keep well clear of the racing tracks; horses and bullock carts run at blazing speeds.', 'Support the rural athletes enthusiastically; maintain clean stadium premises.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ludhiana.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chandigarh-rose-festival', 'Chandigarh Rose Festival', ARRAY['Zakir Hussain Rose Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Botanical & Cultural', 'Asia''s largest rose exhibition celebrating over 50,000 rose bushes in 1,600 varieties inside the famed 30-acre Zakir Hussain Rose Garden.', 'Started in 1972 by the Chandigarh UT Administration to celebrate the visionary landscape design of Dr. M.S. Randhawa and Le Corbusier.', 'Celebrates the peak blooming season of exotic roses and the onset of spring in the City Beautiful.', 'To promote floriculture, urban green heritage, and community cultural engagement.', 'Signature annual festival defining Chandigarh''s identity as a planned green garden city.', 'Attracts over 300,000 visitors, horticulturists, and artists from across northern India.', ARRAY['Grand flower arrangement and bonsai competitions', 'Rose Prince and Rose Princess fancy dress pageants', 'Helicopter joyrides and evening musical concerts']::TEXT[], 'Families wander through aromatic floral pathways, clicking photos amidst velvety rose beds, enjoying food stalls, and watching folk dancers.', ARRAY['Chhole Bhature', 'Spring Mocktails', 'Soft Serve Ice Cream', 'Amritsari Kulcha']::TEXT[], 'Smart casuals, spring floral dresses, and light pastel cotton kurtas.', 'Live folk dance performances from northern states, brass band displays, and musical concerts.', 'Multi-hued blooming rose arches, fountain jets, and Le Corbusier concrete pergolas.', '3 Days', 'Gregorian / Botanical', 'Last weekend of February annually.', 'February', 'FIXED', 'Last Friday to Sunday of February.', '2026-02-27', '2027-02-26', 'Chandigarh Tourism & Municipal Corporation Chandigarh', ARRAY['Chandigarh']::TEXT[], ARRAY['Chandigarh']::TEXT[], ARRAY['Zakir Hussain Rose Garden Sector 16']::TEXT[], 'Mid-morning for photography and early evening for cultural shows', 2, 'Crisp sunny spring weather, intoxicating perfume of thousands of rare roses, and spotless green urban parkways.', 'Centrally located in Sector 16; auto-rickshaws, CTU electric city buses, and app cabs.', 'Excellent hospitality options across Chandigarh, Mohali, and Panchkula.', 'Heavy footfall on weekends; use designated pedestrian underpasses and parking zones.', 'Strictly forbidden to pluck flowers, step into garden beds, or litter; strictly enforced fines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chandigarhtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chandigarh-carnival', 'Chandigarh Carnival', ARRAY['City Beautiful Cultural Carnival']::TEXT[], 'Art & Cultural Festival', 'Secular / Youth & Arts', 'A vibrant three-day open-air carnival celebrating art, literature, youth creativity, and performing arts across Leisure Valley.', 'Introduced by Chandigarh Tourism to provide a dedicated annual creative platform for local citizens and tourists.', 'Celebrates the creative spirit, architectural legacy, and youthful vitality of Chandigarh.', 'To foster artistic expression, showcase local talent, and offer affordable family entertainment.', 'Transforms Le Corbusier''s iconic green Leisure Valley corridor into an interactive cultural hub.', 'Serves as the prime launchpad for college music bands, folk troupes, and contemporary street artists.', ARRAY['Grand costumed carnival parade featuring vintage cars and floats', 'Inter-college rock band and street play competitions', 'Live star nights featuring celebrated Punjabi pop and Sufi singers']::TEXT[], 'Thousands of youth and families explore handicraft stalls, art installations, amusement rides, and open-air food courts.', ARRAY['Momos', 'Tandoori Chicken Tikka', 'Spring Rolls', 'Chandigarh Street Chaat']::TEXT[], 'Trendy contemporary winter fashion, denim jackets, and colorful scarves.', 'High-voltage Punjabi pop concerts, rock bands, Bhangra troupes, and mime acts.', 'Giant colorful carnival floats, sculptural art installations, and balloon arches.', '3 Days', 'Gregorian / Autumn', 'Last weekend of November annually.', 'November', 'FIXED', 'Last Friday to Sunday of November.', '2026-11-27', '2027-11-26', 'Chandigarh Tourism Administration', ARRAY['Chandigarh']::TEXT[], ARRAY['Chandigarh']::TEXT[], ARRAY['Leisure Valley Sector 10']::TEXT[], 'Afternoon 3 PM onwards into the vibrant musical star nights', 2, 'Youthful electric energy, artistic outdoor installations under towering eucalyptus trees, and pleasant autumn evening breezes.', 'Located in Sector 10 near Government Museum; easily accessible by cab or city bus.', 'Hotels across Sectors 17, 22, 35, and IT Park Chandigarh.', 'High student and youth crowds during star nights; follow security frisking guidelines.', 'Keep the green parklands clean; dispose waste in categorized recycling bins.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chandigarhtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mango-festival-pinjore', 'Mango Festival Pinjore Gardens', ARRAY['Pinjore Mango Mela']::TEXT[], 'Harvest & Agriculture', 'Secular / Agrarian & Horticultural', 'A mouthwatering summer festival celebrating India''s king of fruits with displays of over 500 varieties of mangoes inside historic 17th-century Mughal gardens.', 'Jointly initiated in 1992 by Haryana Tourism and the Horticulture Department at the historic Yadavindra (Pinjore) Gardens.', 'Celebrates the summer harvest of India''s richest biodiversity of mango cultivars from northern states.', 'To provide a direct commercial and promotional platform for mango growers and celebrate royal garden heritage.', 'Revitalizes the 17th-century terraced pleasure garden laid out by Nawab Fidai Khan with vibrant seasonal festivities.', 'Attracts mango cultivators from Uttar Pradesh, Punjab, Haryana, Himachal, and Uttarakhand to compete for the ''Mango King'' title.', ARRAY['Exhibition and competitive judging of 500+ mango varieties (Dussehri, Langra, Chausa, Alphonso, Totapuri)', 'Mango eating and tasting competitions for visitors', 'Cultural dances and folk music on historic garden terraces']::TEXT[], 'Visitors taste and purchase rare mango cultivars, sip chilled mango panna, and explore terraced water fountains lit up in the evening.', ARRAY['Fresh sliced mangoes of rare varieties', 'Aam Panna', 'Mango Kulfi', 'Mango Lassi']::TEXT[], 'Comfortable summer cottons, linen shirts, and floral kurtis.', 'Haryanvi Ragni, Punjabi Giddha, and Rajasthani folk dances performed on stone pavilions.', 'Heaping crates of golden, crimson, and green mangoes, terraced water canals, and Mughal pavilions.', '2 Days', 'Gregorian / Summer Harvest', 'First weekend of July annually.', 'July', 'FIXED', 'First Saturday and Sunday of July.', '2026-07-04', '2027-07-03', 'Haryana Tourism & UT Administration', ARRAY['Chandigarh', 'Haryana']::TEXT[], ARRAY['Pinjore', 'Panchkula', 'Chandigarh']::TEXT[], ARRAY['Yadavindra Gardens Pinjore']::TEXT[], 'Morning for mango exhibition judging and late afternoon for illuminated garden strolls', 2, 'Juicy tropical indulgence inside a historic multi-tiered Mughal garden with sparkling fountains and ancient mango orchards.', '22 km from Chandigarh on the Himalayan Expressway; accessible by taxi, car, or Haryana Roadways buses.', 'Resorts in Pinjore, Panchkula, and Chandigarh city.', 'Warm humid weather; stay hydrated and carry sun protection during daytime.', 'Do not touch fruit exhibits before official judging concludes; buy fruit only from authorized grower stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-plaza-carnival-sector17', 'Plaza Carnival Sector 17', ARRAY['Sector 17 Open Air Weekend Carnival']::TEXT[], 'Art & Cultural Festival', 'Secular / Urban Community Arts', 'A cherished weekend cultural institution held at the sprawling pedestrian Plaza of Sector 17, featuring free open-air concerts, magicians, and folk dancers.', 'Initiated in the 1990s by Chandigarh Administration to make world-class cultural arts accessible to the common public in the city center.', 'Celebrates urban public spaces, pedestrian civic life, and local performing arts.', 'To foster social cohesion, support emerging artists, and energize the city''s commercial and architectural center.', 'Embodies Le Corbusier''s concept of the Sector 17 ''heart of the city'' as an inclusive pedestrian agora.', 'One of the longest-running free public weekend cultural series in urban India.', ARRAY['Open-air musical concerts featuring classical and folk genres', 'Puppet shows, street magicians, and ventriloquists for children', 'Skating exhibitions and amateur artist street exhibitions']::TEXT[], 'Hundreds of families assemble on concrete plaza steps around the central fountain, shopping, enjoying street food, and listening to live melodies.', ARRAY['Gol Gappe', 'Softy Ice Cream', 'Pav Bhaji', 'Chana Kulcha', 'Tandoori Soya Chaap']::TEXT[], 'Smart casual city wear, sneakers, and comfortable evening walking clothes.', 'Sufi music, ghazal recitals, Punjabi folk singing, and instrumental violin/sitar performances.', 'Le Corbusier concrete colonnades, dancing illuminated fountains, and open plaza skylines.', 'Recurring Weekends', 'Civic / Recurring', 'Organized on selected weekends during pleasant autumn and spring months.', 'October - March', 'ORGANIZER_ANNOUNCED', 'Organized on Saturday evenings during temperate months.', '2026-10-17', '2027-10-16', 'Chandigarh Tourism Department', ARRAY['Chandigarh']::TEXT[], ARRAY['Chandigarh']::TEXT[], ARRAY['Central Plaza Sector 17']::TEXT[], 'Saturday evenings between 6 PM and 9 PM', 1, 'Relaxed, sophisticated urban pedestrian ambiance where modern architecture meets warm Punjabi evening culture.', 'Plaza is strictly pedestrian; park vehicles at multi-level parking lots in Sector 17.', 'Abundant hotel accommodation across central Chandigarh.', 'Very safe, family-friendly pedestrian environment with strong police presence.', 'Keep the plaza litter-free; seating on steps is on first-come basis.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chandigarhtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-surajkund-crafts-mela', 'Surajkund International Crafts Mela', ARRAY['Surajkund Mela']::TEXT[], 'Fair & Mela', 'Secular / Global Crafts & Rural Heritage', 'The world''s largest crafts fair bringing together over a million visitors, master artisans, and cultural troupes from over 40 nations to a picturesque rural amphitheatre.', 'Started in 1987 by Haryana Tourism near the ancient 10th-century Surajkund reservoir built by King Surajpal of the Tomar dynasty.', 'Celebrates the living crafts heritage, indigenous handlooms, and folk performance traditions of rural India and partner nations.', 'To eliminate middlemen, provide direct national market access to rural artisans, and promote global peace through craft diplomacy.', 'Designated as an International Crafts Mela by the Ministry of Tourism, showcasing a designated Theme State and Partner Country every year.', 'Preserves endangered traditional craft techniques (terracotta, bell metal, ikat, woodwork, lac) for future generations.', ARRAY['Demonstrations by national award-winning master craftspersons', 'Folk dance performances across multiple rural amphitheatres (Chaupals)', 'Grand evening cultural galas at the main open-air auditorium']::TEXT[], 'Visitors walk through authentic thatched-roof rural huts, buying handcrafted textiles, tasting regional culinary spreads, and enjoying folk dancers.', ARRAY['Haryanvi Bajra Khichdi with Desi Ghee and Jaggery', 'Ghevar', 'Kachori', 'Multi-state food court delicacies']::TEXT[], 'Handloom sarees, kurtas, Nehru jackets, and ethnic artisan jewelry.', 'Continuous folk performances: Haryanvi Dhamal and Khoria, Kalbelia, Bihu, Rouff, alongside international African and European ensembles.', 'Terracotta village archways, ancient sun pool amphitheatre, and hand-painted folk murals.', '17 Days', 'Gregorian / Annual', 'First fortnight of February (usually Feb 1 to 17).', 'February', 'FIXED', 'Held annually from February 1 to mid-February.', '2026-02-01', '2027-02-01', 'Surajkund Mela Authority & Haryana Tourism', ARRAY['Haryana']::TEXT[], ARRAY['Faridabad', 'Delhi NCR']::TEXT[], ARRAY['Surajkund Mela Grounds Faridabad']::TEXT[], 'Weekdays from 10:30 AM to 4 PM for uncrowded artisan browsing; evenings for cultural concerts', 2, 'Spectacular kaleidoscope of world crafts, earthy rural aromas, colorful folk costumes, and vibrant global bonhomie.', 'Dedicated feeder buses from Tughlakabad and Badarpur Metro Stations (Delhi Metro Violet Line); app cabs easily available.', 'Abundant hotels across Faridabad, South Delhi, and Gurugram.', 'Extremely heavy weekend crowds (up to 100,000 daily); book tickets online in advance to bypass ticket queues.', 'Respect the craftspersons; avoid aggressive bargaining on handcrafted masterworks; wear comfortable walking shoes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-international-gita-mahotsav', 'International Gita Mahotsav Kurukshetra', ARRAY['Gita Jayanti Kurukshetra']::TEXT[], 'Spiritual & Temple', 'Hinduism (Philosophical Heritage)', 'The profound international celebration commemorating the birth of the Bhagavad Gita on the historic battlefield of Kurukshetra where Lord Krishna delivered his celestial sermon to Arjuna.', 'Centuries-old observance formally elevated to an international festival in 2016 by the Haryana Government at Brahma Sarovar.', 'Marks Mokshada Ekadashi, the day Lord Krishna delivered the immortal 700 verses of the Bhagavad Gita.', 'To disseminate the universal philosophical teachings of selfless duty (Karma Yoga), wisdom (Jnana), and devotion (Bhakti).', 'Celebrates the spiritual and intellectual cornerstone of Indian civilization at its exact geographical birthplace.', 'Brings together international scholars, philosophers, and devotees for academic seminars and cultural presentations.', ARRAY['Global mass chanting of Bhagavad Gita verses by tens of thousands of school students and scholars', 'Grand Maha Aarti at Brahma Sarovar with thousands of oil lamps floating on water', 'National craft fair and intellectual seminars on contemporary relevance of Gita']::TEXT[], 'Brahma Sarovar comes alive with spiritual hymns, illuminated ghats, classical dance dramas, and exhibitions on Mahabharata heritage.', ARRAY['Haryanvi Dalia', 'Kheer', 'Panjiri', 'Makhan-Mishri prasad', 'Gond Ke Laddoo']::TEXT[], 'Traditional dhotis, kurtas, yellow stoles, and modest Indian ethnic attire.', 'Classical Bharatanatyam, Kathak, and Odissi dance dramas depicting the Vishwaroop Darshan, accompanied by live Vedic chanting.', 'Golden chariot of Lord Krishna and Arjuna, sacred banyan tree at Jyotisar, and shimmering waters of Brahma Sarovar.', '18 Days', 'Hindu Lunisolar', 'Culminates on Mokshada Ekadashi of Margashirsha month (December)', 'November - December', 'LUNISOLAR', 'Culminates on Margashirsha Shukla Ekadashi.', '2026-12-20', '2027-12-09', 'Kurukshetra Development Board & Haryana Tourism', ARRAY['Haryana']::TEXT[], ARRAY['Kurukshetra', 'Jyotisar']::TEXT[], ARRAY['Brahma Sarovar Ghats', 'Jyotisar Heritage Complex']::TEXT[], 'Evening Maha Aarti at Brahma Sarovar and day visits to the sacred banyan tree at Jyotisar', 2, 'Deep philosophical resonance, awe-inspiring vistas of one of Asia''s largest man-made water tanks glowing with lamps, and spiritual upliftment.', 'Well connected by road (NH-44) and rail; 160 km north of Delhi and 90 km south of Chandigarh.', 'Hotels, dharamshalas, and tourist complexes across Kurukshetra and nearby Karnal.', 'Significant crowds on Gita Jayanti day; stick to paved pedestrian tracks around the sarovar perimeter.', 'Maintain spiritual decorum; remove footwear near bathing ghats; participate respectfully in evening aartis.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gita.haryana.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pinjore-heritage-festival', 'Pinjore Heritage Festival', ARRAY['Pinjore Utsav']::TEXT[], 'Historical & Royal', 'Secular / Historic Garden Architecture', 'A grand evening festival celebrating the 17th-century Mughal architectural and royal heritage of Yadavindra Gardens with classical music and illuminations.', 'Initiated in 2006 by Haryana Tourism to highlight the timeless beauty of the terraced gardens designed by architect Nawab Fidai Khan.', 'Celebrates the living heritage, royal court arts, and classical music of the medieval era.', 'To promote heritage preservation and showcase the architectural magnificence of terraced pleasure gardens.', 'Exemplifies the syncretic Mughal-Rajput garden design with seven cascading terraces, water channels, and arched pavilions.', 'Recreates the ambiance of royal durbars with illuminated fountains and classical performances under starry skies.', ARRAY['Special night illumination of heritage palaces (Shish Mahal, Rang Mahal, Jal Mahal)', 'Classical vocal and instrumental recitals by national maestros', 'Heritage walks explaining Mughal hydraulics and architectural design']::TEXT[], 'Guests stroll along illuminated cascading water canals, enjoying classical dance ballets and authentic north Indian royal cuisine.', ARRAY['Mughlai Biryani', 'Shahi Tukda', 'Kulfi Falooda', 'Haryanvi Kheer']::TEXT[], 'Traditional formal ethnic wear: Sherwanis, Kurta-pajamas with stoles, and rich silk sarees.', 'Classical Kathak dance, Dhrupad and Khayal vocal recitals, sitar-sarod jugalbandis, and Sufiana music.', 'Terraced water fountains with underwater lights, stone jali screens, and illuminated domes.', '2 Days', 'Gregorian / Autumn', 'Held in October / November annually.', 'October - November', 'ORGANIZER_ANNOUNCED', 'Announced annually by Haryana Tourism.', '2026-10-24', '2027-10-23', 'Haryana Tourism Corporation', ARRAY['Haryana']::TEXT[], ARRAY['Pinjore', 'Panchkula', 'Chandigarh']::TEXT[], ARRAY['Yadavindra Gardens Pinjore']::TEXT[], 'Evenings between 5 PM and 10 PM when palace illuminations and music concerts begin', 2, 'Romantic, regal ambiance with gently splashing fountains, classical melodies echoing off stone arches, and crisp autumn night air.', '22 km from Chandigarh along the scenic foothills highway; easily reached by taxi or car.', 'Heritage resorts in Pinjore, Panchkula, and luxury hotels in Chandigarh.', 'Steps between terraces can be dim; watch your step while walking along water canals.', 'Do not touch delicate heritage wall plasters; maintain silence during classical concerts.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-haryali-teej-haryana', 'Haryali Teej of Haryana', ARRAY['Teej Mela Haryana']::TEXT[], 'Seasonal & Nature', 'Hinduism (Shaktism & Agrarian Nature)', 'The exuberant monsoon festival of swings and greenery celebrating the reunion of Lord Shiva and Devi Parvati and welcoming the cooling rains.', 'Centuries-old monsoon festival celebrated throughout the agrarian heartland of Haryana and northern India.', 'Commemorates the 108-year penance of Goddess Parvati to win Lord Shiva as her consort.', 'To celebrate nature''s rejuvenation, marital harmony, and the joy of women returning to their ancestral homes.', 'Fosters deep female solidarity through collective singing, swinging on decorated swings, and exchanging gifts.', 'Traditional practice of ''Kothli'' (gift hampers sent by parents to married daughters) cements lifelong familial bonds.', ARRAY['Hanging floral swings (Jhoolas) from giant banyan and neem trees', 'Applying intricate green mehndi (henna) patterns on hands and feet', 'Offering prayers to Goddess Parvati for husband''s long life and family happiness']::TEXT[], 'Women and young girls dress in shimmering green clothes, take turns swinging high into the monsoon air, and sing melodious Teej folk songs.', ARRAY['Ghevar (disc-shaped honeycomb sweet soaked in saffron syrup)', 'Feni', 'Malpua', 'Kheer', 'Poori Chhole']::TEXT[], 'Vibrant green Lehengas, green bangles, embroidered Odhnis, and traditional silver Hansli necklaces.', 'Traditional Haryanvi women''s folk dances (Khoria and Loor), accompanied by rhythmic clapping and Dholak.', 'Green swings decorated with marigold garlands, peacock motifs, and sweet Ghevar boxes.', '1 to 2 Days', 'Hindu Lunisolar', 'Tritiya (3rd day) of Shukla Paksha in Shravana month', 'August', 'LUNISOLAR', 'Celebrated on Shravana Shukla Tritiya.', '2026-08-16', '2027-08-05', 'Haryana Cultural Affairs Department', ARRAY['Haryana']::TEXT[], ARRAY['Rohtak', 'Hisar', 'Ambala', 'Jhajjar', 'Faridabad']::TEXT[], ARRAY['Village greens', 'District community parks', 'Town squares']::TEXT[], 'Afternoon and evening when swings are active and fairs are bustling', 1, 'Joyful, festive community spirit with melodic folk songs, fragrant henna aromas, and mouthwatering seasonal Ghevar sweets.', 'Easily accessible across all towns and villages of Haryana via local buses and cabs.', 'City hotels across major Haryana district centers.', 'Crowded swings in public parks; ensure safety of young children around ropes.', 'Respect the cultural modesty of village women participating in family rituals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-baisakhi-mela-pinjore', 'Baisakhi Mela Pinjore', ARRAY['Spring Baisakhi Fest Pinjore']::TEXT[], 'Harvest & Agriculture', 'Secular / Cultural & Agrarian', 'The lively spring harvest mela celebrated inside Pinjore Gardens showcasing traditional Punjabi and Haryanvi folk vitality.', 'Established by Haryana Tourism to commemorate the spring harvest in the foothills region of the Shivaliks.', 'Celebrates the ripening of winter crops and historical New Year traditions.', 'To provide a vibrant cultural weekend for families across Haryana, Punjab, and Chandigarh.', 'Brings together rural folk artists and contemporary urban tourists in an idyllic heritage garden setting.', 'Celebrates agricultural prosperity and folk sportsmanship across border districts.', ARRAY['Folk dance competitions between student and professional troupes', 'Traditional wrestling (Dangal) and rural sports exhibitions', 'Artisan crafts bazaar and regional food festival']::TEXT[], 'Visitors flock to the shaded mango orchards, cheering during folk dance performances, enjoying camel rides, and relishing festive foods.', ARRAY['Makki Di Roti with Sarson Saag', 'Jalebi with Rabri', 'Chhole Bhature', 'Lassi']::TEXT[], 'Bright yellow, orange, and green festive attire with colorful turbans and dupattas.', 'Energetic Haryanvi Dhamal dance, high-tempo Bhangra, and Giddha competitions.', 'Yellow marigold floral gates, decorated brass milk churners, and tractor exhibits.', '2 Days', 'Solar / Harvest', 'Celebrated around April 13 and 14 annually.', 'April', 'FIXED', 'Held around April 13-14.', '2026-04-13', '2027-04-13', 'Haryana Tourism Corporation', ARRAY['Haryana']::TEXT[], ARRAY['Pinjore', 'Panchkula']::TEXT[], ARRAY['Yadavindra Gardens Pinjore']::TEXT[], 'Afternoon between 12 PM and 5 PM for dance competitions', 2, 'Infectious joyful spring energy, lively drum rhythms echoing off Mughal walls, and authentic north Indian food aromas.', '20 km from Chandigarh on the Kalka-Shimla highway; direct buses and taxis.', 'Hotels in Pinjore, Kalka, and Panchkula.', 'Spring sunshine can be warm; carry sunglasses and hats.', 'Keep garden lawns clean; refrain from climbing historic pavilion parapets.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gugga-naumi-haryana', 'Gugga Naumi Fair', ARRAY['Gugga Jaharpir Festival']::TEXT[], 'Tribal & Folk Traditions', 'Folk Shamanism / Syncretic Worship', 'The sacred monsoon folk festival honoring Gugga Pir (the serpent protector) with long blue-cloth standards carried by wandering balladeers.', 'Centuries-old folk tradition observed across the rural plains of Haryana and northern Rajasthan.', 'Commemorates Gugga Pir''s miraculous mastery over snakes and his heroic defense of his kingdom.', 'To seek protection for families and cattle against venomous snakebites during the monsoon season.', 'Deeply entrenched in rural agricultural psychology, blending folk animism with spiritual protection.', 'Maintains the ancient oral tradition of ''Gugga ke Bhagat'' balladeers who sing heroic sagas to the beat of bronze plates (Deru).', ARRAY['Carrying the sacred flag-standard (Chhari) of Gugga Pir through village streets', 'Offering sweet flour balls (Sewaiyan), curd, and milk at snake mounds and shrines', 'Nightlong recitation of the ballad of Gugga Pir''s miraculous life']::TEXT[], 'Villagers gather at village chaupals to listen to the Deru drummers, offering grains and coins, and taking blessings from the sacred peacock-feather fan.', ARRAY['Mithi Roti', 'Kheer', 'Sewaiyan', 'Halwa prasad']::TEXT[], 'Traditional white Haryanvi dhotis and kurtas, yellow turbans, and red dupattas.', 'Hypnotic singing of the epic saga of Gugga accompanied by the Deru (small hourglass drum) and bronze plate (Kansi).', 'Sacred decorated iron-topped staff (Chhari) wrapped in blue cloth with peacock feathers.', '1 Day', 'Hindu Lunisolar', 'Navami (9th day) of Krishna Paksha in Bhadrapada month', 'September', 'LUNISOLAR', 'Celebrated on Bhadrapada Krishna Navami (the day after Janmashtami).', '2026-09-05', '2027-08-26', 'Local Gram Panchayats & Haryana Cultural Board', ARRAY['Haryana']::TEXT[], ARRAY['Hisar', 'Bhiwani', 'Sirsa', 'Jind', 'Rohtak']::TEXT[], ARRAY['Village Gugga shrines and chaupals across Haryana']::TEXT[], 'Morning Chhari procession and nightlong ballad recitals', 1, 'Authentic, unvarnished rural folk devotion that transports travelers into medieval agrarian folklore and shamanic music.', 'Accessible in any village across western and central Haryana via local buses.', 'Stay in district headquarters like Hisar or Rohtak.', 'Rural settings; modest accommodations and simple village facilities.', 'Do not disrespect the sacred Chhari or deride folk beliefs; accept prasad respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hisar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kartik-cultural-festival', 'Kartik Cultural Festival Ballabgarh', ARRAY['Raja Nahar Singh Palace Festival']::TEXT[], 'Historical & Royal', 'Secular / Historic Rajput-Jat Heritage', 'A magnificent heritage festival celebrated inside the illuminated 18th-century palace of the martyr Raja Nahar Singh at Ballabgarh.', 'Instituted in 1996 by Haryana Tourism to honor Raja Nahar Singh, heroic ruler of Ballabgarh who was martyred in the 1857 First War of Independence.', 'Celebrates India''s struggle for freedom, martial valor, and the exquisite Shekhawati and Mughal-style palace architecture.', 'To promote heritage tourism in Faridabad district and provide a prestigious royal platform for classical performing arts.', 'Preserves the memory of the heroic 1857 revolutionary king whose palace was restored into a heritage tourist complex.', 'Features performances by Sangeet Natak Akademi and Padma awardee artists against illuminated arched pavilions.', ARRAY['Lighting of hundreds of traditional oil lamps across palace courtyards', 'Classical music and dance recitals on the central palace stage', 'Heritage exhibitions displaying 1857 revolutionary memorabilia and historic weaponry']::TEXT[], 'Visitors wander through intricately carved stone jalis, painted archways, and courtyards while enjoying world-class classical music and dances.', ARRAY['Royal Rajputana delicacies', 'Kheer', 'Dal Baati Churma', 'Kachori with spicy mint chutney']::TEXT[], 'Traditional formal wear: bandhgalas, kurtas with embroidered waistcoats, and festive silk sarees.', 'Classical Kathak, Odissi, and Bharatanatyam dance dramas, Sarangi solos, and soulful Qawwalis.', 'Carved sandstone arches of Nahar Singh Mahal, oil diyas, and historical cannons.', '3 Days', 'Hindu Lunisolar / Autumn', 'Celebrated during the bright fortnight (Shukla Paksha) of Kartik month.', 'November', 'LUNISOLAR', 'Held during Kartik month (usually mid-November).', '2026-11-14', '2027-11-04', 'Haryana Tourism Corporation', ARRAY['Haryana']::TEXT[], ARRAY['Ballabgarh', 'Faridabad', 'Delhi NCR']::TEXT[], ARRAY['Raja Nahar Singh Palace Ballabgarh']::TEXT[], 'Evenings from 6 PM to 10 PM when palace illuminations and classical concerts commence', 2, 'Enchanting royal heritage ambiance just outside Delhi, with exquisite acoustic concerts inside a historic fortress palace.', 'Easily accessible via Delhi Metro Violet Line (Raja Nahar Singh Metro Station); 35 km from central Delhi.', 'Rooms available within Raja Nahar Singh Palace heritage hotel, or nearby Faridabad/Delhi hotels.', 'Limited courtyard seating; arrive 30 minutes before concerts begin.', 'Respect the historic palace frescoes; photography allowed without flash.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haryanatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kapal-mochan-mela', 'Kapal Mochan Mela Yamunanagar', ARRAY['Gopal Mochan Mahatirth']::TEXT[], 'Spiritual & Temple', 'Hinduism & Sikhism', 'A historic pilgrimage fair celebrated on the banks of three sacred ponds where Lord Shiva and Guru Nanak Dev Ji bathed to wash away sins.', 'Ancient pilgrimage mentioned in Mahabharata and Puranas, sanctified by visits of Lord Shiva, Lord Rama, Guru Nanak Dev Ji, and Guru Gobind Singh Ji.', 'Celebrates the cleansing of sins (Kapal Mochan literally means liberation from the skull).', 'To take holy cleansing dips in Kapal Mochan, Rin Mochan, and Suraj Kund sarovars on the sacred full moon night.', 'Profound symbol of syncretic spiritual heritage where millions of Hindu and Sikh pilgrims bathe together in shared reverence.', 'Guru Gobind Singh Ji stayed here for 52 days after the Battle of Bhangani in 1688 and rewarded his warriors with robes of honor.', ARRAY['Midnight holy dips in Kapal Mochan, Rin Mochan, and Suraj Kund sarovars', 'Grand Akhand Path and Kirtan at Gurdwara Kapal Mochan Sahib', 'Deepdaan floating of thousands of clay lamps on sarovar waters at dusk']::TEXT[], 'Nearly one million pilgrims camp across vast tented fields, cooking community meals, chanting hymns, and bathing at dawn and dusk.', ARRAY['Langar Dal and Roti', 'Puri with Chana and Halwa', 'Jalebi', 'Sweet rice']::TEXT[], 'Simple traditional dhotis, kurtas, Sikh turbans, and rural shawls.', 'continuous Gurbani Kirtan, Vedic hymn chanting, and rustic folk bhajan singing.', 'Three sacred rectangular sarovars, Gurdwara dome, and thousands of glowing leaf lamps.', '5 Days', 'Hindu Lunisolar', 'Culminates on Kartik Purnima (full moon night of Kartik month)', 'November', 'LUNISOLAR', 'Kartik Purnima full moon.', '2026-11-24', '2027-11-13', 'Kapal Mochan Shrine Board & Yamunanagar District Administration', ARRAY['Haryana']::TEXT[], ARRAY['Bilaspur', 'Yamunanagar']::TEXT[], ARRAY['Kapal Mochan Tirth Sarovars', 'Gurdwara Kapal Mochan Sahib']::TEXT[], 'Kartik Purnima eve and dawn for the sacred holy bath and Deepdaan', 2, 'Massive, spiritually charged rural pilgrimage with endless expanses of pilgrims, echoing conch shells, and shimmering water reflections.', '20 km from Yamunanagar Railway Station; special shuttle buses operate during the mela.', 'Mass pilgrim dharamshalas, large tented townships, and hotels in Yamunanagar city.', 'Immense rural crowds (up to 800,000); stay in designated camping zones and follow police traffic diversions.', 'Maintain sanctity around all three sacred sarovars; follow separate bathing ghat areas for men and women.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://yamunanagar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-qutub-festival', 'Qutub Festival Mehrauli', ARRAY['Qutb Cultural Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Classical Music & Heritage', 'A mesmerizing three-day celebration of classical Indian music and dance staged against the dramatic, floodlit 73-meter minaret of Qutub Minar.', 'Initiated in the 1990s by Delhi Tourism and the Government of NCT of Delhi inside the UNESCO World Heritage Qutb Complex.', 'Celebrates the synthesis of Delhi''s 1,000-year-old architectural heritage with classical performing arts.', 'To revive cultural life around historic monuments and present world-renowned musicians in an evocative heritage setting.', 'Showcases the living continuity of Hindustani classical ragas, Sufiana music, and classical dance in the heart of medieval Mehrauli.', 'One of Delhi''s most prestigious cultural events, attended by diplomats, scholars, artists, and music lovers.', ARRAY['Grand open-air performances by living legends of Indian classical dance and music', 'Mesmerizing floodlighting of the 12th-century Qutub Minar minaret', 'Regional food court featuring authentic Old Delhi and royal Awadhi delicacies']::TEXT[], 'Audiences sit in the cool autumn open air, enraptured as classical dancers perform intricate footwork beneath the glowing red sandstone tower.', ARRAY['Nihari with Khamiri Roti', 'Galouti Kebabs', 'Biryani', 'Kulfi Falooda', 'Daulat Ki Chaat']::TEXT[], 'Refined formal winter wear: pashmina shawls, bandhgalas, silk kurtas, and traditional handloom sarees.', 'Classical Kathak, Odissi, Bharatanatyam, Kuchipudi, Sarod, Sitar, and soaring Sufi Qawwalis.', 'Towering 73-meter Qutub Minar illuminated in golden lights, intricate stone calligraphy, and Iron Pillar silhouette.', '3 Days', 'Gregorian / Autumn', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Announced annually by Delhi Tourism (usually late November).', '2026-11-20', '2027-11-19', 'Delhi Tourism and Transportation Development Corporation (DTTDC)', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi', 'Mehrauli']::TEXT[], ARRAY['Qutub Minar Complex Mehrauli']::TEXT[], 'Evenings between 6:30 PM and 10 PM during concert hours', 2, 'Unforgettable, ethereal aesthetic experience with ancient sandstone arches bathed in golden lights and timeless classical ragas floating in the night air.', 'Directly accessible via Delhi Metro Yellow Line (Qutab Minar Metro Station); ample auto-rickshaws and cabs.', 'Abundant luxury and heritage boutique hotels across South Delhi and Mehrauli.', 'Chilly November evenings; carry a warm shawl or jacket; seating is on first-come, first-served basis.', 'Entry requires valid photo ID; maintain quiet decorum during classical recitals; no tripods inside audience area.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://delhitourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-phool-walon-ki-sair', 'Phool Walon Ki Sair Mehrauli', ARRAY['Sair-e-Gul Faroshan']::TEXT[], 'Historical & Royal', 'Syncretic Hindu-Muslim Cultural Heritage', 'The historic 200-year-old syncretic festival of flowers where floral fans (Pankhas) are offered at both a Hindu temple and a Sufi shrine in Mehrauli.', 'Started in 1812 by Mughal Empress Mumtaz Mahal Begum (wife of Akbar Shah II) after the safe return of her son Prince Jahangir from British exile.', 'Celebrates communal brotherhood, harmony, and gratitude across religious divides.', 'To honor Delhi''s composite Ganga-Jamuni Tehzeeb (syncretic culture) through shared floral offerings.', 'Revived in 1962 by Prime Minister Jawaharlal Nehru as a vital symbol of national secular integration.', 'Living testament to the syncretic court culture of the late Mughal era in Mehrauli.', ARRAY['Procession of shehnai players carrying grand floral fans (Phoolon ka Pankha)', 'Offering of floral chadar and pankha at Dargah of Khwaja Qutbuddin Bakhtiyar Kaki', 'Offering of floral pankha at ancient Yogmaya Temple']::TEXT[], 'Hindus and Muslims march together carrying giant embroidered floral fans, participating in kite flying, wrestling, and Shehnai concerts.', ARRAY['Bedmi Poori with Aloo Sabzi', 'Nagori Halwa', 'Mehrauli Sweet Samosas', 'Biryani']::TEXT[], 'Traditional festive attire: Chikankari kurtas, Nehru jackets, sherwanis, and colorful dupattas.', 'Soulful Shehnai recitals, Qawwali sessions at the Dargah, and traditional Kathak dances at Jahaz Mahal.', 'Colossal floral fans (Pankhas) woven with fresh marigolds and roses, historic Jahaz Mahal, and Shamsi Talab.', '7 Days', 'Gregorian / Autumn', 'Held in October / November annually.', 'October - November', 'ORGANIZER_ANNOUNCED', 'Organized annually by Anjuman Sair-e-Gul Faroshan.', '2026-10-22', '2027-10-14', 'Anjuman Sair-e-Gul Faroshan & Delhi Tourism', ARRAY['Delhi']::TEXT[], ARRAY['Mehrauli', 'New Delhi']::TEXT[], ARRAY['Yogmaya Temple', 'Dargah Qutbuddin Bakhtiyar Kaki', 'Jahaz Mahal']::TEXT[], 'Day of the grand floral pankha procession between Yogmaya Temple and Bakhtiyar Kaki Dargah', 2, 'Profound, heartwarming immersion into Old Delhi''s historic syncretic soul, filled with rose petal fragrances, Shehnai notes, and communal warmth.', 'Easily accessible via Qutab Minar Metro Station on Yellow Line; cycle-rickshaws navigate narrow Mehrauli lanes.', 'Hotels across South Delhi, Saket, and Mehrauli.', 'Narrow historic lanes in Mehrauli village; walk on foot and stay close to the procession.', 'Cover head respectfully at both the Yogmaya Temple and Bakhtiyar Kaki Dargah; remove footwear outside sanctums.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://delhitourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-delhi-arts-festival', 'Delhi International Arts Festival', ARRAY['DIAF Delhi']::TEXT[], 'Art & Cultural Festival', 'Secular / Multidisciplinary Arts', 'India''s largest signature festival of the arts, showcasing over 2,000 artists and performers from 30+ countries across multiple iconic Delhi venues.', 'Established in 2007 by renowned classical dancer Pratibha Prahlad and the Prasiddha Foundation in partnership with the Ministry of Culture.', 'Celebrates global cultural exchange, multidisciplinary arts, and Delhi''s status as a world cultural capital.', 'To democratize high-quality arts by staging free public performances in heritage gardens, universities, and auditoriums.', 'Has welcomed cultural troupes from over 50 countries, building strong diplomatic and creative ties.', 'Encompasses classical dance, theatre, jazz, fusion music, visual arts, poetry, and culinary arts over three weeks.', ARRAY['Grand multi-nation opening gala at India Gate or Purana Qila', 'Daily concerts and theatre plays across Siri Fort, Kamani, and India Habitat Centre', 'Heritage park musical performances at Nehru Park and Central Park']::TEXT[], 'Culture lovers criss-cross the capital attending ballet recitals, world jazz concerts, Flamenco dances, and contemporary photography exhibitions.', ARRAY['Dilli Chaat', 'Contemporary Indian fusion cuisine', 'Filter Coffee', 'Mughlai rolls']::TEXT[], 'Smart casuals, artsy handloom stoles, and contemporary cosmopolitan wear.', 'International symphonies, world jazz, Flamenco, African drumming, alongside classical Bharatanatyam, Kathakali, and Carnatic music.', 'India Gate silhouette, open-air amphitheatre lights, and international national flags.', '15 to 21 Days', 'Gregorian / Winter', 'Held in December / January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Announced annually by Prasiddha Foundation & Ministry of Culture.', '2026-12-01', '2027-12-01', 'Prasiddha Foundation & Ministry of Culture', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi']::TEXT[], ARRAY['India Habitat Centre', 'Kamani Auditorium', 'Siri Fort', 'Central Park Connaught Place']::TEXT[], 'Evening 6 PM to 9 PM at flagship auditorium and open-air park performances', 3, 'Vibrant, cosmopolitan intellectual energy celebrating the world''s finest artistic expressions in the pleasant Delhi winter sunshine.', 'Delhi Metro connects all major festival venues across Central and South Delhi.', 'Extensive range of business and luxury hotels across central New Delhi.', 'Certain high-demand auditorium shows require advance online registration or passes.', 'Arrive 15 minutes before hall doors close; switch mobile phones to silent mode.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://diaf.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dastkar-nature-bazaar', 'Dastkar Nature Bazaar Kisan Haat', ARRAY['Dastkar Crafts Mela']::TEXT[], 'Fair & Mela', 'Secular / Artisan Empowerment', 'Delhi''s beloved craft and textile festival held at Andheria Modh, featuring over 150 authentic craft groups, organic farmers, and regional food stalls.', 'Founded in 1981 by Laila Tyabji and Dastkar Society to provide direct market platforms for traditional rural craftspersons.', 'Celebrates handmade artisanal excellence, natural dyeing, indigenous weaves, and rural economic empowerment.', 'To connect urban consumers directly with grassroots tribal and rural artisans without intermediaries.', 'Transformed India''s perception of traditional handicrafts, helping sustain over 100,000 artisan families across India.', 'Regular seasonal editions (Grand Nature Bazaar, Winter Mela, Basant Mela) define Delhi''s ethical shopping calendar.', ARRAY['Live craft demonstrations of pottery, block printing, metal casting, and basketry', 'Workshops in natural tie-dye and folk embroidery for children and adults', 'Regional folk dance performances on the central open-air stone stage']::TEXT[], 'Shoppers browse beneath colorful canopy umbrellas, admiring handwoven sarees, brass sculptures, organic spices, and hand-embroidered quilts.', ARRAY['Rajasthani Pyaaz Kachori', 'Tibetan Momos', 'South Indian Dosa', 'Desi Masala Chai', 'Fresh sugarcane juice']::TEXT[], 'Handloom cotton kurtas, block-printed tunics, Kolhapuri chappals, and silver tribal jewelry.', 'Rajasthani Kalbelia dances, Baul singer performances, and puppet shows.', 'Colorful cloth bunting, terracotta pots, wicker baskets, and hand-painted folk umbrellas.', '12 Days', 'Seasonal / Autumn-Winter', 'Multiple seasonal editions; flagship Grand Bazaar in November.', 'November', 'ORGANIZER_ANNOUNCED', 'Flagship Winter edition held mid-November.', '2026-11-12', '2027-11-11', 'Dastkar Society for Crafts and Craftspeople', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi', 'Chhatarpur']::TEXT[], ARRAY['Nature Bazaar Kisan Haat Andheria Modh']::TEXT[], 'Daytime from 11:30 AM to 5 PM for relaxed shopping and craft demonstrations', 1, 'Lively, tasteful open-air artisan village atmosphere filled with creative colors, warm conversation with master artisans, and authentic food.', '500 meters from Chhatarpur Metro Station on Yellow Line; easily accessible by auto or cab.', 'Abundant hotels across South Delhi, Vasant Kunj, and Saket.', 'Weekend afternoons see steady footfall; digital payments widely accepted by all artisan stalls.', 'Appreciate the immense labor behind handmade crafts; avoid harsh haggling with genuine artisans.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://dastkar.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jahan-e-khusrau', 'Jahan-e-Khusrau World Sufi Festival', ARRAY['World Sufi Music Festival Delhi']::TEXT[], 'Art & Cultural Festival', 'Sufism / Mystic Poetry & Music', 'The world''s premier Sufi music festival founded by filmmaker and painter Muzaffar Ali, held in the moonlit gardens of Arab Ki Serai near Humayun''s Tomb.', 'Conceived in 2001 by Muzaffar Ali under the Rumi Foundation to celebrate the 13th-century mystic poet Hazrat Amir Khusrau.', 'Celebrates divine love, universal spiritual oneness, and the sublime traditions of Sufi poetry and music.', 'To build bridges of global peace and harmony through the ecstatic poetry of Rumi, Amir Khusrau, and Baba Bulleh Shah.', 'Considered the gold standard of Sufi musical presentation, featuring legendary vocalists from India, Pakistan, Iran, and Turkey.', 'Set against the 16th-century arched gateway of Arab Ki Serai, creating an unforgettable architectural and acoustic marvel.', ARRAY['Whirling Dervishes performance from Konya, Turkey', 'Ecstatic Qawwali sessions by master Qawwals of the Chishtia order', 'Soul-stirring renditions of Hazrat Amir Khusrau''s Hindavi poetry and ghazals']::TEXT[], 'Audiences sit transfixed under starry night skies as incense smoke drifts around floodlit Mughal arches and divine music fills the air.', ARRAY['Mughlai Biryani', 'Galouti Kebabs', 'Roghni Roti', 'Shahi Kheer']::TEXT[], 'Elegant winter formal attire: black sherwanis, embroidered Pashmina shawls, and rich silk sarees.', 'World Sufi music, Persian spiritual chants, Turkish Ney flute melodies, and high-energy Chishtia Qawwali.', 'Illuminated stone arches of Arab Ki Serai, flickering earthen torches, and whirling white Sufi robes.', '3 Days', 'Gregorian / Spring', 'Held in March annually.', 'March', 'FIXED', 'Held annually over a March weekend.', '2026-03-06', '2027-03-12', 'Rumi Foundation & Delhi Tourism', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi', 'Nizamuddin']::TEXT[], ARRAY['Arab Ki Serai Humayun''s Tomb Complex']::TEXT[], 'Evenings between 7 PM and 10 PM under the moonlit sky', 2, 'Transcendental spiritual ecstasy, mesmerizing visual aesthetics, and deeply moving poetic melodies in a historic medieval garden setting.', 'Accessible via JLN Stadium Metro Station on Violet Line; auto-rickshaws and cabs to Mathura Road gate.', 'Boutique and luxury hotels in Central and South Delhi.', 'Chilly March evenings; carry warm layers; high-demand event with ticketed donor passes.', 'Maintain solemn silence during spiritual vocal performances; no flash photography.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://delhitourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-urdu-heritage-festival', 'Urdu Heritage Festival Red Fort', ARRAY['Jashn-e-Urdu']::TEXT[], 'Art & Cultural Festival', 'Urdu Literature & Ganga-Jamuni Tehzeeb', 'A grand four-day celebration of Urdu language, poetry, calligraphy, ghazals, and Dastangoi storytelling held against historic Red Fort ramparts.', 'Organized annually by the Urdu Academy and Department of Art, Culture and Languages, Government of NCT of Delhi.', 'Celebrates the rich linguistic, poetic, and cultural heritage of Urdu as a quintessential language of Delhi''s composite culture.', 'To promote Urdu literature, encourage youth engagement with poetry, and celebrate master poets (Mir, Ghalib, Zauq, Faiz).', 'Revives the historic tradition of royal mushairas (poetic symposiums) that once flourished in the Mughal Red Fort.', 'Features legendary Ghazal singers, Dastangoi storytellers, calligraphers, and Urdu book publishers.', ARRAY['Grand All India Mushaira featuring renowned Urdu poets from across the country', 'Dastangoi performances of medieval epics (Dastan-e-Amir Hamza)', 'Ghazal nights, Qawwalis, and Urdu calligraphy exhibitions']::TEXT[], 'Thousands of poetry enthusiasts listen through late night hours, cheering with heartfelt ''Wah Wah'' and ''Mukarrar'' as poets deliver couplets.', ARRAY['Purani Dilli Mutton Korma', 'Biryani', 'Shahi Tukda', 'Kulfi', 'Sheermal']::TEXT[], 'Traditional Lucknowi and Delhite attire: fine Chikankari kurtas, pyjamas, Nehru waistcoats, and sherwanis.', 'Classical Ghazal singing, soulful Qawwali, Dastangoi oral storytelling, and poetic Mushaira recitations.', 'Calligraphic Urdu scrolls, portrait gallery of Mirza Ghalib, and red sandstone arches of Central Park / Red Fort.', '4 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Urdu Academy Delhi.', '2026-02-20', '2027-02-19', 'Urdu Academy Delhi & Government of NCT of Delhi', ARRAY['Delhi']::TEXT[], ARRAY['Old Delhi', 'New Delhi']::TEXT[], ARRAY['Red Fort Ground / Central Park Connaught Place']::TEXT[], 'Evenings from 6 PM to 11 PM for Mushairas and Ghazal concerts', 2, 'Lyrical intellectual delight, deep appreciation of poetic nuance, and the unmatched warmth of Delhi''s literary soul.', 'Easily accessible via Lal Quila or Chandni Chowk Metro Station on Yellow and Violet Lines.', 'Hotels in Central Delhi and Old Delhi heritage properties.', 'Late night events; dress warmly in winter coats or shawls.', 'Follow Mushaira etiquette: listen carefully to couplets and applaud respectfully at the concluding rhyme.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://urduacademydelhi.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dilli-haat-baisakhi', 'Dilli Haat Baisakhi and Crafts Mela', ARRAY['Dilli Haat Spring Festival']::TEXT[], 'Harvest & Agriculture', 'Secular / Rural Crafts & Food', 'A joyful spring harvest festival held at Delhi''s flagship craft village Dilli Haat INA, featuring folk dances, artisan stalls, and rural foods.', 'Inaugurated in 1994 by Delhi Tourism and Ministry of Textiles to provide a permanent rotating craft marketplace in the heart of the capital.', 'Celebrates the arrival of spring, Punjabi and North Indian harvest traditions, and indigenous artisan entrepreneurship.', 'To showcase the cultural and gastronomic diversity of all 28 Indian states in a lively open-air market.', 'Pioneering model of craft tourism in India, replicated nationwide for sustainable artisan livelihoods.', 'The Baisakhi edition brings vibrant Punjabi harvest dance troupes, folk percussionists, and regional harvest delicacies.', ARRAY['Bhangra and Giddha live performances in the central open-air amphitheatre', 'Regional artisan stalls showcasing handlooms, pottery, and brass metalwork', 'Multi-state food stalls serving freshly cooked authentic regional specialties']::TEXT[], 'Crowds wander through red-brick courtyards draped in yellow marigold garlands, relishing street food and watching high-energy folk dances.', ARRAY['Amritsari Naan Chhole', 'Rajasthani Pyaaz Kachori', 'Maharashtrian Vada Pav', 'Bengali Fish Fry', 'Lassi']::TEXT[], 'Casual chic, colorful summer kurtas, and traditional ethnic dupattas.', 'Live Dhol drumming, high-energy Bhangra routines, and regional folk fusion concerts.', 'Brick village pathways, thatched stall roofs, marigold torans, and clay pottery displays.', '3 Days', 'Solar / Harvest', 'Held around April 13-15 annually.', 'April', 'FIXED', 'Held mid-April around Baisakhi day.', '2026-04-13', '2027-04-13', 'Delhi Tourism (DTTDC)', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi', 'INA']::TEXT[], ARRAY['Dilli Haat INA New Delhi']::TEXT[], 'Late afternoon from 3 PM to 8 PM for live performances and street food', 1, 'Vibrant, bustling cross-cultural fair with colors, sounds, and flavors from every corner of India packed into one accessible village.', 'Directly outside Dilli Haat INA Metro Station (Interchange between Yellow and Pink Lines).', 'Central and South Delhi hotels within easy metro commute.', 'Pleasant but warm daytime; visit in late afternoon when temperatures cool down.', 'Nominal entry ticket fee; keep ticket safe for exit.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://delhitourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-garden-tourism-festival', 'Garden Tourism Festival', ARRAY['Garden of Five Senses Floral Fest']::TEXT[], 'Seasonal & Nature', 'Secular / Botanical & Landscape Heritage', 'Delhi''s grandest three-day horticultural festival featuring millions of exotic flowering plants, bonsai exhibits, and landscape artistry.', 'Initiated in 2003 by Delhi Tourism at the sprawling 20-acre Garden of Five Senses in Said-ul-Ajaib.', 'Celebrates the glorious spring blooming season of Delhi''s public and private gardens.', 'To raise environmental consciousness, promote landscape horticulture, and offer citizens a rejuvenating retreat in nature.', 'Transforms the dramatic rocky parklands designed by Pradeep Sachdeva into a dazzling sea of botanical colors.', 'Features competitive exhibits from Rashtrapati Bhavan gardens, CPWD, Indian Railways, and international embassies.', ARRAY['Grand competitive display of over 500 varieties of seasonal flowers in pots and beds', 'Bonsai, topiary, cactus, and medicinal plant exhibitions', 'Evening classical music and indie fusion concerts in the amphitheatre']::TEXT[], 'Thousands of families stroll among winding stone pathways, fragrant herb gardens, and bamboo courts, taking photos and enjoying food stalls.', ARRAY['Spring rolls', 'Chhole Bhature', 'South Indian snacks', 'Kulfi', 'Cold Coffee']::TEXT[], 'Light spring casuals, sun hats, floral dresses, and comfortable walking shoes.', 'Live instrumental music: flute, Santoor, sitar recitals, and light classical fusion concerts.', 'Carved stone elephant sculptures, spiraling floral towers, and blooming petunia carpets.', '3 Days', 'Gregorian / Spring', 'Third weekend of February annually.', 'February', 'FIXED', 'Third Friday to Sunday of February.', '2026-02-20', '2027-02-19', 'Delhi Tourism (DTTDC)', ARRAY['Delhi']::TEXT[], ARRAY['New Delhi', 'Said-ul-Ajaib']::TEXT[], ARRAY['Garden of Five Senses Saket']::TEXT[], 'Mid-morning for flower photography and late afternoon for amphitheatre concerts', 2, 'Peaceful, fragrant botanical sanctuary with artistic rocky vistas, lush floral beds, and soothing live flute melodies.', '1 km from Saket Metro Station on Yellow Line; auto-rickshaws available from station exit.', 'Hotels across Saket, Mehrauli, and South Delhi.', 'Gentle slopes and walking trails; comfortable walking footwear recommended.', 'Do not step into flowerbeds or touch delicate bonsai exhibits; keep the natural park pristine.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://delhitourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-haridwar-kumbh-mela', 'Haridwar Kumbh Mela & Ardh Kumbh', ARRAY['Haridwar Maha Kumbh']::TEXT[], 'Spiritual & Temple', 'Hinduism (Puranic Sacred Confluence)', 'The world''s largest gathering of humanity on the banks of holy river Ganga at Haridwar where drops of the nectar of immortality (Amrit) fell.', 'Mentioned in ancient Puranas, the Mahabharata, and documented by Chinese traveler Xuanzang in the 7th century CE.', 'Celebrates the celestial churning of the ocean (Samudra Manthan) when drops of divine nectar fell at Haridwar, Prayagraj, Ujjain, and Nashik.', 'To take the holy Shahi Snan (royal bath) in the Ganga to wash away lifetimes of karmic impurities and attain liberation (Moksha).', 'Inscribed on UNESCO''s Representative List of Intangible Cultural Heritage of Humanity.', 'Brings together millions of pilgrims, ascetics of thirteen ancient Akharas, Naga sadhus, and seekers from every corner of the earth.', ARRAY['Grand Shahi Snan royal bathing processions of Naga sadhus and Akhara mahants', 'Evening Ganga Aarti at Har Ki Pauri with tens of thousands of floating brass lamps', 'Spiritual discourses (Satsangs), Vedic yagnas, and Annakshetra langars']::TEXT[], 'Har Ki Pauri transforms into an awe-inspiring sea of faith, with millions chanting ''Har Har Gange'' as sacred water splashes under starry skies.', ARRAY['Puri Aloo with Methi Chutney', 'Jalebi', 'Rabri', 'Kachori', 'Mahaprasad Langar']::TEXT[], 'Saffron and white dhotis, ascetic robes, Rudraksha malas, and modest Indian pilgrim wear.', 'Thunderous conch shell blasts, brass bells, chanting of Vedic mantras, and devotional bhajans.', 'Har Ki Pauri clock tower, Brahma Kund swirling waters, Akhara silver maces, and blazing brass aarti lamps.', '1 to 3 Months', 'Astrological Lunisolar', 'Jupiter in Aquarius (Kumbha) and Sun in Aries (Mesha)', 'January - April', 'LUNISOLAR', 'Determined by precise planetary alignments of Jupiter and the Sun.', '2026-03-14', '2027-03-30', 'Haridwar Kumbh Mela Administration & Akhil Bharatiya Akhara Parishad', ARRAY['Uttarakhand']::TEXT[], ARRAY['Haridwar', 'Rishikesh']::TEXT[], ARRAY['Har Ki Pauri Brahma Kund', 'Subhash Ghat', 'Bairagi Camp']::TEXT[], 'Dawn of designated Shahi Snan bathing dates and evening Ganga Aarti', 3, 'Life-altering spiritual spectacle of boundless devotion, ancient ascetic lineages, echoing conch shells, and the luminous celestial river Ganga.', 'Well connected by Haridwar Junction railway station and NH-334; Dehradun Jolly Grant Airport is 35 km away.', 'Extensive ashrams, dharamshalas, and hotels; book 6-12 months in advance during full Kumbh years.', 'Monumental crowds; follow police crowd routing strictly; use designated footbridges and avoid stampede-prone choke points.', 'Remove footwear before stepping onto Har Ki Pauri ghats; strictly no soap or plastic in the sacred Ganga.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haridwar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nanda-devi-raj-jat', 'Nanda Devi Raj Jat Yatra Chamoli', ARRAY['Himalayan Mahakumbh Yatra']::TEXT[], 'Tribal & Folk Traditions', 'Hinduism (Folk Shaktism & Himalayan Ecology)', 'The legendary 280-kilometer high-altitude walking pilgrimage conducted once every 12 years, escorting Goddess Nanda Devi to her celestial abode in Mount Trishul.', 'Documented since the 9th century under the royal patronage of the Chand and Panwar dynasties of Garhwal and Kumaon.', 'Re-enacts the emotional journey of Goddess Nanda Devi leaving her maternal home to join her divine husband Lord Shiva on snowy Mount Trishul.', 'To seek the blessings of Kuldevi Nanda Devi for valley prosperity, rain, and protection from disasters.', 'One of the longest and highest walking pilgrimages in the world, traversing dangerous glaciers up to 17,500 feet.', 'Led by a miraculous four-horned ram (Chausangya Khadu) who leads the barefoot pilgrims across Himalayan ridges without guidance.', ARRAY['Bidding emotional farewell to the four-horned ram at Homkund glacier', 'Barefoot walking across alpine bugyals (meadows) carrying the golden deity palanquin (Ringal Chhatoli)', 'Silent ritual passing of the eerie Roopkund mystery lake surrounded by ancient skeletons']::TEXT[], 'Tens of thousands of pilgrims hike through high meadows with brass horns and silver umbrellas, singing poignant tearful farewell folk ballads.', ARRAY['Mandua (Finger Millet) Roti', 'Gahat (Horsegram) Dal', 'Jhangora (Barnyard Millet) Kheer', 'Dry fruits and Sattu']::TEXT[], 'Traditional woolen Pahadi Cholas, Ringal umbrellas, and coarse wool blankets for mountain bivouacs.', 'Ancient Garhwali Ransinga horn blasts, Dhol-Damau, and moving Nanda Jagar ballads.', 'Four-horned ram (Khadu), golden umbrella (Chhatoli), Roopkund glacial tarn, and towering Trishul mountain.', '22 Days', 'Astrological / 12-Year Cycle', 'Organized once every 12 years during Bhadrapada month.', 'August - September', 'LUNISOLAR', 'Occurs every 12 years in Bhadrapada month.', '2026-08-28', '2027-09-10', 'Nanda Devi Raj Jat Samiti & Uttarakhand Tourism', ARRAY['Uttarakhand']::TEXT[], ARRAY['Nauti', 'Karanprayag', 'Wan', 'Bedni Bugyal', 'Homkund']::TEXT[], ARRAY['Nauti Village', 'Bedni Bugyal', 'Roopkund', 'Homkund Glacier']::TEXT[], 'Trek through Bedni Bugyal and the sacred farewell ceremony at Homkund', 7, 'Mystical, humbling high-altitude odyssey of endurance, intense mountain faith, emerald alpine meadows, and sheer Himalayan grandeur.', 'Road access up to Wan village; onwards strictly on foot through high mountain trails.', 'Expedition tents, alpine shepherd huts, and community pilgrim shelters in high bugyals.', 'Treacherous high-altitude terrain above 14,000 feet; acute mountain sickness (AMS) risk; strict medical fitness mandatory.', 'Complete ecological sanctity: pack out all waste; respect high-altitude fragile bugyal vegetation.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chamoli.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-international-yoga-festival', 'International Yoga Festival Rishikesh', ARRAY['Rishikesh Yoga Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Spiritual Heritage / Yogic Sciences', 'The world''s foremost annual gathering of yoga masters, spiritual teachers, and seekers on the holy banks of river Ganga in the Yoga Capital of the World.', 'Initiated in 1999 by Parmarth Niketan and Uttarakhand Tourism to share India''s ancient yogic science with the global community.', 'Celebrates the ancient Vedic philosophy of Patanjali''s Ashtanga Yoga, inner harmony, and wellness.', 'To promote physical health, mental equanimity, and spiritual awakening through authentic yogic disciplines.', 'Positioned Rishikesh on the global map as the epicenter of spiritual exploration and certified yoga education.', 'Welcomes participants from over 80 nations for intensive masterclasses in Asana, Pranayama, Meditation, and Ayurveda.', ARRAY['Dawn Surya Namaskar sessions on riverbank white sand beaches', 'Masterclasses with world-renowned spiritual teachers and yoga acharyas', 'Evening Ganga Aarti and divine Kirtan concerts at Parmarth Niketan Ghat']::TEXT[], 'Seekers from every continent practice side by side in open-air tents, savoring sattvic vegetarian meals and dipping their feet in the emerald Ganga.', ARRAY['Sattvic Ayurvedic Khichdi', 'Fresh Herbal Teas', 'Sprouted Salads', 'Kheer with jaggery', 'Fresh seasonal fruits']::TEXT[], 'Comfortable white yoga apparel, loose cotton pants, and meditation shawls.', 'Soulful Kirtans, flute recitals, Vedic mantra chanting, and Indian classical fusion concerts.', 'Ganga river currents, Himalayan foothills, Parmarth Niketan Shiva statue, and brass aarti lamps.', '7 Days', 'Gregorian / Annual', 'March 1 to 7 annually.', 'March', 'FIXED', 'Held annually March 1-7.', '2026-03-01', '2027-03-01', 'Parmarth Niketan & Uttarakhand Tourism Development Board', ARRAY['Uttarakhand']::TEXT[], ARRAY['Rishikesh']::TEXT[], ARRAY['Parmarth Niketan Ashram', 'Ganga Beach Rishikesh']::TEXT[], 'Dawn yoga sessions at 6:30 AM and evening Ganga Aarti at sunset', 3, 'Deep mental rejuvenation, serene spiritual vibes, rhythmic river sounds, and inspiring global community of mindful seekers.', '30 km from Dehradun Jolly Grant Airport; auto-rickshaws and cabs widely available.', 'Ashram guest rooms at Parmarth Niketan, wellness resorts, and boutique hotels in Tapovan and Swarg Ashram.', 'Moderate crowds; register months in advance for official delegate passes and ashram rooms.', 'Maintain silence in meditation halls; strictly vegetarian, no alcohol/tobacco within the sacred ashram perimeter.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://internationalyogafestival.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ganga-dussehra-haridwar', 'Ganga Dussehra Haridwar & Rishikesh', ARRAY['Gangavataran Mahotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Ganga Reverence)', 'The sacred festival celebrating the descent of the divine river Ganga from the heavens to earth through the matted locks of Lord Shiva.', 'Mentioned in Valmiki Ramayana and Skanda Purana, marking the historic day Bhagiratha brought Ganga to redeem his ancestors.', 'Celebrates the cosmic arrival of the holy river that sustains millions across northern India.', 'To take ten holy dips in the Ganga to absolve ten specific types of sins committed across lifetimes.', 'Supreme festival of river gratitude, emphasizing ecological preservation of the sacred river system.', 'Attracts millions of devotees to the holy ghats of Haridwar, Rishikesh, and Varanasi.', ARRAY['Taking ten holy baths in the river Ganga at dawn', 'Offering ten different types of fruits, sweets, and flowers to Mother Ganga', 'Spectacular Maha Aarti at Har Ki Pauri with illuminated floating floral leaf-boats']::TEXT[], 'Devotees line the river ghats from before sunrise, offering milk and flowers, reciting Ganga Stotram, and releasing thousands of floating lamps at dusk.', ARRAY['Puri with pumpkin sabzi', 'Kheer', 'Motichoor Laddoo', 'Fresh watermelon and seasonal melons']::TEXT[], 'Traditional white and saffron cotton dhotis, kurtas, and cotton sarees.', 'Recitation of the Ganga Lahari, reverberating temple bells, conch shells, and synchronized evening aarti chanting.', 'Goddess Ganga riding her Makara crocodile, swirling green river rapids, and floating clay lamps.', '1 Day', 'Hindu Lunisolar', 'Dashami (10th day) of Shukla Paksha in Jyeshtha month', 'May - June', 'LUNISOLAR', 'Observed on Jyeshtha Shukla Dashami.', '2026-05-25', '2027-06-14', 'Haridwar Teerth Purohit Sabha & Har Ki Pauri Trust', ARRAY['Uttarakhand', 'Uttar Pradesh']::TEXT[], ARRAY['Haridwar', 'Rishikesh', 'Varanasi', 'Prayagraj']::TEXT[], ARRAY['Har Ki Pauri Haridwar', 'Triveni Ghat Rishikesh']::TEXT[], 'Dawn for sacred bathing rituals and dusk for the magnificent floating lamp aarti', 1, 'Luminous, uplifting river spirituality with thousands of glowing leaf-boats drifting down the rapid emerald currents against the foothills.', 'Easily accessible in Haridwar and Rishikesh via train, bus, and taxi.', 'Ashrams and hotels in Haridwar and Rishikesh fill rapidly; advance booking recommended.', 'Very swift river currents during summer snowmelt; bathe strictly within protective chains and railings.', 'Do not leave plastic bags, soap, or clothes in the river; release only natural biodegradable leaf lamps.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haridwar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kanwar-yatra-haridwar', 'Kanwar Yatra Haridwar', ARRAY['Shravan Kanwar Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism)', 'The colossal annual monsoon pilgrimage where over 30 million Shiva devotees (Kanwariyas) walk hundreds of kilometers barefoot carrying holy Ganga water.', 'Rooted in Puranic lore where Lord Shiva drank the deadly poison (Halahala) during Samudra Manthan and devotees carried cool Ganga water to soothe his throat.', 'Celebrates unwavering devotion, austere physical endurance, and supreme surrender to Lord Shiva.', 'To fetch sacred holy water from Har Ki Pauri and carry it back on foot to bathe Shiva Lingams on Shravan Shivratri.', 'One of the largest coordinated human peaceful pilgrimages on earth, operating with extraordinary communal logistics.', 'Demonstrates complete social equality as every devotee is addressed solely as ''Bhole'' regardless of social background.', ARRAY['Filling consecrated glass vessels with holy Ganga water at Har Ki Pauri', 'Balancing the decorated bamboo Kanwar on shoulders without ever letting it touch the ground', 'Walking barefoot hundreds of kilometers along dedicated highway corridors']::TEXT[], 'Entire national highways transform into a sea of saffron-clad pilgrims carrying colorfully decorated bamboo poles with fluttering flags and bells.', ARRAY['Simple roadside Langar meals: Dal-Roti, Khichdi, and sweet tea', 'Kheer', 'Fruit prasad']::TEXT[], 'Vibrant bright saffron t-shirts, shorts, and headbands with Shiva imagery.', 'Continuous chanting of ''Bol Bam, Bam Bam Bhole'', dholak beats, and devotional DJ tracks at roadside rest camps.', 'Ornate bamboo Kanwar shoulder pole decorated with tinsel and brass bells, Ganga water vessels, and trishul emblems.', '12 to 14 Days', 'Hindu Lunisolar / Monsoon', 'Begins on the first day of Shravana month and concludes on Shravan Shivratri.', 'July - August', 'LUNISOLAR', 'Begins with Shravana Pratipada and ends on Shravana Shivratri.', '2026-07-29', '2027-07-18', 'Uttarakhand Government & Haridwar Police Administration', ARRAY['Uttarakhand', 'Uttar Pradesh', 'Haryana', 'Delhi']::TEXT[], ARRAY['Haridwar', 'Rishikesh', 'Roorkee', 'Meerut']::TEXT[], ARRAY['Har Ki Pauri Haridwar', 'Neelkanth Mahadev Temple']::TEXT[], 'Peak days during the final 3 days before Shravan Shivratri', 3, 'Awe-inspiring wave of collective human faith, relentless stamina, saffron sea stretching to the horizon, and boundless volunteer service.', 'Dedicated pedestrian lanes on NH-334; vehicular traffic is strictly diverted during peak week.', 'Pilgrims stay in thousands of free community seva camps; commercial hotels in Haridwar require early booking.', 'Extreme physical crowd density; highway travel around Haridwar is heavily restricted for normal vehicles.', 'Show extreme patience and courtesy to walking Kanwariyas; never step over or touch a balanced Kanwar pole.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://haridwar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-butter-festival-dayara', 'Butter Festival Dayara Bugyal', ARRAY['Anduri Utsav']::TEXT[], 'Seasonal & Nature', 'Folk Agrarian & Tribal Ecology', 'A delightfully unique high-altitude Holi-like celebration played with fresh milk, butter, and buttermilk on the emerald alpine meadows of Dayara Bugyal.', 'Centuries-old festival of the Gujjar and Pahadi pastoralist communities who take their livestock to graze in high alpine bugyals during monsoon.', 'Celebrates the gratitude of pastoralists to Mother Earth and Lord Krishna for keeping livestock healthy in high pastures.', 'To thank nature for bountiful dairy yields before herds begin their autumn descent to lower valleys.', 'Unique indigenous eco-festival celebrating the harmonious coexistence of pastoralists and Himalayan alpine ecology.', 'Revived and popularized by the Dayara Paryatan Utsav Samiti to promote sustainable high-altitude eco-tourism.', ARRAY['Offering fresh milk and butter to Lord Krishna and local mountain deities', 'Playful smearing of pure white homemade butter and buttermilk on each other''s faces', 'Joyful Pahadi community circle dances on lush green alpine turf']::TEXT[], 'Villagers and trekkers smear creamy butter on cheeks, laugh under warm monsoon mountain skies, and dance in circles overlooking snowy peaks.', ARRAY['Fresh butter with Makki Roti', 'Pahadi buttermilk', 'Jhangora Kheer', 'Local mountain honey']::TEXT[], 'Traditional Garhwali woolen kurtas, Ghagra-Pichora, and colorful embroidered waistcoats.', 'Energetic Garhwali folk dances with Dhol-Damau, Ransingha horn blasts, and flute melodies.', 'Lush emerald Dayara Bugyal meadows, snow-capped Bandarpoonch peak, and wooden churners filled with fresh butter.', '1 Day', 'Solar / Bhadrapada Sankranti', 'Celebrated on Sankranti of Bhadrapada month (around August 16-17).', 'August', 'SOLAR', 'Celebrated annually on Bhadrapada Sankranti.', '2026-08-17', '2027-08-17', 'Dayara Paryatan Utsav Samiti & Uttarkashi District Administration', ARRAY['Uttarakhand']::TEXT[], ARRAY['Dayara Bugyal', 'Raithal', 'Barsu', 'Uttarkashi']::TEXT[], ARRAY['Dayara Bugyal Alpine Meadow (10,000 ft)']::TEXT[], 'Morning 10 AM to 2 PM when celebrations and butter games reach full swing', 2, 'Pure alpine joy amidst endless undulating meadows dotted with wildflowers, with majestic Himalayan peaks smiling in the background.', 'Base camp at Raithal village (40 km from Uttarkashi); followed by a scenic 7 km hike through oak forests to Dayara Bugyal.', 'Village homestays in Raithal or alpine camping in designated eco-tents on the meadow fringe.', 'Trek involves 7 km moderate uphill climb; carry rain protection and sturdy waterproof hiking boots.', 'Do not use commercial chemical butter; only pure natural dairy provided by local villagers is used; keep meadows zero-litter.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://uttarkashi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-phool-dei-uttarakhand', 'Phool Dei Spring Flower Festival', ARRAY['Phool Sankranti']::TEXT[], 'Seasonal & Nature', 'Folk Nature & Children''s Harvest', 'The delightful Himalayan spring flower festival where young children gather fresh wild mountain blossoms and place them on household doorsteps.', 'Ancient indigenous folk tradition of Garhwal and Kumaon celebrating the arrival of spring in the hills.', 'Commemorates the retreat of freezing winter and the blossoming of yellow mustard and wild Pyoli and Buransh (rhododendron) flowers.', 'To welcome the prosperity of spring and bless every village household with happiness and abundant harvest.', 'Instills profound reverence for mountain biodiversity, flora, and neighborly generosity in young children.', 'Celebrates the ancient folk song ''Phool Dei, Chhamma Dei, Daitkar, Bhokar, Tere Mathe Tek'', welcoming peace and good fortune.', ARRAY['Young children (Phulyari) hike into hills to pluck wild yellow Pyoli, Buransh, and peach blossoms', 'Placing flower petals on doorsteps (Dei) of every village home at dawn', 'Households gifting rice, jaggery, and coins to singing children']::TEXT[], 'Small children carry brass thalis piled with colorful wild blossoms, singing traditional folk couplets from door to door across mountain hamlets.', ARRAY['Sei (fried wheat flour dumplings cooked in ghee and jaggery)', 'Arsa', 'Buransh flower juice', 'Roat']::TEXT[], 'Colorful traditional Pahadi dress: bright kurtas, small waistcoats, and floral crowns.', 'Children singing traditional ''Phool Dei'' folk couplets, accompanied by Dholak rhythms.', 'Bright red rhododendron (Buransh) blooms, yellow mustard flowers, and wooden doorway lintels.', '1 to 8 Days', 'Solar / Chaitra Sankranti', 'First day of the Hindu solar month of Chaitra (mid-March).', 'March', 'SOLAR', 'Celebrated on Chaitra Sankranti (around March 14-15).', '2026-03-15', '2027-03-15', 'Uttarakhand Cultural Affairs Department', ARRAY['Uttarakhand']::TEXT[], ARRAY['Pauri', 'Tehri', 'Almora', 'Nainital', 'Chamoli']::TEXT[], ARRAY['Village doorsteps across Garhwal and Kumaon']::TEXT[], 'Early morning hours when children deliver fresh flower petals to doorsteps', 1, 'Heartwarming mountain innocence, vibrant wild rhododendrons painting forested hillsides in scarlet, and pure childhood joy.', 'Easily experienced across any village in Uttarakhand via local road transport.', 'Village homestays and heritage retreats across hill districts.', 'Pleasant spring weather; mild chill in mornings and evenings.', 'Welcome children warmly; keep small coins, jaggery, or treats ready to gift the young flower-bearers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://uttarakhandtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hill-jatra-pithoragarh', 'Hill Jatra Pithoragarh', ARRAY['Kumaiyan Folk Theatre']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Agrarian Folk Theatre', 'A vibrant traditional open-air pastoral drama celebrated in the Soar Valley of Pithoragarh, featuring masked characters portraying farming and cattle life.', 'Originated centuries ago in the pastoral traditions of the Chand kings, associated with the legendary bull-fight of Sor Valley.', 'Celebrates the planting of the paddy crop and prayers for protection of cattle from predators and diseases.', 'To honor Lord Shiva and local village protector deities and celebrate the agrarian bond between humans and oxen.', 'One of the oldest surviving traditional open-air masked folk theatrical forms in the Central Himalayas.', 'Features the dramatic appearance of ''Lakhia Bhoot'' (a fierce incarnation of Lord Shiva''s attendant) who blesses the villagers.', ARRAY['Ritual worship of the sacred oxen and plowing implements', 'Masked theatrical dance depicting farmers, deer, wild boars, and tigers', 'Grand entry and blessing of the fierce Lakhia Bhoot character dressed in green branches']::TEXT[], 'Villagers pack rooftops and stone courtyard walls, roaring with laughter during comedic farming skits and bowing in reverent awe before Lakhia Bhoot.', ARRAY['Singori (sweet wrapped in malu leaf)', 'Kumaoni Raita with ground mustard', 'Bhatia dal', 'Bhang Ki Chutney']::TEXT[], 'Traditional Kumaoni Pichora (yellow-saffron bridal veil with red dots) for women, white dhotis and waistcoats for men.', 'Rhythmic folk drumming with Hurka and Dhol, accompanied by witty improvised theatrical dialogues.', 'Wooden masks of oxen and deer, green leafy regalia of Lakhia Bhoot, and traditional wooden plows.', '1 Day', 'Hindu Lunisolar / Monsoon', 'Celebrated during the month of Bhadrapada (August - September).', 'August - September', 'LUNISOLAR', 'Held during Bhadrapada month following Rikhola / Athon.', '2026-08-25', '2027-09-12', 'Pithoragarh Cultural Committee & UK Tourism', ARRAY['Uttarakhand']::TEXT[], ARRAY['Pithoragarh']::TEXT[], ARRAY['Kumour Village', 'Bajeti', 'Pithoragarh Town']::TEXT[], 'Afternoon 2 PM to 6 PM when the open-air folk theatre unfolds', 1, 'Unfiltered rustic Himalayan folk humor, lively theatrical energy, and raw spiritual awe during the trance of Lakhia Bhoot.', 'Well connected by highway from Kathgodam (210 km) and Pantnagar Airport (240 km).', 'Hotels and government guest houses in Pithoragarh town.', 'Crowded village courtyards; find an elevated viewing spot on courtyard ledges.', 'Do not mock the actors or the sacred trance of Lakhia Bhoot; photography is welcomed.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pithoragarh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jageshwar-monsoon-festival', 'Jageshwar Monsoon Festival', ARRAY['Jageshwar Shravan Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism)', 'The sacred month-long monsoon pilgrimage held amidst towering deodar forests at the ancient cluster of 124 stone temples of Jageshwar Dham.', 'Jageshwar temple complex dates from the 7th to 12th century CE, constructed by Katyuri kings; revered as the 8th Jyotirlinga (Nagesh).', 'Celebrates the sacred monsoon month of Shravan dedicated to Lord Shiva''s contemplation.', 'To perform sacred Rudrabhishek in the sanctified stone sanctums and seek health, wisdom, and liberation.', 'Preserves one of the finest architectural ensembles of Nagara stone temples in the entire Himalayan region.', 'Adi Shankaracharya visited Jageshwar in the 8th century, re-establishing worship of the Mahamrityunjaya and Jyotirlinga shrines.', ARRAY['Performance of Mahamrityunjaya Japa and Rudrabhishek by Kumaoni purohits', 'Lighting of ghee lamps in the deodar-surrounded stone courtyard', 'Holy bath in the sacred Brahma Kund waters']::TEXT[], 'Pilgrims wrapped in shawls sit in meditation beneath ancient deodar trees, listening to continuous Vedic chanting echoing off ancient stone carvings.', ARRAY['Bal Mithai (roasted brown fudge covered in white sugar pearls)', 'Singori', 'Bhatt Ki Churkani', 'Mandua Roti']::TEXT[], 'Traditional Kumaoni Pichora, woolen shawls, and white dhotis.', 'Hypnotic Sanskrit Vedic chanting, conch shells, and gentle temple gongs.', 'Ancient 8th-century stone temple spires (Shikharas), towering deodar trees, and brass Nandi statues.', '1 Month', 'Hindu Lunisolar', 'Throughout the holy month of Shravana (July - August)', 'July - August', 'LUNISOLAR', 'Observed throughout the Hindu month of Shravana.', '2026-07-29', '2027-07-18', 'Jageshwar Temple Management Committee & Uttarakhand Tourism', ARRAY['Uttarakhand']::TEXT[], ARRAY['Jageshwar', 'Almora']::TEXT[], ARRAY['Jageshwar Dham Temple Complex']::TEXT[], 'Morning Rudrabhishek at 7 AM and peaceful evening aarti at 6:30 PM', 2, 'Deep, soul-stirring spiritual tranquility amidst ancient monolithic stone shrines enveloped in monsoon mists and towering cedar forests.', '36 km from Almora; 125 km from Kathgodam railway station; easily accessible by taxi.', 'KMVN tourist rest houses, temple dharamshalas, and eco-resorts near Jageshwar.', 'Monsoon rains can cause mountain road slips; check road conditions before driving.', 'Dress modestly covering shoulders and knees; remove shoes before entering the temple flagstone courtyard.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://almora.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jauljibi-mela', 'Jauljibi and Thal Mela Pithoragarh', ARRAY['Jauljibi International Trade Fair']::TEXT[], 'Fair & Mela', 'Secular / Trans-Himalayan Border Trade', 'A historic cross-border trade fair held at the scenic confluence of the Mahakali and Gori rivers, uniting people of India, Nepal, and Tibet.', 'Started in 1914 by the Askot royal family (Pal dynasty) as a premier trans-Himalayan trading junction.', 'Celebrates the age-old commercial and cultural kinship of border communities across the Himalayas.', 'To trade indigenous mountain products (pashmina, wool, herbs) and celebrate shared cultural bonds.', 'Unique international border fair where citizens of India and Nepal cross the suspension bridge freely without passports for trade.', 'Showcases the living heritage of the Shauka and Rung trans-Himalayan trading tribes.', ARRAY['Inaugural flag hoisting with administrative delegations of India and Nepal', 'Exhibition and sale of rare Himalayan herbs, handwoven Dan carpets, and Gorkha khukuris', 'Bilingual cultural performances by Indian Pahadi and Nepali folk artists']::TEXT[], 'Traders set up stalls along the stony riverbanks, displaying soft sheepskin jackets, rare herbs, wooden handicrafts, and enjoying river fish meals.', ARRAY['Fresh Mahakali River Fish fry', 'Tibetan Thukpa', 'Sel Roti (Nepali rice doughnut)', 'Madua Roti with Chutney']::TEXT[], 'Traditional Shauka woolen Chukla coats, Nepali Dhaka topis, and Kumaoni woolen caps.', 'Nepali folk music (Madal drum songs), Kumaoni Jhora-Chanchari group dances, and Shauka ballads.', 'Suspension bridge connecting India and Nepal, turquoise river confluence, and stacks of handwoven woolen carpets.', '7 Days', 'Gregorian / Autumn', 'November 14 to 21 annually.', 'November', 'FIXED', 'Held annually November 14-21.', '2026-11-14', '2027-11-14', 'Pithoragarh District Administration & Dharchula Sub-Division', ARRAY['Uttarakhand']::TEXT[], ARRAY['Jauljibi', 'Dharchula', 'Pithoragarh']::TEXT[], ARRAY['Confluence of Gori and Kali Rivers Jauljibi']::TEXT[], 'Daytime from 11 AM to 4 PM for vibrant riverside bazaar browsing', 2, 'Fascinating trans-Himalayan borderland energy where two nations meet on a suspension bridge over roaring turquoise mountain rivers.', '65 km from Pithoragarh along the scenic Kali river valley road; accessible by taxi.', 'Local guesthouses in Jauljibi and Dharchula; KMVN rest houses.', 'Carry valid government photo ID due to international border security checkpoints.', 'Respect border regulations; cross the Nepal suspension bridge only during officially permitted hours.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pithoragarh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dev-deepawali-varanasi', 'Dev Deepawali Varanasi', ARRAY['Tripurotsav', 'Diwali of the Gods']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism & Ganga Reverence)', 'The world-renowned visual spectacle where all 84 ghats of Varanasi are illuminated with over one million earthen lamps on the full moon night.', 'Celebrated since ancient times; according to Shiva Purana, Lord Shiva defeated the demon Tripurasura on this day, celebrated by gods lighting lamps on Ganga.', 'Commemorates the triumph of divine righteousness and the celestial descent of gods to bathe in Kashi.', 'To honor Lord Shiva, offer Deepdaan to departed ancestors, and pay tribute to Indian armed forces martyrs.', 'Pinnacle of Varanasi''s spiritual and aesthetic heritage, drawing visitors from across the globe.', 'Commences with a solemn tribute at Dashashwamedh Ghat honoring martyrs of the Indian Army, Navy, and Air Force.', ARRAY['Lighting of over one million earthen lamps (diyas) across 84 ghats simultaneously at sunset', 'Grand Maha Aarti by 21 priests with multi-tiered brass lamps at Dashashwamedh Ghat', 'Green laser and light-and-sound projections on the sandy eastern bank of the Ganga']::TEXT[], 'The entire 7-kilometer crescent of Varanasi ghats glows like a golden amphitheatre, with thousands of illuminated boats gliding over dark waters.', ARRAY['Banarasi Malaiyyo (frothy milk foam with saffron and pistachios)', 'Tamatar Chaat', 'Banarasi Paan', 'Kachori Jalebi', 'Rabri']::TEXT[], 'Traditional silk Banarasi sarees, kurtas, dhotis, and modest ethnic wear.', 'Resounding Vedic chanting, classical Shehnai recitals by exponents of Ustad Bismillah Khan, and thunderous conch shell blasts.', 'One million glowing clay diyas, Dashashwamedh Ghat multi-tiered brass lamps, and illuminated historic palace facades.', '1 Day', 'Hindu Lunisolar', 'Kartik Purnima (full moon of Kartik month)', 'November', 'LUNISOLAR', 'Celebrated on Kartik Purnima (15 days after Diwali).', '2026-11-24', '2027-11-13', 'Varanasi District Administration & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Varanasi']::TEXT[], ARRAY['Dashashwamedh Ghat', 'Assi Ghat', 'Chet Singh Ghat', 'Namo Ghat']::TEXT[], 'Sunset (5 PM to 9 PM) on Kartik Purnima night from a river cruise or heritage rooftop', 2, 'Incomparable celestial vision of an unbroken ribbon of golden fire stretching across ancient river palaces, reflecting in the sacred Ganga.', 'Boats and cruise vessels must be booked months in advance; ghats are pedestrian-only on this night.', 'Varanasi hotels and heritage havelis are fully booked 6-9 months prior; reserve very early.', 'Monumental crowds exceeding one million visitors; adhere strictly to boat capacity limits and wear life-jackets.', 'Do not leave plastic waste on the ghats; buy authentic earthen diyas from local potter stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://varanasi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ganga-mahotsav-varanasi', 'Ganga Mahotsav Varanasi', ARRAY['Varanasi Cultural Festival']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Heritage & Sacred Arts', 'A premier five-day festival of classical music, dance, and fine arts held at Rajghat, celebrating the cultural soul of the world''s oldest living city.', 'Instituted by Uttar Pradesh Tourism to showcase the rich Banaras Gharana musical heritage leading up to Dev Deepawali.', 'Celebrates the civilizational role of river Ganga in nurturing Indian classical music, literature, and arts.', 'To provide a sanctified platform for master classical musicians and promote Banaras cultural tourism.', 'Showcases the unique Banaras Gharana tradition of vocal music (Thumri, Dadra, Chaiti), tabla, and sitar.', 'Includes the thrilling international boat race along the crescent of Varanasi ghats.', ARRAY['Nightly classical music and dance concerts by living legends of Indian classical arts', 'Banaras Gharana Shehnai, Sarangi, and Tabla jugalbandis', 'Grand martial arts and wrestling demonstrations at nearby akharas']::TEXT[], 'Connoisseurs gather on riverside steps under cool November evening skies, listening to meditative classical ragas beside the sacred river.', ARRAY['Banarasi Dum Aloo', 'Litti Chokha', 'Malai Peda', 'Samosa with spicy chana']::TEXT[], 'Elegant handloom Banarasi silk sarees, kurtas with Nehru jackets, and shawls.', 'Banaras Gharana Thumri, Dadra, Kajari, classical Kathak dance, and sitar recitals.', 'Illuminated stage on Rajghat, river Ganga background, and classical musical instruments.', '5 Days', 'Hindu Lunisolar / Autumn', 'Concludes on the eve of Dev Deepawali (Kartik Purnima).', 'November', 'LUNISOLAR', 'Held during the five days preceding Kartik Purnima.', '2026-11-20', '2027-11-09', 'UP Tourism & Varanasi District Cultural Committee', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Varanasi']::TEXT[], ARRAY['Rajghat Varanasi', 'Assi Ghat']::TEXT[], 'Evenings between 6:30 PM and 10:30 PM during musical concert hours', 3, 'Sublime acoustic and spiritual bliss, experiencing world-class classical music in the spiritual capital of India.', 'Taxis, auto-rickshaws, and e-rickshaws to Rajghat.', 'Abundant hotel accommodations across Varanasi.', 'Orderly seating on ghat pavilions; arrive 30 minutes before concerts begin.', 'Maintain pin-drop silence during classical vocal and instrumental performances.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://uptourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lathmar-holi-barsana', 'Lathmar Holi Barsana', ARRAY['Barsana Holi Mahotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Braj Heritage)', 'The world-famous legendary celebration where women of Barsana playfully beat men of Nandgaon with heavy wooden sticks (lathis) amidst showers of gulal.', 'Celebrated since ancient times, re-enacting the playful mythological pastime where young Krishna from Nandgaon visited Radha''s village Barsana and was playfully chased away.', 'Celebrates the immortal, playful divine love of Radha and Krishna and the spirit of Braj devotion (Bhakti).', 'To experience the bliss of Radha Rani''s divine pastimes and celebrate the arrival of spring with joyous abandon.', 'Unique cultural tradition preserving ancient Braj folk language, music, and playful martial defense.', 'Attracts tens of thousands of international photographers, documentary filmmakers, and pilgrims every year.', ARRAY['Men of Nandgaon (Huriyare) sing provocative poetic verses teasing women of Barsana', 'Women of Barsana (Huriyarin) respond by energetically beating their leather shields with polished wooden lathis', 'Showers of natural fragrant herbal gulal, tesu flower water, and rose petals from temple rooftops']::TEXT[], 'Narrow village lanes fill with roaring crowds, clouds of magenta, yellow, and saffron powder, and the thunderous clatter of wooden sticks hitting leather shields.', ARRAY['Braj Thandai laced with dry fruits and saffron', 'Gujiya', 'Malpua', 'Kachori with potato curry']::TEXT[], 'Women wear colorful Rajasthani-Braj Lehengas with veiled faces; men wear white dhotis with turbans and carry heavy leather shields.', 'Traditional Braj folk singing of ''Rasiya'' songs, accompanied by giant Dholak drums and brass cymbals.', 'Polished wooden lathis (sticks), leather shields (Dhal), pink gulal clouds, and Ladli Ji Temple spires.', '2 Days', 'Hindu Lunisolar', 'Navami (9th day) of Shukla Paksha in Phalguna month', 'February - March', 'LUNISOLAR', 'Celebrated on Phalguna Shukla Navami (approx 5-6 days before main Holi).', '2026-02-27', '2027-03-18', 'Shri Ladli Ji Temple Trust & UP Tourism Mathura', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Barsana', 'Mathura', 'Nandgaon']::TEXT[], ARRAY['Radha Rani (Ladli Ji) Temple Barsana', 'Priya Kund', 'Rangeeli Gali Barsana']::TEXT[], 'Afternoon between 2 PM and 5:30 PM when the Lathmar duel unfolds in Rangeeli Gali', 2, 'Overwhelming sensory explosion of flying herbal colors, euphoric chanting of ''Radhe Radhe'', and unforgettable ancient folk vitality.', '50 km from Mathura; accessible by private taxi or state transport buses.', 'Accommodations in Barsana are very limited; base yourself in Mathura or Vrindavan and travel by early morning taxi.', 'Extremely intense crowds in narrow village streets; protect cameras with waterproof plastic sleeves; wear old clothes and sunglasses.', 'Do not use chemical colors; only natural herbal powders are permitted; maintain respectful distance from women performers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mathura.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-braj-ki-holi', 'Braj Ki Holi Mathura & Vrindavan', ARRAY['Mathura Vrindavan Holi']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism)', 'The epic 40-day Holi celebration across the holy pilgrimage circuits of Mathura, Vrindavan, Gokul, and Govardhan.', 'Ancient tradition commemorating Lord Krishna''s childhood and youth pastimes across the pastures and groves of Braj.', 'Celebrates divine transcendental love, spring abundance, and the destruction of the demoness Holika.', 'To immerse completely in the ecstasy of Krishna devotion and experience Holi at its original historic epicenter.', 'Encompasses multiple distinct celebrations: Phoolon Wali Holi (Banke Bihari temple), Chhadimar Holi (Gokul), Huranga (Dauji), and Widow''s Holi (Vrindavan).', 'The iconic Widows'' Holi at Pagal Baba and Gopinath temples broke centuries-old orthodox taboos, empowering marginalized women through joy.', ARRAY['Phoolon Wali Holi where hundreds of kilograms of fresh flower petals are showered on devotees at Banke Bihari temple', 'Huranga at Dauji Temple where clothes are playfully torn and dipped in color', 'Widow''s Holi where thousands of widowed ashram residents celebrate with flower petals and colors']::TEXT[], 'Temples reverberate with singing of Samaj Gayan, brass bells, and clouds of scented colors as priests shower holy water and flowers from sanctums.', ARRAY['Mawa Gujiya', 'Bikaneri Bhujia', 'Braj Kesar Thandai', 'Rabri Jalebi', 'Hing Ki Kachori']::TEXT[], 'Crisp white cotton kurtas and dhotis that transform into living canvasses of pink, green, and yellow powders.', 'Traditional Samaj Gayan temple singing with Pakhavaj and cymbals, ecstatic Rasiya folk songs.', 'Fresh marigold and rose petals, squirt-guns (Pichkaris), Dauji wooden vats, and Banke Bihari black marble idol.', '40 Days (Peak 7 Days)', 'Hindu Lunisolar', 'Begins on Vasant Panchami and peaks from Holashtak to Rangwali Holi', 'February - March', 'LUNISOLAR', 'Peak events occur during the 7 days leading to Phalguna Purnima.', '2026-03-03', '2027-03-22', 'Braj Teerth Vikas Parishad & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Mathura', 'Vrindavan', 'Gokul', 'Govardhan', 'Dauji']::TEXT[], ARRAY['Shri Krishna Janmabhoomi Mathura', 'Banke Bihari Temple Vrindavan', 'Dwarkadhish Temple', 'Dauji Temple']::TEXT[], 'Phoolon Wali Holi day at Banke Bihari Temple (Ekadashi before Holi) and Huranga at Dauji', 3, 'Transcendent spiritual ecstasy, raining flower petals, joyful tears of devotion, and complete surrender to divine playful love.', 'Easily accessible from Delhi (140 km via Yamuna Expressway); Shatabdi trains stop at Mathura Junction.', 'Extensive hotels and ashrams across Mathura and Vrindavan; book 3-4 months in advance for Holi week.', 'Extreme crowd crush inside Banke Bihari temple; avoid carrying wallets, gold jewelry, or expensive smartphones into sanctum crowds.', 'Keep eyes closed or wear protective goggles when dry colors are tossed; accept flower prasad with folded hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mathura.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ram-navami-ayodhya', 'Ram Navami Ayodhya', ARRAY['Shri Ram Janmotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism)', 'The grand celebration of the birth of Maryada Purushottam Lord Rama at his sacred birthplace in Ayodhya and the newly consecrated Shri Ram Janmabhoomi Mandir.', 'Ancient celebration documented in the Ramayana, sanctified by millennia of continuous pilgrimage to the birthplace of Lord Rama.', 'Commemorates the manifestation of Lord Vishnu as Rama on Chaitra Shukla Navami at mid-day to establish righteousness.', 'To celebrate the ideals of truth, righteousness, filial duty, and ideal governance (Ram Rajya).', 'The consecration of the monumental Shri Ram Janmabhoomi Mandir in 2024 elevated Ayodhya into one of the supreme global pilgrimage destinations.', 'Features the miraculous ''Surya Tilak'' where sunlight is optically channeled onto the forehead of Ram Lalla at exact mid-day.', ARRAY['Surya Tilak optical sunlight consecration of Ram Lalla''s forehead at 12:00 noon', 'Holy cleansing dip in the sacred waters of river Saryu', 'Grand Rath Yatra of Lord Rama with decorated elephants and cavalry down Ram Path']::TEXT[], 'Millions of pilgrims throng Ram Path and the newly sculpted temple complex, chanting ''Jai Shri Ram'' as flowers shower from helicopters at mid-day.', ARRAY['Panjiri prasad', 'Panchamrit', 'Ramdana Laddoos', 'Saryu Peda', 'Poori Sabzi Langar']::TEXT[], 'Saffron kurtas, yellow dhotis, Ram-naam stoles, and traditional Indian ethnic wear.', 'Continuous Akhand Ramayan path recitations, classical temple Shehnai, conch blasts, and soulful Ram bhajans.', 'Nagari architectural spires of Ram Mandir, golden bow and arrow, Saryu river ghats, and Surya Tilak light ray.', '9 Days', 'Hindu Lunisolar', 'Navami (9th day) of Shukla Paksha in Chaitra month', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Shukla Navami at exactly 12:00 noon.', '2026-03-27', '2027-04-15', 'Shri Ram Janmabhoomi Teerth Kshetra Trust & Ayodhya District Administration', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Ayodhya']::TEXT[], ARRAY['Shri Ram Janmabhoomi Mandir', 'Kanak Bhawan', 'Hanuman Garhi', 'Ram Ki Paidi Saryu Ghat']::TEXT[], 'Mid-day 12:00 noon on Ram Navami for the divine birth celebration and Surya Tilak', 2, 'Electrifying spiritual pride, tearful devotion, resounding Vedic chants, and the breathtaking architectural splendor of newly restored Ayodhya.', 'Well connected by Maharishi Valmiki International Airport Ayodhya Dham, Ayodhya Dham Junction railway station, and Gorakhpur-Lucknow highway.', 'Rapidly expanding hotel network; book rooms 2-4 months in advance during Ram Navami.', 'Massive footfall exceeding two million devotees; follow designated queue corridors (darshan lines) patiently.', 'Strict security screening: mobile phones, leather wallets, and electronic devices are prohibited inside the main Ram Mandir sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ayodhya.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-deepotsav-ayodhya', 'Deepotsav Ayodhya', ARRAY['Ayodhya Mega Festival of Lights']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Heritage)', 'The world-record-setting celebration where over 2.5 million earthen lamps (diyas) illuminate Ram Ki Paidi on the eve of Diwali to welcome Lord Rama''s return.', 'Initiated in 2017 by the Government of Uttar Pradesh to recreate the historic scene of Treta Yuga when the citizens of Ayodhya illuminated the city with ghee lamps upon Rama''s return from 14 years of exile.', 'Commemorates the victorious return of Lord Rama, Devi Sita, and Lakshmana to Ayodhya after defeating Ravana.', 'To honor the heritage of Lord Rama and showcase Ayodhya''s resurgence as a global cultural capital.', 'Guinness World Record holder for the largest continuous display of oil lamps in human history (over 2.5 million lamps).', 'Features international Ramlila troupes from Indonesia, Thailand, Cambodia, Sri Lanka, and Nepal.', ARRAY['Simultaneous lighting of over 2.5 million earthen lamps along the banks of Saryu River and Ram Ki Paidi', 'Grand aerial laser and 3D projection mapping show on Ram Ki Paidi facades', 'Coronation procession (Shobha Yatra) with 18 tableau floats depicting episodes from Ramcharitmanas']::TEXT[], 'The Saryu riverbanks transform into a shimmering sea of golden light, with spectacular fireworks, laser animations, and aerial drone formations filling the night sky.', ARRAY['Peda', 'Kaju Katli', 'Panchamrit', 'Jalebi', 'Ayodhya Chhole Puri']::TEXT[], 'Saffron, yellow, and red traditional Indian festive attire; silk kurtas with matching stoles.', 'Orchestral Ramayan musical ballets, international Ramlila performances, and continuous Vedic chants.', 'Millions of twinkling clay lamps, illuminated Ram Ki Paidi bridges, holographic laser rays, and Saryu river reflections.', '3 Days', 'Hindu Lunisolar', 'Celebrated on Chhoti Diwali (Kartik Krishna Chaturdashi)', 'October - November', 'LUNISOLAR', 'Held on the eve of Diwali (Narak Chaturdashi / Chhoti Diwali).', '2026-11-07', '2027-10-28', 'Department of Tourism Uttar Pradesh & Ayodhya Administration', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Ayodhya']::TEXT[], ARRAY['Ram Ki Paidi', 'Saryu River Ghats', 'Ram Katha Park']::TEXT[], 'Sunset (5:30 PM to 9 PM) on the evening of Chhoti Diwali', 2, 'Astonishing, historic visual wonder of millions of flickering golden lights stretching across cascading water terraces under laser-lit skies.', 'Easily accessible in Ayodhya via e-rickshaws and shuttles; central Ram Ki Paidi area is pedestrianized on event evening.', 'Ayodhya hotels and luxury tented cities along the Saryu; early advance booking essential.', 'Extremely heavy security and VIP presence; enter spectator enclosures by 4 PM before road barricades close.', 'Do not step into the laid-out diya grids; maintain safety around open mustard oil flames.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ayodhya.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-taj-mahotsav-agra', 'Taj Mahotsav Agra', ARRAY['Agra Cultural & Crafts Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Mughal Heritage & Crafts', 'A 10-day cultural extravaganza celebrated near the eastern gate of the iconic Taj Mahal, bringing together over 400 artisans and world-renowned performers.', 'Inaugurated in 1992 by Uttar Pradesh Tourism to recreate the vibrant marketplace atmosphere of the 17th-century Mughal era.', 'Celebrates the timeless romance, craftsmanship, and architectural legacy of the Taj Mahal and Mughal India.', 'To provide direct market access to master artisans from across India and promote cultural tourism to Agra beyond the monuments.', 'One of India''s most celebrated spring cultural festivals, blending classical arts, folk heritage, and culinary traditions.', 'Showcases master artisans specializing in Agra''s world-famous marble inlay work (Pietra Dura), Zardozi embroidery, and leather crafts.', ARRAY['Procession of decorated elephants and camels recreating Mughal royal pageantry', 'Artisan crafts bazaar with master craftsmen demonstrating marble carving and brassware', 'Nightly Bollywood, classical, and Sufi concerts at the open-air auditorium']::TEXT[], 'Visitors explore bustling craft alleys, savor legendary Mughlai and Awadhi foods, and attend concerts under cool spring evening skies.', ARRAY['Agra Petha (sweet candied ash gourd in 20+ varieties)', 'Bedai with spicy Aloo Sabzi', 'Mughlai Biryani', 'Seekh Kebabs', 'Dal Moth']::TEXT[], 'Smart casuals, spring kurtas, and traditional handloom ethnic wear.', 'Classical Kathak dance, Braj folk dances, soulful Sufi Qawwalis, and contemporary Bollywood fusion bands.', 'White marble Taj Mahal silhouette, Mughal royal archways, and colorful crafts pavilions.', '10 Days', 'Gregorian / Annual', 'February 18 to 27 annually.', 'February', 'FIXED', 'Held annually February 18-27.', '2026-02-18', '2027-02-18', 'Taj Mahotsav Samiti & Uttar Pradesh Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Agra']::TEXT[], ARRAY['Shilpgram (Near Taj Mahal Eastern Gate) Agra']::TEXT[], 'Late afternoon from 3 PM to 9 PM for shopping and evening star concerts', 2, 'Festive, romantic Mughal garden charm packed with exquisite handcrafted treasures, fragrant barbecue aromas, and world-class musical performances.', 'Easily reached via Yamuna Expressway from Delhi (3 hours); electric shuttles operate between Taj Mahal parking and Shilpgram.', 'Extensive hospitality options ranging from luxury heritage hotels overlooking the Taj Mahal to budget guesthouses.', 'Good crowd control inside Shilpgram grounds; parking is 1 km away with clean electric golf-cart shuttles.', 'Respect the master craftspersons; purchase authentic marble inlay pieces with government certification seals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tajmahotsav.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-magh-mela-prayagraj', 'Magh Mela / Kumbh Mela Prayagraj', ARRAY['Triveni Sangam Mahatirth']::TEXT[], 'Spiritual & Temple', 'Hinduism (Puranic Confluence)', 'The annual 45-day winter spiritual gathering at the sacred confluence of the Ganga, Yamuna, and invisible Saraswati rivers, culminating in the historic Kumbh Mela.', 'Celebrated since ancient Vedic times; documented in the Rigveda and Padma Purana as the ''King of all Pilgrimages'' (Tirtharaj Prayag).', 'Celebrates the holy bath at Triveni Sangam during the auspicious transition of the sun into Capricorn (Makar Sankranti).', 'To cleanse past karmas, seek liberation (Moksha), and practice spiritual austerity (Kalpavas) on the holy sandbanks.', 'Pinnacle of Hindu congregational faith; every 12 years it hosts the Maha Kumbh Mela, the largest peaceful gathering in human history.', 'Sustains the unique ancient tradition of ''Kalpavas'' where hundreds of thousands of householders live in simple tents for a month, eating one meal a day.', ARRAY['Taking holy dips at Triveni Sangam on major bathing dates (Makar Sankranti, Mauni Amavasya, Basant Panchami)', 'Akharas of Naga sadhus carrying silver maces and trident standards into the waters', 'Evening Ganga Aarti at Sangam Ghat with floating clay lamps']::TEXT[], 'The vast sandy floodplain turns into a massive tented city with illuminated pontoon bridges, ringing temple bells, and continuous spiritual discourses.', ARRAY['Puri with Dum Aloo', 'Jalebi with Rabri', 'Allahabadi Guava', 'Tehri', 'Langar Khichdi']::TEXT[], 'Simple saffron and white cotton dhotis, shawls, and modest pilgrim attire.', 'Continuous chanting of Vedic mantras, Akhand Ramayan path, conch shells, and folk bhajan singing.', 'Triveni Sangam confluence where green Yamuna meets muddy Ganga, wooden boats, and illuminated pontoon bridges.', '45 Days', 'Astrological / Lunisolar', 'Paush Purnima to Maha Shivratri (January - February)', 'January - February', 'LUNISOLAR', 'Commences Paush Purnima and ends Maha Shivratri.', '2026-01-14', '2027-01-14', 'Prayagraj Mela Authority & Government of Uttar Pradesh', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Prayagraj']::TEXT[], ARRAY['Triveni Sangam Sandbanks Prayagraj']::TEXT[], 'Dawn on Makar Sankranti and Mauni Amavasya for the sacred holy bath', 3, 'Profound, unforgettable spiritual immersion in a miraculous pop-up mega-city of tents, glowing pontoon bridges, and deep human faith.', 'Prayagraj Junction is a major railway hub; special Mela train services operate; boat services connect Sangam sandbanks.', 'Massive tented tourist villages (glamping camps) set up on Mela grounds, alongside city hotels in Civil Lines.', 'Monumental crowds on Mauni Amavasya (up to 30 million in a single day); follow designated one-way pedestrian routes across pontoon bridges.', 'Negotiate boat fares beforehand at official rate boards; use life jackets; no soap or plastic in the sacred confluence.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kumbh.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lucknow-mahotsav', 'Lucknow Mahotsav', ARRAY['City of Nawabs Cultural Festival']::TEXT[], 'Historical & Royal', 'Secular / Awadhi Royal Heritage', 'A grand 10-day celebration of Awadhi royal culture, literature, classical dance, and world-renowned culinary arts in the historic city of Nawabs.', 'Instituted in the 1970s by Uttar Pradesh Tourism to preserve and showcase the sophisticated culture of the Nawabs of Awadh.', 'Celebrates the refined etiquette (Tehzeeb), poetry, music, and craftsmanship of medieval Lucknow.', 'To promote Awadhi culture, support master Chikankari artisans, and celebrate communal harmony.', 'Showcases the living traditions of the Lucknow Gharana of Kathak, popularized by legendary maestro Pt. Birju Maharaj.', 'Features the world''s most comprehensive showcase of authentic Awadhi royal cuisine (Dastarkhwan).', ARRAY['Grand Mushaira featuring leading Urdu and Hindi poets from across India', 'Lucknow Gharana Kathak dance performances by celebrated exponents', 'Craft exhibition showcasing GI-tagged Chikankari, Zardozi, and perfumed Ittar']::TEXT[], 'Visitors browse elegant craft stalls, attend classical concerts, and savor mouthwatering Awadhi kebabs and biryanis at extensive food pavilions.', ARRAY['Galawati Kebabs with Ulte Tawe Ka Paratha', 'Lucknowi Dum Biryani', 'Sheermal', 'Shahi Tukda', 'Makhan Malai']::TEXT[], 'Refined Awadhi formal attire: fine white Chikankari kurtas, Lucknowi caps (Topi), and elegant Anarkali suits.', 'Classical Kathak dance, Thumri and Dadra vocal recitals, soulful Ghazals, and poetic Mushairas.', 'Rumi Darwaza arches, illuminated Asafi Imambara silhouettes, and delicate Chikankari embroidery.', '10 Days', 'Gregorian / Autumn-Winter', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Announced annually by Lucknow District Administration & UP Tourism.', '2026-11-25', '2027-11-24', 'Lucknow Mahotsav Samiti & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Lucknow']::TEXT[], ARRAY['Smriti Upvan Aashiana Lucknow']::TEXT[], 'Late afternoon from 3:30 PM to 10 PM for food tasting and evening cultural programs', 2, 'Sophisticated, poetic charm steeped in centuries of royal Awadhi refinement, unmatched culinary flavors, and mesmerizing Kathak footwork.', 'Well connected by Chaudhary Charan Singh International Airport, Charbagh Railway Station, and Lucknow Metro.', 'Extensive luxury and heritage hotels across Gomti Nagar, Hazratganj, and Cantt.', 'Sprawling grounds; wear comfortable walking shoes; good parking facilities available.', 'Buy authentic hand-embroidered Chikankari with GI certification tags to support genuine artisans.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://lucknow.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-krishna-janmashtami-mathura', 'Krishna Janmashtami Mathura', ARRAY['Shri Krishna Janmotsav Mathura']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism)', 'The sacred midnight birthday celebration of Lord Krishna celebrated with divine pageantry at his exact prison-cell birthplace in Mathura.', 'Celebrated for millennia across India, centered around the sanctified Shri Krishna Janmabhoomi complex in Mathura.', 'Commemorates the midnight birth of the eighth avatar of Lord Vishnu to Devaki and Vasudeva to destroy tyrant Kamsa.', 'To fast, pray, and welcome the divine infant Krishna with bells, conch shells, and panchamrit abhishek at midnight.', 'Pinnacle of Vaishnava devotion, drawing over two million pilgrims to Mathura and Vrindavan.', 'Features the ancient ''Chappan Bhog'' (56 royal food offerings) and midnight ritual bath (Abhishek) of the infant deity.', ARRAY['Midnight Abhishek of Bal Gopal with milk, curd, honey, and sacred herbs at 12:00 midnight', 'Rocking of beautifully decorated infant Krishna in golden and silver swings (Jhula)', '24-hour fast broken only after the midnight birth aarti']::TEXT[], 'The entire city of Mathura is draped in flowers and lights; temple bells peal furiously at midnight amidst joyful chants of ''Nand Ghar Anand Bhayo, Jai Kanhaiya Lal Ki!''.', ARRAY['Panjiri (coriander and dry fruit prasad)', 'Panchamrit', 'Makhan-Mishri', 'Mathura ke Peda', 'Chappan Bhog delicacies']::TEXT[], 'Bright yellow (Pitambari) silk kurtas, dhotis, and sarees with peacock feather (Mor Pankh) crowns.', 'Ecstatic singing of Bhajans, Raaslila dance performances by child artists, and rhythmic drum beats.', 'Silver baby swing (Jhula), peacock feather crowns, flute (Bansuri), and illuminated Janmabhoomi spires.', '2 Days', 'Hindu Lunisolar', 'Ashtami (8th day) of Krishna Paksha in Bhadrapada month', 'August - September', 'LUNISOLAR', 'Midnight celebration on Bhadrapada Krishna Ashtami (Rohini Nakshatra).', '2026-09-04', '2027-08-25', 'Shri Krishna Janmasthan Seva Sansthan & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Mathura', 'Vrindavan']::TEXT[], ARRAY['Shri Krishna Janmabhoomi Complex Mathura', 'Dwarkadhish Temple', 'Banke Bihari Temple']::TEXT[], 'Midnight (11:00 PM to 1:00 AM) for the divine birth aarti and panchamrit distribution', 2, 'Electric, ecstatic spiritual energy, sea of tearful singing devotees, and unforgettable joy when the temple sanctum doors open at midnight.', 'Direct trains from Delhi, Mumbai, and Agra; 2-hour drive from Delhi via Yamuna Expressway.', 'Hotels and dharamshalas in Mathura and Vrindavan are booked solid; reserve months in advance.', 'Massive crowd crush around midnight; maintain queue patience; hold hands of family members tightly.', 'Strict security screening at Janmabhoomi: mobile phones, bags, and electronic items are strictly prohibited inside.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mathura.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jhansi-mahotsav', 'Jhansi Mahotsav Bundelkhand', ARRAY['Rani Lakshmibai Mahotsav']::TEXT[], 'Historical & Royal', 'Secular / Patriotic Freedom Heritage', 'A spirited cultural festival celebrating the heroic valor of Rani Lakshmibai and the historic folk heritage of the Bundelkhand region.', 'Instituted by Uttar Pradesh Tourism inside the shadow of the historic 17th-century Jhansi Fort atop Bangira Hill.', 'Commemorates the fearless sacrifice of Rani Lakshmibai, hero of the 1857 Indian War of Independence.', 'To honor the legacy of Indian freedom fighters and showcase Bundelkhand''s rich folk music, dance, and handicrafts.', 'Reinvigorates patriotic pride and brings vibrant tourist attention to the historic fortresses of Bundelkhand.', 'Features dramatic sound-and-light narrations of Rani Lakshmibai''s legendary horseback leap from fort ramparts.', ARRAY['Grand equestrian procession and martial arts demonstrations', 'Dramatic light-and-sound show on the stone ramparts of Jhansi Fort', 'Bundeli folk dance and music competitions at Mukt Kashi Manch']::TEXT[], 'Locals and visitors gather in the fort grounds, exploring crafts stalls, watching sword-fighting exhibitions, and enjoying Bundeli folk concerts.', ARRAY['Bundeli Thoke', 'Rasiya sweet', 'Bedmi Puri', 'Desi Ghee Jalebi', 'Kachori']::TEXT[], 'Traditional Bundelkhandi dhotis, colorful turbans with metallic brocade, and sarees with ethnic prints.', 'Vibrant Bundeli folk dances: Rai dance, Diwari dance with peacock feathers, and Alha-Udal martial ballads.', 'Rani Lakshmibai statue on rearing horse, granite ramparts of Jhansi Fort, and brass cannons.', '5 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Jhansi District Administration & UP Tourism.', '2026-02-10', '2027-02-12', 'Jhansi District Administration & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Jhansi']::TEXT[], ARRAY['Jhansi Fort Complex', 'Mukt Kashi Manch Jhansi']::TEXT[], 'Evening 5:30 PM to 9 PM for fort illumination and Bundeli folk performances', 2, 'Inspiring patriotic fervor, dramatic medieval fort ramparts against the evening sky, and lively Bundelkhandi folk rhythms.', 'Major railway junction on Delhi-Mumbai line; accessible by Shatabdi and Vande Bharat trains.', 'Comfortable city hotels across Jhansi.', 'Good family atmosphere; carry a light jacket for chilly winter evenings.', 'Respect the historic fort premises; avoid climbing on fragile stone battlements.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jhansi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sarnath-buddha-mahotsav', 'Sarnath Buddha Mahotsav', ARRAY['Sarnath International Buddhist Festival']::TEXT[], 'Spiritual & Temple', 'Buddhism (Dhamma Heritage)', 'The sacred international Buddhist festival celebrating the turning of the Wheel of Law (Dhammacakkappavattana) at the Deer Park in Sarnath.', 'Commemorates the historic event in 528 BCE when Gautama Buddha preached his first sermon to the five ascetics at Sarnath.', 'Celebrates the revelation of the Four Noble Truths and the Noble Eightfold Path.', 'To foster global peace, inter-faith harmony, and celebrate Buddhist monastic heritage.', 'Unites Buddhist monks, scholars, and pilgrims from Thailand, Japan, Sri Lanka, Myanmar, Vietnam, and Tibet.', 'Centered around the massive 5th-century Dhamek Stupa and the ancient archaeological ruins where Emperor Ashoka erected his famous pillar.', ARRAY['Circumambulation (Pradakshina) of Dhamek Stupa with thousands of lotus flowers and oil lamps', 'Chanting of the Dhammacakkappavattana Sutta by international Buddhist monastic delegations', 'Meditation walks through the tranquil ancient Deer Park ruins']::TEXT[], 'Monks in saffron, maroon, and white robes sit in serene meditation around the stupa, while butter lamps flicker in the twilight breeze.', ARRAY['Vegetarian Thai, Tibetan, and Indian Buddhist feast foods', 'Sattvic Kheer', 'Herbal Tea', 'Fruit offerings']::TEXT[], 'Monastic robes of various Buddhist traditions: Theravada saffron robes, Tibetan maroon robes, and white pilgrim attire.', 'Deep harmonic Buddhist chanting, Tibetan monastic horns, and gentle gong chimes.', 'Massive brick Dhamek Stupa, Ashoka Lion Capital emblem, and sacred Bodhi tree sapling from Anuradhapura.', '3 Days', 'Buddhist Lunisolar', 'Celebrated around Buddha Purnima (Vaisakha Purnima)', 'May', 'LUNISOLAR', 'Celebrated on Vaisakha Purnima (Buddha Purnima).', '2026-05-31', '2027-05-20', 'Maha Bodhi Society of India & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Sarnath', 'Varanasi']::TEXT[], ARRAY['Dhamek Stupa Complex', 'Mulagandha Kuti Vihara']::TEXT[], 'Dawn meditation at 6 AM and illuminated evening prayer ceremony at Dhamek Stupa', 2, 'Profound meditative peace, ancient monolithic brick architecture, soft rustling Bodhi leaves, and soothing multi-nation monastic chants.', '10 km north of Varanasi city center; easily accessible by auto-rickshaw, e-rickshaw, or taxi.', 'Buddhist pilgrim guesthouses, monasteries, and hotels in Sarnath or Varanasi city.', 'Keep silence around meditating monks; remove footwear before stepping on the inner stupa circumambulation path.', 'Treat the archaeological ruins with deep reverence; do not litter or disturb nesting deer in the park.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://varanasi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kabir-utsav-maghar', 'Kabir Utsav Maghar', ARRAY['Maghar Mahotsav']::TEXT[], 'Spiritual & Temple', 'Sant Mat / Secular Philosophy', 'A soul-stirring cultural festival celebrating the revolutionary 15th-century mystic poet-saint Kabir at his Samadhi and Mazar in Maghar.', 'Commemorates the passing of Saint Kabir in 1518 CE at Maghar, deliberately defying the orthodox superstition that dying in Maghar leads to rebirth as an ass.', 'Celebrates the immortal message of communal unity, casteless humanity, and internal spiritual truth preached by Kabir.', 'To honor Kabir''s profound poetry (Dohas) that rejected ritual hypocrisy and dogmatism.', 'Extraordinary symbol of syncretic harmony: Saint Kabir''s shrine in Maghar consists of a Hindu Samadhi and a Muslim Mazar standing side by side in the same compound.', 'Brings together leading Kabir Panthi singers, folk balladeers, and social thinkers from across the subcontinent.', ARRAY['Inter-faith prayer service at the twin Samadhi and Mazar shrines', 'All-night Kabir Bhajan sandhyas with tambura and khartal', 'National seminar on Kabir''s philosophy of social justice and communal harmony']::TEXT[], 'Devotees, folk singers, and scholars sit side by side on simple cotton mats, singing famous couplets of Kabir under open night skies.', ARRAY['Simple community Khichdi with ghee', 'Jalebi', 'Poori Sabzi', 'Sattu sharbat']::TEXT[], 'Simple white khadi kurtas, dhotis, cotton shawls, and modest Indian clothing.', 'Soul-stirring singing of Kabir''s Nirgun bhajans with Ektara, Tambura, harmonium, and rhythmic cymbals.', 'Twin Samadhi and Mazar monuments, handloom weaving charkha, and parchment scrolls with Kabir Dohas.', '3 Days', 'Gregorian / Winter', 'Held in January annually.', 'January', 'FIXED', 'Held annually mid-January.', '2026-01-20', '2027-01-20', 'Sant Kabir Academy & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Maghar', 'Sant Kabir Nagar', 'Gorakhpur']::TEXT[], ARRAY['Kabir Chaura Samadhi Complex Maghar']::TEXT[], 'Evening musical sessions from 6 PM to 10 PM for authentic Kabir bhajan recitals', 2, 'Egalitarian, deeply humbling spiritual warmth where caste, creed, and orthodoxy dissolve into poetic truth and human brotherhood.', '30 km from Gorakhpur Railway Station on NH-28; easily reached by taxi or bus.', 'Guesthouses in Maghar and extensive hotels in Gorakhpur city.', 'Peaceful, reflective rural gathering; simple village surroundings.', 'Respect both the Samadhi and Mazar traditions; cover head when entering the inner shrine courtyards.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sankabirnagar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shakumbhari-mela', 'Shakumbhari Devi Mela Saharanpur', ARRAY['Mata Shakumbhari Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism)', 'The massive mountain folk pilgrimage fair dedicated to Goddess Shakumbhari Devi (the vegetarian goddess who nourishes humanity with fruits and greens).', 'Ancient Shakta pilgrimage mentioned in the Devi Bhagavata Purana and Markandeya Purana, nestled in a Shivalik riverbed valley.', 'Commemorates the manifestation of Goddess Durga as Shakumbhari to end a 100-year catastrophic drought by producing vegetarian foods from her body.', 'To seek the blessings of the Mother Goddess for health, agricultural fertility, and relief from poverty.', 'One of the largest Shakti pilgrimages in northwestern Uttar Pradesh, attracting millions from UP, Haryana, Punjab, and Delhi.', 'Pilgrims complete the ancient ritual of first visiting the Bhura Dev (Bhairav) temple before seeking darshan of Goddess Shakumbhari.', ARRAY['Taking cleansing dips in the seasonal mountain riverbed waters', 'Offering fresh green vegetables, fruits, and coconut to the Mother Goddess', 'Visiting the Bhura Dev shrine to complete the traditional pilgrimage circuit']::TEXT[], 'Millions of devotees camp in colorful tented villages across the dry sandy riverbed, singing devotional songs and dancing to dhol beats.', ARRAY['Halwa Puri prasad', 'Kachori with spicy aloo', 'Seasonal fruit offerings', 'Jalebi']::TEXT[], 'Bright colorful chunris, red and yellow kurtas, dhotis, and traditional Indian pilgrim wear.', 'Enthusiastic folk drum beats, Shehnai, brass bells, and group singing of Mata ki Bhetein.', 'Goddess Shakumbhari idol adorned in green silks holding vegetables and herbs, mountain cliffs, and red flags.', '9 Days', 'Hindu Lunisolar', 'Celebrated during Navratri (Chaitra and Ashwin) and Shakambhari Purnima', 'October', 'LUNISOLAR', 'Peaks during Ashwin Navratri and Shakambhari Purnima.', '2026-10-15', '2027-10-05', 'Shakumbhari Devi Mandir Trust & Saharanpur Administration', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Saharanpur']::TEXT[], ARRAY['Shakumbhari Devi Temple Complex Shivalik Hills']::TEXT[], 'Dawn aarti and afternoon fairground exploration', 2, 'Spectacular rural devotion nestled inside a scenic mountain valley, with colorful tents stretching across the wide riverbed.', '40 km north of Saharanpur city; special mela shuttle buses operate continuously from Saharanpur railway station.', 'Temple dharamshalas, large pilgrim tent cities, and hotels in Saharanpur.', 'Dense crowds during Navratri; be alert to flash flood warnings in the riverbed during monsoon months.', 'Visit Bhura Dev shrine first as per local custom; maintain queue discipline inside the temple corridor.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://saharanpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bateshwar-fair-agra', 'Bateshwar Fair Agra', ARRAY['Bateshwar Cattle & Temple Fair']::TEXT[], 'Fair & Mela', 'Hinduism & Pastoral Trade', 'A historic month-long festival and cattle fair centered around a stunning crescent of 101 white Shiva temples along the holy Yamuna river.', 'Dating back over 400 years, established by the Bhadauria Rajput kings of Ater and Bateshwar on an ancient pilgrimage site mentioned in the epics.', 'Celebrates Lord Shiva as Bateshwar Mahadev (Lord of the Banyan Tree) and ancestral livestock trade.', 'To take holy cleansing dips in the Yamuna on Kartik Purnima and trade horses, camels, and cattle.', 'Features the second-largest livestock fair in India, drawing camel and horse breeders from Rajasthan, Haryana, and Gujarat.', 'The crescent of 101 white stone Shiva temples curving along the riverbank creates one of the most picturesque temple ghat vistas in India.', ARRAY['Taking holy dips in the Yamuna river on the dawn of Kartik Purnima', 'Parikrama circumambulation of the 101 white Shiva temples', 'Trading of decorated camels, Kathiawari horses, and agricultural livestock']::TEXT[], 'Pilgrims bathe at sunrise and ring bells at all 101 temples, while camel herders in colorful turbans barter and showcase their prize livestock.', ARRAY['Bedai Puri with spicy potato curry', 'Jalebi', 'Rabri', 'Kachori', 'Bajra Roti with Jaggery']::TEXT[], 'Traditional Rajasthani-Braj attire: vibrant turbans, kurtas, dhotis, and embroidered ghagras.', 'Folk songs of Braj and Bundelkhand, Rasiya singing, and rural wrestling (Dangal) matches.', 'Curving crescent of 101 whitewashed Shiva temples, decorated camels with painted patterns, and Yamuna riverbanks.', '21 Days', 'Hindu Lunisolar', 'Begins on Kartik Shukla Pratipada and culminates on Kartik Purnima', 'November', 'LUNISOLAR', 'Peaks during the days surrounding Kartik Purnima.', '2026-11-20', '2027-11-10', 'Agra District Administration & UP Tourism', ARRAY['Uttar Pradesh']::TEXT[], ARRAY['Bateshwar', 'Bah', 'Agra']::TEXT[], ARRAY['101 Shiva Temple Ghats Bateshwar', 'Bateshwar Fairgrounds']::TEXT[], 'Kartik Purnima dawn for the 101 temple pradakshina and daytime cattle fair', 2, 'Surreal, timeless rural India spectacle: an unbroken curve of 101 white temples reflected in the river, surrounded by thousands of decorated camels.', '70 km from Agra city; accessible by private taxi or state transport buses via Fatehabad.', 'Simple guesthouses at Bateshwar, tourist rest houses, or base yourself in Agra hotels for a day trip.', 'Very dusty rural fairgrounds; wear comfortable walking shoes, sunglasses, and dust protection.', 'Respect the pastoral traders; take photographs only with courteous consent.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://agra.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chhath-puja-up', 'Chhath Puja at Gomti and Ganga Ghats', ARRAY['Surya Shashti UP']::TEXT[], 'Spiritual & Temple', 'Hinduism (Solar Reverence & Vedic Ecology)', 'The ancient four-day Vedic solar festival observed with rigorous fasting and offerings to the rising and setting Sun on river ghats.', 'Mentioned in Rigveda and Mahabharata; practiced by Draupadi and Karna to gain spiritual strength and solar blessings.', 'Celebrates Surya (Sun God) and Chhathi Maiya (Usha/Pratyusha) as the cosmic source of life, health, and energy.', 'To thank the Sun God for sustaining life on earth and pray for the health and prosperity of children.', 'The purest and most rigorous folk festival in India, conducted without priests, celebrating direct communion between human and cosmos.', 'Celebrated by millions of families across eastern Uttar Pradesh along the banks of Ganga, Yamuna, Saryu, and Gomti rivers.', ARRAY['Nahay Khay ceremonial purification and sanctified pumpkin-rice meal', 'Kharna fast broken with jaggery kheer after sunset', 'Standing chest-deep in water to offer Arghya to the setting and rising Sun']::TEXT[], 'River ghats are cleaned and illuminated with thousands of fairy lights; families carry bamboo baskets loaded with fruits and sugarcanes to the water.', ARRAY['Thekua (traditional ghee-fried whole wheat cookies flavored with cardamom and jaggery)', 'Kasar laddoo', 'Fresh sugarcane', 'Grapefruit', 'Bananas']::TEXT[], 'Vibrant yellow and orange cotton sarees with vermilion lines extending from nose to hair parting; men wear yellow dhotis.', 'Soulful, melodic traditional Chhath folk songs sung by women in chorus, accompanied by Dholak.', 'Bamboo baskets (Daura and Soop), sugarcane canopies with leaves, earthen oil lamps, and rising sun over water.', '4 Days', 'Hindu Lunisolar', 'Kartik Shukla Chaturthi to Saptami (6th day of Kartik month)', 'November', 'LUNISOLAR', 'Begins 4 days after Diwali; main Arghya on Kartik Shukla Shashti.', '2026-11-15', '2027-11-05', 'UP Municipal Corporations & Cultural Affairs Department', ARRAY['Uttar Pradesh', 'Bihar']::TEXT[], ARRAY['Varanasi', 'Lucknow', 'Gorakhpur', 'Prayagraj']::TEXT[], ARRAY['Gomti Riverfront Lucknow', 'Varanasi Ghats', 'Saryu Ghats Ayodhya']::TEXT[], 'Sunset on the third day (Sandhya Arghya) and sunrise on the fourth day (Usha Arghya)', 2, 'Profound, tearful devotion, breathtaking vistas of thousands standing chest-deep in misty river waters offering glowing lamps to the golden sun.', 'Ghats across Lucknow, Varanasi, and Gorakhpur are easily accessible by public and private transport.', 'Ample hotel options in major cities; arrive at ghats by 3 PM for afternoon rituals.', 'Massive family crowds on riverbanks; stay clear of deep water channels beyond barricaded safety lines.', 'Treat the sanctified Thekua prasad with utmost purity; never touch it with unclean hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://uptourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pushkar-camel-fair', 'Pushkar Camel Fair', ARRAY['Pushkar Mela', 'Kartik Mela Pushkar']::TEXT[], 'Fair & Mela', 'Hinduism & Pastoral Trade', 'The world-renowned annual camel and livestock fair where 50,000 decorated camels assemble beside the holy lake and solitary Brahma Temple.', 'Ancient pilgrimage fair mentioned in the Mahabharata, sanctified as the sole major temple dedicated to Lord Brahma in the world.', 'Commemorates Lord Brahma dropping a lotus flower that created the sacred Pushkar Lake.', 'To take holy dips in sacred Pushkar Lake on Kartik Purnima and conduct ancestral cattle and horse trading.', 'Global cultural icon combining rural pastoral commerce, thrilling desert competitions, and profound Hindu pilgrimage.', 'Features iconic competitions like the Longest Moustache, Matka Phod, Bridal contests, and high-stakes camel beauty pageants.', ARRAY['Maha Aarti at Brahma Ghat with floating oil lamps', 'Holy dip in the 52 ghats of Pushkar Lake on Kartik Purnima', 'Camel beauty contests with sheared fur designs and brass adornments']::TEXT[], 'Vast sand dunes buzz with music, brightly turbanned camel herders, hot air balloons rising at dawn, and Ferris wheels.', ARRAY['Dal Baati Churma', 'Malpua with Rabri', 'Pushkar Gulkand Lassi', 'Pyaaz Kachori', 'Ghevar']::TEXT[], 'Vibrant Rajasthani turbans (Safas) in neon pink and saffron, Angrakha kurtas, and heavy mirror-work Ghagras.', 'Soulful Manganiyar and Langa folk music with Kamayacha and Khartal, energetic Kalbelia snake dances.', 'Decorated camels with cowrie shells and brass bells, sacred Brahma temple spire, and desert sand dunes.', '8 Days', 'Hindu Lunisolar', 'Kartik Shukla Ashtami to Kartik Purnima (November)', 'November', 'LUNISOLAR', 'Culminates on Kartik Purnima.', '2026-11-20', '2027-11-10', 'Rajasthan Tourism & Pushkar Mela Vikas Samiti', ARRAY['Rajasthan']::TEXT[], ARRAY['Pushkar', 'Ajmer']::TEXT[], ARRAY['Pushkar Fairgrounds', 'Brahma Ghat', 'Brahma Temple']::TEXT[], 'Early morning hot air balloon rides over dunes and evening Brahma Ghat aarti', 3, 'Spectacular desert sensory whirlwind of golden sands, sea of adorned camels, echoing folk music, and transcendent lake spirituality.', '14 km from Ajmer Junction railway station; easily reached by highway buses, private taxis, and camel carts.', 'Luxury desert tented cities, heritage havelis, and desert resorts; book 4-6 months in advance.', 'Heavy desert dust and footfall; protect cameras with lens filters and carry dust scarves and hydration.', 'Remove footwear before stepping onto lake ghats; decline unsolicited ''priest'' flower blessings asking for aggressive donations.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-desert-festival-jaisalmer', 'Desert Festival Jaisalmer', ARRAY['Maru Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Rajasthani Royal & Desert Folk Heritage', 'A glorious three-day desert cultural carnival staged amidst the undulating Sam Sand Dunes and the 12th-century living Golden Fort of Jaisalmer.', 'Initiated in 1979 by Rajasthan Tourism to showcase the rich nomadic traditions, martial valour, and musical heritage of the Thar Desert.', 'Celebrates the unique desert culture, folk architecture, and pastoral life of the Marwar and Thar regions.', 'To present Thar desert folk arts, polo matches, camel acrobatics, and tourism in the heart of the Golden City.', 'Draws thousands of global travelers into the living desert wilderness, supporting hundreds of folk musicians and craftspeople.', 'Famous for the ''Mr. Desert'' (Maru Shri) and ''Miss Moomal'' cultural pageants and camel polo tournaments.', ARRAY['Grand opening procession from Jaisalmer Golden Fort to Shahid Poonam Singh Stadium', 'Turban tying and moustache competitions for visitors', 'Camel polo and musical performances on the shifting Sam sand dunes']::TEXT[], 'Visitors enjoy camel safaris, watch turbaned acrobats balancing on swords, and listen to hypnotic folk melodies under full moon skies.', ARRAY['Ker Sangri', 'Gatte Ki Sabzi', 'Bajra Roti with Desi Ghee', 'Mawa Kachori', 'Bikaneri Bhujia']::TEXT[], 'Vibrant Marwari attire: Bandhani turbans, mirror-work jackets, silver hasli necklaces, and flared ghagras.', 'Legendary Manganiyar folk ballads, Morchang, Algoza, and breathtaking Chari fire dances.', 'Yellow Jaisalmer sandstone fort arches, camel caravans on sand dunes, and desert moon.', '3 Days', 'Hindu Lunisolar', 'Culminates on Magh Purnima (full moon night in February)', 'February', 'LUNISOLAR', 'Full moon of Magh month.', '2026-02-01', '2027-02-20', 'Rajasthan Tourism Development Corporation (RTDC)', ARRAY['Rajasthan']::TEXT[], ARRAY['Jaisalmer', 'Sam Sand Dunes']::TEXT[], ARRAY['Jaisalmer Fort', 'Sam Sand Dunes', 'Poonam Singh Stadium']::TEXT[], 'Sunset and night sessions at Sam Sand Dunes under the full moon', 3, 'Magical desert romance with shimmering golden dunes, mournful folk melodies floating across night sands, and campfire warmth.', 'Jaisalmer Airport connects to Delhi/Mumbai in winter; direct trains from Delhi and Jaipur.', 'Luxury tented camps at Sam or Khuri dunes, and heritage haveli hotels inside the living fort.', 'Desert nights can drop near freezing (4°C); bring heavy woolen jackets and thermal layers.', 'Negotiate camel ride charges in advance; do not litter pristine desert sand dunes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mewar-festival-udaipur', 'Mewar Festival Udaipur', ARRAY['Udaipur Spring Festival']::TEXT[], 'Historical & Royal', 'Hinduism (Shaktism & Mewar Royalty)', 'A regal spring festival celebrating the arrival of spring (Vasant) and welcoming Goddess Gauri with royal boat processions across Lake Pichola.', 'Dates back centuries to the Sisodia rulers of Mewar, commemorating their patron deities and the valor of Rajput chivalry.', 'Celebrates the triumph of spring and the marital devotion of Goddess Parvati (Gauri).', 'To seek blessings of Goddess Gauri for marital bliss and family prosperity and celebrate Mewar''s royal traditions.', 'Showcases the living aristocratic culture of Udaipur''s royal house alongside spirited local community festivities.', 'Concludes with an emotional water immersion procession of clay Gauri idols into Lake Pichola at Gangaur Ghat.', ARRAY['Women carrying colorfully decorated idols of Isar (Shiva) and Gauri (Parvati) through City Palace gates', 'Royal boat procession carrying the royal family and deity idols across Lake Pichola', 'Grand fireworks display illuminating the marble facades of Lake Palace and Jag Mandir']::TEXT[], 'Women dressed in vivid Rajasthani attire balance brass pots and deity idols, singing folk songs down to the marble steps of Gangaur Ghat.', ARRAY['Udaipuri Kachori', 'Mirchi Vada', 'Ghevar', 'Churma Ladoo', 'Dal Baati']::TEXT[], 'Rich Mewari Lehengas with Gota-Patti embroidery, Chunaris with gold foil work, and royal Rajputana Turbans.', 'Graceful Ghoomar dances performed by hundreds of women in unison, Shehnai, and classical Sarangi.', 'Gangaur Ghat marble arches, royal barges with swan prows, and shimmering Lake Pichola reflections.', '3 Days', 'Hindu Lunisolar', 'Chaitra Shukla Tritiya to Panchami (March - April)', 'March - April', 'LUNISOLAR', 'Begins on Gangaur day (Chaitra Shukla Tritiya).', '2026-03-22', '2027-04-10', 'Rajasthan Tourism & Maharana of Mewar Charitable Foundation', ARRAY['Rajasthan']::TEXT[], ARRAY['Udaipur']::TEXT[], ARRAY['Gangaur Ghat', 'City Palace Udaipur', 'Lake Pichola']::TEXT[], 'Late afternoon at Gangaur Ghat followed by sunset boat procession on Lake Pichola', 2, 'Exquisite Rajputana royal romance with white marble palaces reflecting in blue waters, graceful Ghoomar dancers, and fireworks.', 'Maharana Pratap Airport Udaipur (24 km); easily traversed by auto-rickshaws, boats, and walking.', 'Heritage lakefront havelis and palace hotels overlooking Lake Pichola.', 'Crowded ghat steps during idol immersions; watch footing on marble steps near the water.', 'Do not obstruct women carrying deity idols; photography welcomed from viewing platforms.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gangaur-festival-jaipur', 'Gangaur Festival Jaipur', ARRAY['Jaipur Gangaur Shobha Yatra']::TEXT[], 'Historical & Royal', 'Hinduism (Shaktism & Marital Devotion)', 'The glorious royal procession of Goddess Gauri passing through the historic Tripolia Gate of the Pink City with royal lancers and elephants.', 'Initiated centuries ago by the Kachhwaha Rajput rulers of Amber and Jaipur to celebrate the divine marriage of Shiva and Parvati.', 'Commemorates the departure of Goddess Gauri from her maternal home to her consort Lord Shiva.', 'To pray for the longevity of husbands, marital harmony, and virtuous life partners for unmarried maidens.', 'One of the grandest surviving royal processions in Asia, opened exclusively by the royal family of Jaipur.', 'The City Palace gates (Tripolia Gate) are opened exclusively on this day for the royal palanquin to emerge into the city streets.', ARRAY['Special darshan of the bejeweled royal idol of Gauri at City Palace Zenana Deorhi', 'Procession of royal elephants painted with floral motifs, camel cavalry, and brass bands', 'Women carrying water pots on heads singing traditional Gangaur folk couplets']::TEXT[], 'Tens of thousands of spectators pack historic pink sandstone rooftops, balconies, and sidewalks along Tripolia Bazaar to catch a glimpse of the Goddess.', ARRAY['Ghevar (especially Malai Ghevar and Mawa Ghevar)', 'Kachori', 'Feni', 'Puri with Aloo Jhol']::TEXT[], 'Vibrant red and orange Lehengas, traditional Rajput Poshak with Zardozi embroidery, and colorful pagris.', 'Graceful Ghoomar dances, Kalbelia performers, Shehnai, and Rajasthan Police ceremonial brass bands.', 'Goddess Gauri bejeweled golden idol, Tripolia Gate, painted caparisoned elephants, and pink sandstone balconies.', '2 Days', 'Hindu Lunisolar', 'Chaitra Shukla Tritiya and Chaturthi (March - April)', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Shukla Tritiya.', '2026-03-22', '2027-04-10', 'Department of Tourism Rajasthan & City Palace Jaipur', ARRAY['Rajasthan']::TEXT[], ARRAY['Jaipur']::TEXT[], ARRAY['City Palace Jaipur', 'Tripolia Gate', 'Talkatora']::TEXT[], 'Afternoon from 4:30 PM to 6:30 PM when the royal procession marches through the Old City', 2, 'Spectacular pageantry of medieval Rajput royalty, dazzling mirror-work costumes, painted royal elephants, and pink city rooftops.', 'Jaipur Metro (Chhoti Chaupar station), cycle-rickshaws, and cabs; central bazaar is pedestrianized during procession.', 'Extensive heritage havelis and luxury hotels across Jaipur.', 'Heavy street crowds along Tripolia Bazaar; secure a spot on a rooftop cafe or terrace early.', 'Respect the sanctity of the royal deity palanquin; do not block the passage of caparisoned camels and horses.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-teej-festival-jaipur', 'Teej Festival Jaipur', ARRAY['Haryali Teej Jaipur']::TEXT[], 'Historical & Royal', 'Hinduism (Shaktism & Monsoon Pageantry)', 'The grand monsoon royal procession of Goddess Teej carried through the historic streets of Jaipur in a golden palanquin accompanied by royal guards.', 'Celebrated since the founding of Jaipur in 1727 by Maharaja Sawai Jai Singh II, celebrating the cooling monsoon rains in the desert.', 'Commemorates the reunion of Goddess Parvati with Lord Shiva after 108 years of penance.', 'To pray for rain, agricultural fertility, marital bliss, and family happiness.', 'Signature cultural spectacle of Jaipur, where the royal family continues the unbroken tradition of flagging off the procession.', 'Famous for the traditional sweet Ghevar, which is freshly prepared and eaten in massive quantities across Rajasthan only during Teej.', ARRAY['Puja of Goddess Teej idol inside the City Palace by the royal family', 'Grand public procession emerging from Tripolia Gate winding to Chaugan Stadium', 'Women swinging on decorated floral swings suspended from ancient banyan trees']::TEXT[], 'Crowds cheer as the gold-leafed palanquin of Goddess Teej is carried aloft by retainers in traditional livery amidst dancers and acrobats.', ARRAY['Ghevar (Paneer, Malai, and plain varieties)', 'Dal Baati Churma', 'Samosa', 'Mirchi Vada', 'Rabri']::TEXT[], 'Green Lehengas, green bangles, Lehariya (wave-pattern tie-dye) sarees and dupattas, and gold jewellery.', 'Traditional Ghoomar dance, Kalbelia performers, Kachhi Ghodi puppet dancers on wooden hobbyhorses, and Shehnai.', 'Golden palanquin of Teej Mata, green Lehariya fabrics, swings with marigold garlands, and pink city facades.', '2 Days', 'Hindu Lunisolar', 'Shravana Shukla Tritiya (monsoon month of August)', 'August', 'LUNISOLAR', 'Celebrated on Shravana Shukla Tritiya.', '2026-08-16', '2027-08-05', 'Department of Tourism Rajasthan & Municipal Corporation Jaipur', ARRAY['Rajasthan']::TEXT[], ARRAY['Jaipur']::TEXT[], ARRAY['City Palace', 'Tripolia Bazaar', 'Chaugan Stadium']::TEXT[], 'Afternoon between 4:30 PM and 7 PM during the royal street procession', 2, 'Exuberant celebration of rain in the desert, emerald green fabrics everywhere, sweet saffron aromas of hot Ghevar, and royal Rajput pageantry.', 'Jaipur Metro to Badi Chaupar / Chhoti Chaupar; e-rickshaws throughout old city.', 'Heritage hotels and boutique stays throughout Jaipur.', 'Warm and humid monsoon conditions; drink bottled water and carry an umbrella.', 'Book a seat on designated tourist viewing galleries arranged by Rajasthan Tourism at Tripolia Gate.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-marwar-festival-jodhpur', 'Marwar Festival Jodhpur', ARRAY['Maand Festival Jodhpur']::TEXT[], 'Historical & Royal', 'Marwar Chivalry & Classical Folk Music', 'A majestic cultural festival dedicated to the folk heroes, romantic ballads, and chivalric martial culture of Marwar, held at Mehrangarh Fort and Umaid Bhawan.', 'Initiated by Rajasthan Tourism to celebrate the legendary valor of Rao Jodha and the folklore of Marwar under the autumn full moon.', 'Celebrates the immortal romance of Dhola-Maru and the heroic battles of Rajput warriors.', 'To preserve the classical Maand style of singing and honor the desert warriors who defended Marwar.', 'Transforms the colossal Mehrangarh Fort and the marble cenotaphs of Jaswant Thada into illuminated classical concert stages.', 'Features traditional rural sporting contests like the Tug-of-War, Matka race, and camel tattoo shows.', ARRAY['Grand evening concerts of Maand singing against floodlit Mehrangarh Fort walls', 'Camel tattoo and acrobatics shows organized by Border Security Force (BSF)', 'Folk dance competitions at Clock Tower bazaar and Mandore Gardens']::TEXT[], 'Music lovers and travelers sit on royal carpets under the full moon, mesmerized by powerful vocalists whose ballads echo across blue city rooftops.', ARRAY['Mawa Kachori of Jodhpur', 'Pyaaz Kachori', 'Mirchi Bada', 'Gatte Ki Khichdi', 'Gulab Jamun Sabzi']::TEXT[], 'Traditional Jodhpuri Bandhgalas, colorful Jodhpuri turbans, and flowing Rajasthani Lehengas.', 'Classical Maand vocal recitals, hypnotic Ghoomar, energetic Kalbelia, and Dhol-Thali rhythms.', 'Mehrangarh Fort granite battlements, indigo blue houses of Jodhpur, and autumn full moon.', '2 Days', 'Hindu Lunisolar', 'Ashwin Purnima (Sharad Purnima full moon night in October)', 'October', 'LUNISOLAR', 'Celebrated on Sharad Purnima in Ashwin month.', '2026-10-25', '2027-10-15', 'Rajasthan Tourism & Mehrangarh Museum Trust', ARRAY['Rajasthan']::TEXT[], ARRAY['Jodhpur']::TEXT[], ARRAY['Mehrangarh Fort', 'Umaid Bhawan Palace', 'Jaswant Thada', 'Clock Tower']::TEXT[], 'Evenings from 6 PM to 10 PM under the full moon at Mehrangarh Fort', 2, 'Breathtaking romantic grandeur with the colossal fortress glowing amber above the indigo blue city, filled with stirring medieval desert ballads.', 'Jodhpur Airport connects major cities; autorickshaws and cabs navigate the old blue city.', 'Heritage havelis inside the blue city and luxury palace hotels across Jodhpur.', 'Cool desert breezes in late October evenings; carry a light jacket.', 'Respect monument conservation rules; maintain silence during delicate vocal Maand recitals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-elephant-festival-jaipur', 'Elephant Festival Jaipur', ARRAY['Jaipur Gaj Mahotsav']::TEXT[], 'Historical & Royal', 'Royal Rajputana Equestrian Heritage', 'A spectacular royal celebration where majestic elephants are groomed, painted with velvet-soft natural colors, adorned with heavy gold jewelry, and paraded.', 'Rooted in royal Rajput traditions where war elephants were symbols of majesty, power, and sacred protection.', 'Celebrates Lord Ganesha (the elephant-headed remover of obstacles) and royal regal pageantry on the eve of Holi.', 'To honor the sacred bond between humans and gentle pachyderms and celebrate the spirit of spring.', 'Globally famous spectacle of living animal artistry, where mahouts spend days painting intricate floral motifs across elephant trunks and ears.', 'Has transitioned into an eco-conscious cultural festival emphasizing animal welfare, gentle polo, and traditional music.', ARRAY['Parade of elaborately painted elephants draped in embroidered velvet caparisons', 'Elephant beauty contest judged by art historians and veterinary specialists', 'Traditional tug-of-war between an elephant and a team of 19 strong athletes']::TEXT[], 'Spectators watch in delight as decorated giants walk majestically, sway to Shehnai music, and lift garlands with their painted trunks.', ARRAY['Dal Baati Churma', 'Jaipuri Pyaaz Kachori', 'Gujiya', 'Thandai']::TEXT[], 'Festive Holi attire: white cotton kurtas with bright colored stoles, pagris, and bandhani sarees.', 'Traditional Rajasthani folk dances (Kalbelia, Ghoomar, Chari), Shehnai, and Nagada drums.', 'Intricate floral trunk paintings, velvet elephant blankets (Jhul), and golden howdah carriages.', '1 Day', 'Hindu Lunisolar', 'Celebrated on the eve of Holi (Phalguna Purnima day)', 'March', 'LUNISOLAR', 'Held on the eve of Holi in Phalguna.', '2026-03-03', '2027-03-22', 'Rajasthan Tourism Development Corporation', ARRAY['Rajasthan']::TEXT[], ARRAY['Jaipur']::TEXT[], ARRAY['Jaipur Polo Ground / Elephant Village (Hathi Gaon)']::TEXT[], 'Afternoon between 3 PM and 6:30 PM for the beauty pageant and cultural show', 1, 'Dazzling visual feast of royal opulence, vibrant natural paint artistry, gentle giants, and joyful pre-Holi excitement.', 'Easily accessible in Jaipur via taxi, auto-rickshaw, or ride-share apps.', 'Hotels throughout Jaipur.', 'Strict animal welfare guidelines enforced: maintain designated distance from elephants; no loud sudden noises or flash photography.', 'Treat the animals with gentleness; do not feed anything without the mahout''s express permission.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kumbhalgarh-festival', 'Kumbhalgarh Classical Festival', ARRAY['Kumbhalgarh Dance Festival']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Dance & Fortress Heritage', 'A premier three-day festival of classical Indian dance and music staged against the floodlit backdrop of Kumbhalgarh Fort and its 36-kilometer Great Wall.', 'Instituted by Rajasthan Tourism inside the UNESCO World Heritage fortress built by Rana Kumbha in the 15th century.', 'Celebrates the invincible martial spirit of Mewar and its patronage of high classical arts and architecture.', 'To bring world-class performing artists to a remote wilderness fortress and promote heritage tourism.', 'Set against the second-longest continuous wall in the world (36 km), creating an incomparable historical acoustic arena.', 'Presents classical dance traditions from across India (Kathak, Odissi, Bharatnatyam, Kuchipudi, Manipuri, Mohiniyattam) in one royal venue.', ARRAY['Daytime folk competitions including turban tying and tug-of-war between locals and tourists', 'Dramatic evening illumination of the massive stone ramparts and Badal Mahal', 'Nightly classical music and dance recitals by national Sangeet Natak Akademi awardees']::TEXT[], 'Connoisseurs sit beneath cold starlit Aravalli skies as classical dancers perform intricate rhythm sequences on the open-air stone terrace.', ARRAY['Mewari Dal Baati Churma', 'Gatta Curry', 'Rabri', 'Kachori with garlic chutney']::TEXT[], 'Refined winter formal ethnic wear: warm Pashmina shawls, bandhgalas, and silk sarees.', 'Sublime classical dance dramas, sitar-flute jugalbandis, and soulful Rajasthani folk music.', 'Massive 15th-century stone ramparts, Badal Mahal palace, and dramatic yellow spotlights illuminating mountain ridges.', '3 Days', 'Gregorian / Winter', 'December 1 to 3 annually.', 'December', 'FIXED', 'Held annually December 1-3.', '2026-12-01', '2027-12-01', 'Rajasthan Tourism & Kumbhalgarh Sanctuary Administration', ARRAY['Rajasthan']::TEXT[], ARRAY['Kumbhalgarh', 'Rajsamand', 'Udaipur']::TEXT[], ARRAY['Kumbhalgarh Fort Complex (Badal Mahal Terrace)']::TEXT[], 'Evenings between 6 PM and 9:30 PM when the fortress is floodlit for classical concerts', 2, 'Awe-inspiring medieval mountain citadel atmosphere, cold whispering winds, ancient stone ramparts, and flawless classical artistry.', '85 km north of Udaipur (2.5 hours by taxi through scenic Aravalli hills).', 'Heritage resorts, jungle lodges, and hotels nestled in the hills around Kumbhalgarh.', 'Chilly December nights in the hills (drop to 6°C); carry heavy woolen coats, shawls, and thermals.', 'Wear flat comfortable shoes as walking from fort gates to the performance terrace involves steep cobbled slopes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kolayat-fair-bikaner', 'Kolayat Fair (Kapil Muni Fair) Bikaner', ARRAY['Kapil Muni Mela Kolayat']::TEXT[], 'Spiritual & Temple', 'Hinduism (Samkhya Philosophy & Sacred Lake)', 'The sacred desert lake pilgrimage where thousands float illuminated earthen lamps on the waters where sage Kapil Muni meditated.', 'Ancient pilgrimage site where Maharshi Kapil, propounder of the Samkhya philosophical school of Hinduism, attained spiritual liberation.', 'Celebrates the enlightenment of Sage Kapil and spiritual cleansing in the sacred Kolayat Lake.', 'To take holy dips in the 52 ghats of Kolayat Lake and perform Deepdaan to wash away sins.', 'Equal in spiritual significance to Pushkar, drawing rural pilgrims, Sadhus, and cattle herders from western Rajasthan.', 'Features a bustling cattle fair where prize camels, Marwari horses, and indigenous buffaloes are traded.', ARRAY['Midnight and dawn holy dips in Kolayat Lake on Kartik Purnima', 'Grand Deepdaan where thousands of earthen lamps in leaf cups are released on lake waters at dusk', 'Pilgrimage darshan at the marble Kapil Muni Temple']::TEXT[], 'The tranquil desert lake turns into a shimmering galaxy of golden lights as chanting pilgrims gently push leaf-boats into the water.', ARRAY['Bikaneri Bhujia', 'Rasgulla of Bikaner', 'Ghevar', 'Bajra Khichdi', 'Mirchi Vada']::TEXT[], 'Vivid rural Marwari dhotis, saffron turbans, and mirror-work embroidered Odhnis.', 'Devotional Kapil Muni bhajans, Dholak beats, and traditional desert folk singing.', 'Ghats of Kolayat Lake, Kapil Muni marble idol, floating clay lamps, and desert dunes.', '3 Days', 'Hindu Lunisolar', 'Culminates on Kartik Purnima (November)', 'November', 'LUNISOLAR', 'Culminates on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Bikaner District Administration & Kolayat Temple Trust', ARRAY['Rajasthan']::TEXT[], ARRAY['Kolayat', 'Bikaner']::TEXT[], ARRAY['Kolayat Sacred Lake', 'Kapil Muni Temple Complex']::TEXT[], 'Sunset on Kartik Purnima for the magnificent Deepdaan ceremony and dawn for holy dips', 2, 'Serene, untouched spiritual authenticity of the Thar desert, peaceful lake waters, and thousands of twinkling floating lamps.', '50 km southwest of Bikaner on NH-11; accessible by trains and frequent local buses.', 'Simple pilgrim dharamshalas at Kolayat; comfortable hotels in Bikaner city.', 'Cool desert November nights; carry warm clothing.', 'Maintain deep spiritual sanctity at the 52 bathing ghats; avoid single-use plastics.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bikaner.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-brij-holi-bharatpur', 'Brij Holi Festival Bharatpur', ARRAY['Bharatpur Braj Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Hinduism (Braj Vaishnavism)', 'A vibrant two-day spring cultural festival celebrated with dramatic Raaslila dance dramas and showers of herbal colors in Bharatpur.', 'Celebrates the historic inclusion of Bharatpur (Deeg) into the sacred cultural circle of Braj (Braj Mandal).', 'Celebrates the divine pastimes of Radha and Krishna and the arrival of the spring harvest season.', 'To showcase Braj culture, folk music, and spectacular water fountain displays at the historic Deeg Palace.', 'Combines the spiritual joy of Braj Holi with the architectural marvel of Deeg''s 18th-century royal monsoon palaces.', 'Features the operation of hundreds of historic colored water fountains at Deeg Palace powered by gravity hydraulics.', ARRAY['Raaslila dance performances depicting the life of Lord Krishna by traditional troupes', 'Operation of over 500 historic colored water fountains at Deeg Jal Mahal', 'Spirited folk dance competitions including Charkula dance and Huranga']::TEXT[], 'Visitors gather around historic water canals as colorful fountains spray into the sky and women perform dramatic Charkula fire dances.', ARRAY['Brij Gujiya', 'Bikaneri Kachori', 'Thandai', 'Rabri Jalebi', 'Bedmi Puri']::TEXT[], 'White cotton kurtas, colorful dupattas, and turbans spattered with natural herbal gulal.', 'Charkula dance (balancing heavy lighted pyramids of 108 lamps on head), Rasiya folk songs, and Raaslila ballets.', 'Historic fountains of Deeg Palace, 108-lamp Charkula pyramid, and vibrant herbal colors.', '2 Days', 'Hindu Lunisolar / Spring', 'Held a few days before main Holi in Shukla Paksha of Phalguna month.', 'March', 'LUNISOLAR', 'Held 2-3 days before Holi.', '2026-03-01', '2027-03-20', 'Rajasthan Tourism & Bharatpur District Administration', ARRAY['Rajasthan']::TEXT[], ARRAY['Bharatpur', 'Deeg']::TEXT[], ARRAY['Deeg Palace', 'Lohagarh Fort Bharatpur']::TEXT[], 'Afternoon fountain operation at Deeg Palace and evening Charkula dance concerts', 2, 'Joyful spring vitality, engineering wonder of 250-year-old gravity water fountains, and breathtaking fire-lamp balancing dances.', '35 km from Bharatpur Junction; easily reached by road from Agra (55 km) or Mathura (40 km).', 'Heritage hotels and resorts in Bharatpur and nearby bird sanctuary area.', 'Water sprays from fountains can be misty; protect electronic devices in water-resistant cases.', 'Appreciate the difficult balance of Charkula dancers; avoid loud flash photography during sacred dances.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bharatpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shekhawati-festival', 'Shekhawati Heritage Festival Nawalgarh', ARRAY['Shekhawati Open-Air Art Festival']::TEXT[], 'Historical & Royal', 'Secular / Fresco Art & Architecture', 'A fascinating three-day festival celebrating the world''s largest open-air art gallery of fresco-painted havelis across the Shekhawati region.', 'Initiated in 1995 by Rajasthan Tourism and the Morarka Foundation to protect and showcase the 18th and 19th-century painted merchant havelis.', 'Celebrates the artistic genius, fresco techniques, and pioneering mercantile enterprise of Shekhawati Marwari merchants.', 'To promote conservation of fresco-painted architecture and support rural artisan traditions.', 'Highlights the unique cultural synthesis of traditional Rajasthani lore, mythology, and British colonial inventions painted on haveli walls.', 'Features guided heritage walks, organic farming seminars, and classical folk musical concerts.', ARRAY['Guided haveli architectural walks explaining natural pigment fresco techniques', 'Traditional camel cart rallies and horse safaris across rural hamlets', 'Folk dance and fireworks evening concerts at Anandilal Poddar Haveli']::TEXT[], 'Visitors wander through quiet sandy streets, looking up in awe at thousand-square-meter walls painted with epics, trains, motorcars, and deities.', ARRAY['Shekhawati Peda', 'Pyaaz Kachori', 'Bajra Roti with Lehsun Chutney', 'Churma', 'Ker Sangri']::TEXT[], 'Traditional Rajasthani Bandhani kurtas, colorful turbans, and comfortable travel wear.', 'Folk performances of Chang dance during Dhulandi season, Ghoomar, and energetic Algoza-flute duets.', 'Painted haveli courtyards, intricately carved wooden doorways, and brass stud hardware.', '3 Days', 'Gregorian / Winter', 'Held in February annually.', 'February', 'FIXED', 'Held annually in mid-February.', '2026-02-13', '2027-02-12', 'Rajasthan Tourism & Morarka Organic Foundation', ARRAY['Rajasthan']::TEXT[], ARRAY['Nawalgarh', 'Mandawa', 'Fatehpur', 'Jhunjhunu']::TEXT[], ARRAY['Anandilal Poddar Haveli Nawalgarh', 'Aath Haveli Complex']::TEXT[], 'Morning architectural walking tours (8:30 AM to 12 PM) and evening folk concerts', 2, 'Enchanting step back into the golden age of Silk Route merchant princes, surrounded by thousands of breathtaking painted fresco masterpieces.', '140 km from Jaipur; accessible by highway cabs and Shekhawati passenger trains.', 'Exquisite restored heritage haveli hotels and boutique homestays in Nawalgarh and Mandawa.', 'Sandy village lanes; comfortable walking shoes and sun protection recommended.', 'Never scratch, lean against, or touch fragile historic wall paintings; support local haveli preservation trusts.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bundi-utsav', 'Bundi Utsav Bundi', ARRAY['Bundi Cultural Festival']::TEXT[], 'Historical & Royal', 'Rajput Heritage & Stepwell Architecture', 'A charming festival showcasing the medieval Rajput chivalry, exquisite miniature paintings, and intricate stepwells of the historic town of Bundi.', 'Initiated by Rajasthan Tourism and the district administration to highlight Bundi''s unique architectural and miniature painting legacy.', 'Celebrates the romantic cultural heritage of the Hada Rajput rulers of Bundi.', 'To promote tourism to Bundi''s fairytale Taragarh Fort, royal palaces, and ancient stepwells (Baoris).', 'Showcases the world-renowned Bundi School of miniature paintings, famed for vivid green hues, lush vegetation, and expressive eyes.', 'Features the lighting of hundreds of earthen lamps on the stone steps of ancient baoris and Nawal Sagar lake.', ARRAY['Shobha Yatra grand street procession featuring decorated camels and folk dancers', 'Lighting of thousands of floating lamps on the waters of Nawal Sagar Lake (Deepdaan)', 'Turban tying and traditional mustache competitions for international travelers']::TEXT[], 'The ancient town glows with fairy lights; folk artists perform at the majestic stepwells, while fireworks burst over Taragarh Fort.', ARRAY['Bundi ke Laddoos (sweet gram flour pearl pearls)', 'Dal Baati Churma', 'Samosa', 'Rabri']::TEXT[], 'Traditional Hada Rajput dress: colorful Angrakhas, Bandhani turbans, and Lehengas.', 'Graceful Ghoomar, energetic Chari dance with burning brass pots on head, and soulful Shehnai.', 'Intricate stepwell arches (Raniji ki Baori), Taragarh Fort ramparts, and illuminated lake mirrors.', '3 Days', 'Hindu Lunisolar / Autumn', 'Kartik month (November) immediately following Pushkar Fair.', 'November', 'LUNISOLAR', 'Held in Kartik month following Kartik Purnima.', '2026-11-26', '2027-11-15', 'Rajasthan Tourism & Bundi District Administration', ARRAY['Rajasthan']::TEXT[], ARRAY['Bundi']::TEXT[], ARRAY['Taragarh Fort', 'Raniji ki Baori', 'Nawal Sagar Lake', 'Chaugan']::TEXT[], 'Deepdaan evening at Nawal Sagar and morning procession from Garh Palace', 2, 'Authentic, uncommercialized medieval fairy-tale charm with stunning stepwells glowing with lamps beneath a crumbling hill fortress.', '35 km from Kota (major railway junction); connected by highway and local buses.', 'Charming heritage havelis and guesthouses throughout Bundi old town.', 'Steep stone staircases at Taragarh Fort; sturdy walking shoes required.', 'Take care near deep open water stepwells; maintain clean water surroundings.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bundi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mount-abu-winter-festival', 'Mount Abu Winter Festival', ARRAY['Mount Abu Tourism Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Hill Station Heritage', 'A delightful year-end festival celebrating the scenic beauty, cool mountain air, and tribal folk culture of Rajasthan''s only hill station.', 'Jointly established by Rajasthan Tourism and the Municipal Board of Mount Abu to celebrate the winter season.', 'Celebrates the pleasant chill of the Aravalli highlands, boat culture on Nakki Lake, and indigenous Garasia tribal arts.', 'To provide a celebratory year-end carnival for domestic and international travelers.', 'Showcases Rajasthan''s surprising alpine identity with cool morning mists, pine trees, and serene mountain lakes.', 'Concludes on New Year''s Eve with a spectacular midnight countdown, fireworks, and live rock and classical concerts.', ARRAY['Procession starting from RTDC Hotel Shikhar winding down to Nakki Lake', 'Rowing and boat racing competitions on scenic Nakki Lake', 'Deepdaan ceremony where hundreds of floating lamps are released on the lake at dusk']::TEXT[], 'Visitors stroll along lakeside promenades in warm woolens, shopping at Tibetan craft markets and watching lively folk dances.', ARRAY['Dal Baati Churma', 'Garam Masala Chai', 'Gajar Ka Halwa', 'Corn Tikki', 'Rajasthani Chaat']::TEXT[], 'Winter woolens: stylish jackets, woolen caps, colorful Kashmiri shawls, and Rajasthani bandhani stoles.', 'Folk dances: Ghoomar, Kalbelia, tribal Gair dance by Garasia artists, alongside live fusion bands.', 'Toad Rock silhouette, tranquil waters of Nakki Lake, and blooming garden terraces.', '3 Days', 'Gregorian / Year-End', 'December 29 to 31 annually.', 'December', 'FIXED', 'Held annually December 29-31.', '2026-12-29', '2027-12-29', 'Rajasthan Tourism & Municipal Board Mount Abu', ARRAY['Rajasthan']::TEXT[], ARRAY['Mount Abu', 'Sirohi']::TEXT[], ARRAY['Nakki Lake Promenade', 'Polo Ground Mount Abu']::TEXT[], 'Evenings at Nakki Lake for boat illumination and midnight New Year''s Eve celebrations', 2, 'Refreshing hill-station crispness amidst the arid plains, romantic boat rides, crackling bonfires, and infectious year-end cheer.', 'Abu Road Railway Station (28 km); accessible by mountain road taxis and state transport buses.', 'Huge range of mountain resorts, colonial-era bungalows, and hotels in Mount Abu.', 'Very heavy tourist rush over New Year''s Eve; book hotel rooms and parking permits weeks ahead.', 'Eco-sensitive wildlife zone; do not play loud car music in forest areas or feed wild langurs.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ranakpur-festival', 'Ranakpur Temple Festival', ARRAY['Ranakpur Jawai Cultural Festival']::TEXT[], 'Art & Cultural Festival', 'Jain Sacred Architecture & Music', 'A sublime cultural and spiritual festival held in the sun-dappled valley of Ranakpur against the miraculous 15th-century carved marble temple of 1,444 pillars.', 'Organized by Rajasthan Tourism inside the secluded valley of the Aravallis, celebrating the Jain architectural wonder built by Dharna Shah in 1437 CE.', 'Celebrates the transcendent spiritual serenity and sculptural perfection of Jain sacred art.', 'To promote cultural tourism to Ranakpur and the nearby Jawai leopard conservation landscape.', 'The Ranakpur Jain Temple is world-renowned: no two of its 1,444 intricately carved marble pillars are identical.', 'Features evening open-air classical concerts where light and music reflect off translucent white marble arches.', ARRAY['Morning yoga and meditation sessions in the tranquil temple gardens', 'Illumination of the temple''s 1,444 carved marble pillars with warm golden lights', 'Classical vocal and instrumental recitals by celebrated maestros on the temple lawns']::TEXT[], 'Travelers marvel at the unbelievable stone filigree and lace-like carvings, followed by night safaris to spot wild leopards on granite rocks.', ARRAY['Pure Jain vegetarian feast', 'Sattvic Khichdi', 'Dal Baati', 'Kaju Katli', 'Almond Milk']::TEXT[], 'Refined Indian ethnic attire: white kurtas, light cotton dhotis, and elegant sarees.', 'Classical Indian instrumental music: flute, santoor, sitar, and devotional Jain stavan singing.', '1,444 hand-carved marble pillars, lotus ceiling rosettes, and forested Aravalli mountain backdrops.', '2 Days', 'Gregorian / Winter', 'December 21 and 22 annually.', 'December', 'FIXED', 'Held annually December 21-22.', '2026-12-21', '2027-12-21', 'Rajasthan Tourism & Ranakpur Temple Trust', ARRAY['Rajasthan']::TEXT[], ARRAY['Ranakpur', 'Sadri', 'Pali']::TEXT[], ARRAY['Ranakpur Jain Temple Complex', 'Jawai Leopard Reserve']::TEXT[], 'Morning temple architecture walkthrough and evening classical musical concert', 2, 'Breathtaking architectural wonder of translucent white marble glowing in warm light, serene spiritual silence, and thrilling wild leopard sightings.', '95 km from Udaipur Airport; 35 km from Falna railway station; accessible by taxi.', 'Luxury safari lodges in Jawai and heritage resorts near Ranakpur temple.', 'Strict Jain religious guidelines: leather items (shoes, belts, wallets) strictly prohibited inside temple complex.', 'Dress modestly covering shoulders and knees; maintain peaceful contemplative silence inside prayer halls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-karni-mata-fair-deshnoke', 'Karni Mata Fair Deshnoke', ARRAY['Deshnoke Rat Temple Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Charan Folk Shaktism)', 'The extraordinary sacred fair held at the world-famous Karni Mata Temple in Deshnoke, where over 25,000 sacred black rats (Kabas) are revered and fed.', 'Dates back to the 15th century, honoring Karni Mata, a revered female mystic and incarnation of Goddess Durga worshipped by Charan and Rajput communities.', 'According to legend, the deceased children of Karni Mata''s clan are reincarnated as sacred rats (Kabas) until their rebirth as humans.', 'To seek blessings of Karni Mata for safety, courage, and family health, and sight an auspicious white rat.', 'Unrivaled anthropological and religious marvel: thousands of rats drink milk alongside devotees without any history of disease.', 'Sighting one of the few rare white rats among the 25,000 black rats is considered supreme good fortune and divine blessing.', ARRAY['Offering large bowls of milk, sweets, and grains to thousands of sacred rats in the marble courtyard', 'Searching for the rare white rat to receive special divine grace', 'Grand aarti with silver lamps and chanting of Karni Mata Chirjas (ballads)']::TEXT[], 'Pilgrims walk barefoot through the marble corridors, stepping carefully to avoid disturbing the thousands of revered rodents scurrying around their feet.', ARRAY['Prasad laddoos nibbled by the sacred rats (considered highly auspicious)', 'Peda', 'Halwa', 'Puri Sabzi']::TEXT[], 'Traditional Rajasthani attire: red and saffron turbans, kurtas, dhotis, and colorful odhnis.', 'Chanting of devotional Chirja ballads by Charan bards, accompanied by dholak and cymbals.', 'Carved silver doors of Deshnoke temple, marble rat reliefs, and brass bowls filled with milk.', '9 Days', 'Hindu Lunisolar', 'Celebrated twice a year during Navratri (Chaitra and Ashwin)', 'April & October', 'LUNISOLAR', 'Observed during Chaitra Navratri and Ashwin Navratri.', '2026-10-15', '2027-10-05', 'Shri Karni Mandir Trust Deshnoke & Bikaner Administration', ARRAY['Rajasthan']::TEXT[], ARRAY['Deshnoke', 'Bikaner']::TEXT[], ARRAY['Karni Mata Temple Deshnoke']::TEXT[], 'Morning aarti at 6 AM when hundreds of rats gather around large milk basins', 1, 'Astonishing, mind-expanding spiritual phenomenon that challenges rational perception, filled with profound, fearless rural devotion.', '30 km south of Bikaner on the Jodhpur highway; easily reached by local train, bus, or taxi.', 'Hotels in Bikaner city; simple dharamshalas at Deshnoke.', 'Footwear must be removed outside; walking barefoot among scurrying rats is mandatory; watch your step to avoid harming any animal.', 'Keep calm and respectful; the rats are gentle, accustomed to humans, and completely harmless.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bikaner.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kota-dussehra', 'Kota Dussehra Fair', ARRAY['National Kota Dussehra Mela']::TEXT[], 'Historical & Royal', 'Hinduism (Epic Victory Pageantry)', 'A monumental 25-day celebration featuring India''s tallest effigies of Ravana, Kumbhakarna, and Meghnada standing over 80 feet tall on Dussehra Maidan.', 'Instituted in 1723 CE by Maharao Durjan Sal Singh of Kota, transforming an ancient religious rite into an epic civic and royal festival.', 'Celebrates the victory of Lord Rama over the demon king Ravana, symbolizing truth triumphing over injustice.', 'To honor the heroic martial traditions of the Harauti region and enjoy the longest post-Dussehra rural trade fair in northern India.', 'Distinguished by its colossal effigies, which are packed with artistic fireworks and burst with spectacular light sequences.', 'Preceded by a grand royal procession of the titular Maharao of Kota riding a caparisoned elephant from City Palace to the fairgrounds.', ARRAY['Royal religious procession with palanquins and decorated cavalry from Kota Garh', 'Thunderous shooting of flaming arrows setting ablaze the 80-foot effigies of Ravana', '25-day national trade fair, all-India wrestling competitions, and Kavi Sammelans']::TEXT[], 'Hundreds of thousands of spectators pack the vast stadium, gasping in awe as fireworks shoot from Ravana''s multiple heads before exploding in flames.', ARRAY['Kota Kachori (famous spicy urad dal kachori with asafoetida)', 'Jalebi', 'Rabri', 'Dal Baati', 'Chana Zor Garam']::TEXT[], 'Traditional Harauti dhotis, bright colorful turbans, and festive Rajasthani ethnic wear.', 'Thunderous fireworks, brass royal bands, Kavi Sammelan poetic recitals, and Rajasthani folk dances.', '80-foot towering painted effigy of Ravana with glowing eyes, flaming arrows, and royal Kota palace flags.', '25 Days', 'Hindu Lunisolar', 'Begins on Vijyadashami (Dashami of Ashwin Shukla Paksha)', 'October', 'LUNISOLAR', 'Begins on Vijyadashami day.', '2026-10-20', '2027-10-10', 'Municipal Corporation Kota & Rajasthan Tourism', ARRAY['Rajasthan']::TEXT[], ARRAY['Kota']::TEXT[], ARRAY['Dussehra Maidan Kota', 'Kota Garh (City Palace)']::TEXT[], 'Vijyadashami evening between 5 PM and 8 PM for the effigy burning spectacle', 3, 'Colossal visual energy, thunderous explosions of fireworks lighting up the night sky, and exhilarating carnival atmosphere.', 'Kota Junction is a major railway station on the Delhi-Mumbai line; accessible by superfast trains.', 'Hotels throughout Kota city; book well ahead for Dussehra week.', 'Vast crowds exceeding 300,000 on burning night; enter stadium enclosures by 4:30 PM.', 'Maintain safe distance from burning effigies; follow directions of city police and fire marshals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kota.rajasthan.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rann-utsav-kutch', 'Rann Utsav Kutch', ARRAY['White Desert Festival of Kutch']::TEXT[], 'Art & Cultural Festival', 'Secular / Desert Salt Marsh & Tribal Crafts', 'A world-famous three-month winter festival staged on the endless white salt desert of the Great Rann of Kutch under the dazzling full moon.', 'Conceptualized in 2006 by the Gujarat Government to turn an inaccessible salt wilderness into an internationally acclaimed cultural tourism destination.', 'Celebrates the natural phenomenon of the white salt desert, Kutchi artisan handicrafts, and desert folk music.', 'To empower indigenous Kutchi artisan communities (Rogan, Ajrakh, Bandhani, Mud mirror work) through sustainable cultural tourism.', 'Transformed Dhordo village into a UNWTO-recognized Best Tourism Village of the World.', 'The blinding white salt plains stretch to the horizon, glowing with eerie silvery brilliance under the full moon night sky.', ARRAY['Moonlit walks across the crystalline white salt desert', 'Paramotoring, camel cart safaris, and ATV rides across salt flats', 'Nightly cultural concerts in the Tent City amphitheatre featuring Kutchi folk musicians']::TEXT[], 'Visitors stay in luxury Swiss tents, browse vibrant artisan craft bazaars, taste authentic Gujarati thalis, and ride camel carts into the white wilderness.', ARRAY['Kutchi Dabeli', 'Khichdi with Kadhi and Ringna no Oro', 'Jalebi Fafda', 'Gulab Pak', 'Chaash (buttermilk)']::TEXT[], 'Intricate Kutchi embroidered chaniyas with mirror work, bandhani dupattas, and Kediyu tunics with dhoti.', 'Soulful Kutchi and Sufi folk music with Jodiya Pawa (double flute), Morchang, and energetic Garba round dances.', 'Endless white salt flats, colorful Kutchi Bhungas (mud roundhouses), and radiant full moon.', '3 to 4 Months', 'Seasonal / Winter', 'November to February annually; peaks on full moon nights.', 'November - February', 'SEASONAL', 'Full season runs November to February.', '2026-11-15', '2027-11-15', 'Gujarat Tourism & Tent City Dhordo', ARRAY['Gujarat']::TEXT[], ARRAY['Dhordo', 'Bhuj', 'Kutch']::TEXT[], ARRAY['White Desert Dhordo', 'Kala Dungar', 'Gandhi nu Gam Ludiya']::TEXT[], 'Full moon night and sunrise/sunset over the white salt plains', 3, 'Surreal, otherworldly visual magic of walking on an infinite ocean of sparkling white salt crystals under a starry sky.', '80 km from Bhuj Airport and railway station; regular tourist coach buses and pre-booked taxis.', 'Luxury tented township at Tent City Dhordo, white desert resorts, and authentic village homestays in traditional Bhungas.', 'Warm sunny days but cold winter desert nights (down to 5°C); pack heavy warm woolens and jackets.', 'Permit required to enter the White Desert (available online or at Bhirandiyara checkpost); carry valid government photo ID.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://rannutsav.net', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-international-kite-festival', 'International Kite Festival (Uttarayan)', ARRAY['Makar Sankranti Gujarat']::TEXT[], 'Seasonal & Nature', 'Secular / Solar Heritage & Aerobatics', 'The sky-filling extravaganza where millions of colorful kites soar over Ahmedabad rooftops and Sabarmati Riverfront, celebrating the sun''s northern journey.', 'Celebrated since ancient times as Makar Sankranti; officially elevated in 1989 into an international festival bringing master kite flyers from over 45 nations.', 'Commemorates the sun entering the zodiac sign of Capricorn (Makara), heralding longer days and the end of winter.', 'To celebrate solar vitality, community rooftop togetherness, and aerial craftsmanship.', 'Ahmedabad''s skies become a living kaleidoscope of colors, with the famous cry ''Kai Po Che!'' (I have cut it!) echoing from millions of rooftops.', 'Includes the nighttime spectacle of ''Tukkals'' (illuminated paper lanterns) strung along kite lines, lighting up the midnight sky.', ARRAY['Fierce rooftop kite battles from sunrise to sunset with glass-coated cotton manjha', 'Nighttime release of thousands of glowing paper lantern kites (Tukkals)', 'Master kite demonstrations at Sabarmati Riverfront featuring giant inflatable dragons and octopuses']::TEXT[], 'Entire families spend two straight days on rooftops, playing high-energy music, cutting competitor kites, and sharing hot winter delicacies.', ARRAY['Undhiyu (slow-cooked winter vegetable casserole in earthen pots)', 'Jalebi', 'Til Chikki', 'Mamra Ladoo', 'Bor (wild berries)']::TEXT[], 'Comfortable casual clothing, colorful cotton bandhani dupattas, caps, and sunglasses.', 'High-energy rooftop music systems, dhol beats, and spontaneous celebratory Garba steps on terraces.', 'Diamond-shaped paper kites (Patang), wooden spools (Firki), sky lanterns (Tukkals), and rooftop silhouettes.', '2 Days', 'Solar / Makar Sankranti', 'January 14 and 15 annually (Uttarayan and Vasi Uttarayan).', 'January', 'FIXED', 'Celebrated January 14-15 every year.', '2026-01-14', '2027-01-14', 'Gujarat Tourism & Ahmedabad Municipal Corporation', ARRAY['Gujarat']::TEXT[], ARRAY['Ahmedabad', 'Surat', 'Vadodara', 'Rajkot']::TEXT[], ARRAY['Sabarmati Riverfront Ahmedabad', 'Old City Pol Rooftops']::TEXT[], 'Sunrise to sunset on January 14 on an authentic Old City heritage rooftop', 2, 'Unrivaled collective joy, exhilarating aerial battles, rooftop music, and the delicious aroma of fresh Undhiyu floating on the winter breeze.', 'Sardar Vallabhbhai Patel International Airport Ahmedabad; Ahmedabad Metro and cab services.', 'Heritage havelis in the Old Pols of Ahmedabad and modern hotels across the city.', 'Kite strings (manjha) can cause cuts; wear protective tape on fingers; never grab falling kites near roads or power lines.', 'Bird-friendly flying: stop flying during dawn and dusk hours (6-8 AM and 5-7 PM) to protect birds from string injuries.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gujarattourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-navratri-garba-gujarat', 'Navratri Garba Mahotsav', ARRAY['World''s Longest Dance Festival']::TEXT[], 'Art & Cultural Festival', 'Hinduism (Shaktism & Community Dance)', 'The world''s largest nine-night dance festival where millions of people dance in synchronized concentric circles celebrating the Mother Goddess.', 'Ancient Shakta tradition documented in Puranas; popularized into massive community circular dances in Gujarat over the past two centuries.', 'Commemorates the triumph of Goddess Durga over the buffalo demon Mahishasura after nine days of fierce battle.', 'To honor the nine divine forms of Goddess Durga (Navadurga) and seek cosmic feminine energy (Shakti).', 'Inscribed on UNESCO''s Representative List of the Intangible Cultural Heritage of Humanity in 2023.', 'Known for its extraordinary discipline, universal participation across ages, and zero-alcohol energetic dance marathons lasting past midnight.', ARRAY['Aarti of the sacred perforated earthen pot (Garbo) containing a glowing oil lamp', 'Traditional circular Garba dance with rhythmic two-clap and three-clap movements', 'Fast-paced Dandiya Raas with polished wooden sticks clacking in sync']::TEXT[], 'Vast illuminated venues host up to 50,000 dancers in dazzling mirror-work costumes dancing seamlessly around a flower-draped central shrine.', ARRAY['Fafda and Jalebi (eaten especially on Dussehra morning)', 'Khaman Dhokla', 'Sabudana Khichdi (fasting food)', 'Singhare Ke Pakore']::TEXT[], 'Chaniya Choli with heavy mirror work, Rabari embroidery, and oxidized silver jewelry for women; Kedia and dhotis for men.', 'Live orchestra with traditional Dhol, Dholak, Shehnai, keyboard, and soul-stirring Gujarati devotional Garba singing.', 'Perforated earthen pot (Garbi) with glowing flame, colorful wooden dandiya sticks, and multi-layered circular dance formations.', '9 Nights', 'Hindu Lunisolar', 'Ashwin Shukla Pratipada to Navami (September - October)', 'September - October', 'LUNISOLAR', 'Celebrated for 9 nights in Ashwin month.', '2026-10-11', '2027-09-30', 'Gujarat Tourism & Vadodara Navratri Festival (VNF)', ARRAY['Gujarat']::TEXT[], ARRAY['Vadodara', 'Ahmedabad', 'Surat', 'Rajkot']::TEXT[], ARRAY['United Way Garba Vadodara', 'GMDC Ground Ahmedabad', 'University Grounds']::TEXT[], 'Night from 9 PM to 2 AM when the synchronized dancing reaches peak euphoria', 3, 'Mind-blowing, hypnotic visual spectacle of 40,000 dancers swirling in perfect unison like a vibrant living mandala of devotion and joy.', 'Easily accessible across Ahmedabad and Vadodara via metro, cabs, and late-night festival shuttle buses.', 'Hotels throughout Gujarat cities; book 2-3 months in advance as diaspora visitors arrive in millions.', 'Massive attendance; passes for major venues like United Way Vadodara require prior online registration.', 'Traditional dress code is strictly mandatory for entering the inner dancing circle (Garba ground); non-dancers can view from stadium stands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gujarattourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-modhera-dance-festival', 'Modhera Dance Festival Sun Temple', ARRAY['Uttarardh Mahotsav Modhera']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & Solar Architecture', 'A breathtaking three-day festival of classical Indian dance staged against the intricately sculpted 11th-century Sun Temple of Modhera.', 'Established by the Tourism Corporation of Gujarat to celebrate classical performing arts at the architectural marvel built by King Bhima I of the Chaulukya dynasty in 1026 CE.', 'Celebrates Uttarardh (the sun''s northern transit after Makar Sankranti) and the eternal cosmic dance of time and light.', 'To revive the cultural traditions of temple dance and highlight the architectural genius of Gujarat''s Solanki style.', 'Staged against the monumental Sabha Mandap (Hall of Religious Gatherings) and the grand stepped water reservoir (Surya Kund).', 'Showcases the finest classical dancers of Bharatanatyam, Kathak, Odissi, Kuchipudi, and Mohiniyattam under dramatic golden floodlights.', ARRAY['Illumination of the 1,000-year-old stone temple facade and Surya Kund steps', 'Evening classical dance recitals by legendary national maestros', 'Daytime heritage walks explaining the solar alignment of the temple sanctum']::TEXT[], 'Connoisseurs sit along the stone steps under the cool winter sky, watching classical dancers perform to live mridangam and flute melodies.', ARRAY['Gujarati Thali', 'Handvo', 'Lilva Kachori', 'Ghevar', 'Masala Chaas']::TEXT[], 'Refined ethnic formal wear: handloom silk sarees, Bandhani dupattas, and kurtas with jackets.', 'Sublime classical dance dramas, Carnatic and Hindustani classical music, and resonant Vedic chanting.', 'Carved stone pillars of Sabha Mandap, stepped terraces of Surya Kund, and golden temple floodlights.', '3 Days', 'Solar / Cultural', 'Third weekend of January annually (following Uttarayan).', 'January', 'FIXED', 'Third Friday to Sunday of January.', '2026-01-16', '2027-01-15', 'Gujarat Tourism & Department of Culture', ARRAY['Gujarat']::TEXT[], ARRAY['Modhera', 'Mehsana', 'Patan']::TEXT[], ARRAY['Sun Temple Complex Modhera']::TEXT[], 'Evenings between 6:30 PM and 9:30 PM during floodlit dance recitals', 2, 'Soul-stirring, surreal aesthetic experience where 1,000-year-old carved stone gods seem to come alive in rhythm with classical dancers.', '100 km north of Ahmedabad (2-hour drive via 4-lane highway); 25 km from Mehsana railway station.', 'Hotels in Mehsana, Patan, or luxury eco-resorts near Modhera.', 'Chilly January evenings; carry warm shawls or jackets.', 'Strict archaeological protection: no touching or climbing on delicate ancient temple carvings.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gujarattourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tarnetar-fair', 'Tarnetar Fair Surendranagar', ARRAY['Trinetreshwar Mahadev Mela']::TEXT[], 'Tribal & Folk Traditions', 'Hinduism (Folk Shaktism & Pastoral Romance)', 'The legendary rural romance and folk fair held around the ancient Trinetreshwar Mahadev Temple, famous for mirror-embroidered umbrellas and Raas dancing.', 'Dates back centuries, rooted in the folk legend of the Mahabharata where Arjuna pierced the eye of the rotating fish (Matsyavedha) at Draupadi''s Swayamvar.', 'Celebrates youth, romance, martial archery skill, and the blessings of Lord Shiva.', 'Historically serves as a traditional matrimonial fair where young tribal men and women meet and choose life partners.', 'World-renowned for its dazzling hand-embroidered umbrellas (Chhatris) embellished with mirrors, beads, and lace by Bharwad pastoralists.', 'Features massive circles of up to 200 dancers performing the spirited ''Rahado'' folk dance accompanied by multiple dhol drums.', ARRAY['Ritual flag hoisting and darshan at the 10th-century Trinetreshwar Temple', 'Grand Rahado and Raas folk dance competitions with circular movements', 'Showcase of hand-embroidered pastoral umbrellas and traditional costume judging']::TEXT[], 'The vast village common turns into a vibrant sea of swirling colorful costumes, embroidery, pastoral livestock, and joyful music.', ARRAY['Bajra no Rotlo with Ringna no Oro', 'Makhan', 'Jalebi', 'Fafda', 'Sev Khamani']::TEXT[], 'Bharwad men wear white dhotis with embroidered red borders, ornate turbans, and carry embroidered umbrellas; women wear bright Zini Chaniyas.', 'Energetic Rahado pastoral dances, continuous high-tempo Dhol rhythms, and resonant Shenai melodies.', 'Mirror-embroidered velvet umbrellas, Kund water reflections, and colorful flags atop Trinetreshwar temple.', '3 Days', 'Hindu Lunisolar', 'Bhadrapada Shukla Chaturthi, Panchami, and Shashti (August - September)', 'August - September', 'LUNISOLAR', 'Celebrated on Bhadrapada Shukla 4-6.', '2026-09-15', '2027-09-05', 'Surendranagar District Administration & Gujarat Tourism', ARRAY['Gujarat']::TEXT[], ARRAY['Tarnetar', 'Thangadh', 'Surendranagar']::TEXT[], ARRAY['Trinetreshwar Mahadev Temple Grounds Tarnetar']::TEXT[], 'Daytime from 11 AM to 5 PM for the grandest Rahado dance circles and umbrella displays', 2, 'Intoxicating rural energy, breathtaking artisanal embroidery, infectious drumbeats, and authentic tribal pastoral joy.', '70 km from Rajkot and 190 km from Ahmedabad; nearest railway station is Thangadh (10 km).', 'Tented tourist village set up by Gujarat Tourism at Tarnetar, or hotels in Rajkot and Surendranagar.', 'Hot and sunny daytime; carry sun hats, sunglasses, and bottled water.', 'Respect the privacy of pastoral youth; ask politely before taking close-up portraits of traditional dancers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gujarattourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhavnath-mahadev-fair', 'Bhavnath Mahadev Fair Girnar Junagadh', ARRAY['Maha Shivratri Girnar Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Naga Sadhus & Shaivite Mysticism)', 'The mystical midnight gathering of thousands of naked Naga sadhus who march down holy Mount Girnar to bathe in the sacred Mrigi Kund on Maha Shivratri.', 'Ancient Shaivite gathering described in Puranic texts, set in the deep forested valley below sacred Mount Girnar.', 'Celebrates the divine marriage of Lord Shiva and Devi Parvati and the immortal ascetic traditions of the Nath and Giri sects.', 'To receive the darshan and blessings of mystical Siddha ascetics and witness the sacred midnight holy dip.', 'According to legend, Lord Shiva himself visits the fair invisibly, and Nine Naths and 84 Siddhas dwell in the Girnar caves.', 'The midnight procession of naked Naga sadhus riding decorated elephants and wielding swords is one of the most intense spiritual sights in India.', ARRAY['Midnight Shahi Snan (royal bath) of Naga sadhus in the sacred Mrigi Kund waters', 'Procession of Dashnami Akhara ascetics with conch shells and sacred flags', 'Continuous distribution of Mahaprasad at hundreds of free community kitchens (Annakshetras)']::TEXT[], 'Over one million devotees pack the jungle valley, chanting ''Har Har Mahadev'' as the air fills with dhoop incense, conch blasts, and holy ash.', ARRAY['Puri with Potato curry', 'Khichdi with Ghee', 'Langar Kheer', 'Tea and fruit offerings']::TEXT[], 'Saffron and white robes of pilgrims; Naga sadhus covered in sacred ash (Vibhuti) and Rudraksha beads.', 'Thunderous conch shell blasts, metal damaru drums, chimta cymbals, and ecstatic Shaivite chants.', 'Mount Girnar forested peaks, sacred Mrigi Kund stone tank, trident standards, and burning Dhunis (sacred fires).', '5 Days', 'Hindu Lunisolar', 'Magha Krishna Dashami to Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Culminates on Maha Shivratri midnight.', '2026-02-15', '2027-03-06', 'Junagadh District Administration & Bhavnath Temple Trust', ARRAY['Gujarat']::TEXT[], ARRAY['Junagadh', 'Mount Girnar']::TEXT[], ARRAY['Bhavnath Mahadev Temple', 'Mrigi Kund Foothills']::TEXT[], 'Maha Shivratri night from 10 PM to 2 AM for the midnight Naga Sadhu procession', 2, 'Deeply intense, mystical spiritual encounter with ancient ascetic traditions in a wild forested mountain valley.', '8 km from Junagadh railway station; easily reached by auto-rickshaw or mela shuttle buses.', 'Dharamshalas and hotels in Junagadh city; book rooms months in advance.', 'Massive crowd crush around Mrigi Kund at midnight; stay in designated visitor galleries.', 'Show deep reverence to ascetics; never photograph Naga sadhus without their explicit permission.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://junagadh.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-madhavpur-fair', 'Madhavpur Ghed Fair Porbandar', ARRAY['Rukmini Krishna Vivah Utsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / National Integration)', 'The vibrant festival celebrating the immortal marriage of Lord Krishna of Gujarat with Princess Rukmini of Arunachal Pradesh on the Arabian Sea coast.', 'Centuries-old festival celebrating the mythological wedding described in the Srimad Bhagavatam, connecting India''s western and north-eastern frontiers.', 'Commemorates Lord Krishna bringing Rukmini from Kundinapuri (northeast) to Madhavpur to wed her according to Vedic rites.', 'To celebrate the divine marriage and the civilizational bridge connecting Gujarat with the 8 North-Eastern states.', 'Now organized as a landmark National Integration festival by the Ministry of Culture, featuring cultural troupes from all eight North-East states.', 'Features a colorful royal chariot procession (Varnagi) where Lord Krishna''s palanquin is carried across coastal sands to the wedding pavilion.', ARRAY['Grand wedding rituals (Vivah Vidhi) performed at Madhavrai Temple', 'Spectacular cultural exchange concerts featuring North-Eastern folk dances (Bihu, Manipuri, Cheraw) alongside Gujarati Garba', 'Royal chariot procession down to the golden Arabian Sea beach']::TEXT[], 'Thousands of villagers gather in the coastal town, throwing gulal, singing wedding songs, and celebrating the unique union of western and eastern Indian cultures.', ARRAY['Ghed region Jalebi', 'Khaman', 'Undhiyu', 'Puri with mango ras', 'Khichdi']::TEXT[], 'Gujarati traditional attire alongside colorful tribal handlooms of Arunachal, Assam, and Manipur.', 'Fascinating blend of Gujarati Raas-Garba and North-Eastern dances (Assamese Bihu, Manipuri Raas, Naga warrior dances).', 'Ornate wooden marriage chariot (Rath), Madhavrai temple spires, and azure Arabian Sea shoreline.', '5 Days', 'Hindu Lunisolar', 'Begins on Ram Navami (Chaitra Shukla Navami) in March - April', 'March - April', 'LUNISOLAR', 'Begins on Chaitra Shukla Navami.', '2026-03-27', '2027-04-15', 'Ministry of Culture & Gujarat Tourism', ARRAY['Gujarat']::TEXT[], ARRAY['Madhavpur Ghed', 'Porbandar']::TEXT[], ARRAY['Madhavrai Temple Complex', 'Madhavpur Beach']::TEXT[], 'Chaitra Shukla Dwadashi for the grand wedding chariot procession to the beach', 2, 'Joyful coastal wedding celebration blending the gentle Arabian Sea breeze with rich cultural performances from India''s farthest frontiers.', '60 km south of Porbandar; 120 km from Somnath; easily accessible by coastal highway.', 'Guesthouses in Madhavpur or hotels in Porbandar city.', 'Coastal sunshine; carry sun protection and comfortable beach walking shoes.', 'Respect the solemnity of Vedic wedding rituals; enjoy the multicultural performances.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://porbandar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-vautha-fair', 'Vautha Donkey & Cattle Fair', ARRAY['Vautha Mela']::TEXT[], 'Fair & Mela', 'Hinduism & Pastoral Trade', 'A fascinating historic animal fair held at the holy confluence of seven sacred rivers (Saptasangam), famous for thousands of colorfully painted and decorated donkeys.', 'Dates back centuries, centered around the sanctified confluence of Vatrak, Meshwo, Mazam, Shedhi, Sabarmati, Guhai, and Hathmati rivers.', 'Celebrates the confluence where Kartikeya (son of Shiva) visited during his circumambulation of the earth.', 'To take holy cleansing dips at the Saptasangam on Kartik Purnima and trade pastoral donkeys, camels, and cattle.', 'The largest animal fair in Gujarat, famous for the extraordinary practice of painting donkeys in neon pinks, greens, and blues for sale.', 'Over 20,000 donkeys, along with camels and bullocks, are traded by pastoral nomadic communities (Vanjara, Rabari).', ARRAY['Holy cleansing dip in the Saptasangam river confluence at sunrise', 'Display and trading of donkeys painted with decorative dots, zebra stripes, and dyed ears', 'Evening riverbank Aarti with floating clay lamps on the dark river waters']::TEXT[], 'Pastoralists pitch thousands of colorful tents on the sandy riverbanks, roasting rotlas over wood fires and parading their prize animals.', ARRAY['Bajra no Rotlo with butter and jaggery', 'Kadhi', 'Khichdi', 'Fresh Jalebi', 'Gota']::TEXT[], 'Traditional Vanjara and Rabari tribal dresses with heavy silver jewelry, turbans, and mirrored waistcoats.', 'Rustic folk songs of the Vanjara nomads, Ravanhatha melodies, and lively evening Garba around campfires.', 'River confluence sandbanks, colorfully painted donkeys with bells, and tented nomadic encampments.', '5 Days', 'Hindu Lunisolar', 'Culminates on Kartik Purnima (November)', 'November', 'LUNISOLAR', 'Culminates on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Ahmedabad District Administration & Dholka Taluka Panchayat', ARRAY['Gujarat']::TEXT[], ARRAY['Vautha', 'Dholka', 'Ahmedabad']::TEXT[], ARRAY['Saptasangam Riverbanks Vautha']::TEXT[], 'Kartik Purnima dawn for the sacred river dip and daytime donkey market', 2, 'Authentic, unvarnished rural spectacle of nomadic desert life, crackling campfires, and painted donkeys across wide river sands.', '60 km south of Ahmedabad; accessible by road via Dholka.', 'Rustic camping on riverbanks or stay in Ahmedabad hotels and visit as a day trip.', 'Dusty riverbed terrain; wear sturdy walking boots and carry dust protection.', 'Treat the animals with compassion; negotiate photography with nomadic owners respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ahmedabad.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shamlaji-fair', 'Shamlaji Fair Aravalli', ARRAY['Gadhadhar Mahatirth Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism & Tribal Vaishnavism', 'A massive three-week tribal and Hindu pilgrimage fair held on the banks of holy river Meshwo at the 11th-century carved shrine of Lord Shamlaji (Dark Krishna).', 'Ancient shrine dating back over 1,000 years, constructed in fine white and grey sandstone adorned with thousands of carved elephants and deities.', 'Celebrates Lord Vishnu as Gadhadhar (bearer of the mace) and honors ancestral tribal ties.', 'To take holy dips in the sacred Karmanbhai Kund and pray for fertility, agricultural prosperity, and spiritual liberation.', 'Vital cultural bridge between the tribal communities of Gujarat and southern Rajasthan (Bhil and Garasia tribes).', 'Known in tribal folk songs as ''Shamlaji na Mele Re, Ranjhaniyu Vaje'' (cymbals ringing at Shamlaji Fair).', ARRAY['Holy bath in the Meshwo river and sacred temple Kund on Kartik Purnima', 'Procession carrying traditional tribal flags (Dhwaja) to the temple spire', 'Bustling tribal trading fair with traditional silver jewelry and brassware']::TEXT[], 'Over 200,000 tribal pilgrims from Gujarat and Rajasthan arrive singing devotional songs, playing flutes, and dancing down temple ghats.', ARRAY['Kansar sweet dish', 'Dal Baati', 'Kachori', 'Ghevar', 'Makai no Rotlo']::TEXT[], 'Bhil and Garasia tribal costumes: colorful turbans, silver hasli torque necklaces, and bright embroidered skirts.', 'Tribal flutes, Dhol drums, and rhythmic circular Garba danced by thousands of devotees.', 'Carved sandstone elephants of Shamlaji temple, sacred Meshwo river, and colorful tribal flags.', '21 Days', 'Hindu Lunisolar', 'Begins on Dev Uthani Ekadashi and peaks on Kartik Purnima', 'November', 'LUNISOLAR', 'Peaks on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Aravalli District Administration & Shamlaji Temple Trust', ARRAY['Gujarat']::TEXT[], ARRAY['Shamlaji', 'Aravalli']::TEXT[], ARRAY['Shamlaji Temple Complex', 'Meshwo Riverbanks']::TEXT[], 'Kartik Purnima day and night for peak tribal gatherings and flag processions', 2, 'Vibrant tribal devotion, stunning 1,000-year-old architectural carvings, and echoing folk cymbals in a scenic river valley.', '125 km northeast of Ahmedabad on NH-8 (Delhi-Mumbai highway); accessible by bus and taxi.', 'Temple dharamshalas at Shamlaji and hotels in nearby Himmatnagar.', 'Dense crowds around temple steps on Kartik Purnima; follow police queue lanes.', 'Respect tribal traditions; purchase authentic tribal crafts from local artisan stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://arvalli.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kavant-fair', 'Kavant Tribal Fair Chhota Udepur', ARRAY['Rathwa Tribal Carnival']::TEXT[], 'Tribal & Folk Traditions', 'Rathwa Indigenous Animism', 'An exhilarating, sensory-charged tribal festival where Rathwa men paint their entire bodies with white ash and clay patterns, dancing with huge peacocks-feather headdresses.', 'Ancient tribal festival celebrated after Holi by the Rathwa tribe of Chhota Udepur, rooted in indigenous Pithora painting traditions.', 'Celebrates the end of the harvest, divine fertility, and thanksgiving to the supreme deity Baba Pithora.', 'To express tribal joy, thank ancestral spirits for crop abundance, and celebrate youth vitality.', 'One of the most visually stunning indigenous tribal celebrations in western India, untouched by commercialization.', 'Performers balance heavy belts of brass bells (Ghungroos) weighing up to 10 kilograms, creating a hypnotic acoustic rhythm.', ARRAY['Body painting with sacred white ash, lime, and rice paste into tiger and bird stripes', 'Dancing with colossal peacock-feather standards (Pankha) towering 10 feet above head', 'Continuous rhythmic stamping of feet to ring dozens of heavy brass bells tied to the waist']::TEXT[], 'Hundreds of painted warriors leap and stamp through village streets in synchronized rhythm, creating a thundering acoustic wave of bells and drums.', ARRAY['Mahua wine (traditional sacred brew)', 'Makai no Rotlo with spicy chutney', 'Smoked meat delicacies', 'Jaggery sweets']::TEXT[], 'Minimal loincloths with bodies completely painted in white and red dots and stripes; colossal peacock-feather crowns.', 'Hypnotic, relentless brass bell rhythms, wooden flutes (Peeho), and deep tribal drumbeats.', 'Sacred Pithora mural imagery, peacock-feather crests, and white-painted tribal bodies.', '1 Day', 'Hindu Lunisolar / Spring', 'Celebrated on the third day after Holi (Rang Panchami season).', 'March', 'LUNISOLAR', 'Held three days after Holi.', '2026-03-07', '2027-03-26', 'Chhota Udepur District Administration & Rathwa Tribal Council', ARRAY['Gujarat']::TEXT[], ARRAY['Kavant', 'Chhota Udepur']::TEXT[], ARRAY['Village Grounds and Streets Kavant']::TEXT[], 'Daytime from 11 AM to 5 PM when dancing troupes take over the village square', 1, 'Electrifying, raw tribal energy, thunderous rhythmic bells vibrating the earth, and extraordinary indigenous body art.', '130 km from Vadodara; 30 km from Chhota Udepur; accessible by private car or rural bus.', 'Heritage homestays in Chhota Udepur palaces or return to Vadodara for hotel stay.', 'Very crowded and dusty village streets; wear comfortable clothing and sturdy shoes.', 'Show genuine respect for the sacred Rathwa customs; do not mock body art or disrupt ritual dancing lines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chhotaudepur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dang-darbar-ahwa', 'Dang Darbar Ahwa', ARRAY['Dangs Tribal Gathering']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Tribal Royalty & Nature', 'A historic three-day tribal festival where the five surviving tribal kings (Bhil and Kokni Rajas) of the Dangs receive their ancestral political pensions.', 'Originates from the 19th-century British colonial era when the British signed a timber lease treaty with the five forest kings of the Dangs.', 'Celebrates the autonomy, forest rights, and cultural heritage of the indigenous Dang tribal kings.', 'To formally distribute the government political pensions (Varshikasan) to the five Rajas and celebrate Holi in the deep forests.', 'The five kings of the Dangs are the only recognized titular monarchs in India who continue to receive official privy purse-like honors from the state.', 'Features the famous Dangi dance, where dancers form human pyramids and balance on each other''s shoulders without stopping.', ARRAY['Ceremonial arrival of the five Dang Kings in decorated open carriages with royal retinues', 'Presentation of royal honors and state tribute by government officials', 'Astonishing Dangi folk dances with three-tier human pyramids and Kahalia flutes']::TEXT[], 'Tribal communities from all 311 villages of the Dangs gather on the Ahwa fairgrounds, dancing continuously for three days and shopping for household goods.', ARRAY['Nagli (Finger Millet) Rotla', 'Bamboo shoot curry', 'Wild forest honey', 'Urad Dal Vada']::TEXT[], 'Simple tribal clothing with colorful dhotis, silver ornaments, and peacock-feather hairpins.', 'Dangi folk dance with hypnotic Kahalia flutes, Tadpu horns, and Dholak rhythms.', 'Royal umbrellas of the five Dang kings, teak forest trees, and multi-tiered human dance pyramids.', '3 Days', 'Hindu Lunisolar / Spring', 'Held during the days immediately preceding Holi.', 'March', 'LUNISOLAR', 'Held 2-3 days before Holi.', '2026-03-01', '2027-03-20', 'Dang District Administration & Gujarat Tourism', ARRAY['Gujarat']::TEXT[], ARRAY['Ahwa', 'Saputara', 'The Dangs']::TEXT[], ARRAY['Ahwa Fairgrounds Dangs']::TEXT[], 'Opening day for the royal procession of the five kings and afternoon human pyramid dances', 2, 'Rare historical glimpse of living indigenous tribal royalty, lush teak forest surroundings, and breathtaking acrobatic folk dances.', 'Accessible from Surat (140 km) or Bilimora (100 km); 40 km from the hill station of Saputara.', 'Hotels in Saputara hill station or forest guest houses in Ahwa.', 'Heavy footfall from surrounding forest villages; basic rural amenities in Ahwa town.', 'Respect the royal dignity of the five Dang kings; do not disrupt the formal durbar assembly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://dangs.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chitra-vichitra-fair', 'Chitra Vichitra Fair Sabarkantha', ARRAY['Gunbhakhari Tribal Fair']::TEXT[], 'Tribal & Folk Traditions', 'Tribal Folk Healing & Ancestral Rites', 'A poignant yet vibrant tribal fair held at the scenic confluence of three rivers, where Garasia and Bhil tribes mourn departed ancestors before celebrating life.', 'Named after Chitravirya and Vichitravirya, sons of King Shantanu from the Mahabharata, who meditated here to cleanse their guilt.', 'Commemorates ancestral healing, cleansing of grief, and the joyous renewal of tribal community life.', 'To immerse the ashes of departed family members in the holy river confluence and celebrate future marriages.', 'Unique emotional duality: the first night is spent in solemn mourning and weeping for departed loved ones, followed by days of joyful matchmaking and dance.', 'Attracts over 60,000 tribal people from the remote border hills of Gujarat and Rajasthan.', ARRAY['Solemn nightlong weeping and offering of food to departed souls at the riverbank', 'Morning immersion of ancestral ashes in the confluence of Wakal, Sabarmati, and Aakol rivers', 'Spirited daytime tribal dances, musical drumming, and matchmaking around fair stalls']::TEXT[], 'By midday, tears transform into laughter as drums thunder, flutes wail, and young men and women in brilliant festive finery join hands in dance.', ARRAY['Makai no Rotlo', 'Spicy Garlic Chutney', 'Jalebi', 'Sweet Bundi', 'Sugarcane juice']::TEXT[], 'Dazzling tribal finery: women wear blue and red Ghagras with heavy silver bangles and necklaces; men wear saffron turbans with silver amulets.', 'Traditional tribal drumming with Mandals and Dholaks, accompanied by wailing flutes and communal singing.', 'Confluence of three mountain rivers, sacred Shiva temple, and hills draped in tribal encampments.', '2 Days', 'Hindu Lunisolar / Spring', 'Held on the eve of Amavasya following Holi (Phalguna/Chaitra)', 'March - April', 'LUNISOLAR', 'Held a fortnight after Holi on Amavasya.', '2026-03-18', '2027-04-06', 'Sabarkantha District Administration & Poshina Tribal Block', ARRAY['Gujarat']::TEXT[], ARRAY['Gunbhakhari', 'Poshina', 'Sabarkantha']::TEXT[], ARRAY['Confluence of Sabarmati, Aakol and Wakal Rivers Gunbhakhari']::TEXT[], 'Morning hours when the emotional transition from mourning rituals to ecstatic dance takes place', 2, 'Profoundly moving human drama of collective grief and joyous resurrection against a rugged, untamed river valley landscape.', '150 km from Ahmedabad; 30 km from Khedbrahma; accessible by road.', 'Heritage hotels in Poshina or stay in Himmatnagar/Mount Abu.', 'Remote rural valley; wear sturdy footwear for rocky riverbank walking.', 'Observe ancestral mourning rituals with solemn silence; never photograph weeping families during morning rites.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sabarkantha.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rath-yatra-ahmedabad', 'Rath Yatra Ahmedabad', ARRAY['Ahmedabad Jagannath Rath Yatra']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Chariot Festival)', 'The second largest Rath Yatra in the world, where colossal wooden chariots of Lord Jagannath, Balbhadra, and Subhadra traverse 14 km through Ahmedabad.', 'Initiated in 1878 CE by Mahant Narsinghdasji Maharaj of the historic 400-year-old Jagannath Temple in Jamalpur.', 'Celebrates the annual journey of Lord Jagannath to visit his maternal aunt''s home, granting darshan to all citizens irrespective of caste.', 'To pull the sacred ropes of the divine chariots, an act believed to grant liberation from rebirth.', 'A monumental cultural institution in Gujarat, bringing together over a million devotees and 18 decorated temple elephants.', 'Traditionally flagged off at dawn by the Chief Minister of Gujarat performing the ceremonial sweeping with a golden broom (Pahind Vidhi).', ARRAY['Early morning Mangala Aarti followed by the ceremonial golden broom sweeping (Pahind Vidhi)', 'Procession of 18 decorated temple elephants leading the three towering chariots', 'Acrobatic martial arts demonstrations by 101 Akhadas and 30 Bhajan mandalis']::TEXT[], 'Lakhs of devotees pack balconies and streets of Old Ahmedabad, cheering as the majestic wooden chariots rumble through historic stone gateways.', ARRAY['Sprouted Moong and Black Chana (traditional prasad distributed by millions of packets)', 'Jamun fruit', 'Mango pulp (Keri no Ras)', 'Puri']::TEXT[], 'White cotton kurtas, yellow dhotis, Jagannath stoles, and colorful Gujarati ethnic dresses.', 'Thunderous Jai Jagannath chants, Dhol-Nagada beats, Shehnai, and devotional Bhajan singing.', 'Three majestic wooden chariots (Nandighosha, Taladhwaja, Darpadalana), caparisoned elephants, and sprouted moong prasad.', '1 Day', 'Hindu Lunisolar', 'Ashadha Shukla Dwitiya (June - July)', 'June - July', 'LUNISOLAR', 'Celebrated on Ashadha Shukla Dwitiya.', '2026-07-16', '2027-07-06', 'Shree Jagannath Mandir Trust Jamalpur & Gujarat Police', ARRAY['Gujarat']::TEXT[], ARRAY['Ahmedabad']::TEXT[], ARRAY['Jagannath Temple Jamalpur', 'Saraspur', 'Kalupur', 'Manek Chowk']::TEXT[], 'Dawn (4 AM to 7 AM) at Jamalpur temple for Mangala Aarti and Pahind Vidhi', 1, 'Colossal spiritual frenzy, thunderous energy of leaping gymnasts and martial artists, and moving ocean of faith in the historic walled city.', 'Ahmedabad Metro connects to nearby stations; entire 14 km route is heavily guarded and pedestrian-only.', 'Extensive hotels across Ahmedabad; reserve well in advance.', 'Over one million devotees; high security drone surveillance; follow designated police spectator enclosures.', 'Accept the blessed sprouted moong and jamun prasad with reverence; stay hydrated in summer heat.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ahmedabadcity.police.gujarat.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-somnath-mahotsav', 'Somnath Mahotsav Prabhas Patan', ARRAY['Somnath Shivratri Mahotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (First Jyotirlinga / Shaivism)', 'The sacred festival celebrated at the First of the Twelve Jyotirlingas, where the eternal temple stands on the shore of the roaring Arabian Sea.', 'Ancient pilgrimage shrine mentioned in Rigveda, rebuilt multiple times in history; modern grand temple inaugurated in 1951 by Sardar Vallabhbhai Patel.', 'Celebrates Lord Shiva as the protector of the Moon God (Soma) and Lord of the Cosmic Dance.', 'To offer holy Ganga water and milk to the first Jyotirlinga and seek liberation from mortality.', 'Supreme symbol of civilizational resilience and eternal faith, having risen undefeated through centuries of invasions.', 'Features the magnificent ''Jay Somnath'' sound-and-light show projected on the temple spire with the crashing sea in the background.', ARRAY['Continuous Maha Rudrabhishek of the Jyotirlinga throughout Maha Shivratri night', 'Grand Shobha Yatra of Lord Somnath through the streets of Prabhas Patan', 'Nightlong classical devotional music and dance concerts in the temple auditorium']::TEXT[], 'Lakhs of pilgrims wait in serene queues, listening to the eternal roar of the Arabian Sea mingling with Vedic hymns and brass bells.', ARRAY['Fasting prasad: Sabudana Vada, Moraiyo Khichdi', 'Peda', 'Panchamrit', 'Dry fruit prasad']::TEXT[], 'Traditional dhotis, kurtas, white and saffron sarees, and Rudraksha malas.', 'Resounding Vedic chanting of the Rudram, classical Shehnai, temple bells, and soulful Shiva stutis.', 'Towering stone Shikhara of Somnath temple, golden Kalash, Trishul, and crashing Arabian Sea breakers.', '4 Days', 'Hindu Lunisolar', 'Magha Krishna Trayodashi to Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Culminates on Maha Shivratri night.', '2026-02-15', '2027-03-06', 'Shree Somnath Trust & Gujarat Tourism', ARRAY['Gujarat']::TEXT[], ARRAY['Prabhas Patan', 'Veraval', 'Somnath']::TEXT[], ARRAY['Somnath Jyotirlinga Temple Complex']::TEXT[], 'Evening aarti at 7 PM followed by the Sound-and-Light show and midnight Darshan', 2, 'Sublime spiritual awe where the eternal stone temple towers over crashing ocean waves, filled with timeless Vedic peace.', 'Veraval railway station (7 km); Diu Airport (85 km); well connected by state highways.', 'Somnath Trust guest houses (Sagar Darshan, Maheshwari), luxury resorts, and dharamshalas.', 'Strict security check at temple entrance: mobile phones, cameras, leather belts, and electronic items are strictly prohibited inside.', 'Arrive early for the sound-and-light show; enjoy peaceful walking along the fortified Arabian sea promenade.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://somnath.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-goa-carnival', 'Goa Carnival', ARRAY['Carnaval de Goa']::TEXT[], 'Art & Cultural Festival', 'Christian / Lusitanian & Goan Cultural Heritage', 'The legendary four-day pre-Lenten carnival introduced by the Portuguese in 1510, celebrated with King Momo, street parades, and masquerades.', 'Introduced over 500 years ago during Portuguese colonial rule, modeled on European pre-Lenten carnivals and adapted to Goan Konkani folk life.', 'Celebrates feasting, merriment, and joyous abandon before the austere 40-day Christian penitential season of Lent.', 'To celebrate community joy, humor, satire, and the inclusive spirit of Goa''s multicultural heritage.', 'The only authentic European-style carnival celebrated in the Indian subcontinent, drawing visitors from across the world.', 'Led by King Momo, who is formally handed the keys to the city on opening day and proclaims his royal decree: ''Eat, Drink, and Be Merry!''.', ARRAY['Coronation and proclamation of King Momo leading the grand float parade down Panaji''s DB Marg', 'Vibrant parade of themed floats, costumed dancers, acrobats, and brass bands', 'Red and Black masked ball on the concluding Fat Tuesday night']::TEXT[], 'Streets of Panaji, Margao, Vasco, and Mapusa overflow with costumed dancers throwing confetti, music, and food stalls.', ARRAY['Goan Fish Curry Rice', 'Pork Vindaloo', 'Bebinca (layered Goan coconut-egg dessert)', 'Dodol', 'Chourico Pau']::TEXT[], 'Flamboyant masquerade costumes, feathered carnival masks, colorful floral shirts, and vintage Portuguese outfits.', 'Live Konkani Brass bands, lively Latin samba rhythms, Goan mando songs, and energetic street dance troupes.', 'King Momo''s crown and sceptre, giant papier-mâché carnival masks, colorful streamers, and Mandovi river promenade.', '4 Days', 'Christian Liturgical (Pre-Lent)', 'Four days leading up to Ash Wednesday (Fat Saturday to Fat Tuesday)', 'February', 'LUNAR', 'Dates vary based on Easter; held four days prior to Ash Wednesday.', '2026-02-14', '2027-02-06', 'Goa Tourism Development Corporation (GTDC)', ARRAY['Goa']::TEXT[], ARRAY['Panaji', 'Margao', 'Vasco da Gama', 'Mapusa']::TEXT[], ARRAY['Dayanand Bandodkar Marg Panaji', 'Margao City Center']::TEXT[], 'Opening day parade on Saturday in Panaji and evening street dances', 3, 'Infectious, joyful Mediterranean street party atmosphere with pumping music, dazzling costumes, and Goa''s legendary relaxed susegad charm.', 'Dabolim Airport and Manohar International Airport Mopa; Kadamba buses, rented scooters, and taxis.', 'Hotels throughout Panaji, Miramar, and beach resorts across North and South Goa; book 2-3 months in advance.', 'High crowd density along parade routes; secure a spot along the DB Marg barricades by 2:30 PM.', 'Keep the carnival eco-friendly: no throwing plastic waste or harmful chemicals; respect families and dancers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shigmo-festival', 'Shigmo Festival Statewide', ARRAY['Shigmotsav Goa']::TEXT[], 'Art & Cultural Festival', 'Hinduism (Folk Konkani Heritage)', 'The grand 14-day spring folk festival of Goan Hindus celebrating the return of warriors from battle with elaborate mythological street floats and folk dances.', 'Ancient Konkani spring harvest and warrior festival celebrating the return of local forces who defended Goan soil against invaders.', 'Celebrates the arrival of spring, victory of righteousness, and the harvesting of winter crops.', 'To honor village deities (Gramdevtas) and showcase ancient Konkani folk performing arts.', 'The indigenous Goan counterpart to Carnival, celebrated with pure folk traditions, warrior dances, and colossal floats depicting Hindu epics.', 'Features authentic traditional folk dances including Ghode Modni (warrior horse dance) and Fugdi.', ARRAY['Nightly street parades featuring colossal mechanized floats depicting scenes from Ramayana and Mahabharata', 'Ghode Modni warrior dance where performers strap wicker horses to their waists wielding swords', 'Spirited Romtamel percussion procession with giant brass cymbals and Dhol-Tasha']::TEXT[], 'Towns across Goa come alive with sound and color as hundreds of costumed dancers, drummers, and illuminated floats parade past cheering crowds.', ARRAY['Goan Khatkhate (mixed vegetable stew with triphala)', 'Nevryo (sweet coconut turnovers)', 'Kheer', 'Puri Bhaji']::TEXT[], 'Vibrant traditional Konkani attire: bright dhotis with turbans (Phetas), warrior costumes, and Nauvari sarees.', 'Thundering beats of Dhol, Tasha, and Kasale (cymbals), accompanied by folk singing of Naman and Jot.', 'Mechanized illuminated mythological float sculptures, wicker wooden horses, and colorful gulal powders.', '14 Days', 'Hindu Lunisolar', 'Phalguna Shukla Navami to Phalguna Purnima (March)', 'March', 'LUNISOLAR', 'Held during the bright half of Phalguna month.', '2026-03-03', '2027-03-22', 'Goa Tourism & Directorate of Art and Culture', ARRAY['Goa']::TEXT[], ARRAY['Panaji', 'Ponda', 'Margao', 'Bicholim', 'Mapusa']::TEXT[], ARRAY['18th June Road Panaji', 'Ponda Town Square']::TEXT[], 'Panaji city parade evening and Ponda cultural night for the most elaborate mythological floats', 2, 'Electrifying tribal and folk pride, thundering drum vibrations, dazzling mechanical float artistry, and joyous spring colors.', 'Easily accessible across major Goan towns via local buses, rental cars, and scooters.', 'Hotels in Panaji, Ponda, or coastal beach areas.', 'Parades take place in the evening; main roads are closed to vehicles from 3 PM onwards.', 'Appreciate the immense creative labor behind the handmade floats; avoid throwing water or chemical colors.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-feast-st-francis-xavier', 'Feast of St. Francis Xavier Old Goa', ARRAY['Goencho Saib Feast']::TEXT[], 'Spiritual & Temple', 'Christianity (Catholicism)', 'The solemn, deeply reverent annual feast honoring St. Francis Xavier (Goencho Saib), patron saint of Goa, at the UNESCO World Heritage Basilica of Bom Jesus.', 'Commemorates the death of St. Francis Xavier in 1552 CE; his miraculously uncorrupted mortal remains have been enshrined in Old Goa for nearly 500 years.', 'Celebrates the life, missionary devotion, and miracles of the Apostle of the Indies.', 'To offer prayers, fulfill vows, and seek healing and spiritual blessings at the sacred silver reliquary.', 'The supreme Christian pilgrimage in South Asia, drawing hundreds of thousands of Catholic and Hindu devotees alike.', 'Every 10 years, the sacred body of St. Francis Xavier is brought down from its silver casket for a public Decennial Exposition.', ARRAY['Nine-day Novena of special open-air masses leading up to the feast day', 'Solemn High Mass concelebrated by bishops and hundreds of priests on the Basilica grounds', 'Veneration of the sacred silver casket containing the saint''s uncorrupted body']::TEXT[], 'Pilgrims from across India and the global diaspora camp on the sprawling greens of Old Goa, attending dawn masses and shopping at the traditional fair.', ARRAY['Goan Pork Sorpotel with Sannas', 'Bebinca', 'Doce de Grao (chana dal sweet)', 'Chorizo Pau', 'Roasted gram']::TEXT[], 'Sunday church best: formal suits, modest dresses, lace mantillas, and traditional sarees.', 'Angelic choir singing, liturgical brass ensemble accompaniment, and Konkani devotional hymns (''Sam Francisku Xaviera'').', '17th-century Baroque facade of Basilica of Bom Jesus, Florentine bronze casket, and towering palm trees.', '10 Days (9 days Novena + Feast Day)', 'Christian Liturgical', 'December 3 annually (Novena begins November 24).', 'November - December', 'FIXED', 'Feast day celebrated on December 3 annually.', '2026-12-03', '2027-12-03', 'Archdiocese of Goa and Daman & GTDC', ARRAY['Goa']::TEXT[], ARRAY['Old Goa (Velha Goa)', 'Panaji']::TEXT[], ARRAY['Basilica of Bom Jesus', 'Se Cathedral Grounds']::TEXT[], 'Feast Day (December 3) for the solemn morning High Mass or peaceful evening novena masses', 2, 'Profound, tearful spiritual reverence amidst world-class 16th-century Renaissance and Baroque church architecture and peaceful Goan warmth.', '10 km east of Panaji; special nonstop shuttle buses operate between Panaji/Margao bus stands and Old Goa.', 'Accommodations in Panaji city or surrounding riverine boutique stays.', 'Massive attendance (over 200,000 pilgrims); long queues to venerate the sacred casket; arrive early.', 'Modest, respectful attire mandatory inside the Basilica; photography prohibited during holy mass.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://archgoadaman.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bonderam-festival', 'Bonderam Flag Festival Divar Island', ARRAY['Island Flags Carnival']::TEXT[], 'Historical & Royal', 'Secular / Island Heritage & Konkani Folklore', 'A delightfully colorful island festival celebrating the resolution of historic village boundary disputes on peaceful Divar Island on the Mandovi River.', 'Originates from the Portuguese era when rival sections of Divar Island fought bitter land disputes, which the Portuguese resolved by posting flags (Bandeiras) along boundaries.', 'Celebrates communal peace, forgiveness, and the humorous memory of ancient village rivalries.', 'To promote island unity, preserve Konkani folk arts, and celebrate rural island culture.', 'Celebrated exclusively on the car-free, lush river island of Divar, accessible only by picturesque river ferries.', 'Famous for the mock toy-weapon battles with ''Fotash'' (bamboo peashooters) shooting berries at competitor flags.', ARRAY['Grand opening brass band parade with traditional flag-bearers representing island wards', 'Mock village battle using bamboo Fotash shooters to knock down mock flags', 'Vibrant street carnival with themed floats designed by island village youth']::TEXT[], 'Visitors cross the Mandovi river on ferries to join islanders dancing in cobblestone streets, enjoying Konkani food and live music.', ARRAY['Freshly caught Mandovi River Mud Crabs and Prawns', 'Fish Recheado', 'Bebinca', 'Pao with Beef/Pork Roast']::TEXT[], 'Casual festive island wear, floral Hawaiian-Goan shirts, straw sun hats, and colorful cotton dresses.', 'High-energy live Konkani brass bands, classic Goan pop music, and lively group street dances.', 'Multi-colored flags (Bandeiras) fluttering across island lanes, bamboo Fotash shooters, and river ferry boats.', '1 Day', 'Gregorian / Monsoon', 'Fourth Saturday of August annually.', 'August', 'FIXED', 'Fourth Saturday of August.', '2026-08-22', '2027-08-28', 'Piedade Youth Association & Goa Tourism', ARRAY['Goa']::TEXT[], ARRAY['Divar Island', 'Piedade', 'Panaji']::TEXT[], ARRAY['Piedade Village Square Divar Island']::TEXT[], 'Afternoon between 3 PM and 8 PM for the flag parade and street carnival', 1, 'Idyllic, joyful island escapade with scenic river ferry crossings, cobblestone Portuguese village lanes, and warm local camaraderie.', 'Short 10-minute free car-ferry ride from Ribandar or Old Goa ferry jetty to Divar Island.', 'Charming boutique heritage homestays on Divar Island or hotels in Panaji.', 'Narrow island roads; walk on foot or rent a bicycle on the island; expect ferry queues on return.', 'Respect the private properties of island villagers; Fotash toy shooters should not be aimed at spectators'' faces.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sao-joao-goa', 'Sao Joao Water Festival Siolim', ARRAY['St. John the Baptist Feast']::TEXT[], 'Seasonal & Nature', 'Christianity (Catholic & Monsoon Ecology)', 'The exuberant monsoon water festival where Goan youth wearing wild floral crowns (Kopels) leap joyfully into village wells and streams.', 'Commemorates the biblical feast of St. John the Baptist, who leapt with joy in his mother Elizabeth''s womb when Mary visited her.', 'Celebrates the arrival of cooling monsoon rains, reproductive fertility, and nature''s emerald rejuvenation.', 'To honor newly married sons-in-law (Javai) and newborn children through customary gift exchanges.', 'One of the most unique and joyous water festivals in the world, combining Christian theology with indigenous monsoon water rituals.', 'Famous for the grand procession of colorfully decorated boat barges (Sangodd) floating down the Siolim river.', ARRAY['Weaving and wearing intricate fresh floral crowns made of wild monsoon blossoms and leaves (Kopel)', 'Young men leaping joyfully from trees and stone ledges into natural village wells and rivers', 'Procession of decorated cultural boat floats (Sangodd) at the Siolim church riverfront']::TEXT[], 'Villages reverberate with music and laughter as youths jump into rain-filled wells, shouting ''Viva Sao Joao!'', while elders distribute fruits and feni.', ARRAY['Fresh Jackfruit', 'Pineapple slices', 'Mangoes', 'Goan Sannas', 'Feni infused cocktails']::TEXT[], 'Vibrant floral crowns (Kopels) woven with hibiscus and palm fronds, colorful summer t-shirts, and board shorts.', 'Ghumot percussion rhythms, Konkani folk singing, accordion melodies, and enthusiastic ''Viva Sao Joao!'' chants.', 'Fresh floral Kopel crowns, rainwater-filled stone wells, decorated boat floats, and lush green monsoon paddy fields.', '1 Day', 'Christian Liturgical', 'June 24 annually (Feast of St. John the Baptist).', 'June', 'FIXED', 'Celebrated June 24 every year.', '2026-06-24', '2027-06-24', 'Goa Tourism & Siolim Sao Joao Committee', ARRAY['Goa']::TEXT[], ARRAY['Siolim', 'Benaulim', 'Anjuna', 'Curtorim']::TEXT[], ARRAY['St. Anthony Church Riverfront Siolim', 'Village wells across Goa']::TEXT[], 'Afternoon between 2 PM and 6:30 PM at the Siolim riverfront for the Sangodd boat parade', 1, 'Exhilarating, splash-filled monsoon euphoria, intoxicating floral aromas from wild crowns, and Goa''s peerless spirit of community hospitality.', 'Easily accessible across North Goa via scooter, taxi, or car.', 'Boutique hotels and heritage villas across North Goa (Siolim, Assagao, Vagator).', 'Wet and slippery conditions; ensure well-jumping is done only in supervised, cleared village wells.', 'Wear a freshly woven Kopel crown; celebrate respectfully without causing nuisance.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tripurari-poornima-goa', 'Tripurari Poornima Boat Festival Sankhali', ARRAY['Sankhali Miniature Boat Carnival']::TEXT[], 'Seasonal & Nature', 'Hinduism (Shaivism / Folk Maritime)', 'The dazzling nocturnal festival where hundreds of handcrafted miniature boats made of thermocol and wood compete in illuminated beauty on the Valvanti River.', 'Rooted in the ancient mythological legend of Lord Shiva slaying the demon Tripurasura on Kartik Purnima.', 'Celebrates the triumph of divine light over darkness and honors Goa''s ancient seafaring maritime traditions.', 'To remember the ancient Goan mariners who set sail to Southeast Asian kingdoms for trade on the auspicious full moon.', 'A breathtaking visual competition where local artisans spend months crafting miniature replicas of historic ships, aircraft carriers, and temples.', 'The illuminated miniature boats are gently released onto the calm waters of the Valvanti river at midnight.', ARRAY['Exhibition and competitive judging of hundreds of intricately illuminated miniature model boats', 'Releasing of miniature illuminated boats onto the dark waters of the Valvanti River', 'Grand fireworks display and cultural folk performances at the riverfront']::TEXT[], 'Tens of thousands of spectators line the riverbanks, cheering as hundreds of miniature glowing battleships, galleons, and palaces float downstream.', ARRAY['Goan sweets: Nevryo, Sakharbhaat', 'Mirchi Pakoda', 'Fish Cutlets', 'Puri Bhaji']::TEXT[], 'Festive cotton kurtas, sarees, and casual evening attire.', 'Konkani folk songs, live orchestra music, and traditional Dhol-Tasha drumming.', 'Intricate miniature model boats glowing with LED lights, midnight fireworks over water, and Valvanti river reflections.', '1 Day', 'Hindu Lunisolar', 'Kartik Purnima (full moon night of Kartik month in November)', 'November', 'LUNISOLAR', 'Celebrated on Kartik Purnima night.', '2026-11-24', '2027-11-13', 'Sankhali Municipal Council & Department of Tourism Goa', ARRAY['Goa']::TEXT[], ARRAY['Sankhali (Sanquelim)', 'Bicholim']::TEXT[], ARRAY['Valvanti Riverfront Sankhali']::TEXT[], 'Evening from 7 PM to midnight when the illuminated boat competition and release takes place', 1, 'Spectacular nocturnal creativity, glowing reflections drifting down the tranquil river, and authentic non-commercial Goan cultural warmth.', '30 km northeast of Panaji; accessible by road via Mapusa or Bicholim.', 'Hotels in Panaji or eco-resorts in North Goa.', 'Crowded riverbank spectator paths; watch your footing along the water''s edge.', 'Keep the river clean; model boats are retrieved after competition judging to avoid water pollution.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-grape-escapade', 'Grape Escapade Wine Festival Panaji', ARRAY['Goa Wine & Gourmet Festival']::TEXT[], 'Art & Cultural Festival', 'Gourmet Wine & Culinary Arts', 'India''s premier lifestyle and wine festival bringing together world-class winemakers, master chefs, musicians, and food lovers to the banks of the Mandovi River.', 'Established in 2005 by Goa Tourism Development Corporation (GTDC) to position Goa as a sophisticated culinary and wine tourism destination.', 'Celebrates the international art of winemaking, gourmet dining, and cosmopolitan lifestyle.', 'To promote agro-tourism, wine appreciation, and showcase Goa''s rich culinary traditions to global visitors.', 'The largest wine festival in India, featuring over 50 leading domestic and international wineries.', 'Features the traditional grape-stomping ceremony where visitors stomp fresh grapes in large oak barrels to the beat of live music.', ARRAY['Wine tasting masterclasses conducted by master sommeliers', 'Traditional grape stomping in large wooden barrels for visitors', 'Nightly live jazz, blues, and world fusion musical concerts by international bands']::TEXT[], 'Visitors sip fine wines from crystal glasses, sample artisanal cheeses and Goan gourmet delicacies, and dance beneath illuminated palm trees.', ARRAY['Goan Chorizo Croquettes', 'Artisanal Cheese platters', 'Seafood Paella', 'Pork Ribs', 'Bebinca with Ice Cream']::TEXT[], 'Smart casuals, chic resort wear, linen shirts, and elegant evening dresses.', 'Live international jazz, blues, Portuguese Fado singing, and acoustic Latin guitar.', 'Oak wine barrels, grape clusters, wine glasses against the Mandovi riverfront, and fairy-lit garden pavilions.', '4 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by GTDC.', '2026-02-05', '2027-02-04', 'Goa Tourism Development Corporation (GTDC)', ARRAY['Goa']::TEXT[], ARRAY['Panaji']::TEXT[], ARRAY['DB Bandodkar Grounds Campal Panaji']::TEXT[], 'Evening from 6 PM to 11 PM for wine tasting and live musical performances', 2, 'Chic, sophisticated lifestyle ambiance with cool river breezes, exquisite vintage wines, gourmet aromas, and world-class live jazz.', 'Centrally located in Panaji; easily reached by auto-rickshaw, cab, or walking from city center.', 'Abundant luxury and boutique hotels across Panaji and Miramar.', 'Adult-oriented lifestyle festival; designated driver or taxi use recommended after wine tasting.', 'Legal drinking age rules apply for wine tasting; drink responsibly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-goa-heritage-festival', 'Goa Heritage Festival Campal', ARRAY['Goa Arts & Literature Heritage Fest']::TEXT[], 'Historical & Royal', 'Secular / Indo-Portuguese Architecture & History', 'A sophisticated five-day celebration of Goa''s tangible and intangible heritage held amidst the heritage Latin quarters of Campal and Fontainhas.', 'Initiated by the Goa Heritage Action Group (GHAG) to advocate for the preservation of historic architecture, literature, music, and crafts.', 'Celebrates Goa''s unique 450-year synthesis of Indian and European artistic, architectural, and literary traditions.', 'To raise awareness for heritage conservation and showcase traditional Goan artisans, writers, and musicians.', 'Staged along the picturesque tree-lined promenade of Campal, bordered by classic Portuguese heritage villas.', 'Features curated heritage walks, architectural symposiums, antique exhibitions, and traditional Konkani folk arts.', ARRAY['Curated walking tours through Fontainhas (Latin Quarter) and Campal heritage precincts', 'Craft demonstrations of traditional Goan tile painting (Azulejos) and terracotta pottery', 'Evening musical soirees featuring Portuguese Fado singing and classical Konkani Mando']::TEXT[], 'Culture enthusiasts stroll past pastel-painted havelis with oyster-shell windows, attending author talks, sampling lost Goan recipes, and listening to violinists.', ARRAY['Traditional Goan Khatkhate', 'Pattolleo (sweet rice rolls steamed in turmeric leaves)', 'Caldo Verde soup', 'Bolo de Rulao']::TEXT[], 'Sophisticated casual wear, handloom cotton kurtas, linen trousers, and elegant hats.', 'Soulful Portuguese Fado vocals accompanied by classical 12-string Portuguese guitar, and classical Konkani Mando ensembles.', 'Azulejo glazed ceramic tiles, wrought iron balconies, oyster-shell windows, and cobblestone lanes.', '5 Days', 'Gregorian / Autumn', 'Held in November annually.', 'November', 'ORGANIZER_ANNOUNCED', 'Organized annually by Goa Heritage Action Group.', '2026-11-18', '2027-11-17', 'Goa Heritage Action Group & GTDC', ARRAY['Goa']::TEXT[], ARRAY['Panaji', 'Campal', 'Fontainhas']::TEXT[], ARRAY['Campal Heritage Promenade', 'Fontainhas Latin Quarter']::TEXT[], 'Morning heritage architectural walks and evening Fado musical recitals', 2, 'Intellectually invigorating, romantic aesthetic journey into Goa''s living architectural soul and artistic refinement.', 'Located in central Panaji; easily accessible on foot, by bicycle, or auto-rickshaw.', 'Heritage boutique hotels in Fontainhas and Campal.', 'Pedestrian-friendly environment; wear comfortable walking shoes for heritage walks.', 'Support local heritage artisans; treat historic residential neighborhoods with courtesy and quiet respect.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://goaheritageactiongroup.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nariyal-poornima-daman', 'Nariyal Poornima Daman', ARRAY['Coconut Day Daman & Diu']::TEXT[], 'Seasonal & Nature', 'Hinduism (Maritime & Fisherfolk Heritage)', 'The joyful coastal festival marking the end of the monsoon season and resumption of the fishing season, where fishermen offer golden coconuts to the Arabian Sea.', 'Ancient coastal festival observed by the Koli, Machhi, and fishing communities of Daman, Diu, and western India.', 'Commemorates Lord Varuna (God of Oceans and Rain) calming the monsoon waves to permit safe maritime navigation.', 'To thank the ocean for sustenance, seek blessings for safe sea voyages, and celebrate the start of the commercial fishing year.', 'Boats are painted in brilliant colors, decorated with bunting and flags, and blessed with sacred vermilion before launching into the sea.', 'Features exhilarating country boat races and swimming competitions in the Arabian Sea.', ARRAY['Offering consecrated coconuts (often wrapped in gold and silver foil) into the Arabian Sea waves', 'Blessing and consecration of decorated fishing trawlers and wooden boats', 'Spirited coastal folk dances and boat racing competitions off Devka Beach']::TEXT[], 'Fisherfolk families dress in their finest festive clothes, marching to the beach with brass bands and singing songs of gratitude to Mother Ocean.', ARRAY['Fresh Pomfret Fish Curry with rice', 'Coconut Barfi', 'Narali Bhaat (sweet coconut rice)', 'Daman Prawn Fry']::TEXT[], 'Traditional Koli attire: brightly colored Lugade sarees tucked between knees, gold jewelry, and embroidered waistcoats for men.', 'Energetic Koli folk dances mimicking the rowing of boats and netting of fish, accompanied by Dholak and brass trumpets.', 'Gold-foiled coconuts, colorful fluttering boat pennants, fishing nets, and azure Arabian Sea waters.', '1 Day', 'Hindu Lunisolar', 'Shravana Purnima (full moon day of Shravana month in August)', 'August', 'LUNISOLAR', 'Celebrated on Shravana Purnima.', '2026-08-28', '2027-08-17', 'UT Administration of DNH & DD Tourism', ARRAY['Dadra and Nagar Haveli and Daman and Diu']::TEXT[], ARRAY['Daman', 'Diu']::TEXT[], ARRAY['Devka Beach Daman', 'Nani Daman Jetty', 'Ghoghla Beach Diu']::TEXT[], 'Morning boat blessing ceremony at Nani Daman Jetty and afternoon beach games', 1, 'Vibrant coastal camaraderie, colorful fleets of decorated boats bobbing on blue waters, and delicious fresh seafood aromas.', '12 km from Vapi railway station (major station on Mumbai-Delhi route); accessible by taxi.', 'Beachfront resorts and hotels along Devka and Jampore beaches in Daman.', 'Monsoon sea tides can be strong; stay within safe designated beach viewing areas.', 'Do not throw plastic wraps or non-biodegradable decorations into the ocean.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://daman.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tarpa-festival-silvassa', 'Tarpa Folk Festival Silvassa', ARRAY['Dadra & Nagar Haveli Tribal Utsav']::TEXT[], 'Tribal & Folk Traditions', 'Warli, Dhodia & Kokna Tribal Heritage', 'A vibrant cultural celebration in the lush forests of Silvassa showcasing the mesmerizing Tarpa dance and famous Warli tribal art of Dadra & Nagar Haveli.', 'Initiated by the Department of Tourism to preserve and celebrate the living heritage of the indigenous Warli, Dhodia, and Kokna tribes.', 'Celebrates the autumn post-harvest abundance, forest ecology, and community bonding.', 'To provide a prominent platform for tribal musicians, preserve the ancient Tarpa horn instrument, and promote tribal handicrafts.', 'Centered around the ''Tarpa'', a magnificent deep-toned wind instrument made of dried gourd, bamboo, and wild palm leaves.', 'Dozens of dancers form a human spiral around the Tarpa player, moving inward and outward in mesmerizing circular waves without breaking hands.', ARRAY['Performance of the grand continuous Tarpa spiral dance by hundreds of tribal dancers', 'Live demonstrations of authentic white-pigment Warli canvas and wall painting', 'Traditional archery, boat races, and swimming competitions on the Daman Ganga river']::TEXT[], 'Visitors gather on lush riverside lawns under cool autumn skies, watching concentric spirals of dancers move in hypnotic rhythm to the deep droning Tarpa horn.', ARRAY['Ubadiyu (steamed clay-pot vegetable and bean bake with wild herbs)', 'Nagli (Ragi) Rotla', 'Wild mushroom curry', 'Rice flour pancakes']::TEXT[], 'Traditional tribal attire: colorful lungis, waistcloths, silver necklaces, and peacock-feather hair ornaments.', 'Deep, resonant drone of the Tarpa horn, accompanied by Ghanghli string instruments and rhythmic foot stamping.', 'Dried gourd Tarpa horn instrument, Warli spiral dance motifs, and painted mud walls.', '3 Days', 'Gregorian / Autumn', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Organized annually by UT Tourism Department.', '2026-12-04', '2027-12-03', 'Department of Tourism UT of DNH & DD', ARRAY['Dadra and Nagar Haveli and Daman and Diu']::TEXT[], ARRAY['Silvassa', 'Khanvel', 'Dudhani']::TEXT[], ARRAY['Daman Ganga Riverfront', 'Silvassa Tribal Cultural Centre']::TEXT[], 'Late afternoon and evening when the grand Tarpa spiral dances take place', 2, 'Peaceful forest riverfront retreat, ancient hypnotic tribal music echoing through lush greenery, and authentic handmade Warli art.', '17 km from Vapi railway station on the Mumbai-Ahmedabad mainline; easily reached by cab or bus.', 'Riverside resorts and forest retreats in Silvassa and Khanvel.', 'Relaxed family-friendly festival; comfortable casual walking shoes recommended.', 'Buy authentic Warli paintings directly from tribal master artists to ensure fair trade.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ddd.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gangaji-fair-daman', 'Gangaji Fair Daman', ARRAY['Dabhel Gangaji Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Sacred Water Heritage)', 'The historic annual pilgrimage fair held at the ancient Somnath Mahadev temple in Dabhel, dedicated to the sacred emergence of river Ganga in Daman.', 'Centuries-old folk tradition centered around the miraculous underground freshwater spring at Somnath Mahadev Temple in Dabhel.', 'Celebrates the emergence of holy waters and the victory of Lord Shiva over cosmic afflictions.', 'To take holy baths in the sacred Gangaji Kund and pray for freedom from illnesses and family prosperity.', 'Draws thousands of rural pilgrims from Daman, Gujarat, and Maharashtra, serving as a major regional cultural fair.', 'Features bustling village bazaars with traditional terracotta toys, brass utensils, and rustic joyrides.', ARRAY['Holy cleansing dip in the sacred stone tank of Gangaji Kund', 'Abhishek of the ancient Shiva Lingam at Somnath Mahadev Temple with spring water', 'Ringing of massive temple bells and participation in the rural carnival']::TEXT[], 'Pilgrims bathe at dawn and circumambulate the temple, while children enjoy giant wooden Ferris wheels and savor sweet treats.', ARRAY['Peda', 'Jalebi', 'Gathiya', 'Spicy Chana', 'Kachori']::TEXT[], 'Traditional Gujarati and Konkani rural attire: dhotis, colorful sarees, and embroidered dupattas.', 'Continuous Bhajan singing, devotional folk hymns, and traditional Dholak-harmonium melodies.', 'Ancient stone Kund spring, carved Shiva Lingam, and colorful rural fairground stalls.', '3 Days', 'Hindu Lunisolar', 'Celebrated in the month of March around Maha Shivratri / Holi.', 'March', 'LUNISOLAR', 'Held in Phalguna month.', '2026-03-05', '2027-03-24', 'Dabhel Gram Panchayat & Daman District Administration', ARRAY['Dadra and Nagar Haveli and Daman and Diu']::TEXT[], ARRAY['Dabhel', 'Daman']::TEXT[], ARRAY['Somnath Mahadev Temple Dabhel']::TEXT[], 'Morning for holy bath rituals and evening for the rural fairground vibrancy', 1, 'Authentic, unhurried rural pilgrimage charm, clean freshwater spring amidst swaying palms, and warm village hospitality.', '5 km from Vapi railway station; easily reached by auto-rickshaw.', 'Hotels in Daman city or Vapi.', 'Moderate crowds; follow designated bathing lines at the Kund.', 'Keep the sacred spring water clean; avoid using soaps near the holy tank.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://daman.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-daman-beach-carnival', 'Daman Beach Carnival & Seafood Festival', ARRAY['Daman Fest']::TEXT[], 'Art & Cultural Festival', 'Secular / Beach Tourism & Seafood', 'A lively beachside celebration along the Arabian Sea featuring coastal watersports, music concerts, and the finest fresh coastal seafood of western India.', 'Initiated by the Tourism Department of Daman to promote the pristine black-sand beaches of Devka and Jampore as premier coastal holiday destinations.', 'Celebrates coastal leisure, Portuguese-influenced heritage, and the rich marine biodiversity of the Gulf of Khambhat.', 'To boost beach tourism, support local coastal fishing economies, and offer vibrant family entertainment.', 'Features thrilling beach sports including parasailing, jet-skiing, ATV quad biking on tidal sands, and beach volleyball.', 'Famous for its seafood festival showcasing authentic Portuguese-Goan-Gujarati coastal fusion cuisine.', ARRAY['Watersports competitions and parasailing flights over the Arabian Sea', 'Live culinary demonstrations by master chefs cooking fresh lobsters, crabs, and tiger prawns', 'Nightly open-air musical concerts and Bollywood/Sufi fusion bands on the beach']::TEXT[], 'Families stroll along the wide casuarina-fringed sands, sipping fresh coconuts, riding ATVs, and relishing grilled seafood as the sun sets over the ocean.', ARRAY['Daman Garlic Prawns', 'Stuffed Crab', 'Tandoori Pomfret', 'Fish Curry Rice', 'Bebinca']::TEXT[], 'Beach casuals, floral resort wear, sunglasses, and flip-flops.', 'Live rock bands, Bollywood fusion, DJ sets on the beach, and Portuguese folk dance performances.', 'Wide black-sand beach of Jampore, casuarina groves, fluttering beach flags, and glowing sunsets.', '3 Days', 'Gregorian / Winter', 'Held in December / January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Held annually during the winter holiday season.', '2026-12-25', '2027-12-24', 'Department of Tourism Daman & Diu', ARRAY['Dadra and Nagar Haveli and Daman and Diu']::TEXT[], ARRAY['Daman']::TEXT[], ARRAY['Jampore Beach', 'Devka Beach']::TEXT[], 'Afternoon 3 PM onwards for watersports and evening beachside concerts', 2, 'Relaxed, breezy coastal getaway vibes with gentle waves, adrenaline-packed watersports, and delicious freshly caught seafood.', '15 km from Vapi railway station; auto-rickshaws and cabs connect easily to beaches.', 'Beachfront resorts, luxury hotels, and boutique stays across Daman.', 'Check tide timings before venturing far out onto the shallow tidal sands of Jampore Beach.', 'Dispose of food wrappings in beach trash bins; obey lifeguards during water sports.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://daman.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ganesh-chaturthi-maharashtra', 'Ganesh Chaturthi Mumbai & Pune', ARRAY['Ganeshotsav Maharashtra']::TEXT[], 'Spiritual & Temple', 'Hinduism (Smartism & National Unity)', 'The colossal 10-day festival where millions welcome Lord Ganesha into homes and giant public pandals, culminating in earth-shaking immersion processions into the Arabian Sea.', 'Celebrated since the Satavahana dynasty, elevated into a magnificent public national movement in 1893 by freedom fighter Lokmanya Bal Gangadhar Tilak in Pune and Mumbai.', 'Commemorates the manifestation of Lord Ganesha, the elephant-headed remover of obstacles and god of wisdom.', 'To invoke Lord Ganesha''s blessings for auspicious beginnings, wisdom, and communal solidarity.', 'The defining cultural festival of Maharashtra, famous for monumental community idols (Lalbaugcha Raja) and thundering Dhol-Tasha pathaks.', 'Culminates on Anant Chaturdashi with the immersion (Visarjan) of hundreds of thousands of idols into the Arabian Sea at Girgaon Chowpatty.', ARRAY['Prana Pratishtha ritual invocation of life into the clay Ganesha idol', 'Performance of continuous Aarti with camphor lamps and chanting of ''Sukh Karta Dukh Harta''', 'Grand Visarjan immersion procession accompanied by 100-member Dhol-Tasha drumming troupes']::TEXT[], 'The streets of Mumbai and Pune vibrate with thundering drumbeats, clouds of orange gulal, and joyful shouts of ''Ganpati Bappa Morya, Pudhchya Varshi Lavkar Ya!''.', ARRAY['Ukadiche Modak (steamed rice-flour dumplings filled with fresh coconut and jaggery)', 'Puran Poli', 'Karanji', 'Kothimbir Vadi', 'Sheera']::TEXT[], 'Traditional Maharashtrian attire: bright Kurta-Pajama with saffron Feta (turban) for men; Nauvari (nine-yard) silk sarees with Nath (nose ring) for women.', 'Thunderous, synchronized beats of 100-member Dhol-Tasha-Dhwaj pathaks, Lezim dance, and soul-stirring Marathi aartis.', 'Clay idol of Lord Ganesha with modak in hand, red hibiscus flowers, Durva grass blades, and glowing pandal chandeliers.', '10 Days', 'Hindu Lunisolar', 'Bhadrapada Shukla Chaturthi to Anant Chaturdashi (August - September)', 'August - September', 'LUNISOLAR', 'Begins Bhadrapada Shukla Chaturthi and ends Anant Chaturdashi.', '2026-09-14', '2027-09-04', 'Brihanmumbai Sarvajanik Ganeshotsav Samanway Samiti & Maharashtra Tourism', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai', 'Pune', 'Nagpur', 'Nashik']::TEXT[], ARRAY['Lalbaugcha Raja Mumbai', 'Girgaon Chowpatty', 'Shreemant Dagdusheth Halwai Ganpati Pune']::TEXT[], 'Anant Chaturdashi day for the epic immersion procession at Girgaon Chowpatty and dawn pandal hopping', 3, 'Unrivaled emotional and rhythmic high: the earth shakes under hundreds of thundering drums, tears of devotion flow, and boundless collective joy unifies the city.', 'Mumbai Suburban Railway, Metro, and BEST buses operate 24/7 during Visarjan; major roads are pedestrianized.', 'Hotels across Mumbai and Pune; reserve well in advance for Ganeshotsav week.', 'Monumental crowds (millions on streets); keep personal belongings secure; follow police movement corridors.', 'Use eco-friendly clay (Shadu mati) idols; adhere to designated artificial immersion tanks to protect marine ecology.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gudi-padwa', 'Gudi Padwa Mumbai & Nagpur', ARRAY['Marathi New Year', 'Chaitra Shukla Pratipada']::TEXT[], 'Seasonal & Nature', 'Hinduism (Marathi New Year & Victory)', 'The glorious Marathi New Year celebrated with traditional victory standards (Gudis) erected outside homes and vibrant traditional motorcycle rallies (Shobha Yatras).', 'Celebrated since ancient times; according to legend, Lord Rama returned to Ayodhya and crowned king after defeating Ravana on this day; also marks the victory of King Shalivahana.', 'Celebrates the arrival of spring, harvest of the rabi crop, and the first day of the Chaitra month in the Shalivahana Saka calendar.', 'To welcome good fortune, health, and prosperity, and celebrate Maharashtrian cultural pride and martial valor.', 'Features the iconic ''Swagat Yatra'' or ''Shobha Yatra'' where women in Nauvari sarees ride motorcycles wearing sunglasses and saffron turbans.', 'The ''Gudi'' standard (an inverted copper pot draped in silk with neem leaves and sugar crystals) symbolizes victory over negativity.', ARRAY['Erection of the sacred Gudi standard at the entrance of household balconies at sunrise', 'Eating the auspicious bitter-sweet mixture of neem leaves, jaggery, and tamarind to symbolize life''s varied experiences', 'Grand community Shobha Yatra with traditional Lezim, Dhol-Tasha, and cultural floats']::TEXT[], 'Families wake before dawn, decorate doorways with colorful Rangoli and mango leaf torans, and wear new clothes to greet neighbors with ''Gudi Padvyachya Hardik Shubhechha!''.', ARRAY['Puran Poli with Katachi Amti', 'Shrikhand with hot Puris', 'Batata Vada', 'Basundi', 'Kaju Katli']::TEXT[], 'Traditional Nauvari (nine-yard) Paithani silk sarees, Kolhapuri chappals, traditional gold jewelry (Thushi, Nath), and crisp Kurta-Dhotis with saffron turbans.', 'Dynamic Lezim folk dance, high-energy Dhol-Tasha percussion troupes, and traditional Tutari horn blasts.', 'Erected Gudi standard with copper pot (Kalash), bright yellow marigold torans, and intricate powdered Rangoli.', '1 Day', 'Hindu Lunisolar (Shalivahana Saka)', 'First day of Shukla Paksha in Chaitra month (Chaitra Pratipada)', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Shukla Pratipada.', '2026-03-20', '2027-04-07', 'Maharashtra Cultural Affairs & Local Municipal Corporations', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai (Girgaon/Dadar)', 'Pune', 'Thane', 'Nagpur', 'Kolhapur']::TEXT[], ARRAY['Girgaon Shobha Yatra Mumbai', 'Dadar', 'Tilak Road Pune']::TEXT[], 'Morning between 7 AM and 11 AM during the grand Shobha Yatra in Girgaon or Thane', 1, 'Vibrant Maharashtrian cultural pride, dazzling traditional costumes, thunderous drums, and the joyful spirit of renewal in the spring sunshine.', 'Easily accessible across Mumbai and Pune via local trains, metro, and auto-rickshaws.', 'Hotels throughout Mumbai and Pune.', 'Warm spring morning; stay hydrated during the walking street processions.', 'Accept the traditional neem-jaggery prasad graciously; participate respectfully in the street festivities.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-elephanta-festival', 'Elephanta Cultural Festival Elephanta Island', ARRAY['Elephanta Caves Cultural Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Dance & Rock-Cut Architecture', 'A magical two-day festival of classical music and dance staged against the 6th-century rock-cut caves and colossal three-headed Sadashiva sculpture on Elephanta Island.', 'Initiated in 1989 by Maharashtra Tourism Development Corporation (MTDC) on the UNESCO World Heritage island of Gharapuri (Elephanta).', 'Celebrates the monumental rock-cut cave art of ancient India and the eternal dance of Lord Shiva (Nataraja).', 'To promote heritage appreciation and present master classical dancers against an evocative ancient stone backdrop.', 'Staged on the open-air stone plaza outside Cave 1, overlooking Mumbai''s illuminated coastal skyline across the Arabian Sea.', 'Features legendary exponents of classical dance and music under the moonlit sky.', ARRAY['Ferry ride across Mumbai harbour from Gateway of India to Elephanta Island', 'Illumination of the ancient 6th-century rock-cut cave pillars and sculptures', 'Classical dance and music performances by Padma awardees on the open-air stage']::TEXT[], 'Connoisseurs board evening ferries, walk up the ancient stone steps, and sit enraptured as classical dancers perform beneath ancient basalt sculptures.', ARRAY['Fresh coastal seafood delicacies', 'Vada Pav', 'Modak', 'Puran Poli', 'Solkadhi']::TEXT[], 'Refined formal Indian ethnic wear, light evening shawls, and comfortable walking shoes.', 'Classical Bharatanatyam, Kathak, Odissi, sitar and flute jugalbandis, and soulful classical vocal recitals.', 'Colossal three-headed Sadashiva basalt sculpture, rock-cut pillars, and glittering night lights of Mumbai harbour.', '2 Days', 'Gregorian / Winter', 'Held in February / March annually.', 'February - March', 'ORGANIZER_ANNOUNCED', 'Announced annually by MTDC.', '2026-02-21', '2027-02-20', 'Maharashtra Tourism Development Corporation (MTDC)', ARRAY['Maharashtra']::TEXT[], ARRAY['Elephanta Island (Gharapuri)', 'Mumbai']::TEXT[], ARRAY['Elephanta Caves Amphitheatre']::TEXT[], 'Evenings between 5 PM and 9:30 PM for sunset ferry ride and floodlit classical concerts', 2, 'Extraordinary, timeless aesthetic romance: sitting on an ancient island surrounded by 1,500-year-old rock-cut sculptures with classical ragas echoing over the ocean.', 'Scenic 1-hour ferry ride from Gateway of India, followed by a short walk or toy train ride to the cave steps.', 'Hotels in South Mumbai (Colaba, Fort, Marine Drive); return ferries operate after concerts.', 'Climbing 120 stone steps to the caves; wear comfortable flat walking shoes.', 'Strict archaeological protection: no touching ancient basalt carvings; no flash photography inside cave chambers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ellora-ajanta-festival', 'Ellora-Ajanta International Festival', ARRAY['Chhatrapati Sambhajinagar Heritage Fest']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Arts & UNESCO Cave Architecture', 'A world-class celebration of classical music and dance staged against the monumental rock-cut monolithic marvel of the Kailasa Temple at Ellora.', 'Initiated in the 1980s by Maharashtra Tourism to showcase the cultural brilliance of the UNESCO World Heritage sites of Ellora and Ajanta.', 'Celebrates India''s peerless architectural, sculptural, and performing arts heritage.', 'To provide a global platform for master classical performing artists against the greatest monolithic rock-cut monument in the world.', 'The Kailasa Temple (Cave 16), carved out of a single volcanic basalt cliff, serves as the most awe-inspiring natural stage backdrop on earth.', 'Presents the finest exponents of Indian classical dance, vocal music, and instrumental jugalbandis.', ARRAY['Dramatic illumination of the 30-meter-tall monolithic Kailasa Temple facade', 'Nightly classical music and dance recitals by living legends of Indian arts', 'Daytime heritage seminars and guided art walks through the Buddhist, Hindu, and Jain caves']::TEXT[], 'Audience members sit under cool winter skies, captivated as classical dancers perform complex rhythmic footwork beneath the ancient carved stone elephants.', ARRAY['Naan Qalia (historic Awadhi-style meat stew of Aurangabad)', 'Puran Poli', 'Tahri', 'Mawa Jalebi', 'Hurda']::TEXT[], 'Formal ethnic Indian wear: silk kurtas, bandhgalas, and Paithani silk sarees.', 'Classical Kathak, Odissi, Kuchipudi, Carnatic vocal recitals, sitar-sarod jugalbandis, and Sufi Qawwalis.', 'Carved monolithic stone temple shikhara, life-size sculpted rock elephants, and dramatic golden illumination.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by MTDC.', '2026-01-23', '2027-01-22', 'Maharashtra Tourism (MTDC) & ASI', ARRAY['Maharashtra']::TEXT[], ARRAY['Ellora', 'Chhatrapati Sambhajinagar (Aurangabad)']::TEXT[], ARRAY['Kailasa Temple Complex Ellora (Cave 16)']::TEXT[], 'Evenings between 6 PM and 10 PM when the Kailasa Temple is illuminated for classical concerts', 3, 'Transcendental, awe-inspiring communion with India''s highest artistic and architectural genius, under open star-studded skies.', '30 km from Chhatrapati Sambhajinagar Airport and railway station; easily reached by highway taxi.', 'Hotels and heritage resorts in Chhatrapati Sambhajinagar and near Ellora caves.', 'Chilly winter evenings; carry a warm shawl or jacket; seating is on designated chairs and stone steps.', 'Strict archaeological heritage conservation rules apply; maintain silence during classical recitals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pandharpur-wari', 'Pandharpur Wari Ashadhi Ekadashi', ARRAY['Warkari Yatra Pandharpur']::TEXT[], 'Spiritual & Temple', 'Hinduism (Bhakti / Varkari Tradition)', 'The epic 21-day walking pilgrimage where over one million white-clad Varkaris walk 250 km singing abhangas to reach Lord Vitthal at Pandharpur.', 'Unbroken tradition dating back over 800 years, led by the sacred padukas (footprints) of saint-poets Sant Dnyaneshwar and Sant Tukaram.', 'Commemorates the supreme egalitarian Bhakti movement of Maharashtra, where caste and social hierarchies are completely dissolved in love for Lord Vitthal.', 'To reach Pandharpur on the sacred dawn of Ashadhi Ekadashi to behold the smiling black stone image of Vitthal (Vithoba) and Rukmini.', 'One of the most extraordinary mass spiritual walking journeys on earth, recognized for its zero-crime, self-managed community discipline.', 'Features the breathtaking ''Ringan'' ritual, where a sacred riderless horse (Ashwa) gallops through circular rings of hundreds of thousands of pilgrims.', ARRAY['Barefoot walking across Maharashtra carrying saffron flags (Patakas) and singing abhangas', 'Performance of the dramatic Ringan ritual where the sacred horse gallops through kneeling crowds', 'Taking the holy cleansing bath in the sacred Chandrabhaga River at Pandharpur']::TEXT[], 'Over one million pilgrims in white dhotis dance and sing continuously with cymbals, chanting ''Gyanba Tukaram'' across open rural roads.', ARRAY['Pithla Bhakri', 'Shengdana Chutney', 'Sabudana Khichdi (on Ekadashi fasting day)', 'Sheera', 'Ambil (fermented millet porridge)']::TEXT[], 'Simple traditional white cotton dhotis, white topis (Nehru caps), and saffron flags; women carry Tulsi pots on heads.', 'Soul-stirring singing of Marathi Abhangas by Tukaram and Dnyaneshwar, accompanied by Chipli cymbals, Mridangam, and Veena.', 'Saffron triangular flags (Patakas), Tulsi pots balanced on heads, sacred palanquins (Palkhis), and Chandrabhaga river ghats.', '21 Days', 'Hindu Lunisolar', 'Culminates on Ashadhi Ekadashi (11th day of Shukla Paksha in Ashadha month)', 'June - July', 'LUNISOLAR', 'Culminates on Ashadhi Ekadashi.', '2026-07-25', '2027-07-15', 'Shree Vitthal Rukmini Mandir Samiti & Pandharpur Municipal Council', ARRAY['Maharashtra']::TEXT[], ARRAY['Pandharpur', 'Alandi', 'Dehu', 'Pune']::TEXT[], ARRAY['Vitthal Rukmini Temple Pandharpur', 'Chandrabhaga River Ghats']::TEXT[], 'Ashadhi Ekadashi dawn at Pandharpur and witnessing the Ringan ceremony in rural Pune/Solapur', 4, 'Life-transforming wave of pure, selfless devotion, boundless egalitarian fellowship, ringing brass cymbals, and tears of joy before Lord Vitthal.', 'Pandharpur is connected by rail from Pune and Solapur; walking routes are dedicated pedestrian corridors.', 'Huge tented cities and pilgrim shelters at Pandharpur; advance booking essential.', 'Gigantic crowd of over one million; queue for Padsparsha Darshan can take 12-24 hours; Mukh Darshan is faster.', 'Embrace the egalitarian spirit of the Varkaris: greet every pilgrim with ''Ram Krishna Hari''; remove footwear before stepping onto ghats.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://solapur.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-banganga-music-festival', 'Banganga Classical Music Festival', ARRAY['Walkeshwar Heritage Music Festival']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Heritage & Sacred Waters', 'A magical two-day festival of classical Indian music staged on the ancient stone steps of the sacred Banganga Tank in Malabar Hill, Mumbai.', 'Initiated in 1992 by Maharashtra Tourism Development Corporation (MTDC) and the Indian Heritage Society around the historic 12th-century tank.', 'Celebrates the mythical origin of the freshwater spring created when Lord Rama shot an arrow (Bana) into the earth to quench Sita''s thirst.', 'To promote conservation of Mumbai''s oldest surviving heritage precinct and present master musicians in an intimate acoustic setting.', 'Set around the ancient rectangular stepped water reservoir, surrounded by centuries-old temples, samadhis, and flickering oil lamps.', 'Legendary maestros including Pt. Hariprasad Chaurasia, Ustad Zakir Hussain, and Begum Parveen Sultana have performed on its floating stages.', ARRAY['Lighting of hundreds of traditional earthen lamps along the ancient stone steps of the tank', 'Classical vocal and instrumental recitals on a floating stage in the center of the water', 'Heritage walks exploring the Walkeshwar temple precinct and ancient samadhis']::TEXT[], 'Connoisseurs sit along the ancient stone steps in the cool sea breeze, listening to sublime evening ragas reflecting off the tranquil water.', ARRAY['Puran Poli', 'Batata Vada', 'Sabudana Vada', 'Maharashtrian Kothimbir Vadi', 'Filter Coffee']::TEXT[], 'Refined formal ethnic wear: handloom kurtas, silk sarees, and evening shawls.', 'Sublime Hindustani classical music: flute, Santoor, sitar, sarangi, Khayal vocal recitals, and tabla solos.', 'Ancient stepped stone reservoir, wooden marker poles in water, brass temple bells, and flickering oil lamps.', '2 Days', 'Gregorian / Winter', 'Held in January annually.', 'January', 'FIXED', 'Held annually over a January weekend.', '2026-01-10', '2027-01-09', 'Maharashtra Tourism & Indian Heritage Society', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai', 'Malabar Hill']::TEXT[], ARRAY['Banganga Tank Walkeshwar']::TEXT[], 'Evenings between 6:30 PM and 10 PM under the starlit sky', 2, 'Enchanting, secluded oasis of ancient spiritual peace tucked away inside bustling South Mumbai, with sublime classical melodies floating over sacred water.', 'Located in Walkeshwar, Malabar Hill; accessible by taxi from Chhatrapati Shivaji Maharaj Terminus (CSMT) or Churchgate.', 'Hotels throughout South Mumbai (Marine Drive, Fort, Colaba).', 'Steep, narrow ancient stone steps around the tank; watch your step in dim lighting.', 'Maintain pin-drop silence during delicate classical recitals; no flash photography.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-narali-purnima', 'Narali Purnima Koli Fishing Community', ARRAY['Coconut Day Mumbai']::TEXT[], 'Seasonal & Nature', 'Hinduism & Maritime Fisherfolk Culture', 'The colorful coastal festival of Mumbai''s original inhabitants (the indigenous Kolis), offering golden coconuts to the sea to mark the end of the monsoon.', 'Ancient festival celebrated by the indigenous Koli fisherfolk who inhabited the seven islands of Bombay long before modern urbanization.', 'Commemorates the appeasement of Lord Varuna (God of Waters) to calm monsoon storms and bless the upcoming fishing season.', 'To express gratitude to the Arabian Sea for sustaining fisherfolk livelihoods and pray for safe ocean voyages.', 'Celebrates Mumbai''s authentic indigenous heritage across historic Koliwadas (Worli, Versova, Khar Danda, Mahim).', 'Boats are freshly painted, decorated with colorful paper buntings, and fitted with new fishing nets.', ARRAY['Procession carrying gold-and-silver foil-wrapped coconuts to the seashore with brass bands', 'Offering of coconuts into the Arabian Sea waves with prayers to Lord Varuna', 'Blessing and launching of fishing trawlers into the open ocean after months of monsoon hiatus']::TEXT[], 'Koliwada lanes overflow with vibrant music, traditional dances, and festive feasts, as fisherfolk celebrate the reopening of the sea.', ARRAY['Narali Bhaat (sweet coconut rice flavored with cloves, cardamom, and saffron)', 'Koli Prawn Curry', 'Bombil Fry (Bombay Duck)', 'Crab Masala', 'Karanji']::TEXT[], 'Traditional Koli attire: vibrant Nauvari sarees draped above the knees with heavy gold jewelry for women; colorful shirts, lungis, and caps for men.', 'Energetic Koli folk dances mimicking ocean waves, casting nets, and hauling fish, accompanied by Dholak and brass instruments.', 'Gold-wrapped coconuts, colorful painted fishing boats, traditional Koli flags, and the Arabian Sea coastline.', '1 Day', 'Hindu Lunisolar', 'Shravana Purnima (full moon day of Shravana month in August)', 'August', 'LUNISOLAR', 'Celebrated on Shravana Purnima (same day as Raksha Bandhan).', '2026-08-28', '2027-08-17', 'All Assam / All Mumbai Koli Samaj & Maharashtra Tourism', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai (Versova, Worli, Mahim)', 'Alibaug', 'Thane']::TEXT[], ARRAY['Versova Koliwada', 'Worli Koliwada', 'Girgaon Chowpatty']::TEXT[], 'Late afternoon from 3:30 PM to 7 PM for the coastal processions and boat blessing', 1, 'Joyful, salt-tinged immersion into Mumbai''s original indigenous fishing culture, packed with infectious music, dazzling gold, and delicious seafood.', 'Easily accessible across Mumbai''s coastal koliwadas via auto-rickshaw, taxi, and local trains.', 'Hotels throughout Mumbai.', 'Monsoon beach conditions; follow safety instructions near breaking waves.', 'Respect the cultural authenticity of the Koli community; purchase fresh seafood snacks from local women cooperatives.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kala-ghoda-arts-festival', 'Kala Ghoda Arts Festival Mumbai', ARRAY['KGAF Mumbai']::TEXT[], 'Art & Cultural Festival', 'Secular / Street Art & Multidisciplinary Culture', 'Asia''s largest multicultural street festival transforming the historic Victorian Gothic heritage precinct of South Mumbai into an open-air wonderland of arts.', 'Founded in 1999 by the Kala Ghoda Association to preserve, restore, and upgrade the historic heritage arts district of South Mumbai.', 'Celebrates the cosmopolitan artistic energy, architectural legacy, and creative talent of Mumbai.', 'To fund the architectural conservation of heritage buildings in the precinct through an entirely free, non-ticketed public arts festival.', 'Features 14 diverse cultural sections: visual arts, literature, theatre, cinema, dance, music, heritage walks, street food, and children''s workshops.', 'The iconic black horse equestrian statue (Kala Ghoda) stands at the center of the pedestrianized festival streets.', ARRAY['Exhibition of monumental public art sculptures made of recycled materials along Rampart Row', 'Open-air classical and contemporary dance performances at Cross Maidan', 'Nightly musical concerts featuring celebrated artists at Asiatic Library steps']::TEXT[], 'Over 150,000 visitors stroll through pedestrianized heritage avenues daily, taking selfies with giant art installations, browsing craft stalls, and attending author talks.', ARRAY['Mumbai Cutting Chai', 'Vada Pav', 'Pav Bhaji', 'Artisanal Gelato', 'Irani Cafe Bun Maska']::TEXT[], 'Trendy contemporary urban wear, artistic ethnic scarves, comfortable sneakers, and bohemian cotton kurtas.', 'Classical dance dramas, world jazz, indie rock bands, street theatre, and acoustic fusion music.', 'Equestrian black horse statue, monumental street art installations, and Victorian Gothic heritage facades.', '9 Days', 'Gregorian / Annual', 'First Saturday of February to the second Sunday of February.', 'February', 'FIXED', 'Held annually during the first full week of February.', '2026-02-07', '2027-02-06', 'Kala Ghoda Association & Maharashtra Tourism', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai']::TEXT[], ARRAY['Kala Ghoda Precinct', 'Rampart Row', 'Cross Maidan', 'Asiatic Library Steps']::TEXT[], 'Afternoon from 2 PM to 5 PM for art installation viewing and evening concerts at Asiatic Steps', 3, 'Vibrant, intellectual, creative street carnival buzzing with artistic brilliance, historical architectural grandeur, and Mumbai''s inimitable energetic spirit.', '10-minute walk from Churchgate and CSMT railway stations; app cabs easily available.', 'Extensive hotels across South Mumbai (Fort, Colaba, Marine Drive).', 'Massive weekend crowds; watch out for personal belongings; entire precinct is pedestrian-only.', 'Do not touch or lean against fragile street art installations; keep streets clean.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kalaghodaassociation.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chikoo-festival-dahanu', 'Chikoo Festival Dahanu & Bordi', ARRAY['Dahanu Chikoo Utsav']::TEXT[], 'Harvest & Agriculture', 'Secular / Agro-Tourism & Tribal Heritage', 'A delightfully rustic agro-tourism festival celebrating the GI-tagged sweet Dahanu Gholvad Chikoo (sapodilla) and Warli tribal culture amidst coastal orchards.', 'Initiated in 2013 by the Dahanu Taluka Environment Protection Authority and local farmers to celebrate the century-old chikoo farming heritage.', 'Celebrates the agricultural heritage of the coastal chikoo belt introduced to Dahanu by Sir Dinshaw Petit in 1898.', 'To promote sustainable agro-tourism, support indigenous Warli tribal artisans, and showcase rural Maharashtrian hospitality.', 'Celebrates the GI-tagged ''Dahanu Gholvad Chikoo'', prized across India for its exceptionally sweet, calcium-rich golden pulp.', 'Features innovative chikoo-based culinary creations, orchard farm tours, and traditional Warli folk dances.', ARRAY['Guided farm tours through 100-year-old shaded chikoo orchards with fruit plucking', 'Tasting of innovative chikoo products (chikoo chips, wine, ice cream, halwa, and milkshakes)', 'Warli tribal art workshops and Tarpa folk dance performances in farm courtyards']::TEXT[], 'Families wander through cool, leafy green chikoo groves, cycling along quiet coastal roads and savoring rustic farm-to-table village meals.', ARRAY['Chikoo Halwa', 'Chikoo Ice Cream', 'Chikoo Chips', 'Pithla Bhakri', 'Fresh Neera juice']::TEXT[], 'Comfortable rural casuals, sun hats, cotton shirts, and walking shoes.', 'Hypnotic Warli Tarpa dance with village elders playing the gourd horn, and lively Dholak drumming.', 'Clusters of velvety brown chikoo fruit, green orchard canopies, Warli wall murals, and Bordi beach sands.', '2 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Chikoo Festival Organizing Committee.', '2026-02-14', '2027-02-13', 'Maharashtra Tourism & Dahanu Farmers Association', ARRAY['Maharashtra']::TEXT[], ARRAY['Dahanu', 'Bordi', 'Palghar']::TEXT[], ARRAY['Bordi Beach Grounds', 'Chikoo Orchards Gholvad']::TEXT[], 'Morning orchard walkthroughs and afternoon beachside craft shopping', 2, 'Wholesome, refreshing rural farm retreat with sweet fruit aromas, peaceful coastal village paths, and authentic Warli tribal hospitality.', '135 km north of Mumbai on Western Railway line (Dahanu Road station); 2.5 hours by car via NH-48.', 'Rustic farmstays, beachside eco-resorts, and heritage bungalows in Dahanu and Bordi.', 'Sunny daytime; carry sun protection, water bottles, and comfortable footwear for farm walking.', 'Support local farmers by purchasing certified GI-tagged chikoos and organic processed products directly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chikoofestival.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-marathwada-mahotsav', 'Marathwada Mahotsav Aurangabad', ARRAY['Chhatrapati Sambhajinagar Cultural Fest']::TEXT[], 'Historical & Royal', 'Secular / Maratha Heritage & Folk Arts', 'A vibrant festival celebrating the rich historical, linguistic, and folk traditions of the historic Marathwada region.', 'Established to commemorate the freedom struggle of the Marathwada Mukti Sangram and celebrate regional folk arts.', 'Celebrates the distinct cultural identity, Sant tradition (Eknath, Ramdas), and bravery of the people of Marathwada.', 'To preserve traditional Marathwada folk arts (Gondhal, Bharud, Powada) and promote regional handicrafts.', 'Showcases the living traditions of the celebrated Paithani silk sarees woven in nearby historic Paithan on the Godavari.', 'Features performances by master Shahirs (balladeers) singing stirring historical Powadas of Chhatrapati Shivaji Maharaj.', ARRAY['Performances of traditional Bharud (satirical folk morality plays) and Gondhal invocations', 'Recitation of heroic martial ballads (Powadas) by traditional Shahir balladeers', 'Grand exhibition of genuine GI-tagged handwoven Paithani silk sarees and Himroo shawls']::TEXT[], 'Visitors enjoy stirring ballad recitations, explore handloom weaving demonstrations, and relish traditional Marathwada culinary feasts.', ARRAY['Marathwada Hurda (roasted tender sorghum grains with spicy garlic chutney)', 'Puran Poli', 'Jowar Bhakri with Thecha', 'Gulab Jamun']::TEXT[], 'Traditional Maharashtrian attire: Paithani silk sarees, Dhotis with Pheta turbans, and ethnic kurtas.', 'Martial Powada ballads with Dhaf tambourine and Tuntune, spiritual Bharud plays, and Gondhal folk dances.', 'Paithani peacock (Mor) border motifs, Chhatrapati Shivaji Maharaj portrait, and historic Daulatabad fort ramparts.', '4 Days', 'Gregorian / Autumn', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Announced annually by Maharashtra Cultural Board.', '2026-11-20', '2027-11-19', 'Marathwada Cultural Council & Maharashtra Tourism', ARRAY['Maharashtra']::TEXT[], ARRAY['Chhatrapati Sambhajinagar', 'Paithan', 'Nanded']::TEXT[], ARRAY['Marathwada Sanskrutik Mandal Ground']::TEXT[], 'Evenings between 5:30 PM and 9:30 PM for folk performances and Powada recitals', 2, 'Stirring patriotic pride, rich folk humor of saintly Bharuds, exquisite silk handloom artistry, and rustic culinary warmth.', 'Well connected by air, rail, and road to Mumbai and Pune.', 'Extensive hotels across Chhatrapati Sambhajinagar city.', 'Good family seating arrangements; arrive early for high-profile musical and dramatic shows.', 'Buy authentic handwoven Paithani sarees directly from certified master weavers to avoid powerloom imitations.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maharashtratourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pola-festival-maharashtra', 'Pola Cattle Festival Vidarbha', ARRAY['Bail Pola Maharashtra']::TEXT[], 'Harvest & Agriculture', 'Pastoral Agriculture & Cattle Reverence', 'The deeply touching agrarian festival where farmers decorate, worship, and celebrate their working bullocks and oxen, granting them total rest from labor.', 'Ancient agricultural thanksgiving festival observed throughout Maharashtra, especially celebrated with unmatched fervor in the Vidarbha region.', 'Celebrates the vital partnership between farmers and their bullocks who plow the earth to produce food.', 'To express profound gratitude to cattle, honor Nandi (sacred bull of Lord Shiva), and celebrate agrarian fertility.', 'On this sacred day, no working animal is yoked or made to work; bullocks are treated as honored family members.', 'Bullocks are bathed in rivers, massaged with oils, their horns painted in bright colors and capped with brass bells, and draped in velvet blankets (Jhul).', ARRAY['Ritual washing and bathing of bullocks in rivers and village ponds at dawn', 'Painting bullock horns in vibrant colors and decorating them with silk tassels, flowers, and brass ornaments', 'Grand village procession where decorated bullocks are led through village gates to the temple to receive blessings']::TEXT[], 'Villages resound with joyful brass bells as beautifully adorned bullocks march through streets lined with cheering families offering sweets.', ARRAY['Puran Poli (traditional sweet flatbread offered first to the bullocks)', 'Karanji', 'Sev Bhaji', 'Jowar Bhakri with Thecha']::TEXT[], 'Traditional Maharashtrian rural attire: crisp white dhotis, white Gandhi topis or colorful turbans, and bright festive sarees.', 'Rhythmic rural drumming with Dholak and Halgi, accompanied by folk songs celebrating the strength and loyalty of bullocks.', 'Painted bullock horns decorated with peacock feathers and brass caps, velvet embroidered blankets (Jhul), and Nandi statues.', '1 Day', 'Hindu Lunisolar', 'Shravana Amavasya (new moon day of Shravana month in August - September)', 'August - September', 'LUNISOLAR', 'Celebrated on Shravana Amavasya (Pithori Amavasya).', '2026-09-10', '2027-08-31', 'Local Village Gram Panchayats & Maharashtra Agriculture Board', ARRAY['Maharashtra']::TEXT[], ARRAY['Nagpur', 'Amravati', 'Wardha', 'Akola', 'Kolhapur']::TEXT[], ARRAY['Village chaupals across Vidarbha and rural Maharashtra']::TEXT[], 'Afternoon between 2 PM and 6 PM during the grand decorated bullock procession', 1, 'Touching, authentic rural gratitude: watching rugged farmers lovingly feed sweet Puran Poli to their majestic, colorfully adorned bullocks.', 'Easily experienced in any village across Vidarbha; accessible from Nagpur or Amravati.', 'Hotels in major district centers like Nagpur, Amravati, or Wardha.', 'Large animal procession; keep a respectful safe distance from excited decorated bulls.', 'Never provoke or startle the animals; admire the traditional horn painting and artisanal decorations.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://nagpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jyotiba-fair-kolhapur', 'Jyotiba Fair Wadi Ratnagiri Kolhapur', ARRAY['Chaitra Poornima Jyotiba Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Shaivism & Royal Chhatrapati Heritage)', 'The awe-inspiring ''Pink Mountain'' fair where over one million pilgrims throw tons of bright pink Gulal powder, turning the entire mountain into a dazzling sea of magenta.', 'Ancient temple constructed in 1730 CE by Ranoji Shinde, dedicated to Lord Jyotiba, a composite incarnation of Brahma, Vishnu, and Shiva.', 'Commemorates the triumph of Lord Jyotiba in destroying the demons Kolhasur and Ratnasur to protect the Deccan plateau.', 'To climb the sacred mountain, offer Gulal, and seek divine protection and health for families.', 'Celebrated with the grand arrival of ''Sasans'' (towering 50-foot sacred wooden poles wrapped in red and gold silk) from hundreds of villages.', 'The sight of thousands of pilgrims tossing pink gulal simultaneously creates colossal clouds of magenta rising against the blue sky.', ARRAY['Arrival of towering 50-foot holy poles (Sasan Kathis) danced by village athletes', 'Continuous tossing of vibrant pink gulal powder covering the entire mountain, temple, and sky', 'Chanting of ''Jyotibachya Navana Changbhala'' (May all be auspicious in the name of Jyotiba)']::TEXT[], 'A sea of one million pink-coated devotees dances up the mountain slopes amidst blaring brass trumpets and swirling magenta dust clouds.', ARRAY['Puran Poli', 'Kolhapuri Misal', 'Tambda-Pandhra Rassa', 'Bhakri with Thecha', 'Gulal-tinged prasad laddoos']::TEXT[], 'Clothes turn completely magenta pink from flying Gulal; devotees wear dhotis, kurtas, and turbans entirely drenched in pink powder.', 'Thunderous beats of Halgi, Dhol, and Tutari horns, accompanied by roaring shouts of ''Changbhala!''.', 'Towering 50-foot Sasan poles decorated with mirrors and flags, clouds of pink Gulal, and hill temple spires.', '2 Days', 'Hindu Lunisolar', 'Chaitra Purnima (full moon night of Chaitra month in April)', 'April', 'LUNISOLAR', 'Culminates on Chaitra Purnima.', '2026-04-02', '2027-04-20', 'Western Maharashtra Devasthan Management Committee & Kolhapur Police', ARRAY['Maharashtra']::TEXT[], ARRAY['Wadi Ratnagiri', 'Kolhapur']::TEXT[], ARRAY['Jyotiba Temple Mountain Complex']::TEXT[], 'Chaitra Purnima day between 9 AM and 4 PM for the grand Sasan pole procession and pink clouds', 2, 'Spectacular, surreal visual and acoustic explosion: an entire mountain bathed in blinding magenta pink dust, echoing with thundering horns and raw human ecstasy.', '18 km north of Kolhapur city; dedicated state transport shuttle buses run continuously during the mela.', 'Hotels throughout Kolhapur city; early booking recommended.', 'Intense crowds and heavy pink Gulal powder in the air; protect eyes with goggles; wear a dust mask and old clothes.', 'Take care on steep temple stairways; follow designated police one-way movement corridors.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kolhapur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mount-mary-bandra-fair', 'Mount Mary Bandra Fair Mumbai', ARRAY['Bandra Feast Mumbai']::TEXT[], 'Spiritual & Temple', 'Christianity (Catholic Marian Devotion)', 'The historic week-long festival and fair celebrating the Nativity of the Blessed Virgin Mary at the century-old Gothic Basilica of Mount Mary in Bandra, Mumbai.', 'Dates back over 300 years to the 16th century when Jesuit priests constructed the first chapel; the present majestic neo-Gothic Basilica was consecrated in 1904.', 'Celebrates the birthday of the Virgin Mary (Mother of Jesus) and honors her miraculous intercession.', 'To offer wax figurines representing prayers (for health, homes, children, success) and seek healing and blessings.', 'One of the grandest inter-faith cultural gatherings in Mumbai, attended with equal devotion by Christians, Hindus, Muslims, and Parsis.', 'The winding stone steps of Mount Mary Hill transform into a bustling carnival fairground with hundreds of stalls selling sweets, candles, and toys.', ARRAY['Solemn Holy Mass inside the neo-Gothic Basilica of Mount Mary', 'Offering of wax body parts, homes, and cribs representing prayers at the outdoor Marian shrine', 'Browsing the historic Bandra Fair stalls along Kane Road and Mt. Mary Steps']::TEXT[], 'Lakhs of pilgrims climb the scenic hill steps overlooking the Arabian Sea, lighting candles, eating festive treats, and enjoying amusement rides.', ARRAY['Bandra Mutton/Chicken Pattice', 'Goan Chana (roasted spiced chickpeas)', 'Halwa in 10 colors', 'Kadio Bodio (sugar-coated ginger sticks)', 'Bebinca']::TEXT[], 'Sunday formal wear: elegant dresses, shirts with trousers, and festive sarees.', 'Solemn Catholic choir hymns, brass band melodies, and the lively festive hum of carnival stalls.', 'Twin spires of the neo-Gothic Mount Mary Basilica, glowing candle stands, wax prayer figurines, and Bandra sea view.', '8 Days', 'Christian Liturgical', 'Begins on the Sunday following September 8 (Nativity of Mary).', 'September', 'FIXED', 'Begins on the Sunday following September 8 annually.', '2026-09-13', '2027-09-12', 'Basilica of Our Lady of the Mount Bandra & Mumbai Police', ARRAY['Maharashtra']::TEXT[], ARRAY['Mumbai', 'Bandra West']::TEXT[], ARRAY['Basilica of Our Lady of the Mount Bandra', 'Kane Road Steps']::TEXT[], 'Weekday mornings for peaceful church visits or late afternoon for the bustling fairground experience', 2, 'Warm, inclusive Mumbai spirit where diverse faiths mingle in shared hope, surrounded by heritage colonial architecture, ocean views, and carnival sweets.', '10-minute auto-rickshaw or bus ride from Bandra Railway Station (Western & Harbour Lines).', 'Extensive hotels and boutique guesthouses across Bandra, Khar, and South Mumbai.', 'Heavy footfall on weekends; vehicle entry to Mount Mary Hill is restricted; prepare for uphill walking.', 'Maintain respectful silence inside the Basilica sanctum; keep personal belongings secure in carnival crowds.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mountmarybasilicabandra.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shivaji-jayanti-shivneri', 'Shivaji Jayanti Shivneri & Pune', ARRAY['Shiv Jayanti Maharashtra']::TEXT[], 'Historical & Royal', 'Secular / Patriotic Freedom & Chhatrapati Heritage', 'The glorious statewide celebration of the birth anniversary of Chhatrapati Shivaji Maharaj, celebrated with royal cradle ceremonies at Shivneri Fort.', 'Instituted in 1870 by social reformer Mahatma Jyotirao Phule at Raigad, and popularized into a national patriotic festival by Lokmanya Tilak in 1895.', 'Celebrates the birth of Chhatrapati Shivaji Maharaj in 1630 CE at Shivneri Fort, founder of the sovereign Maratha Empire (Hindavi Swarajya).', 'To honor Shivaji Maharaj''s ideals of righteous governance (Swarajya), military genius, religious tolerance, and women''s honor.', 'Celebrated with supreme patriotic pride across Maharashtra, featuring torch relays from mountain forts and grand cultural processions.', 'At Shivneri Fort, the formal royal cradle ceremony (Palakhi Sohla) takes place at exact birth hour in the historic fort chamber.', ARRAY['Traditional royal cradle ceremony (Janmotsav) inside the birth chamber of Shivneri Fort', 'Shiv Jyoti torch relay carried by runners from historic mountain forts to village squares', 'Grand Shobha Yatra with martial arts (Mardani Khel), sword fighting, and Dhol-Tasha']::TEXT[], 'Millions of citizens dressed in traditional attire fill the streets waving saffron Zenda flags, shouting ''Chhatrapati Shivaji Maharaj Ki Jai!''.', ARRAY['Puran Poli', 'Shrikhand Puri', 'Katachi Amti', 'Batata Vada', 'Pedas']::TEXT[], 'Crisp white Kurta-Pajamas with saffron Feta (turbans), and Nauvari sarees with traditional jewelry.', 'High-voltage Dhol-Tasha drumming, resonant Tutari horn blasts, and martial Mardani Khel sword-fighting demonstrations.', 'Saffron Maratha swallowtail flag (Bhagva Jhanda), Shivneri Fort bastion, Rajmudra royal seal, and equestrian statues.', '1 Day', 'Solar & Lunisolar (Dual Observance)', 'February 19 (official state holiday) and Phalguna Krishna Tritiya (traditional)', 'February', 'FIXED', 'Celebrated officially on February 19 annually.', '2026-02-19', '2027-02-19', 'Government of Maharashtra & Shivneri Fort Conservation Authority', ARRAY['Maharashtra']::TEXT[], ARRAY['Junnar', 'Shivneri Fort', 'Pune', 'Mumbai', 'Raigad']::TEXT[], ARRAY['Shivneri Fort Junnar', 'Shanivar Wada Pune', 'Gateway of India Mumbai']::TEXT[], 'Morning cradle ceremony at Shivneri Fort and evening Shobha Yatra in Pune or Mumbai', 2, 'Stirring patriotic goosebumps, thundering drums, sea of fluttering saffron flags, and deep collective pride in Maharashtra''s greatest historic hero.', 'Shivneri Fort is 90 km from Pune and 160 km from Mumbai; easily reached by highway buses and private cars via Junnar.', 'Hotels in Junnar town, heritage resorts near Narayangaon, or base yourself in Pune.', 'Climbing Shivneri Fort involves climbing over 400 stone steps; wear comfortable walking shoes and carry water.', 'Show supreme respect for the historical monuments and royal emblems; keep the mountain fortress clean.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pune.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-khajuraho-dance-festival', 'Khajuraho Dance Festival', ARRAY['Khajuraho Nritya Samaroh']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & UNESCO Temple Art', 'A world-renowned one-week celebration of classical Indian dance staged against the floodlit sandstone facades of the Western Group of Khajuraho Temples.', 'Initiated in 1975 by the Madhya Pradesh Kala Parishad to celebrate classical performing arts at the 1,000-year-old Chandela dynasty UNESCO monuments.', 'Celebrates the immortal synthesis of stone sculpture, classical aesthetics, and temple dance.', 'To promote high classical performing arts and highlight the architectural brilliance of the Chandela temples.', 'The Western Group of Temples (Chitragupta and Vishwanatha temples) serves as the world''s most breathtaking natural temple backdrop for classical dance.', 'Features leading exponents of Bharatanatyam, Kathak, Odissi, Kuchipudi, Mohiniyattam, and Manipuri dancing under the open night sky.', ARRAY['Nightly classical dance performances by Padma and Sangeet Natak Akademi awardees', 'Craft exhibition ''Hunar'' showcasing regional artisans and sculptors', 'Interactive morning art dialogues (''Kala Varta'') between dancers and critics']::TEXT[], 'Connoisseurs sit in rapt silence in the cool February night air, watching dancers match the exact sculptural poses carved in stone on the temple behind them.', ARRAY['Bundelkhandi Thoke', 'Mawa Jalebi', 'Dal Baati Churma', 'Rogan Josh', 'Khajuraho Sweet Rabri']::TEXT[], 'Refined formal ethnic wear: handloom Chanderi and Maheshwari silk sarees, bandhgalas, and elegant shawls.', 'Sublime classical dance dramas, mridangam and pakhawaj rhythms, classical vocal recitals, and flute melodies.', 'Intricately carved sandstone temple spires, sculpted celestial nymphs (Surasundaris), and dramatic golden floodlights.', '7 Days', 'Gregorian / Annual', 'February 20 to 26 annually.', 'February', 'FIXED', 'Held annually February 20-26.', '2026-02-20', '2027-02-20', 'Ustad Allauddin Khan Sangeet Evam Kala Akademi & MP Tourism', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Khajuraho', 'Chhatarpur']::TEXT[], ARRAY['Western Group of Temples Khajuraho']::TEXT[], 'Evenings between 6:30 PM and 10 PM during floodlit dance recitals', 3, 'Transcendental, awe-inspiring aesthetic experience where ancient sculpted sandstone dancers seem to come to life in living rhythm before your eyes.', 'Khajuraho Airport connects to Delhi/Varanasi; direct railway station; 4-hour highway drive from Jhansi.', 'Extensive luxury and heritage hotels and boutique resorts across Khajuraho.', 'Chilly February evenings in open-air auditorium; carry a warm shawl or jacket.', 'Strict archaeological protection: no touching temple carvings; photography without flash only.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://khajurahodancefestival.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tansen-samaroh-gwalior', 'Tansen Samaroh Gwalior', ARRAY['Tansen Music Festival']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Music / Gwalior Gharana', 'The oldest and most prestigious classical music festival in India, celebrated at the tomb of musical legend Mian Tansen in Gwalior.', 'Conceived in the 1930s to honor Mian Tansen, the court musician of Emperor Akbar and one of the Nine Gems (Navaratnas) of Mughal India.', 'Celebrates the pure, meditative traditions of Hindustani classical vocal and instrumental music.', 'To honor the father of north Indian classical music and promote the living heritage of the Gwalior Gharana.', 'Staged directly at the sacred Samadhi of Tansen under the legendary tamarind tree whose leaves were believed to sweeten the singing voice.', 'Features the prestigious National Tansen Samman award presented to living legends of Indian classical music.', ARRAY['Nightlong and dawn musical sessions (Baithaks) by celebrated classical maestros', 'Performance of classical Dhrupad compositions created by Tansen', 'Solemn morning floral offering and prayer at Tansen''s tomb and the grave of Sufi saint Muhammad Ghaus']::TEXT[], 'Music lovers sit cross-legged on white cotton mattresses in the open air, listening to meditative ragas from dusk until the early hours of dawn.', ARRAY['Gwalior Bedai with spicy potato curry', 'Kachori', 'Morena Gajak', 'Gwalior Jalebi', 'Rabri']::TEXT[], 'Traditional formal attire: fine white Kurtas, Nehru jackets, Pashmina shawls, and classical silk sarees.', 'Pure classical Dhrupad, Khayal, Sitar, Sarod, Rudra Veena, and subtle Tabla-Pakhawaj accompaniment.', 'Mughal-style stone mausoleum of Tansen, ancient tamarind tree, Tanpura string instruments, and white cotton shamianas.', '5 Days', 'Gregorian / Winter', 'Held in December annually.', 'December', 'ORGANIZER_ANNOUNCED', 'Organized annually in December by Ustad Allauddin Khan Sangeet Akademi.', '2026-12-19', '2027-12-18', 'MP Culture Department & Gwalior District Administration', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Gwalior']::TEXT[], ARRAY['Tomb of Tansen Hazira Gwalior', 'Gwalior Fort']::TEXT[], 'Evening baithaks (6 PM to 10 PM) and the serene Sunday morning dawn session (9 AM)', 3, 'Deeply sacred, acoustically pure musical pilgrimage where centuries-old classical melodies echo beneath the stars at the master''s resting place.', 'Gwalior Airport and major North-Central railway junction on the Delhi-Mumbai line.', 'Heritage palace hotels and modern business hotels across Gwalior.', 'Cold December nights; heavy woolens, shawls, and insulated caps essential for open-air sessions.', 'Strict classical concert etiquette: maintain silence during performances; do not walk around during raga alaap.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lokrang-festival-bhopal', 'Lokrang Festival Bhopal', ARRAY['Bhopal National Folk Festival']::TEXT[], 'Art & Cultural Festival', 'Tribal, Folk & Indigenous Heritage', 'A spectacular five-day national cultural festival organized in the City of Lakes, bringing together over 1,000 tribal and folk artists from across India.', 'Initiated on Republic Day in 1986 by the Directorate of Culture, Madhya Pradesh, to preserve and celebrate India''s indigenous tribal arts.', 'Celebrates India''s rich cultural diversity, tribal heritage, and the living arts of indigenous communities.', 'To provide a prominent urban platform for remote tribal artists and foster cross-cultural understanding.', 'Staged on the open-air cultural grounds of Ravindra Bhavan, overlooking the tranquil upper lake of Bhopal.', 'Features five distinct components: folk dance, tribal music, indigenous pottery and crafts, children''s folk theatre, and traditional tribal cuisine.', ARRAY['Grand Republic Day evening cultural inauguration featuring 28 state folk dance contingents', 'Tribal craft and live pottery demonstrations by national award winners', 'Regional food festival showcasing indigenous tribal delicacies from across India']::TEXT[], 'Visitors explore bustling craft alleys, watch thrilling folk acrobats and masked dancers, and taste authentic tribal dishes cooked over wood fires.', ARRAY['Bhopali Biryani', 'Bafla (boiled and baked wheat balls with spicy dal)', 'Mawa Baati', 'Bhopali Paan', 'Poha Jalebi']::TEXT[], 'Smart casuals, handloom stoles, ethnic kurtas, and traditional tribal textiles.', 'Energetic tribal dances: Gond Karma, Baiga Pardhauni, Bhil Bhagoria, alongside folk dances from every Indian state.', 'Tribal mud mural motifs, painted terracotta horses, bamboo pavilions, and illuminated stage sets.', '5 Days', 'Gregorian / Annual', 'January 26 to 30 annually.', 'January', 'FIXED', 'Held annually January 26-30 starting on Republic Day.', '2026-01-26', '2027-01-26', 'Adivasi Lok Kala Evam Boli Vikas Akademi & MP Culture', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Bhopal']::TEXT[], ARRAY['Ravindra Bhavan Open Air Complex Bhopal']::TEXT[], 'Evenings between 5:30 PM and 9:30 PM for main stage folk dance performances', 2, 'Vibrant, colorful celebration of India''s indigenous soul, filled with earth-shaking tribal drum rhythms, colorful feathers, and warm hospitality.', 'Easily accessible across Bhopal via auto-rickshaws, cabs, and city buses.', 'Extensive hotels and heritage properties overlooking Bhopal''s Upper Lake.', 'Pleasant winter evenings; carry a light jacket.', 'Support indigenous tribal artists by purchasing authentic handmade terracotta, brass Dhokra, and Gond paintings directly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ujjain-simhastha-kumbh', 'Ujjain Simhastha Kumbh Mela', ARRAY['Ujjain Maha Kumbh']::TEXT[], 'Spiritual & Temple', 'Hinduism (Jyotirlinga & Sacred Confluence)', 'The colossal celestial congregation held every 12 years on the banks of the holy Kshipra River at the sacred city of Lord Mahakaleshwar.', 'Celebrated since ancient Vedic times, sanctified as the city of the Greenwich of ancient Indian astronomy (Prime Meridian of Avantika).', 'Celebrates the planetary alignment when Jupiter enters Leo (Simha) and the Sun enters Aries (Mesha).', 'To take the holy Shahi Snan (royal bath) in the sacred Kshipra River and seek liberation at the Mahakaleshwar Jyotirlinga.', 'One of the four sacred Kumbh Melas of India, uniquely celebrated in the sacred city of Mahakal where Lord Shiva is the eternal king.', 'Draws over 75 million pilgrims, ascetics of thirteen Akharas, and spiritual masters during its month-long observance.', ARRAY['Grand Shahi Snan royal bathing processions of Naga sadhus into the Kshipra River at Ram Ghat', 'Midnight Bhasma Aarti at the sanctified Mahakaleshwar Jyotirlinga temple', 'Continuous religious discourses, Annakshetras serving free food, and evening Kshipra Aarti']::TEXT[], 'Ram Ghat and Dutt Akhara ghats turn into an awe-inspiring sea of faith, with millions chanting ''Jai Mahakal'' as sacred waters splash under the sun.', ARRAY['Ujjaini Poha Jalebi', 'Dal Baati Churma', 'Malpua', 'Sabudana Khichdi', 'Badaam Milk']::TEXT[], 'Simple saffron and white cotton dhotis, ascetic robes, Rudraksha malas, and modest pilgrim attire.', 'Thunderous conch shell blasts, metal damaru drums, brass bells, and roaring Shaivite chants of ''Har Har Mahadev''.', 'Sacred Kshipra River ghats, Ram Ghat temples, Mahakaleshwar golden spire, and Akhara trident flags.', '1 Month', 'Astrological / 12-Year Cycle', 'Jupiter in Leo and Sun in Aries (April - May every 12 years)', 'April - May', 'LUNISOLAR', 'Occurs every 12 years (next in 2028).', '2028-04-09', '2028-05-08', 'Ujjain Simhastha Mela Authority & Government of Madhya Pradesh', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Ujjain']::TEXT[], ARRAY['Ram Ghat Kshipra River', 'Mahakaleshwar Temple', 'Dutt Akhara']::TEXT[], 'Dawn of designated Shahi Snan dates and evening Kshipra Aarti at Ram Ghat', 4, 'Overwhelming spiritual magnitude, ancient ascetic traditions, vibrant sacred riverbanks, and profound communion with the divine energy of Mahakal.', 'Ujjain Junction is a major railway station; Indore Airport is 55 km away with 4-lane highway connectivity.', 'Massive tented pop-up cities, ashrams, and hotels; advance booking essential during Simhastha years.', 'Monumental crowds exceeding 10 million on royal bathing days; follow police crowd movement routes strictly.', 'Remove footwear before stepping onto bathing ghats; bathe strictly within safety barricades.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ujjain.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhagoria-tribal-fair', 'Bhagoria Tribal Fair Jhabua & Alirajpur', ARRAY['Bhagoria Haat Mahotsav']::TEXT[], 'Tribal & Folk Traditions', 'Bhil & Bhilala Indigenous Heritage', 'An exhilarating tribal festival of spring romance, matchmaking, and harvest joy celebrated across the weekly rural haats of Jhabua and Alirajpur.', 'Centuries-old indigenous festival of the Bhil, Bhilala, and Pateliya tribal communities, marking the conclusion of the agricultural harvest before Holi.', 'Celebrates youth, romance, harvest bounty, and thanksgiving to nature.', 'Traditionally serves as a joyous social carnival where young tribal men and women meet, express affection, and choose life partners.', 'Famous for the traditional courting ritual: a youth offers red betel leaf (Paan) to a maiden, and if she accepts, they celebrate their union.', 'Features thrilling traditional wooden Ferris wheels, dynamic tribal flute orchestras, and rhythmic community dances.', ARRAY['Brisk morning trading of silver jewelry, farming tools, and colorful clothing at the weekly haat', 'Young tribal men playing massive hollow bamboo flutes and playing traditional wooden drums', 'Joyful rides on manually operated wooden giant wheels and savouring sweet jalebis']::TEXT[], 'Tribal youth dress in striking matching outfits, wandering through the dusty rural markets in laughing groups, playing flutes and dancing.', ARRAY['Giant Jalebis (weighing up to 500 grams each)', 'Makki Ki Roti with Garlic Chutney', 'Mahua beverage (traditional sacred brew)', 'Pani Puri']::TEXT[], 'Dazzling tribal finery: women wear neon-bright Lehengas with heavy silver necklaces and armlets; men wear colorful shirts, turbans, and carry flutes and bows.', 'Hypnotic, continuous drone of giant bamboo flutes, accompanied by thundering beats of wooden Mandal drums.', 'Carved bamboo flutes, giant wooden Ferris wheels, mounds of giant golden jalebis, and tribal silver jewelry.', '7 Days (at rotating village haats)', 'Hindu Lunisolar / Spring', 'Held during the seven days immediately preceding Holi.', 'March', 'LUNISOLAR', 'Held during the week leading up to Holi in Phalguna.', '2026-02-25', '2027-03-16', 'Jhabua & Alirajpur District Administrations & MP Tourism', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Jhabua', 'Alirajpur', 'Bhabhra', 'Ranapur']::TEXT[], ARRAY['Village Haat Grounds across Jhabua and Alirajpur']::TEXT[], 'Daytime between 10 AM and 4 PM when the tribal haat reaches peak festive energy', 2, 'Authentic, infectious tribal joy, dazzling neon colors, hypnotic flute melodies echoing across rural landscapes, and uninhibited celebration of life.', '150 km from Indore (3 hours by road via Dhar); accessible by highway buses and private cars.', 'Simple guesthouses in Jhabua or base yourself in Indore and visit on day excursions.', 'Crowded and dusty rural market conditions; wear comfortable clothing and flat walking shoes.', 'Respect the cultural modesty of tribal youth; do not intrude on personal courting interactions; take photos only with polite consent.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jhabua.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mandu-festival', 'Mandu Festival', ARRAY['City of Joy Heritage Festival']::TEXT[], 'Historical & Royal', 'Secular / Afghan Architecture & Romance', 'A charming five-day festival celebrating the architectural romance, medieval Afghan monuments, and scenic plateau of Mandu (the City of Joy).', 'Initiated by Madhya Pradesh Tourism to celebrate the immortal love story of Sultan Baz Bahadur and Rani Roopmati amidst the dramatic 15th-century ruins.', 'Celebrates Mandu''s rich medieval Islamic and Afghan architectural heritage and royal courtly romance.', 'To promote heritage tourism, hot air ballooning, and eco-adventure in one of India''s most dramatic medieval ruined cities.', 'Set against the miraculous Jahaz Mahal (Ship Palace), floating between two artificial lakes, and the cliffside pavilion of Rani Roopmati.', 'Features hot air balloon flights at sunrise, cycling tours across ancient palaces, and classical-Sufi concerts at night.', ARRAY['Hot air balloon flights over the medieval ruined palaces at dawn', 'Heritage cycling tours through the ancient stone gateways (Darwazas) and baolis', 'Nightly Sufi and classical musical concerts inside illuminated medieval courtyards']::TEXT[], 'Visitors explore dramatic ruined palaces shrouded in morning mist, climb to Roopmati''s Pavilion overlooking the Narmada River, and attend moonlit concerts.', ARRAY['Mandu Tamarind (giant Baobab fruit pulp drinks)', 'Dal Bafla', 'Malwa Poha', 'Jalebi', 'Bhutte Ka Kees']::TEXT[], 'Smart casuals, comfortable walking boots, warm evening jackets, and light ethnic stoles.', 'Soulful Sufi Qawwalis, classical flute recitals, Kabir rock fusion, and traditional Malwa folk music.', 'Jahaz Mahal stone arches, giant Baobab trees, Roopmati''s cliffside pavilion, and colorful hot air balloons.', '5 Days', 'Gregorian / Winter', 'Held in December / January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Announced annually by MP Tourism.', '2026-12-28', '2027-12-28', 'Madhya Pradesh Tourism Board (MPTB)', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Mandu (Mandav)', 'Dhar']::TEXT[], ARRAY['Jahaz Mahal Complex', 'Roopmati Pavilion', 'Hindola Mahal']::TEXT[], 'Sunrise for hot air ballooning and evening 6 PM onwards for illuminated palace concerts', 2, 'Romantic, poetic medieval atmosphere with misty hilltop ruins, dramatic cliffs dropping into the Narmada valley, and soulful Sufi melodies.', '95 km from Indore Airport (2.5-hour scenic drive via Dhar); accessible by taxi or tourist bus.', 'Luxury glamping tented city set up by MP Tourism, heritage hotels, and boutique resorts in Mandu.', 'Cobbled stone pathways and undulating plateau; wear sturdy comfortable walking shoes.', 'Respect the historic monuments; hot air balloon rides require advance online booking due to limited seats.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mandufestival.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pachmarhi-utsav', 'Pachmarhi Utsav', ARRAY['Queen of Satpura Cultural Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Hill Station Ecology & Folk Arts', 'A delightful year-end cultural festival celebrated in the lush forested hill station of Pachmarhi amidst cascading waterfalls and colonial bungalows.', 'Established by the Madhya Pradesh Tourism Board to celebrate the winter season in the state''s sole hill station.', 'Celebrates the pristine biodiversity of the Satpura Tiger Reserve, British colonial heritage, and indigenous Gond-Korku tribal culture.', 'To provide a vibrant cultural retreat for travelers during the year-end holidays.', 'Set in an idyllic valley at 3,500 feet, surrounded by deep sandstone ravines, ancient rock paintings, and sal forests.', 'Features a colorful crafts bazaar, national folk dance performances, and adventure sports like paragliding and rock climbing.', ARRAY['Evening cultural concerts showcasing folk dances from across India', 'Artisan crafts fair featuring Gond tribal paintings, bamboo crafts, and wild forest honey', 'Guided nature walks to historic viewpoints like Dhoopgarh (highest peak in MP) and Bee Falls']::TEXT[], 'Visitors enjoy the pleasant mountain chill, strolling past colonial sandstone churches, exploring prehistoric cave paintings, and attending evening shows.', ARRAY['Bhutta (roasted sweet corn)', 'Dal Bafla', 'Satpura Honey pancakes', 'Poha Jalebi', 'Garam Masala Tea']::TEXT[], 'Winter woolens: warm jackets, colorful scarves, woolen caps, and comfortable hiking attire.', 'Tribal Gond and Korku folk dances, classical dance dramas, and live acoustic fusion bands.', 'Dhoopgarh mountain sunset, sandstone gorge cliffs, green pine forests, and open-air festival stage.', '5 Days', 'Gregorian / Year-End', 'December 26 to 30 annually.', 'December', 'FIXED', 'Held annually December 26-30.', '2026-12-26', '2027-12-26', 'Madhya Pradesh Tourism Board & Pachmarhi Special Area Development Authority', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Pachmarhi', 'Narmadapuram (Hoshangabad)']::TEXT[], ARRAY['Pachmarhi Golf Course Grounds', 'Dhoopgarh']::TEXT[], 'Sunset at Dhoopgarh followed by evening cultural concerts at the festival ground', 2, 'Refreshing mountain chill, fragrant pine and sal forests, dramatic sunset viewpoints, and lively folk entertainment under starry skies.', '47 km from Pipariya Railway Station (on Mumbai-Howrah mainline); easily reached by taxis and buses.', 'Colonial heritage bungalows, MP Tourism resorts, and private hotels across Pachmarhi.', 'Cold winter evenings (temperatures can drop to 3°C); carry adequate warm woolen layers.', 'Eco-sensitive biosphere reserve: plastic littering is strictly penalized; do not disturb wildlife in forest zones.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chethiyagiri-vihara-sanchi', 'Chethiyagiri Vihara Festival Sanchi', ARRAY['Sanchi International Buddhist Festival']::TEXT[], 'Spiritual & Temple', 'Buddhism (Theravada / Sacred Relics)', 'The sacred international Buddhist pilgrimage where the holy bone relics of the Buddha''s chief disciples, Sariputta and Mahamoggallana, are displayed.', 'Initiated in 1952 when the sacred relics of Sariputta and Mahamoggallana (discovered by Sir Alexander Cunningham in 1851) were returned from London and enshrined.', 'Commemorates the enshrinement of the holy relics and honors the foremost disciples of the Buddha.', 'To venerate the holy relics, seek spiritual wisdom, and celebrate universal Buddhist peace and compassion.', 'Attracts Buddhist monks, ambassadors, and pilgrims from Sri Lanka, Myanmar, Japan, Thailand, Cambodia, and Tibet.', 'The sacred golden and crystal caskets containing the bone relics are brought out of the sanctum vault for public darshan once a year.', ARRAY['Ceremonial exposition of the holy bone relics of Arahat Sariputta and Arahat Mahamoggallana', 'Chanting of the Dhammacakkappavattana Sutta and Karaniya Metta Sutta by international monks', 'Solemn circumambulation of the Great Stupa of Sanchi (UNESCO World Heritage Site)']::TEXT[], 'Monks in golden, saffron, and crimson robes lead peaceful walking processions around the ancient 3rd-century BCE stone stupa of Emperor Ashoka.', ARRAY['Sattvic vegetarian feast meals', 'Sri Lankan hoppers and tea', 'Kheer', 'Fruit prasad']::TEXT[], 'Monastic robes of various Buddhist lineages, alongside crisp white cotton pilgrim clothing.', 'Deep meditative Buddhist Pali chanting, temple bells, and gentle gong strikes.', 'Great Stupa of Sanchi with carved Torana gateways, crystal relic casket, and fluttering five-colored Buddhist flags.', '2 Days', 'Gregorian / Autumn', 'Last weekend of November annually.', 'November', 'FIXED', 'Last Saturday and Sunday of November.', '2026-11-28', '2027-11-27', 'Maha Bodhi Society of India & MP Culture Department', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Sanchi', 'Raisen', 'Bhopal']::TEXT[], ARRAY['Chethiyagiri Vihara', 'Great Stupa of Sanchi']::TEXT[], 'Morning relic exposition ceremony at 9 AM and peaceful sunset meditation at the Great Stupa', 2, 'Profound, tearful spiritual tranquility, gentle monks chanting under the Bodhi tree, and timeless monumental Mauryan stone architecture.', '46 km northeast of Bhopal on the mainline railway; easily reached by highway taxi or local train to Sanchi station.', 'Buddhist pilgrim guesthouses at the Maha Bodhi Society, MP Tourism Gateway Retreat, and hotels in Bhopal.', 'Remove footwear before climbing the stupa terraces; maintain respectful silence around meditating monks.', 'Do not lean against or touch delicate 2,000-year-old carved sandstone gateway sculptures.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-malwa-utsav', 'Malwa Utsav Indore & Ujjain', ARRAY['Malwa Cultural & Food Festival']::TEXT[], 'Art & Cultural Festival', 'Malwa Regional Heritage & Culinary Arts', 'A grand celebration of the culture, folk dances, and legendary street food of the fertile Malwa plateau, held in Indore and Ujjain.', 'Established by Madhya Pradesh Tourism to showcase the rich cultural traditions, handicrafts, and culinary heritage of the Malwa region.', 'Celebrates the peace, prosperity, and agrarian abundance nurtured by the historic Malwa dynasty and Queen Ahilyabai Holkar.', 'To promote regional tourism, support traditional craftspeople, and celebrate Malwa''s famous street food culture.', 'Held alternately at the historic Lal Bagh Palace in Indore and the sacred riverfront of Ujjain.', 'Features one of the most extensive food festivals in central India, celebrating Indore''s reputation as the culinary capital of central India.', ARRAY['Nightly folk dance and music concerts featuring regional troupes from across India', 'Sprawling artisan crafts bazaar with live demonstrations of Bagh block printing and Chanderi weaving', 'Mega food street showcasing over 100 authentic Malwa culinary specialties']::TEXT[], 'Thousands of foodies and culture lovers wander through illuminated palace grounds, relishing hot snacks and watching vibrant folk ballets.', ARRAY['Bhutte Ka Kees (grated corn cooked in milk with spices)', 'Garadu (deep-fried spiced yam)', 'Dal Bafla with Ghee', 'Indori Poha with Sev', 'Jaleba']::TEXT[], 'Smart casuals, comfortable ethnic wear, and Chanderi cotton dupattas.', 'Malwi folk dances: Matki dance with brass pots balanced on head, Aada-Khada, and lively folk songs.', 'Lal Bagh Palace ornate wrought-iron gates, brass cooking cauldrons, and colorful handicraft stalls.', '5 Days', 'Gregorian / Spring', 'Held in May annually (or rotating dates in autumn).', 'May', 'ORGANIZER_ANNOUNCED', 'Announced annually by MP Tourism.', '2026-05-08', '2027-05-07', 'Madhya Pradesh Tourism Board & Indore Municipal Corporation', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Indore', 'Ujjain']::TEXT[], ARRAY['Lal Bagh Palace Grounds Indore', 'Kshipra Riverfront Ujjain']::TEXT[], 'Evenings between 5:30 PM and 10:30 PM for street food tasting and cultural concerts', 2, 'Mouthwatering gastronomic paradise, lively folk humor, exquisite royal palace surroundings, and warm Malwi hospitality.', 'Devi Ahilyabai Holkar Airport Indore; well connected by express trains and highways.', 'Extensive luxury and business hotels across Indore.', 'Warm summer evenings; stay hydrated and wear light breathable cotton clothing.', 'Patience required around popular food stalls; maintain clean eating areas using designated waste bins.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nimar-utsav-maheshwar', 'Nimar Utsav Maheshwar', ARRAY['Maheshwar Narmada Festival']::TEXT[], 'Historical & Royal', 'Holkar Dynasty Heritage & Sacred River', 'A romantic three-day festival celebrated on the magnificent sandstone ghats of the holy Narmada River, beneath the 18th-century palace fortress of Queen Ahilyabai Holkar.', 'Initiated by Madhya Pradesh Tourism to celebrate the glorious legacy of Rani Ahilyabai Holkar and the cultural life of the Nimar region.', 'Celebrates the sacred Narmada River and the architectural and handloom heritage of Maheshwar.', 'To promote cultural tourism to Maheshwar and celebrate the world-famous handwoven Maheshwari silk saree industry.', 'Staged directly on the Ahilya Ghat steps, where towering sandstone temple carvings reflect in the calm waters of the sacred Narmada.', 'Includes thrilling traditional boat races and swimming competitions across the Narmada River.', ARRAY['Deepdaan ceremony where thousands of glowing earthen lamps are released onto the Narmada at dusk', 'Nightly classical dance and music concerts on the open-air Ahilya Ghat stone stage', 'Exhibition and live demonstrations of handloom Maheshwari saree weaving']::TEXT[], 'Connoisseurs sit on the cool stone steps as classical dancers perform beneath illuminated palace walls, with glowing lamps floating gently down the river.', ARRAY['Nimadi Dal Bafla', 'Jowar Roti with Garlic Chutney', 'Mawa Baati', 'Khargone Chilies specialties', 'Fresh sugarcane juice']::TEXT[], 'Handloom Maheshwari silk sarees with distinctive Zari borders, dhotis, and kurtas.', 'Classical dance dramas, soulful Nimadi folk singing (Nirguni bhajans), and flute melodies.', 'Sandstone temple carvings of Ahilya Ghat, Narmada river currents, floating leaf lamps, and wooden handlooms.', '3 Days', 'Hindu Lunisolar / Autumn', 'Kartik Purnima (November full moon)', 'November', 'LUNISOLAR', 'Celebrated around Kartik Purnima.', '2026-11-23', '2027-11-12', 'Madhya Pradesh Tourism Board & District Administration Khargone', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Maheshwar', 'Khargone']::TEXT[], ARRAY['Ahilya Ghat Maheshwar Fort', 'Narmada Riverfront']::TEXT[], 'Sunset on Kartik Purnima for the magnificent Deepdaan and evening classical concerts', 2, 'Incomparable serene romance: magnificent royal stone fortresses glowing in warm lights, gentle river ripples, and exquisite handloom elegance.', '90 km south of Indore Airport (2 hours by road via Dhamnod); accessible by taxi.', 'Heritage hotels within Ahilya Fort, riverside resorts, and boutique guesthouses in Maheshwar.', 'Gentle stone steps down to the river; wear comfortable walking shoes.', 'Buy authentic handwoven Maheshwari sarees directly from the Rehwa Society weaving cooperative inside the fort.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-orchha-mahotsav', 'Orchha Mahotsav', ARRAY['Orchha Cultural Festival']::TEXT[], 'Historical & Royal', 'Bundela Royal Architecture & Ram Raja Heritage', 'A captivating cultural festival celebrating the 16th-century Bundela Rajput architecture, palaces, and cenotaphs along the boulder-strewn Betwa River.', 'Organized by Madhya Pradesh Tourism in the historic capital of the Bundela kings founded by Rudra Pratap Singh in 1501 CE.', 'Celebrates Bundela royal chivalry, medieval architecture, and the unique tradition where Lord Rama is worshipped as the sovereign King (Ram Raja).', 'To showcase Orchha''s magnificent Jahangir Mahal, Raja Mahal, and Chaturbhuj Temple to cultural travelers.', 'The Ram Raja Temple is the only shrine in India where Lord Rama is worshipped as a reigning monarch, receiving daily police guard of honor salutes.', 'Features mesmerizing 3D projection mapping on palace facades, river rafting on the Betwa, and classical music recitals.', ARRAY['Guard of honor ceremony with police rifles at the Ram Raja Temple', 'Nightly 3D projection mapping and light-and-sound show on Jahangir Mahal', 'Bundeli folk dance performances and classical musical concerts in royal courtyards']::TEXT[], 'Travelers explore massive ruined palace towers with panoramic views of the Betwa river, watch soaring vultures on temple spires, and attend evening concerts.', ARRAY['Bundelkhandi Thoke', 'Dal Baati', 'Kachori', 'Mawa Jalebi', 'Amla Candy']::TEXT[], 'Traditional Bundelkhandi dhotis, colorful turbans, and elegant handloom ethnic wear.', 'Vibrant Bundeli Rai dance, Diwari stick dance with peacock feathers, and classical vocal recitals.', 'Multi-tiered domes of Jahangir Mahal, historic royal Chhatris (cenotaphs) along the Betwa, and Ram Raja palace.', '3 Days', 'Gregorian / Autumn', 'Held in October / November annually.', 'October - November', 'ORGANIZER_ANNOUNCED', 'Announced annually by MP Tourism.', '2026-11-06', '2027-11-05', 'Madhya Pradesh Tourism Board & Niwari District Administration', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Orchha', 'Niwari']::TEXT[], ARRAY['Jahangir Mahal Complex', 'Ram Raja Temple', 'Betwa Riverbank Chhatris']::TEXT[], 'Morning aarti at Ram Raja Temple and evening projection show at Jahangir Mahal', 2, 'Enchanting medieval time-capsule where monumental stone palaces, soaring cenotaphs, and rushing river rapids transport you back 500 years.', '18 km from Jhansi Junction railway station; easily reached by auto-rickshaw or taxi.', 'Heritage palace hotels (Sheesh Mahal inside the fort), riverside resorts, and boutique homestays.', 'Uneven historic stone steps and steep palace staircases; wear comfortable flat shoes.', 'Maintain decorum at Ram Raja Temple; leather items must be deposited outside before entering.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-allauddin-khan-samaroh', 'Allauddin Khan Sangeet Samaroh Maihar', ARRAY['Maihar Music Festival']::TEXT[], 'Art & Cultural Festival', 'Indian Classical Music / Maihar Gharana', 'A deeply reverent classical music festival celebrated at the birthplace of the world-famous Maihar Gharana founded by Baba Allauddin Khan.', 'Initiated to honor the legendary multi-instrumentalist Baba Allauddin Khan (1862-1972), teacher of Pt. Ravi Shankar, Ustad Ali Akbar Khan, and Annapurna Devi.', 'Celebrates the austere, disciplined traditions of the Maihar Gharana of Hindustani classical music.', 'To preserve the unique instrumental compositions and the legendary Maihar Band created by Baba Allauddin Khan.', 'Maihar is revered as a sacred musical pilgrimage where the master trained some of the greatest musical icons of the 20th century.', 'Features rare live performances by the historic ''Maihar Band'', an indigenous orchestra created by Baba using orphaned children after a plague in 1918.', ARRAY['Performance by the historic Maihar Band playing indigenous instruments (Naltarang)', 'Classical instrumental recitals by leading exponents of Sitar, Sarod, and Surbahar', 'Pilgrimage to the historic residence of Baba Allauddin Khan (Madina Bhavan)']::TEXT[], 'Connoisseurs and disciples gather in the small pilgrim town, listening in deep silence to complex classical ragas played on sarods and sitars.', ARRAY['Bundelkhandi Peda', 'Samosa', 'Puri Sabzi', 'Langar Khichdi']::TEXT[], 'Simple, refined Indian attire: white khadi kurtas, dhotis, and modest sarees.', 'Pristine Maihar Gharana instrumental classical music, Sarod solos, Sitar recitals, and orchestral band compositions.', 'Baba Allauddin Khan''s violin and sarod, Madina Bhavan courtyard, and Sharda Devi hilltop temple.', '3 Days', 'Gregorian / Winter', 'Held in February / March annually.', 'February - March', 'ORGANIZER_ANNOUNCED', 'Organized annually by Ustad Allauddin Khan Sangeet Akademi.', '2026-02-12', '2027-02-11', 'Ustad Allauddin Khan Sangeet Akademi & Satna District Administration', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Maihar', 'Satna']::TEXT[], ARRAY['Madina Bhavan Maihar', 'Town Hall Complex']::TEXT[], 'Evening sessions from 6 PM to 10 PM for authentic classical instrumental recitals', 2, 'Austere, sacred musical sanctity where modern global classical legends trace their roots back to the modest home of a saintly master.', 'Maihar railway station is well connected on the Mumbai-Howrah line; 40 km from Satna.', 'Guesthouses in Maihar and hotels in Satna city.', 'Quiet, contemplative festival; audience maintains deep silence during raga alaap.', 'Combine your visit with a climb up the 1,063 stone steps to the ancient Maa Sharda Devi Temple atop Trikuta Hill.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dhrupad-samaroh-bhopal', 'Dhrupad Samaroh Bhopal', ARRAY['Bhopal National Dhrupad Festival']::TEXT[], 'Art & Cultural Festival', 'Ancient Indian Classical Music / Dhrupad Heritage', 'The premier national festival dedicated exclusively to Dhrupad, the oldest surviving genre of Indian classical vocal and instrumental music.', 'Established by the Madhya Pradesh Culture Department to preserve and nurture the sublime meditative tradition of Dhrupad.', 'Celebrates the ancient Vedic roots of Indian music, characterized by spiritual contemplation, microtonal nuances, and profound sound resonance (Naad Brahma).', 'To provide a dedicated national platform for Dhrupad masters, disciples of the Dagar and Gwalior traditions, and new generations of practitioners.', 'Organized in close collaboration with the renowned Dhrupad Sansthan Bhopal, the premier global academy for Dhrupad training.', 'Features rare recitals on the ancient Rudra Veena, Surbahar, Pakhawaj, and contemplative multi-octave vocal alaap.', ARRAY['Meditative, unhurried solo and jugalbandi Dhrupad vocal recitals', 'Rare instrumental performances on the ancient Rudra Veena and Surbahar', 'Solo Pakhawaj rhythmic demonstrations exploring complex 14-beat Dhamar and 12-beat Chautal cycles']::TEXT[], 'Audiences sit transfixed as deep, resonant bass notes vibrate through the hall, leading the mind into deep meditative stillness.', ARRAY['Bhopali Poha', 'Sulemani Chai', 'Mawa Baati', 'Kachori']::TEXT[], 'Formal ethnic attire: khadi kurtas, silk shawls, and sarees.', 'Pure, meditative Dhrupad singing (Alaap-Jod-Jhala followed by Bandish), accompanied exclusively by Tanpura and Pakhawaj.', 'Ancient tubular Rudra Veena with double gourd resonators, barrel-shaped wooden Pakhawaj, and glowing brass oil lamps.', '3 Days', 'Gregorian / Autumn', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Announced annually by MP Culture Department.', '2026-11-13', '2027-11-12', 'Ustad Allauddin Khan Sangeet Akademi & Dhrupad Sansthan', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Bhopal']::TEXT[], ARRAY['Ravindra Bhavan Bhopal', 'Dhrupad Sansthan']::TEXT[], 'Evening sessions from 6:30 PM to 10 PM for meditative listening', 2, 'Transcendental sonic meditation: deep, primordial acoustic vibrations that quiet the modern mind and transport you to ancient Vedic hermitage roots.', 'Easily accessible in central Bhopal via taxi, auto-rickshaw, or city bus.', 'Hotels throughout Bhopal city.', 'Strict meditative listening environment; audience members maintain absolute silence and avoid exiting mid-performance.', 'Dhrupad performances involve long, gradual alaap sequences; give yourself time to settle into the meditative tempo.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhojpur-utsav', 'Bhojpur Utsav', ARRAY['Bhojeshwar Temple Cultural Mahotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism & Paramara Architecture)', 'The sacred cultural festival celebrated on Maha Shivratri at the monumental 11th-century Bhojeshwar Temple, home to one of the largest Shiva Lingams in the world.', 'Founded by the legendary polymath King Bhoja of the Paramara dynasty in the 11th century; renowned for its colossal monolithic stone architecture.', 'Celebrates Lord Shiva and honors King Bhoja''s monumental contributions to architecture, Sanskrit literature, and arts.', 'To perform sacred Abhishek on the giant 18-foot monolithic Shiva Lingam and celebrate classical cultural heritage.', 'The temple features an enormous polished stone lingam measuring 7.5 feet in height and 17.8 feet in circumference, set on a massive 20-foot square platform.', 'Surrounded by ancient rock quarries with architectural blueprints incised into the stone bedrock 1,000 years ago.', ARRAY['Continuous Maha Abhishek of the colossal monolithic Shiva Lingam with milk and holy waters on Maha Shivratri', 'Grand cultural concerts featuring classical dance and devotional music on the temple grounds', 'Heritage architectural tours explaining the unique 1,000-year-old rock-cut architectural drawings']::TEXT[], 'Tens of thousands of pilgrims climb the massive stone ramp, offering flowers and milk to the towering monolithic deity amidst chanting.', ARRAY['Prasad Laddoos', 'Sabudana Vada', 'Bhopali Mawa Jalebi', 'Puri Sabzi']::TEXT[], 'Traditional dhotis, kurtas, sarees, and modest pilgrim attire.', 'Classical dance dramas, resonant Vedic chanting, conch blasts, and devotional bhajans.', 'Colossal 18-foot polished stone Shiva Lingam, massive uncarved monolithic temple pillars, and Betwa river vistas.', '3 Days', 'Hindu Lunisolar', 'Culminates on Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Culminates on Maha Shivratri.', '2026-02-15', '2027-03-06', 'Archaeological Survey of India & MP Culture Department', ARRAY['Madhya Pradesh']::TEXT[], ARRAY['Bhojpur', 'Raisen', 'Bhopal']::TEXT[], ARRAY['Bhojeshwar Shiva Temple Complex Bhojpur']::TEXT[], 'Maha Shivratri day and evening for the grand temple illuminations and cultural concerts', 2, 'Awe-inspiring architectural and spiritual magnitude: standing dwarfed before a colossal 1,000-year-old stone god surrounded by wild rocky countryside.', '28 km southeast of Bhopal; accessible by road via taxi or state transport buses.', 'Hotels in Bhopal city; easily visited as a day trip.', 'Massive crowds on Maha Shivratri day; follow designated queue barricades to the elevated sanctum platform.', 'Explore the stone quarry behind the temple to see 11th-century architectural diagrams engraved directly into the bedrock.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mptourism.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bastar-dussehra', 'Bastar Dussehra Jagdalpur', ARRAY['World''s Longest Festival']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Shaktism & Tribal Democracy', 'The longest festival in the world spanning 75 continuous days, celebrated by indigenous tribes honoring Goddess Danteshwari with massive hand-built wooden chariots.', 'Initiated in the 13th century by King Purushottam Dev of the Kakatiya dynasty after returning from a pilgrimage to Jagannath Puri with the title of ''Rath-Pati''.', 'Unlike northern Dussehra which celebrates Rama defeating Ravana, Bastar Dussehra is dedicated entirely to Goddess Danteshwari (Mother Goddess of Bastar).', 'To honor Goddess Danteshwari, affirm tribal council governance, and celebrate nature''s bounty and tribal solidarity.', 'Spans 75 days across 13 distinct traditional phases, entirely organized by traditional village guilds (woodcutters, rope-makers, blacksmiths, chariot-pullers).', 'Features the pulling of colossal double-decker wooden chariots (Phul Rath and Bhitar Rath) hand-hewn by tribal carpenters without a single nail.', ARRAY['Pata Jatra ritual consecration of the first log of sal wood brought from the forest', 'Pulling of the massive 8-wheeled double-decker wooden chariot by thousands of tribal men using thick jungle vines', 'Muria Darbar where tribal village headmen (Manjhis) hold formal council with the royal Maharaja and state administrators']::TEXT[], 'Over 100,000 tribal people from the deep Sal forests of Bastar camp in Jagdalpur, dancing, playing massive wooden drums, and pulling the giant chariot.', ARRAY['Bafauri (steamed chana dal cakes)', 'Chilka Roti', 'Chaprah (traditional red ant chutney)', 'Mahua beverage', 'Jilabi']::TEXT[], 'Traditional tribal attire: white and red cotton dhotis, cowrie-shell headbands, horn headdresses, and silver ornaments.', 'Thunderous beats of giant Mandal and Dhol drums, wailing Mohri horns, and energetic tribal Gaur and Bison-Horn Maria dances.', 'Colossal 8-wheeled wooden chariot draped in yellow and red cloth, Goddess Danteshwari''s palanquin, and thick jungle vine ropes.', '75 Days (Peak 10 Days)', 'Hindu-Tribal Lunisolar', 'Shravana Amavasya to Ashwin Shukla Trayodashi (August - October)', 'September - October', 'LUNISOLAR', 'Peak rituals occur during the 10 days of Navratri leading to Vijyadashami.', '2026-10-11', '2027-09-30', 'Bastar District Administration & Danteshwari Temple Trust', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Jagdalpur', 'Dantewada', 'Bastar']::TEXT[], ARRAY['Sirhasar Chowk Jagdalpur', 'Danteshwari Temple']::TEXT[], 'Navratri Saptami to Vijyadashami for the chariot pulling and concluding Muria Darbar', 3, 'Astonishing, unparalleled living anthropology: witnessing the world''s longest unbroken tribal democratic festival powered by pure community muscle and faith.', 'Jagdalpur is connected by train from Visakhapatnam and Raipur; 300 km from Raipur Airport via 4-lane highway.', 'Hotels, tribal eco-resorts, and homestays across Jagdalpur; book well in advance for peak Dussehra days.', 'Massive tribal crowds; stay clear of the colossal chariot wheels when the heavy ropes are pulled.', 'Respect tribal traditions and rituals; photography is generally welcomed but ask before taking close-up portraits.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bastar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-madai-festival-bastar', 'Madai Festival Bastar & Narayanpur', ARRAY['Gond Tribal Fair']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Gond & Maria Ancestral Deities', 'A fascinating rotating tribal fair celebrated across the deep forest villages of Bastar, where village deity totems (Anga Dev) assemble to dance and prophesy.', 'Ancient tribal festival observed across Bastar and Narayanpur by the Gond, Maria, Muria, and Halba communities.', 'Celebrates the annual gathering of local deities, seasonal harvest, and community reconciliation.', 'To appease village gods, perform sacrificial thanksgiving rites, and facilitate traditional tribal courtship.', 'Centered around the ''Anga Dev''—sacred wooden palanquin totems representing village ancestral deities that are carried on shoulders and move in trance.', 'The deities are believed to physically communicate through the carriers, swaying, rushing forward, and greeting neighboring gods.', ARRAY['Procession and dynamic greeting of sacred Anga Dev wooden totems carried by shamans', 'Sacrificial offering of goats and roosters to goddess Danteshwari and local forest spirits', 'Bustling tribal forest bazaar featuring brass Dhokra crafts, wrought iron, and forest herbs']::TEXT[], 'Thousands of forest dwellers in tribal finery gather on village clearings, drinking Mahua, watching cockfights, and dancing late into the night.', ARRAY['Chaprah (red ant chutney)', 'Dubki Kadi', 'Millet beer (Landa)', 'Mahua spirit', 'Roasted meat delicacies']::TEXT[], 'Vivid tribal clothing: white loincloths, heavy brass neck-rings, cowrie shell ornaments, and peacock-feather hair pins.', 'Deep, hypnotic rhythm of Kotodoka drums, wailing bamboo horns, and circular tribal group dances.', 'Sacred Anga Dev wooden totems draped in red cloth and peacock plumes, iron tridents, and forest clearing bonfires.', '3 Days (rotates across villages)', 'Tribal Calendar / Winter', 'Celebrated from December to March across rotating Bastar villages (flagship at Narayanpur in February).', 'December - March', 'COMMUNITY_SPECIFIC', 'Rotates across villages during winter months.', '2026-02-23', '2027-02-12', 'Narayanpur District Administration & Bastar Tribal Council', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Narayanpur', 'Kondagaon', 'Jagdalpur', 'Kanker']::TEXT[], ARRAY['Narayanpur Fairgrounds', 'Village clearings across Bastar']::TEXT[], 'Daytime from 11 AM to 5 PM when deity totems assemble and tribal dancing reaches full energy', 2, 'Raw, unvarnished encounter with living animist spirituality, deep tribal community solidarity, and ancient forest rhythms.', 'Narayanpur is 120 km from Jagdalpur and 240 km from Raipur; accessible by road.', 'Simple guesthouses in Narayanpur or base yourself in Jagdalpur hotels.', 'Remote tribal heartland; travel with a knowledgeable local guide who understands Gondi dialects.', 'Show deep reverence for the sacred Anga Dev totems; never touch them or step in their path during trance movements.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://narayanpur.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rajim-kumbh-mela', 'Rajim Kumbh Mela', ARRAY['Rajim Maghi Punni Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Sacred Confluence)', 'The ''Prayag of Chhattisgarh'' celebrated on the sacred Triveni Sangam where the Mahanadi, Pairi, and Sondhur rivers meet at the 8th-century Rajiv Lochan Temple.', 'Ancient pilgrimage celebrated for over 1,200 years, centered around the 8th-century black stone temple of Lord Rajiv Lochan (Vishnu).', 'Celebrates the holy confluence of three sacred rivers and the divine blessings of Lord Vishnu.', 'To take the holy cleansing bath on Magh Purnima and offer prayers at the historic Kuleshwar Mahadev temple situated in the middle of the riverbed.', 'The largest religious gathering in Chhattisgarh, bringing together lakhs of devotees, Naga sadhus, and saints of the Kabir and Satnami traditions.', 'Features the ancient Kuleshwar Mahadev Temple built on an octagonal stone platform in the center of the riverbed, surviving centuries of monsoonal floods.', ARRAY['Holy cleansing dip at the Triveni Sangam on Magh Purnima dawn', 'Grand Shahi Snan procession of Naga sadhus and Mahamandaleshwars', 'Nightly cultural performances featuring Chhattisgarhi folk epics (Pandavani and Panthi)']::TEXT[], 'Lakhs of pilgrims camp on the sandy riverbanks, bathing at sunrise, attending Satsangs, and listening to thrilling performances of the Mahabharata.', ARRAY['Chusela (fried rice flour bread)', 'Dehrori (sweet fried rice dumplings in sugar syrup)', 'Faraa (steamed rice flour rolls)', 'Bafauri']::TEXT[], 'Simple white dhotis, cotton kurtas, and traditional Chhattisgarhi Lugda sarees.', 'Electric performances of Pandavani folk singing (Mahabharata balladry) with Tambura and Kartal, and energetic Panthi dance.', 'Confluence of three sacred rivers, 8th-century carved stone temple shikharas, and floating leaf lamps.', '15 Days', 'Hindu Lunisolar', 'Magh Purnima to Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Begins Magh Purnima and concludes Maha Shivratri.', '2026-02-01', '2027-02-20', 'Rajim Kumbh Mela Authority & Chhattisgarh Tourism', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Rajim', 'Gariaband', 'Raipur']::TEXT[], ARRAY['Triveni Sangam Rajim', 'Rajiv Lochan Temple', 'Kuleshwar Mahadev Temple']::TEXT[], 'Magh Purnima dawn for the sacred holy bath and evening Pandavani performances', 2, 'Vibrant rural spirituality, breathtaking ancient temple architecture on sandy river confluences, and world-renowned folk epic storytelling.', '45 km south of Raipur Airport; well connected by highway buses and private cars.', 'Hotels in Raipur city (1 hour away) or pilgrim dharamshalas in Rajim.', 'Dusty riverbed walking; wear comfortable walking shoes and carry sun protection.', 'Maintain deep spiritual sanctity at the river confluence; do not litter in the riverbed.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gariaband.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sirpur-dance-festival', 'Sirpur National Dance and Music Festival', ARRAY['Sirpur Heritage Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Performing Arts & Buddhist-Hindu Archaeology', 'A magnificent three-day festival of classical music and dance staged against the red-brick 7th-century Laxman Temple and ancient Buddhist monastic ruins of Sirpur.', 'Initiated by Chhattisgarh Tourism to highlight the extraordinary archaeological wealth of Sirpur, which was visited by Chinese traveler Xuanzang in 639 CE.', 'Celebrates the ancient Buddhist, Hindu, and Jain syncretic civilization that flourished along the Mahanadi River.', 'To promote archaeological conservation and present world-renowned classical performing artists in an ancient heritage setting.', 'Staged against the exquisite red-brick Laxman Temple, one of the finest surviving 7th-century brick temples in India.', 'Features performances by living legends of Indian classical dance and music alongside Chhattisgarhi folk artists.', ARRAY['Nightly classical dance and music concerts against the illuminated 7th-century red-brick temple', 'Guided archaeological walks through the grand excavated Buddhist Viharas (monasteries)', 'Exhibition of ancient terracotta sculptures and metal artifacts discovered at the site']::TEXT[], 'Connoisseurs sit beneath cold starlit skies, enraptured as classical dancers perform intricate rhythm sequences before glowing ancient brick arches.', ARRAY['Chhattisgarhi Thali: Faraa, Thetthari, Khurmi', 'Bafauri', 'Chilka Roti', 'Dal Pithi']::TEXT[], 'Refined formal ethnic wear: handloom Kosa silk sarees (pride of Chhattisgarh), bandhgalas, and shawls.', 'Classical Kathak, Odissi, Bharatanatyam, flute and sitar recitals, and traditional Chhattisgarhi Pandavani singing.', 'Exquisite red-brick carvings of Laxman Temple, excavated stone Buddha statues, and floodlit ancient pillars.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Chhattisgarh Tourism.', '2026-01-16', '2027-01-15', 'Chhattisgarh Tourism Board (CTB) & ASI', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Sirpur', 'Mahasamund', 'Raipur']::TEXT[], ARRAY['Laxman Temple Complex Sirpur']::TEXT[], 'Evenings between 6 PM and 9:30 PM for floodlit classical concerts and morning archaeological walks', 2, 'Enchanting archaeological wonderland: standing among 1,400-year-old Buddhist monasteries and red-brick temples, immersed in sublime classical arts.', '85 km east of Raipur Airport; accessible by private taxi or tourist bus via NH-53 (1.5-hour drive).', 'Heritage eco-resort by Chhattisgarh Tourism at Sirpur, or luxury hotels in Raipur city.', 'Cool January evenings; carry a warm shawl or light jacket.', 'Strict archaeological protection: no climbing or leaning against ancient fragile brick carvings.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://chhattisgarhtourism.cg.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhoramdeo-mahotsav', 'Bhoramdeo Mahotsav Kawardha', ARRAY['Khajuraho of Chhattisgarh Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Heritage & Nagara Temple Architecture', 'A premier cultural festival staged against the 11th-century carved stone temple of Bhoramdeo, nestled in the scenic Maikal hills.', 'Established by Chhattisgarh Tourism at the historic 11th-century temple built by King Ramchandra of the Nagavanshi dynasty.', 'Celebrates the synthesis of medieval stone architecture, classical performing arts, and indigenous Baiga tribal culture.', 'To showcase the ''Khajuraho of Chhattisgarh'' and celebrate regional folk arts.', 'The temple is renowned for its erotic and divine stone sculptures carved in exquisite detail on yellowish-brown sandstone.', 'Features classical dancers and musicians performing on an open-air stage against the illuminated medieval temple spire.', ARRAY['Nightly classical dance and music concerts against the illuminated 11th-century temple facade', 'Baiga tribal folk dance performances with rhythmic wooden stilts and drums', 'Artisan crafts fair showcasing indigenous Bell Metal (Dhokra) and wrought iron crafts']::TEXT[], 'Visitors admire the medieval temple carvings, watch thrilling Baiga tribal dancers leap in unison, and attend evening classical recitals.', ARRAY['Kawardha Peda', 'Chilka Roti', 'Faraa', 'Dehrori', 'Mahua tea']::TEXT[], 'Traditional handloom Kosa silk sarees, dhotis, and ethnic Indian festive wear.', 'Classical Indian dance forms, Baiga tribal Karma dance, and soulful Chhattisgarhi folk singing.', 'Carved sandstone temple spire (Shikhara), erotic sculpture panels, and forested Maikal hill backdrop.', '3 Days', 'Hindu Lunisolar / Spring', 'Held during the month of March around Holi.', 'March', 'LUNISOLAR', 'Held in Phalguna month around Holi.', '2026-03-08', '2027-03-27', 'Kawardha District Administration & Chhattisgarh Tourism', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Kawardha', 'Kabirdham']::TEXT[], ARRAY['Bhoramdeo Temple Complex']::TEXT[], 'Evening from 5:30 PM to 9 PM during floodlit temple concerts', 2, 'Serene medieval architectural splendor tucked away in forested mountain foothills, filled with captivating tribal and classical rhythms.', '130 km northwest of Raipur Airport; accessible by road via Simga and Bemetara.', 'Palace Kawardha heritage hotel, government guest houses, and hotels in Kawardha town (18 km away).', 'Pleasant spring weather; comfortable walking shoes recommended for temple grounds.', 'Strict archaeological heritage conservation rules apply; maintain respect inside the active sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kawardha.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chakradhar-samaroh', 'Chakradhar Samaroh Raigarh', ARRAY['Raigarh Classical Dance & Tabla Fest']::TEXT[], 'Art & Cultural Festival', 'Kathak Classical Dance & Percussion Heritage', 'The legendary 10-day classical music and dance festival commemorating Maharaja Chakradhar Singh, the royal patron of the Raigarh Gharana of Kathak.', 'Initiated to honor Maharaja Chakradhar Singh of Raigarh (1905-1947), an accomplished dancer, percussionist, and author who established the Raigarh Gharana of Kathak.', 'Celebrates the royal patronage of Kathak dance, intricate Tabla rhythms, and classical vocal arts.', 'To preserve the unique syncretic aesthetic of the Raigarh Gharana, which synthesized elements of Lucknow and Jaipur Kathak with tribal rhythms.', 'Held during Ganesh Chaturthi for 10 straight nights, drawing India''s most celebrated classical dancers, vocalists, and percussionists.', 'Known for its extraordinary audience: thousands of common citizens and connoisseurs sit together for 10 nights listening to high classical music.', ARRAY['Grand evening classical Kathak dance recitals by legendary exponents', 'Electrifying Tabla and Pakhawaj percussion jugalbandis', 'Conferment of the prestigious National Chakradhar Samman award']::TEXT[], 'The festival pavilion buzzes with electric energy as audiences applaud complex rhythmic footwork (Tatkar) and lightning-fast chakkars (pirouettes).', ARRAY['Chhattisgarhi Kosa Peda', 'Samosa with spicy chana', 'Faraa', 'Jalebi', 'Chakradhar Tea']::TEXT[], 'Formal Indian classical attire: silk kurtas, bandhgalas, and handloom Kosa silk sarees.', 'Exquisite Raigarh Gharana Kathak dance, thunderous Tabla solos, classical Hindustani vocal, and sitar-sarod jugalbandis.', 'Statue of Maharaja Chakradhar Singh with tabla, illuminated classical stage arches, and Kathak ankle bells (Ghungroos).', '10 Days', 'Hindu Lunisolar', 'Bhadrapada Shukla Chaturthi to Anant Chaturdashi (Ganesh Chaturthi season)', 'August - September', 'LUNISOLAR', 'Runs for the 10 days of Ganeshotsav.', '2026-09-14', '2027-09-04', 'Ustad Allauddin Khan Sangeet Akademi & Raigarh Administration', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Raigarh']::TEXT[], ARRAY['Ramleela Maidan Raigarh']::TEXT[], 'Nightly concerts from 7 PM to 11 PM during peak Kathak and Tabla performances', 3, 'High-voltage classical ecstasy where thunderous tabla beats and virtuosic Kathak footwork captivate an audience of thousands under the open sky.', 'Raigarh is a major railway station on the Mumbai-Howrah line; well connected by express trains.', 'Hotels and government guest houses across Raigarh town.', 'Massive local attendance; arrive 30 minutes before evening sessions to secure good seating.', 'Applaud appropriately with ''Wah Wah'' at the completion of complex rhythmic tihai sequences.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://raigarh.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-goncha-festival', 'Goncha Festival Jagdalpur', ARRAY['Bastar Chariot & Tupki Carnival']::TEXT[], 'Spiritual & Temple', 'Tribal Vaishnavism & Bamboo Popgun War', 'The unique tribal chariot festival celebrated alongside Jagannath Rath Yatra, famous for the playful mock war fought with bamboo popguns firing wild fruit bullets.', 'Introduced in the 14th century by King Purushottam Dev of Bastar, integrating Jagannath temple traditions with indigenous tribal playfulness.', 'Celebrates the chariot journey of Lord Jagannath, Balabhadra, and Subhadra through the tribal heartland.', 'To honor Lord Jagannath and engage in the traditional friendly mock battle with ''Tupki'' bamboo popguns.', 'Completely unique to Bastar: every child and adult carries a ''Tupki'' (a hollow bamboo cylinder with a piston) firing wild ''Peng'' berries.', 'Spectators and participants playfully shoot each other with harmless wild berries that pop with a loud ''thwack'' sound.', ARRAY['Pulling of the sacred wooden chariot of Lord Jagannath by tribal devotees down Jagdalpur main avenue', 'Playful mock battles with bamboo Tupki popguns firing wild Peng fruit bullets through the streets', 'Ceremonial darshan and distribution of sacred Mahaprasad at the historic Jagannath Temple']::TEXT[], 'Streets echo with the continuous popping sound of thousands of bamboo popguns, joyful laughter, and devotional chanting.', ARRAY['Bafauri', 'Chilka Roti', 'Jagannath Temple Khichdi Prasad', 'Jalebi', 'Sweet Bundi']::TEXT[], 'Colorful tribal and rural attire: bright shirts, dhotis, cotton sarees, and straw hats.', 'Lively tribal drumming, folk singing, and the loud rhythmic popping of bamboo Tupki guns.', 'Three wooden chariots of Lord Jagannath, handcrafted bamboo Tupki popguns, and wild yellow Peng berries.', '1 Day', 'Hindu Lunisolar', 'Ashadha Shukla Dwitiya (June - July)', 'June - July', 'LUNISOLAR', 'Celebrated on Ashadha Shukla Dwitiya (same day as Puri Rath Yatra).', '2026-07-16', '2027-07-06', 'Jagannath Mandir Trust Jagdalpur & Bastar Administration', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Jagdalpur', 'Bastar']::TEXT[], ARRAY['Jagannath Temple Jagdalpur', 'Main Road Jagdalpur']::TEXT[], 'Afternoon between 2 PM and 6 PM during the chariot procession and Tupki games', 1, 'Delightful, laugh-out-loud playful community joy where an entire city engages in a harmless, popping fruit mock-battle amidst deep spiritual devotion.', 'Easily accessible in central Jagdalpur via auto-rickshaw or walking.', 'Hotels throughout Jagdalpur city.', 'Watch your eyes: while Peng berry bullets are small wild fruits, wear sunglasses or protective glasses on streets.', 'Buy an authentic bamboo Tupki gun from local artisan stalls for a few rupees to join in the fun.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bastar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-raut-nacha-mahotsav', 'Raut Nacha Mahotsav Bilaspur', ARRAY['Yaduvanshi Martial Dance Festival']::TEXT[], 'Tribal & Folk Traditions', 'Yaduvanshi Pastoral & Martial Heritage', 'The thrilling traditional folk festival of the Yaduvanshi (cowherd) community, featuring thousands of stick-wielding warriors in mirror-work jackets.', 'Centuries-old post-Diwali martial dance tradition commemorating Lord Krishna''s victory over the tyrant King Kamsa and the martial defense of cattle.', 'Celebrates the valor, camaraderie, and divine cattle-herding heritage of the Yaduvanshi community.', 'To honor Lord Krishna, celebrate the bond between cowherds and cattle, and showcase traditional stick-fighting martial arts.', 'Features the dramatic singing of ''Dohas'' (rhyming couplets) by warriors who challenge competitor troupes in poetic duels.', 'Dancers wear heavy traditional jackets covered in hundreds of tiny mirrors and cowrie shells, carrying brass bells and polished wooden sticks.', ARRAY['Competitive marching of hundreds of decorated Raut Nacha troupes down Bilaspur streets', 'Display of synchronized stick-fighting martial choreography (Lathi Khel) and sword-defense', 'Recitation of witty and heroic couplets (Dohas) praising Lord Krishna and mocking cowards']::TEXT[], 'The stadium roars as wave after wave of warriors in jingling mirror jackets leap into the air, clashing their sticks in thunderous, lightning-fast rhythms.', ARRAY['Chhattisgarhi Faraa', 'Dehrori', 'Thetthari', 'Chusela', 'Sweet Lassi']::TEXT[], 'Dazzling mirror-work jackets (Kurta), colorful turbans decorated with peacock feathers, brass waist-bells, and knee-length dhotis.', 'Thunderous, fast-paced rhythm of Mandal drums, Sinh-Baja, and clattering wooden sticks (Lathis).', 'Peacock-feather crests (Mor Pankh), polished wooden lathis, mirror-work jackets, and Krishna imagery.', '1 Day', 'Hindu Lunisolar / Autumn', 'Kartik Shukla Paksha (approx 10-12 days after Diwali)', 'November', 'LUNISOLAR', 'Held during Kartik month following Diwali.', '2026-11-18', '2027-11-08', 'Raut Nacha Mahotsav Samiti & Bilaspur Municipal Corporation', ARRAY['Chhattisgarh']::TEXT[], ARRAY['Bilaspur']::TEXT[], ARRAY['Lal Bahadur Shastri Stadium Bilaspur']::TEXT[], 'Evening from 5 PM to 11 PM when competitive troupe performances take place', 1, 'Electrifying martial spectacle: thousands of warrior dancers swirling with peacock feathers, flashing mirrors, and clattering sticks in thunderous unison.', 'Bilaspur is a major railway headquarters on the Mumbai-Howrah mainline; 120 km from Raipur Airport.', 'Hotels and guest houses across Bilaspur city.', 'High crowd energy in the stadium; stay in designated spectator seating stands.', 'Applaud the witty poetic couplets (Dohas) recited by the lead dancers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bilaspur.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chhath-puja-bihar', 'Chhath Puja Patna & Gaya', ARRAY['Mahaparv Chhath', 'Dala Chhath']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vedic Solar Reverence & Pure Ecology)', 'The supreme cultural festival of Bihar observed with four days of rigorous fasting and divine offerings to the rising and setting Sun on holy Ganga ghats.', 'Ancient Vedic solar tradition mentioned in the Rigveda and Mahabharata, practiced by Karna (King of Anga) and Draupadi.', 'Celebrates the Sun God (Surya) and Chhathi Maiya (Usha/Pratyusha) as the cosmic source of life, health, and progeny.', 'To thank nature for sustaining life, pray for family well-being, and attain inner mental and physical purity.', 'The purest and most democratic mass festival in India, conducted without priests or caste distinctions.', 'Devotees (Vratis) fast without a single drop of water for 36 continuous hours while standing chest-deep in river waters.', ARRAY['Nahay Khay ritual bath and preparation of sacred bottle gourd and rice meal', 'Kharna fast broken with jaggery kheer after sunset', 'Standing chest-deep in water to offer Arghya to the setting and rising Sun']::TEXT[], 'Millions of families march barefoot to illuminated Ganga ghats carrying bamboo baskets laden with seasonal fruits, singing traditional folk songs.', ARRAY['Thekua (traditional ghee-fried whole wheat cookies with jaggery)', 'Kasar Ladoo', 'Fresh Sugarcane', 'Pomelo (Grapefruit)', 'Coconut']::TEXT[], 'Bright yellow, orange, and red cotton sarees with long vermilion lines extending from nose to hair parting; men wear yellow dhotis.', 'Soul-stirring, melancholic Chhath geet sung in chorus by women, made immortal by legendary singer Sharda Sinha.', 'Woven bamboo baskets (Daura and Soop), fresh sugarcane stalks, earthen lamps, and the golden sun rising over the Ganga.', '4 Days', 'Hindu Lunisolar', 'Kartik Shukla Chaturthi to Saptami (October - November)', 'October - November', 'LUNISOLAR', 'Commences 4 days after Diwali; main Arghya on Kartik Shukla Shashti.', '2026-11-15', '2027-11-05', 'Bihar State Tourism Development Corporation (BSTDC)', ARRAY['Bihar']::TEXT[], ARRAY['Patna', 'Gaya', 'Bhagalpur', 'Muzaffarpur']::TEXT[], ARRAY['Collectorate Ghat Patna', 'Digha Ghat', 'Ganga Riverfront Patna']::TEXT[], 'Sunset of Day 3 (Sandhya Arghya) and sunrise of Day 4 (Usha Arghya)', 2, 'Profound, tearful spiritual awe: millions standing in misty river waters illuminated by golden dawn light, offering glowing lamps to the rising sun.', 'Patna Airport; well connected by trains and state highways; ghats are pedestrian-only on Arghya days.', 'Hotels throughout Patna; book 2-3 months ahead as millions of diaspora Biharis return home.', 'Massive riverbank crowds; stay within protective safety nets along the ghat steps.', 'Maintain absolute ritual purity around the sacred Thekua prasad; accept prasad with both hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.bihar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sonepur-cattle-fair', 'Sonepur Cattle Fair', ARRAY['Harihar Kshetra Mela']::TEXT[], 'Fair & Mela', 'Hinduism & Ancient Animal Trade', 'The largest cattle and livestock fair in Asia, held on the sacred confluence of the Ganga and Gandak rivers where Lord Vishnu saved Gajendra the Elephant.', 'Ancient fair dating back to Emperor Chandragupta Maurya who bought war elephants and horses here; sacred site of the Gajendra Moksha legend from Bhagavata Purana.', 'Commemorates the rescue of the elephant king Gajendra by Lord Vishnu at the holy confluence of Gandak and Ganga.', 'To take the holy cleansing bath on Kartik Purnima and participate in ancient livestock trading.', 'Staged near the ancient Hariharnath Temple, a rare shrine where Lord Vishnu (Hari) and Lord Shiva (Har) are worshipped together in one lingam.', 'Sprawls over miles with thousands of horses, cattle, birds, and working animals, alongside circus shows and theatres.', ARRAY['Dawn holy dip at the confluence of Gandak and Ganga on Kartik Purnima', 'Puja at the historic Hariharnath Temple with holy river water', 'Trading and exhibition of Kathiawari horses, Murrah buffaloes, and agricultural breeds']::TEXT[], 'The dusty plains buzz with horse traders galloping their stallions, giant wooden Ferris wheels, and nightlong rural folk theatres.', ARRAY['Litti Chokha with Desi Ghee', 'Sonepur Malpua', 'Jalebi', 'Gaja sweet', 'Fried river fish']::TEXT[], 'Rural Bihari attire: white dhotis, colorful kurtas, gamchas, and traditional sarees.', 'Bhojpuri folk singing, Biraha ballads, Nautanki rural theatre, and energetic Dholak rhythms.', 'Historic Hariharnath temple spires, horses with decorated bridles, and the wide sandy river confluence.', '1 Month', 'Hindu Lunisolar', 'Begins on Kartik Purnima (November) and lasts for 30 days.', 'November - December', 'LUNISOLAR', 'Commences on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Saran District Administration & BSTDC', ARRAY['Bihar']::TEXT[], ARRAY['Sonepur', 'Hajipur', 'Patna']::TEXT[], ARRAY['Harihar Kshetra Fairgrounds Sonepur', 'Hariharnath Temple']::TEXT[], 'First week including Kartik Purnima dawn for peak animal trading and holy bath', 3, 'Unfiltered, thrilling glimpse of ancient rural India: galloping horses, bustling circus tents, holy riverbanks, and authentic rustic warmth.', '25 km north of Patna; connected by the JP Ganga Setu bridge; direct train to Sonepur Junction.', 'Swiss tent city set up by Bihar Tourism at Sonepur, or comfortable hotels in Patna city.', 'Dusty rural terrain; wear sturdy walking shoes and sunglasses; keep personal belongings secure.', 'Respect animal welfare regulations; commercial sale of elephants and wild animals is strictly banned under wildlife laws.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.bihar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pitrapaksha-mela-gaya', 'Pitrapaksha Mela Gaya', ARRAY['Gaya Pind Daan Mahasangam']::TEXT[], 'Spiritual & Temple', 'Hinduism (Ancestral Liberation & Vedic Rites)', 'The sacred international fortnight where millions of Hindus perform ancestral rites (Pind Daan) on the banks of holy river Falgu and at Vishnupad Temple.', 'Ancient pilgrimage documented in the Mahabharata and Vayu Purana, sanctified by Lord Rama performing Pind Daan for King Dasharatha.', 'Celebrates filial duty, gratitude, and the spiritual liberation of departed ancestors (Pitras).', 'To offer sesame, rice, and water balls (Pindas) to ancestors to ensure their peaceful ascension to higher spiritual realms.', 'Centered around the sacred 40-centimeter footprint of Lord Vishnu (Vishnupad) imprinted in solid basalt rock inside the 18th-century temple built by Ahilyabai Holkar.', 'Pind Daan is performed at 45 designated sacred altars (Veedis) including Falgu River, Akshayavat (immortal banyan tree), and Pretshila Hill.', ARRAY['Offering of barley, sesame, and rice Pindas guided by hereditary Gayawal Brahmins', 'Worship of the sacred rock-cut footprint of Lord Vishnu at Vishnupad Temple', 'Final ancestral prayer under the immortal Akshayavat banyan tree']::TEXT[], 'Pilgrims sit along the sandy banks of the dry Falgu River, offering water through kuśa grass fingers and praying with tearful devotion.', ARRAY['Tilkut (crispy sweet sesame seed wafer of Gaya)', 'Anarsa', 'Khaja', 'Sattvic vegetarian meals', 'Kheer']::TEXT[], 'White cotton dhotis and kurtas for men; simple cotton sarees for women performing ancestral rites.', 'Continuous chanting of Vedic mantras, Sanskrit Pitra Suktas, and solemn temple bells.', 'Sacred footprint of Lord Vishnu (Vishnupad), Akshayavat banyan tree, and rice-sesame Pinda balls.', '16 Days', 'Hindu Lunisolar', 'Bhadrapada Purnima to Sarva Pitru Amavasya (September - October)', 'September - October', 'LUNISOLAR', 'Observed throughout the waning fortnight of Ashwin (Pitrapaksha).', '2026-09-25', '2027-09-15', 'Gaya District Administration & Gayawal Panda Sabha', ARRAY['Bihar']::TEXT[], ARRAY['Gaya', 'Bodh Gaya']::TEXT[], ARRAY['Vishnupad Temple Complex', 'Falgu River Ghats', 'Akshayavat']::TEXT[], 'Morning hours between 6 AM and 12 PM for ancestral Pind Daan rituals', 2, 'Deeply emotional, solemn pilgrimage of filial gratitude connecting living generations with ancestors in an ancient holy sanctuary.', 'Gaya Airport; well connected by trains on the Grand Chord line; 100 km south of Patna.', 'Pilgrim dharamshalas in Gaya or modern hotels in nearby Bodh Gaya (12 km away).', 'Crowded narrow lanes around Vishnupad Temple; engage certified priests with fixed rate cards issued by administration.', 'Maintain solemnity during ancestral rituals; dress conservatively in white cotton clothing.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://gaya.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rajgir-mahotsav', 'Rajgir Mahotsav', ARRAY['Ancient Magadha Cultural Festival']::TEXT[], 'Art & Cultural Festival', 'Ancient Indian History & Multireligious Heritage', 'A grand cultural festival celebrated in the ancient capital of the Magadha Empire, surrounded by seven holy hills, hot springs, and historic ruins.', 'Initiated in 1986 by the Department of Tourism, Bihar, in the historic valley where Buddha preached and Lord Mahavira attained liberation.', 'Celebrates the glorious heritage of the Magadha Empire (Bimbisara, Ajatashatru) and the peaceful synthesis of Hinduism, Buddhism, and Jainism.', 'To promote cultural tourism to Rajgir''s Vulture Peak (Gridhrakuta), Nalanda ruins, and natural sulphur hot springs (Brahmakund).', 'Staged on the open-air cultural grounds near the historic Venuvana bamboo grove.', 'Features classical music and dance, traditional Tongaride competitions, and martial wrestling (Dangal).', ARRAY['Nightly classical dance and music concerts by national award-winning artists', 'Traditional wrestling (Dangal) competitions at the ancient arena of Jarasandha', 'Heritage walks exploring Gridhrakuta Peak and the newly built Rajgir Glass Bridge']::TEXT[], 'Visitors take the aerial ropeway to the white Shanti Stupa, bathe in healing hot springs, and attend evening classical concerts.', ARRAY['Khaja (layered crispy pastry of Silao - GI Tagged)', 'Litti Chokha', 'Peda', 'Sattu Sharbat', 'Jalebi']::TEXT[], 'Smart casuals, comfortable walking boots, ethnic handloom kurtas, and cotton sarees.', 'Classical Kathak, Odissi, and Bharatanatyam, alongside Chhattisgarhi and Bihari folk music and Sufi Qawwalis.', 'Vishwa Shanti Stupa dome, ancient cyclopean stone walls of Rajgir, and aerial ropeway chairs.', '3 Days', 'Gregorian / Autumn-Winter', 'Held in November / December annually.', 'November - December', 'ORGANIZER_ANNOUNCED', 'Announced annually by Bihar Tourism.', '2026-11-27', '2027-11-26', 'Bihar State Tourism Development Corporation (BSTDC)', ARRAY['Bihar']::TEXT[], ARRAY['Rajgir', 'Nalanda']::TEXT[], ARRAY['Rajgir International Convention Centre Grounds', 'Venuvana']::TEXT[], 'Morning visit to Gridhrakuta Peak and evening classical concerts', 2, 'Mesmerizing encounter with the roots of Indian philosophy and imperial history, surrounded by emerald hills and sacred hot springs.', '100 km southeast of Patna; accessible by train to Rajgir station or 2-hour taxi drive.', 'Hotels, heritage resorts, and Buddhist monasteries in Rajgir.', 'Undulating hill trails; wear comfortable walking shoes; carry light woolens for winter evenings.', 'Buy authentic GI-tagged Silao Khaja from historic sweetshops near the main market.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.bihar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-buddha-jayanti-bodh-gaya', 'Buddha Jayanti Bodh Gaya', ARRAY['Vesak Bodh Gaya']::TEXT[], 'Spiritual & Temple', 'Buddhism (Global Enlightenment Celebration)', 'The supreme global Buddhist celebration at the exact site where Gautama Buddha attained supreme enlightenment under the sacred Bodhi Tree.', 'Commemorates the birth, enlightenment (Nirvana), and passing (Parinirvana) of Gautama Buddha at the UNESCO World Heritage Mahabodhi Temple.', 'Celebrates the dawn of Buddhist wisdom, compassion, non-violence, and universal peace.', 'To sit in silent meditation beneath the sacred Bodhi Tree where the Buddha conquered delusion in 528 BCE.', 'The holiest shrine in the Buddhist world, drawing thousands of monks, lamas, and devotees from over 40 nations.', 'Features a grand morning peace procession carrying the sacred scriptures and statues through the streets of Bodh Gaya.', ARRAY['Grand morning Dhamma peace procession from 80-foot Buddha statue to Mahabodhi Temple', 'Chanting of the Sutras beneath the holy Bodhi Tree and Vajrasana (Diamond Throne)', 'Lighting of tens of thousands of butter lamps around the 50-meter ancient stone temple spire']::TEXT[], 'Monks in saffron, maroon, and white robes sit in meditation around the stone stupa, while the evening air glows with thousands of butter lamps.', ARRAY['Sattvic vegetarian feast meals', 'Tibetan Momos', 'Kheer (commemorating Sujata''s milk-rice offering to the Buddha)', 'Fresh fruits']::TEXT[], 'Monastic robes of Theravada, Mahayana, and Vajrayana lineages; pilgrims wear pure white cotton clothing.', 'Deep, resonant chanting of the Pali canon, Tibetan monastic horns, and meditative temple gongs.', '50-meter pyramid spire of Mahabodhi Temple, sacred Bodhi Tree (Ficus religiosa), and golden Vajrasana stone.', '1 Day', 'Buddhist Lunisolar', 'Vaisakha Purnima (full moon night of Vaisakha month in May)', 'May', 'LUNISOLAR', 'Celebrated on Vaisakha Purnima.', '2026-05-31', '2027-05-20', 'Bodhgaya Temple Management Committee (BTMC)', ARRAY['Bihar']::TEXT[], ARRAY['Bodh Gaya', 'Gaya']::TEXT[], ARRAY['Mahabodhi Temple Complex', 'Sacred Bodhi Tree']::TEXT[], 'Dawn procession at 6:30 AM and illuminated evening butter lamp meditation under the Bodhi Tree', 2, 'Transcendent, life-changing spiritual peace: sitting in meditative silence under the sacred tree where human consciousness attained enlightenment.', '12 km from Gaya International Airport and railway station; auto-rickshaws and cabs widely available.', 'Monastery guesthouses representing Japan, Thailand, Sri Lanka, and Bhutan, alongside luxury hotels in Bodh Gaya.', 'Strict security screening at Mahabodhi Temple: mobile phones, cameras, and bags are prohibited inside the inner sanctum.', 'Maintain deep meditative silence around the Bodhi Tree; remove shoes before entering the temple terrace.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bodhgayatemple.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mithila-vivah-panchami', 'Mithila Vivah Panchami Janakpur & Madhubani', ARRAY['Sita Ram Vivah Utsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Mithila Cultural Heritage)', 'The joyous divine wedding anniversary celebration of Lord Rama and Goddess Sita celebrated across the historic Mithila region with Maithili songs and Madhubani art.', 'Celebrates the ancient wedding of Prince Rama of Ayodhya with Princess Sita of Mithila at King Janaka''s palace, as described in the Ramayana.', 'Celebrates the sacred marital bond, filial duty, and the cultural pride of the ancient kingdom of Mithila.', 'To honor Goddess Sita (Janaki) as the beloved daughter of Mithila and celebrate divine marriage rites.', 'Features the arrival of a ceremonial wedding procession (Barat) of sadhus and devotees traveling from Ayodhya to Janakpur.', 'Every household is decorated with intricate GI-tagged Madhubani paintings depicting the wedding scenes.', ARRAY['Ceremonial welcome of the marriage procession (Barat) with traditional Maithili songs', 'Performance of Vedic wedding rituals (Kanyadaan and Sindoor Daan) for the divine idols', 'Singing of witty, teasing Maithili wedding ballads (Samdaun and Gali) by women']::TEXT[], 'Temples and homes resound with laughter as women sing playful songs teasing the groom''s party, followed by grand community feasts.', ARRAY['Mithila Thali: Dal Puri, Kheer, Chana Daal', 'Makhana Kheer (fox nut pudding - GI Tagged)', 'Parwal Mithai', 'Tilkor Pakora']::TEXT[], 'Traditional Maithili attire: Dhoti-Kurta with Paag (traditional red headdress) for men; fine Madhubani-painted sarees for women.', 'Melodious Maithili folk wedding songs, traditional Dholak, harmonium, and classical Maithili Vidyapati geet.', 'Intricate Madhubani Kohbar art paintings, fresh lotus flowers, sacred wedding mandap, and Mithila Paag.', '5 Days', 'Hindu Lunisolar', 'Margashirsha Shukla Panchami (November - December)', 'November - December', 'LUNISOLAR', 'Celebrated on Margashirsha Shukla Panchami.', '2026-12-14', '2027-12-03', 'Janaki Mandir Trust & Mithila Cultural Society', ARRAY['Bihar']::TEXT[], ARRAY['Madhubani', 'Sitamarhi', 'Darbhanga', 'Janakpur']::TEXT[], ARRAY['Janaki Mandir', 'Punaura Dham Sitamarhi', 'Madhubani town']::TEXT[], 'Day of Vivah Panchami for the grand wedding rituals and traditional Maithili feasts', 2, 'Delightful, warm cultural immersion in Mithila''s ancient artistic elegance, witty wedding humor, and profound love for daughter Sita.', 'Well connected by road and rail via Darbhanga Airport (65 km from Madhubani) and Sitamarhi.', 'Hotels in Madhubani, Darbhanga, or cross-border heritage stays in Janakpur.', 'Gentle, family-centered celebration; respect temple sanctum rules during wedding rituals.', 'Buy authentic GI-tagged Madhubani paintings directly from master women artists in Jitwarpur and Ranti villages.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://madhubani.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sama-chakeva-mithila', 'Sama Chakeva Mithila', ARRAY['Mithila Clay Bird Festival']::TEXT[], 'Tribal & Folk Traditions', 'Folk Legends & Sibling Bond', 'A charming eight-day festival where women and young girls sculpt clay figures of birds, singing traditional folk songs under moonlit village skies to celebrate sibling love.', 'Ancient folk festival described in the Skanda Purana, centered around the legend of Sama (daughter of Lord Krishna) and her brother Samba who redeemed her.', 'Celebrates the pure, unconditional bond of love and protection between brothers and sisters.', 'To pray for the health, prosperity, and longevity of brothers through traditional clay bird rituals.', 'A cherished cultural tradition unique to the Mithila region of Bihar and southern Nepal, entirely led by women and girls.', 'Concluding on Kartik Purnima, the clay bird figures are ritually broken and immersed in ponds while brothers burn a mock effigy of the slanderer Chugla.', ARRAY['Crafting and painting clay figures of birds (Sama, Chakeva) and human characters (Chugla, Satbhaiya)', 'Singing traditional folk songs in village courtyards every night under the autumn moon', 'Brothers ritually breaking clay figures and burning the mustache of the evil slanderer Chugla on Kartik Purnima']::TEXT[], 'Groups of women sit in village circles under the starry sky, holding wicker baskets containing painted clay birds and singing melodious folk songs.', ARRAY['Makhana Kheer', 'Puri', 'Jaggery sweets', 'Chuda Dahi (beaten rice with fresh curd and jaggery)']::TEXT[], 'Traditional Maithili cotton sarees, colorful dupattas, and simple festive ethnic wear.', 'Pure vocal chorus singing of traditional Sama-Chakeva folk ballads without instruments, clapping in rhythm.', 'Painted clay birds (Sama and Chakeva), wicker baskets (Daura), and autumn full moon.', '8 Days', 'Hindu Lunisolar', 'Kartik Shukla Saptami to Kartik Purnima (November)', 'November', 'LUNISOLAR', 'Begins on the day following Chhath and concludes on Kartik Purnima.', '2026-11-17', '2027-11-07', 'Mithila Sanskritik Parishad & Local Panchayats', ARRAY['Bihar']::TEXT[], ARRAY['Darbhanga', 'Madhubani', 'Samastipur', 'Sitamarhi']::TEXT[], ARRAY['Village courtyards across Mithila']::TEXT[], 'Kartik Purnima evening when the concluding immersion and fire rituals take place', 1, 'Touching, authentic folk intimacy: listening to sweet women''s choruses echoing across moonlit village courtyards in the peaceful countryside.', 'Easily experienced in any village across the Mithila plains; accessible from Darbhanga.', 'Hotels in Darbhanga and Madhubani.', 'Gentle village celebration; visitors are welcomed warmly by village households.', 'Do not interrupt the singing circles; observe the ancient clay crafting tradition respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://darbhanga.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bihula-bishahari-bhagalpur', 'Bihula-Bishahari Bhagalpur', ARRAY['Manjusha Art & Snake Goddess Festival']::TEXT[], 'Tribal & Folk Traditions', 'Anga Regional Folklore & Snake Reverence', 'The ancient folk festival of the Anga region celebrating the chaste heroine Bihula and snake goddess Bishahari, famous for the unique GI-tagged Manjusha art.', 'Centuries-old folk tradition commemorating the epic legend of Bihula, who sailed down the river on a raft with her husband''s corpse to challenge the snake goddess Mansa and restore him to life.', 'Celebrates conjugal devotion, feminine courage, and protection from snakebites during the monsoon.', 'To worship Goddess Bishahari (Mansa Devi) and pray for the safety of families and agricultural fertility.', 'The foundational inspiration for ''Manjusha Art'' (Angika folk painting), characterized by bold line drawings in three primary colors (pink, green, yellow).', 'Features the crafting of ''Manjushas''—temple-shaped box structures made of bamboo, jute, and paper, painted with epic scenes from Bihula''s saga.', ARRAY['Crafting of vibrant temple-shaped painted boxes (Manjushas) by traditional artisans', 'Nightlong singing of the epic ballad of Bihula-Bishahari by traditional folk singers', 'Grand immersion procession of painted Manjushas into the river on the final day']::TEXT[], 'Devotees throng the Bishahari temples in Bhagalpur, offering milk and flowers, admiring intricate Manjusha scrolls, and listening to thrilling ballads.', ARRAY['Katarni Chuda (GI-tagged aromatic beaten rice of Bhagalpur) with curd and jaggery', 'Litti Chokha', 'Peda', 'Samosa']::TEXT[], 'Traditional handloom Bhagalpuri Tussar silk sarees and kurtas, decorated with Manjusha borders.', 'Soulful Angika folk singing accompanied by Dholak, cymbals, and traditional flute.', 'Temple-shaped painted Manjusha boxes, snake motifs, three-color borders (snakes, waves, and trees), and Tussar silk.', '2 Days', 'Hindu Lunisolar / Monsoon', 'Held on the last day of Shravana and first day of Bhadrapada (August)', 'August', 'LUNISOLAR', 'Celebrated on Shravana Amavasya / Bhadrapada Sankranti.', '2026-08-17', '2027-08-17', 'Anga Sanskritik Parishad & Bhagalpur District Administration', ARRAY['Bihar']::TEXT[], ARRAY['Bhagalpur', 'Champanagar', 'Banka']::TEXT[], ARRAY['Mata Bishahari Temple Champanagar', 'Bhagalpur town']::TEXT[], 'Day of the grand Manjusha procession and temple worship in Champanagar', 1, 'Fascinating immersion into ancient Angika folklore, bold graphic folk art, and the heroic mythological courage of women in eastern India.', 'Bhagalpur Junction is a major railway station; 220 km east of Patna; accessible by express trains.', 'Hotels throughout Bhagalpur city.', 'Monsoon season; carry umbrellas and rain protection.', 'Buy authentic GI-tagged Manjusha paintings and Bhagalpuri Tussar silk directly from certified artisan cooperatives.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bhagalpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shravani-mela-sultanganj', 'Shravani Mela Sultanganj to Deoghar', ARRAY['Sultanganj Kanwar Yatra']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism & Ganga Pilgrimage)', 'The extraordinary month-long pilgrimage where millions of saffron-clad Kanwariyas fetch holy water from the north-flowing Ganga at Sultanganj and walk 105 km to Baba Baidyanath.', 'Ancient pilgrimage documented in the Shiva Purana, sanctified by the unique geographic phenomenon of the Ganga flowing northwards (Uttaravahini) at Sultanganj.', 'Celebrates the surrender of devotees to Lord Shiva during the auspicious monsoon month of Shravana.', 'To collect holy Uttaravahini Ganga water and carry it barefoot over 105 kilometers to offer to the Baidyanath Jyotirlinga.', 'One of the longest unbroken walking pilgrimages in the world, bringing together over five million pilgrims in a single month.', 'Sustains an egalitarian brotherhood: every pilgrim is addressed solely as ''Bol Bam'' or ''Bhole Baba'', transcending all caste, wealth, and age barriers.', ARRAY['Collecting sacred north-flowing Ganga water at the rocky promontory of Ajgaibinath Temple in Sultanganj', 'Balancing the decorated bamboo Kanwar on shoulders without ever placing it on the ground', 'Walking 105 kilometers barefoot along the dedicated red-carpet sand track through hills and forests']::TEXT[], 'The 105 km rural highway turns into a continuous river of saffron-clad pilgrims chanting ''Bol Bam, Bol Bam, Har Har Bam Bam'' day and night.', ARRAY['Sattvic roadside Langar meals: Dal-Roti, Khichdi, and sweet tea', 'Peda', 'Fresh seasonal fruits']::TEXT[], 'Vibrant saffron shorts, t-shirts, and headbands with Shiva trishul symbols.', 'Resounding, continuous chanting of ''Bol Bam'', folk dholak beats, and devotional Bhojpuri and Maithili Kanwar bhajans.', 'Decorated bamboo Kanwar pole with brass bells and water vessels, Ajgaibinath rock temple, and saffron sea of pilgrims.', '1 Month', 'Hindu Lunisolar / Monsoon', 'Throughout the holy month of Shravana (July - August)', 'July - August', 'LUNISOLAR', 'Observed throughout the Hindu month of Shravana.', '2026-07-29', '2027-07-18', 'Bhagalpur & Banka District Administrations & BSTDC', ARRAY['Bihar', 'Jharkhand']::TEXT[], ARRAY['Sultanganj', 'Banka', 'Deoghar']::TEXT[], ARRAY['Ajgaibinath Temple Sultanganj', '105 km Kanwar Route']::TEXT[], 'Mondays of Shravan month when pilgrim departures from Sultanganj reach peak intensity', 3, 'Awe-inspiring display of relentless physical stamina, unshakeable faith, boundless community volunteerism, and the radiant energy of Lord Shiva.', 'Sultanganj is 25 km west of Bhagalpur; connected by train and highway.', 'Hundreds of free pilgrim shelter camps (Dharamshalas) along the 105 km route; hotels in Bhagalpur and Deoghar.', 'Extremely heavy walking crowds; walking track is covered with fine river sand to ease barefoot travel.', 'Show supreme patience and courtesy to walking Kanwariyas; never step over or touch a resting Kanwar pole.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tourism.bihar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mandar-mahotsav-banka', 'Mandar Mahotsav Banka', ARRAY['Mandar Hill Mela', 'Bausi Mela']::TEXT[], 'Fair & Mela', 'Hinduism & Jainism (Mythological Confluence)', 'The historic Makar Sankranti fair held at the foot of sacred Mandar Hill, the mythical churning rod (churning rod) used by gods and demons during Samudra Manthan.', 'Ancient sacred site described in the Puranas and Mahabharata as Mount Mandara, used to churn the cosmic ocean to produce the nectar of immortality (Amrit).', 'Celebrates the cosmic victory of divine wisdom and honors Lord Vishnu (Madhusudana) and Jain Tirthankara Vasupujya.', 'To take holy cleansing dips in the sacred Papaharini tank at the base of the hill and climb to the rock temples.', 'Unique multireligious pilgrimage site revered by Hindus, Jains (12th Tirthankara attained Nirvana here), and indigenous Santhal tribal communities.', 'Features the ancient rock-cut sculpture of Lord Vishnu slaying the demon Madhu, carved into the granite face of the 700-foot monolith.', ARRAY['Dawn holy dip in the sacred Papaharini tank on Makar Sankranti', 'Circumambulation (Parikrama) and climb up the granite monolithic Mandar Hill', 'Worship at the historic Madhusudana Temple and the Jain temple on the summit']::TEXT[], 'Lakhs of pilgrims and tribal families gather in the vast fairgrounds, offering Tilkut, shopping at rural craft bazaars, and climbing the monolithic rock.', ARRAY['Tilkut (sweet sesame candy)', 'Chuda Dahi with Jaggery', 'Litti Chokha', 'Peda', 'Jalebi']::TEXT[], 'Traditional rural dhotis, kurtas, colorful sarees, and Santhal tribal handloom lungis.', 'Santhal tribal folk drumming with Tamak and Tumdak, accompanied by devotional Vishnu bhajans.', '700-foot monolithic granite hill, sacred Papaharini tank reflections, and carved serpent rope markings on rock.', '3 Days', 'Solar / Makar Sankranti', 'January 14 to 16 annually (Makar Sankranti).', 'January', 'FIXED', 'Commences on Makar Sankranti (January 14).', '2026-01-14', '2027-01-14', 'Banka District Administration & BSTDC', ARRAY['Bihar']::TEXT[], ARRAY['Bausi', 'Banka', 'Bhagalpur']::TEXT[], ARRAY['Mandar Hill Complex', 'Papaharini Tank Bausi']::TEXT[], 'Dawn on Makar Sankranti for the holy dip and morning climb up Mandar Hill', 2, 'Mythological wonder: climbing the ancient monolithic mountain that churned the cosmic ocean, surrounded by sacred tanks and vibrant rural fairs.', '45 km south of Bhagalpur on the Deoghar highway; accessible by passenger train to Mandar Hill station.', 'Simple guesthouses in Bausi; comfortable hotels in Bhagalpur city.', 'Climbing Mandar Hill involves climbing hundreds of rock-cut stone steps; wear sturdy walking shoes.', 'Respect the sacred sanctity of the Papaharini tank; bathe strictly in designated safe areas.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://banka.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sarhul-festival-ranchi', 'Sarhul Festival Ranchi', ARRAY['Tribal Spring Festival of Jharkhand']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Sarna Animism / Nature Worship', 'The supreme cultural festival of the indigenous tribes of Jharkhand, celebrating the blooming of the sacred Sal tree and the divine marriage of Earth and Sun.', 'Ancient indigenous festival celebrated by the Oraon, Munda, Ho, and Santhal tribes, rooted in prehistoric nature worship and the Sarna faith.', 'Celebrates the arrival of spring, rejuvenation of Mother Earth, and blooming of fragrant white Sal blossoms (Sarai phul).', 'To pray for rain, bumper agricultural harvest, and village protection through rituals performed at the sacred village grove (Sarna Sthal).', 'The village priest (Pahan) conducts water divination: storing water in earthen pots overnight to forecast the monsoon rains for the coming year.', 'Concludes with a massive, vibrant street procession of hundreds of thousands of tribal people in matching handloom attire parading through Ranchi.', ARRAY['Water divination ceremony by the village Pahan at the sacred Sarna grove', 'Distribution of blessed white Sal blossoms (Sarai) to be tucked into hair and house roofs', 'Grand cultural procession through Ranchi streets with thousands dancing to traditional Mandar drums']::TEXT[], 'Streets of Ranchi overflow with music, laughter, and dancing as men and women in traditional red-and-white handloom dresses celebrate their deep bond with nature.', ARRAY['Hadiya (traditional fermented rice beverage)', 'Dhuska with Ghugni (fried rice-lentil cakes with spicy chickpea curry)', 'Chilka Roti', 'Fried Sal seeds', 'Mahuwa sweets']::TEXT[], 'Traditional tribal handlooms: pristine white sarees with broad red borders (Lal Paar) for women; white dhotis with red borders and turbans for men.', 'Hypnotic, thundering beats of traditional Mandar and Nagara drums, accompanied by joyful group dancing in concentric locking-arm lines.', 'Fragrant white Sal tree blossoms (Sarai), red-and-white Sarna flags, and wooden Mandar drums.', '1 Day', 'Hindu-Tribal Lunisolar / Spring', 'Chaitra Shukla Tritiya (March - April)', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Shukla Tritiya.', '2026-03-22', '2027-04-10', 'Central Sarna Samiti & Jharkhand Tourism', ARRAY['Jharkhand']::TEXT[], ARRAY['Ranchi', 'Khunti', 'Gumla', 'Jamshedpur']::TEXT[], ARRAY['Sarna Sthal Hatma Ranchi', 'Main Road Ranchi']::TEXT[], 'Morning Sarna worship at Hatma and afternoon grand street procession down Main Road', 1, 'Awe-inspiring display of indigenous pride, pristine eco-spirituality, rhythmic ground-shaking drum beats, and boundless warmth.', 'Birsa Munda Airport Ranchi; easily reached by auto-rickshaws, cabs, and state buses; central roads are pedestrianized during procession.', 'Hotels and boutique guest houses throughout Ranchi city.', 'Vast, peaceful crowds; wear comfortable walking shoes and carry sun protection for the street parade.', 'Accept the blessed Sal flower with reverence; treat the sacred Sarna grove with quiet respect.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ranchi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-karma-festival-jharkhand', 'Karma Festival Jharkhand', ARRAY['Karam Puja']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Nature Worship & Sibling Devotion', 'The sacred post-monsoon festival celebrating the worship of the sacred Karma tree branch, symbolizing youth vigor, agricultural prosperity, and brotherly protection.', 'Ancient tribal festival celebrated across Jharkhand, Odisha, and Bengal by Munda, Oraon, Ho, and Santhal communities.', 'Celebrates the blessing of green paddy crops, youthful strength (Karma), and thanksgiving to nature.', 'To pray for the protection of standing crops, fertility of the soil, and the long life of brothers.', 'Centred around the planting of three freshly cut branches of the sacred Karma tree (Nauclea parvifolia) in the center of the village dancing ground (Akhra).', 'Young unmarried maidens fast throughout the day, germinating grains (Jawa) in small bamboo baskets to offer to the sacred tree.', ARRAY['Cutting and ceremonial carrying of three sacred Karma branches from the forest to the village Akhra', 'Nightlong dancing and singing around the planted Karma branches', 'Recitation of the moral folk legend of Karma and Dharma by village elders']::TEXT[], 'The village Akhra reverberates all night with drum beats as youth in festive finery dance in locked-arm arcs, waving sprout baskets (Jawa).', ARRAY['Dhuska with Chana Dal curry', 'Arsa Roti (sweet fried rice cakes)', 'Chilka Roti', 'Pitha', 'Handia']::TEXT[], 'Tribal cotton handloom dresses: white with colorful red or yellow borders, hair decorated with wild wildflowers and feathers.', 'Soulful Karam folk songs accompanied by the resonant, earthy beats of the Mandar, Nagara, and bamboo flute.', 'Three leafy branches of the sacred Karma tree, germinated green Jawa sprouts in wicker baskets, and earthen lamps.', '1 Day', 'Hindu-Tribal Lunisolar', 'Bhadrapada Shukla Ekadashi (August - September)', 'August - September', 'LUNISOLAR', 'Celebrated on Bhadrapada Shukla Ekadashi.', '2026-09-22', '2027-09-11', 'Jharkhand Tribal Welfare Department & Cultural Board', ARRAY['Jharkhand']::TEXT[], ARRAY['Ranchi', 'Dumka', 'Hazaribagh', 'Bokaro', 'Chaibasa']::TEXT[], ARRAY['Village Akhras across Jharkhand']::TEXT[], 'Nightlong dancing and storytelling around the sacred Karma tree at the village Akhra', 1, 'Authentic tribal forest village life: dancing beneath moonlit skies in locked-arm harmony to the heartbeat of ancient clay drums.', 'Easily experienced in any tribal village outside Ranchi, Khunti, or Hazaribagh.', 'Hotels in Ranchi or district headquarters.', 'Village night ceremonies; dress comfortably and carry a light jacket for late-night outdoor sitting.', 'Respect the sanctity of the planted Karma branches; do not step into the central ritual circle.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jharkhandtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tusu-parab-jharkhand', 'Tusu Parab Chotanagpur', ARRAY['Tusu Mela Jharkhand']::TEXT[], 'Harvest & Agriculture', 'Folk Harvest & Feminine Devotion', 'The vibrant winter harvest festival celebrated by rural folk and tribal communities, featuring colorful temple-shaped paper towers (Chaudal) immersed in rivers on Makar Sankranti.', 'Ancient agrarian festival celebrated across the Chotanagpur plateau, centered around the beloved folk deity Tusu, imagined as a young rural maiden.', 'Celebrates the completion of the winter paddy harvest and the solar transition of Makar Sankranti.', 'To celebrate feminine beauty, sisterhood, and thank nature for abundant golden grain yields.', 'Famous for the creation of ''Chaudal''—towering, multi-tiered temple structures crafted of bamboo, colored paper, and tinsel, carried by young women.', 'Culminates in massive rural riverbank fairs where thousands of singing women gently immerse their decorated Chaudals into the river at sunrise.', ARRAY['Crafting of multi-tiered colorful paper and bamboo Chaudal towers', 'Singing of traditional poetic Tusu folk ballads addressing joys and sorrows of rural women', 'Immersion of Chaudal towers in sacred rivers (Subarnarekha, Damodar) at dawn on Makar Sankranti']::TEXT[], 'Riverbanks turn into a dazzling sea of towering colorful paper temples, with singing women marching in groups and celebrating at rural melas.', ARRAY['Pitha (rice dumplings filled with jaggery and coconut)', 'Chuda Dahi with Jaggery', 'Til Ladoo', 'Dhuska', 'Khaja']::TEXT[], 'Brightly colored handloom cotton sarees, warm woolen shawls, and glass bangles.', 'Melodious Tusu folk songs sung in chorus by young women, accompanied by Dholak and flute.', 'Multi-tiered colorful paper Chaudal towers, bamboo frames, ears of golden paddy, and river currents.', '1 Month (Culminates on Makar Sankranti)', 'Solar / Winter Harvest', 'Last day of Paush month (Makar Sankranti on January 14).', 'January', 'FIXED', 'Culminates on Makar Sankranti (January 14).', '2026-01-14', '2027-01-14', 'Chotanagpur Cultural Council & Jharkhand Tourism', ARRAY['Jharkhand']::TEXT[], ARRAY['Ranchi', 'Jamshedpur', 'Purulia', 'Dhanbad']::TEXT[], ARRAY['Subarnarekha Riverbanks', 'Dimna Lake', 'Ranchi Lake']::TEXT[], 'Dawn of Makar Sankranti (January 14) for the colorful river immersion procession and daytime fair', 2, 'Delightful folk creativity, soaring colorful paper towers, melodic women''s choruses, and rustic rural carnival cheer.', 'Easily accessible across Ranchi and Jamshedpur via local buses, auto-rickshaws, and cabs.', 'Hotels throughout Ranchi and Jamshedpur.', 'Crisp January morning weather; wear warm layers for early dawn riverbank visits.', 'Treat the singing women and their delicate paper Chaudal towers with courtesy; do not crush the structures.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jharkhandtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sohrai-khovar-art-festival', 'Sohrai and Khovar Art Festival Hazaribagh', ARRAY['Hazaribagh Tribal Wall Art Festival']::TEXT[], 'Art & Cultural Festival', 'Indigenous Mural Art & Cattle Thanksgiving', 'The glorious celebration of the GI-tagged Sohrai and Khovar indigenous mural art, where tribal women paint ancient wildlife and geometric frescoes on mud walls.', 'Ancient indigenous traditions practiced by Santhal, Munda, Oraon, and Prajapati women in Hazaribagh, continuous with 10,000-year-old rock art found in local caves (Isko).', 'Celebrates the harvest, Thanksgiving to working cattle (Sohrai), and sacred marriage blessings (Khovar).', 'To honor ancestral wildlife (tigers, elephants, peacocks, horned deer) and bless domestic dwellings with sacred fertility symbols.', 'Recognized globally with a Geographical Indication (GI) tag, celebrated for using pure natural earth pigments (red oxide, kaolin white, black manganese).', 'In Sohrai, bold colorful murals are painted using chewed twigs; in Khovar (comb-cut art), white clay is coated over black earth and scraped away with broken comb teeth.', ARRAY['Cleaning and mud-plastering of rural mud homes before Diwali', 'Painting monumental murals of wild animals and fertility vines using natural earth clays', 'Ritual worship and decoration of cattle with oil, vermilion, and paddy garlands']::TEXT[], 'Entire mud villages transform into living open-air art galleries, with every house facade painted in breathtaking ancient monochrome and polychrome designs.', ARRAY['Arsa Roti', 'Dhuska with Aloo Chana', 'Pitha', 'Kheer with wild honey', 'Rice beer (Handia)']::TEXT[], 'Simple cotton sarees, silver tribal jewelry, and flowers tucked into hair.', 'Rhythmic folk singing celebrating cows and the forest, accompanied by small Dholak drums and clappers.', 'Giant stylized paintings of horned bulls, elephants with calves, lotuses, peacocks, and mud walls.', '4 Days', 'Hindu-Tribal Lunisolar', 'Celebrated during the days immediately following Diwali (Kartik Amavasya).', 'November', 'LUNISOLAR', 'Held in Kartik month following Diwali.', '2026-11-09', '2027-10-30', 'Virasat Trust & Hazaribagh Tribal Art Development Society', ARRAY['Jharkhand']::TEXT[], ARRAY['Hazaribagh', 'Bada', 'Oriya', 'Isko']::TEXT[], ARRAY['Village homes across Hazaribagh district']::TEXT[], 'Daytime from 9 AM to 4 PM for guided walking tours through painted art villages', 2, 'Astonishing, deeply humbling aesthetic encounter: walking through clean mud village lanes that look like prehistoric art galleries painted by master women artists.', '90 km north of Ranchi; accessible by highway taxi via NH-33 (2 hours).', 'Hotels in Hazaribagh town, or eco-homestays in tribal art villages.', 'Rural walking trails; wear comfortable flat footwear and carry water.', 'Respect the privacy of village homes: ask permission before entering courtyards; buy original canvas paintings from artist collectives.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hazaribag.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-baidyanath-shravani-mela', 'Baidyanath Shravani Mela Deoghar', ARRAY['Baba Dham Shravani Mahotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Jyotirlinga & Tantric Shakti Peeth)', 'The sacred monsoon pilgrimage where millions of barefoot Kanwariyas offer holy Ganga water to the ancient Baidyanath Jyotirlinga at Deoghar.', 'Ancient pilgrimage documented in the Shiva Purana and Padma Purana, sanctified as both one of the 12 sacred Jyotirlingas and one of the 51 Shakti Peethas (Hriday Peeth).', 'Commemorates the devotion of demon king Ravana who carried the Shiva Lingam towards Lanka until tricked by Lord Varuna and Lord Vishnu.', 'To offer holy Ganga water carried barefoot from Sultanganj onto the sacred stone lingam to heal all physical and spiritual afflictions.', 'The supreme pilgrimage center of eastern India, drawing over five million pilgrims during the holy month of Shravana.', 'Famous for the traditional red and yellow silk ribbons connecting the golden trident of the Shiva temple with the adjacent Parvati temple.', ARRAY['Offering the sacred holy water of the north-flowing Ganga onto the Baidyanath Jyotirlinga', 'Circumambulation of the 22 ancient stone temples inside the sacred courtyard', 'Touching the sacred wish-fulfilling stone lingam amidst the resounding roar of ''Har Har Mahadev''']::TEXT[], 'Deoghar streets resound with endless chants of ''Bol Bam'' as millions of saffron-clad pilgrims with blistered feet wait patiently for darshan.', ARRAY['Deoghar Peda (world-famous slow-cooked caramelized milk fudge - GI Application)', 'Puri Sabzi', 'Langar Khichdi', 'Rabri', 'Kachori']::TEXT[], 'Bright saffron clothes (t-shirts and shorts) worn by walking Kanwariyas; pilgrims wear traditional dhotis and sarees.', 'Continuous thunderous chanting of ''Bol Bam, Bol Bam'', temple conch shells, and spiritual devotional bhajans.', 'Ancient stone shikhara of Baba Baidyanath temple, golden trident (Trishul), red silk marriage threads, and holy water vessels.', '1 Month', 'Hindu Lunisolar / Monsoon', 'Throughout the holy month of Shravana (July - August)', 'July - August', 'LUNISOLAR', 'Observed throughout the Hindu month of Shravana.', '2026-07-29', '2027-07-18', 'Baba Baidyanath Temple Management Board & Deoghar Administration', ARRAY['Jharkhand']::TEXT[], ARRAY['Deoghar', 'Jasidih']::TEXT[], ARRAY['Baba Baidyanath Jyotirlinga Temple Complex']::TEXT[], 'Dawn (4 AM to 8 AM) for early morning VIP/general darshan lines', 2, 'Profound, electric spiritual intensity: a monumental sea of saffron-clad pilgrims whose blistered feet and weary bodies are forgotten in ecstatic devotion.', 'Deoghar Airport connects to Delhi/Kolkata; Jasidih Junction (7 km) is a major mainline railway station.', 'Extensive hotels, dharamshalas, and guest houses throughout Deoghar; book well in advance during Shravan.', 'Massive crowd crush; general darshan queue can take 6-12 hours on Shravan Mondays; buy advance ''Shigra Darshan'' passes online.', 'Deposit mobile phones and leather items outside; follow temple trust queue marshals strictly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://babadham.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hal-punhya-jharkhand', 'Hal Punhya', ARRAY['First Plowing Ceremony']::TEXT[], 'Harvest & Agriculture', 'Indigenous Agrarian & Solar Rites', 'The sacred agrarian ceremony marking the formal beginning of the new agricultural plowing season on the day following Makar Sankranti.', 'Ancient agricultural rite observed by tribal and farming communities across Jharkhand, celebrating the awakening of the soil.', 'Celebrates the end of winter dormancy and the spiritual commencement of agricultural plowing for the year.', 'To consecrate the wooden plow and bullocks and pray to Mother Earth for good rainfall and pest-free crops.', 'Traditionally conducted at dawn on the first day of the solar month of Magha, immediately following Makar Sankranti.', 'The farmer plows exactly two and a half furrows in his field, interpreting the direction of the upturned earth to forecast crop prosperity.', ARRAY['Ceremonial washing and applying of vermilion and oil to the wooden plow (Hal) and bullocks', 'Plowing of exactly two and a half furrows in the family field at dawn', 'Offering of sanctified grains to Mother Earth and praying for bountiful rainfall']::TEXT[], 'Families gather in misty morning fields, singing traditional agrarian songs and greeting neighbors with wishes for a prosperous farming year.', ARRAY['Pitha (steamed rice dumplings)', 'Chuda Dahi with new harvest jaggery', 'Til Ladoo', 'Dhuska']::TEXT[], 'Traditional white cotton dhotis, kurtas, gamchas, and simple rural sarees.', 'Melodious rural folk songs celebrating the earth, oxen, and rain, sung without instruments.', 'Wooden agricultural plow (Hal), consecrated bullock yoke, and freshly turned dark earth.', '1 Day', 'Solar / Magh Sankranti', 'First day of the solar month of Magh (January 15).', 'January', 'FIXED', 'Celebrated on the day following Makar Sankranti (January 15).', '2026-01-15', '2027-01-15', 'Jharkhand Agriculture Department & Village Gram Sabhas', ARRAY['Jharkhand']::TEXT[], ARRAY['Ranchi', 'Hazaribagh', 'Palamu', 'Giridih']::TEXT[], ARRAY['Agricultural fields across rural Jharkhand']::TEXT[], 'Early morning dawn hours (6 AM to 8 AM) when the ceremonial first plowing takes place', 1, 'Peaceful, deeply grounded agrarian spirituality: watching farmers lovingly honor their wooden plows and turn the first soil of spring.', 'Easily witnessed across any farming hamlet in rural Jharkhand.', 'Hotels in nearby district centers.', 'Early dawn winter chill; wear warm clothing for open field visits.', 'Respect the sanctity of the newly plowed furrows; do not step across consecrated ground.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jharkhandtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bandna-parab', 'Bandna Parab', ARRAY['Sohrai Cattle Festival Jharkhand']::TEXT[], 'Harvest & Agriculture', 'Pastoral Devotion & Animal Reverence', 'The joyous week-long post-harvest cattle festival celebrated by Kurmi, Santhal, and Munda communities, featuring singing to working animals.', 'Ancient pastoral festival celebrating the animals whose labor created the golden winter harvest.', 'Celebrates the deep symbiotic bond between human beings, bullocks, cows, and nature.', 'To honor, decorate, and express profound gratitude to livestock for their selfless labor throughout the farming year.', 'Celebrated around Kartik Amavasya (Diwali); features the famous ''Gohal Puja'' (cowshed worship) and ''Ohira'' singing.', 'Farmers sing traditional ''Ohira'' ballads to their cattle at midnight, soothing them and apologizing for any harshness during the plowing season.', ARRAY['Gohal Puja: cleaning, whitewashing, and lighting oil lamps in every cattle shed', 'Bathing bullocks and painting their horns in bright red and yellow designs with oil and vermilion', 'Singing traditional Ohira folk ballads to cattle accompanied by small clay drums']::TEXT[], 'Villages glow with hundreds of oil lamps, while decorated bullocks with floral crowns and brass bells are paraded through streets to festive drumming.', ARRAY['Pitha (steamed rice cakes)', 'Dhuska', 'Arsa Roti', 'Ladoo', 'Fresh sugarcane']::TEXT[], 'Traditional rural dhotis, kurtas, and colorful cotton sarees with traditional jewelry.', 'Poetic singing of traditional Ohira songs, accompanied by Dholak, Dhak, and flutes.', 'Painted bullock horns decorated with paddy sheaves, oil lamps in cattle sheds, and flower garlands.', '7 Days', 'Hindu-Tribal Lunisolar', 'Celebrated during the week surrounding Kartik Amavasya (Diwali).', 'November', 'LUNISOLAR', 'Held in Kartik month around Diwali.', '2026-11-08', '2027-10-29', 'Jharkhand Cultural Affairs Board & Local Panchayats', ARRAY['Jharkhand']::TEXT[], ARRAY['Dhanbad', 'Bokaro', 'Purulia', 'Ranchi', 'Giridih']::TEXT[], ARRAY['Village courtyards and cattle sheds across Jharkhand']::TEXT[], 'Evening during cattle shed illumination and morning decorated bullock parades', 1, 'Heartwarming rural affection: observing farmers gently sing apologetic and loving ballads to their gentle working animals.', 'Easily accessible across rural Jharkhand via road transport from Ranchi or Dhanbad.', 'Hotels in district centers.', 'Large animal movements in village lanes; maintain gentle distance from excited bulls.', 'Admire the hand-painted horn art; treat village cattle with gentleness.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jharkhandtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhagta-parab', 'Bhagta Parab', ARRAY['Tribal Ascetic Penance Festival']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Shamanism & Shiva Worship', 'The dramatic spring tribal festival celebrated by the Tamar and Kol communities, featuring barefoot fire-walking and extreme feats of ascetic devotion.', 'Ancient tribal festival celebrated in the Chotanagpur plateau, combining indigenous animism with the worship of Lord Shiva (Budha Baba).', 'Celebrates spiritual endurance, purification of the body and mind, and prayers for village prosperity.', 'To fulfill solemn vows, seek healing from chronic diseases, and invoke the blessings of Budha Baba.', 'Devotees (Bhagtas) undergo strict fasting and austerity for days, culminating in breathtaking public demonstrations of faith.', 'Features the dramatic ''Lota-dhor'' where priests swing devotees suspended from high wooden poles over blazing fires without injury.', ARRAY['Ritual purification and fast observed by male devotees (Bhagtas)', 'Walking barefoot across beds of glowing red-hot coals (Agnikunda)', 'Devotees suspended from high rotating wooden masts by cords, swinging over crowds in ecstatic trance']::TEXT[], 'Thousands of villagers gather in the village square, cheering and playing drums as Bhagtas walk calmly across glowing red-hot embers.', ARRAY['Simple fasting prasad: fruits, milk, and sweet sattu', 'Pitha', 'Chilka Roti', 'Khichdi']::TEXT[], 'Sacred white dhotis, bare upper bodies smeared with sandalwood paste and sacred ash, and flower garlands.', 'Thunderous beats of giant Nagara drums, wailing Shehnai, and roaring cheers of ''Budha Baba Ki Jai!''.', 'Glowing red-hot coal pit (Agnikunda), towering wooden swinging pole, and trishul standards.', '2 Days', 'Hindu-Tribal Lunisolar / Spring', 'Celebrated in the month of Chaitra / Baisakh (April - May).', 'April - May', 'LUNISOLAR', 'Held during spring in Chaitra/Baisakh.', '2026-04-14', '2027-04-14', 'Tamar & Bundu Regional Cultural Committees', ARRAY['Jharkhand']::TEXT[], ARRAY['Tamar', 'Bundu', 'Ranchi']::TEXT[], ARRAY['Village temple grounds across Tamar block']::TEXT[], 'Afternoon and evening when fire-walking and pole-swinging feats take place', 1, 'Astonishing, hair-raising encounter with extreme faith and mind-over-matter endurance in a vibrant rural tribal setting.', '50 km southeast of Ranchi on the Tata-Ranchi highway; accessible by bus or car.', 'Base yourself in Ranchi hotels and visit Tamar on a day excursion.', 'High emotional energy and dense rural crowds; stay behind safety ropes near the fire-pit.', 'Do not mock or disrupt the deep trance states of the Bhagtas; observe with respectful awe.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ranchi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rath-yatra-puri', 'Rath Yatra Puri', ARRAY['Shri Jagannath Chariot Festival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Universal Brotherhood)', 'The world''s most famous chariot festival where colossal multi-storey wooden chariots of Lord Jagannath, Balabhadra, and Subhadra are pulled by millions down the Grand Road of Puri.', 'Celebrated for over a millennium, documented in ancient Puranas, centered around the 12th-century Jagannath Temple built by King Anantavarman Chodaganga Deva.', 'Commemorates the annual journey of Lord Jagannath from his sanctum to his maternal aunt''s home at Gundicha Temple, granting darshan to all humanity.', 'To pull the sacred ropes of the divine chariots, an act believed to cleanse all sins and grant liberation (Moksha).', 'The supreme cultural festival of Odisha, famous for its colossal wooden chariots hand-built anew each year without nails from sacred timber.', 'Features the ''Chhera Panhara'', where the titular Gajapati King of Puri sweeps the chariot floors with a golden broom, demonstrating supreme humility.', ARRAY['Chhera Panhara: ceremonial sweeping of chariot decks by the Gajapati King of Puri with a golden broom', 'Pulling of the three colossal wooden chariots (Nandighosha, Taladhwaja, Darpadalana) by over one million devotees', 'Nine-day stay of the deities at Gundicha Temple followed by the return Bahuda Yatra']::TEXT[], 'Puri''s Bada Danda (Grand Road) becomes an ocean of humanity, chanting ''Jai Jagannath'' amidst flying floral garlands and thunderous drumbeats.', ARRAY['Jagannath Mahaprasad (Khaja, Abadha, Dalma, Kanika rice, Chhena Poda)', 'Chhena Gaja', 'Rasabali', 'Malpua']::TEXT[], 'Crisp cotton kurtas, yellow dhotis, Jagannath stoles, and traditional handloom Sambalpuri sarees.', 'Thunderous beats of hundreds of bronze gongs (Ghanta), traditional Mardala percussion, and conch shell blasts.', 'Three towering wooden chariots draped in red, yellow, green, and black silk, colossal wooden wheels, and golden brooms.', '9 Days', 'Hindu Lunisolar', 'Ashadha Shukla Dwitiya (June - July)', 'June - July', 'LUNISOLAR', 'Begins on Ashadha Shukla Dwitiya.', '2026-07-16', '2027-07-06', 'Shree Jagannath Temple Administration & Odisha Tourism', ARRAY['Odisha']::TEXT[], ARRAY['Puri']::TEXT[], ARRAY['Bada Danda (Grand Road) Puri', 'Shree Jagannath Temple', 'Gundicha Temple']::TEXT[], 'Opening day for the pulling of chariots (Rath Yatra) and concluding Bahuda Yatra', 3, 'Colossal, spine-tingling spiritual magnitude: standing among a million singing devotees, watching giant wooden chariots rumble forward like moving mountains.', 'Puri is a major railway terminus; 60 km from Biju Patnaik International Airport Bhubaneswar via 4-lane highway.', 'Hotels, resorts, and dharamshalas along Puri Beach and Grand Road; book 6-12 months in advance.', 'Monumental crowds exceeding one million; stay away from the moving chariot wheels; follow police pedestrian corridors.', 'Never climb onto chariots without official permission; enjoy the blessed Mahaprasad inside Anand Bazar.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jagannath.odisha.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-konark-dance-festival', 'Konark Dance and Sand Art Festival', ARRAY['Konark Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & Architectural Wonder', 'A world-renowned five-day celebration of classical Indian dance staged against the monumental UNESCO World Heritage 13th-century Sun Temple of Konark.', 'Initiated in 1986 by Odisha Tourism and Odissi Research Centre against the colossal Sun Temple built by King Narasimhadeva I in 1250 CE.', 'Celebrates the immortal dialogue between stone sculpture, classical dance, and solar architecture.', 'To showcase India''s highest classical dance traditions against one of the greatest architectural wonders of human civilization.', 'Organized simultaneously with the International Sand Art Festival on the golden sands of nearby Chandrabhaga Beach.', 'Features master exponents of Odissi, Bharatanatyam, Kathak, Kuchipudi, and Manipuri performing on an open-air stone stage under dramatic golden floodlights.', ARRAY['Nightly classical dance performances by living legends of Indian classical arts', 'International Sand Art Festival at Chandrabhaga Beach with master sand sculptors from 20+ nations', 'Craft exhibition showcasing Odishan silver filigree, Pattachitra paintings, and handlooms']::TEXT[], 'Audiences sit in the cool December night air, mesmerized as classical dancers match the exact sculptural dance poses carved on the ancient stone wheels behind them.', ARRAY['Chhena Poda (baked caramelized cottage cheese cake - pride of Odisha)', 'Chhena Gaja', 'Dalma with steamed rice', 'Poda Pitha', 'Crab Masala']::TEXT[], 'Formal Indian ethnic wear: handloom Sambalpuri, Bomkai, and Pasapalli silk sarees, bandhgalas, and warm shawls.', 'Sublime classical Odissi music: Mardala percussion, flute, violin, and Odissi vocal ragas, alongside Carnatic and Hindustani ensembles.', '24 monumental carved stone chariot wheels of Konark, sculpted stone horses, and golden floodlights.', '5 Days', 'Gregorian / Annual', 'December 1 to 5 annually.', 'December', 'FIXED', 'Held annually December 1-5.', '2026-12-01', '2027-12-01', 'Department of Tourism Odisha & Sangeet Natak Akademi', ARRAY['Odisha']::TEXT[], ARRAY['Konark', 'Puri']::TEXT[], ARRAY['Konark Sun Temple Amphitheatre', 'Chandrabhaga Beach']::TEXT[], 'Evenings between 6 PM and 8:30 PM for dance recitals and daytime for sand art viewing', 2, 'Transcendental, awe-inspiring aesthetic perfection: ancient stone temple wheels glowing amber in the darkness with sublime classical dancers moving to timeless ragas.', '65 km from Bhubaneswar Airport; 35 km from Puri railway station; accessible by smooth 4-lane highway.', 'Luxury eco-retreat tented camps set up by Odisha Tourism on the beach, hotels in Konark, or stay in Puri.', 'Pleasant but cool December evenings; carry a warm shawl or light jacket.', 'Strict archaeological protection: no touching ancient temple stone carvings; sand sculptures should be admired from viewing barriers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://odishatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-raja-parba-odisha', 'Raja Parba', ARRAY['Swing Festival of Odisha', 'Mithuna Sankranti']::TEXT[], 'Seasonal & Nature', 'Folk Agrarian & Feminine Earth Reverence', 'The unique three-day festival celebrating the fertility of Mother Earth (Bhumi Devi) and honoring womanhood, where no earth is tilled and girls enjoy flower-decked swings.', 'Ancient agrarian tradition unique to Odisha, marking the onset of the monsoon and the agricultural rejuvenation of Mother Earth.', 'According to legend, Mother Earth undergoes her menstrual cycle during these three days before the monsoon rains commence.', 'To grant complete rest to Mother Earth: no plowing, digging, or cutting of trees is permitted, and women are pampered with sweet food and games.', 'A cherished cultural celebration of feminine biological rhythms, womanhood, and nature''s fertility, celebrated across all Odia households.', 'Famous for the traditional community swings (Jhulas) suspended from mango and banyan trees, decorated with fresh wild flowers.', ARRAY['First day ''Pahili Raja'', second day ''Mithuna Sankranti'', third day ''Basi Raja'', and fourth day ''Vasumati Snana'' (purification bath of Mother Earth)', 'Hanging flower-bedecked swings from trees and girls swinging high while singing traditional Raja folk songs', 'Gifting new clothes, applying alta (red dye) to feet, and enjoying sweet Poda Pitha without cooking chores']::TEXT[], 'Village groves and urban parks buzz with laughter as young girls in new dresses swing high into the summer sky, singing melodious Raja ballads.', ARRAY['Poda Pitha (traditional baked cake of rice, black gram, coconut, and jaggery)', 'Manda Pitha', 'Arisa Pitha', 'Raja Paan (sweet betel leaf)', 'Chhena Gaja']::TEXT[], 'New festive sarees, colorful salwar kameez, red alta dye decorating the edges of feet, and traditional gold ornaments.', 'Melodious traditional Raja folk songs sung in chorus on swings, accompanied by Dholak and flute.', 'Decorated floral swings, baked Poda Pitha cakes, red alta feet markings, and sweet betel leaves (Raja Paan).', '4 Days', 'Solar / Mithuna Sankranti', 'First day of Mithuna solar month (June 14-16 annually).', 'June', 'FIXED', 'Celebrated June 14-17 annually.', '2026-06-14', '2027-06-14', 'Odisha Tourism & Department of Odia Language, Literature & Culture', ARRAY['Odisha']::TEXT[], ARRAY['Bhubaneswar', 'Cuttack', 'Puri', 'Balasore', 'Sambalpur']::TEXT[], ARRAY['Village greens across Odisha', 'Ekamra Haat Bhubaneswar']::TEXT[], 'Afternoon between 3 PM and 7 PM when swings are bustling and folk singing is at its peak', 2, 'Joyful, heartwarming celebration of nature''s feminine vitality, sweet aroma of baked Poda Pitha, and carefree swinging under cool mango trees.', 'Easily experienced across all towns and villages of Odisha via local buses and cabs.', 'Hotels throughout Bhubaneswar, Cuttack, and Puri.', 'Summer monsoon transition; humid daytime weather; stay hydrated.', 'Respect the cultural modesty of village women participating in swing rituals; enjoy fresh Raja Paan from local stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://odishatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-durga-puja-cuttack', 'Durga Puja Cuttack', ARRAY['Cuttack Chandi Medha Puja']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & Silver Filigree Heritage)', 'The historic celebration of Goddess Durga in the Millennium City of Cuttack, world-famous for its dazzling ''Chandi Medha'' silver filigree backdrops weighing hundreds of kilos.', 'Celebrated since 1510 CE when Chaitanya Mahaprabhu visited Cuttack and consecrated the first Durga Puja at Balu Bazar.', 'Celebrates the triumph of Goddess Durga over the demon Mahishasura and the divine protective power of the Mother Goddess.', 'To seek blessings of Goddess Durga and showcase Cuttack''s world-famous 500-year-old GI-tagged silver filigree craftsmanship (Tarakasi).', 'Over 160 community puja pandals in Cuttack feature colossal backdrop arches (Medhas) hand-crafted entirely from pure silver and gold filigree.', 'Famous for the historic ''Bhasani'' immersion procession, where dozens of illuminated tableaux march through the streets for 24 continuous hours.', ARRAY['Prana Pratishtha of Goddess Durga idols adorned in gold and silver filigree jewelry', 'Exhibition of dazzling multi-crore silver filigree backdrops (Chandi Medhas) at Choudhury Bazar and Balu Bazar', 'Epic 24-hour immersion procession (Bhasani) with synchronized drum beats and fireworks']::TEXT[], 'Over two million spectators throng the narrow historic streets of Cuttack, marveling at the glowing silver filigree arches and cheering the immersion processions.', ARRAY['Dahi Bara Aloo Dum (Cuttack''s iconic street food: lentil fritters in spiced yogurt with potato curry)', 'Gupchup', 'Rasagola', 'Chhena Poda', 'Thakur Bhog']::TEXT[], 'Traditional silk Sambalpuri and Kataki sarees, crisp white kurtas with dhotis, and festive ethnic wear.', 'Thunderous, fast-paced beats of Ghanta, Dhol, and Tasha, accompanied by classical Odissi music and patriotic marches.', 'Intricate silver filigree peacock backdrops (Chandi Medha), golden crown of Goddess Durga, and Mahanadi riverbanks.', '5 Days', 'Hindu Lunisolar', 'Ashwin Shukla Shashthi to Dashami (September - October)', 'September - October', 'LUNISOLAR', 'Celebrated during Ashwin Navratri / Durga Puja.', '2026-10-17', '2027-10-06', 'Cuttack Mahanagar Shanti Committee & Odisha Police', ARRAY['Odisha']::TEXT[], ARRAY['Cuttack']::TEXT[], ARRAY['Choudhury Bazar', 'Balu Bazar', 'Chandni Chowk', 'Kathajodi River Ghats']::TEXT[], 'Maha Ashtami night for viewing the glowing silver filigree backdrops and Vijyadashami for the Bhasani procession', 2, 'Dazzling, glittering silver spectacle of unmatched artisanal brilliance, mouthwatering street food, and Cuttack''s legendary communal harmony.', '30 km north of Bhubaneswar; connected by twin-city highway buses, local trains, and cabs.', 'Hotels across Cuttack and Bhubaneswar.', 'Vast pedestrian crowds in narrow lanes; major streets are closed to vehicles from 5 PM onwards.', 'Do not touch the delicate silver filigree backdrops; enjoy Cuttack''s famous Dahi Bara Aloo Dum from street vendors.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://cuttack.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nuakhai-sambalpur', 'Nuakhai Sambalpur & Western Odisha', ARRAY['Agrarian New Rice Festival']::TEXT[], 'Harvest & Agriculture', 'Pastoral Agriculture & Mother Earth Gratitude', 'The foremost agrarian social festival of Western Odisha, where families offer the first harvest grains of rice to presiding deity Goddess Samaleswari.', 'Centuries-old agrarian festival dating back to the Vedic period (Panchayajna), revitalized under the 14th-century Chauhan dynasty of Sambalpur.', 'Celebrates the harvest of the new paddy crop and thanksgiving to Mother Earth and village deities.', 'To offer the first harvested grain (Nua) to the gods and ancestors before consuming it as a community.', 'Famous for the emotional social custom of ''Nuakhai Juhar''—elders bless the younger generations, and all past grievances and feuds are forgiven.', 'Observed on an exact auspicious planetary hour (Lagna) determined by senior astrologers and temple priests.', ARRAY['Offering the first cooked rice porridge (Nabanna) to Goddess Samaleswari at the auspicious Lagna', 'Partaking of the consecrated new rice meal with extended families sitting together in unity', 'Nuakhai Juhar: touching elders'' feet, embracing peers, and exchanging formal greetings across the community']::TEXT[], 'Towns and villages in western Odisha come alive with music, joyous family reunions, new clothes, and high-energy Sambalpuri folk dances.', ARRAY['Nabanna (new rice cooked with milk, jaggery, and sesame)', 'Kheer', 'Pitha', 'Chaul Bara (crispy rice fritters)', 'Kakara Pitha']::TEXT[], 'Exquisite handloom Sambalpuri silk and cotton sarees with traditional Ikat weave motifs; men wear Sambalpuri kurtas and kurtis.', 'High-voltage, infectious Sambalpuri folk dances: Dalkhai, Rasarkeli, and Maelajada, fueled by thundering Dhol and Nishan drums.', 'Fresh ears of green paddy sheaves, clay bowls of new rice, Samaleswari temple spire, and Sambalpuri Ikat textiles.', '1 Day', 'Hindu Lunisolar', 'Bhadrapada Shukla Panchami (the day after Ganesh Chaturthi)', 'August - September', 'LUNISOLAR', 'Celebrated on Bhadrapada Shukla Panchami.', '2026-09-15', '2027-09-05', 'Samaleswari Temple Trust & Sambalpur District Administration', ARRAY['Odisha']::TEXT[], ARRAY['Sambalpur', 'Bargarh', 'Balangir', 'Jharsuguda', 'Rourkela']::TEXT[], ARRAY['Maa Samaleswari Temple Sambalpur']::TEXT[], 'Morning auspicious Lagna hour for temple Nabanna offering and evening Sambalpuri cultural programs', 1, 'Heartwarming family solidarity, forgiveness, mouthwatering new-harvest feasts, and the irresistible, foot-tapping beats of Sambalpuri folk drums.', 'Sambalpur is well connected by rail on the Mumbai-Howrah line; 280 km west of Bhubaneswar.', 'Hotels throughout Sambalpur city.', 'Warm late-monsoon weather; pleasant festive atmosphere.', 'Embrace the spirit of Nuakhai Juhar: greet locals with ''Nuakhai Juhar'' and receive warm blessings in return.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sambalpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bali-yatra-cuttack', 'Bali Yatra Cuttack', ARRAY['Voyage to Bali Maritime Fair']::TEXT[], 'Fair & Mela', 'Secular / Ancient Maritime Seafaring Heritage', 'Asia''s largest open-air trade fair celebrated on the vast sandy banks of the Mahanadi River, commemorating ancient Odia mariners (Sadhabas) who sailed to Bali, Java, and Sumatra.', 'Ancient historical fair celebrating over 2,000 years of maritime trade between Kalinga (Odisha) and the islands of Southeast Asia (Bali, Java, Sumatra, Sri Lanka).', 'Celebrates maritime enterprise, naval exploration, and international commercial exchange.', 'To honor the brave seafaring ancestors and provide an enormous open-air commercial and cultural marketplace.', 'Sprawls over 50 acres on the riverbed near historic Barabati Fort, attracting over five million visitors over eight days.', 'Begins on Kartik Purnima with the floating of miniature boats (Boita Bandana) to re-enact the historic voyages of the merchant fleet.', ARRAY['Dawn release of illuminated miniature boats made of banana bark and paper into the Mahanadi River', 'Opening of the 50-acre mega-fairground featuring over 1,500 commercial, craft, and food pavilions', 'National cultural festival ''Ganakavi Baishnab Pani Manch'' showcasing performing artists from across India']::TEXT[], 'Millions of visitors browse vast electronics pavilions, artisan stalls, rural pottery displays, giant rides, and food alleys stretching across the river sands.', ARRAY['Cuttack Dahi Bara Aloo Dum', 'Thunka Puri with Chenna Tarka', 'Rasagola', 'Kulfi', 'Biryani']::TEXT[], 'Casual urban wear, comfortable walking shoes, and light evening jackets.', 'Folk dances from across India, live Bollywood and Odia musical concerts, and energetic street theatre.', 'Giant mechanized paper boats (Boitas), historic Barabati Fort walls, Ferris wheels, and vast sandy riverbeds.', '8 Days', 'Hindu Lunisolar', 'Begins on Kartik Purnima (November) and lasts for eight days.', 'November', 'LUNISOLAR', 'Begins on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Cuttack District Administration & Odisha Tourism', ARRAY['Odisha']::TEXT[], ARRAY['Cuttack']::TEXT[], ARRAY['Mahanadi Riverbed Grounds Barabati Fort']::TEXT[], 'Evening between 5 PM and 10 PM for the glittering mega-fairground atmosphere', 3, 'Vast, exhilarating commercial and cultural spectacle of staggering proportions: an entire glowing city of stalls on a sandy riverbed buzzing with energy.', 'Easily accessible across Cuttack via auto-rickshaws, shuttle buses, and cabs; dedicated parking zones outside the riverbed.', 'Hotels in Cuttack and Bhubaneswar (30 km away via 4-lane highway).', 'Vast walking distances across sandy riverbed; wear sturdy walking shoes; keep children close in massive crowds.', 'Buy authentic handloom and brass bell metal crafts directly from government-certified rural artisan pavilions.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://cuttack.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chandan-yatra-puri', 'Chandan Yatra Puri', ARRAY['Sandalwood Water Festival Puri']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Aquatic Devotion)', 'The longest festival of Lord Jagannath spanning 42 continuous days, where the deities enjoy evening boat cruises in the sandalwood-scented waters of Narendra Tank.', 'Celebrated since ancient times, marking the onset of the scorching summer season when cooling rituals are performed for the deities.', 'Celebrates the summer relaxation of Lord Jagannath, Balabhadra, Subhadra, and the Five Shivas (Pancha Pandavas).', 'To offer cool sandalwood paste (Chandan) and boat rides to soothe the deities from summer heat.', 'Spans 42 days in two phases: Bahara Chandana (21 days in Narendra Tank) and Bhitara Chandana (21 days inside the temple complex).', 'The deities are carried in palanquins to the historic Narendra Tank and boarded onto two lavishly decorated swan-shaped wooden boats (Nanda and Bhadra).', ARRAY['Anointing the deities with fragrant white and red sandalwood paste (Chandan Lepana)', 'Evening procession of the deities in silver palanquins from Jagannath Temple to Narendra Tank', 'Boat cruise of the deities around the island temple in Narendra Tank accompanied by music and dance']::TEXT[], 'Devotees throng the stone ghats of Narendra Tank, watching the illuminated swan boats glide across the water while temple music plays.', ARRAY['Manduo sweet', 'Tanka Torani (spiced fermented rice water with lemon leaves and green chili)', 'Chhena Gaja', 'Mahaprasad']::TEXT[], 'Light white cotton dhotis, kurtas, and summer cotton sarees.', 'Traditional Odissi Mardala, soothing flute melodies, and classical Odissi devotional singing.', 'Two swan-shaped wooden boats (Nanda and Bhadra), Narendra Tank island temple, and white sandalwood paste.', '42 Days (Peak 21 Days)', 'Hindu Lunisolar / Summer', 'Begins on Akshaya Tritiya (April - May) and lasts for 42 days.', 'April - May', 'LUNISOLAR', 'Begins on Akshaya Tritiya.', '2026-04-19', '2027-05-09', 'Shree Jagannath Temple Administration & Puri Municipality', ARRAY['Odisha']::TEXT[], ARRAY['Puri']::TEXT[], ARRAY['Narendra Tank Complex Puri', 'Grand Road']::TEXT[], 'Evenings between 5:30 PM and 8:30 PM during the boat cruise in Narendra Tank', 2, 'Serene, fragrant summer devotion: cool evening breezes over holy water, gentle splashing of swan boats, and soothing classical Odissi music.', 'Centrally located in Puri; accessible by auto-rickshaw, cycle-rickshaw, or walking from Grand Road.', 'Beach resorts and hotels across Puri.', 'Warm and humid summer evenings; carry bottled water and wear light cotton clothing.', 'Maintain queue decorum along the Narendra Tank stone embankments.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jagannath.odisha.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-boita-bandana-odisha', 'Boita Bandana', ARRAY['Kartik Purnima Boat Festival']::TEXT[], 'Seasonal & Nature', 'Maritime History & River Thanksgiving', 'The poetic dawn festival where millions of people across Odisha float miniature paper, cork, and banana-bark boats carrying glowing lamps into rivers and lakes.', 'Ancient cultural tradition commemorating the historic maritime expeditions of Kalinga''s merchant-navigators who set sail on Kartik Purnima.', 'Celebrates the favorable northeast trade winds that allowed ancient mariners to navigate across the Indian Ocean to Southeast Asia.', 'To remember ancestral seafaring heroism and pray for family prosperity and safe journeys.', 'Celebrated at dawn on Kartik Purnima across every river, pond, canal, and ocean beach in Odisha.', 'Accompanied by the timeless folk chant: ''Aa Ka Ma Boi, Pana Gua Thoi, Pana Gua Tora, Masaka Dharama Mora'' (celebrating four holy months).', ARRAY['Crafting miniature boats from colored paper, cork (sholapith), and dried banana plantain bark', 'Placing an earthen oil lamp, betel leaf (Pana), betel nut (Gua), and flowers inside the miniature boat', 'Gently launching the illuminated boat onto the water at dawn while singing the traditional chant']::TEXT[], 'Water bodies across Odisha glow with hundreds of thousands of twinkling miniature boats drifting peacefully across morning mists.', ARRAY['Habisha Dalma', 'Kheer', 'Arisa Pitha', 'Chhena Poda', 'Khaja']::TEXT[], 'Traditional white cotton dhotis, kurtas, and handloom cotton sarees.', 'Devotional chanting of ''Aa Ka Ma Boi'', conch shell blasts, and temple morning bells.', 'Miniature paper and cork boats (Boitas), glowing oil lamps on water, and sunrise over rivers.', '1 Day', 'Hindu Lunisolar', 'Kartik Purnima (dawn of the full moon of Kartik month in November)', 'November', 'LUNISOLAR', 'Celebrated at dawn on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Odisha Culture Department & Local Municipalities', ARRAY['Odisha']::TEXT[], ARRAY['Bhubaneswar', 'Cuttack', 'Puri', 'Sambalpur', 'Paradip']::TEXT[], ARRAY['Bindu Sagar Lake Bhubaneswar', 'Mahanadi River Ghats', 'Puri Sea Beach']::TEXT[], 'Pre-dawn hours (4:30 AM to 6:30 AM) when thousands of glowing boats are released at sunrise', 1, 'Deeply poetic, visually enchanting sunrise spectacle: misty morning waters glowing with a shimmering galaxy of thousands of floating paper boats.', 'Easily experienced at any water body across Odisha; Bindu Sagar in Bhubaneswar is especially magical.', 'Hotels throughout Bhubaneswar, Cuttack, and Puri.', 'Crisp November morning weather; wear a light shawl.', 'Eco-friendly practice: use only biodegradable paper, cork, or banana-bark boats; avoid plastic or chemical decorations.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://odishatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-dhauli-kalinga-mahotsav', 'Dhauli Kalinga Mahotsav', ARRAY['Peace Pagoda Martial Dance Fest']::TEXT[], 'Art & Cultural Festival', 'Martial Arts & Buddhist Peace Heritage', 'A premier three-day festival of classical dance and traditional martial arts staged at the foot of the glistening white Dhauli Peace Pagoda.', 'Jointly established by the Odisha Tourism Department and Orissa Dance Academy at the historic site of the Kalinga War (261 BCE).', 'Celebrates Emperor Ashoka''s historic transformation from war and violence (Chandashoka) to peace and compassion (Dharmashoka).', 'To spread the message of universal peace, non-violence, and harmony through the synthesis of martial arts and classical dance.', 'Staged against the gleaming white hemispherical dome of the Shanti Stupa erected atop Dhauli Hill by Japanese Buddhist monks.', 'Uniquely combines graceful classical dance traditions with thrilling indigenous martial arts (Kalaripayattu, Thang-Ta, Paika Akhada, Chhau).', ARRAY['Nightly classical dance recitals by leading exponents of Odissi, Kathak, and Bharatanatyam', 'High-octane martial arts demonstrations featuring live sword-fighting, spear duels, and shields', 'Buddhist peace prayers and guided heritage walks through the 3rd-century BCE Ashokan rock edicts']::TEXT[], 'Connoisseurs sit beneath cold starlit skies on the hillside, watching graceful classical dancers followed by roaring martial warriors clashing swords.', ARRAY['Odishan Thali', 'Chhena Poda', 'Rasagola', 'Dalma', 'Puri Bhaji']::TEXT[], 'Refined formal Indian ethnic wear: handloom silk sarees, kurtas, and warm shawls.', 'Classical Odissi music, energetic martial drumbeats, war trumpets, and resonant Buddhist peace chants.', 'White Dhauli Shanti Stupa dome, Ashokan rock-cut elephant sculpture, and Daya River valley vistas.', '3 Days', 'Gregorian / Winter', 'February 6 to 8 annually.', 'February', 'FIXED', 'Held annually February 6-8.', '2026-02-06', '2027-02-06', 'Department of Tourism Odisha & Orissa Dance Academy', ARRAY['Odisha']::TEXT[], ARRAY['Dhauli', 'Bhubaneswar']::TEXT[], ARRAY['Dhauli Shanti Stupa Foothills']::TEXT[], 'Evenings between 6 PM and 9 PM during the floodlit martial and classical dance concerts', 2, 'Inspiring, powerful aesthetic contrast: martial warriors clashing swords followed by serene classical dancers under the glowing Buddhist peace pagoda.', '10 km south of Bhubaneswar city center; accessible by taxi, auto-rickshaw, or tourist bus.', 'Extensive hotels across Bhubaneswar city.', 'Chilly February evenings on the hillside; carry a warm shawl or jacket.', 'Do not touch or climb on the 2,300-year-old rock edicts of Emperor Ashoka at the base of the hill.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://odishatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mukteswar-dance-festival', 'Mukteswar Dance Festival Bhubaneswar', ARRAY['Gem of Odishan Architecture Fest']::TEXT[], 'Art & Cultural Festival', 'Odissi Classical Dance & 10th-Century Temple Architecture', 'An exquisite three-day festival dedicated exclusively to classical Odissi dance, staged in the intimate courtyard of the 10th-century Mukteswar Temple.', 'Initiated by Odisha Tourism at the monument considered the ''Gem of Odishan Architecture'', renowned for its magnificent arched Torana gateway.', 'Celebrates the pure, sculpturesque beauty of classical Odissi dance and temple architectural aesthetics.', 'To provide a sanctified, intimate platform exclusively for classical Odissi solo, duet, and group performances.', 'The arched Torana gateway of Mukteswar Temple, carved with smiling maidens and celestial musicians, serves as the natural stage backdrop.', 'Features performances by leading Odissi gurus and disciples of the Kelucharan Mohapatra, Pankaj Charan Das, and Deba Prasad Das schools.', ARRAY['Opening Shiva Vandana invocation by classical Odissi vocalists', 'Solo, duet, and group Odissi dance performances matching temple sculptural poses', 'Illumination of the 10th-century stone temple spire and Marichi Kund sacred tank']::TEXT[], 'Audiences sit in rapt silence on the temple flagstones, watching dancers in silver jewelry and silk sarees perform intricate sculpturesque footwork.', ARRAY['Bhubaneswar street chaat', 'Chhena Gaja', 'Rasagola', 'Kachori with Aloo Dum']::TEXT[], 'Formal handloom attire: Sambalpuri and Kataki silk sarees, ethnic kurtas, and light evening shawls.', 'Classical Odissi music: Mardala percussion, flute, violin, and soulful singing of Gita Govinda ashtapadis.', 'Carved stone Torana arch of Mukteswar Temple, Marichi Kund water reflections, and glowing oil lamps.', '3 Days', 'Gregorian / Winter', 'January 14 to 16 annually.', 'January', 'FIXED', 'Held annually January 14-16.', '2026-01-14', '2027-01-14', 'Department of Tourism Odisha & Guru Kelucharan Mohapatra Odissi Research Centre', ARRAY['Odisha']::TEXT[], ARRAY['Bhubaneswar']::TEXT[], ARRAY['Mukteswar Temple Complex Old Town']::TEXT[], 'Evenings between 6 PM and 8:30 PM for intimate open-air classical concerts', 2, 'Sublime, intimate classical aesthetic bliss: sitting in a 1,000-year-old temple courtyard with classical Odissi dancers performing before ancient stone sculptures.', 'Located in Old Town Bhubaneswar; easily accessible by auto-rickshaw or taxi.', 'Hotels throughout Bhubaneswar.', 'Intimate courtyard seating on first-come basis; arrive 30 minutes early to secure good seats.', 'Maintain pin-drop silence during performances; no flash photography allowed.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://odishatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chhau-mahotsav-baripada', 'Chhau Mahotsav Baripada', ARRAY['Mayurbhanj Chhau Dance Festival']::TEXT[], 'Art & Cultural Festival', 'Indigenous Martial Dance & Royal Patronage', 'The thrilling three-day martial dance festival showcasing the unique, maskless Mayurbhanj Chhau dance under the royal patronage of the Bhanja dynasty.', 'Centuries-old royal martial dance tradition nurtured by the Bhanja kings of Mayurbhanj inside the historic Baripada palace grounds.', 'Celebrates the martial valor, agility, and chivalric culture of the warrior clans (Paikas) of northern Odisha.', 'To preserve the unmasked Mayurbhanj Chhau tradition and celebrate the annual Chaitra Parva spring festival.', 'Unlike Purulia and Seraikela Chhau which use masks, Mayurbhanj Chhau dancers do not wear masks, using facial expressions and acrobatic martial footwork.', 'Features the historic rivalry between the two premier royal dancing academies: the Uttar Sahi and Dakshin Sahi troupes.', ARRAY['Ceremonial flag hoisting and royal invocation at the Baripada Palace grounds', 'Competitive martial dance presentations depicting episodes from Ramayana and Mahabharata', 'High-leaping acrobatic combat routines (Chali and Upalaya) with swords and shields']::TEXT[], 'Thousands of spectators cheer as athletic warrior dancers perform breathtaking 360-degree aerial leaps and sword-fighting sequences.', ARRAY['Mudhi Mansa (Baripada''s iconic dish: puffed rice served with mutton gravy)', 'Chhena Poda', 'Arisa Pitha', 'Kakara Pitha']::TEXT[], 'Dazzling Chhau martial costumes: bright satin dhotis, embroidered velvet waistcoats, and metallic jewelry.', 'Thundering, high-energy rhythm of giant Dhol, Dhumsa drums, and wailing Mohuri reed horns.', 'Baripada royal palace facade, shining swords and shields, and high-flying martial leaps.', '3 Days', 'Solar / Chaitra Parva', 'April 11 to 13 annually (concluding on Pana Sankranti).', 'April', 'FIXED', 'Held annually April 11-13.', '2026-04-11', '2027-04-11', 'Mayurbhanj Chhau Nrutya Pratishthan & Odisha Tourism', ARRAY['Odisha']::TEXT[], ARRAY['Baripada', 'Mayurbhanj']::TEXT[], ARRAY['Baripada Stadium / Royal Palace Grounds']::TEXT[], 'Nightly performances between 7 PM and 11 PM when competitive troupe battles unfold', 2, 'Electrifying adrenaline rush: jaw-dropping acrobatic leaps, thundering tribal drums, and pure, raw martial artistry in a royal princely town.', 'Baripada is connected by train from Balasore and Bhubaneswar; 250 km north of Bhubaneswar via highway.', 'Hotels in Baripada town or eco-resorts in nearby Similipal Tiger Reserve.', 'Warm April evenings; stadium seating available.', 'Savor the legendary local specialty ''Mudhi Mansa'' at authentic local eateries in Baripada.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mayurbhanj.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-taratarini-mela', 'Taratarini Mela Ganjam', ARRAY['Chaitra Yatra Maa Tara Tarini']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism / Ancient Tantric Peeth)', 'The massive hill pilgrimage fair held on the sacred Purnagiri Hill overlooking the Rushikulya River, honoring the twin goddess sisters Tara and Tarini.', 'Ancient Shakti Peeth dating back over 2,000 years, revered as the Sthana Peeth (breast shrine) of Goddess Sati; ancient patron deity of Kalinga seafarers.', 'Celebrates the twin goddesses Tara and Tarini as protective mother deities and masters of navigation and healing.', 'To climb the 999 stone steps to the hill temple, tonsure the heads of young children (Mundan), and seek maternal blessings.', 'Draws over two million pilgrims from southern Odisha and northern Andhra Pradesh during the holy month of Chaitra.', 'Pilgrims perform the traditional tonsure ritual of shaving infants'' hair on the scenic banks of the Rushikulya River before climbing the hill.', ARRAY['First haircut and tonsure ritual (Mundan) of infants on the Rushikulya riverbanks', 'Climbing the 999 stone steps (or taking the aerial ropeway) to the hilltop temple sanctum', 'Offering sweet Chhena Kheeri and coconut to the twin stone idols of Tara and Tarini']::TEXT[], 'Thousands of families climb the steep hill stairs, singing devotional songs and carrying toddlers, while the hilltop offers panoramic views of the curving river.', ARRAY['Kheeri (sweet rice pudding)', 'Puri with Chana Dal', 'Kachori', 'Ganjam Peda', 'Sattu Sharbat']::TEXT[], 'Traditional cotton dhotis, kurtas, and colorful Berhampuri Patta silk sarees.', 'Soulful devotional Bhajans, temple conch shells, and folk drumming with Dholak and Ghanta.', '999 hilltop stone steps, ancient twin stone idols with gold eyes, and curving Rushikulya River valley.', '4 Tuesdays of Chaitra Month', 'Hindu Lunisolar / Spring', 'Celebrated on all four Tuesdays (Mangalbars) of Chaitra month (March - April).', 'March - April', 'LUNISOLAR', 'Held on all Tuesdays of Chaitra month.', '2026-03-24', '2027-04-13', 'Maa Tara Tarini Temple Trust & Ganjam Administration', ARRAY['Odisha']::TEXT[], ARRAY['Purushottampur', 'Berhampur', 'Ganjam']::TEXT[], ARRAY['Tara Tarini Hilltop Temple Complex']::TEXT[], 'Early morning hours (5 AM to 10 AM) on Chaitra Tuesdays to avoid afternoon hill heat', 2, 'Deep rural Shakta devotion, breathtaking hill panoramas over lush coastal plains, and the joyful celebration of childhood milestones.', '30 km from Berhampur railway station; easily reached by highway buses, private taxis, and auto-rickshaws.', 'Pilgrim dharamshalas at the base of the hill; comfortable hotels in Berhampur city.', 'Climbing 999 steps can be strenuous in summer; an aerial ropeway and motorable road are also available.', 'Very crowded on Chaitra Tuesdays; follow queue lines at the sanctum; stay hydrated.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ganjam.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-shital-sasthi-sambalpur', 'Shital Sasthi Sambalpur', ARRAY['Divine Wedding of Shiva and Parvati']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Folk Marriage Carnival)', 'The grand week-long carnival celebrating the divine marriage of Lord Shiva and Devi Parvati, where human families adopt the deities as their own children.', 'Centuries-old festival unique to Sambalpur, initiated around 1600 CE to celebrate the cooling showers that bring relief from the fierce summer heat.', 'Commemorates the celestial wedding of Lord Shiva and Goddess Parvati, marking the arrival of the monsoon.', 'To celebrate divine domesticity, family love, and the cooling of the earth from summer heat (Shital means cool).', 'Unique social custom: two prominent citizen families of Sambalpur are chosen to act as the human parents of Shiva and Parvati, performing all wedding and dowry rites.', 'Concludes with an epic nightlong street carnival where hundreds of thousands of costumed dancers, acrobats, and illuminated floats parade past dawn.', ARRAY['Patra Pendi: formal adoption of Goddess Parvati by a human family who conducts all bridal rites', 'Grand Barat wedding procession of Lord Shiva riding a decorated bull with demons and gods', 'All-night street carnival with thousands of folk artists dancing down Sambalpur avenues']::TEXT[], 'The entire city of Sambalpur stays awake all night, lining the streets with cheering families as hundreds of folk troupes and brass bands parade past.', ARRAY['Chaul Bara', 'Sambalpuri Rasgulla', 'Puri with Dalma', 'Kheer', 'Tanka Torani']::TEXT[], 'Traditional Sambalpuri handloom Ikat sarees, dhotis with Sambalpuri borders, and colorful festive wear.', 'High-voltage Sambalpuri folk percussion: Dhol, Nishan, Tasha, and vibrant Dalkhai group dances.', 'Decorated wooden marriage chariots, divine wedding thrones, and colorful street illuminations.', '5 Days', 'Hindu Lunisolar / Summer', 'Jyeshtha Shukla Panchami and Shashti (May - June)', 'May - June', 'LUNISOLAR', 'Celebrated on Jyeshtha Shukla Shashti.', '2026-06-20', '2027-06-10', 'Sambalpur Shital Sasthi Jatra Samiti & District Administration', ARRAY['Odisha']::TEXT[], ARRAY['Sambalpur']::TEXT[], ARRAY['Balunkeswar Temple Nandapada', 'Loknath Temple', 'Sambalpur Main Avenue']::TEXT[], 'Night of the grand Shobha Yatra (wedding street carnival) from 10 PM to 6 AM', 2, 'Electrifying, nightlong urban street carnival of boundless joy, thundering Sambalpuri rhythms, and the charming blurring of human and divine relationships.', 'Sambalpur is well connected by rail and highway; easily accessible by local transport.', 'Hotels throughout Sambalpur city; book well ahead for Shital Sasthi week.', 'All-night event; streets are completely packed; wear comfortable walking shoes.', 'Accept the blessed wedding feast offerings with joy; celebrate respectfully alongside local families.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sambalpur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-joranda-mela-dhenkanal', 'Joranda Mela Dhenkanal', ARRAY['Mahima Mela Dhenkanal']::TEXT[], 'Spiritual & Temple', 'Mahima Dharma / Casteless Monastic Faith', 'The unique ascetic festival of the indigenous Mahima Dharma monastic order, where ochre-robed monks make offerings into a perpetual sacred fire without idol worship.', 'Founded in 1874 CE by Mahima Gosain, a revolutionary religious reformer who preached a monotheistic, casteless faith worshipping the unmanifest supreme truth (Alekh).', 'Celebrates the surrender to the formless, unmanifest supreme reality (Alekh Brahma) and the brotherhood of all living beings.', 'To pray for universal peace (Jagat Kalyan) and liberation from caste discrimination and ritual hypocrisy.', 'Completely distinct from orthodox Hinduism: strictly no idols, temples, or priests; monks wear bark from the Kumbhi tree (Balkaladhari) or saffron loincloths (Kaupindhari).', 'Centered around the massive Sunya Mandir (Temple of the Void) and the Akhanda Dhuni (perpetual sacred fire pit) burning with pure ghee.', ARRAY['Lighting and offering of hundreds of kilograms of pure cow ghee into the Akhanda Dhuni (eternal sacred fire)', 'Prostration (Sharan Darshan) by hundreds of ascetic monks facing the four cardinal directions at dawn and dusk', 'Chanting of the universal peace prayer: ''Let my soul be damned to hell, but let the universe be saved''']::TEXT[], 'Thousands of monks in tree-bark robes bow in synchronized prostration before the roaring sacred fire, chanting ''Brahma Alekh'' beneath the full moon.', ARRAY['Simple community vegetarian prasad', 'Poha', 'Fruits', 'Ghee Khichdi']::TEXT[], 'Tree-bark robes (Kumbhi tree bark) for Balkaladhari monks; simple saffron loincloths for Kaupindhari monks; pilgrims wear white cotton.', 'Resonant, hypnotic chanting of ''Alekh Brahma, Niranjana'', accompanied by blowing of brass trumpets and small gongs.', 'Sunya Mandir (Temple of the Void) with golden kalash, leaping flames of the Akhanda Dhuni, and full moon sky.', '3 Days', 'Hindu Lunisolar', 'Magha Purnima (full moon night of Magha month in February)', 'February', 'LUNISOLAR', 'Culminates on Magha Purnima.', '2026-02-01', '2027-02-20', 'Mahima Gadi Trust & Dhenkanal District Administration', ARRAY['Odisha']::TEXT[], ARRAY['Joranda', 'Dhenkanal']::TEXT[], ARRAY['Mahima Gadi Sunya Mandir Complex Joranda']::TEXT[], 'Magha Purnima sunset and midnight when the Akhanda Dhuni fire offerings reach peak intensity', 2, 'Profound, deeply moving spiritual austerity: observing hundreds of tree-bark-clad ascetic monks bowing before leaping flames under a brilliant full moon.', '25 km from Dhenkanal railway station; 90 km northwest of Bhubaneswar; accessible by taxi.', 'Simple pilgrim rest houses in Joranda or hotels in Dhenkanal town.', 'Cool February nights; carry a warm shawl.', 'Strict monastic rules: no leather items permitted near the sacred Gadi; maintain deep silence and modesty.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://dhenkanal.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-durga-puja-kolkata', 'Kolkata Durga Puja', ARRAY['Sharadotsav Kolkata', 'Durgotsav']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & Community Art)', 'The world''s largest public art festival and supreme cultural carnival, where over 3,000 monumental thematic art pandals transform Kolkata into an open-air museum.', 'Celebrated since the late 16th century by Bengal Zamindars (Sabarna Roy Choudhury family in 1610), transformed into a democratic public art movement (Barowari) in the 20th century.', 'Commemorates the triumph of Goddess Durga over the buffalo demon Mahishasura, symbolizing the victory of cosmic good over oppression.', 'To welcome Goddess Durga as the beloved daughter (Uma) returning to her maternal home for four blissful days of celebration.', 'Inscribed on UNESCO''s Representative List of the Intangible Cultural Heritage of Humanity in 2021.', 'Renowned for its staggering architectural and sculptural innovation: pandals replicate the Louvre, ancient Mayan temples, or present poignant socio-political themes.', ARRAY['Bodhan ritual invoking the Goddess into a sacred bel tree branch on Shashthi', 'Pushpanjali flower offerings with fasting devotees reciting Sanskrit stotrams on Ashtami morning', 'Sindoor Khela where married women smear vermilion on each other before tearful water immersion (Bisarjan)']::TEXT[], 'Millions of people wander through day and night, hopping from pandal to pandal, eating street food, and cheering the thundering beats of the Dhak drums.', ARRAY['Kolkata Biryani', 'Kathi Rolls', 'Fish Fry', 'Kosha Mangsho with Luchi', 'Mishti Doi and Sandesh', 'Pujor Bhog (Khichuri, Labra, Payesh)']::TEXT[], 'Dazzling festive wear: red-and-white Dhakai Jamdani and Baluchari silk sarees for women; silk Kurtas with Dhuti for men.', 'Thundering, high-energy beats of the giant double-sided Dhak drums, accompanied by ecstatic Dhunuchi Naach (fire-pot dance).', 'Sculpted clay idol of ten-armed Goddess Durga, burning coconut-husk Dhunuchi censers, Shiuli flowers, and white Kaash grass plumes.', '5 Days', 'Hindu Lunisolar', 'Ashwin Shukla Shashthi to Dashami (October)', 'October', 'LUNISOLAR', 'Begins on Maha Shashthi and culminates on Vijyadashami.', '2026-10-16', '2027-10-06', 'Kolkata Municipal Corporation & Department of Tourism West Bengal', ARRAY['West Bengal']::TEXT[], ARRAY['Kolkata', 'Howrah']::TEXT[], ARRAY['Bagbazar Sarbojanin', 'Maddox Square', 'Ekdalia Evergreen', 'Suruchi Sangha']::TEXT[], 'Maha Saptami and Maha Ashtami nights (8 PM to 4 AM) for all-night pandal hopping', 4, 'Overwhelming, euphoric cultural masterpiece: an entire megacity pulsing with art, beauty, thundering drums, delicious food, and unmatched warmth.', 'Kolkata Metro runs 24 hours during Puja nights; yellow taxis, app cabs, and local suburban trains connect the city.', 'Hotels throughout Kolkata; reserve 4-6 months in advance as international travelers arrive in tens of thousands.', 'Monumental crowds on streets; wear comfortable walking shoes; use the Kolkata Police Durga Puja Guide Map app.', 'Respect the artistic sanctity of the pandals; accept the sacred Pujor Bhog with devotion.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://wbtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-poush-mela-shantiniketan', 'Poush Mela Shantiniketan', ARRAY['Tagore Winter Cultural Fair']::TEXT[], 'Fair & Mela', 'Brahmo Samaj & Baul Mystic Heritage', 'The soul-stirring winter fair celebrating the foundation of Shantiniketan, where wandering Baul mystic singers, tribal dancers, and rural artisans gather.', 'Initiated in 1894 by Maharshi Debendranath Tagore (father of Rabindranath Tagore) to mark his acceptance of the Brahmo faith and celebrate rural arts.', 'Celebrates the rural soul of Bengal, the spiritual philosophy of universal humanism, and the harvest of the winter Poush crop.', 'To foster direct cultural and economic exchange between university intellectuals, wandering Baul minstrels, and rural Santhal villagers.', 'Staged on the red soil grounds of Visva-Bharati University, echoing with the haunting melodies of the Ektara and Dotara.', 'Features the immortal tradition of Baul music, recognized by UNESCO as an Intangible Cultural Heritage of Humanity.', ARRAY['Dawn prayer service (Upasana) at the historic stained-glass Glass Mandir (Upasana Griha)', 'Nightlong Baul musical sessions in open-air tents under the starry winter sky', 'Exhibition and sale of authentic Kantha embroidery, Dokra brass castings, and terracotta pottery']::TEXT[], 'Thousands of visitors sit on the red laterite soil in open-air circles, listening to wandering Bauls sing of divine love, and shopping for handicrafts.', ARRAY['Pithe-Puli (traditional Bengali winter rice crepes with jaggery and coconut)', 'Patishapta', 'Joynagarer Moa', 'Chhanar Jilapi', 'Khichuri']::TEXT[], 'Earthy handloom cotton kurtas, Santhal tribal handwoven sarees, Kantha-embroidered shawls, and leather Shantiniketan bags.', 'Soul-stirring Baul and Fakir songs with Ektara, Dubki, and Dotara, accompanied by Santhal tribal dance to Madol drums.', 'Red laterite soil of Khoai, stained glass Upasana Griha, Ektara instruments, and Kantha embroidered motifs.', '3 to 6 Days', 'Bengali Solar Calendar', 'Starts on the 7th day of the Bengali month of Poush (around December 23).', 'December', 'FIXED', 'Commences December 23 annually.', '2026-12-23', '2027-12-23', 'Visva-Bharati University & Shantiniketan Trust', ARRAY['West Bengal']::TEXT[], ARRAY['Shantiniketan', 'Bolpur', 'Birbhum']::TEXT[], ARRAY['Poush Mela Ground Shantiniketan', 'Khoai Kopai Riverbanks']::TEXT[], 'Dawn service at the Glass Temple and evening Baul music circles under the trees', 2, 'Deeply romantic, poetic pastoral magic: wandering through red earth groves under cool winter skies, serenaded by the immortal songs of mystic minstrels.', 'Bolpur Shantiniketan railway station (2 hours by express train from Howrah/Kolkata); easily traversed by battery toto-rickshaws.', 'Boutique heritage homestays, eco-resorts, and hotels across Bolpur and Shantiniketan; early booking essential.', 'Cool, pleasant December days; chilly evenings; carry a warm shawl.', 'Support indigenous rural artisans by purchasing certified handloom Kantha embroidery directly from village women.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://visvabharati.ac.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-gangasagar-mela', 'Gangasagar Mela Sagar Island', ARRAY['Makar Sankranti Sagar Confluence']::TEXT[], 'Spiritual & Temple', 'Hinduism (Puranic Confluence & Kapil Muni)', 'The second largest congregation of humanity in India after the Kumbh Mela, where millions take the holy dawn dip where the sacred Ganga merges into the Bay of Bengal.', 'Celebrated since ancient epic times, commemorated by the ancient proverb: ''Sab Teerth Baar Baar, Gangasagar Ek Baar'' (All pilgrimages many times, but Gangasagar once in a lifetime).', 'Celebrates the mythical descent of the Ganga brought by Bhagiratha to liberate the 60,000 cursed sons of King Sagara at the hermitage of Sage Kapil.', 'To take the holy cleansing dip at the sacred confluence (Ganga-Sagar Sangam) at dawn on Makar Sankranti and seek spiritual liberation.', 'Draws over five million pilgrims, Naga sadhus, ascetics, and householders from every corner of India to the remote southern tip of Sagar Island.', 'Pilgrims complete their sacred journey by praying at the white marble temple of Sage Kapil Muni standing on the seashore.', ARRAY['Taking the holy cleansing dip in the icy sea-river confluence at dawn on Makar Sankranti', 'Offering coconuts and prayers at the ancient Kapil Muni Temple', 'Spiritual discourses and continuous distribution of hot meals at thousands of community camps']::TEXT[], 'The vast sandy seashore turns into a sprawling canvas of human faith, with millions shivering in the dawn mist, chanting ''Jai Ganga Maiya, Jai Kapil Muni''.', ARRAY['Chuda Dahi with new Nolen Gur (date palm jaggery)', 'Khichuri Bhog', 'Puri Sabzi', 'Joynagarer Moa', 'Hot Tea']::TEXT[], 'Simple saffron and white cotton dhotis, ascetic robes, wool shawls, and modest pilgrim attire.', 'Continuous chanting of Vedic mantras, ringing of brass bells, conch shell blasts, and traditional devotional kirtan.', 'Vast ocean confluence where Ganga meets the Bay of Bengal, Kapil Muni temple spire, and red triangular flags.', '5 Days', 'Solar / Makar Sankranti', 'Makar Sankranti (January 13 to 15 annually).', 'January', 'FIXED', 'Culminates on Makar Sankranti dawn (January 14-15).', '2026-01-14', '2027-01-14', 'South 24 Parganas District Administration & West Bengal Tourism', ARRAY['West Bengal']::TEXT[], ARRAY['Sagar Island', 'Kakdwip', 'Kolkata']::TEXT[], ARRAY['Gangasagar Beach Sangam', 'Kapil Muni Temple']::TEXT[], 'Dawn of Makar Sankranti (January 14) for the sacred holy bath at the ocean confluence', 3, 'Awe-inspiring, humbling epic pilgrimage: witnessing millions of devout souls brave winter winds and complex river crossings in a collective quest for salvation.', '130 km south of Kolkata; requires traveling by road/train to Kakdwip (Harwood Point), crossing the Muriganga River by ferry to Kachuberia, and taking buses to the beach.', 'Massive tented pilgrim cities set up by the administration; limited permanent hotels.', 'Massive crowds; tidal ferry crossings require patience; stay within marked safe bathing zones along the coast.', 'Wear warm clothes for foggy winter mornings; keep emergency contact numbers and identification cards on person.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sagar.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-basanta-utsav-shantiniketan', 'Basanta Utsav Shantiniketan', ARRAY['Tagore Spring Festival', 'Holi Shantiniketan']::TEXT[], 'Art & Cultural Festival', 'Rabindranath Tagore Heritage & Spring Harmony', 'The graceful, poetic celebration of spring introduced by Nobel laureate Rabindranath Tagore, where students and visitors dance in yellow attire to Tagore''s songs.', 'Initiated in the 1920s by Rabindranath Tagore at Visva-Bharati University to replace boisterous Holi with an aesthetic celebration of nature''s rebirth.', 'Celebrates the arrival of spring (Basanta), the blossoming of red Palash flowers, and universal artistic harmony.', 'To welcome spring with music, graceful dance, poetry, and the gentle smearing of dry herbal perfumed powder (Abir).', 'A cultural icon of Bengal, where thousands of women dress in yellow Basanti sarees with red Palash flowers in their hair, dancing in unison.', 'Staged on the open grounds of Visva-Bharati, opening with the immortal musical dance drama ''Ore Grihobasi, Khol Darr Khol'' (O house-dweller, open your doors).', ARRAY['Morning musical procession (Prabhat Pheri) with students singing Tagore songs', 'Grand open-air dance performance to Rabindrasangeet in the university amphitheatre', 'Gentle smearing of dry herbal perfumed Abir powder on feet of elders and cheeks of friends']::TEXT[], 'The entire town turns into a sea of bright yellow and red, filled with laughter, spontaneous dancing under flowering trees, and poetic joy.', ARRAY['Bengali sweets: Sandesh, Malpua', 'Basanti Pulao', 'Luchi with Alur Dom', 'Thandai']::TEXT[], 'Bright yellow (Basanti) cotton and silk sarees with red borders and fresh Palash blossoms in hair; yellow kurtas with white dhotis for men.', 'Sublime Rabindrasangeet (songs of Tagore) sung in chorus, accompanied by Esraj string instruments, harmonium, and gentle clay drums.', 'Flaming red Palash blossoms (Butea monosperma), yellow Basanti sarees, heaps of fragrant Abir powder, and open university groves.', '1 Day', 'Hindu Lunisolar / Spring', 'Phalguna Purnima (Holi day in March)', 'March', 'LUNISOLAR', 'Celebrated on the day of Holi (Phalguna Purnima).', '2026-03-03', '2027-03-22', 'Visva-Bharati University & Shantiniketan Administration', ARRAY['West Bengal']::TEXT[], ARRAY['Shantiniketan', 'Bolpur']::TEXT[], ARRAY['Ashram Grounds Visva-Bharati', 'Gour Prangan']::TEXT[], 'Early morning from 7 AM to 11 AM during the opening musical procession and dance ballets', 1, 'Unrivaled poetic grace and gentle springtime romance: singing under blooming forest trees, enveloped in fragrant clouds of dry pink abir.', 'Bolpur railway station (2 hours from Howrah/Sealdah by express train); local electric toto-rickshaws.', 'Hotels and homestays across Bolpur and Shantiniketan; book 3-4 months in advance as tourist influx is immense.', 'Very heavy crowds; only dry natural herbal Abir powder is permitted; use of chemical or liquid colors is strictly forbidden.', 'Treat the academic campus and teachers with high respect; avoid boisterous or disruptive behavior.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://visvabharati.ac.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rash-mela-coochbehar', 'Rash Mela Cooch Behar', ARRAY['North Bengal Historic Carousel Fair']::TEXT[], 'Historical & Royal', 'Hinduism & Cooch Behar Royal Heritage', 'The oldest and grandest historical festival of North Bengal, celebrated around the 200-year-old Madan Mohan Temple with a towering rotating paper carousel.', 'Initiated in 1812 CE by Maharaja Harendra Narayan of the princely Koch dynasty of Cooch Behar.', 'Celebrates the divine Raaslila dance of Lord Krishna with the Gopis and the royal heritage of the Koch kingdom.', 'To honor Lord Madan Mohan (patron deity of the Cooch Behar royal family) and foster regional unity between North Bengal and Assam.', 'The centerpiece is the colossal multi-tiered rotating paper carousel (Rash Chakra) crafted by a traditional Muslim artisan family for over a century.', 'The Maharaja of Cooch Behar (or state representative) ceremonially spins the giant Rash Chakra at midnight to inaugurate the month-long fair.', ARRAY['Midnight spinning of the monumental multi-tiered paper Rash Chakra by royal representatives', 'Special Raaslila darshan at the historic red-domed Madan Mohan Temple', 'Month-long trade fair drawing merchants and artisans from West Bengal, Assam, and Bhutan']::TEXT[], 'Lakhs of pilgrims throng the temple square to spin the sacred paper carousel, praying for good fortune before enjoying the vast carnival.', ARRAY['Bhadbhadia (famous crispy sweet snack of Cooch Behar)', 'Jalebi', 'Luchi with Cholar Dal', 'Rasgulla', 'Tibetan Momos']::TEXT[], 'Traditional Bengali dhoti-kurtas and sarees alongside indigenous Koch-Rajbongshi handloom wraps (Patani).', 'Bhawaiya folk songs of North Bengal with Dotara, traditional Kirtan chanting, and classical music.', 'Monumental rotating multi-tiered paper Rash Chakra, red-brick domes of Madan Mohan Temple, and Cooch Behar Royal Palace.', '15 to 20 Days', 'Hindu Lunisolar', 'Begins on Kartik Purnima (full moon of November)', 'November', 'LUNISOLAR', 'Begins on Kartik Purnima night.', '2026-11-24', '2027-11-13', 'Cooch Behar Debutter Trust & District Administration', ARRAY['West Bengal']::TEXT[], ARRAY['Cooch Behar']::TEXT[], ARRAY['Madan Mohan Temple Grounds Cooch Behar', 'Rash Mela Maidan']::TEXT[], 'Kartik Purnima midnight for the ceremonial spinning of the Rash Chakra and opening prayers', 2, 'Fascinating princely charm, inter-faith craft synthesis, cool North Bengal winter breezes, and the mesmerizing sight of the giant rotating paper carousel.', 'Cooch Behar Airport connects to Kolkata; well connected by New Cooch Behar railway junction.', 'Hotels and guest houses in Cooch Behar town.', 'Massive opening night crowds around the temple; follow police queue systems.', 'Spin the sacred Rash Chakra with quiet reverence; explore the adjacent European-style Cooch Behar Palace.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://coochbehar.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jagaddhatri-puja-chandannagar', 'Jagaddhatri Puja Chandannagar', ARRAY['Chandannagar Festival of Lights']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & World-Famous Light Art)', 'The world-renowned four-day festival celebrating Goddess Jagaddhatri (Holder of the Universe), famous for colossal illuminated 3D moving light gates.', 'Initiated in the 18th century by Indranarayan Choudhury, the wealthy Dewan of the French East India Company at Chandannagar.', 'Celebrates Goddess Jagaddhatri, a tranquil four-armed lion-riding form of Goddess Durga, holding the conch, bow, arrow, and chakra.', 'To honor the Mother Goddess who sustains and holds the cosmos together, and showcase Chandannagar''s peerless LED light engineering.', 'Chandannagar is globally famous as the birthplace of automated decorative lighting; its master electricians create colossal animated light gates.', 'Concludes with an epic all-night immersion procession (Bhashan) stretching for 4 km along the historic French Strand on the Hooghly River.', ARRAY['Prana Pratishtha of monumental 30-foot tall straw and clay idols of Goddess Jagaddhatri', 'Exhibition of breathtaking automated moving light gates portraying epics, current affairs, and global landmarks', 'All-night immersion procession along the French colonial Strand promenade with hundreds of illuminated floats']::TEXT[], 'Over two million spectators stroll along the historic tree-lined French boulevard, gazing up at 60-foot tall glowing illuminated gateways.', ARRAY['Jalbhara Sandesh (Chandannagar''s iconic sweet: GI Tagged)', 'Kathi Rolls', 'Fish Fry', 'Biryani', 'Luchi with Alur Dom']::TEXT[], 'Traditional festive silk sarees, stylish modern ethnic wear, and comfortable walking casuals.', 'Thundering Dhak drumming, synchronized brass band marches, and classical Shehnai recitals.', '30-foot glowing idol of Goddess Jagaddhatri on lion, colossal moving LED light gates, and French colonial Strand boulevard.', '4 Days', 'Hindu Lunisolar', 'Kartik Shukla Saptami to Dashami (November)', 'November', 'LUNISOLAR', 'Celebrated approx one month after Durga Puja.', '2026-11-18', '2027-11-07', 'Chandannagar Jagaddhatri Puja Central Committee & Police', ARRAY['West Bengal']::TEXT[], ARRAY['Chandannagar', 'Bhadreswar', 'Hooghly']::TEXT[], ARRAY['Strand Promenade Chandannagar', 'Fatokgora', 'Bara Bazar']::TEXT[], 'Navami night for illuminated light gates and Dashami night for the 24-hour immersion parade', 2, 'Dazzling, mind-boggling electrical and artistic wonder: giant moving light arches that turn a historic French colonial river town into a glowing dreamscape.', '35 km north of Kolkata; 45 minutes by suburban local train from Howrah Station to Chandannagar station.', 'Hotels in Chandannagar or stay in Kolkata and visit via evening local train.', 'Massive pedestrian crowds along the Strand promenade; vehicle traffic is completely restricted.', 'Taste the legendary GI-tagged ''Jalbhara Sandesh'' from historic confectionery Surya Kumar Modak.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://hooghly.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kali-puja-kolkata', 'Kali Puja & Diwali Kolkata', ARRAY['Shyama Puja']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism / Tantric Heritage)', 'The intense, luminous midnight festival worshipping the fierce Mother Goddess Kali with thousands of oil lamps, fireworks, and tantric midnight rituals.', 'Deeply rooted in Bengal Shakta traditions, popularized in the 18th century by Raja Krishnachandra of Nadia and mystic saint Ramprasad Sen.', 'Commemorates Goddess Kali stepping on Lord Shiva''s chest to halt her cosmic dance of destruction after annihilating demons.', 'To seek divine protection from negativity, conquer ego and fear of death, and invoke the compassionate maternal grace of Ma Kali.', 'Coincides with pan-Indian Diwali: while northern India worships Lakshmi, Bengal worships Goddess Kali as the supreme protective mother.', 'Centered around the historic Shakti Peeth of Kalighat, the 19th-century Dakshineswar Kali Temple of Sri Ramakrishna, and Barasat pandals.', ARRAY['Midnight Tantric Puja with offerings of red hibiscus flowers, sweets, and ceremonial prasad', 'Lighting of thousands of earthen diyas (Pradip) outside every household on the new moon night', 'Grand darshan at Dakshineswar Temple where Sri Ramakrishna Paramahamsa meditated']::TEXT[], 'Kolkata is drenched in brilliant fireworks, illuminated with clay lamps, while devotees wait in nightlong queues at temple shrines.', ARRAY['Mutton Curry (traditionally offered as prasad in Shakta households)', 'Khichuri Bhog', 'Luchi', 'Sandesh', 'Boondi Ladoo']::TEXT[], 'Traditional silk sarees with red borders, dhotis, kurtas, and festive Indian ethnic wear.', 'Soulful Shyama Sangeet (devotional hymns to Kali) by Ramprasad Sen and Kazi Nazrul Islam, conch shells, and thundering Dhak drums.', 'Fierce black stone idol of Kali with protruding red tongue, garlands of 108 red hibiscus flowers, and clay lamps.', '1 Night (Festivities for 3 Days)', 'Hindu Lunisolar', 'Kartik Amavasya (new moon night of Kartik month in October - November)', 'October - November', 'LUNISOLAR', 'Celebrated on Diwali night (Kartik Amavasya).', '2026-11-08', '2027-10-29', 'Kalighat Temple Committee & Dakshineswar Kali Temple Trust', ARRAY['West Bengal']::TEXT[], ARRAY['Kolkata', 'Barasat', 'Dakshineswar']::TEXT[], ARRAY['Kalighat Kali Temple', 'Dakshineswar Kali Temple', 'Barasat Pandals']::TEXT[], 'Midnight (11 PM to 2 AM) on Diwali night for the sacred tantric Kali Puja', 2, 'Intense, awe-inspiring spiritual energy: fiery red hibiscus garlands, glowing clay lamps, soul-stirring hymns, and the loving power of the Divine Mother.', 'Kolkata Metro connects directly to Kalighat and Dakshineswar stations; taxis operating 24 hours.', 'Extensive hotels across Kolkata.', 'Very crowded around Kalighat and Dakshineswar temples; arrive early for darshan; fireworks require safety caution.', 'Maintain deep spiritual silence during midnight tantric mantras; accept the blessed prasad with reverence.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://wbtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-saraswati-puja-kolkata', 'Saraswati Puja Kolkata', ARRAY['Basant Panchami Bengal', 'Bengal''s Valentine''s Day']::TEXT[], 'Spiritual & Temple', 'Hinduism (Goddess of Learning & Youth)', 'The joyful spring festival celebrating Goddess Saraswati, patron of learning, arts, and music, famously celebrated as ''Bengal''s Valentine''s Day'' by youth.', 'Ancient Vedic festival dedicated to Saraswati, patron goddess of wisdom, speech, music, and learning.', 'Celebrates the arrival of spring (Basant Panchami) and the divine power of intellect, literature, and fine arts.', 'To worship books, musical instruments, and pens, seeking blessings for academic and creative excellence.', 'Celebrated with universal joy across every school, college, university, and neighborhood club in Bengal.', 'Known as Bengal''s Valentine''s Day: young boys and girls dress in bright yellow traditional attire, wandering hand-in-hand through city parks and museums.', ARRAY['Hatey Khori ceremony where toddlers write their very first letters of the alphabet on slate', 'Placing textbooks, notebooks, and musical instruments before the Goddess for blessings (no studying allowed on this day)', 'Pushpanjali flower offerings to the white swan-riding Goddess of Wisdom']::TEXT[], 'Kolkata streets are filled with laughing students in yellow sarees and kurtas, eating Khichuri bhog in schools and visiting cultural hubs.', ARRAY['Khichuri Bhog with Labra (mixed vegetable curry) and Beguni (eggplant fritters)', 'Topa Kuler Chutney (wild berry chutney)', 'Boondi', 'Sandesh']::TEXT[], 'Bright yellow (Basanti) cotton and silk sarees for girls; yellow and white Kurta-Pajamas for boys.', 'Classical Shehnai music, Rabindrasangeet, student cultural concerts, and acoustic guitar songs.', 'White marble or clay idol of Saraswati holding Veena, sacred books, white swan (Hamsa), and yellow marigold garlands.', '1 Day', 'Hindu Lunisolar', 'Magha Shukla Panchami (January - February)', 'January - February', 'LUNISOLAR', 'Celebrated on Magha Shukla Panchami.', '2026-01-23', '2027-02-11', 'Kolkata Schools, Colleges & Cultural Associations', ARRAY['West Bengal']::TEXT[], ARRAY['Kolkata', 'Howrah', 'Siliguri', 'Burdwan']::TEXT[], ARRAY['College Street', 'Presidency University', 'Jadavpur University', 'Victoria Memorial']::TEXT[], 'Morning between 9 AM and 1 PM for school ceremonies, followed by afternoon strolling at Victoria Memorial', 1, 'Joyful, innocent youthful charm: a city draped in yellow sunshine, books honored with flowers, and young love blooming in spring gardens.', 'Kolkata Metro and public buses easily connect all educational campuses and heritage parks.', 'Hotels throughout Kolkata.', 'Pleasant sunny winter weather; ideal for walking along College Street book markets.', 'It is traditional custom not to read or write after the morning puja; enjoy the leisure and culture.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://wbtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-charak-puja-bengal', 'Charak Puja & Gajan', ARRAY['Shiva Gajan Bengal']::TEXT[], 'Tribal & Folk Traditions', 'Folk Shaivism & Extreme Ascetic Penance', 'The ancient folk festival celebrating the close of the Bengali year, famous for astonishing feats of ascetic endurance, hook-swinging, and body-piercing.', 'Centuries-old folk tradition rooted in pre-Aryan tantric and agrarian fertility rites, dedicated to Lord Shiva and Goddess Nilavati.', 'Celebrates the passage of the old solar year (Chaitra Sankranti) and the fertility renewal of the soil for the coming year.', 'To undergo voluntary physical penance to expiate sins, propitiate Lord Shiva, and ensure good rains and health.', 'Devotees (Sanyasis or Gajanis) fast for a month, culminating on Chaitra Sankranti with the dramatic ''Charak Tree'' swinging ceremony.', 'A tall straight wooden pole (Charak Tree) is erected in village grounds; devotees suspended by ropes swing high above the crowd.', ARRAY['Barefoot dancing on beds of burning charcoal and thorny branches', 'Piercing of tongues, arms, and backs with iron rods and hooks without bleeding', 'Charak tree swinging: devotees suspended from a rotating horizontal beam high above the crowd']::TEXT[], 'Thousands of villagers pack dusty rural grounds, playing drums and watching in breathless suspense as devotees swing in high arcs.', ARRAY['Makar Chaul (soaked rice with coconut and jaggery)', 'Fruits', 'Sattvic vegetarian feast', 'Jalebi']::TEXT[], 'Saffron dhotis, sacred red threads across shoulders, Rudraksha beads, and upper bodies smeared with sandalwood.', 'Thunderous, frenzied beats of the Dhak drum, Kanshi cymbals, and roaring chants of ''Bole Baba Par Karega''.', 'Tall wooden Charak tree mast, iron hooks and ropes, burning coal pits, and trishul standards.', '3 Days', 'Bengali Solar Calendar', 'Last three days of the Bengali month of Chaitra (April 12 to 14).', 'April', 'SOLAR', 'Concludes on Chaitra Sankranti (April 13-14).', '2026-04-14', '2027-04-14', 'Gram Panchayats & Gajan Samitis across rural Bengal', ARRAY['West Bengal']::TEXT[], ARRAY['Burdwan', 'Bankura', 'Birbhum', 'Hooghly', 'Kolkata (Kalighat)']::TEXT[], ARRAY['Village grounds across rural Bengal', 'Kalighat Temple Kolkata']::TEXT[], 'Afternoon between 2 PM and 6 PM on Chaitra Sankranti when the Charak swinging takes place', 1, 'Raw, intense, mind-over-matter folk devotion: witnessing ancient rural endurance and spiritual trance untouched by the modern world.', 'Easily witnessed across rural Bengal (Burdwan, Hooghly) or at Kalighat Temple in Kolkata.', 'Hotels in Kolkata or district towns like Burdwan.', 'Warm summer afternoon; intense visual sights of physical piercing; sensitive viewers should exercise discretion.', 'Maintain respectful distance from the Charak rotating mast; respect the solemn vows of the ascetics.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://wbtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kenduli-baul-mela', 'Kenduli Baul Mela Joydev', ARRAY['Joydev Kenduli Mela']::TEXT[], 'Art & Cultural Festival', 'Baul Mysticism & Medieval Bhakti Poetry', 'The legendary pilgrimage fair of wandering Baul and Fakir minstrels held on the sandy banks of the Ajay River at the birthplace of medieval poet Jayadeva.', 'Centuries-old festival held at Joydev Kenduli, birthplace of 12th-century Sanskrit poet Jayadeva, author of the immortal Gita Govinda.', 'Celebrates divine love (Prema), Sufi-Vaishnava mystic philosophy, and the wandering minstrel traditions of Bengal.', 'To honor poet Jayadeva and experience authentic, non-commercial Baul music around rural monastery camps (Akhras).', 'Draws hundreds of saffron-robed Baul and Fakir singers who live in temporary straw Akhras, singing continuously for three days and nights.', 'Famous for the holy dip in the sacred Ajay River at dawn on Makar Sankranti, believed to purify the soul.', ARRAY['Holy bath in the Ajay River on Makar Sankranti dawn', 'Visiting the terracotta-carved 17th-century Radhabinode Temple at Joydev Kenduli', 'Nightlong musical immersion in dozens of rural Baul Akhras, listening to mystic songs of the inner soul']::TEXT[], 'Travelers and seekers sit on straw mats inside thatched-roof tents, listening to master Bauls sing philosophical songs with the single-stringed Ektara.', ARRAY['Khichuri Bhog with Ghee', 'Litti Chokha', 'Joynagarer Moa', 'Chuda Dahi with date palm jaggery', 'Hot Masala Chai']::TEXT[], 'Patchwork saffron robes (Alkhalla) worn by Bauls, turbans, wooden beads, and simple handloom cotton clothes.', 'Hypnotic, transcendental Baul and Fakir music played with Ektara, Dotara, Dubki (tambourine), and ankle bells (Ghungroo).', 'Single-stringed Ektara, terracotta reliefs of Radhabinode temple, sandy Ajay riverbanks, and thatched Akhras.', '3 Days', 'Solar / Makar Sankranti', 'Makar Sankranti (January 14 to 16 annually).', 'January', 'FIXED', 'Commences on Makar Sankranti (January 14).', '2026-01-14', '2027-01-14', 'Birbhum District Administration & Zilla Parishad', ARRAY['West Bengal']::TEXT[], ARRAY['Joydev Kenduli', 'Birbhum', 'Bolpur']::TEXT[], ARRAY['Ajay Riverbanks Joydev Kenduli', 'Radhabinode Temple']::TEXT[], 'Nighttime from 9 PM to 4 AM for the most authentic and soulful Baul musical sessions in the Akhras', 2, 'Transcendental, soulful voyage into the heart of mystical Bengal: warming around bonfires on river sands, listening to timeless songs of love and human freedom.', '35 km from Bolpur Shantiniketan railway station; accessible by taxi or rural shared buses.', 'Basic tents and straw huts in Kenduli or stay in Shantiniketan/Bolpur hotels and visit by taxi.', 'Cold January winter nights on open river sands; carry heavy sleeping bags, woolens, and flashlights.', 'Treat the Bauls and Fakirs with deep respect; listen quietly; contributions to the Akhras are appreciated.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://birbhum.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bishnupur-festival', 'Bishnupur Festival Bankura', ARRAY['Terracotta Temples & Classical Music Fest']::TEXT[], 'Historical & Royal', 'Malla Dynasty Architecture & Classical Bishnupur Gharana', 'A magnificent cultural festival celebrated against the 17th-century terracotta temples and pyramid-roofed Rasmancha of the historic Malla kings.', 'Initiated by the Department of Tourism, West Bengal, to celebrate the rich cultural legacy of the Malla kings who ruled Bishnupur for a thousand years.', 'Celebrates the unique terracotta brick temple architecture, classical Bishnupur Gharana of music, and silk handloom weaving.', 'To promote heritage conservation and showcase Bishnupur''s GI-tagged Baluchari and Swarnachari silk sarees and Bankura terracotta horses.', 'Staged near the monumental 16th-century Rasmancha, an extraordinary pyramid-roofed brick monument unique in Indian architecture.', 'Features performances by master classical musicians of the Bishnupur Gharana (Bengal''s only recognized classical Dhrupad gharana).', ARRAY['Nightly classical music and dance concerts staged against illuminated 17th-century terracotta temples', 'Live demonstrations of intricate mythological silk weaving on Baluchari Jacquard handlooms', 'Exhibition of Bankura terracotta pottery, long-eared terracotta horses, and Dashavatara playing cards']::TEXT[], 'Connoisseurs wander past intricately carved terracotta temples depicting scenes from the Ramayana, attending classical concerts under cool winter skies.', ARRAY['Bishnupuri Pera', 'Mecha Sandesh (GI-tagged gram flour sweet)', 'Postor Bora (poppy seed fritters)', 'Dal-Bhat with Machher Jhol']::TEXT[], 'Exquisite handloom Baluchari silk sarees with woven Mahabharata pallu borders, handloom dhotis, and kurtas.', 'Pristine classical Dhrupad vocal recitals of the Bishnupur Gharana, classical sitar-sarod, and Odissi/Kathak dance dramas.', 'Pyramid-roofed brick Rasmancha, carved terracotta tile panels, long-necked Bankura terracotta horses, and Baluchari silks.', '4 Days', 'Gregorian / Winter', 'December 27 to 30 annually.', 'December', 'FIXED', 'Held annually December 27-30.', '2026-12-27', '2027-12-27', 'Department of Tourism West Bengal & Bankura District Administration', ARRAY['West Bengal']::TEXT[], ARRAY['Bishnupur', 'Bankura']::TEXT[], ARRAY['Rasmancha Complex', 'Madan Mohan Temple Bishnupur']::TEXT[], 'Morning architectural temple walks and evening classical concerts at Rasmancha', 2, 'Extraordinary step back into medieval royal Bengal: monumental terracotta temples glowing in golden lights, classical Dhrupad melodies, and magnificent silks.', 'Bishnupur railway station is 3 hours from Howrah/Kolkata by express train; well connected by highway.', 'Tourist lodges by West Bengal Tourism and heritage hotels in Bishnupur town.', 'Cool December evenings; carry a warm shawl.', 'Buy authentic GI-tagged Baluchari silk sarees directly from certified master weavers'' cooperatives in the town.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://wbtourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jhapan-mela-banka', 'Jhapan Mela Bankura', ARRAY['Snake Charmers Festival Bishnupur']::TEXT[], 'Tribal & Folk Traditions', 'Snake Deities & Rural Serpent Lore', 'A fascinating traditional folk festival held in honor of snake goddess Mansa Devi, where rural snake-handlers display venomous cobras and vipers on bullock carts.', 'Centuries-old folk tradition observed in the Bishnupur region of Bankura, celebrated on the last day of the Bengali month of Shravana.', 'Commemorates Goddess Mansa, the deity of snakes, fertility, and poison cure, invoking her protection during the monsoon season.', 'To honor snake-charmers (Jhampanias), celebrate rural folk resilience, and seek immunity from snakebites.', 'Famous for the grand procession of snake-charmers standing on bullock carts and trucks, displaying hooded king cobras, kraits, and pythons without fear.', 'Features the competitive display of snake-handling skill, accompanied by the singing of ancient Mansa Mangal epic ballads.', ARRAY['Grand procession of traditional snake-handlers (Jhampanias) displaying living cobras and pythons', 'Singing of ancient Mansa Mangal kavyas (epic poetry) by traditional balladeers', 'Puja of Goddess Mansa with offerings of milk, bananas, and wild wildflowers']::TEXT[], 'Crowds pack temple steps and village roads in awe as snake-handlers demonstrate incredible affinity and fearlessness with deadly serpents.', ARRAY['Makar Chaul', 'Pitha', 'Jalebi', 'Litti Chokha', 'Sweets']::TEXT[], 'Traditional rural dhotis, saffron waistcloths, snake-charmer headbands, and cotton sarees.', 'Rhythmic rural folk drumming with Dhol and Madol, accompanied by the wailing notes of the snake-charmer''s Been flute.', 'Hooded king cobras with spread hoods, cane baskets (Jhnapi), Mansa Devi clay idols, and neem leaves.', '1 Day', 'Bengali Solar Calendar', 'Last day of the Bengali month of Shravana (mid-August).', 'August', 'SOLAR', 'Celebrated on Shravana Sankranti (mid-August).', '2026-08-17', '2027-08-17', 'Bishnupur Jhapan Committee & Bankura Administration', ARRAY['West Bengal']::TEXT[], ARRAY['Bishnupur', 'Bankura']::TEXT[], ARRAY['Mansa Temple Bishnupur', 'Chaugan Grounds']::TEXT[], 'Afternoon between 2 PM and 6 PM during the snake procession and handling displays', 1, 'Astonishing, heart-stopping encounter with ancient serpent folklore, courageous snake-handlers, and living village mythology.', 'Accessible from Kolkata via train to Bishnupur (3 hours).', 'Hotels in Bishnupur.', 'Live venomous snakes are displayed in the procession; maintain a respectful, safe distance from handlers.', 'Do not provoke the animals; observe the deep folk connection between rural handlers and serpents.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bankura.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-jalpesh-mela', 'Jalpesh Mela Jalpaiguri', ARRAY['North Bengal Maha Shivratri Mela']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / North Bengal Heritage)', 'The historic month-long pilgrimage fair held at the massive 17th-century Jalpesh Shiva Temple, drawing millions of devotees from Bengal, Assam, Bihar, and Bhutan.', 'Ancient temple dating back to King Jalpa in 800 CE, rebuilt in grand Mughal-influenced style by Maharaja Pran Narayan of Cooch Behar in 1665 CE.', 'Celebrates Lord Shiva as Jalpeshwara (Lord of Water and Wells) and honors the spiritual brotherhood of North Bengal.', 'To offer holy water from the Teesta River to the subterranean Shiva Lingam and celebrate the sacred Maha Shivratri night.', 'The largest religious fair in North Bengal, serving as an ancient commercial and cultural bridge between the plains and Himalayan kingdoms (Bhutan, Sikkim).', 'Pilgrims walk barefoot carrying decorated Kanwars of holy water from the Teesta River at Jalpaiguri to the temple 25 km away.', ARRAY['Continuous holy abhishek of the subterranean Shiva Lingam with Teesta River water on Maha Shivratri', 'Walking barefoot with decorated water pots (Kanwar) from Teesta riverbanks to Jalpesh', 'Month-long trade fair selling Bhutanese woolens, agricultural implements, and cane furniture']::TEXT[], 'Over one million pilgrims fill the massive temple grounds, chanting ''Bhole Baba Par Karega'' as temple bells ring furiously through the night.', ARRAY['Bhadbhadia sweets', 'Jalebi', 'Puri Sabzi', 'Chhole Bhature', 'Tibetan Momos']::TEXT[], 'Saffron Kanwar dresses, white dhotis, cotton kurtas, and traditional Koch-Rajbongshi handloom wraps.', 'Thunderous beats of Dholak, conch shells, devotional Shiva bhajans, and Bhawaiya folk singing.', 'Monumental domed red-brick shikhara of Jalpesh Temple, Teesta river water vessels, and brass trishuls.', '1 Month', 'Hindu Lunisolar', 'Begins on Maha Shivratri (February - March) and lasts for four weeks.', 'February - March', 'LUNISOLAR', 'Commences on Maha Shivratri.', '2026-02-15', '2027-03-06', 'Jalpesh Temple Trust & Jalpaiguri District Administration', ARRAY['West Bengal']::TEXT[], ARRAY['Mainaguri', 'Jalpaiguri']::TEXT[], ARRAY['Jalpesh Temple Complex Mainaguri']::TEXT[], 'Maha Shivratri night and morning for the sacred abhishek and vibrant opening fair', 2, 'Powerful, historic spiritual fervor: an enormous 350-year-old domed temple rising above tea gardens and misty Dooars foothills, filled with echoing chants.', '25 km from Jalpaiguri railway station; 65 km from Bagdogra Airport; easily reached by highway buses and taxis.', 'Hotels in Jalpaiguri, Siliguri, or tea garden eco-resorts in the Dooars.', 'Huge crowds on Maha Shivratri; follow barricaded queue lines down to the underground sanctum.', 'Dress modestly; remove footwear before entering the temple gate; explore local handicraft stalls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://jalpaiguri.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-raas-utsav-nabadwip', 'Raas Utsav Nabadwip', ARRAY['Shakto Raas Nabadwip']::TEXT[], 'Spiritual & Temple', 'Gaudiya Vaishnavism & Shakta Synthesis', 'The extraordinary 300-year-old festival celebrated at the birthplace of Chaitanya Mahaprabhu, unique for gigantic 25-foot clay idols of both Krishna and Shakta deities.', 'Initiated in the 17th century in the holy town of Nabadwip on the Bhagirathi River, center of Sanskrit learning and birthplace of Sri Chaitanya Mahaprabhu.', 'Celebrates divine transcendental love, the Gaudiya Vaishnava Bhakti movement, and Bengal''s Shakta mother goddess traditions.', 'To honor Lord Krishna and Sri Chaitanya Mahaprabhu through music, kirtan, and colossal temporary clay sculptures.', 'Completely unique in Bengal: along with Vaishnava Raaslila scenes, the festival features colossal clay idols (up to 25 feet tall) of fierce tantric goddesses (Bhadrakali, Mahishasuramardini).', 'Concludes with the famous ''Shovayatra'' where clay idols are carried on the shoulders of hundreds of barefoot devotees to the Bhagirathi river for immersion.', ARRAY['Continuous Harinaam Sankirtan (chanting of Hare Krishna maha-mantra) across dozens of akhras', 'Darshan of over 300 colossal 25-foot clay idols depicting divine pastimes and tantric deities', 'Grand manual immersion procession where massive clay idols are carried on human shoulders to the river']::TEXT[], 'The ancient town transforms into an illuminated maze of glowing shrines, filled with the aroma of incense and ecstatic singing pilgrims.', ARRAY['Nabadwip Lal Doi (famous red caramelized sweet curd - GI Tagged)', 'Chhanar Murki', 'Radhaballabhi with Alur Dom', 'Khichuri Mahaprasad']::TEXT[], 'Traditional white cotton dhotis with Harinaam printed stoles, Tulsi neck-beads, and handloom cotton sarees.', 'Ecstatic Gaudiya Vaishnava Kirtan singing with Khol clay drums and brass Karatal cymbals, accompanied by classical Padavali kirtan.', 'Colossal 25-foot painted clay idols, clay Khol drums, Tulsi beads, and the flowing Bhagirathi River.', '3 Days', 'Hindu Lunisolar', 'Kartik Purnima (full moon night of Kartik month in November)', 'November', 'LUNISOLAR', 'Celebrated on Kartik Purnima.', '2026-11-24', '2027-11-13', 'Nabadwip Municipality & Gaudiya Math Association', ARRAY['West Bengal']::TEXT[], ARRAY['Nabadwip', 'Mayapur', 'Nadia']::TEXT[], ARRAY['Nabadwip Town Shrines', 'Bhagirathi River Ghats']::TEXT[], 'Night of Kartik Purnima and the following day for viewing the colossal clay idols and immersion procession', 2, 'Intense, ecstatic spiritual immersion: singing and dancing through narrow medieval lanes amidst colossal clay gods and the transcendent joy of Bhakti.', '120 km north of Kolkata; 2.5 hours by local train from Howrah/Sealdah; 15-minute boat ride from ISKCON Mayapur.', 'Guesthouses in Nabadwip or extensive international guest accommodations at ISKCON Mayapur across the river.', 'Narrow ancient town lanes; entire town is pedestrian-only during peak festival nights; wear comfortable walking shoes.', 'Taste the legendary GI-tagged ''Nabadwip Lal Doi'' from century-old sweetshops in the town.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://nadia.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mysuru-dasara', 'Mysuru Dasara', ARRAY['Mysore Nada Habba', 'Jumboo Savari']::TEXT[], 'Historical & Royal', 'Hinduism (Shaktism & Royal Wadiyar Heritage)', 'The state festival (Nada Habba) of Karnataka celebrated with breathtaking royal pageantry, illuminated palaces, and the iconic Jumboo Savari elephant procession.', 'Initiated in 1610 CE by Raja Wadiyar I of Mysore at Srirangapatna, carrying forward the glorious traditions of the Vijayanagara Empire.', 'Celebrates the victory of Goddess Chamundeshwari over the buffalo demon Mahishasura, who according to legend gave Mysore its name.', 'To honor Goddess Chamundeshwari (patron deity of Mysore), celebrate the royal cultural heritage, and showcase the diversity of Karnataka.', 'The iconic Mysore Palace is illuminated with over 100,000 incandescent golden bulbs, creating one of the most stunning architectural sights in Asia.', 'Culminates on Vijyadashami with the ''Jumboo Savari'', where the lead tusker carries the 750-kilogram solid gold howdah containing Goddess Chamundeshwari.', ARRAY['Worship of Goddess Chamundeshwari atop Chamundi Hill by the royal family', 'Special private Durbar conducted by the titular Maharaja at Mysore Palace', 'Grand Jumboo Savari street procession featuring caparisoned elephants, cavalry, and cultural tableaux']::TEXT[], 'Over one million spectators line the 5 km route from Mysore Palace to Bannimantap, cheering as the golden howdah elephant passes amidst brass bands.', ARRAY['Mysore Pak (world-famous melt-in-mouth ghee-gram flour confection - GI Tagged)', 'Mysore Masala Dosa', 'Bisi Bele Bath', 'Mysore Rasam', 'Holige (Obbattu)']::TEXT[], 'Traditional Karnataka royal attire: Mysore Peta (gold-laced turban), silk Kurta with Zari Angavastram, and rich Kanjeevaram and Mysore Silk sarees.', 'Royal Karnataka Police brass bands, classical Carnatic music concerts, traditional Dollu Kunitha folk drummers, and Veeragase dance.', 'Solid gold 750 kg golden howdah (Chinnada Ambari), 100,000 glowing palace bulbs, caparisoned elephants, and Chamundeshwari idol.', '10 Days', 'Hindu Lunisolar', 'Ashwin Shukla Pratipada to Dashami (September - October)', 'September - October', 'LUNISOLAR', 'Culminates on Vijyadashami in Ashwin month.', '2026-10-20', '2027-10-10', 'Mysuru Dasara High Power Committee & Karnataka Tourism', ARRAY['Karnataka']::TEXT[], ARRAY['Mysuru (Mysore)']::TEXT[], ARRAY['Mysore Palace', 'Chamundi Hill', 'Bannimantap Grounds']::TEXT[], 'Vijyadashami day for the Jumboo Savari procession and nightly palace illumination at 7 PM', 3, 'Peerless royal grandeur: a fairytale palace glowing with 100,000 golden lights, majestic caparisoned elephants, and Karnataka''s vibrant cultural soul.', 'Mysore Airport connects to major cities; Shatabdi and Vande Bharat trains connect from Bengaluru (2 hours); 10-lane expressway.', 'Hotels and heritage palace resorts across Mysuru; book 4-6 months in advance for Dasara week.', 'Enormous crowds exceeding one million along the procession route; buy official gold card or stadium gallery passes in advance.', 'Remove footwear before climbing Chamundi Hill temple; buy authentic GI-tagged Mysore Silk sarees directly from KSIC outlets.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mysoredasara.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hampi-utsav', 'Hampi Utsav', ARRAY['Vijayanagara Utsav']::TEXT[], 'Historical & Royal', 'Vijayanagara Imperial Heritage & Classical Arts', 'A monumental three-day cultural festival celebrating the golden age of the Vijayanagara Empire amidst the UNESCO World Heritage boulder-strewn ruins of Hampi.', 'Initiated by the Government of Karnataka to celebrate the glorious history, architecture, and arts of the 14th-century Vijayanagara Empire.', 'Celebrates the peace, prosperity, and artistic brilliance of Emperor Krishnadevaraya''s reign in the 16th century.', 'To revive the cultural splendor of the ancient capital and showcase world-renowned performing artists amidst ancient stone monuments.', 'The monumental ruins (Virupaksha Temple, Stone Chariot at Vittala Temple, Lotus Mahal, Elephant Stables) serve as floodlit natural performance stages.', 'Features the ''Janapada Vahini'' folk procession, grand elephant parades, and spectacular sky-lighting across the rocky landscape.', ARRAY['Grand cultural procession featuring caparisoned elephants, royal cavalry, and 500 folk dance troupes', 'Nightly classical music and dance recitals on multiple stages near Virupaksha Temple and Eduru Basavanna', 'Dramatic illumination and laser projection show transforming the boulder hills and stone monuments']::TEXT[], 'Travelers wander through the illuminated medieval ruins by day, climbing boulders and attending open-air classical concerts under the starlit sky.', ARRAY['Bisi Bele Bath', 'Jolada Roti with Ennegai (stuffed brinjal)', 'Dharwad Peda', 'Mysore Pak', 'Ragi Mudde']::TEXT[], 'Smart casual travel wear, comfortable walking boots, ethnic handloom stoles, and cotton kurtas.', 'Classical Carnatic vocal and instrumental music, classical Bharatanatyam and Kuchipudi, Dollu Kunitha, and Lambani tribal dances.', 'Iconic stone chariot of Vittala Temple, towering Gopuram of Virupaksha Temple, Tungabhadra River, and granite boulder hills.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Karnataka Tourism & Bellary District Administration.', '2026-01-29', '2027-01-28', 'Department of Tourism Karnataka & Hampi World Heritage Area Management Authority', ARRAY['Karnataka']::TEXT[], ARRAY['Hampi', 'Hosapete (Hospet)', 'Vijayanagara']::TEXT[], ARRAY['Virupaksha Temple Complex', 'Vittala Temple', 'Mahanavami Dibba']::TEXT[], 'Evenings between 6 PM and 10 PM when monuments are illuminated for classical concerts', 2, 'Awe-inspiring journey into a fairytale medieval empire: monumental stone temples and boulder hills glowing under night spotlights, echoing with classical melodies.', 'Jindal Vidyanagar Airport (Toranagallu - 40 km); Hosapete Junction railway station (12 km); easily reached by cabs and auto-rickshaws.', 'Heritage resorts, riverine lodges, and boutique hotels in Hosapete and around Hampi.', 'Extensive walking over uneven granite stone; wear sturdy, comfortable walking shoes; carry hats and water during daytime.', 'Strict UNESCO conservation rules: no touching or climbing on ancient carved stone monuments; respect the active sanctity of Virupaksha Temple.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kambala-buffalo-race', 'Kambala Buffalo Race Coastal Karnataka', ARRAY['Tuluva Slush Track Buffalo Race']::TEXT[], 'Art & Cultural Festival', 'Tuluva Agrarian & Athletic Heritage', 'The exhilarating traditional rural sport of coastal Karnataka where jockeys sprint through waterlogged muddy paddy fields holding the reins of two galloping buffaloes.', 'Centuries-old agrarian winter festival celebrated across the Tulu-speaking coastal districts of Dakshina Kannada and Udupi.', 'Originated as a post-monsoon harvest thanksgiving by farmers to Lord Shiva (Manjunatha) to keep buffalo herds healthy and bless the winter crop.', 'To celebrate rural athleticism, foster community solidarity, and honor the sacred bond between Tuluva farmers and their prize buffaloes.', 'Jockeys race through a parallel 145-meter slush-filled track (Kambala Gadde), with champion sprinters completing the race in under 12 seconds.', 'Famous for the laser-measured ''Kene Halage'' category, where a wooden plank attached to the yoke kicks up a jet of water measured against white banners.', ARRAY['Traditional puja and consecration of the muddy twin racing tracks (Kambala Gadde)', 'Competitive heats of prize racing buffaloes sprinting through slush-filled tracks with jockeys', 'Ceremonial honoring of champion buffalo breeders and jockeys with gold medals and trophies']::TEXT[], 'Vast crowds line the muddy embankment under floodlights, roaring with excitement as pairs of jet-black buffaloes thunder past, kicking up mud sprays.', ARRAY['Mangalorean Kori Rotti (crispy rice wafers with spicy chicken curry)', 'Neer Dosa', 'Pundi (steamed rice balls)', 'Mangalore Buns', 'Filter Coffee']::TEXT[], 'Comfortable casual wear, shorts, T-shirts, and flat footwear that can handle muddy embankments.', 'Resounding Tulu commentary over loudspeakers, rhythmic cheering, and traditional folk drumming with Chende.', 'Twin muddy racing tracks, sleek horned water buffaloes, water jets splashing on marker banners, and floodlight towers.', '2 Days (weekly circuit from Nov to March)', 'Seasonal / Winter Slush', 'Held on alternating weekends across coastal towns from November to March.', 'November - March', 'SEASONAL', 'Flagship races held between December and February.', '2026-12-12', '2027-12-11', 'Dakshina Kannada & Udupi District Kambala Committee', ARRAY['Karnataka']::TEXT[], ARRAY['Moodabidri', 'Puttur', 'Mangaluru', 'Udupi']::TEXT[], ARRAY['Miyar Kambala Track Moodabidri', 'Pilikula Nisargadhama']::TEXT[], 'Afternoon and night (4 PM to midnight) under the floodlights when semi-finals and finals take place', 2, 'Electrifying adrenaline rush: roaring crowds, splashing mud, thunderous thudding hooves, and witnessing lightning-fast rural athletic human-animal coordination.', 'Mangaluru International Airport; well connected by Konkan Railway and coastal highway NH-66.', 'Hotels and beachfront resorts across Mangaluru and Udupi.', 'Muddy spectator embankments; wear casual clothes and shoes that you do not mind getting splashed with mud.', 'Strict animal welfare guidelines: no whipping or harming of buffaloes is permitted; races are monitored by veterinary officers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-karaga-shaktyotsava', 'Karaga Shaktyotsava Bengaluru', ARRAY['Bangalore Karaga']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism / Draupadi & Thigala Heritage)', 'The oldest unbroken festival of Bengaluru celebrated by the Vahnikula Kshatriya (Thigala) community, where a floral pyramid pot is carried in a nightlong trance procession.', 'Celebrated for over 800 years, centered around the historic Dharmaraya Swamy Temple in Tigalarpet in the heart of Bengaluru''s historic Pete market.', 'Commemorates Draupadi as Goddess Adi Shakti and honors her mythological legion of warrior-servants (Veerakumaras).', 'To invoke the cosmic protective power of Goddess Draupadi for the prosperity, health, and peace of Bengaluru city.', 'A priest dressed in female attire balances the sacred Karaga—a towering floral pyramid pot decorated with jasmine flowers—without touching it with hands.', 'Famous for its historic communal harmony: the Karaga procession makes a midnight visit to the 300-year-old Dargah of Sufi Saint Tawakkal Mastan.', ARRAY['Balancing of the sacred floral Karaga on the head of the consecrated priest', 'Barefoot midnight procession through the historic Pete streets guarded by Veerakumaras wielding bare swords', 'Ceremonial visit and offering of flowers at the Sufi Dargah of Hazrat Tawakkal Mastan']::TEXT[], 'Narrow old market lanes are packed with thousands of devotees chanting ''Govinda, Govinda'' as the floral pyramid moves in an ecstatic trance through the night.', ARRAY['Puliyogare (tamarind rice prasad)', 'Chitranna (lemon rice)', 'Sweet Pongal', 'Holige', 'Mysore Pak']::TEXT[], 'Veerakumaras wear traditional white dhotis with bare torsos, red turbans, and carry gleaming curved steel swords; devotees wear festive Indian attire.', 'Thunderous beats of traditional Tamate percussion drums, wailing horns, and deafening shouts of ''Govinda! Govinda!''.', 'Tall floral Karaga pyramid pot covered in fragrant white jasmine flowers (Mullai), flashing steel swords, and midnight oil lamps.', '9 Days (Culminates on Chaitra Purnima)', 'Hindu Lunisolar', 'Chaitra Purnima (full moon night of Chaitra month in April)', 'March - April', 'LUNISOLAR', 'Culminates on the midnight of Chaitra Purnima.', '2026-04-02', '2027-04-20', 'Sri Dharmaraya Swamy Temple Trust & Bengaluru City Police', ARRAY['Karnataka']::TEXT[], ARRAY['Bengaluru']::TEXT[], ARRAY['Sri Dharmaraya Swamy Temple Tigalarpet', 'Dargah Hazrat Tawakkal Mastan']::TEXT[], 'Midnight (11 PM to 4 AM) on Chaitra Purnima night during the grand street procession', 1, 'Mystical, thrilling midnight trance ritual in the historic heart of modern Bangalore, packed with flying jasmine petals, clashing swords, and inter-faith harmony.', 'Located in Old Pete (near City Market); accessible by Namma Metro (Chickpete Station); walking on foot is essential.', 'Hotels throughout central Bengaluru.', 'All-night event; narrow, intensely crowded historic alleys; keep wallets and phones in front pockets.', 'Do not touch the Karaga priest or get in the path of the sword-wielding Veerakumaras; remove footwear near the temple and dargah.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pattadakal-dance-festival', 'Pattadakal Dance Festival', ARRAY['Chalukya Dance Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & 8th-Century UNESCO Architecture', 'A magnificent three-day festival of classical Indian dance staged against the 8th-century UNESCO World Heritage sandstone temples of the early Chalukya kings.', 'Established by the Government of Karnataka to celebrate the architectural genius of the Chalukya dynasty where northern Nagara and southern Dravida temple styles harmonized.', 'Celebrates the coronation city (Pattadakal literally means ''city of the coronation stone'') of the Badami Chalukyan monarchs.', 'To showcase world-class classical dancers against the intricately sculpted temple facades of Virupaksha, Mallikarjuna, and Sangameshwara.', 'The Virupaksha Temple, built in 740 CE by Queen Lokamahadevi to commemorate her husband''s victory over the Pallavas, serves as the majestic stage backdrop.', 'Features master exponents of Bharatanatyam, Kathak, Odissi, Kuchipudi, and Mohiniyattam performing on an open-air stone terrace under golden floodlights.', ARRAY['Dramatic illumination of the 8th-century UNESCO World Heritage stone temple complex', 'Nightly classical dance and music concerts by celebrated national maestros', 'Daytime heritage seminars and guided walks through the Chalukyan temple clusters']::TEXT[], 'Connoisseurs sit beneath cold starlit skies on the Malaprabha riverbank, mesmerized as classical dancers match the exact sculptures carved 1,300 years ago.', ARRAY['Jolada Roti with Stuffed Brinjal Curry', 'Shenga Chutney (peanut chutney)', 'Dharwad Peda', 'Sajjige', 'Filter Coffee']::TEXT[], 'Refined formal Indian ethnic wear: handloom Ilkal sarees (from nearby historic Ilkal), silk kurtas, and warm shawls.', 'Sublime classical Carnatic and Hindustani music, mridangam and pakhawaj rhythms, flute melodies, and classical dance dramas.', 'Sculpted stone pillars of Virupaksha Temple, Chalukyan Dravida and Nagara shikharas, and golden floodlights.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Karnataka Tourism & Bagalkot Administration.', '2026-01-23', '2027-01-22', 'Department of Tourism Karnataka & ASI', ARRAY['Karnataka']::TEXT[], ARRAY['Pattadakal', 'Badami', 'Bagalkot']::TEXT[], ARRAY['Pattadakal Temple Complex']::TEXT[], 'Evenings between 6 PM and 9:30 PM during the floodlit classical dance recitals', 2, 'Transcendental communion with ancient Indian architectural perfection: sitting before 1,300-year-old temples where classical ragas echo through the river valley.', '22 km from Badami railway station; 130 km from Hubballi Airport; accessible by taxi.', 'Hotels and heritage resorts in Badami; basic guesthouses near Pattadakal.', 'Cool January winter evenings; carry a warm shawl or light jacket.', 'Strict archaeological protection: no touching ancient temple stone carvings; stay within designated spectator seating.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kadalekai-parishe', 'Kadalekai Parishe Bengaluru', ARRAY['Basavanagudi Peanut Fair']::TEXT[], 'Fair & Mela', 'Folk Agrarian & Sacred Bull Heritage', 'Bengaluru''s beloved 500-year-old peanut fair held at the historic Bull Temple (Nandi Temple) in Basavanagudi, where farmers offer their first harvest of groundnuts.', 'Dates back to 1537 CE during the reign of Kempe Gowda I, founder of Bengaluru, after farmers pacified a rampaging bull by promising their first peanut crop to Lord Basava.', 'Celebrates the autumn peanut harvest and thanksgiving to the sacred bull Nandi (Lord Basava).', 'To offer the first harvest of groundnuts to the monumental monolithic bull statue and pray for agricultural abundance and family prosperity.', 'Bull Temple Road transforms into a vibrant two-kilometer pedestrian carnival lined with hundreds of peanut farmers selling raw, roasted, boiled, and spiced peanuts.', 'Features the magnificent 16th-century monolithic granite bull statue of Nandi, measuring 15 feet high and 20 feet long, anointed with fresh butter and groundnuts.', ARRAY['Offering the first harvest of peanuts to the monumental monolithic Nandi statue at the Bull Temple', 'Special abhishekam of the sacred bull statue with milk, curd, and butter', 'Strolling down the vibrant two-kilometer street fair enjoying hot roasted groundnuts, street food, and traditional toys']::TEXT[], 'Hundreds of thousands of citizens and families stroll through tree-shaded Basavanagudi avenues, cracking hot roasted peanuts and soaking in Old Bangalore charm.', ARRAY['Freshly roasted, salted, and boiled Kadalekai (groundnuts)', 'Masala Peanuts', 'Congress Kadlekai', 'Mangalore Buns', 'Mysore Pak', 'Hot Filter Coffee']::TEXT[], 'Casual ethnic wear, comfortable walking shoes, and traditional South Indian cotton attire.', 'Traditional Nadaswaram temple music, Carnatic devotional singing, and lively street folk songs.', 'Monumental black granite Nandi bull statue, massive smoking peanut roasting pans, and overflowing mounds of groundnuts.', '3 Days', 'Hindu Lunisolar', 'Last Monday of the Hindu month of Kartika (November - December)', 'November - December', 'LUNISOLAR', 'Celebrated on the last Monday of Kartika month.', '2026-11-30', '2027-11-22', 'Basavanagudi Temple Trust & BBMP', ARRAY['Karnataka']::TEXT[], ARRAY['Bengaluru', 'Basavanagudi']::TEXT[], ARRAY['Bull Temple Road Basavanagudi', 'Bugle Rock Park']::TEXT[], 'Evening between 4 PM and 9 PM when the street fair is vibrant and peanuts are freshly roasted', 2, 'Heartwarming Old Bangalore nostalgia: pleasant autumn evening chill, aroma of wood-roasted peanuts filling the air, and joyful community banter.', 'Easily accessible via Namma Metro Green Line (National College or Lalbagh stations); auto-rickshaws widely available.', 'Hotels throughout central and south Bengaluru.', 'Heavy pedestrian crowds along Bull Temple Road; streets are closed to vehicular traffic; wear comfortable walking shoes.', 'Buy different varieties of groundnuts: raw pods for boiling at home, and spicy masala peanuts for snacking.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-vairamudi-brahmotsavam', 'Vairamudi Brahmotsavam Melukote', ARRAY['Melkote Diamond Crown Festival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Sri Vaishnavism / Ramanuja Heritage)', 'The glorious nocturnal festival where the presiding deity Lord Cheluvanarayana Swamy is adorned with the legendary diamond-studded crown (Vairamudi).', 'Ancient Sri Vaishnava festival celebrated for nearly 1,000 years, revitalized by philosopher-saint Sri Ramanujacharya who lived in Melukote for 12 years in the 12th century.', 'According to sacred tradition, the divine diamond crown was brought to earth by Garuda from Vaikuntha to adorn the deity.', 'To behold Lord Cheluvanarayana Swamy wearing the dazzling diamond crown during his midnight procession.', 'The priceless diamond crown (kept under armed government treasury custody in Mandya) is brought out only on this single night of the year.', 'By sacred vow, the chief temple priest must place the crown on the deity''s head blindfolded, as looking directly at the brilliant gems is forbidden by tradition.', ARRAY['Ceremonial arrival of the priceless diamond crown from the government treasury under heavy armed guard', 'Blindfolded crowning of Lord Cheluvanarayana Swamy by the chief archaka inside the sanctum', 'All-night street procession of the deity riding the golden Garuda Vahana through illuminated town streets']::TEXT[], 'Over 400,000 pilgrims pack the historic temple town, chanting ''Govinda, Govinda'' as the dazzling diamond crown flashes brilliantly under torchlight.', ARRAY['Melukote Puliyogare (world-famous tangy tamarind rice - GI Tagged)', 'Sweet Pongal (Chakkara Pongal)', 'Tirukannamadhu sweet', 'Mysore Pak']::TEXT[], 'Traditional Sri Vaishnava white dhotis with red/gold borders, Angavastrams, and silk Kanjeevaram sarees.', 'Continuous chanting of the Nalayira Divya Prabandham hymns by Tamil Sri Vaishnava scholars, resonant Nadaswaram, and temple bells.', 'Priceless diamond-encrusted Vairamudi crown, golden Garuda vehicle (Vahana), and 12th-century Cheluvanarayana Swamy Temple.', '1 Night (Festivities for 10 Days)', 'Hindu Lunisolar', 'Panguni (Phalguna) month on Pushya Nakshatra (March - April)', 'March - April', 'LUNISOLAR', 'Celebrated on the night of Pushya Nakshatra in Phalguna/Chaitra.', '2026-03-29', '2027-03-18', 'Melukote Cheluvanarayana Swamy Temple Trust & Mandya Administration', ARRAY['Karnataka']::TEXT[], ARRAY['Melukote', 'Pandavapura', 'Mandya']::TEXT[], ARRAY['Sri Cheluvanarayana Swamy Temple Melukote']::TEXT[], 'Midnight (10 PM to 4 AM) when the deity wearing the diamond crown is carried on the golden Garuda vehicle', 1, 'Mesmerizing spiritual intensity: witnessing a priceless medieval diamond crown blazing under torchlight, surrounded by 400,000 chanting pilgrims in a 1,000-year-old temple town.', '50 km from Mysuru and 130 km from Bengaluru via Bengaluru-Mysuru Expressway; accessible by highway taxi.', 'Simple pilgrim dharamshalas in Melukote; comfortable hotels in Mysuru or Mandya.', 'All-night event with enormous crowd density in narrow historic streets; hold children''s hands securely.', 'Savor the authentic GI-tagged ''Melukote Puliyogare'' and Chakkara Pongal prasad distributed at traditional temple kitchens.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mandya.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mahamastakabhisheka-shravanabelagola', 'Mahamastakabhisheka Shravanabelagola', ARRAY['Grand Head Anointing of Gommateshwara']::TEXT[], 'Spiritual & Temple', 'Jainism (Digambara Sacred Anointing)', 'The monumental 12-year grand anointing ceremony of the colossal 57-foot monolithic granite statue of Lord Bahubali (Gommateshwara) atop Vindhyagiri Hill.', 'Consecrated in 981 CE by Chavundaraya, commander of the Western Ganga dynasty; the grand head anointing has been celebrated continuously every 12 years for over 1,000 years.', 'Commemorates the supreme renunciation, non-violence (Ahimsa), and spiritual liberation (Kevala Jnana) of Lord Bahubali.', 'To perform sacred anointing (Abhisheka) on the head of the world''s tallest free-standing monolithic statue with milk, saffron, and sandalwood.', 'A monumental event on the global religious calendar, drawing millions of Jain monks, scholars, and pilgrims from around the world.', 'Scaffolding is erected behind the 57-foot monolith, and devotees pour 1,008 consecrated brass pots (Kalashas) of milk, sugarcane juice, saffron paste, and vermilion.', ARRAY['Climbing the 650 rock-cut steps of holy Vindhyagiri Hill', 'Pouring consecrated Kalash pots of milk, turmeric, saffron, and sugarcane juice over Bahubali''s head', 'Showering of 57-foot statue with gold and silver flowers from low-flying helicopters']::TEXT[], 'The colossal grey granite statue turns miraculously white with milk, golden with turmeric, crimson with vermilion, and fragrant with sandalwood paste.', ARRAY['Pure Jain sattvic feast meals', 'Bisi Bele Bath (Jain preparation)', 'Badam Milk', 'Mysore Pak', 'Fruit prasad']::TEXT[], 'White cotton dhotis for devotees; Digambara monks in complete ascetic renunciation; women wear white or yellow sarees.', 'Sacred Sanskrit and Prakrit Jain stotram recitations, resonant trumpet blasts, and continuous chanting of ''Bhagwan Bahubali Ki Jai''.', '57-foot monolithic granite statue of Bahubali, 1,008 consecrated golden Kalashas, and Vindhyagiri rock-cut steps.', '9 Days', 'Astrological / 12-Year Cycle', 'Organized once every 12 years (last held in 2018; next in 2030).', 'February', 'LUNISOLAR', 'Celebrated every 12 years in February (next in 2030).', '2030-02-17', '2030-02-25', 'Mahamastakabhisheka Mahotsava Samiti & Government of Karnataka', ARRAY['Karnataka']::TEXT[], ARRAY['Shravanabelagola', 'Hassan']::TEXT[], ARRAY['Vindhyagiri Hill Gommateshwara Statue']::TEXT[], 'Morning hours (8 AM to 1 PM) when the sacred color anointing (Abhisheka) takes place', 3, 'Once-in-a-lifetime spiritual and visual wonder: standing dwarfed before a 1,000-year-old monolithic stone giant as cascades of milk, saffron, and gold wash down his serene face.', 'Shravanabelagola railway station connects from Bengaluru (2.5 hours); 150 km west of Bengaluru Airport via 4-lane highway.', 'Massive temporary satellite townships (tented cities) set up during Mahamastakabhisheka; hotels in Hassan and Bengaluru.', 'Climbing 650 rock-cut stone steps barefoot; doli palanquin service is available for elderly visitors.', 'Strict Digambara Jain sanctity: no leather items (shoes, belts, wallets) permitted on the hill; dress modestly in white or yellow.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-yakshagana-festival', 'Yakshagana Bayalata Festival Coastal Karnataka', ARRAY['All-Night Yakshagana Mela']::TEXT[], 'Art & Cultural Festival', 'Epic Folk Theatre & Coastal Tuluva Heritage', 'The thrilling all-night open-air dance-theatre festival celebrated across coastal Karnataka, featuring towering feathered crowns, vibrant makeup, and roaring dialogue.', 'Ancient classical-folk theatre tradition dating back over 800 years, documented in 16th-century inscriptions of the Vijayanagara Empire.', 'Brings to life the grand mythological episodes (Prasangas) from the Mahabharata, Ramayana, and Bhagavata Purana.', 'To honor village temple deities (Mandarthi, Kateel, Dharmasthala) and celebrate the triumph of divine righteousness over demons.', 'Performed all night from dusk till dawn (Bayalata literally means ''open field play'') by traditional travelling temple troupes (Melas).', 'Features two distinct regional styles: Tenkutittu (southern style with fast spinning acrobatics and Chande) and Badagutittu (northern style with towering crowns and intricate footwork).', ARRAY['Lighting of the sacred brass oil lamp (Ranga Deepa) to inaugurate the open-air stage', 'Performance of intricate dance and improvised theatrical dialogue in Kannada and Tulu', 'Spectacular battle scenes where demons and gods leap, clash weapons, and deliver thunderous monologues']::TEXT[], 'Villagers of all ages sit on straw mats in open paddy fields until sunrise, cheering heroic kings, booing comedic demons, and admiring lightning-fast pirouettes.', ARRAY['Mangalorean Buns', 'Neer Dosa with Chutney', 'Kori Rotti', 'Pundi', 'Hot Filter Coffee served all night']::TEXT[], 'Flamboyant costumes: towering layered crowns (Kireeta), winged shoulder ornaments (Bhujakeerti), red-and-black checkerboard dhotis, and heavy facial makeup.', 'Resounding, fast-tempo beats of the Chande and Maddale drums, accompanied by high-pitched singing by the Bhagavat (lead singer).', 'Towering gold-and-mirror Kireeta crowns, painted demon faces, flaming stage torches, and open paddy fields.', 'All-Night (Regular season from Nov to May)', 'Seasonal / Winter-Spring', 'Celebrated continuously on winter and spring nights across coastal Karnataka.', 'November - May', 'SEASONAL', 'Peak performances occur between December and April.', '2026-12-15', '2027-12-15', 'Karnataka Yakshagana Academy & Coastal Temple Melas', ARRAY['Karnataka']::TEXT[], ARRAY['Udupi', 'Mangaluru', 'Kundapura', 'Karkala', 'Dharmasthala']::TEXT[], ARRAY['Kateel Durgaparameshwari Temple', 'Udupi Krishna Matha', 'Village maidans']::TEXT[], 'Night from 10 PM to 4 AM when high-drama mythological battles and comedic interludes take place', 1, 'Electrifying, larger-than-life folk theatrical spectacle: thundering drums, towering feathered crowns, lightning pirouettes, and gripping epic storytelling under the stars.', 'Easily accessible across coastal Karnataka via Konkan Railway and coastal highway NH-66.', 'Hotels and coastal resorts in Mangaluru, Udupi, and Kundapura.', 'All-night outdoor event; carry a light jacket for cool pre-dawn hours; seating on ground mats or plastic chairs.', 'Follow the complex improvised dialogue; even without knowing Kannada or Tulu, the dramatic body language and percussion convey the story brilliantly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chalukya-utsav-badami', 'Chalukya Utsav Badami & Aihole', ARRAY['Badami Cave Temples Festival']::TEXT[], 'Historical & Royal', 'Early Chalukyan Architecture & Cave Temples', 'A magnificent three-day cultural festival celebrated amidst the dramatic red sandstone cliffs, rock-cut cave temples, and emerald waters of Agastya Lake in Badami.', 'Initiated by Karnataka Tourism to honor the legendary Chalukya dynasty (Pulakeshin II) who established their magnificent rock-cut capital at Vatapi (Badami) in the 6th century CE.', 'Celebrates the birth of Indian temple architecture in the Malaprabha river valley (Badami, Aihole, Pattadakal).', 'To showcase world-class classical dancers, vocalists, and folk artists against the majestic red sandstone cliffside cave temples.', 'Staged against the tranquil waters of Agastya Lake, with the ancient Bhutanatha Temple and 6th-century rock-cut cave temples glowing in amber floodlights.', 'Includes Aihole—the ''Cradle of Indian Temple Architecture''—featuring over 120 experimental temples dating from the 5th to 8th centuries.', ARRAY['Classical dance and music concerts staged against illuminated 6th-century rock-cut cave temples', 'Heritage walking tours through the carved rock sanctuaries depicting the 18-armed dancing Shiva (Nataraja)', 'Folk dance competitions, wrestling bouts, and laser projections over the red sandstone cliffs']::TEXT[], 'Visitors sit beside the calm waters of Agastya Lake under the evening sky, watching classical dancers perform before ancient rock temples carved into monolithic sandstone cliffs.', ARRAY['Jolada Roti with Stuffed Brinjal (Ennegai)', 'Shenga Chutney', 'Dharwad Peda', 'Sajjige', 'Filter Coffee']::TEXT[], 'Traditional handloom Ilkal sarees with distinctive red Chikki Paras borders, kurtas, and comfortable travel wear.', 'Classical Carnatic and Hindustani music, classical Bharatanatyam, Kathak, and traditional Veeragase martial dance.', 'Red sandstone cliffs of Badami, 18-armed dancing Shiva relief in Cave 1, Bhutanatha Temple reflected in Agastya Lake, and golden floodlights.', '3 Days', 'Gregorian / Winter', 'Held in February annually.', 'February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Karnataka Tourism & Bagalkot Administration.', '2026-02-06', '2027-02-05', 'Department of Tourism Karnataka & ASI', ARRAY['Karnataka']::TEXT[], ARRAY['Badami', 'Aihole', 'Pattadakal']::TEXT[], ARRAY['Agastya Lake Badami', 'Bhutanatha Temple', 'Aihole Temple Complex']::TEXT[], 'Evenings between 6 PM and 9:30 PM for floodlit lakefront concerts and morning cliff walks', 2, 'Breathtaking natural and architectural grandeur: dramatic red sandstone cliffs glowing amber around tranquil lake waters, filled with sublime classical arts.', 'Badami railway station connects to Hubballi and Bengaluru; 100 km from Hubballi Airport.', 'Heritage resorts, tourist lodges, and hotels in Badami town.', 'Climbing stone stairs to Cave Temples 1 through 4; wear sturdy walking footwear.', 'Strict archaeological protection: no touching delicate 1,500-year-old rock-cut sculptures; watch out for local monkeys around cave steps.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tula-sankramana-coorg', 'Tula Sankramana Coorg', ARRAY['Theerthodbhava Talakaveri']::TEXT[], 'Spiritual & Temple', 'Hinduism (Sacred River Birth & Kodava Heritage)', 'The sacred annual miracle celebrated at the birthplace of River Cauvery in Talakaveri, where spring water surges miraculously in the sacred pond at an exact astrological moment.', 'Celebrated since ancient times by the martial Kodava community and millions across Karnataka and Tamil Nadu who revere River Cauvery as Mother Goddess (Kaveramma).', 'Celebrates the annual rebirth and divine manifestation of Mother Cauvery (Theerthodbhava) as the life-giving lifeline of southern India.', 'To take holy cleansing dips in the sacred Kundike (spring) and pray for agricultural fertility and family prosperity.', 'At the exact astrological moment (Theerthodbhava) determined by Kodava priests, water bubbles up miraculously and overflows from the small stone spring pond.', 'Lakhs of pilgrims shout ''Kaveri Mathe Ki Jai'' as they collect the holy surging spring water in silver and brass vessels to carry back home.', ARRAY['Waiting in silent prayer around the sacred Brahma Kundike spring for the miraculous surge of water (Theerthodbhava)', 'Collecting the sanctified bubbling holy spring water in vessels for distribution as life-giving Amrita', 'Solemn prayer rituals performed by Kodava elders in traditional attire atop Brahmagiri Hill']::TEXT[], 'Devotees brave cold mountain mists atop the scenic Brahmagiri mountain, singing hymns to Mother Cauvery and bathing in the stepped pond.', ARRAY['Kodava Koli Curry with Kadambuttu (steamed rice dumplings)', 'Akki Roti with bamboo shoot curry (Kani)', 'Pandi Curry', 'Coorg Filter Coffee']::TEXT[], 'Distinctive traditional Kodava attire: Kodava Kupya (collarless tunic) with gold-embroidered silk sash (Chele) and silver dagger (Peeche Kathi); Kodava saree draped with pleats at the back.', 'Solemn Kodava traditional hymns (Kaveri Pattu), accompanied by traditional Dudikott Pat folk singing.', 'Brahma Kundike sacred spring, Brahmagiri mountain peak, silver holy water vessels, and traditional Kodava attire.', '1 Day (Astrological Timing)', 'Solar / Tula Sankramana', 'Mid-October (first day of the solar month of Tula - usually October 17-18).', 'October', 'FIXED', 'Celebrated on Tula Sankranti (October 17-18 annually).', '2026-10-18', '2027-10-18', 'Talakaveri Temple Trust & Kodagu District Administration', ARRAY['Karnataka']::TEXT[], ARRAY['Talakaveri', 'Madikeri', 'Bhagamandala', 'Kodagu']::TEXT[], ARRAY['Talakaveri Sacred Spring Brahmagiri', 'Bhagamandala Triveni Sangam']::TEXT[], 'The exact predetermined astrological hour of Theerthodbhava (usually afternoon or evening) and dawn bathing', 2, 'Profound, tearful spiritual awe: witnessing the birth of a sacred river on a misty mountain summit surrounded by ancient evergreen shola rainforests.', '45 km from Madikeri; 150 km from Mangaluru Airport and Mysuru railway station; accessible by scenic mountain roads.', 'Plantation homestays, coffee estate resorts, and hotels in Madikeri and Bhagamandala.', 'Cool, misty mountain weather; carry warm woolens and rain protection.', 'Strict sanctity observed around the small holy spring; maintain queue discipline; do not push around the spring perimeter.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kodagu.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-hoysala-mahotsava', 'Hoysala Mahotsava Halebidu & Belur', ARRAY['Belur Halebidu Heritage Dance Fest']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & 12th-Century Star-Shaped Temples', 'A magnificent cultural celebration of classical Indian dance staged against the world-famous 12th-century star-shaped soapstone temples of the Hoysala Empire.', 'Initiated by Karnataka Tourism to celebrate the architectural and sculptural genius of the Hoysala dynasty who ruled southern India from Belur and Halebidu.', 'Celebrates the immortal stone sculptures of master artists Mallitamma and Dasoja and the patron Queen Shantala Devi, an accomplished classical dancer.', 'To showcase India''s finest classical dancers against the UNESCO World Heritage star-shaped temples of Chennakeshava and Hoysaleshwara.', 'The temples are renowned for their unbelievable soapstone filigree: intricate dancing maidens (Madanikas), charging elephants, and lace-like stone screens.', 'Features classical Bharatanatyam, Odissi, Kathak, and Mohiniyattam performed on a floodlit stage on the temple lawns.', ARRAY['Nightly classical dance recitals by living legends of Indian arts staged against the star-shaped temple', 'Guided architectural walking tours explaining the miniature soapstone carving techniques', 'Illumination of the 12th-century stone temple plinths and carved star-shaped platforms']::TEXT[], 'Connoisseurs sit beneath cool night skies, captivated as classical dancers mirror the exact sculpturesque poses of the 900-year-old stone Madanika maidens.', ARRAY['Bisi Bele Bath', 'Akki Roti with Chutney', 'Mysore Pak', 'Dharwad Peda', 'Filter Coffee']::TEXT[], 'Formal Indian ethnic wear: handloom silk sarees, kurtas with dhotis, and light evening shawls.', 'Sublime classical Carnatic music, mridangam rhythms, flute melodies, and classical dance dramas.', 'Star-shaped soapstone temple platforms, filigree Madanika dancing figures, and golden spotlights.', '3 Days', 'Gregorian / Spring', 'Held in March annually.', 'March', 'ORGANIZER_ANNOUNCED', 'Announced annually by Karnataka Tourism & Hassan District Administration.', '2026-03-13', '2027-03-12', 'Department of Tourism Karnataka & ASI', ARRAY['Karnataka']::TEXT[], ARRAY['Halebidu', 'Belur', 'Hassan']::TEXT[], ARRAY['Hoysaleshwara Temple Halebidu', 'Chennakeshava Temple Belur']::TEXT[], 'Evenings between 6 PM and 9 PM during the floodlit dance concerts and daytime for sculptural exploration', 2, 'Aesthetic perfection: sitting before 900-year-old soapstone carvings of astonishing intricate lace-like detail, immersed in sublime classical temple dance.', 'Hassan railway station is 30 km away; 200 km west of Bengaluru Airport via 4-lane highway.', 'Heritage resorts, plantation homestays, and hotels in Hassan and Belur.', 'Pleasant spring weather; flat stone walking areas around temples.', 'Strict archaeological protection: no touching delicate soapstone carvings; photography permitted without flash.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karnatakatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-banashankari-jatre', 'Banashankari Jatre Badami', ARRAY['Tilakaranya Banashankari Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & Rural Carnival)', 'The massive month-long rural temple fair celebrated at the 7th-century shrine of Goddess Banashankari (Mother of the Forest) on the sacred Haridra Tirtha tank.', 'Ancient shrine dating back to 603 CE, established by the early Chalukya kings in the sacred forest of Tilakaranya.', 'Commemorates Goddess Shakambhari (Banashankari) slaying the demon Durgamasura to relieve a catastrophic famine with green herbs.', 'To seek the blessings of the Mother of the Forest for agricultural fertility, child protection, and family prosperity.', 'The largest rural fair in northern Karnataka, attracting hundreds of thousands of villagers, nomadic performers, and rural merchants.', 'Famous for the grand pulling of the multi-storey wooden chariot (Rath) around the sacred Haridra Tirtha, surrounded by stone lamp towers (Deepa Stambhas).', ARRAY['Pulling of the towering wooden temple chariot (Rath) by thousands of rural devotees on Pushya Purnima', 'Holy bath and floating of oil lamps in the ancient rectangular Haridra Tirtha stone tank', 'Month-long rural trade fair famous for traditional agricultural implements, handloom textiles, and cattle']::TEXT[], 'The ancient temple grounds buzz with rural vitality: giant wooden Ferris wheels, nomadic folk musicians, brass utensil bazaars, and sizzling sweet shops.', ARRAY['Jolada Roti with Shenga Chutney', 'Churmuri', 'Mirchi Bajji', 'Sweet Jalebi', 'Badami Peda']::TEXT[], 'Vibrant rural attire: Ilkal handloom sarees with Chikki Paras borders, colorful dhotis, and traditional headscarves.', 'Rural folk songs, continuous chanting of ''Banashankari Devi Ki Jai'', Shehnai, and energetic Dholak rhythms.', 'Ancient Haridra Tirtha stone water tank, towering stone Deepa Stambha lamp pillars, and multi-storey wooden chariot.', '1 Month', 'Hindu Lunisolar', 'Begins on Pushya Purnima (January - February) and lasts for four weeks.', 'January - February', 'LUNISOLAR', 'Begins on Pushya Purnima.', '2026-02-01', '2027-01-22', 'Banashankari Temple Trust & Bagalkot Administration', ARRAY['Karnataka']::TEXT[], ARRAY['Badami', 'Cholachagudda', 'Bagalkot']::TEXT[], ARRAY['Banashankari Amma Temple Cholachagudda']::TEXT[], 'Pushya Purnima day for the grand chariot pulling (Rathotsava) and evening illuminated tank strolls', 2, 'Authentic, unvarnished rural North Karnataka culture: ancient stone tank reflecting stone lamp pillars, colorful village crowds, and infectious folk joy.', '5 km from Badami railway station; easily reached by auto-rickshaw or local bus.', 'Hotels and heritage resorts in Badami town.', 'Vast rural crowds on Rathotsava day; stay clear of the heavy chariot wheels during the procession.', 'Buy authentic handloom Ilkal sarees directly from local weaver stalls set up during the fair.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bagalkot.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-godachi-jatre', 'Godachi Jatre Belagavi', ARRAY['Veerabhadra Temple Fair Godachi']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Veerashaiva Heritage)', 'The historic annual fair celebrated at the 12th-century Veerabhadra Temple in Godachi, famous for the colossal community offering of 56 sacred delicacies (Chhappan Bhog).', 'Dates back centuries to the Vijayanagara and Peshwa eras, honoring Lord Veerabhadra, the fierce martial manifestation of Lord Shiva.', 'Celebrates the triumph of divine righteousness over arrogant ritualism (slaying of Daksha Prajapati).', 'To seek protection from enemies, cure physical ailments, and pray for family health.', 'Renowned across northern Karnataka for the ''Chhappan Bhog'', where thousands of rural families prepare 56 different traditional dishes to offer to the deity.', 'Devotees perform the traditional ''Guggalu'' ritual, carrying blazing brass pots filled with burning camphor and incense on their bare heads.', ARRAY['Guggalu ritual: carrying blazing brass fire-pots on head in devotional trance', 'Chhappan Bhog: offering of 56 traditional homemade dishes to Lord Veerabhadra', 'Grand pulling of the historic wooden chariot (Brahma Rathotsava) through Godachi streets']::TEXT[], 'Thousands of devotees gather in the rural village, cheering as the wooden chariot moves forward amidst clouds of camphor smoke and drumbeats.', ARRAY['Dharwad Peda', 'Belagavi Kunda (slow-cooked caramelized milk confection - GI Tagged)', 'Jolada Roti with Ennegai', 'Sweet Pongal']::TEXT[], 'White dhotis with red borders, saffron shawls, Lingayat Ishtalinga pendants, and traditional cotton sarees.', 'Resounding beats of traditional Sambal drums, horn blasts, and devotional Veerashaiva Vachana singing.', 'Historic stone temple shikhara, blazing brass Guggalu fire-pots, and wooden temple chariot.', '3 Days', 'Hindu Lunisolar', 'Margashirsha month (December)', 'December', 'LUNISOLAR', 'Celebrated in Margashirsha month.', '2026-12-18', '2027-12-07', 'Veerabhadra Temple Trust Godachi & Belagavi Administration', ARRAY['Karnataka']::TEXT[], ARRAY['Godachi', 'Ramdurg', 'Belagavi']::TEXT[], ARRAY['Veerabhadra Temple Complex Godachi']::TEXT[], 'Rathotsava day and evening for the dramatic Guggalu fire-pot procession', 1, 'Powerful rural Shaivite devotion, rich community culinary offerings, fragrant camphor smoke, and warm North Karnataka village fellowship.', '80 km from Belagavi city; accessible by road via Ramdurg.', 'Hotels in Belagavi city; simple guest rooms in Ramdurg.', 'Rural fair setting; follow queue lines inside the temple sanctum.', 'Taste the legendary GI-tagged ''Belagavi Kunda'' at authentic local sweet shops in the region.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://belagavi.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-onam-kerala', 'Onam Statewide', ARRAY['Thiruvonam', 'Grand Harvest Festival of Kerala']::TEXT[], 'Harvest & Agriculture', 'Secular / Kerala Civilizational Identity', 'The national festival of Kerala celebrated by all communities, welcoming the mythical benevolent King Mahabali with intricate floral carpets (Pookkalam) and the grand Onasadya feast.', 'Ancient harvest festival celebrated for millennia, commemorating the mythical golden age of King Mahabali (Maveli) when all human beings lived in absolute equality, prosperity, and truth.', 'Celebrates the annual return of King Mahabali from the netherworld (Pathala) to visit his beloved subjects in Kerala.', 'To celebrate agricultural abundance, human equality, social harmony, and familial love.', 'Transcends all religious boundaries: celebrated with equal passion by Hindus, Christians, and Muslims across Kerala and the global Malayali diaspora.', 'Features the iconic ''Pookkalam'' (intricate geometric floral carpets laid out at household entrances using fresh flower petals for 10 days).', ARRAY['Designing intricate ten-ring floral carpets (Pookkalam) with fresh blossoms at home entrances', 'Preparation and communal feasting on the 26-dish grand vegetarian Onasadya served on fresh banana leaves', 'Traditional performing arts including Pulikali (tiger dance), Vallamkali (snake boat race), and Thiruvathira dance']::TEXT[], 'The entire state of Kerala dresses in traditional cream-and-gold handlooms, celebrating with grand family feasts, boat races, and village games (Onakalikal).', ARRAY['Grand Onasadya feast (26 dishes: Parippu, Sambar, Avial, Thoran, Olan, Kalan, Pachadi, Injipuli, Payasam in 4 varieties)', 'Palada Payasam', 'Banana Chips (Upperi)', 'Sharkara Varatti']::TEXT[], 'Traditional Kasavu handloom attire: cream-colored Kasavu sarees with woven gold Zari borders for women; crisp white Kasavu Mundu (dhoti) and shirt for men.', 'Graceful Thiruvathirakali circular clapping dance by women around brass lamps, high-energy Chenda Melam drumming, and Pulikali tiger dance.', 'Intricate geometric floral carpet (Pookkalam), King Mahabali with palm-leaf umbrella, tall brass Nilavilakku lamp, and banana leaf feast.', '10 Days (Atham to Thiruvonam)', 'Malayalam Solar Calendar (Kollam Era)', 'Month of Chingam (August - September) culminating on Thiruvonam day.', 'August - September', 'SOLAR', 'Culminates on Thiruvonam day in Chingam month.', '2026-08-26', '2027-09-13', 'Department of Tourism Government of Kerala', ARRAY['Kerala']::TEXT[], ARRAY['Thiruvananthapuram', 'Kochi', 'Thrissur', 'Kottayam', 'Kozhikode']::TEXT[], ARRAY['Thrikkakara Vamana Temple Kochi', 'Kanakakkunnu Palace Trivandrum', 'Swaraj Round Thrissur']::TEXT[], 'Thiruvonam day for the grand family Onasadya feast and the fourth Onam day for Pulikali tiger dance in Thrissur', 3, 'Pure cultural paradise: fragrant fresh floral carpets, cream-and-gold handlooms, mouthwatering 26-dish banana leaf banquets, and God''s Own Country in full bloom.', 'Kochi, Thiruvananthapuram, Kozhikode, and Kannur International Airports; extensive rail and road connectivity.', 'Hotels, backwater resorts, and heritage homestays across Kerala; book 2-3 months in advance for Onam week.', 'Government offices and banks are closed during Onam holidays; tourist attractions remain bustling with special cultural carnivals.', 'Experience an authentic multi-course Onasadya at traditional heritage restaurants or local homestays; eat using right hand on banana leaf.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-thrissur-pooram', 'Thrissur Pooram', ARRAY['Festival of Festivals Kerala']::TEXT[], 'Spiritual & Temple', 'Hinduism (Temple Pageantry & Percussion)', 'The most magnificent temple festival on earth, where 30 caparisoned elephants, 250 master percussionists, and a million spectators assemble at Vadakkunnathan Temple.', 'Created in 1798 CE by Raja Rama Varma (popularly Sakthan Thampuran), the visionary ruler of Cochin who unified ten neighboring temples into one grand friendly competition.', 'Celebrates the annual assembly of deities paying homage to Lord Shiva at the ancient Vadakkunnathan Temple atop Thekkinkadu Maidan.', 'To celebrate social unity, peerless classical percussion ensembles, and magnificent temple artistic craftsmanship.', 'Famous for the friendly rivalry between the two temple factions: Paramekkavu Bagavathi Temple and Thiruvambadi Sri Krishna Temple.', 'Features the legendary ''Ilanjithara Melam''—the largest live acoustic percussion symphony on earth, led by 250 master artists playing Chenda, Ilathalam, Kurumkuzhal, and Kombu.', ARRAY['Grand face-off (Kudamattom) between 30 caparisoned elephants exchanging hundreds of dazzling silk umbrellas', 'Ilanjithara Melam: 250-member synchronized traditional percussion ensemble playing beneath the ancient Ilanji tree', 'Epic midnight and dawn fireworks display (Vedikkettu) shaking the entire city of Thrissur']::TEXT[], 'The sprawling Thekkinkadu Maidan turns into an ocean of hundreds of thousands of people, raising hands in synchronized rhythm to thundering Chenda beats.', ARRAY['Traditional Kerala Sadya', 'Unniyappam', 'Neyyappam', 'Ada Pradhaman', 'Avil Milk of Thrissur']::TEXT[], 'Traditional cream-and-gold Kasavu Mundu with Angavastram for men, Kasavu sarees for women, and sunglasses for daytime sun.', 'Unrivaled classical percussion: Pandi Melam, Panchavadyam (five temple instruments), thunderous Chenda beats, and Kombu horn blasts.', '30 caparisoned tuskers wearing pure gold forehead plates (Nettipattam), multi-colored silk umbrellas (Kuda), white yak-tail whisks (Venchamaram), and peacock-feather fans (Aalavattam).', '36 Hours (Main Day + Night)', 'Malayalam Solar Calendar', 'Medam month on Pooram Nakshatra (April - May)', 'April - May', 'LUNISOLAR', 'Celebrated on Pooram star in the Malayalam month of Medam.', '2026-04-27', '2027-05-16', 'Paramekkavu & Thiruvambadi Devaswoms & Cochin Devaswom Board', ARRAY['Kerala']::TEXT[], ARRAY['Thrissur']::TEXT[], ARRAY['Thekkinkadu Maidan', 'Vadakkunnathan Temple', 'Swaraj Round']::TEXT[], 'Afternoon between 2 PM and 6 PM for Ilanjithara Melam and Kudamattom umbrella exchange', 2, 'The ultimate acoustic and visual sensory climax: the ground shakes under 250 thundering drums, 30 golden elephants face off, and pure adrenaline sweeps through a million people.', 'Thrissur railway station connects to all major Indian cities; Kochi Airport is 55 km away via 4-lane highway.', 'Hotels throughout Thrissur are booked solid 6-9 months in advance; book well ahead or stay in Kochi/Ernakulam and travel by train.', 'Extreme crowd density (over 500,000 spectators on the maidan) and summer heat; stay hydrated; wear ear protection for sensitive ears during fireworks.', 'Maintain respectful distance from the elephants; follow police safety barricades strictly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://thrissur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-theyyam-festival-malabar', 'Theyyam Festival North Malabar', ARRAY['Dance of the Gods', 'Kaliyattam']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Folk Shaktism & Ancestral Worship', 'The awe-inspiring ancient ritual dance of North Malabar where mortal performers transform into living, breathing deities in fiery trances.', 'Pre-Aryan ritualistic tradition dating back over 2,000 years, documented in Sangam literature and celebrated across Kannur and Kasaragod districts.', 'Celebrates the manifestation of divine justice, ancestral spirits, and protective mother goddesses who vanquish evil and bless the village.', 'To seek direct prophecy, healing, and blessings from the living deity who speaks to devotees during the sacred trance.', 'Over 400 distinct forms of Theyyam exist (Muthappan, Pottan, Gulikan, Muchilot Bhagavathi, Raktha Chamundi), each with unique mythology and visual regalia.', 'Performers undergo rigorous fasting and spend hours having intricate geometric face-paint applied using natural earth minerals before leaping into blazing pyres.', ARRAY['Intricate facial painting (Mukhathezhuthu) using crushed stone pigments and natural orange/red hues', 'Headdress erection: balancing towering, 30-foot bamboo and cloth crowns (Mudi) on head', 'Fiery trance rituals: running through and rolling over massive piles of red-hot wooden embers (Thee Chamundi)']::TEXT[], 'Village shrines (Kavus) surrounded by sacred groves glow in the night with blazing torches, as thundering drums announce the arrival of the living god.', ARRAY['Traditional Malabar feast', 'Payasam', 'Puttu with Kadala Curry', 'Neer Dosa', 'Tender Coconut']::TEXT[], 'Colossal red costumes made of woven palm fronds, towering feathered headdresses, heavy brass armlets, and jingling ankle bells (Chilambu).', 'Thunderous, fast-tempo beats of Chenda and Ilathalam cymbals, accompanied by the hypnotic chanting of Tottam ballads.', 'Towering 30-foot red cloth headdress (Mudi), flaming wooden torches (Chool), red-hot ember pits, and sacred forest grove.', 'All-Night (Season from Oct to May)', 'Malayalam Solar Calendar', 'Celebrated continuously on winter and spring nights across North Malabar sacred groves.', 'October - May', 'SEASONAL', 'Peak performances occur between December and March.', '2026-12-15', '2027-12-15', 'Malabar Tourism & Sacred Kavu Devaswom Committees', ARRAY['Kerala']::TEXT[], ARRAY['Kannur', 'Kasaragod', 'Nileshwar', 'Payyanur']::TEXT[], ARRAY['Parasshinikadavu Muthappan Temple', 'Village Kavus across Malabar']::TEXT[], 'Night from 10 PM to 6 AM at a village Kavu when fire Theyyam rituals take place', 2, 'Hair-raising, transcendent spiritual intensity: standing feet away from a towering, painted living god walking through roaring flames in a sacred rainforest grove.', 'Kannur International Airport; well connected by mainline Konkan railway stations (Kannur, Kasaragod).', 'Hotels in Kannur city or authentic beachside homestays and heritage retreats in Nileshwar.', 'All-night outdoor ritual in rural sacred groves; carry a flashlight, mosquito repellent, and water; wear modest clothing.', 'Show supreme reverence: the performer is treated not as an actor, but as the living embodiment of the divine; approach for blessings with folded hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kannur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-attukal-pongala', 'Attukal Pongala Thiruvananthapuram', ARRAY['Women''s Sabarimala', 'Largest Gathering of Women']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & Divine Motherhood)', 'The Guinness World Record-setting festival where over four million women congregate across the streets of Thiruvananthapuram to cook sweet rice offerings for the Goddess.', 'Ancient Shakta tradition centered around the Attukal Bhagavathy Temple, honoring Kannagi (heroine of the Tamil epic Silappathikaram) as the supreme Mother Goddess.', 'Commemorates the welcoming of Goddess Kannagi after her righteous destruction of injustice, offering her sweet nourishment.', 'To offer sweet boiled rice (Pongala) in new earthen pots and seek health, prosperity, and the protection of the Divine Mother.', 'Guinness World Record holder for the single largest gathering of women in human history (over 4.5 million women in a single day).', 'The entire capital city of Thiruvananthapuram transforms into an enormous open-air holy kitchen, with brick hearths lining every street, lane, and sidewalk for miles.', ARRAY['Ceremonial lighting of the first hearth fire (Pandara Aduppu) from the temple sanctum lamp', 'Simultaneous cooking of sweet rice, jaggery, and coconut pudding in millions of clay pots on brick hearths', 'Showering of holy water (Theertham) by hundreds of priests blessing all pots simultaneously at afternoon aarti']::TEXT[], 'Millions of women dressed in traditional cotton clothes tend crackling wood hearths, cooking sweet Pongala while sweet aromas of jaggery and ghee engulf the city.', ARRAY['Attukal Pongala (sweet rice boiled with jaggery, coconut, ghee, and cardamom)', 'Mandakappam', 'Therali (steamed rice cake wrapped in bay leaf)', 'Parippu Payasam']::TEXT[], 'Traditional Kerala Kasavu cotton sarees, simple cotton salwar suits, and cotton towels to shield from fire smoke.', 'Devotional singing of Kannagi Charitham, temple Shehnai, conch blasts, and women''s prayer choruses.', 'New earthen clay pots (Kalam), three-brick open hearths, sugarcane, sweet jaggery syrup, and Attukal temple spires.', '10 Days (Main Pongala on Day 9)', 'Malayalam Solar Calendar', 'Month of Kumbham (February - March) on Pooram Nakshatra.', 'February - March', 'LUNISOLAR', 'Main Pongala day falls on Pooram star in Kumbham.', '2026-03-03', '2027-02-21', 'Attukal Bhagavathy Temple Trust & Thiruvananthapuram Police', ARRAY['Kerala']::TEXT[], ARRAY['Thiruvananthapuram']::TEXT[], ARRAY['Attukal Bhagavathy Temple', 'Citywide streets across Trivandrum']::TEXT[], 'Pongala day from 10 AM (lighting of hearths) to 2:30 PM (sanctified water blessing)', 2, 'Unbelievable, humbling testament to feminine spiritual power, sisterhood, and devotion: an entire state capital transformed into a four-million-strong holy kitchen.', 'Thiruvananthapuram International Airport and Central Railway Station; entire city center is pedestrianized for women''s hearths.', 'Hotels throughout Thiruvananthapuram are booked months in advance; book early or stay in Kovalam.', 'Exclusively women participate in cooking Pongala; male travelers can observe with respectful courtesy from designated areas.', 'Extreme heat from millions of open cooking fires; drink plenty of water; wear light cotton clothing and carry a sun umbrella.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://attukal.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nehru-trophy-boat-race', 'Nehru Trophy Boat Race Alappuzha', ARRAY['Kuttanad Snake Boat Carnival']::TEXT[], 'Art & Cultural Festival', 'Secular / Aquatic Sports & Coastal Unity', 'The world''s most thrilling water regatta where 100-foot-long wooden Snake Boats (Chundan Vallams), powered by 100 synchronized oarsmen, race across Punnamada Lake.', 'Initiated in December 1952 when Prime Minister Jawaharlal Nehru visited Alappuzha and was so mesmerized by an impromptu boat race that he donated a silver trophy.', 'Celebrates the ancient naval warfare heritage, boat-building craftsmanship, and village camaraderie of the backwaters.', 'To compete for the prestigious silver replica of a snake boat bearing Jawaharlal Nehru''s autographed trophy.', 'The Chundan Vallams are 100 to 120 feet long with raised sterns resembling a cobra''s hood, crewed by 100 oarsmen, 4 helmsmen, and 8 singers.', 'The oarsmen row in furious, lightning-fast unison to the rhythmic beat of Vanchipattu (boat songs) sung by lead singers standing in the center.', ARRAY['Ceremonial inaugural procession of decorated houseboats and cultural floats on Punnamada Lake', 'Preliminary heats of traditional canoe categories (Chundan, Churulan, Veppu, Odi)', 'Thunderous grand finale race of the Chundan Vallams with thousands of oars slicing through the water']::TEXT[], 'Over 200,000 spectators pack lakeside pavilions and houseboats, roaring with excitement as four giant snake boats speed down the 1.4-kilometer track.', ARRAY['Karimeen Pollichathu (pearl spot fish wrapped in banana leaf)', 'Appam with Stew', 'Kerala Duck Roast', 'Puttu with Kadala Curry', 'Tender Coconut']::TEXT[], 'Traditional white Kasavu Mundu with shirts, comfortable summer casuals, sunglasses, and sun hats.', 'Thrilling, fast-paced Vanchipattu boat songs sung in rhythmic chorus, accompanied by clashing bronze cymbals.', '120-foot wooden Chundan Vallam snake boat, raised cobra-hood stern, rhythmic wooden oars, and silver Nehru trophy.', '1 Day', 'Gregorian / Monsoon', 'Second Saturday of August annually.', 'August', 'FIXED', 'Held annually on the second Saturday of August.', '2026-08-08', '2027-08-14', 'Nehru Trophy Boat Race Society & Alappuzha Administration', ARRAY['Kerala']::TEXT[], ARRAY['Alappuzha (Alleppey)']::TEXT[], ARRAY['Punnamada Lake Alappuzha']::TEXT[], 'Afternoon between 1:30 PM and 5:30 PM during the heats and grand final races', 2, 'Electrifying adrenaline rush on tranquil backwaters: 400 synchronized oars churning the water to high-speed songs, amidst thunderous cheers from thousands.', 'Alappuzha railway station is well connected; Kochi Airport is 85 km away via highway.', 'Heritage houseboats, lakeside resorts, and boutique hotels in Alappuzha; book months in advance.', 'Very crowded spectator pavilions; purchase official ticketed gallery passes (Rose Corner, Gold Corner) online in advance.', 'Monsoon showers frequent in August; carry waterproof raincoats and protective bags for cameras.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://nehrutrophy.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-vishu-kerala', 'Vishu Statewide', ARRAY['Malayalam New Year', 'Astronomical Equinox']::TEXT[], 'Seasonal & Nature', 'Hinduism (Solar New Year & Prosperity)', 'The radiant harvest and astrological New Year festival of Kerala celebrated with the golden ''Vishu Kani'' altar, elders gifting gold coins, and joyful fireworks.', 'Ancient solar festival marking the astronomical vernal equinox when the Sun enters the zodiac sign of Aries (Medam) in the Malayalam calendar.', 'Celebrates the promise of agricultural abundance, new beginnings, and family blessings for the coming year.', 'To open one''s eyes first upon the auspicious golden Vishu Kani altar at dawn to ensure an entire year of prosperity.', 'The ''Vishu Kani'' is lovingly arranged by the mother the night before: a bell-metal vessel (Uruli) containing raw rice, golden cucumber, yellow Kani Konna flowers, gold coins, and a mirror.', 'Features the cherished tradition of ''Vishu Kaineettam'', where family elders distribute auspicious gift coins and currency to all younger members.', ARRAY['Opening eyes at dawn to behold the auspicious Vishu Kani altar with lit oil lamps', 'Vishu Kaineettam: elders blessing children and distributing coins and currency notes', 'Bursting of morning firecrackers (Vishu Padakkam) and enjoying the family Vishu Sadya feast']::TEXT[], 'Homes are filled with golden yellow Kani Konna blossoms, children celebrate with firecrackers, and families feast on traditional festive delicacies.', ARRAY['Vishu Kanji (savory rice and coconut porridge)', 'Vishu Katta (sweet rice cake served with jaggery syrup)', 'Mampazha Pulissery (ripe mango curry)', 'Jackfruit Payasam', 'Vishu Sadya']::TEXT[], 'Traditional cream-and-gold Kasavu handloom Mundu and Neriyathu for women, and Kasavu Mundu for men.', 'Traditional temple Nadaswaram, devotional Krishna bhajans, and festive celebratory folk singing.', 'Golden shower tree blossoms (Kani Konna - Cassia fistula), bell-metal Uruli vessel, golden cucumber, and glowing brass Nilavilakku lamp.', '1 Day', 'Malayalam Solar Calendar', 'First day of the Malayalam month of Medam (April 14 or 15).', 'April', 'SOLAR', 'Celebrated on the first day of Medam month (April 14-15 annually).', '2026-04-14', '2027-04-15', 'Travancore Devaswom Board & Department of Culture Kerala', ARRAY['Kerala']::TEXT[], ARRAY['Thiruvananthapuram', 'Kochi', 'Guruvayur', 'Kozhikode']::TEXT[], ARRAY['Guruvayur Sri Krishna Temple', 'Sabarimala Temple', 'Family homes']::TEXT[], 'Early morning dawn hours (4:30 AM to 6:30 AM) for viewing the sacred Vishu Kani', 1, 'Pure golden warmth, gentle family affection, radiant yellow blossoms everywhere, and the hopeful promise of a prosperous new beginning.', 'Easily accessible across Kerala via train, bus, and flight.', 'Hotels throughout Kerala; book early for temple towns like Guruvayur.', 'Morning firecrackers around residential neighborhoods; exercise safety with children.', 'Visit Guruvayur Sri Krishna Temple or local shrines where special public Vishu Kani altars are displayed.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-makaravilakku-sabarimala', 'Makaravilakku Sabarimala', ARRAY['Makara Jyothi Darshan']::TEXT[], 'Spiritual & Temple', 'Hinduism (Ayyappa Devotion & Forest Austerity)', 'The sacred climax of the two-month Sabarimala pilgrimage where millions of black-clad Ayyappa devotees witness the celestial Makara Jyothi flame atop Ponnambalamedu hill.', 'Ancient pilgrimage documented in the Skanda Purana, nestled in the dense evergreen rainforests of the Periyar Tiger Reserve.', 'Commemorates Lord Ayyappa (Dharma Sastha) uniting with the supreme light after defeating the demoness Mahishi.', 'To fulfill the rigorous 41-day austerity vow (Vrutham) and climb the sacred 18 gold-plated steps (Pathinettampadi) carrying the Irumudi basket.', 'One of the largest annual pilgrimages in human history, attracting over 30 million devotees from across southern India.', 'At exact dusk on Makar Sankranti, the deity is adorned with sacred royal jewels (Thiruvabharanam) and a miraculous celestial flame flashes three times atop distant mountain ridges.', ARRAY['Carrying the sacred two-compartment cloth basket (Irumudi) containing ghee-filled coconuts on the head', 'Climbing the sacred 18 gold-plated steps (Pathinettampadi) chanting ''Swamiye Saranam Ayyappa''', 'Beholding the three flashes of the sacred Makara Jyothi flame atop distant Ponnambalamedu hill at dusk']::TEXT[], 'The mist-shrouded mountain valley reverberates with the thunderous roar of millions chanting ''Swamiye Saranam Ayyappa'' as the celestial light flashes in the night sky.', ARRAY['Aravana Payasam (thick dark jaggery-rice dessert of Sabarimala - GI Tagged)', 'Appam prasad', 'Parippu Kanchi', 'Poha']::TEXT[], 'Black or dark blue dhotis, Tulsi or Rudraksha beads, and bare feet symbolizing complete detachment from ego.', 'Continuous thunderous chanting of ''Swamiye Saranam Ayyappa'', temple bells, and soulful Harivarasanam lullaby at closing.', 'Sacred 18 gold-plated steps (Pathinettampadi), two-compartment Irumudi cloth bag, ghee coconuts, and Makara Jyothi flame.', '3 Days (Climax of 41-Day Season)', 'Solar / Makar Sankranti', 'Makar Sankranti evening (January 14 or 15 annually).', 'January', 'FIXED', 'Celebrated on Makar Sankranti evening.', '2026-01-14', '2027-01-14', 'Travancore Devaswom Board & Kerala Police', ARRAY['Kerala']::TEXT[], ARRAY['Sabarimala', 'Pathanamthitta']::TEXT[], ARRAY['Sabarimala Sannidhanam', 'Pampa River Base', 'Ponnambalamedu Viewpoints']::TEXT[], 'Dusk (5:30 PM to 7 PM) on Makar Sankranti for the Thiruvabharanam darshan and Makara Jyothi sighting', 2, 'Overwhelming spiritual magnitude: standing among millions of black-clad seekers in a wild mountain forest, united in a deafening roar of absolute surrender to the divine.', 'Pampa base camp is 135 km from Kochi and 160 km from Trivandrum; from Pampa, pilgrims hike 5 km uphill on foot to Sannidhanam.', 'Pilgrim shelters at Sannidhanam and Pampa; hotels in Kottayam, Pathanamthitta, and Chengannur.', 'Monumental crowds exceeding two million on Makaravilakku day; strictly follow police movement guidelines; stay off precarious tree branches.', 'Devotees must observe 41 days of strict celibacy, vegetarianism, and morning-evening prayers before undertaking the pilgrimage.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://sabarimala.kerala.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-aranmula-boat-race', 'Aranmula Uthrattathi Vallamkali', ARRAY['Aranmula Temple Regatta']::TEXT[], 'Spiritual & Temple', 'Hinduism & Sacred Temple Regatta', 'The sacred water festival celebrated on the holy Pamba River at the 1,000-year-old Aranmula Parthasarathy Temple, where boat songs replace competition.', 'Centuries-old temple tradition commemorating the day Lord Krishna (Parthasarathy) crossed the river to rescue an impoverished devotee who offered him a humble feast.', 'Celebrates divine compassion, village temple solidarity, and the ancient art of temple snake-boat craftsmanship.', 'To offer boat songs and sacred rowed tributes to Lord Parthasarathy on the anniversary of the temple idol consecration.', 'Unlike commercial boat races, the Aranmula regatta is not a competitive race, but a sacred water pageant where 52 village snake boats (Palliyodams) row together in worship.', 'Famous for the legendary ''Valla Sadya''—a colossal ritual banquet featuring over 64 traditional dishes served to oarsmen inside the temple.', ARRAY['Rowing of 52 traditional village snake boats (Palliyodams) down the sacred Pamba River in synchronized pairs', 'Singing of sacred Vanchipattu boat hymns praising Lord Krishna and ancient epics', 'Serving the grand 64-dish Valla Sadya feast to hundreds of oarsmen inside the temple courtyard']::TEXT[], 'Tens of thousands of devotees line the lush green riverbanks, chanting praises as majestic wooden snake boats glide in solemn grace with fluttering flags.', ARRAY['Aranmula Valla Sadya (epic 64-dish traditional feast)', 'Palada Payasam', 'Aranmula Ada', 'Fried banana chips', 'Nendran banana']::TEXT[], 'Pristine white cotton Kasavu Mundu with gold borders, white towels, and sandal marks on forehead.', 'Solemn, beautiful classical Vanchipattu boat hymns sung in call-and-response rhythm with bronze cymbals.', '52 sacred village Palliyodams with golden prows, ancient Parthasarathy temple gopuram, and Pamba riverbanks.', '1 Day', 'Malayalam Solar Calendar', 'Month of Chingam (August - September) on Uthrattathi Nakshatra.', 'August - September', 'LUNISOLAR', 'Celebrated on Uthrattathi star during Onam season.', '2026-08-30', '2027-09-17', 'Palliyoda Seva Sangham & Travancore Devaswom Board', ARRAY['Kerala']::TEXT[], ARRAY['Aranmula', 'Pathanamthitta', 'Chengannur']::TEXT[], ARRAY['Aranmula Parthasarathy Temple', 'Pamba Riverfront']::TEXT[], 'Midday (11:30 AM to 3 PM) for the river pageant and Valla Sadya feast', 1, 'Serene, deeply devotional temple regatta: majestic snake boats gliding gracefully across calm river waters, filled with soaring classical hymns and temple feasts.', 'Chengannur railway station (10 km); Kochi Airport is 115 km away via highway.', 'Riverside homestays in Aranmula or hotels in Chengannur and Pathanamthitta.', 'Monsoon river currents; stay behind bamboo safety railings along riverbanks.', 'Visit local artisan workshops in Aranmula to see the making of the world-famous GI-tagged ''Aranmula Kannadi'' (metal mirrors).', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chembai-sangeetholsavam', 'Chembai Sangeetholsavam Guruvayur', ARRAY['Guruvayur Carnatic Music Festival']::TEXT[], 'Art & Cultural Festival', 'Carnatic Classical Music Heritage', 'The prestigious 15-day festival of Carnatic classical music held at Guruvayur Temple, where over 3,000 musicians perform as an offering to Lord Guruvayurappan.', 'Established in memory of legendary Carnatic vocalist Chembai Vaidyanatha Bhagavatar (1896-1974), who dedicated his lifetime of musical genius to Lord Krishna.', 'Celebrates the divine offering of classical music (Naada Upasana) and the rich traditions of Carnatic vocal and instrumental art.', 'To sing and play classical ragas before Lord Guruvayurappan as a humble spiritual prayer without commercial fees.', 'One of the largest gatherings of classical musicians in India: everyone from renowned maestros (Padma awardees) to beginner students performs on the same stage.', 'Culminates on Guruvayur Ekadashi with the mass choral singing of the immortal Pancharatna Kritis of Saint Tyagaraja by hundreds of musicians in unison.', ARRAY['Consecutive 15-day round-the-clock classical music concerts from 6 AM to midnight', 'Mass choral rendition of Saint Tyagaraja''s Pancharatna Kritis on Guruvayur Ekadashi night', 'Special Panchavadyam and elephant procession (Seeveli) at Guruvayur Temple']::TEXT[], 'Audiences and musicians sit in the open-sided Melpathur Auditorium outside the temple, enraptured by continuous classical melodies flowing day and night.', ARRAY['Guruvayur Palpayasam (thick slow-cooked milk pudding)', 'Neyyappam', 'Avil prasad', 'Vegetarian Kerala feast']::TEXT[], 'Traditional white Kasavu Mundu with Angavastram for men, and elegant Kasavu sarees for women.', 'Pure classical Carnatic vocal, violin, veena, flute, mridangam, ghatam, and morsing concerts.', 'Melpathur Auditorium stage, oil lamps, portrait of Chembai Bhagavatar, and gold-roofed Guruvayur temple.', '15 Days', 'Hindu Lunisolar', 'Culminates on Guruvayur Ekadashi (Vrischika month in November - December)', 'November - December', 'LUNISOLAR', 'Culminates on Guruvayur Ekadashi.', '2026-12-08', '2027-11-28', 'Guruvayur Devaswom Board', ARRAY['Kerala']::TEXT[], ARRAY['Guruvayur', 'Thrissur']::TEXT[], ARRAY['Melpathur Auditorium Guruvayur Temple']::TEXT[], 'Guruvayur Ekadashi night for the mass singing of the Pancharatna Kritis', 3, 'Sublime acoustic and spiritual bliss: an unbroken 15-day river of pure classical melody flowing directly into the presence of the divine.', 'Guruvayur railway station connects from Thrissur; Kochi Airport is 80 km away via 4-lane highway.', 'Devaswom guest houses, luxury hotels, and dharamshalas surrounding the temple; early booking recommended.', 'Concerts are open to all visitors free of charge; maintain pin-drop silence during recitals.', 'Strict dress code inside Guruvayur Temple sanctum (men must wear mundu without shirts; women in sarees/dresses).', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://guruvayurdevaswom.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-parumala-perunnal', 'Parumala Perunnal', ARRAY['Feast of Saint Gregorios of Parumala']::TEXT[], 'Spiritual & Temple', 'Christianity (Malankara Orthodox Syrian Heritage)', 'The sacred annual feast and pilgrimage commemorating Saint Geevarghese Mar Gregorios (Parumala Thirumeni), the first canonized Christian saint of India.', 'Commemorates the passing of Saint Gregorios in 1902 CE at Parumala Seminary on the banks of the Pamba River; canonized as a saint in 1947.', 'Celebrates the life of prayer, humility, healing, and miraculous intercession of the beloved bishop-saint.', 'To walk barefoot on pilgrimage to the saint''s tomb, seek spiritual healing, and attend solemn liturgical services.', 'Draws over one million pilgrims of all faiths (Christians, Hindus, Muslims), who walk hundreds of kilometers across Kerala carrying prayer flags.', 'The unique circular church designed by celebrated architect Laurie Baker features exposed brickwork and natural ventilation.', ARRAY['Barefoot walking pilgrimage (Padayatra) from all parts of Kerala to Parumala Seminary', 'Solemn Holy Qurbana (Eucharistic Liturgy) concelebrated by the Catholicos and bishops', 'Veneration of the sacred tomb (Kabar) of Parumala Thirumeni']::TEXT[], 'Pilgrims wrapped in white clothes arrive singing ancient West Syriac hymns, lighting candles, and offering fragrant frankincense at the holy tomb.', ARRAY['Kerala Christian Feast dishes: Appam with Mutton Stew', 'Pork Roast', 'Kozhi Curry', 'Parippu Curry', 'Halwa']::TEXT[], 'Modest Sunday church wear: white shirts with trousers, traditional sarees, and head coverings for women.', 'Soulful West Syriac and Malayalam liturgical hymns, choir choral singing, and solemn brass bell chimes.', 'Circular brick architecture of Parumala Church, holy tomb of Saint Gregorios, and waving prayer flags.', '2 Days (Week of Pilgrimage)', 'Gregorian / Annual', 'November 1 and 2 annually (Feast day on November 2).', 'November', 'FIXED', 'Held annually November 1-2.', '2026-11-02', '2027-11-02', 'Malankara Orthodox Syrian Church & Parumala Seminary', ARRAY['Kerala']::TEXT[], ARRAY['Parumala', 'Mannar', 'Pathanamthitta', 'Chengannur']::TEXT[], ARRAY['Parumala Church & Seminary Complex']::TEXT[], 'November 2 morning for the solemn Holy Qurbana and grand circumambulation procession (Rasa)', 2, 'Deeply tranquil, tearful spiritual pilgrimage where ancient Syriac Christian chants blend with gentle Pamba river breezes and universal healing.', 'Chengannur railway station (10 km); accessible by road from Kochi (110 km) or Trivandrum (120 km).', 'Pilgrim rest houses in Parumala; hotels in Chengannur and Thiruvalla.', 'Large crowd density; follow designated walking paths around the tomb.', 'Maintain reverent silence inside the church; photography is restricted during the Holy Qurbana liturgy.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://parumalachurch.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nishagandhi-dance-festival', 'Nishagandhi Dance Festival Thiruvananthapuram', ARRAY['Kanakakkunnu Palace Cultural Fest']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Performing Arts', 'A prestigious seven-day festival of classical dance and music staged in the open-air amphitheatre of Kanakakkunnu Palace in the capital city of Kerala.', 'Initiated by Kerala Tourism to celebrate the finest traditions of classical Indian performing arts and promote cultural tourism.', 'Celebrates the diversity of India''s classical dance disciplines in an elegant royal palace garden setting.', 'To present leading classical dance maestros and confer the prestigious national Nishagandhi Puraskaram award.', 'Staged at the open-air Nishagandhi Amphitheatre, bordered by lush tropical foliage and illuminated royal palace facades.', 'Features master exponents of Bharatanatyam, Mohiniyattam, Kathak, Odissi, Kuchipudi, Manipuri, and Sattriya.', ARRAY['Nightly classical dance and vocal concerts by Padma and Sangeet Natak Akademi awardees', 'Grand food festival showcasing traditional culinary specialties of all 14 districts of Kerala', 'Conferment of the prestigious national Nishagandhi Puraskaram for lifetime contribution to arts']::TEXT[], 'Audiences sit beneath cool January evening skies, captivated as classical dancers perform intricate rhythm sequences to live Carnatic orchestras.', ARRAY['Malabar Biryani', 'Appam with Vegetable Stew', 'Parippu Vada', 'Sulaimani Tea', 'Palada Payasam']::TEXT[], 'Smart casuals, elegant cotton and silk sarees, kurtas, and evening shawls.', 'Classical Carnatic and Hindustani music, mridangam rhythms, flute melodies, and classical dance dramas.', 'Illuminated stone arches of Kanakakkunnu Palace, open-air amphitheatre stage, and glowing oil lamps.', '7 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Kerala Tourism.', '2026-01-20', '2027-01-20', 'Department of Tourism Government of Kerala', ARRAY['Kerala']::TEXT[], ARRAY['Thiruvananthapuram']::TEXT[], ARRAY['Nishagandhi Amphitheatre Kanakakkunnu Palace']::TEXT[], 'Evenings between 6 PM and 9:30 PM during classical dance concerts', 2, 'Cultured, sophisticated palace garden charm with cool night breezes, world-class classical performing arts, and delicious regional Kerala cuisine.', 'Centrally located in Thiruvananthapuram; easily reached by auto-rickshaw, cab, or bus.', 'Extensive hotels across Thiruvananthapuram and nearby beach resorts in Kovalam.', 'Pleasant winter evening temperatures; seating is on first-come basis; arrive 30 minutes early.', 'Free public admission; maintain pin-drop silence during classical dance performances.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-cochin-carnival', 'Cochin Carnival Fort Kochi', ARRAY['Fort Kochi New Year Carnival']::TEXT[], 'Art & Cultural Festival', 'Portuguese-Dutch Colonial Heritage & New Year Pageantry', 'The exuberant year-end carnival celebrated in historic Fort Kochi, culminating at midnight on New Year''s Eve with the burning of the giant 40-foot ''Papanji'' effigy.', 'Originates from the Portuguese colonial era (1503-1663), revived in 1984 during International Youth Year by local youth and cultural historians.', 'Celebrates the casting away of the old year''s sorrows and welcoming the New Year with boundless hope, merriment, and peace.', 'To promote communal harmony, youth creativity, and celebrate Fort Kochi''s multi-ethnic Portuguese, Dutch, British, and Jewish heritage.', 'The centerpiece is ''Papanji''—a colossal 40 to 60-foot effigy of an old Portuguese gentleman with white beard and European suit, packed with fireworks.', 'At exact midnight on New Year''s Eve, the massive Papanji is set ablaze on the beach amidst thunderous fireworks, cheers, and beach dancing.', ARRAY['Burning of the colossal Papanji effigy at midnight on December 31 on Fort Kochi Beach', 'Grand New Year''s Day street parade featuring costumed masqueraders, caparisoned elephants, and brass bands', 'Beach sports competitions, cycling races, and classical-rock fusion music concerts']::TEXT[], 'Over 300,000 people from all over the world crowd Fort Kochi beach and streets, counting down to midnight and dancing to live music.', ARRAY['Kerala Fish Curry Rice', 'Kochi Prawn Masala', 'Dutch-influenced Breudher bread', 'Appam with Chicken Stew', 'Bebinca']::TEXT[], 'Flamboyant masquerade costumes, colonial sailor outfits, colorful beach resort wear, and festival party hats.', 'High-voltage live rock bands, Latin samba rhythms, traditional Chenda Melam, and Western brass bands.', 'Colossal burning Papanji effigy, historic Chinese Fishing Nets, colonial heritage buildings, and beach fireworks.', '10 Days (Culminates on New Year''s Day)', 'Gregorian / Year-End', 'December 23 to January 1 annually.', 'December - January', 'FIXED', 'Peaks on December 31 night and January 1 parade.', '2026-12-31', '2027-12-31', 'Cochin Carnival Committee & Kerala Tourism', ARRAY['Kerala']::TEXT[], ARRAY['Kochi', 'Fort Kochi', 'Mattancherry']::TEXT[], ARRAY['Fort Kochi Beach', 'Parade Ground Fort Kochi', 'Vasco da Gama Square']::TEXT[], 'December 31 night from 10 PM to 1 AM for the midnight Papanji burning and beach countdown', 2, 'Electric, euphoric global beach celebration with centuries of colonial history, roaring bonfires, fireworks reflecting in the ocean, and joyous celebration.', 'Kochi International Airport (45 km); well connected by ro-ro ferries from Vypin and scenic water metro from Ernakulam.', 'Charming colonial boutique heritage hotels, art cafes, and homestays throughout Fort Kochi; book months ahead.', 'Monumental crowds on December 31 night; vehicular entry into Fort Kochi is strictly blocked from afternoon; rely on ferries and walking.', 'Keep the heritage beach clean; follow police crowd dispersal orders after the midnight burning.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-utsavam-kerala-arts', 'Utsavam Kerala Arts Festival', ARRAY['Folk & Traditional Arts Festival']::TEXT[], 'Art & Cultural Festival', 'Endangered Indigenous Performing Arts', 'A statewide seven-day festival organized simultaneously across all 14 districts of Kerala, showcasing over 5,000 artists in 150 rare and endangered traditional art forms.', 'Established by Kerala Tourism and Bharat Bhavan to preserve, document, and revitalize endangered indigenous folk, tribal, and classical art forms.', 'Celebrates Kerala''s extraordinary diversity of performing arts, ritual theatre, and indigenous music.', 'To provide direct financial livelihood to traditional master artists and introduce younger generations to living heritage.', 'Staged on public beaches, parks, and heritage grounds across all 14 district headquarters simultaneously.', 'Features rare, endangered arts including Koodiyattam (ancient Sanskrit theatre), Mudiyettu, Padayani, Chavittu Nadakam, and tribal dances.', ARRAY['Simultaneous open-air performances of 150+ traditional art forms across all 14 Kerala districts', 'Performances of UNESCO-recognized ancient Sanskrit theatre Koodiyattam and ritual Mudiyettu', 'Demonstrations by senior master artists of traditional drum carving, makeup, and mask-making']::TEXT[], 'Travelers stroll between open-air stages in city parks, mesmerized by masked demon dancers, Christian martial theatre, and hypnotic drum symphonies.', ARRAY['Traditional regional delicacies from each district', 'Unniyappam', 'Neer Dosa', 'Banana Fritters (Pazham Pori)', 'Spiced Buttermilk']::TEXT[], 'Casual travel wear, handloom cotton kurtas, and traditional Kerala attire.', 'Rare performing arts: Chavittu Nadakam (Latin Christian musical drama), Padayani, Koodiyattam, Duffmuttu, Oppana, and Margamkali.', 'Intricate Kathakali and Padayani facial masks, towering headgear, palm-leaf torches, and brass oil lamps.', '7 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Department of Tourism Kerala.', '2026-02-10', '2027-02-09', 'Department of Tourism Government of Kerala & Bharat Bhavan', ARRAY['Kerala']::TEXT[], ARRAY['Thiruvananthapuram', 'Kochi', 'Kozhikode', 'Palakkad', 'Kollam']::TEXT[], ARRAY['Shanghumugham Beach Trivandrum', 'Durbar Hall Ground Kochi', 'Mananchira Square Calicut']::TEXT[], 'Evenings between 5:30 PM and 9:30 PM across all district stages', 2, 'Fascinating, encyclopedic cultural treasure trove: witnessing 150 rare, mind-bending living folk and ritual arts presented free to the public.', 'Easily accessible in every major city center across Kerala via public transport.', 'Hotels across all district headquarters.', 'Free public admission; seating on chairs and open lawns; family-friendly atmosphere.', 'Applaud the master artists who have dedicated their lives to preserving these endangered art forms.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://keralatourism.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-maramon-convention', 'Maramon Convention', ARRAY['Asia''s Largest Christian Convention']::TEXT[], 'Spiritual & Temple', 'Christianity (Mar Thoma Syrian Heritage)', 'The largest annual Christian gathering in Asia, held inside a colossal thatched-roof sandbank pavilion on the dry bed of the holy Pamba River.', 'Initiated in 1895 CE by the Mar Thoma Evangelistic Association, continuing an unbroken 130-year spiritual tradition.', 'Celebrates Christian faith, biblical teachings, spiritual renewal, and the ancient heritage of Saint Thomas Syrian Christians of Malabar.', 'To gather for a week of prayer, ethical reflection, social welfare commitment, and spiritual revival.', 'Attracts over 300,000 attendees who assemble inside a colossal temporary pavilion (Pandal) constructed entirely of bamboo poles and dried coconut leaves on the river sands.', 'Distinguished by its peaceful, disciplined, non-commercial atmosphere where world-renowned biblical scholars preach in English and Malayalam.', ARRAY['Daily morning, afternoon, and evening spiritual prayer discourses by international speakers', 'Choral hymn singing by the 300-member Mar Thoma voluntary choir in four-part harmony', 'Special sessions for children, youth, and women emphasizing social justice and addiction-free living']::TEXT[], 'Lakhs of attendees dressed in pristine white clothes sit in deep, contemplative silence on the soft river sand, listening to stirring sermons.', ARRAY['Parippu Kanchi', 'Appam with Stew', 'Puttu with Kadala', 'Vegetarian Kerala Sadya', 'Hot Tea']::TEXT[], 'Simple, modest white attire: white shirts with white dhotis (Mundu) for men; white sarees or modest clothing for women.', 'Solemn, majestic choral hymn singing in four-part harmony without drums, accompanied only by organ.', 'Colossal thatched coconut-leaf Pandal spanning acres of sandy riverbed, bamboo poles, and the gentle flowing Pamba River.', '8 Days', 'Gregorian / Winter', 'Second week of February annually (Sunday to Sunday).', 'February', 'FIXED', 'Held annually during the second week of February.', '2026-02-08', '2027-02-14', 'Mar Thoma Evangelistic Association & Pathanamthitta Administration', ARRAY['Kerala']::TEXT[], ARRAY['Maramon', 'Kozhencherry', 'Pathanamthitta']::TEXT[], ARRAY['Pamba River Sandbank Maramon']::TEXT[], 'Morning sessions (9:30 AM to 12 PM) and concluding Sunday valedictory service', 2, 'Profound, serene spiritual peace: sitting on cool river sands under a colossal thatched palm canopy, surrounded by a sea of white-clad seekers in silent contemplation.', 'Chengannur railway station (15 km); easily reached by bus or taxi from Thiruvalla and Pathanamthitta.', 'Hotels and guesthouses in Kozhencherry, Chengannur, and Thiruvalla.', 'Sunny daytime on open riverbed; wear sun hats, carry drinking water, and remove shoes before stepping onto the pavilion mats.', 'Completely non-commercial, peaceful atmosphere; strictly no loud advertising, political campaigning, or commercial stalls inside the pavilion.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://marthomaevangelical.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-pongal-jallikattu', 'Pongal & Jallikattu Madurai', ARRAY['Thai Pongal & Eruthazhuvuthal']::TEXT[], 'Harvest & Agriculture', 'Pastoral Agriculture & Ancient Martial Heritage', 'The premier four-day harvest festival of Tamil Nadu celebrated with the boiling over of sweet rice in earthen pots and the legendary ancient bull-embracing sport of Jallikattu.', 'Celebrated since the Sangam era (2,000 years ago), documented in ancient Tamil epics (Silappathikaram) as ''Eruthazhuvuthal'' (embracing the bull).', 'Celebrates the winter harvest of rice and sugarcane, thanksgiving to the Sun God (Surya), working cattle, and ancestral agricultural roots.', 'To cook sweet milk-rice until it boils over (shouting ''Pongalo Pongal!''), signifying overflowing abundance, and showcase rural youth bravery in Jallikattu.', 'Spans four distinct days: Bhogi Pongal (cleansing), Surya Pongal (sun worship), Mattu Pongal (cattle thanksgiving), and Kaanum Pongal (family outings).', 'On Mattu Pongal, the world-famous Jallikattu competitions take place at Alanganallur, Palamedu, and Avaniyapuram in Madurai district.', ARRAY['Boiling sweet rice and milk in fresh clay pots until it overflows, accompanied by conch shells and shouts of ''Pongalo Pongal!''', 'Painting and decorating cattle horns, draping garlands of bells and sugarcane around their necks', 'Daring young athletes attempting to embrace and hold the hump of furious indigenous Kangayam bulls in the Jallikattu arena']::TEXT[], 'Towns and villages are adorned with vibrant rice-flour Kolams; the arena in Alanganallur roars as brave youths leap onto the humps of sprinting prize bulls.', ARRAY['Sakkarai Pongal (sweet rice cooked with jaggery, ghee, cashews, and raisins)', 'Ven Pongal with coconut chutney and sambar', 'Fresh Sugarcane', 'Meduvada', 'Payasam']::TEXT[], 'Traditional Tamil attire: pristine white Veshti (dhoti) with gold borders and Angavastram for men; bright Kanchipuram silk sarees for women.', 'Traditional Nadaswaram and Thavil percussion, vibrant folk dances: Karakattam, Oyilattam, and Mayilattam (peacock dance).', 'Clay Pongal pot with turmeric plant tied to its neck, overflowing sweet froth, indigenous Kangayam bull horns, and sugarcane stalks.', '4 Days', 'Solar / Thai Sankranti', 'First day of the Tamil solar month of Thai (January 14 to 17 annually).', 'January', 'FIXED', 'Celebrated January 14-17 annually.', '2026-01-14', '2027-01-14', 'Tamil Nadu Tourism & Madurai District Administration', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Madurai (Alanganallur, Palamedu)', 'Chennai', 'Thanjavur', 'Coimbatore']::TEXT[], ARRAY['Alanganallur Jallikattu Arena Madurai', 'Village squares across Tamil Nadu']::TEXT[], 'Surya Pongal morning (Jan 15) for home cooking and Mattu Pongal day (Jan 16) for Alanganallur Jallikattu', 3, 'Exhilarating, authentic celebration of ancient Dravidian agrarian vitality: sweet boiling pots, overflowing abundance, and heart-pounding martial courage in the bull arena.', 'Madurai Airport connects to major hubs; well connected by express trains and highways.', 'Hotels throughout Madurai city; book 2-3 months in advance for Pongal week.', 'Very crowded spectator galleries at Jallikattu; register for tourist viewing gallery passes in advance; stay clear of bull exit points.', 'Respect the cultural bond: Jallikattu bulls are prized, beloved family members of farmers; do not harm or provoke animals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-chithirai-festival-madurai', 'Chithirai Festival Madurai', ARRAY['Meenakshi Kalyanam & Alagar River Entry']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism & Vaishnavism / Pandyan Royalty)', 'The glorious two-week festival celebrating the celestial coronation and wedding of Goddess Meenakshi, culminating in Lord Alagar''s grand procession into the Vaigai River.', 'Historical synthesis established in the 17th century by King Thirumalai Nayak, uniting the Shaivite Meenakshi wedding with the Vaishnavite Alagar festival into one unified civic celebration.', 'Celebrates the coronation of Meenakshi as the sovereign Queen of Madurai and her divine marriage to Lord Sundareswarar (Shiva).', 'To honor Goddess Meenakshi and celebrate divine love, royal pageantry, and communal harmony between Shaivite and Vaishnavite traditions.', 'Over one million devotees pack the ancient streets around the historic Meenakshi Amman Temple to witness the divine wedding (Thirukalyanam).', 'Features the legendary ''Alagar Aattil Eringuthal'', where Lord Kallazhagar riding a golden horse enters the waters of the Vaigai River amidst massive crowds.', ARRAY['Coronation (Pattabhishekam) of Goddess Meenakshi as Queen of the Pandyan kingdom', 'Celestial Wedding (Thirukalyanam) of Meenakshi and Sundareswarar in the temple wedding hall', 'Lord Kallazhagar riding his golden horse into the waters of the Vaigai River amidst a sea of a million devotees']::TEXT[], 'Madurai vibrates day and night with thundering Nadaswaram horns, waving silk flags, flying water sprays, and joyous shouts of ''Govinda! Govinda!''.', ARRAY['Madurai Kari Dosa', 'Jigarthanda (famous cooling royal drink with almond gum and ice cream)', 'Sakkarai Pongal', 'Kalkandu Bath', 'Vada']::TEXT[], 'Rich Kanchipuram silk sarees with heavy Zari borders, white dhotis with gold borders, and saffron turbans.', 'Classical Nadaswaram and Thavil temple music, vibrant Oyilattam, Karakattam, and mass devotional chanting.', 'Towering multi-sculptured Gopurams of Meenakshi Temple, golden wedding chariot, and golden horse of Lord Alagar in the Vaigai River.', '12 Days', 'Tamil Solar Calendar', 'Month of Chithirai (April - May) culminating on Chitra Pournami.', 'April - May', 'LUNISOLAR', 'Culminates on Chitra Pournami.', '2026-05-02', '2027-04-21', 'Arulmigu Meenakshi Sundareswarar Temple Trust & Madurai Police', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Madurai']::TEXT[], ARRAY['Meenakshi Amman Temple', 'Vaigai River Bed', 'Alagar Kovil']::TEXT[], 'Meenakshi Kalyanam day (temple wedding) and Lord Alagar''s morning entry into the Vaigai River', 3, 'Colossal, spine-tingling visual pageantry: an ancient temple city celebrating its beloved Queen''s wedding with unmatched love, thundering horns, and sea of faith.', 'Madurai Airport; well connected by trains and highways; central old city is pedestrianized during chariot processions.', 'Hotels throughout Madurai are booked solid months ahead; reserve early.', 'Monumental crowds exceeding one million along the Vaigai riverbed; keep hydrated in summer heat; follow designated police pedestrian routes.', 'Taste the legendary cooling drink ''Jigarthanda'' at famous century-old stalls in Madurai.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://maduraimeenakshi.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-margazhi-season-chennai', 'Margazhi Music and Dance Season Chennai', ARRAY['Madras December Music Season']::TEXT[], 'Art & Cultural Festival', 'Carnatic Classical Music & Bharatanatyam Heritage', 'The world''s largest classical music and dance festival, featuring over 3,000 concerts, lecture demonstrations, and dance dramas across 100 Sabhas in Chennai.', 'Initiated in 1927 to commemorate the founding of the Madras Music Academy, continuing an unbroken century-old winter cultural tradition.', 'Celebrates the sacred spiritual month of Margazhi, considered by Lord Krishna in the Bhagavad Gita as the supreme month for divine contemplation.', 'To showcase the highest traditions of Carnatic vocal and instrumental music, classical Bharatanatyam, and scholarly musicological research.', 'Officially recognized by UNESCO when Chennai was designated as a UNESCO Creative City of Music in 2017.', 'Renowned for its unique cultural ambiance: music lovers hop from Sabha to Sabha attending morning kutcheris, afternoon dance recitals, and relishing famous Sabha canteen snacks.', ARRAY['Morning Kutcheri classical vocal and instrumental concerts at premier Sabhas (Music Academy, Narada Gana Sabha)', 'Classical Bharatanatyam dance dramas depicting episodes from ancient Tamil epics and Sanskrit classics', 'Scholarly academic lecture demonstrations (Lec-Dems) exploring microtones and raga structures']::TEXT[], 'Connoisseurs and international travelers spend the entire month immersed in sublime classical ragas, sipping filter coffee, and discussing musical nuances.', ARRAY['Sabha Canteen specialties: Kasi Halwa, Vazhaipoo Vadai, Keerai Vadai, Mysore Pak', 'Ghee Pongal with Chutney', 'Idli with Tiffin Sambar', 'Madras Filter Coffee']::TEXT[], 'Elegant handloom Kanchipuram silk sarees with traditional temple borders, crisp white Veshtis with shirts, and silk shawls.', 'Pristine Carnatic classical music: vocal ragas, Veena, Violin, Flute, Mridangam, Ghatam, Kanjira, and Morsing.', 'Bronze Nataraja statue, Tanpura string instruments, jasmine floral garlands, and Sabha canteen menu boards.', '6 Weeks (Peak 4 Weeks)', 'Tamil Solar Calendar', 'Mid-December to mid-January throughout the month of Margazhi.', 'December - January', 'SOLAR', 'Full season runs mid-December to mid-January.', '2026-12-15', '2027-12-15', 'Madras Music Academy, Federation of City Sabhas & TN Tourism', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Chennai (Mylapore, T. Nagar, Alwarpet)']::TEXT[], ARRAY['Music Academy', 'Narada Gana Sabha', 'Kalakshetra', 'Brahma Gana Sabha']::TEXT[], 'Morning 8:30 AM lecture demonstrations and evening 6:30 PM prime concerts at The Music Academy', 4, 'Sublime, intellectually invigorating classical music paradise: world-class acoustic mastery, rich scholarly discourse, and legendary Sabha canteen delicacies in pleasant winter weather.', 'Chennai International Airport; Chennai Metro, suburban trains, and app cabs connect all central Sabhas easily.', 'Extensive hotels across central and south Chennai (Mylapore, Alwarpet, T. Nagar).', 'High-demand morning and evening concerts at The Music Academy require advance season passes or online tickets.', 'Strict concert etiquette: absolute silence during raga alaap; switch off mobile phones; no entering or leaving mid-song.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://musicacademymadras.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mahabalipuram-dance-festival', 'Mahabalipuram Indian Dance Festival', ARRAY['Mamallapuram Dance Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & 7th-Century Pallava Sculptures', 'A premier month-long festival of classical Indian dance staged against the 7th-century UNESCO World Heritage monolithic rock relief of Arjuna''s Penance on the Coromandel Coast.', 'Established by the Department of Tourism, Tamil Nadu, to celebrate classical dance against the ancient stone carving capital of the Pallava kings.', 'Celebrates the immortal synthesis of stone sculpture, classical dance, and maritime heritage.', 'To present India''s highest classical dance traditions against one of the largest open-air bas-relief sculptures in the world.', 'Staged against the monumental 100-foot rock face of ''Arjuna''s Penance'' (Descent of the Ganga), carved with life-size elephants, gods, and flying celestial beings.', 'Features daily performances by leading exponents of Bharatanatyam, Kuchipudi, Kathakali, Odissi, and Mohiniyattam under the open winter night sky.', ARRAY['Nightly classical dance performances against the illuminated 7th-century monolithic rock sculptures', 'Folk dance presentations including Karagattam, Kavadi Aattam, and Thappattam', 'Guided heritage walks exploring the Shore Temple and monolithic Five Rathas (Pancha Rathas)']::TEXT[], 'Audience members sit under cool coastal night breezes, captivated as classical dancers mirror the exact sculptural poses carved 1,300 years ago.', ARRAY['Fresh coastal seafood delicacies', 'Crispy Masala Dosa', 'Filter Coffee', 'Medu Vada', 'Coconut Barfi']::TEXT[], 'Comfortable evening casuals, handloom cotton kurtas, elegant silk sarees, and sandals.', 'Classical Carnatic music, mridangam rhythms, nattuvangam cymbals, and vocal ragas, accompanied by coastal breeze.', 'Colossal rock relief of Arjuna''s Penance, monolithic stone elephants, Shore Temple spires, and golden spotlights.', '4 Weeks', 'Gregorian / Winter', 'Held from late December to late January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Full season runs mid-December to mid-January.', '2026-12-25', '2027-12-25', 'Department of Tourism Government of Tamil Nadu', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Mamallapuram (Mahabalipuram)', 'Chengalpattu']::TEXT[], ARRAY['Arjuna''s Penance Open Air Complex', 'Shore Temple']::TEXT[], 'Evenings between 6 PM and 8:30 PM for open-air dance performances against the illuminated rock', 2, 'Enchanting coastal aesthetic bliss: watching classical dancers perform before 1,300-year-old carved stone elephants with gentle sea breezes rustling palm leaves.', '55 km south of Chennai Airport along the scenic East Coast Road (ECR); easily accessible by taxi or tourist bus.', 'Beachfront luxury resorts, boutique heritage hotels, and backpacker guesthouses in Mahabalipuram.', 'Pleasant coastal winter evenings; open-air seating; free public admission.', 'Strict archaeological protection: no touching or climbing on delicate ancient Pallava rock sculptures.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-karthigai-deepam-tiruvannamalai', 'Karthigai Deepam Tiruvannamalai', ARRAY['Maha Deepam Festival of Light']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Cosmic Element of Fire)', 'The awe-inspiring festival of light where a colossal cauldron burning 3,000 kg of pure ghee is lit atop the 2,668-foot holy mountain of Arunachala.', 'Ancient festival documented in Sangam literature (Akananuru) dating back over 2,500 years, celebrating Lord Shiva manifesting as the infinite pillar of fire (Jyotirlinga).', 'Commemorates Lord Shiva appearing as an endless column of cosmic light to destroy the pride of Brahma and Vishnu.', 'To behold the sacred Maha Deepam flame atop Mount Arunachala and perform the sacred 14-kilometer barefoot walk around the mountain (Girivalam).', 'Draws over 2.5 million pilgrims who walk barefoot around Mount Arunachala along the 14 km paved path, chanting ''Annamalaiyarukku Harohara''.', 'The sacred Maha Deepam cauldron atop the summit burns 3,000 liters of ghee and hundreds of meters of cotton wick, visible for 35 kilometers around.', ARRAY['Dawn Bharani Deepam lit inside the sanctum of the 1,000-year-old Annamalaiyar Temple', 'Lighting of the colossal Maha Deepam cauldron atop the summit of Mount Arunachala at exact sunset (6:00 PM)', 'Barefoot 14-kilometer circumambulation of the holy mountain (Girivalam) by over two million pilgrims']::TEXT[], 'At exact sunset, as the flame blazes atop the mountain peak, two million pilgrims roar ''Annamalaiyarukku Harohara'' as millions of oil lamps light up every household.', ARRAY['Pori Urundai (puffed rice balls with jaggery and cardamom)', 'Appam', 'Sakkarai Pongal', 'Tiruvannamalai Dosa', 'Filter Coffee']::TEXT[], 'Traditional white cotton dhotis, saffron stoles, Rudraksha malas, and modest Indian pilgrim wear.', 'Resounding, continuous chanting of ''Annamalaiyarukku Harohara'', thunderous temple bells, conch shells, and Nadaswaram horns.', '2,668-foot holy Mount Arunachala, towering eastern Raja Gopuram (66 meters tall), blazing summit cauldron, and millions of earthen lamps.', '10 Days (Maha Deepam on Day 10)', 'Tamil Solar Calendar', 'Month of Karthigai (November - December) on Krittika Nakshatra.', 'November - December', 'LUNISOLAR', 'Culminates on Karthigai Deepam day.', '2026-11-23', '2027-12-12', 'Arulmigu Arunachaleswarar Temple Trust & Tiruvannamalai Police', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Tiruvannamalai']::TEXT[], ARRAY['Annamalaiyar Temple', 'Mount Arunachala Summit', '14 km Girivalam Path']::TEXT[], 'Sunset (6:00 PM) on Maha Deepam day when the summit flame is lit, and midnight for Girivalam mountain walk', 2, 'Colossal spiritual ecstasy and primeval wonder: beholding a towering mountain blazing with sacred fire while two million barefoot pilgrims chant in collective oneness.', '190 km southwest of Chennai; well connected by trains and state transport buses.', 'Hotels, ashrams (Sri Ramana Ashram), and dharamshalas are booked months in advance; book well ahead.', 'Monumental crowds exceeding two million; barefoot 14 km Girivalam walk takes 4-5 hours; stay hydrated.', 'Remove footwear before stepping onto the temple flagstones; respect the sacred sanctity of Mount Arunachala.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://arunachaleswarartemple.tnhrce.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-natyanjali-dance-festival', 'Natyanjali Dance Festival Chidambaram', ARRAY['Cosmic Dance of Shiva Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Indian Dance & Cosmic Shaivism', 'The sacred five-day classical dance festival held inside the thousand-pillar halls of the ancient Chidambaram Nataraja Temple on Maha Shivratri.', 'Initiated in 1981 at the ancient temple where Lord Shiva is worshipped as Nataraja, the cosmic dancer performing the eternal Ananda Tandava.', 'Celebrates the cosmic dance of creation, preservation, and dissolution performed by Lord Nataraja.', 'To offer classical dance (Natya Anjali - dance offering) directly to the Lord of Dance as a pure spiritual prayer without financial remuneration.', 'Staged directly within the ancient temple courtyard, surrounded by the 108 sculpted dance postures (Karanas) of Bharatanatyam carved into the stone gopurams.', 'Dancers consider performing before the golden sanctum of Lord Nataraja on Maha Shivratri the ultimate spiritual milestone of their careers.', ARRAY['All-night classical dance performances commencing on Maha Shivratri evening', 'Continuous recitals by classical dancers from across India and abroad on the temple stage', 'Sacred darshan of Lord Nataraja inside the Chit Sabha and the mysterious Chidambara Rahasya']::TEXT[], 'Connoisseurs and devotees sit on the ancient flagstones under the night sky, watching classical dancers perform to live mridangam and nattuvangam.', ARRAY['Chidambaram Kothsu (spicy eggplant gravy served with idli)', 'Sakkarai Pongal', 'Kalkandu Bath', 'Curd Rice', 'Filter Coffee']::TEXT[], 'Traditional silk Bharatanatyam dance costumes with temple jewelry; audience in formal Indian ethnic wear.', 'Pure classical Carnatic music, mridangam rhythms, nattuvangam cymbals, flute melodies, and sacred Shiva stotrams.', 'Bronze idol of Nataraja in cosmic dance posture, four towering gopurams carved with 108 Karanas, and glowing oil lamps.', '5 Days', 'Hindu Lunisolar', 'Culminates on Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Begins on Maha Shivratri night.', '2026-02-15', '2027-03-06', 'Natyanjali Trust Chidambaram & Temple Podu Dikshitars', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Chidambaram', 'Cuddalore']::TEXT[], ARRAY['Thillai Nataraja Temple Chidambaram']::TEXT[], 'Maha Shivratri night (6 PM to 6 AM) for continuous all-night classical dance offerings', 2, 'Sublime, transcendent artistic and spiritual communion: watching classical dancers perform the ancient sacred movements before the very God of Dance in his 1,000-year-old temple.', 'Chidambaram railway station connects to Chennai and Tiruchirappalli; 230 km south of Chennai via highway.', 'Hotels and guest houses in Chidambaram town.', 'All-night event inside the temple courtyard; sit on floor mats; carry light woolens for cool night hours.', 'Strict temple sanctity: maintain silence during performances; photography inside the inner sanctum is strictly prohibited.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-thaipusam-palani', 'Thaipusam Palani', ARRAY['Palani Kavadi Aattam Festival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Kaumaram / Lord Murugan & Ascetic Devotion)', 'The intense, awe-inspiring festival of Lord Murugan where millions of devotees carry decorated wooden Kavadi arches on shoulders and pierce cheeks with silver vel spears.', 'Ancient Tamil festival celebrated since the Sangam era, dedicated to Lord Murugan (Kartikeya), the supreme commander of divine forces and patron god of the Tamil language.', 'Commemorates Goddess Parvati gifting the divine golden spear (Vel) to Lord Murugan to vanquish the demon Surapadman.', 'To fulfill solemn vows, seek healing, and practice extreme spiritual surrender through ascetic penance.', 'Devotees walk barefoot for hundreds of kilometers carrying the ''Kavadi'' (a decorated wooden arch carrying pots of sacred milk).', 'Famous for the extreme ascetic trance (Alagu Kuthal): devotees pierce their cheeks, tongues, and backs with small and large silver Vel spears without bleeding.', ARRAY['Walking barefoot for days carrying the decorated wooden Kavadi arch to the hilltop Palani Temple', 'Piercing of cheeks and tongues with sacred silver spears (Vel) in ecstatic devotional trance', 'Offering of sacred milk (Paal Kavadi) and the world-famous Palani Panchamirtham to Lord Dhandayuthapani']::TEXT[], 'Millions of yellow-clad pilgrims fill the foothills and mountain steps, dancing in trance to the electrifying beats of Thavil drums and chanting ''Vetrivel Muruganukku Harohara!''.', ARRAY['Palani Panchamirtham (divine jam of banana, jaggery, honey, ghee, and cardamom - GI Tagged)', 'Tender Coconut', 'Sweet Pongal', 'Sundal']::TEXT[], 'Vibrant yellow or green cotton dhotis and shawls, sacred Vibhuti (holy ash) covering forehead and body, and bare feet.', 'High-voltage, frenzied folk drumming: Thavil, Pambai, and Urumee percussion, accompanied by the hypnotic Kavadi Chindu folk songs.', 'Sacred spear of Murugan (Vel), decorated wooden Kavadi arch with peacock feathers, and Palani hilltop temple.', '10 Days', 'Tamil Solar Calendar', 'Month of Thai (January - February) on Pusam Nakshatra.', 'January - February', 'LUNISOLAR', 'Culminates on Thaipusam day.', '2026-02-01', '2027-01-22', 'Arulmigu Dhandayuthapani Swamy Temple Trust & Dindigul Police', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Palani', 'Dindigul', 'Madurai']::TEXT[], ARRAY['Palani Murugan Hilltop Temple Complex']::TEXT[], 'Thaipusam day for viewing the Kavadi processions and daytime trance dancing', 2, 'Overwhelming, mind-expanding display of intense ascetic devotion: thousands dancing in trance with pierced cheeks and peacock-feather arches, swept up in deafening chants.', 'Palani railway station connects to Coimbatore and Madurai; 110 km from Coimbatore Airport.', 'Devaswom dharamshalas and hotels in Palani town.', 'Climbing 693 stone steps to the hilltop temple (winch and ropeway cars also operate); prepare for immense crowd density.', 'Purchase authentic GI-tagged ''Palani Panchamirtham'' exclusively from authorized temple devaswom counters.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://palanimurugantemple.tnhrce.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kanthuri-festival-nagore', 'Kanthuri Festival Nagore Dargah', ARRAY['Nagore Santhanakoodu Festival']::TEXT[], 'Spiritual & Temple', 'Islam (Sufism / Inter-Faith Harmony)', 'The historic 14-day international Sufi festival celebrated at the 500-year-old Nagore Dargah, famous for the grand illuminated chariot carrying sacred sandalwood paste.', 'Commemorates the death anniversary (Urs) of the 16th-century Sufi saint Hazrat Syed Shahul Hamid Qadir Wali, who performed numerous miraculous healings in Nagore.', 'Celebrates universal love, spiritual healing, and inter-religious harmony between Muslims, Hindus, and Christians.', 'To offer prayers at the sacred tomb of the saint and receive the healing sandalwood paste (Santhanam).', 'A magnificent symbol of syncretism: the five towering minarets of the Dargah were constructed with royal patronage from the Hindu Maratha rulers of Thanjavur.', 'Culminates on the 10th night with the ''Santhanakoodu''—a grand procession of an illuminated chariot carrying sacred sandalwood paste through cheering crowds.', ARRAY['Ceremonial hoisting of the sacred Islamic flags sent by the Thanjavur royal family atop the five minarets', 'Santhanakoodu procession: an illuminated multi-tiered chariot carrying consecrated sandalwood paste', 'Anointing of the sacred tomb (Mazar) of the saint with sandalwood paste at dawn']::TEXT[], 'Hundreds of thousands of pilgrims of all religious faiths line the coastal streets, cheering as the glowing chariot passes amidst qawwalis and fireworks.', ARRAY['Nagore Dumroot (famous sweet semolina cake)', 'Mutton Biryani', 'Ghee Rice with Dalcha', 'Halwa', 'Rose Sharbat']::TEXT[], 'Traditional white Pathani suits, Kurta-pajamas with prayer caps, and colorful traditional sarees.', 'Soulful Tamil and Urdu Qawwalis, Dafmuttu drumming, Sufi zikr recitations, and Nadaswaram temple music.', 'Five soaring whitewashed minarets of Nagore Dargah (tallest is 131 feet), illuminated Santhanakoodu chariot, and sandalwood vessels.', '14 Days', 'Islamic Lunar (Hijri)', 'Jumada al-Thani month of the Islamic calendar', 'November - December', 'LUNAR', 'Observed during the Islamic month of Jumada al-Thani.', '2026-11-20', '2027-11-09', 'Nagore Dargah Managing Board & Nagapattinam Administration', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Nagore', 'Nagapattinam']::TEXT[], ARRAY['Nagore Dargah Complex', 'Nagore Beach Road']::TEXT[], '10th night of the festival for the grand Santhanakoodu chariot procession and dawn sandalwood anointing', 2, 'Profound, tearful spiritual harmony: watching Hindus and Muslims march together in devotion behind an illuminated chariot in a historic coastal town.', 'Nagore railway station is 5 km from Nagapattinam; 300 km south of Chennai via coastal highway.', 'Pilgrim guest houses in Nagore and hotels in nearby Nagapattinam and Karaikal.', 'Dense crowds during the 10th night chariot procession; follow police crowd lines along main roads.', 'Dress respectfully covering shoulders and knees; head covering required inside the Dargah courtyard.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://nagapattinam.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-velankanni-feast', 'Velankanni Feast', ARRAY['Feast of Our Lady of Good Health']::TEXT[], 'Spiritual & Temple', 'Christianity (Catholic Marian Shrine / Lourdes of the East)', 'The massive international pilgrimage festival where over two million devotees of all faiths congregate at the grand Gothic Basilica of Our Lady of Good Health on the Bay of Bengal.', 'Commemorates the 16th-century miraculous apparitions of the Virgin Mary to a shepherd boy and buttermilk vendor, and the rescue of Portuguese sailors in a storm.', 'Celebrates the Nativity of the Blessed Virgin Mary and honors her maternal healing compassion as ''Arogya Matha''.', 'To pray for healing from serious diseases, fulfill vows, and seek physical and spiritual health at the sacred shrine.', 'Known as the ''Lourdes of the East'', attracting millions of Catholic, Hindu, and Muslim pilgrims who observe traditional Indian rituals of devotion.', 'Unique syncretic practices: pilgrims shave their heads (tonsure), perform ear-piercing for infants, and walk on their knees to the shrine.', ARRAY['Grand flag hoisting ceremony on August 29 inaugurating the nine-day Novena', 'Daily solemn Holy Mass celebrated in eight languages (Tamil, English, Malayalam, Telugu, Kannada, Hindi, Marathi, Konkani)', 'Car procession carrying the bejeweled statue of Our Lady of Good Health around the shrine every evening']::TEXT[], 'The entire coastal town turns into a sea of millions of pilgrims, carrying candles, offering silver anatomical models for healing, and attending outdoor masses.', ARRAY['Coastal fish curry rice', 'Appam with stew', 'Puttu', 'Velankanni Halwa', 'Tender Coconut']::TEXT[], 'Pilgrims wear saffron or yellow clothes fulfilling vows; Sunday best suits, dresses, and traditional sarees.', 'Solemn Catholic choir hymns, brass liturgical bands, and multi-lingual devotional singing.', 'Gleaming white neo-Gothic twin spires of the Basilica, illuminated car procession, and the azure Bay of Bengal.', '10 Days (Novena + Feast Day)', 'Christian Liturgical', 'August 29 to September 8 annually (Feast day on September 8).', 'August - September', 'FIXED', 'Flag hoisted August 29; feast day celebrated September 8.', '2026-08-29', '2027-08-29', 'Shrine Basilica of Our Lady of Good Health & Nagapattinam Administration', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Velankanni', 'Nagapattinam']::TEXT[], ARRAY['Basilica of Our Lady of Good Health Complex']::TEXT[], 'Evening car procession at 8 PM and September 8 morning feast day High Mass', 3, 'Deeply emotional, tearful pilgrimage of universal human suffering and hope, where millions of broken bodies and hopeful hearts find solace before the Loving Mother.', 'Velankanni railway station connects to Chennai and Madurai; 320 km south of Chennai via ECR highway.', 'Massive church pilgrim lodges, private hotels, and cottages across Velankanni; book months in advance.', 'Vast crowds exceeding two million; watch footing on crowded beach sands; follow church volunteer queue marshals.', 'Maintain deep silence and prayerful decorum inside the Basilica chambers; deposit wax offerings at designated altars.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://velankannichurch.com', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-arubathumoovar-festival', 'Arubathumoovar Festival Mylapore Chennai', ARRAY['Mylapore Panguni Uthiram Carnival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / 63 Nayanmar Saints)', 'The glorious celebration of the 63 Nayanmar Shaivite saints, where bronze idols of all 63 saints are carried in a massive procession around the ancient Kapaleeshwarar Temple.', 'Celebrated since the 7th century CE in historic Mylapore, immortalized by saint-poet Thirugnanasambandar in his Tevaram hymns.', 'Celebrates the lives, supreme devotion, and egalitarian social message of the 63 Nayanmar saints of Tamil Shaivism.', 'To honor Lord Kapaleeshwarar (Shiva) and witness the rare, majestic assembly of all 63 saints carried in procession together.', 'The crowning spectacle of the 10-day Panguni Brahmotsavam: bronze idols of all 63 Nayanmars are placed on palanquins and carried around the four Mada Streets.', 'Famous for the boundless charitable hospitality (Thanneer Pandal): local residents set up hundreds of stalls offering free buttermilk, food, and sweets to all pilgrims.', ARRAY['Grand morning procession of Lord Kapaleeshwarar and Karpagambal on the silver chariot', 'Afternoon procession of the 63 Nayanmar bronze idols carried on palanquins around the Mada streets', 'Offering of free buttermilk, Sambaram, and food at hundreds of community hospitality stalls']::TEXT[], 'Hundreds of thousands of citizens fill the historic temple streets of Mylapore, singing Tevaram hymns, drinking cool buttermilk, and revering the passing saints.', ARRAY['Mylapore Rose Milk', 'Mor (spiced buttermilk with curry leaves)', 'Panakam (sweet jaggery-ginger cooler)', 'Puli Sadam (tamarind rice)', 'Thayir Sadam']::TEXT[], 'Traditional Tamil handloom cotton Veshti and shirts for men, and silk or cotton sarees for women.', 'Ancient Tevaram hymn chanting by traditional Oduvars, resonant Nadaswaram and Thavil duets, and temple conch shells.', 'Carved multi-tiered Gopuram of Kapaleeshwarar Temple, bronze idols of the 63 Nayanmars, and massive wooden temple chariot.', '1 Day (Peak of 10-Day Festival)', 'Tamil Solar Calendar', 'Panguni month (March - April) on the 8th day of the Brahmotsavam.', 'March - April', 'LUNISOLAR', 'Held during Panguni month (March - April).', '2026-03-31', '2027-04-19', 'Arulmigu Kapaleeshwarar Temple Trust & Chennai City Police', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Chennai', 'Mylapore']::TEXT[], ARRAY['Kapaleeshwarar Temple', 'Four Mada Streets Mylapore']::TEXT[], 'Afternoon between 2:30 PM and 7 PM for the procession of the 63 Nayanmars', 1, 'Authentic, heartwarming Old Madras cultural vitality: ancient temple rituals, soul-stirring Tamil hymns, sweet rose milk, and boundless community charity.', 'Thirumayilai MRTS Railway Station; easily reached by Chennai Metro and city buses to Luz Corner.', 'Hotels throughout central and south Chennai.', 'Warm summer afternoon; drink plenty of water and buttermilk; wear easy slip-on footwear as shoes must be removed on temple streets.', 'Accept the offered charity buttermilk and food with gratitude; keep Mada streets clean.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mylaporekapaleeswarar.tnhrce.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kanyakumari-cape-festival', 'Kanyakumari Cape Festival', ARRAY['Three Seas Confluence Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Maritime Heritage & Confluence', 'A scenic three-day cultural festival celebrated at the southernmost tip of mainland India, where the Arabian Sea, Bay of Bengal, and Indian Ocean meet.', 'Initiated by Tamil Nadu Tourism at the sacred confluence (Triveni Sangam) where Goddess Kanyakumari performed penance and Swami Vivekananda meditated.', 'Celebrates the natural phenomenon of the three-seas confluence, marine ecology, and coastal tourism.', 'To showcase the classical and folk dance heritage of Tamil Nadu against the backdrop of the ocean sunrises and sunsets.', 'Famous for the breathtaking spectacle of the full moon rising from the Bay of Bengal at the exact same moment the sun sets into the Arabian Sea.', 'Features classical Bharatanatyam, Kathakali, and folk dances performed on an open-air stage overlooking the Vivekananda Rock Memorial.', ARRAY['Taking holy cleansing dips at the Triveni Sangam ocean confluence at sunrise', 'Ferry rides to the offshore Vivekananda Rock Memorial and the 133-foot stone statue of saint-poet Thiruvalluvar', 'Evening classical and folk dance concerts staged at the beach amphitheatre']::TEXT[], 'Visitors sit on the coastal stone promenade, watching the golden sunset over the waves and attending musical concerts beneath ocean breezes.', ARRAY['Kanyakumari Nendran Banana Chips', 'Fish Curry with Rice', 'Appam with Fish Stew', 'Kothu Parotta', 'Tender Coconut']::TEXT[], 'Light casual resort wear, cotton shirts, sunglasses, sun hats, and sandals.', 'Classical Carnatic music, Bharatanatyam dance dramas, coastal folk drumming, and Nadaswaram recitals.', '133-foot stone statue of Thiruvalluvar on rocky islet, Vivekananda Rock Memorial, and three-ocean confluence.', '3 Days', 'Gregorian / Autumn', 'Held in October annually.', 'October', 'ORGANIZER_ANNOUNCED', 'Announced annually by Tamil Nadu Tourism.', '2026-10-18', '2027-10-17', 'Department of Tourism Tamil Nadu & Kanyakumari Administration', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Kanyakumari']::TEXT[], ARRAY['Triveni Sangam Beach', 'Vivekananda Rock Memorial Complex']::TEXT[], 'Dawn for the three-seas sunrise and evening 5:30 PM to 8:30 PM for sunset and cultural shows', 2, 'Romantic, poetic geographical wonder: standing at the very tip of the Indian subcontinent, watching the ocean turn to liquid gold while classical music floats on the breeze.', 'Kanyakumari railway station connects directly to major Indian cities; 90 km from Trivandrum International Airport.', 'Beachfront hotels and ocean-view resorts throughout Kanyakumari town.', 'Ocean currents at the Triveni Sangam can be swift; bathe only within designated safety chains.', 'Ferry tickets to Vivekananda Rock have long queues; arrive early in the morning.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kumbakonam-mahamaham', 'Kumbakonam Mahamaham', ARRAY['Kumbh Mela of South India']::TEXT[], 'Spiritual & Temple', 'Hinduism (Puranic Sacred Tank & 12-Year Cycle)', 'The monumental festival celebrated once every 12 years at the massive 6.2-acre sacred Mahamaham Tank in the temple city of Kumbakonam.', 'Ancient pilgrimage documented since the Chola dynasty, sanctified by the legend of Lord Shiva breaking the pot (Kumbha) of celestial nectar at the dawn of creation.', 'Celebrates the planetary alignment when Jupiter enters Leo (Simha) and the Sun enters Aquarius, coinciding with the full moon.', 'To take the holy cleansing dip in the sacred Mahamaham Tank, believed to be infused with the waters of all nine sacred rivers of India on this day.', 'Known as the ''Kumbh Mela of South India'', drawing over four million pilgrims to the historic town in the fertile Kaveri delta.', 'Centered around the massive rectangular Mahamaham Tank surrounded by 16 ornate stone pavilions (Mandapams) constructed by Govinda Dikshitar.', ARRAY['Shahi Snan holy dip in the sacred 6.2-acre Mahamaham Tank on the auspicious conjunction day', 'Procession of deities from twelve ancient Shiva temples and five Vaishnava temples of Kumbakonam to the tank banks', 'Theerthavari ritual where the sacred weapons of the deities are bathed in the tank waters amidst lakhs of chanting devotees']::TEXT[], 'Over four million pilgrims pack the stone steps around the sacred green tank, splashing holy water and chanting ''Hara Hara Mahadeva''.', ARRAY['Kumbakonam Degree Coffee (famous chicory-free pure cow milk coffee)', 'Kadappa with Idli', 'Thirunageswaram Halwa', 'Sakkarai Pongal', 'Kumbakonam Betel leaf (GI Tagged)']::TEXT[], 'Traditional white cotton Veshtis with gold borders, and traditional handloom silk sarees.', 'Resounding Vedic chanting by hundreds of Veda pathashala scholars, Nadaswaram-Thavil duets, and temple bells.', '6.2-acre sacred Mahamaham Tank, 16 stone mandapams with carved pillars, and towering gopurams of Kumbakonam.', '10 Days', 'Astrological / 12-Year Cycle', 'Month of Masi (February - March) on Magha Nakshatra every 12 years (next in 2028).', 'February - March', 'LUNISOLAR', 'Celebrated every 12 years (next in 2028).', '2028-02-28', '2028-03-08', 'Kumbakonam Municipal Corporation & HR&CE Department TN', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Kumbakonam', 'Thanjavur']::TEXT[], ARRAY['Mahamaham Tank Complex', 'Adi Kumbeswarar Temple']::TEXT[], 'Dawn of the main Theerthavari bathing day for the holy dip in the sacred tank', 3, 'Awe-inspiring, historic spiritual energy: plunging into an ancient sacred pool believed to hold the nectar of creation, surrounded by 16 sculpted stone pavilions and millions of devout souls.', 'Kumbakonam railway station is well connected; 90 km from Tiruchirappalli International Airport.', 'Hotels throughout Kumbakonam and nearby Thanjavur (40 km away); early booking essential during Mahamaham years.', 'Massive crowd density exceeding four million; enter the tank only via designated ramp entrances; follow volunteer safety instructions.', 'Enjoy authentic ''Kumbakonam Degree Coffee'' at historic highway cafes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://thanjavur.nic.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-panguni-uthiram', 'Panguni Uthiram Statewide', ARRAY['Day of Divine Marriages']::TEXT[], 'Spiritual & Temple', 'Hinduism (Celestial Weddings / Tamil Heritage)', 'The sacred full moon festival celebrated across every major temple in Tamil Nadu, honoring the celestial weddings of Shiva-Parvati, Rama-Sita, and Murugan-Deivanai.', 'Ancient Tamil festival mentioned in early Sangam literature and celebrated across temples for over two millennia.', 'Commemorates the auspicious alignment of the full moon with the star Uthiram (Uttara Phalguni), the day of cosmic matrimonial harmony.', 'To celebrate divine love, pray for marital bliss and family peace, and witness the elaborate celestial wedding rituals (Thirukalyanam).', 'Unique day on which multiple divine couples were married: Shiva and Parvati, Rama and Sita, Murugan and Deivanai, and Andal and Ranganatha.', 'Celebrated with grand public chariot processions and midnight wedding rituals in temples from Kanchipuram to Madurai.', ARRAY['Performance of the elaborate celestial wedding ritual (Thirukalyanam) with silk garlands and Mangalsutra tying', 'Carrying the divine wedding couple on grand flower-bedecked palanquins through city streets', 'Singing of sacred Tamil wedding hymns and distribution of sanctified wedding feast meals']::TEXT[], 'Temples are decorated with thousands of fragrant jasmine and rose garlands, as thousands of devotees attend the divine weddings with tearful joy.', ARRAY['Panchamirtham', 'Sakkarai Pongal', 'Kalyana Sadya feast', 'Laddu', 'Appam']::TEXT[], 'Traditional silk sarees (Kanchipuram), white Veshti with gold borders, and fresh jasmine garlands in hair.', 'Classical Nadaswaram wedding melodies (Anandabhairavi, Kalyani ragas), Thavil drums, and devotional chanting.', 'Golden wedding mandapams draped in jasmine flowers, holy wedding thread (Mangalasutra), and decorated chariots.', '1 Day', 'Tamil Solar Calendar', 'Month of Panguni (March - April) on Uthiram Nakshatra (Full Moon).', 'March - April', 'LUNISOLAR', 'Celebrated on Panguni Uthiram day.', '2026-04-02', '2027-03-22', 'HR&CE Department Government of Tamil Nadu', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Kanchipuram', 'Madurai', 'Palani', 'Srirangam', 'Mylapore Chennai']::TEXT[], ARRAY['Ekambareswarar Temple Kanchipuram', 'Palani Murugan Temple', 'Srirangam Temple']::TEXT[], 'Evening from 5 PM to 11 PM during the celestial wedding ceremony (Thirukalyanam)', 1, 'Enchanting, joy-filled temple atmosphere: sweet fragrances of thousands of jasmine garlands, melodious wedding music, and the infectious happiness of attending a divine marriage.', 'Easily accessible across Tamil Nadu via rail and road transport.', 'Hotels across all major temple cities in Tamil Nadu.', 'Very crowded inside major temple wedding halls; arrive 1-2 hours before scheduled Thirukalyanam rites.', 'Respect traditional dress codes mandatory in Tamil Nadu temples (no jeans or Western clothing allowed in sanctums).', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mamallapuram-heritage-dance', 'Mamallapuram Heritage Dance Festival', ARRAY['Shore Temple Dance Festival']::TEXT[], 'Art & Cultural Festival', 'Classical Dance & Coastal Shore Temple', 'A magnificent open-air classical dance festival staged directly on the golden sands beside the 8th-century UNESCO World Heritage Shore Temple on the Bay of Bengal.', 'Organized by the Department of Tourism, Tamil Nadu, to celebrate the classical dance traditions of India in a dramatic marine heritage setting.', 'Celebrates the sea-facing architectural marvel built by Pallava King Narasimhavarman II (Rajasimha) in the early 8th century.', 'To promote coastal cultural tourism and present classical dancers against the ancient stone temple and crashing ocean breakers.', 'The twin-spired Shore Temple, standing undefeated against the salt spray of the Bay of Bengal for 1,300 years, serves as an unforgettable backdrop.', 'Features daily classical dance performances by leading exponents of Bharatanatyam, Kuchipudi, Kathak, and Mohiniyattam.', ARRAY['Nightly classical dance performances staged on an open-air stone stage on the beach', 'Dramatic floodlighting illuminating the 1,300-year-old twin stone spires of the Shore Temple', 'Craft exhibition showcasing master stone carvers creating granite sculptures on site']::TEXT[], 'Connoisseurs sit under cool coastal night skies, listening to the roar of crashing ocean waves mingling with classical mridangam and violin melodies.', ARRAY['Fresh grilled seafood', 'Masala Dosa', 'Filter Coffee', 'Medu Vada', 'Mango Kulfi']::TEXT[], 'Comfortable evening coastal casuals, handloom cotton kurtas, elegant silk sarees, and sandals.', 'Classical Carnatic music, mridangam percussion, nattuvangam cymbals, and classical vocal ragas.', 'Twin spires of the Shore Temple, sculpted Nandi bulls on stone walls, and breaking waves of the Bay of Bengal.', '30 Days', 'Gregorian / Winter', 'Held from late December to late January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Runs for four weeks across December and January.', '2026-12-25', '2027-12-25', 'Department of Tourism Tamil Nadu & ASI', ARRAY['Tamil Nadu']::TEXT[], ARRAY['Mamallapuram', 'Chengalpattu']::TEXT[], ARRAY['Shore Temple Complex', 'Mamallapuram Beach']::TEXT[], 'Evenings between 6 PM and 8:30 PM for sunset viewing and open-air classical dance recitals', 2, 'Pure poetic magic: standing on the seashore where ancient stone temple spires glow in golden light while classical dancers move to the rhythm of ocean waves.', '55 km south of Chennai along the East Coast Road (ECR); easily accessible by taxi or tourist bus.', 'Beachfront luxury resorts, boutique heritage hotels, and guesthouses in Mahabalipuram.', 'Pleasant coastal winter evenings; carry a light shawl; open-air beach seating.', 'Strict archaeological protection: stay behind protective railings; do not touch fragile ancient stone temple walls.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tamilnadutourism.tn.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-tirumala-brahmotsavam', 'Tirumala Brahmotsavam Tirupati', ARRAY['Salakatla Brahmotsavam']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Kali Yuga Varada)', 'The glorious nine-day festival celebrated at the richest and most visited temple in the world, where Lord Venkateswara is carried in majestic processions on different celestial vehicles.', 'Instituted by Lord Brahma according to sacred tradition; documented in Chola, Pallava, and Vijayanagara royal inscriptions for over a millennium.', 'Celebrates the glory of Lord Venkateswara (Balaji), the preserver of the universe and savior of Kali Yuga.', 'To behold the Lord of the Seven Hills riding majestic golden vehicles and seek liberation from worldly suffering.', 'Attracts over a million pilgrims to the holy hill of Tirumala during the nine-day celebration.', 'The crowning spectacle is the ''Garuda Vahana Seva'' on the fifth night, when Lord Venkateswara adorned in the priceless Makarakandi jewels rides his divine eagle mount Garuda.', ARRAY['Daily morning and evening processions of Lord Malayappa Swamy on different celestial vahanas (vehicles)', 'Garuda Vahana Seva on the fifth night viewed by over 500,000 pilgrims along the four Mada Streets', 'Grand wooden chariot procession (Rathotsavam) followed by the sacred holy bath (Chakrasnanam) in Swami Pushkarini']::TEXT[], 'The four Mada streets surrounding the golden temple turn into a roaring sea of faith, with devotees chanting ''Govinda, Govinda, Venkataramana Govinda''.', ARRAY['Tirupati Laddu (world-famous GI-tagged gram flour, cashew, and cardamom sweet)', 'Daddojanam (temple curd rice)', 'Pulihora (tamarind rice)', 'Pongal', 'Appam']::TEXT[], 'Traditional white cotton dhotis with gold borders and Angavastram for men; traditional Kanjeevaram and Gadwal silk sarees for women.', 'Continuous chanting of the Govinda Nama, classical Carnatic vocal and instrumental concerts, and traditional Nadaswaram-Thavil.', 'Golden Vimana dome (Ananda Nilayam), golden Garuda Vahana vehicle, Tirupati Laddu prasad, and sacred Seven Hills.', '9 Days', 'Hindu Lunisolar', 'Ashwin month (September - October) culminating on Vijyadashami.', 'September - October', 'LUNISOLAR', 'Held during Navratri in Ashwin month.', '2026-10-12', '2027-10-01', 'Tirumala Tirupati Devasthanams (TTD)', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Tirumala', 'Tirupati']::TEXT[], ARRAY['Tirumala Venkateswara Temple', 'Four Mada Streets', 'Swami Pushkarini']::TEXT[], 'Fifth night for the glorious Garuda Vahana Seva and final day morning for Chakrasnanam', 3, 'Colossal, spine-tingling spiritual magnitude: beholding the Lord of the Seven Hills glowing in diamonds under torchlight, surrounded by 500,000 chanting pilgrims.', 'Tirupati Airport connects to major Indian cities; well connected by trains to Tirupati Main and Renigunta stations; ghat roads connect up to Tirumala.', 'TTD dharamshalas, cottages, and private hotels in Tirupati and Tirumala; book 3-4 months in advance via TTD online portal.', 'Massive crowd density; general darshan queue can take 12-24 hours; book special entry darshan tickets online weeks ahead.', 'Strict traditional dress code strictly enforced: men must wear dhoti/kurta; women in sarees or salwar suits; no Western clothing permitted.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tirupatibalaji.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ugadi-andhra', 'Ugadi Statewide', ARRAY['Telugu New Year', 'Chaitra Suddha Padyami']::TEXT[], 'Seasonal & Nature', 'Hinduism (Telugu New Year & Six Flavors)', 'The auspicious Telugu New Year celebrated with the reading of the new astrological almanac (Panchanga Sravanam) and tasting the unique six-flavor ''Ugadi Pachadi''.', 'Ancient solar-lunar festival marking the beginning of the Shalivahana Saka calendar and the dawn of creation by Lord Brahma on Chaitra Pratipada.', 'Celebrates the arrival of spring, rejuvenation of nature, and the philosophical acceptance of all experiences of life.', 'To welcome the new year with prayers, astrological wisdom, and consume the symbolic six-flavor dish representing life''s emotions.', 'Famous for the iconic ''Ugadi Pachadi'' containing six tastes: sweet (jaggery/happiness), sour (tamarind/challenges), bitter (neem/sadness), salty (salt/fear), spicy (chili/anger), and astringent (raw mango/surprise).', 'Features the formal civic and temple tradition of ''Panchanga Sravanam'' where astrologers read predictions for the year ahead.', ARRAY['Preparing and consuming the six-flavor Ugadi Pachadi as the first food of the new year', 'Decorating doorways with fresh mango leaves (Toranams) and colorful floor Kolams', 'Panchanga Sravanam: gathering to listen to the new year''s astrological almanac and weather predictions']::TEXT[], 'Families wake before dawn, take oil baths, wear new clothes, and visit temples to pray for prosperity before enjoying sweet festive banquets.', ARRAY['Ugadi Pachadi (unique six-taste chutney of neem, jaggery, raw mango, tamarind, chili, salt)', 'Bobbatlu (Bhakshalu - sweet stuffed lentil flatbreads)', 'Pulihora', 'Pooreelu', 'Boorelu']::TEXT[], 'Traditional Telugu attire: crisp white Pancha (dhoti) with Kanduva (stole) for men; rich Mangalagiri and Dharmavaram silk sarees for women.', 'Classical Carnatic music concerts, Kavi Sammelans (poetic symposiums), and devotional Telugu singing.', 'Fresh green mango leaves, yellow neem blossoms, traditional clay bowls of Ugadi Pachadi, and colorful Muggulu floor art.', '1 Day', 'Hindu Lunisolar (Shalivahana Saka)', 'First day of Shukla Paksha in Chaitra month (Chaitra Suddha Padyami).', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Suddha Padyami.', '2026-03-20', '2027-04-07', 'Government of Andhra Pradesh & Endowments Department', ARRAY['Andhra Pradesh', 'Telangana']::TEXT[], ARRAY['Vijayawada', 'Tirupati', 'Visakhapatnam', 'Rajahmundry']::TEXT[], ARRAY['Kanaka Durga Temple Vijayawada', 'Family homes statewide']::TEXT[], 'Morning hours between 7 AM and 11 AM for family rituals, Ugadi Pachadi tasting, and temple visits', 1, 'Profound philosophical depth and heartwarming family joy: tasting life''s six flavors together, surrounded by fragrant mango leaves and warm Telugu hospitality.', 'Easily accessible across Andhra Pradesh via train, bus, and flight.', 'Hotels throughout major Andhra cities.', 'Warm spring sunshine; stay hydrated; enjoy the leisure and culture.', 'Taste the traditional Ugadi Pachadi with an open, reflective heart; savor freshly made hot Bobbatlu with ghee.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://aptourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lepakshi-heritage-festival', 'Lepakshi Heritage Festival', ARRAY['Lepakshi Utsav']::TEXT[], 'Historical & Royal', '16th-Century Vijayanagara Architecture & Mythology', 'A magnificent two-day cultural festival celebrated amidst the 16th-century Veerabhadra Temple, the mysterious Hanging Pillar, and India''s largest monolithic Nandi bull.', 'Initiated by Andhra Pradesh Tourism to celebrate the extraordinary architectural genius of the Vijayanagara Empire built by brothers Virupanna and Veeranna in 1530 CE.', 'Commemorates the Ramayana legend where the heroic bird Jatayu fell wounded fighting Ravana, and Lord Rama blessed him with the words ''Le Pakshi'' (Rise, bird).', 'To promote archaeological conservation and showcase classical performing arts against the world-famous carved stone temple.', 'Features the world-renowned ''Hanging Pillar'' of Lepakshi (which does not touch the ground, allowing cloth to pass beneath it) and exquisite ceiling frescoes.', 'The colossal monolithic Nandi bull, carved out of a single granite boulder measuring 15 feet high and 27 feet long, serves as an illuminated natural stage backdrop.', ARRAY['Classical dance and music recitals staged on the open-air stone plaza near the monolithic Nandi', 'Guided architectural walks exploring the 70 carved stone pillars and ceiling fresco paintings', 'Folk arts carnival featuring traditional shadow puppetry (Tholu Bommalata) and Kolattam']::TEXT[], 'Connoisseurs wander through ancient pillared halls, watching classical dancers perform to live mridangam beneath 500-year-old carved granite pillars.', ARRAY['Andhra Thali: Gongura Pachadi, Pappu, Rice with Ghee', 'Ragi Sankati with Natu Kodi Pulusu', 'Pootharekulu (paper-thin sweet wafer of Atreyapuram - GI Tagged)', 'Bobbatlu']::TEXT[], 'Traditional handloom Dharmavaram silk sarees, dhotis with Angavastram, and smart ethnic casuals.', 'Classical Carnatic music, Kuchipudi classical dance dramas, and traditional Tholu Bommalata shadow puppetry.', 'Colossal monolithic granite Nandi bull, multi-headed stone Nagalinga snake sculpture, and hanging stone pillar.', '2 Days', 'Gregorian / Winter', 'Held in February annually.', 'February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Andhra Pradesh Tourism.', '2026-02-14', '2027-02-13', 'Department of Tourism Andhra Pradesh & Ananthapuramu Administration', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Lepakshi', 'Hindupur', 'Ananthapuramu']::TEXT[], ARRAY['Veerabhadra Temple Lepakshi', 'Monolithic Nandi Complex']::TEXT[], 'Evenings between 5:30 PM and 9 PM during the illuminated temple dance concerts', 2, 'Awe-inspiring architectural wonder: standing dwarfed before a colossal 500-year-old stone bull, watching classical Kuchipudi dancers perform under glowing spotlights.', '120 km north of Bengaluru International Airport (2-hour smooth highway drive via NH-44); 15 km from Hindupur railway station.', 'Hotels and guest houses in Hindupur or base yourself in Bengaluru and visit on a day trip.', 'Uneven stone flagstones; wear comfortable flat walking shoes; carry a hat for daytime sun.', 'Strict archaeological protection: do not touch fragile ancient ceiling fresco paintings; maintain sanctity inside the active sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://aptourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-flamingo-festival-nelapattu', 'Flamingo Festival Nelapattu & Pulicat Lake', ARRAY['Pulicat Bird Festival']::TEXT[], 'Seasonal & Nature', 'Secular / Coastal Wetland Ecology & Bird Migration', 'A delightful three-day eco-tourism festival celebrating the arrival of tens of thousands of pink greater flamingos and migratory birds to Pulicat Lake and Nelapattu Sanctuary.', 'Initiated in 2001 by the Andhra Pradesh Tourism Department and Forest Department to promote wetland conservation and eco-tourism.', 'Celebrates the natural phenomenon of trans-continental avian migration from Siberia, Central Asia, and the Rann of Kutch to the second-largest brackish water lagoon in India.', 'To raise environmental consciousness, support local fishing communities, and offer birdwatchers a breathtaking natural spectacle.', 'Over 15,000 pink greater and lesser flamingos, alongside pelicans, storks, and herons, feed in the shallow turquoise waters of Pulicat Lake.', 'Features boat safaris through the lagoon, photography workshops, birdwatching camps, and evening cultural concerts in Sullurpeta.', ARRAY['Boat safaris across the shallow brackish waters of Pulicat Lake to photograph feeding flamingo flocks', 'Birdwatching walkthroughs at Nelapattu Bird Sanctuary (one of the largest pelican nesting grounds in Southeast Asia)', 'Cultural dance performances, environmental seminars, and regional food exhibitions in Sullurpeta']::TEXT[], 'Nature lovers and families view vast pink clouds of flamingos wading gracefully through shallow lagoon waters, framed by blue skies and swaying palms.', ARRAY['Nellore Chepala Pulusu (famous spicy, tangy fish curry cooked in earthen pots)', 'Prawn Fry', 'Nellore Dosa', 'Bobbatlu', 'Tender Coconut']::TEXT[], 'Comfortable outdoor travel wear, walking shoes, sun hats, polarized sunglasses, and binoculars.', 'Traditional Telugu folk dances, classical Kuchipudi recitals, and nature-themed musical performances.', 'Pink flamingos with curved beaks, spot-billed pelicans in nesting trees, traditional fishing catamarans, and lagoon waters.', '3 Days', 'Gregorian / Winter', 'Held in January annually (during peak migratory bird season).', 'January', 'FIXED', 'Held annually in mid-January.', '2026-01-18', '2027-01-17', 'Department of Tourism Andhra Pradesh & Forest Department', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Sullurpeta', 'Nelapattu', 'Pulicat Lake', 'Tirupati']::TEXT[], ARRAY['Nelapattu Bird Sanctuary', 'Pulicat Lake Lagoon']::TEXT[], 'Early morning (6:30 AM to 10 AM) for the best birdwatching light and active flamingo feeding', 2, 'Magical natural tranquility: gliding silently across vast coastal lagoons watching thousands of graceful pink flamingos take flight against morning golden skies.', 'Sullurpeta railway station is on the Chennai-Vijayawada mainline; 85 km north of Chennai Airport via NH-16.', 'Hotels in Sullurpeta, forest rest houses, and accommodations in nearby Sriharikota or Chennai.', 'Carry binoculars, telephoto lenses, sun protection, and insect repellent; wear muted earthy colors so as not to startle birds.', 'Eco-sensitive wildlife sanctuary: strictly no littering or plastic waste; do not shout or approach nesting birds too closely.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://tirupati.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-visakha-utsav', 'Visakha Utsav Visakhapatnam', ARRAY['Vizag Beach Cultural Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Maritime Beach Culture & Andhra Arts', 'A vibrant three-day coastal carnival celebrated along the scenic Rama Krishna (RK) Beach and surrounding hills of the ''City of Destiny''.', 'Established by Andhra Pradesh Tourism to celebrate the maritime heritage, cultural diversity, and industrial progress of Visakhapatnam.', 'Celebrates coastal leisure, Andhra folk and classical arts, and the scenic beauty of the Eastern Ghats meeting the Bay of Bengal.', 'To promote coastal tourism, showcase regional artisans, and offer world-class musical entertainment on the beach.', 'Staged along the sprawling RK Beach promenade, flanked by the historic submarine museum (INS Kursura) and TU-142 aircraft museum.', 'Features international watersports, helicopter joyrides, sand art competitions, and star-studded musical concerts.', ARRAY['Grand carnival street parade along the RK Beach promenade featuring traditional folk performers', 'Live sand art demonstrations and helicopter joyrides over the scenic coastal coastline', 'Nightly open-air musical concerts featuring leading Indian classical and Bollywood playback singers']::TEXT[], 'Hundreds of thousands of families stroll along the sea promenade under sea breezes, enjoying carnival joyrides, beach food, and live music.', ARRAY['Visakhapatnam seafood curries', 'Bamboo Chicken of Araku Valley', 'Madugula Halwa (century-old wheat halwa - GI Application)', 'Punugulu with spicy chutney', 'Bongu Biryani']::TEXT[], 'Coastal casuals, resort wear, light cotton shirts, and comfortable walking shoes.', 'Traditional Andhra folk dances: Dhimsa tribal dance of Araku, Tappeta Gullu, and high-energy fusion musical bands.', 'Submarine INS Kursura silhouette, breaking waves of RK Beach, sand art sculptures, and illuminated palm trees.', '3 Days', 'Gregorian / Winter', 'Held in December / January annually.', 'December - January', 'ORGANIZER_ANNOUNCED', 'Announced annually by Andhra Pradesh Tourism.', '2026-12-26', '2027-12-26', 'Andhra Pradesh Tourism Board & Visakhapatnam District Administration', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Visakhapatnam (Vizag)']::TEXT[], ARRAY['RK Beach Promenade', 'Kailasagiri Hill', 'Jatara Grounds']::TEXT[], 'Late afternoon from 3:30 PM to 10 PM for beach activities and evening musical concerts', 2, 'Vibrant, breezy coastal celebration where the rolling blue waves meet the lush hills of the Eastern Ghats, filled with music and delicious food.', 'Visakhapatnam International Airport; major railway junction on Chennai-Howrah line; well connected by highways.', 'Beachfront luxury hotels, resorts along Rushikonda Beach, and city hotels across Vizag.', 'Large evening crowds along the beach road; vehicle movement is restricted on the promenade; parking in designated lots.', 'Keep the coastal beach clean; follow lifeguards'' instructions regarding ocean swimming.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://visakhapatnam.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-kotappakonda-fair-guntur', 'Kotappakonda Fair Guntur', ARRAY['Kotappakonda Prabha Festival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Towering Lighted Towers)', 'The spectacular Maha Shivratri fair celebrated at the sacred three-peaked Trikuta Hill, famous for towering 100-foot illuminated bamboo towers (Prabhas) carried by tractors.', 'Ancient Shaivite festival dating back over 1,000 years to the Chola and Kakatiya eras, honoring Lord Kotappa (Trikoteswara Swamy) atop the hill.', 'Celebrates the manifestation of Lord Shiva as Dakshinamurthy and his divine meditation on the three sacred peaks representing Brahma, Vishnu, and Shiva.', 'To climb the sacred hill, worship Lord Shiva on Maha Shivratri, and bring towering decorated ''Prabhas'' as offerings.', 'Famous for the monumental ''Prabhas''—colossal structural towers made of bamboo and cloth, standing up to 100 feet tall, decorated with LED lights and loudspeakers.', 'Over 100 giant Prabhas mounted on decorated tractors and bullock carts are driven from neighboring villages, converging on the hill base like glowing neon skyscrapers.', ARRAY['Competitive arrival of dozens of 100-foot-tall illuminated bamboo towers (Prabhas) with deafening music', 'Climbing the 1,000 stone steps of the sacred Trikuta Hill to worship Lord Trikoteswara Swamy', 'Nightlong cultural performances, folk dances, and lightning shows at the foot of the mountain']::TEXT[], 'Over one million pilgrims gather in the valley, watching the jaw-dropping spectacle of dozens of 100-foot illuminated towers blazing with lights across the night sky.', ARRAY['Guntur Mirchi Bajji (world-famous spicy stuffed chili fritters)', 'Pulihora', 'Sakkarai Pongal', 'Ghee Jalebi', 'Sweet Bobbatlu']::TEXT[], 'Traditional white dhotis with Angavastram, colorful rural shirts, and bright cotton sarees.', 'Thunderous, fast-tempo beats of Tappeta Gullu, Dappu percussion, and high-decibel devotional songs playing from tower speakers.', '100-foot illuminated bamboo Prabha towers, glowing LED arches, sacred three-peaked Trikuta Hill, and temple spires.', '1 Day (All-Night)', 'Hindu Lunisolar', 'Culminates on Maha Shivratri night (February - March)', 'February - March', 'LUNISOLAR', 'Celebrated on Maha Shivratri.', '2026-02-15', '2027-03-06', 'Trikoteswara Swamy Temple Trust & Guntur Police', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Kotappakonda', 'Narasaraopet', 'Guntur']::TEXT[], ARRAY['Trikoteswara Swamy Temple Hill', 'Kotappakonda Foothills']::TEXT[], 'Maha Shivratri evening (6 PM to midnight) when all 100-foot illuminated Prabhas assemble in the valley', 2, 'Mind-boggling, surreal visual wonder: dozens of 100-foot-tall glowing neon towers rising out of the rural landscape, shaking the earth with thunderous music and faith.', '15 km from Narasaraopet railway station; 55 km from Guntur city; accessible by state transport buses.', 'Hotels in Guntur city or Narasaraopet; simple dharamshalas at the base of the hill.', 'Immense rural crowd density (over one million); keep safe distance from moving tractor-mounted towers and overhead power lines.', 'Climbing 1,000 stone steps to the hilltop temple requires physical stamina; ghat road with shuttle vans is also available.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://guntur.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sirimanotsavam-vizianagaram', 'Sirimanotsavam Vizianagaram', ARRAY['Pydithalli Ammavari Sirimanu Jathara']::TEXT[], 'Tribal & Folk Traditions', 'Folk Shaktism & Royal Goddess Heritage', 'The extraordinary folk festival where the temple priest is suspended from the tip of a 60-foot flexible wooden pole (Sirimanu), swaying high above cheering crowds.', 'Centuries-old festival of the historic Gajapati kings of Vizianagaram, dedicated to Goddess Pydithalli Ammavaru (patron goddess of the kingdom).', 'Commemorates the self-sacrifice and spiritual deification of Princess Pydimamba who drowned in the Pedda Cheruvu lake after the Battle of Bobbili in 1757.', 'To honor Goddess Pydithalli and pray for good rainfall, disease prevention, and agricultural bounty.', 'The centerpiece is the ''Sirimanu'' (sacred trunk of a tamarind tree), a 60-foot flexible pole mounted on a chariot.', 'The chief priest (Pujari), considered the living embodiment of the Goddess, sits in a chair at the tip of the pole, swaying dramatically 50 feet in the air.', ARRAY['Selection and cutting of the sacred 60-foot tamarind tree trunk revealed to the priest in a dream', 'Mounting of the chief priest at the tip of the flexible Sirimanu pole atop a moving chariot', 'Procession of the swaying Sirimanu chariot three times between the royal Vizianagaram Fort and temple']::TEXT[], 'Over 400,000 devotees pack the streets and fort walls, throwing bananas and flowers at the priest swaying high above their heads amidst wild cheering.', ARRAY['Andhra Pulihora', 'Chakra Pongali', 'Madugula Halwa', 'Bobbatlu', 'Garijelu']::TEXT[], 'Traditional white dhotis with red stoles, bright festive sarees, and yellow turmeric markings on foreheads.', 'Thunderous rural folk drumming with Dappu, Tappeta Gullu, and energetic Garagalu brass pot balancing dances.', '60-foot wooden Sirimanu pole with swaying seat, decorated royal elephant chariot (Anjali Ratham), and Vizianagaram Fort.', '1 Day', 'Hindu Lunisolar / Autumn', 'First Tuesday following Vijyadashami (Dussehra) in October', 'October', 'LUNISOLAR', 'First Tuesday after Dussehra.', '2026-10-27', '2027-10-19', 'Sri Pydithalli Ammavari Devasthanam & Vizianagaram Police', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Vizianagaram']::TEXT[], ARRAY['Pydithalli Ammavari Temple', 'Vizianagaram Fort Road']::TEXT[], 'Afternoon between 3 PM and 6:30 PM when the Sirimanu chariot moves along the fort road', 1, 'Thrilling, heart-stopping folk spectacle: watching a priest suspended 50 feet in the air swaying gracefully over a cheering ocean of nearly half a million devotees.', 'Vizianagaram Junction is a major railway station; 55 km from Visakhapatnam International Airport.', 'Hotels in Vizianagaram town or stay in nearby Visakhapatnam city.', 'Very dense street crowds; stay on elevated pavements or balconies along the fort road.', 'Devotees throw bananas towards the swaying priest as blessings; protect your eyes from flying fruit.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://vizianagaram.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-rottela-panduga-nellore', 'Rottela Panduga Nellore', ARRAY['Roti Festival of Bara Shaheed Dargah']::TEXT[], 'Spiritual & Temple', 'Sufism & Interfaith Wish Fulfillment', 'The unique four-day festival of flatbreads celebrated at the sacred lake of Bara Shaheed Dargah, where millions of people of all faiths exchange rotis for wish fulfillment.', 'Centuries-old syncretic festival honoring twelve noble Muslim martyrs (Bara Shaheed) who died defending Nellore against invading forces.', 'Celebrates communal harmony, divine sacrifice, and the miraculous power of shared food and prayers.', 'To exchange flatbreads (Rotis) standing in the sacred Swarnala Cheruvu lake to fulfill specific life wishes (health, marriage, children, jobs, education).', 'One of India''s most extraordinary examples of inter-faith solidarity, where over 80% of participants are non-Muslims who share faith in the martyrs.', 'Rotis are categorized by wish: ''Sowbhagya Roti'' (for marriage), ''Santana Roti'' (for children), ''Udyoga Roti'' (for jobs), ''Arogya Roti'' (for health), and ''Vidya Roti'' (for education).', ARRAY['Worship at the tombs of the twelve martyrs (Bara Shaheed Dargah) with floral chadars', 'Wading waist-deep into the waters of the sacred Swarnala Cheruvu lake holding flatbreads', 'Exchanging rotis with another person whose wish was already fulfilled the previous year']::TEXT[], 'Lakhs of pilgrims from all faiths wade into the calm lake waters under the evening sky, calling out wishes and exchanging blessed rotis with strangers.', ARRAY['Savoury and sweet wheat Rotis (flatbreads)', 'Nellore Mutton Biryani', 'Ghee Rice with Dalcha', 'Sheer Khurma', 'Halwa']::TEXT[], 'Traditional modest attire: white dhotis, kurtas, green and white scarves, and traditional cotton sarees.', 'Soulful Sufi Qawwalis, Dargah prayers, Daf drumming, and the cheerful hum of thousands exchanging rotis.', 'Twelve whitewashed tombs of Bara Shaheed Dargah, tranquil waters of Swarnala Cheruvu lake, and exchange of wrapped flatbreads.', '4 Days', 'Islamic Lunar (Muharram)', 'Observed during the holy month of Muharram (Ashura season).', 'July', 'LUNAR', 'Observed during the month of Muharram.', '2026-07-28', '2027-07-17', 'Bara Shaheed Dargah Committee & Nellore Municipal Corporation', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Nellore']::TEXT[], ARRAY['Bara Shaheed Dargah', 'Swarnala Cheruvu Lake']::TEXT[], 'Evening between 4 PM and 9 PM when the lake roti exchange reaches peak activity', 2, 'Profound, heartwarming human brotherhood: standing knee-deep in a tranquil lake exchanging bread with complete strangers in shared hope and joy.', 'Nellore railway station connects to Chennai (3 hours); well connected by highway NH-16.', 'Hotels and guest houses across Nellore city.', 'Wading into the lake involves wet clothing; changing enclosures are available along the banks.', 'If your wish is granted, it is sacred custom to return the following year with a roti to gift to another hopeful soul.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://nellore.ap.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bhavani-deeksha-vijayawada', 'Bhavani Deeksha Vijayawada', ARRAY['Kanaka Durga Bhavani Mandalam']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaktism / Red Robe Austerity)', 'The massive pilgrimage where over one million red-clad Bhavani devotees conclude their 41-day vow at the ancient Kanaka Durga Temple atop Indrakeeladri Hill.', 'Ancient Shakta tradition centered around the golden Kanaka Durga Temple mentioned in Mahabharata, where Arjuna meditated to obtain the Pasupatastra weapon.', 'Commemorates the triumph of Goddess Kanaka Durga over the buffalo demon Mahishasura on Indrakeeladri Hill overlooking the Krishna River.', 'To observe strict 41-day austerity, surrender the ego to the Divine Mother, and conclude the vow (Deeksha Viramana) at the holy sanctum.', 'Devotees wear bright red robes, walk barefoot, observe strict celibacy and vegetarianism, and carry the sacred ''Irumudi'' bundle on their heads.', 'The festival concludes with the magnificent ''Teppotsavam'' (celestial boat festival) where the deity is taken on a swan-shaped boat across the Krishna River.', ARRAY['Circumambulation (Giri Pradakshina) around the sacred Indrakeeladri Hill carrying the red Irumudi bundle', 'Concluding the 41-day vow (Deeksha Viramana) and offering coconut and ghee to Goddess Kanaka Durga', 'Spectacular swan boat procession (Teppotsavam) carrying the golden deity across the sacred Krishna River']::TEXT[], 'Vijayawada turns into a sea of bright red as hundreds of thousands of barefoot devotees fill the ghats and bridges, chanting ''Bhavani Mata Ki Jai''.', ARRAY['Kanaka Durga Laddu (famous temple prasad)', 'Pulihora', 'Chakra Pongali', 'Sweet Dosa', 'Andhra Meals']::TEXT[], 'Vibrant bright red robes (dhotis, kurtas, sarees), Rudraksha malas, and bare feet.', 'Thunderous chanting of ''Jai Bhavani, Jai Durga'', temple conch shells, Nadaswaram, and traditional Telugu devotional songs.', 'Towering golden temple gopuram atop Indrakeeladri Hill, sacred Krishna River waters, and glowing swan boat.', '5 Days', 'Hindu Lunisolar', 'Culminates on Margashirsha Purnima (December - January)', 'December - January', 'LUNISOLAR', 'Culminates on Margashirsha Purnima.', '2026-12-24', '2027-12-13', 'Sri Durga Malleswara Swamyvarla Devasthanam & Vijayawada Police', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Vijayawada', 'Krishna']::TEXT[], ARRAY['Kanaka Durga Temple Indrakeeladri', 'Krishna River Ghats']::TEXT[], 'Dawn for the sacred hill walk (Giri Pradakshina) and sunset for the Krishna River swan boat festival', 2, 'Awe-inspiring wave of red-robed devotion, breathless views of the sacred river from the cliffside temple, and profound mother goddess grace.', 'Vijayawada International Airport; major railway junction connecting all parts of India.', 'Hotels throughout Vijayawada; temple devaswom dharamshalas near the ghats.', 'Dense crowds around Indrakeeladri steps; special queue lines operate; follow volunteer marshals.', 'Observe the 41-day vow with purity if undertaking the formal pilgrimage; general tourists can visit for darshan.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://kanakadurgamma.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-amaravati-buddhist-festival', 'Amaravati Buddhist Heritage Festival', ARRAY['Dhyana Buddha Heritage Fest']::TEXT[], 'Art & Cultural Festival', 'Buddhism & Ancient Satavahana Art', 'A serene international festival celebrating the 2,000-year-old Buddhist art, stupas, and heritage of ancient Amaravati along the Krishna River.', 'Initiated by Andhra Pradesh Tourism to celebrate the ancient capital of the Satavahana dynasty, where the glorious Mahachaitya stupa was built in the 2nd century BCE.', 'Celebrates the Mahayana and Vajrayana Buddhist philosophy nurtured by the legendary philosopher Acharya Nagarjuna at Amaravati.', 'To promote archaeological conservation and celebrate Buddhist peaceful ideals in the shadow of the colossal 125-foot Dhyana Buddha statue.', 'Amaravati is world-famous in art history for its distinct ''Amaravati School of Art'', celebrated for dynamic, expressive limestone relief carvings.', 'Features international Buddhist delegations from Japan, Thailand, Sri Lanka, and Tibet chanting under the open sky beside the river.', ARRAY['Solemn peace prayers and meditation under the monumental 125-foot Dhyana Buddha statue', 'Guided archaeological walks through the ancient excavated Mahachaitya stupa ruins and museum', 'International classical and devotional musical concerts on the Krishna riverfront']::TEXT[], 'Monks in saffron and maroon robes sit in serene contemplation beside the river, while visitors explore priceless 2,000-year-old limestone carvings.', ARRAY['Sattvic Andhra vegetarian meals', 'Khichdi with Ghee', 'Sweet Pongal', 'Filter Coffee', 'Fresh fruit offerings']::TEXT[], 'Monastic robes of various Buddhist traditions, alongside crisp white cotton pilgrim clothing.', 'Deep harmonic Buddhist chanting, Tibetan monastic trumpets, meditative gong chimes, and classical flute recitals.', 'Monumental 125-foot Dhyana Buddha statue, ancient limestone stupa railings, and flowing Krishna River.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Andhra Pradesh Tourism.', '2026-02-06', '2027-02-05', 'Department of Tourism Andhra Pradesh & Guntur Administration', ARRAY['Andhra Pradesh']::TEXT[], ARRAY['Amaravati', 'Guntur', 'Vijayawada']::TEXT[], ARRAY['Dhyana Buddha Complex Amaravati', 'Amaravati Archaeological Museum']::TEXT[], 'Morning meditation at 8 AM and sunset views of the 125-foot Buddha statue reflecting in the Krishna River', 2, 'Profound meditative peace, ancient monolithic art, gentle river ripples, and timeless Buddhist wisdom in a cradle of world sculpture.', '35 km from Vijayawada railway station; 50 km from Vijayawada Airport; accessible by highway taxi.', 'Hotels in Vijayawada or Guntur; tourist guest houses in Amaravati.', 'Pleasant sunny winter days; comfortable walking shoes recommended for archaeological museum grounds.', 'Maintain quiet respect around the Dhyana Buddha meditation hall and archaeological excavations.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://aptourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bathukamma-telangana', 'Bathukamma Statewide', ARRAY['Floral Festival of Telangana', 'Maha Gauri Festival']::TEXT[], 'Seasonal & Nature', 'Hinduism (Folk Shaktism & Floral Ecology)', 'The state festival of Telangana where women create monumental multi-tiered conical flower pyramids using wild monsoon blossoms, dancing in graceful circles.', 'Centuries-old indigenous festival unique to Telangana, celebrated during the monsoon harvest, embodying the emotional and cultural soul of Telangana women.', 'Commemorates Goddess Gauri (Bathukamma literally means ''Mother, Come Alive!'') and celebrates nature''s healing botanical bounty.', 'To honor womanhood, celebrate the medicinal properties of wild monsoon flowers, and invoke blessings for family health and prosperity.', 'Features the crafting of ''Bathukamma''—colossal concentric conical mounds meticulously arranged with seasonal wild flowers (Gunugu, Thangedu, Gummadi, Katla).', 'Culminates on the 9th day ''Saddula Bathukamma'', when millions of women carry their flower pyramids on heads to lakes and immerse them peacefully at sunset.', ARRAY['Arranging concentric layers of wild medicinal flowers into a conical pyramid topped with turmeric Gouramma', 'Women and girls in silk sarees dancing in circles around the floral mounds, clapping and singing folk songs', 'Ceremonial carrying of Bathukammas on heads to local lakes and gently floating them on the water at dusk']::TEXT[], 'Lakes and city squares across Hyderabad and Telangana turn into an ocean of millions of floating flower pyramids glowing under evening lights.', ARRAY['Maleeda (sweet balls of jaggery and roti)', 'Saddulu (five varieties of spiced rice: tamarind, lemon, sesame, peanut, and curd)', 'Sakinalu', 'Puri']::TEXT[], 'Exquisite traditional silk sarees: Pochampally Ikat, Gadwal, and Narayanpet silks, adorned with gold jewelry; young girls wear Langa Voni.', 'Graceful, rhythmic Bathukamma folk songs celebrating sisterhood, folk mythology, and village life, accompanied by synchronized hand claps.', 'Conical flower pyramid made of yellow Thangedu and white Gunugu flowers, golden turmeric Gauramma, and floating lake lights.', '9 Days', 'Hindu Lunisolar', 'Begins on Bhadrapada Amavasya (Mahalaya) and ends on Durgashtami (Ashwin month)', 'October', 'LUNISOLAR', 'Culminates on Durgashtami (Saddula Bathukamma).', '2026-10-18', '2027-10-07', 'Department of Culture Government of Telangana', ARRAY['Telangana']::TEXT[], ARRAY['Hyderabad', 'Warangal', 'Karimnagar', 'Nizamabad']::TEXT[], ARRAY['Hussain Sagar Lake Hyderabad', 'Bhadrakali Lake Warangal']::TEXT[], 'Saddula Bathukamma evening (Day 9) from 4:30 PM to 8:30 PM when millions of flower mounds are immersed', 3, 'Breathtaking, deeply feminine ecological wonder: millions of women singing in graceful circles around towering floral pyramids that gently float away into shimmering waters.', 'Rajiv Gandhi International Airport Hyderabad; Hyderabad Metro connects to Tank Bund and Hussain Sagar lake.', 'Hotels throughout Hyderabad and Telangana district centers.', 'Very crowded lakefronts on Saddula Bathukamma night; use designated tourist viewing galleries along Tank Bund.', 'Eco-friendly heritage: all flowers used are natural and biodegradable, acting as natural water purifiers for local lakes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://telanganatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-bonalu-hyderabad', 'Bonalu Hyderabad & Secunderabad', ARRAY['Mahankali Bonalu Jathara']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Shaktism & Ward Health)', 'The exuberant folk festival of the twin cities where women carry colorfully painted brass and earthen pots balanced on heads to thank Goddess Mahakali.', 'Initiated in 1813 CE during a catastrophic plague in Hyderabad; military soldiers prayed to Goddess Mahakali in Ujjain and vowed to build temples upon deliverance.', 'Commemorates the return of Goddess Mahakali to her maternal home during the monsoon month of Ashadha.', 'To thank the Mother Goddess for protecting the city from epidemics, and pray for family health and good rains.', 'Celebrated on successive Sundays across historic temple zones: Golconda Fort, Ujjaini Mahakali Temple (Secunderabad), and Lal Darwaza (Old City).', 'Features the fierce character ''Pothuraju'' (brother of the Goddess), a bare-chested warrior with bells on ankles who cracks whips to drive away evil spirits.', ARRAY['Preparing ''Bonam'' (cooked rice with milk and jaggery inside brass or clay pots decorated with neem leaves and burning lamps)', 'Women balancing the burning Bonam pots on their heads while dancing to the temple', 'Rangam (the oracle ceremony): a maiden standing atop an earthen pot enters a trance to prophesy the city''s future']::TEXT[], 'The streets of Hyderabad resound with wild drumming, as thousands of women carry glowing pots on heads, guided by dancing Pothurajus cracking whips.', ARRAY['Bonalu Mahaprasad (cooked rice with jaggery and curd)', 'Mutton Biryani (traditionally cooked in community feasts after animal sacrifice)', 'Puri Sabzi']::TEXT[], 'Traditional silk and cotton sarees in bright red, yellow, and green; turmeric and vermilion paste adorning face and neck.', 'Thunderous, fast-paced rhythm of traditional Teen Maar drumbeats, Marfa percussion, and ecstatic folk dancing.', 'Painted earthen and brass Bonam pots with burning oil lamps, neem leaves, whip-cracking Pothuraju, and Golconda Fort battlements.', '1 Month (Celebrated over 4 Sundays)', 'Hindu Lunisolar / Monsoon', 'Sundays of the holy month of Ashadha (July - August).', 'July - August', 'LUNISOLAR', 'Celebrated across Ashadha month.', '2026-07-19', '2027-07-11', 'Government of Telangana Endowments Department & Police', ARRAY['Telangana']::TEXT[], ARRAY['Hyderabad', 'Secunderabad']::TEXT[], ARRAY['Golconda Fort Jagadambika Temple', 'Ujjaini Mahakali Temple Secunderabad', 'Lal Darwaza']::TEXT[], 'Sundays of Ashadha month, especially Secunderabad Mahakali Bonalu and Old City Lal Darwaza Bonalu', 3, 'High-voltage, raw folk energy: thundering Teen Maar drumbeats, whip-cracking warrior dancers, burning pots balanced on heads, and electric street ecstasy.', 'Hyderabad Metro connects directly to Secunderabad and Old City stations; app cabs and auto-rickshaws widely available.', 'Extensive hotels across Hyderabad and Secunderabad.', 'Extremely heavy street crowds and dancing processions; stay on elevated pavements; protect personal belongings.', 'Accept the blessed Bonam prasad respectfully; do not obstruct the dancing Pothuraju whip performers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://telanganatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sammakka-saralamma-jatara', 'Sammakka Saralamma Jatara Medaram', ARRAY['Medaram Jatara', 'Asia''s Largest Tribal Fair']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Koya Tribal Freedom & Sacrifice', 'The largest tribal pilgrimage in Asia and second-largest congregation in India after the Kumbh Mela, where over 12 million people gather in the dense teak forests of Medaram.', 'Dates back to the 12th century, commemorating the heroic mother-daughter tribal leaders Sammakka and Saralamma who fought to the death against the Kakatiya Empire.', 'Celebrates indigenous freedom, forest rights, heroic maternal courage, and defiance against unjust feudal taxation.', 'To offer jaggery equal to one''s body weight (Bangaram - gold) to the tribal goddesses and bathe in the sacred Jampanna Vagu forest stream.', 'Celebrated once every two years (biennial) in the remote tribal heartland of Medaram in Mulugu district.', 'Completely distinct from orthodox Hinduism: strictly no idols, temples, or Vedic priests; the goddesses are worshipped as sacred forest trees and bamboo poles.', ARRAY['Taking holy cleansing dips in the sacred red waters of Jampanna Vagu forest stream', 'Weighing oneself on large balance scales and offering equivalent weight of jaggery (Bangaram) to the goddesses', 'Welcoming the arrival of the sacred deity caskets carried on foot by Koya tribal priests through the deep forest']::TEXT[], 'Over 12 million pilgrims camp under vast teak canopies across hundreds of square miles, cooking over wood fires and celebrating their tribal mother queens.', ARRAY['Bangaram (jaggery prasad distributed in massive quantities)', 'Jowar Roti with Chicken Curry', 'Rice with Dal', 'Pulihora']::TEXT[], 'Simple tribal and rural attire: white dhotis, cotton shirts, colorful handloom sarees, and yellow turmeric smeared on faces.', 'Thunderous, continuous beats of tribal Dappu and Kommu drums, accompanied by ancient Koya folk ballads.', 'Sacred wooden Gadde platforms under forest trees, towering bamboo totems, mounds of golden jaggery, and Jampanna Vagu waters.', '4 Days', 'Tribal-Hindu Lunisolar / Biennial', 'Magha Purnima every two years (even-numbered years: 2026, 2028).', 'February', 'LUNISOLAR', 'Celebrated biennially in February (held in 2026, next in 2028).', '2026-02-01', '2028-02-18', 'Telangana Tribal Welfare Department & Mulugu Administration', ARRAY['Telangana']::TEXT[], ARRAY['Medaram', 'Mulugu', 'Warangal']::TEXT[], ARRAY['Medaram Forest Grounds', 'Jampanna Vagu Stream']::TEXT[], 'Day of Sammakka''s arrival at the Gadde (Day 2 and 3) when religious fervor reaches its absolute peak', 3, 'Staggering, humbling anthropological magnitude: 12 million souls camping in a remote wilderness, united in fierce reverence for their ancient forest warrior queens.', '100 km from Warangal railway station; 240 km from Hyderabad; dedicated shuttle bus lanes and temporary roads operate during Jatara.', 'Vast temporary tented cities set up by the government; hotels in Warangal city.', 'Monumental crowds exceeding 10 million; travel strictly using designated government transport routes; carry drinking water.', 'Treat the sacred Koya tribal priests with deep reverence; do not attempt to enter the inner bamboo sanctum enclosure.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://mulugu.telangana.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-alai-balai-hyderabad', 'Alai Balai Hyderabad', ARRAY['Dussehra Cultural Harmony Festival']::TEXT[], 'Art & Cultural Festival', 'Secular / Social Solidarity & Telangana Pride', 'A cherished post-Dussehra cultural festival celebrating communal unity, social brotherhood, and the distinct folk arts and culinary traditions of Telangana.', 'Initiated in 2005 by senior statesman Bandaru Dattatreya to foster cross-party political harmony, celebrate Telangana statehood identity, and embrace all communities.', 'Celebrates the traditional ''Alai Balai'' custom of warm physical embraces, forgiveness, and mutual affection following Vijyadashami.', 'To provide a non-partisan platform where political rivals, cultural artists, and ordinary citizens celebrate Telangana heritage together.', 'Staged on the open grounds of Exhibition Grounds (Nampally) in Hyderabad, attended by political leaders of all parties, artists, and thousands of citizens.', 'Famous for its massive traditional feast showcasing over 50 authentic rural Telangana culinary preparations served free to all attendees.', ARRAY['Traditional ''Alai Balai'' ceremonial embrace between leaders of all political parties and community heads', 'Live folk music and dance performances by rural Telangana troupes (Oggu Katha, Gussadi, Chindu Bhagavatham)', 'Grand communal feast showcasing authentic traditional Telangana village cuisine cooked in massive cauldrons']::TEXT[], 'The festival ground buzzes with laughter, joyous embraces, live folk performances, and delicious aromas of authentic rural Telangana cooking.', ARRAY['Hyderabadi Biryani', 'Jonna Rotte (Sorghum flatbread) with Natu Kodi Pulusu', 'Sakinalu', 'Garijelu', 'Sarva Pindi', 'Ambli']::TEXT[], 'Traditional Telangana attire: Pancha (dhoti) with Kanduva stole for men; Pochampally and Gadwal silk sarees for women.', 'Soulful Telangana folk songs, high-energy Dappu drumming, Oggu Katha folk ballads, and Gussadi tribal dance.', 'Jammi tree leaves (symbolizing gold), colorful festive shamianas, and traditional brass cooking cauldrons.', '1 Day', 'Hindu Lunisolar / Post-Dussehra', 'Held on the day immediately following Vijyadashami (October).', 'October', 'LUNISOLAR', 'Held the day after Dussehra.', '2026-10-21', '2027-10-11', 'Alai Balai Foundation & Department of Culture Telangana', ARRAY['Telangana']::TEXT[], ARRAY['Hyderabad']::TEXT[], ARRAY['Exhibition Grounds Nampally Hyderabad']::TEXT[], 'Daytime from 11 AM to 4 PM for the cultural performances and grand communal feast', 1, 'Warm, inclusive celebration of political goodwill and cultural camaraderie: rivals embracing with smiles, united by love for Telangana''s rich heritage and food.', 'Centrally located in Nampally, Hyderabad; easily accessible via Nampally Metro Station and cabs.', 'Hotels throughout central Hyderabad.', 'Very popular public event; free entry; arrive early for the grand community lunch.', 'Embrace the spirit of Alai Balai: greet fellow attendees with warm handshakes and respectful smiles.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://telanganatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-golconda-masters-festival', 'Golconda Masters Cultural Festival', ARRAY['Golconda Fort Heritage Fest']::TEXT[], 'Historical & Royal', 'Qutb Shahi Dynasty Architecture & Sufi Music', 'A magnificent heritage festival celebrated inside the monumental 16th-century fortress of Golconda, famous for its miraculous acoustics and diamond history.', 'Organized by Telangana Tourism inside the historic capital of the Qutb Shahi sultans and Kakatiya kings, source of the Koh-i-Noor and Hope diamonds.', 'Celebrates Golconda''s glorious synthesis of Persian, Deccani, and Telugu courtly arts, architecture, and literature.', 'To promote heritage conservation and present world-renowned musicians in an acoustic marvel fortress.', 'Staged against the imposing Balahisar (upper citadel) and the grand arched durbar halls, famed for their acoustic clapping galleries.', 'Features nightlong classical Sufi Qawwali, Deccani poetry, classical Carnatic and Hindustani vocal recitals under starry skies.', ARRAY['Acoustic demonstrations at the Grand Portico where a handclap echoes clearly to the hilltop citadel 1 km away', 'Nightly Sufi Qawwali and classical music concerts inside illuminated historic stone courtyards', 'Guided heritage walks exploring the medieval water systems, royal tombs, and diamond vaults']::TEXT[], 'Audiences sit in the cool stone courtyards as soulful Qawwalis and classical melodies float against the massive granite fortress walls.', ARRAY['Hyderabadi Dum Biryani', 'Haleem', 'Mirchi Ka Salan', 'Double Ka Meetha', 'Irani Chai with Osmania Biscuits']::TEXT[], 'Sophisticated formal ethnic wear: Sherwanis, Kurta-pajamas with Nehru jackets, and elegant handloom sarees.', 'Soulful Deccani Qawwalis, classical Hindustani and Carnatic vocal recitals, sitar-sarod, and ghazal mehfils.', 'Massive granite bastions of Golconda Fort, acoustic arched gateways, diamond vault chambers, and evening floodlights.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Telangana Tourism.', '2026-01-23', '2027-01-22', 'Department of Tourism Government of Telangana & ASI', ARRAY['Telangana']::TEXT[], ARRAY['Hyderabad', 'Golconda']::TEXT[], ARRAY['Golconda Fort Complex', 'Balahisar Citadel']::TEXT[], 'Evenings between 6 PM and 9:30 PM for floodlit concerts inside the historic fort', 2, 'Majestic, romantic Deccani grandeur: ancient stone fortresses whispering with history, miraculous acoustics, and soulful melodies under a moonlit sky.', '11 km west of central Hyderabad; easily accessible by cab or auto-rickshaw.', 'Hotels and boutique stays across Banjara Hills, Jubilee Hills, and central Hyderabad.', 'Cobbled stone pathways and climbing to upper pavilions; wear sturdy flat walking shoes.', 'Strict heritage conservation: no climbing on historic stone ramparts; maintain silence during musical recitals.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://telanganatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-nagoba-jatara-adilabad', 'Nagoba Jatara Keslapur Adilabad', ARRAY['Mesram Clan Serpent Festival']::TEXT[], 'Tribal & Folk Traditions', 'Indigenous Gond Tribal Snake Deities', 'The sacred five-day tribal pilgrimage of the Mesram clan of Raj Gonds and Pardhans, who walk 100 km to fetch holy Godavari water to bathe the sacred serpent deity Nagoba.', 'Ancient tribal festival celebrated for centuries at Keslapur in the forested hills of Adilabad by the Mesram clan of Raj Gonds.', 'Celebrates the divine serpent god Sri Shesh Nag (Nagoba) and the ancestral lineage of the Mesram clan.', 'To perform sacred purification rites for new brides (Bheting) and seek blessings for tribal fertility and peace.', 'Features the ancient ''Bheting'' ritual: newly married brides are formally inducted into the Mesram clan by touching the serpent deity''s shrine.', 'Tribal elders walk over 100 kilometers barefoot carrying sacred brass pots (Jharia) to fetch holy water from the Godavari River at Hastinamadugu.', ARRAY['Solemn bathing of the sacred stone idol of Nagoba with holy Godavari water fetched from 100 km away', 'Bheting ceremony: formal induction and blessing of newly married tribal brides into the Mesram clan', 'Traditional ''Durbar'' administrative conference where government collectors meet tribal elders under banyan trees']::TEXT[], 'Tens of thousands of Raj Gond and Pardhan tribal families camp in bullock carts across the forest grounds, playing sacred flutes and drums.', ARRAY['Jowar Roti with spicy country chicken', 'Pulihora', 'Mahua beverage', 'Rice with wild greens']::TEXT[], 'Traditional Gond tribal dresses: white waistcloths, turbans, silver torque necklaces (Hasli), and colorful sarees.', 'Haunting, ancient melodies of the Kingri (three-stringed fiddle played by Pardhan bards), accompanied by Dappu drums.', 'Whitewashed shrine of serpent god Nagoba, sacred brass Jharia water vessels, and century-old banyan trees.', '5 Days', 'Hindu-Tribal Lunisolar / Winter', 'Starts on Pushya Amavasya (new moon night of Pushya month in January - February).', 'January - February', 'LUNISOLAR', 'Begins on Pushya Amavasya.', '2026-01-18', '2027-02-06', 'Mesram Clan Tribal Council & Adilabad Administration', ARRAY['Telangana']::TEXT[], ARRAY['Keslapur', 'Indervelly', 'Adilabad']::TEXT[], ARRAY['Nagoba Temple Grounds Keslapur']::TEXT[], 'Opening night on Pushya Amavasya for the sacred midnight Godavari water bathing ritual', 2, 'Authentic, untouched tribal forest anthropology: observing ancient clan rituals, haunting three-stringed bards, and deep ancestral reverence.', '30 km from Adilabad railway station; 300 km north of Hyderabad; accessible by highway buses and private cars.', 'Simple guesthouses in Adilabad town; camping on grounds with tribal families.', 'Remote rural forest setting; basic amenities; carry warm clothing for chilly January winter nights.', 'Only members of the Mesram clan are permitted inside the inner sanctum during peak midnight rites; tourists observe from courtyard enclosures.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://adilabad.telangana.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-komuravelli-mallanna-jatara', 'Komuravelli Mallanna Jatara', ARRAY['Mallikarjuna Swamy Jathara']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Shaivism & Oggu Katha Balladry)', 'The massive three-month folk pilgrimage celebrating Lord Mallanna (Shiva) inside a natural hill cave, world-famous for the colourful ''Patnam'' powder geometric mandalas.', 'Centuries-old folk tradition honoring Lord Mallanna, an indigenous pastoral manifestation of Lord Shiva revered by Kuruma and Golla (shepherd) communities.', 'Celebrates the marriage of Lord Mallanna with his consorts Goddess Medala Devi and Goddess Ketamma.', 'To offer sweet ''Bonam'' pots, seek healing and pastoral fertility, and listen to the heroic ballads of Oggu Katha.', 'World-renowned for the ''Patnam'' ritual: Kuruma priests spend hours drawing monumental geometric rangoli mandalas using five natural colored powders on the earth.', 'Devotees leap and dance across the colorful powder mandalas in devotional trance, chanting ''Mallanna Namam''.', ARRAY['Drawing of intricate multi-colored powder mandalas (Patnam) by traditional Kuruma priests', 'All-night storytelling and musical performances of Oggu Katha (epic ballads of Mallanna) with large drums', 'Carrying of sweet Bonam pots by women and offering sacred turmeric (Bhandar) to the cave deity']::TEXT[], 'The hills of Komuravelli glow with bright yellow turmeric powder as lakhs of devotees dance to thundering drums and leap across colorful mandalas.', ARRAY['Mallanna Bonam (sweet rice cooked with jaggery and milk)', 'Pulihora', 'Bobbattu', 'Country chicken curry (in village camps)']::TEXT[], 'Vibrant yellow shirts, dhotis, and sarees drenched in bright yellow turmeric powder (Bhandar).', 'High-voltage folk balladry: Oggu Katha performed with giant Damaru drums (Jaggu) and large brass cymbals (Thalam).', 'Natural hill cave shrine of Lord Mallanna, monumental multi-colored Patnam powder mandalas, and mounds of bright yellow turmeric.', '3 Months (Peak on Sankranti & Maha Shivratri)', 'Hindu Lunisolar', 'Begins on Makar Sankranti and lasts until Ugadi (January to April).', 'January - April', 'LUNISOLAR', 'Peak rituals occur on Sundays between Makar Sankranti and Maha Shivratri.', '2026-01-18', '2027-01-17', 'Sri Mallikarjuna Swamy Devasthanam & Siddipet Administration', ARRAY['Telangana']::TEXT[], ARRAY['Komuravelli', 'Siddipet', 'Jangaon']::TEXT[], ARRAY['Komuravelli Mallanna Temple Complex']::TEXT[], 'Sundays during the festival season, especially the Sunday preceding Maha Shivratri for Patnam rituals', 2, 'Electrifying folk devotional frenzy: swirling clouds of bright yellow turmeric, thundering sheep-skin drums, and breathtaking geometric powder floor art.', '85 km northeast of Hyderabad via Rajiv Rahadari highway; 25 km from Jangaon railway station.', 'Temple dharamshalas at Komuravelli; hotels in Siddipet and Hyderabad.', 'Heavy yellow turmeric powder in the air; wear clothes you do not mind getting stained yellow.', 'Admire the intricate Patnam floor mandala from designated viewing barriers before the ceremonial dancing begins.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://siddipet.telangana.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-edupayala-jathara', 'Edupayala Vana Durga Bhavani Jathara', ARRAY['Seven Streams Goddess Fair']::TEXT[], 'Spiritual & Temple', 'Hinduism (Folk Shaktism & River Confluence)', 'The picturesque three-day forest pilgrimage held at the scenic spot where the Manjeera River splits into seven distinct streams around the shrine of Goddess Vana Durga.', 'Centuries-old folk tradition dating back to King Janamejaya of the Mahabharata who performed a sarpa yaga (serpent sacrifice) at this river confluence.', 'Celebrates Goddess Vana Durga (Durga of the Forest) as the loving protector of nature, water, and rural families.', 'To take holy baths in the seven streams of the Manjeera River on Maha Shivratri and offer prayers at the natural rock cave shrine.', 'Edupayalu literally means ''Seven Streams'' in Telugu: the sacred Manjeera River naturally branches into seven cascading rivulets before reuniting.', 'Over two million devotees camp in decorated bullock carts and tractors on the river islands and forest clearings during the three-day festival.', ARRAY['Holy cleansing dip in the pristine cascading waters of the seven streams (Edupayalu)', 'Darshan of Goddess Vana Durga inside the natural rock cave temple nestled under boulders', 'Grand congregation of decorated bullock carts with colorful canopies camping on riverbanks']::TEXT[], 'The dense forest reverberates with devotional songs, ringing temple bells, and the sound of splashing waters as families picnic on river rocks.', ARRAY['Pulihora', 'Sakkarai Pongal', 'Sweet Bobbatlu', 'Mirchi Bajji', 'Kari Dosa']::TEXT[], 'Traditional cotton dhotis, kurtas, colorful sarees, and turmeric-smeared foreheads.', 'Telugu devotional folk bhajans, energetic Dappu drumming, and traditional rural music.', 'Natural granite rock cave shrine, seven foaming river streams, and hundreds of colorful bullock cart canopies.', '3 Days', 'Hindu Lunisolar', 'Culminates on Maha Shivratri (February - March)', 'February - March', 'LUNISOLAR', 'Held during Maha Shivratri.', '2026-02-15', '2027-03-06', 'Edupayala Vana Durga Devasthanam & Medak Police', ARRAY['Telangana']::TEXT[], ARRAY['Edupayalu', 'Nagasanpalli', 'Medak']::TEXT[], ARRAY['Edupayala Vana Durga Temple Complex']::TEXT[], 'Maha Shivratri day and evening for the holy river bath and forest fairground energy', 2, 'Idyllic, refreshing forest pilgrimage: clear cascading river streams rushing around natural rock temples, filled with unhurried rural warmth.', '20 km from Medak town; 100 km northwest of Hyderabad; accessible by highway buses and private cars.', 'Hotels in Medak town; camping on riverbanks.', 'River rocks can be slippery; wade only in designated safe bathing pools; avoid deep fast-flowing channels.', 'Eco-sensitive forest river zone: do not throw plastics or waste into the river streams.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://medak.telangana.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-ramappa-heritage-festival', 'Ramappa Temple Heritage Festival', ARRAY['UNESCO Kakatiya Temple Fest']::TEXT[], 'Historical & Royal', '13th-Century Kakatiya Architecture & Classical Arts', 'A magnificent cultural festival celebrated against the 800-year-old UNESCO World Heritage Ramappa Temple, world-famous for its floating bricks and sculpted bracket figures.', 'Constructed in 1213 CE by General Recharla Rudra during the reign of Kakatiya ruler Ganapati Deva; inscribed as a UNESCO World Heritage Site in 2021.', 'Celebrates the golden age of Kakatiya architecture and honors master sculptor Ramappa (the only temple in India named after its architect).', 'To promote archaeological appreciation and stage classical dance against the exquisite carved stone bracket figures of celestial dancers (Madanikas).', 'The temple was built using revolutionary engineering: earthquake-resistant sandbox foundations and lightweight porous ''floating bricks'' that float on water.', 'Features master classical Kuchipudi, Bharatanatyam, and Perini Sivatandavam dancers performing on an illuminated stage before the temple.', ARRAY['Nightly classical dance performances staged on an open-air platform before the floodlit 13th-century temple', 'Demonstrations of Perini Sivatandavam (the ancient martial warrior dance of the Kakatiyas)', 'Guided archaeological walks explaining the floating brick technology and sandbox foundations']::TEXT[], 'Audiences sit beneath the starry night sky on temple lawns, watching classical dancers recreate the exact poses carved in black basalt stone on the temple roof.', ARRAY['Telangana Thali', 'Jonna Roti with Natu Kodi', 'Sakinalu', 'Sweet Pongal', 'Filter Coffee']::TEXT[], 'Formal Indian ethnic wear: Pochampally Ikat silk sarees, kurtas with dhotis, and light evening shawls.', 'Ancient Perini Sivatandavam martial dance with thundering drums, classical Carnatic vocal recitals, and Kuchipudi dance dramas.', 'Intricately carved black basalt bracket figures (Madanikas), star-shaped temple platform, and lightweight floating bricks.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Telangana Tourism.', '2026-01-30', '2027-01-29', 'Department of Tourism Government of Telangana & ASI', ARRAY['Telangana']::TEXT[], ARRAY['Palampet', 'Mulugu', 'Warangal']::TEXT[], ARRAY['Ramappa Temple Complex Palampet']::TEXT[], 'Evenings between 6 PM and 9:30 PM for floodlit classical concerts and morning architectural walks', 2, 'Transcendental communion with medieval Indian architectural genius: watching classical dancers perform before 800-year-old carved stone maidens glowing under golden lights.', '65 km from Warangal railway station; 210 km northeast of Hyderabad; accessible by highway taxi.', 'Haritha Lake View Resort near Ramappa Lake; hotels in Warangal city.', 'Pleasant winter evenings; flat lawn seating available.', 'Strict archaeological protection: no touching delicate basalt stone carvings; respect the active sanctum.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://telanganatourism.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-sri-rama-navami-bhadrachalam', 'Sri Rama Navami Bhadrachalam', ARRAY['Bhadrachalam Sita Rama Kalyanam']::TEXT[], 'Spiritual & Temple', 'Hinduism (Vaishnavism / Ramadasu Heritage)', 'The celestial wedding celebration of Lord Rama and Goddess Sita celebrated with royal pearl offerings (Mutyala Talambralu) on the banks of the sacred Godavari River.', 'Established in the 17th century by devotee-composer Kancharla Gopanna (Bhakta Ramadasu), who built the magnificent temple inside the dense Dandakaranya forest.', 'Celebrates the birth of Lord Rama and his divine marriage with Goddess Sita at the sacred forest hermitage where they lived during exile.', 'To behold the celestial wedding (Thirukalyanam) and receive the blessed pearls and rice grains (Mutyala Talambralu).', 'By historic tradition dating back to the Qutb Shahi Sultan of Golconda Abul Hasan Tana Shah, the state government formally presents pearls and silk robes to the deity.', 'Over 300,000 devotees assemble in the massive Mithila Stadium to witness the priests shower hundreds of kilograms of sanctified pearls on the divine idols.', ARRAY['State government presentation of pearl offerings (Mutyala Talambralu) and silk vastrams to Lord Rama', 'Performance of the grand Vedic marriage ceremony (Sita Rama Thirukalyanam) at 12:00 noon', 'Holy cleansing dip in the sacred waters of the Godavari River at Bhadrachalam Ghats']::TEXT[], 'The vast stadium erupts in cheers as pearls shower over the divine wedding couple at exact mid-day, amidst resounding chants of ''Jai Sita Ram''.', ARRAY['Bhadrachalam Laddu', 'Mutyala Talambralu (blessed pearl-infused rice grains distributed to pilgrims)', 'Pulihora', 'Chakra Pongali', 'Panakam']::TEXT[], 'Traditional white cotton dhotis with gold borders, and bright silk sarees (Kanchipuram, Gadwal).', 'Soulful devotional kirtans of Bhakta Ramadasu sung with Tambura, classical Nadaswaram, and Vedic chanting.', 'Sacred Godavari River, ancient temple gopuram, golden wedding crowns, and blessed pearl offerings.', '1 Day', 'Hindu Lunisolar', 'Chaitra Shukla Navami (March - April)', 'March - April', 'LUNISOLAR', 'Celebrated on Chaitra Shukla Navami at exact mid-day.', '2026-03-27', '2027-04-15', 'Sri Sita Ramachandra Swamy Devasthanam & Bhadradri Police', ARRAY['Telangana']::TEXT[], ARRAY['Bhadrachalam', 'Bhadradri Kothagudem']::TEXT[], ARRAY['Sri Sita Ramachandra Swamy Temple', 'Mithila Stadium']::TEXT[], 'Mid-day (10:30 AM to 1 PM) for the grand celestial wedding ceremony and pearl showering', 2, 'Deeply touching, tearful devotion: watching a 350-year-old royal wedding tradition unfold on the banks of the sacred Godavari River under a shower of glistening pearls.', 'Bhadrachalam Road railway station (Kothagudem - 40 km); 300 km east of Hyderabad via 4-lane highway.', 'Temple devaswom guest houses, cottages, and private hotels in Bhadrachalam.', 'Massive crowd density; daytime temperatures in March/April can be warm; book stadium gallery tickets online in advance.', 'Take home the blessed Mutyala Talambralu rice pearls as a sacred souvenir for marital harmony.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://bhadrachalam.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-puducherry-yoga-festival', 'Puducherry International Yoga Festival', ARRAY['Pondicherry Yoga Mahotsav']::TEXT[], 'Art & Cultural Festival', 'Spiritual Heritage / Yogic Sciences', 'A premier five-day global yoga festival bringing together master yoga teachers, researchers, and practitioners from over 30 countries to the French promenade.', 'Initiated in 1993 by the Government of Puducherry to celebrate the union of ancient Indian yogic science and international wellness.', 'Celebrates the ancient wisdom of Patanjali''s Ashtanga Yoga, physical health, and inner mental equanimity.', 'To promote authentic classical yoga, conduct international asana competitions, and share yogic philosophy with global seekers.', 'Staged near the historic French Quarter and the international spiritual township of Auroville.', 'Features competitive yogasana championships judged by medical and yogic specialists, alongside spiritual meditation workshops.', ARRAY['Morning mass yoga and pranayama sessions on the historic Goubert Avenue beach promenade', 'International yogasana championships judged across age groups from youth to seniors', 'Evening cultural concerts, classical dance recitals, and academic symposiums on yoga therapy']::TEXT[], 'Seekers from every continent practice side by side along the coastal promenade under morning ocean breezes, enjoying sattvic meals and lectures.', ARRAY['Sattvic Ayurvedic Thali', 'French Baguettes and Croissants', 'Fresh Coconut Water', 'Herbal Tea', 'Idli with Sambar']::TEXT[], 'Comfortable white yoga apparel, cotton trousers, and loose linen shirts.', 'Classical flute recitals, Vedic chanting, soothing sitar ragas, and contemporary acoustic fusion.', 'Rock-lined Goubert Avenue beach, statue of Mahatma Gandhi, yoga mats on sands, and French colonial facades.', '5 Days', 'Gregorian / Winter', 'January 4 to 7 annually.', 'January', 'FIXED', 'Held annually January 4-7.', '2026-01-04', '2027-01-04', 'Department of Tourism Government of Puducherry', ARRAY['Puducherry']::TEXT[], ARRAY['Puducherry (Pondicherry)', 'Auroville']::TEXT[], ARRAY['Goubert Avenue Beach Promenade', 'Kamban Kalai Arangam']::TEXT[], 'Dawn sessions (6:30 AM to 8:30 AM) on the sea promenade for coastal yoga practice', 2, 'Refreshing, mindful coastal rejuvenation: stretching and breathing in unison along a historic French seaside promenade as the sun rises over the Bay of Bengal.', 'Puducherry Airport connects to Bengaluru/Hyderabad; 150 km south of Chennai via scenic East Coast Road (ECR).', 'French colonial heritage boutique hotels in White Town, ashram guesthouses, and eco-resorts in Auroville.', 'Pleasant sunny winter days; comfortable shoes for walking the pedestrianized French Quarter.', 'Open to all fitness levels; bring your own yoga mat; register online in advance for competition participation.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pondytourism.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-fete-de-puducherry', 'Fete de Puducherry', ARRAY['Pondicherry Liberation & Heritage Fest']::TEXT[], 'Art & Cultural Festival', 'French-Tamil Synthesis & Freedom Heritage', 'A vibrant three-day cultural festival celebrating the historic merger of the French settlements with the Indian Union, held during Independence week.', 'Celebrates the historic De Jure transfer of power on August 16, 1962, when the French government formally transferred sovereignty to India.', 'Celebrates the unique Franco-Tamil culture, architectural charm, and peaceful freedom struggle of Puducherry.', 'To showcase the distinct synthesis of French colonial elegance and traditional Tamil heritage through arts, music, and food.', 'Centered around the scenic Goubert Avenue promenade, transforming the beachfront into a dazzling festival zone of lights, music, and fireworks.', 'Features competitions in sand art, traditional coastal boat races, and simultaneous performances of French and Tamil performing arts.', ARRAY['Ceremonial flag hoisting and parade at the French War Memorial on Goubert Avenue', 'Cultural concerts blending French Chanson music, accordion recitals, and traditional Tamil folk dances', 'Grand fireworks display illuminating the Bay of Bengal from the Old Pier at night']::TEXT[], 'Locals and international visitors stroll along the pedestrianized seaside avenue, enjoying crepes and dosas, listening to live jazz, and watching street acrobats.', ARRAY['Franco-Tamil fusion cuisine: Bouillabaisse, Ratatouille', 'Crepes', 'Masala Dosa', 'Filter Coffee', 'Fresh Pastries']::TEXT[], 'Chic resort wear, linen shirts, summer dresses, and comfortable evening walking casuals.', 'French accordion music, live jazz bands, classical Bharatanatyam, and high-energy Tamil folk drumming (Thappattam).', 'French colonial government buildings, Gandhi Statue on the promenade, French War Memorial, and colorful light arches.', '3 Days', 'Gregorian / Monsoon', 'August 15 to 17 annually (coinciding with De Jure Transfer Day).', 'August', 'FIXED', 'Held annually August 15-17.', '2026-08-15', '2027-08-15', 'Department of Tourism Government of Puducherry', ARRAY['Puducherry']::TEXT[], ARRAY['Puducherry']::TEXT[], ARRAY['Beach Promenade Goubert Avenue', 'Gandhi Thidal']::TEXT[], 'Evenings from 5:30 PM to 10 PM for seaside carnival walks, live music, and fireworks', 2, 'Idyllic Franco-Tamil seaside joie de vivre: gentle ocean breezes, accordion melodies mingling with temple drums, and cobblestone French elegance.', 'Easily accessible across Puducherry via rented bicycles, scooters, and walking.', 'Colonial heritage boutique hotels in White Town.', 'Monsoon showers possible; carry an umbrella; Beach Road is strictly pedestrianized in the evenings.', 'Rent a vintage bicycle to explore the picturesque pastel-painted villas and bougainvillea-draped lanes of the French Quarter.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pondytourism.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-french-bastille-day-puducherry', 'French Bastille Day Heritage Celebrations', ARRAY['14th of July Bastille Day Pondicherry']::TEXT[], 'Historical & Royal', 'French National Heritage & Veteran Pageantry', 'The unique historic celebration of the French National Day celebrated with military pomp, torchlight parades, and bilingual national anthems on the Bay of Bengal.', 'Celebrated since colonial times by the French-speaking citizens and French war veterans of Puducherry, commemorating the storming of the Bastille in 1789.', 'Celebrates the universal democratic ideals of the French Revolution: Liberty, Equality, Fraternity (Liberte, Egalite, Fraternite).', 'To honor French military veterans of Indian descent who served in the French Armed Forces during World Wars I and II.', 'The only place in India where Bastille Day is officially celebrated with military honors, attended by the French Consul General and Indian dignitaries.', 'Features the solemn singing of both the French National Anthem (''La Marseillaise'') and the Indian National Anthem (''Jana Gana Mana'') side by side.', ARRAY['Solemn wreath-laying ceremony at the illuminated French War Memorial on Goubert Avenue', 'Torchlight parade (Retraite aux Flambeaux) led by French-Indian veterans and police brass bands', 'Grand Bastille Day Gala Ball at the French Consulate and Alliance Francaise']::TEXT[], 'French citizens and Indian locals gather along the seaside promenade, waving French and Indian flags, watching veterans in medals, and attending evening balls.', ARRAY['Authentic French Baguettes', 'Quiche Lorraine', 'Croissants', 'French Cheeses', 'Wine and fruit punch']::TEXT[], 'Formal French dress: dark suits with medals for veterans, summer evening dresses, and stylish linen wear.', 'Brass band renditions of ''La Marseillaise'', French military marches, classic French Chansons (Edith Piaf), and jazz.', 'French War Memorial with bronze soldier sculpture, French tricolor flags (Tricolore), and flickering torchlight parade.', '2 Days', 'Gregorian / French National Day', 'July 13 and 14 annually.', 'July', 'FIXED', 'Held annually July 13-14.', '2026-07-13', '2027-07-14', 'Consulate General of France in Puducherry & Alliance Francaise', ARRAY['Puducherry']::TEXT[], ARRAY['Puducherry']::TEXT[], ARRAY['French War Memorial Goubert Avenue', 'Consulate General of France']::TEXT[], 'July 13 evening for the torchlight procession and July 14 morning for the solemn wreath-laying ceremony', 1, 'Fascinating historical time-capsule: watching decorated Indian soldiers in French military kepis saluting the French tricolor along a tropical Indian ocean promenade.', 'Easily accessible in central White Town, Puducherry, on foot or by bicycle.', 'Heritage hotels in White Town.', 'Warm, humid July weather; dress comfortably; ceremony area at War Memorial has designated spectator lines.', 'Maintain solemn silence during the playing of the national anthems and the sounding of the Last Post bugle call.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://ambafrance.org', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-villianur-car-festival', 'Villianur Temple Car Festival', ARRAY['Sri Kameeswarar Temple Rathotsavam']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Chola Temple Chariot)', 'The historic chariot festival celebrated at the 1,000-year-old Sri Kokilambal Kameeswarar Temple in Villianur, where the colossal 50-foot wooden chariot is pulled by thousands.', 'Constructed in the 12th century by Chola King Kulothunga Chola I, who was miraculously cured of leprosy after bathing in the temple tank.', 'Celebrates Lord Kameeswarar (Shiva) and Goddess Kokilambal blessing devotees and cleansing past afflictions.', 'To pull the sacred ropes of the colossal wooden temple chariot, an act believed to bestow health and spiritual liberation.', 'By historic colonial tradition dating back over 200 years, the Lieutenant Governor of Puducherry (or state representative) ceremonially pulls the first rope of the chariot.', 'The towering 50-foot wooden chariot, adorned with intricate wood carvings and draped in red and white cloth, rolls through ancient town streets.', ARRAY['Ceremonial flagging off of the chariot pulling by the Lieutenant Governor of Puducherry', 'Pulling of the massive 50-foot wooden chariot by thousands of devotees down the four temple car streets', 'Holy cleansing dip in the sacred 1,000-year-old temple tank (Theertham)']::TEXT[], 'Tens of thousands of devotees pack the streets, cheering ''Om Namah Shivaya'' as the colossal chariot rumbles past amidst showers of flowers and coconuts.', ARRAY['Pulihora', 'Sakkarai Pongal', 'Sundal', 'Panakam', 'Vada']::TEXT[], 'Traditional Tamil attire: white cotton Veshtis with gold borders, and bright silk sarees.', 'Thunderous beats of traditional Thavil drums, resonant Nadaswaram wedding ragas, and conch shell blasts.', 'Colossal 50-foot hand-carved wooden temple chariot, ancient Chola gopuram, and sacred stone temple tank.', '1 Day (Brahmotsavam for 10 Days)', 'Tamil Solar Calendar', 'Month of Vaikasi (May - June) on Pournami (Full Moon).', 'May - June', 'LUNISOLAR', 'Culminates on Vaikasi Pournami.', '2026-05-31', '2027-05-20', 'Sri Kameeswarar Devasthanam & Puducherry Government', ARRAY['Puducherry']::TEXT[], ARRAY['Villianur', 'Puducherry']::TEXT[], ARRAY['Sri Kokilambal Kameeswarar Temple Complex Villianur']::TEXT[], 'Morning between 7 AM and 11 AM when the massive wooden chariot is pulled through town streets', 1, 'Authentic, vibrant Dravidian temple chariot energy: immense community strength pulling a 50-foot wooden monument through historic streets, filled with deep faith.', '10 km west of central Puducherry; easily reached by local bus, taxi, or auto-rickshaw.', 'Hotels throughout Puducherry city.', 'Summer morning heat; carry drinking water and sun hats; stay clear of the heavy wooden chariot wheels.', 'Remove footwear before stepping onto the temple car streets; participate respectfully in pulling the sacred ropes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://pondytourism.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-mangani-festival-karaikal', 'Mangani Festival Karaikal', ARRAY['Karaikkal Ammaiyar Mango Festival']::TEXT[], 'Spiritual & Temple', 'Hinduism (Shaivism / Sweet Mango Miracle)', 'The unique sweet festival celebrating the 6th-century female saint Karaikkal Ammaiyar, where thousands of sweet mangoes are joyfully thrown into cheering crowds from rooftops.', 'Centuries-old festival commemorating Karaikkal Ammaiyar (one of the three female Nayanmar saints of Tamil Shaivism) and the miracle of the sweet divine mangoes.', 'According to legend, Lord Shiva miraculously sent sweet mangoes to his devotee Punithavathi (Karaikkal Ammaiyar) to demonstrate her pure spiritual sanctity to her husband.', 'To honor the saint''s supreme devotion, celebrate feminine spiritual liberation, and catch blessed mangoes believed to grant children and health.', 'Completely unique: during the street procession of Lord Shiva (Bikshatana), devotees standing on rooftops and balconies toss thousands of fresh sweet mangoes into the crowds.', 'Devotees leap and reach into the air with outstretched hands to catch the flying blessed fruit without letting it touch the ground.', ARRAY['Procession of Lord Shiva (Bikshatana) riding a decorated silver palanquin through Karaikal streets', 'Thousands of devotees throwing fresh sweet ripe mangoes from rooftops and balconies into the crowd below', 'Grand feast of curd rice and sweet mangoes served to thousands at the Karaikkal Ammaiyar Temple']::TEXT[], 'Streets are filled with laughter and excitement as sweet ripe mangoes rain from the sky, while thousands of people leap with open arms to catch the blessed fruit.', ARRAY['Curd Rice served with sweet fresh mangoes (traditional temple Mahaprasad)', 'Mangani sweet', 'Pulihora', 'Sakkarai Pongal', 'Filter Coffee']::TEXT[], 'Traditional cotton dhotis, colorful sarees, and casual clothes that can handle sweet mango splashes.', 'Resounding Nadaswaram temple music, Thavil drums, and devotional singing of the saint''s Tevaram hymns.', 'Showers of yellow ripe mangoes falling from rooftops, silver palanquin of Lord Shiva, and Karaikkal Ammaiyar shrine.', '4 Days', 'Tamil Solar Calendar', 'Month of Aani (June - July) on the full moon day.', 'June - July', 'LUNISOLAR', 'Culminates on Aani Pournami.', '2026-06-29', '2027-06-18', 'Karaikkal Ammaiyar Temple Trust & Karaikal Administration', ARRAY['Puducherry']::TEXT[], ARRAY['Karaikal']::TEXT[], ARRAY['Karaikkal Ammaiyar Temple', 'Bharathiar Street Karaikal']::TEXT[], 'Aani Pournami day between 9 AM and 1 PM during the mango-throwing street procession', 1, 'Joyful, unforgettable community festival: sweet ripe mangoes raining from the heavens, collective laughter, and catching divine blessings straight out of the sky.', 'Karaikal has its own railway station; 135 km south of Puducherry; accessible by highway buses and private cars.', 'Hotels and guest houses in Karaikal town.', 'Watch your head and eyes: thousands of fresh mangoes are tossed from rooftops; wear a cap and be alert.', 'Catching a mango is considered supreme blessing; share your caught fruit joyfully with fellow pilgrims.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://karaikal.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-eid-ul-fitr-lakshadweep', 'Eid-ul-Fitr Kavaratti', ARRAY['Cheriyaperunnal Lakshadweep']::TEXT[], 'Spiritual & Temple', 'Islam (Shafi''i Sunni Island Heritage)', 'The joyous festival marking the end of the holy month of Ramadan celebrated across the 10 inhabited coral islands of Lakshadweep with community prayers and feasts.', 'Celebrated since the 7th century CE when Islam was introduced to Lakshadweep by Saint Ubaidullah at Amini and Kavaratti.', 'Celebrates gratitude to Allah for completing the month of fasting, purification, charity, and self-discipline.', 'To offer congregational prayers at ancient coral-stone mosques, distribute Zakat al-Fitr to the needy, and enjoy family feasts.', 'The entire island population dresses in new clothes, walking along white coral sand paths to attend dawn prayers at historic 17th-century mosques.', 'Centered around the historic Ujra Mosque in Kavaratti, renowned for its intricately carved deodar wood ceilings and miraculous freshwater well.', ARRAY['Morning congregational Eid prayers on open-air coral beach grounds and historic mosques', 'Visiting every home on the island to exchange greetings (''Eid Mubarak'') and taste festive dishes', 'Traditional community folk games, boat regattas, and cultural performances by youth']::TEXT[], 'Island pathways bordered by turquoise lagoons and coconut palms buzz with children in colorful clothes, sharing sweet treats from house to house.', ARRAY['Kavaratti Tuna Biryani (fragrant rice cooked with fresh yellowfin tuna)', 'Ray Mus (spicy smoked tuna preparation)', 'Kinnathappam (steamed sweet coconut cake)', 'Sura (spiced shark curry)', 'Dates and Payasam']::TEXT[], 'Crisp new white Kurta-Pajamas or lungis with embroidered prayer caps for men; colorful embroidered silk dresses and hijabs for women.', 'Soulful Islamic Baith (hymns) sung in Malayalam and Arabic, Dafmuttu percussion, and gentle festive island folk songs.', 'Carved coral stone of Ujra Mosque, turquoise lagoon water reflections, swaying coconut palms, and white coral sand paths.', '1 to 2 Days', 'Islamic Lunar (Hijri)', 'First day of the Islamic month of Shawwal (following Ramadan).', 'March - April', 'LUNAR', 'Dates determined by moon sighting marking the end of Ramadan.', '2026-03-20', '2027-03-10', 'Lakshadweep Wakf Board & District Administration', ARRAY['Lakshadweep']::TEXT[], ARRAY['Kavaratti', 'Agatti', 'Amini', 'Minicoy', 'Kalpeni']::TEXT[], ARRAY['Ujra Mosque Kavaratti', 'Island Eidgah grounds']::TEXT[], 'Dawn for the congregational prayers at 7 AM and daytime house-to-house community visiting', 2, 'Idyllic, heartwarming island paradise warmth: stepping across powdery white coral sands between turquoise lagoons, welcomed into every home with fresh seafood and sweet hospitality.', 'Air India flights operate from Kochi to Agatti Airport; inter-island passenger ferries or helicopter services connect to Kavaratti.', 'Government tourist huts, eco-resorts, and authorized homestays on designated islands (permit required for all travelers).', 'Mandatory entry permit required for all tourists to visit Lakshadweep (arranged via travel agents or Lakshadweep administration portal).', 'Respect the cultural modesty and Islamic traditions of the islanders; strictly zero alcohol throughout Lakshadweep.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://lakshadweep.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-milad-un-nabi-lakshadweep', 'Milad-un-Nabi Lakshadweep', ARRAY['Mawlid an-Nabi Island Celebrations']::TEXT[], 'Spiritual & Temple', 'Islam (Prophet''s Birthday & Sufi Hymns)', 'The sacred celebration of the birth anniversary of Prophet Muhammad celebrated across the coral atolls with rhythmic Dafmuttu drumming and sweet communal feasts.', 'Centuries-old Islamic tradition observed across the Arabian Sea atolls, honoring the birth and universal moral teachings of the Prophet.', 'Celebrates peace, divine mercy, moral righteousness, and love for Prophet Muhammad.', 'To recite the sacred Mawlid poetry (eulogies praising the Prophet) and distribute blessed food to the entire island community.', 'Features the captivating performance of ''Dafmuttu''—a traditional percussion dance where men in white attire strike tambourines (Daf) in synchronized rhythm.', 'Every neighborhood mosque prepares and distributes ''Nercha'' (blessed feast meals of spiced rice and fresh tuna) to all households.', ARRAY['Recitation of the sacred Mawlid and Qasida Burda hymns in ancient coral-stone mosques', 'Synchronized Dafmuttu dance performance by youth in white dhotis with green sashes', 'Preparation of massive community Nercha meals cooked in brass cauldrons on the beach']::TEXT[], 'Island mosques glow with fairy lights beneath star-studded equatorial skies, filled with the rhythmic thud of Daf tambourines and melodic Arabic chants.', ARRAY['Island Nercha Rice (fragrant spiced rice cooked with coconut and fresh tuna)', 'Kinnathappam', 'Fish Cutlets', 'Sweet Halwa', 'Spiced Milk Tea']::TEXT[], 'Pristine white cotton Jubbas, lungis with green sashes, prayer caps, and modest hijabs.', 'Rhythmic, synchronized Dafmuttu percussion, melodic Arabic Mawlid chanting, and traditional devotional songs.', 'Coral-stone mosque arches, brass Daf tambourines with jingling bells, coconut palm fronds, and tranquil lagoons.', '1 Day', 'Islamic Lunar (Hijri)', '12th day of Rabi al-Awwal in the Islamic calendar.', 'August - September', 'LUNAR', 'Celebrated on 12th Rabi al-Awwal.', '2026-08-25', '2027-08-14', 'Lakshadweep Sunni Wakf Council & Island Panchayats', ARRAY['Lakshadweep']::TEXT[], ARRAY['Kavaratti', 'Andrott', 'Minicoy', 'Agatti']::TEXT[], ARRAY['Juma Mosque Kavaratti', 'Tomb of Saint Ubaidullah Andrott']::TEXT[], 'Morning Mawlid recitations (8 AM to 11 AM) and evening Dafmuttu performances', 1, 'Peaceful, deeply musical island spirituality: listening to rhythmic tambourines and devotional poetry echo across tranquil coral lagoons under swaying palms.', 'Accessible via passenger ships from Kochi or flight to Agatti followed by boat transfer (permit required).', 'Authorized tourist guesthouses and homestays on permit-approved islands.', 'Obtain mandatory Lakshadweep entry permit weeks in advance through authorized portals.', 'Dress modestly covering arms and legs; remove footwear before entering coral-stone mosque precincts.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://lakshadweep.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('fest-lakshadweep-sea-festival', 'Lakshadweep National Sea Festival', ARRAY['Coral Island Watersports Carnival']::TEXT[], 'Seasonal & Nature', 'Secular / Marine Eco-Tourism & Water Sports', 'A spectacular marine adventure and cultural festival celebrating the pristine coral reefs, turquoise lagoons, and traditional seafaring sports of Lakshadweep.', 'Initiated by the Department of Tourism and Sports, Lakshadweep, to promote responsible marine eco-tourism and celebrate island seafaring heritage.', 'Celebrates the fragile coral reef biodiversity, turquoise marine lagoons, and traditional boat racing sports of the islands.', 'To position Lakshadweep as a premier global scuba diving and water-sports destination while promoting coral reef conservation.', 'Staged across the crystalline lagoons of Kavaratti, Bangaram, and Kadmat, renowned for visibility exceeding 30 meters.', 'Features thrilling traditional canoe regattas, windsurfing, scuba diving explorations along vertical coral drop-offs, and deep-sea kayaking.', ARRAY['Scuba diving and snorkeling expeditions through pristine coral gardens teeming with sea turtles and manta rays', 'Traditional wooden outrigger canoe and country boat racing competitions across the lagoon', 'Evening cultural performances on the beach featuring traditional Minicoy island dances (Lava dance)']::TEXT[], 'Visitors sail over transparent turquoise lagoons that look like liquid emerald, diving with marine turtles and watching energetic tribal dancers by campfire.', ARRAY['Grilled Coral Fish and Yellowfin Tuna', 'Coconut rice', 'Ray Mus', 'Kinnathappam', 'Fresh coconut water']::TEXT[], 'Beach casuals, swimwear, rash guards, sunglasses, sun hats, and sandals.', 'Traditional Minicoy ''Lava'' dance with colorful striped costumes and drums, alongside modern acoustic island music.', 'Vibrant underwater coral reefs, sea turtles, traditional wooden outrigger boats, and blinding white sandbars.', '3 Days', 'Gregorian / Winter', 'Held in January / February annually.', 'January - February', 'ORGANIZER_ANNOUNCED', 'Announced annually by Lakshadweep Tourism (SPORTS).', '2026-02-10', '2027-02-09', 'Society for Promotion of Nature Tourism and Sports (SPORTS)', ARRAY['Lakshadweep']::TEXT[], ARRAY['Kavaratti', 'Bangaram', 'Kadmat']::TEXT[], ARRAY['Bangaram Island Lagoon', 'Kavaratti Marine Watersports Centre']::TEXT[], 'Daytime from 8 AM to 4 PM for scuba diving, boat races, and lagoon water sports', 3, 'Unbelievable, pristine tropical ocean paradise: floating over crystalline turquoise waters with 100-foot underwater visibility, surrounded by vibrant coral gardens and sea turtles.', 'Flight to Agatti Airport from Kochi; high-speed speedboats connect directly to Bangaram and Kavaratti.', 'Beachfront cottages and luxury eco-tents at Bangaram Island Resort and Kadmat Island Beach Resort.', 'Mandatory entry permit and confirmed resort booking required before boarding flight from Kochi.', 'Strict coral reef conservation: never touch, stand on, or break live corals; collecting shells or coral pieces is strictly prohibited under marine wildlife laws.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://lakshadweep.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('bohag-bihu-assam', 'Bohag Bihu', ARRAY['Rongali Bihu', 'Xaat Bihu', 'Assamese New Year']::TEXT[], 'HARVEST_SEASONAL', 'Assamese Folk Tradition / Hinduism', 'The grandest 7-day spring festival marking the Assamese New Year, sowing season, love, and vibrant Bihu dance.', 'Celebrated since antiquity across the Brahmaputra valley, uniting indigenous Tibeto-Burman traditions with Sanskritic seasonal rites.', 'Associated with the spring equinox and pastoral fertility; seven distinct phases celebrated across sacred cattle groves and courtyards.', 'Welcomes the vernal new year, honors agricultural renewal, respects elders with handwoven Gamochas, and kindles youthful romance.', 'Represents the quintessential soul of Asomiya culture, expressing communal harmony, agrarian fertility, and creative joy.', 'Historically patronized by Ahom monarchs in the Rang Ghar pavilion of Sivasagar, transforming pastoral dance into a courtly art.', ARRAY['Goru Bihu (ritual bathing and worship of cows)', 'Manuh Bihu (honoring elders with Phulam Gamocha)', 'Husori performances door-to-door', 'Bihu dance under sacred banyan trees']::TEXT[], 'People don Muga silk, assemble in community open grounds (Bakori), exchange pitha sweets, and dance to dhol drum rhythms.', ARRAY['Pitha (Til Pitha, Ghila Pitha)', 'Laru (Narikol and Laskar)', 'Khar', 'Xaak (101 wild spring greens)', 'Duck curry with ash gourd']::TEXT[], 'Women wear golden Muga silk Mekhela Chador with Kopou orchid flowers in hair; men wear Dhoti, Kurta, and Seleng Sador with Gamocha tied on forehead.', 'Bihu geet songs accompanied by Dhol (barrel drum), Pepa (buffalo horn flute), Toka (bamboo clapper), Gagana (jaw harp), and Xutuli (clay whistle).', ARRAY['Phulam Gamocha', 'Kopou phool (foxtail orchid)', 'Japi conical hat', 'Xorai brass tray']::TEXT[], '7 Days (traditionally observed for an entire month)', 'Assamese Solar Calendar (Bohag 1)', 'Begins on the first day of Bohag month, coinciding with the Mesha Sankranti in mid-April.', 'April', 'SOLAR', 'First day of Assamese month Bohag (April 14/15 annually)', '2026-04-14 to 2026-04-20', '2027-04-14 to 2027-04-20', 'Government of Assam Official Holiday Calendar & Directorate of Cultural Affairs', ARRAY['Assam']::TEXT[], ARRAY['Guwahati', 'Sivasagar', 'Tezpur', 'Jorhat', 'Dibrugarh']::TEXT[], ARRAY['Latasil Field Guwahati', 'Rang Ghar Pavilion Sivasagar', 'Judges Field Guwahati', 'Chowkidingee Field Dibrugarh']::TEXT[], 'Evenings between 5 PM and 10 PM at open-air cultural fields and community Husori rounds.', 4, 'Unmatched electric energy as thousands of young dancers move to thunderous dhol beats. Travelers are warmly welcomed into homes for freshly brewed tea and pitha.', 'ASTC buses, app cabs in Guwahati; rental cars for Sivasagar heritage pavilion.', 'Extensive hotel range in Guwahati (Paltan Bazar, GS Road) and heritage tea bungalows in Jorhat.', 'Extremely high public participation; safe, festive family atmosphere everywhere.', 'Accept Gamocha gifts with both hands; remove footwear when entering Assamese prayer rooms (Namghar).', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('kati-bihu-assam', 'Kati Bihu', ARRAY['Kongali Bihu', 'Poor Bihu']::TEXT[], 'HARVEST_SEASONAL', 'Assamese Folk Tradition', 'A solemn, contemplative festival marking the critical paddy growth phase, observed with earthen oil lamps in fields.', 'Rooted in Assamese agrarian lore where the granaries were empty (Kongali) before the winter harvest, requiring prayers for protection.', 'Originates from ancient insect-protection practices and prayers to Goddess Lakshmi and the sacred Tulsi plant.', 'To pray for a bounteous paddy harvest, ward off crop pests, and seek divine blessings during lean autumn months.', 'A reflective observance emphasizing spiritual quietude, environmental reverence, and hope for agrarian sustenance.', 'Demonstrates ancient eco-friendly pest management through light traps and community solidarity during subsistence periods.', ARRAY['Lighting earthen lamps (Akaxboti) on bamboo poles in paddy fields', 'Worship of Tulsi plant with mustard oil lamps', 'Recitation of sacred hymns (Nam-Prasanga) in Namghars']::TEXT[], 'Families gather silently at twilight in lush green paddy fields and domestic courtyards to light Diya lamps.', ARRAY['Black tea with roasted rice (Jolpan)', 'Tita phool (bitter flower) preparations', 'Simple home-cooked seasonal lentils']::TEXT[], 'Simple traditional handloom cotton Mekhela Chador and Dhoti-Kurta.', 'Quiet devotional chanting (Naam) without festive drumming or dancing.', ARRAY['Akaxboti (sky lantern on tall bamboo pole)', 'Tulsi altar', 'Earthen saki lamps in emerald paddy fields']::TEXT[], '1 Day', 'Assamese Solar Calendar (Kati 1)', 'Falls on the first day of Kati month (mid-October) coinciding with Tula Sankranti.', 'October', 'SOLAR', 'First day of Assamese month Kati (October 17/18 annually)', '2026-10-18', '2026-10-18', 'Assam Directorate of Tourism', ARRAY['Assam']::TEXT[], ARRAY['Guwahati', 'Majuli', 'Nagaon', 'Golaghat']::TEXT[], ARRAY['Rural paddy fields across Brahmaputra valley', 'Sattras of Majuli', 'Community Namghars']::TEXT[], 'Dusk (5 PM to 7 PM) when thousands of tiny flickering flames illuminate wide paddy fields.', 1, 'Poetic, deeply peaceful visual spectacle of golden lamps glowing across miles of dark, whispering green rice terraces.', 'Local ferries to Majuli, country autos and cabs in rural Assam.', 'Eco-cottages in Majuli island or riverfront stays in Jorhat and Guwahati.', 'Gentle, intimate rural community gatherings; very tranquil.', 'Walk carefully along narrow field embankments (ali); respect silent prayer moments at Tulsi shrines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('magh-bihu-assam', 'Magh Bihu', ARRAY['Bhogali Bihu', 'Bihu of Feasts']::TEXT[], 'HARVEST_SEASONAL', 'Assamese Folk Tradition', 'Assam''s exuberant winter harvest carnival characterized by overnight bonfires, Meji burnings, and grand community feasts.', 'Celebrated following the winter rice harvest when granaries overflow, enabling abundant culinary hospitality.', 'Ancient harvest thanksgiving to the fire god Agni and mother earth for providing food grains to sustain winter survival.', 'To celebrate the conclusion of the harvest season, feast in community solidarity, and consign evil to ritual Meji flames.', 'Abundance, gastronomic celebration, warmth amidst winter chill, and thanksgiving to nature.', 'Community building institution where youth build ingenious thatch huts (Bhelaghar) showcasing traditional architecture before ritual burning.', ARRAY['Uruka (community feast on the eve)', 'Constructing architectural Bhelaghar and tall Meji of bamboo and thatch', 'Burning the Meji at dawn and offering sesame and coconuts to Agni', 'Traditional egg fights (Koni juj) and buffalo fights']::TEXT[], 'Villagers spend the cold night inside Bhelaghar singing, feasting on fresh fish, and torch the Meji at sunrise before breakfast.', ARRAY['Chira-Doi-Gur (flattened rice with curd and jaggery)', 'Tekeli Pitha', 'Sunga Pitha (rice cake baked in green bamboo tubes)', 'Roasted pork/fish', 'Mahor Daal']::TEXT[], 'Warm handloom shawls, Eri silk jackets, Muga Chador, and traditional Dhotis.', 'Bihu beats, dhol rhythms, folk songs around the campfire, and lively morning ululation (Uruli).', ARRAY['Meji bamboo pyre', 'Bhelaghar temporary straw architecture', 'Green bamboo tubes (Sunga)', 'Chira-curd bowl']::TEXT[], '2 Days', 'Assamese Solar Calendar (Magh 1)', 'Begins with Uruka on the last day of Poush, transitioning into Magh on Makar Sankranti (Jan 14/15).', 'January', 'SOLAR', 'Makar Sankranti alignment in Magh month', '2026-01-14 to 2026-01-15', '2027-01-14 to 2027-01-15', 'Assam Tourism Development Corporation', ARRAY['Assam']::TEXT[], ARRAY['Guwahati', 'Barpeta', 'Nagaon', 'Morigaon', 'Jorhat']::TEXT[], ARRAY['Open fields across Assam', 'Ahatguri (traditional buffalo fights)', 'Barpeta Satra grounds']::TEXT[], 'Early morning dawn (5:30 AM to 7:30 AM) on Magh 1 when the towering Meji fires ignite.', 2, 'Mesmerizing sight of towering bamboo structures erupting into blazing infernos under the winter morning mist, followed by piping hot pitha.', 'Early morning vehicle hire essential to reach rural harvest grounds.', 'Tea estate heritage stays or city hotels in Guwahati and Tezpur.', 'Energetic village gatherings; respectful, warm, and highly hospitable.', 'Dress in layers against morning chill; accept blessed sesame seeds and ash (Meji phoot) respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ambubachi-mela-assam', 'Ambubachi Mela', ARRAY['Ameti', 'Kamakhya Fertility Festival', 'Mahakumbh of the East']::TEXT[], 'RELIGIOUS_TEMPLE', 'Shaktism / Tantric Hinduism', 'Eastern India''s most significant Tantric gathering commemorating the annual menstruation of Goddess Kamakhya atop Nilachal Hill.', 'Practiced for centuries at Kamakhya Temple, one of the 51 Shakti Peethas where the Yoni (generative organ) of Sati fell.', 'Rooted in the cosmic cycle of fertility where Mother Earth rests during the onset of the monsoon rains to prepare for rejuvenation.', 'To celebrate divine feminine power (Shakti), natural fertility cycles, and spiritual renewal.', 'De-stigmatization of menstruation as a divine, fertile natural cycle; gathering of esoteric Tantric sadhus and householders.', 'A sacred pilgrimage unifying mystics, Aghoris, and millions of devotees from across India, Nepal, and Bengal.', ARRAY['Temple doors closed for 3 days of seclusion', 'Continuous Vedic and Tantric chanting on Nilachal Hill', 'Temple opening on the 4th day with grand ablution', 'Distribution of sacred red cloth (Raktavastra or Angavastra)']::TEXT[], 'Nilachal Hill transforms into a vibrant spiritual sea with hundreds of thousands of sadhus, Baul singers, and devotees camping in serenity.', ARRAY['Pure vegetarian sattvic mahaprasad', 'Khichuri', 'Seasonal mangoes', 'Labra mixed vegetable']::TEXT[], 'Pilgrims and sadhus wear red, ochre, and saffron robes adorned with rudraksha garlands.', 'Haunting Baul songs with ektara, Shiva chants, blowing of conch shells, and rhythmic ringing of temple brass bells.', ARRAY['Sacred red Raktavastra cloth', 'Sindoor marks', 'Kamakhya Yoni stone', 'Nilachal mountain contour']::TEXT[], '4 to 5 Days', 'Assamese Luni-Solar Calendar (Aashar month)', 'Commences on the seventh day of the Hindu month of Aashar when the sun transits into Gemini (Mithuna).', 'June', 'LUNISOLAR', 'Sun transit into Mithuna during Aashar month (June 21-26 window)', '2026-06-22 to 2026-06-26', '2027-06-22 to 2027-06-26', 'Kamakhya Devalaya Management Board & Kamrup District Administration', ARRAY['Assam']::TEXT[], ARRAY['Guwahati']::TEXT[], ARRAY['Kamakhya Temple Complex atop Nilachal Hill']::TEXT[], 'Morning of the 4th day when the temple gates reopen for Darshan.', 3, 'An intense, unforgettable spiritual spectacle of Tantric ascetics, sacred smoke, devotional fervour, and breathtaking Brahmaputra panoramas.', 'District administration shuttle buses from Kamakhya station and Guwahati city up Nilachal hill.', 'Advance booking mandatory; hotels across Guwahati fill to full capacity.', 'Exceedingly dense crowds (over 1 million attendees); strict security cordons.', 'Expect extensive walking queues; dress modestly in traditional attire; photography inside inner sanctum strictly prohibited.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('majuli-festival-assam', 'Majuli Festival', ARRAY['Majuli Cultural and Tourism Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Neo-Vaishnavite Satra Culture & Indigenous Tribes', 'A breathtaking river island festival showcasing Neo-Vaishnavite Sattriya culture, mask making, and Mishing tribal heritage.', 'Founded to celebrate the unique heritage of the world''s largest river island, pioneered by 15th-century saint Srimanta Sankardeva.', 'Conceived by local cultural preservationists and Assam Tourism to highlight fragile eco-cultural traditions.', 'To preserve and showcase Majuli''s unique Sattriya monasteries, traditional boat making, bamboo craftsmanship, and tribal coexistence.', 'Harmonious coexistence of Vaishnavite monastic devotional art and vibrant riverine tribal cultures.', 'Brings centuries-old monastic dance traditions (recognized as Indian Classical Dance) to public open-air celebration.', ARRAY['Ankiya Bhaona (traditional one-act mythological theatre)', 'Borgeet singing', 'Sattriya classical dance recitals', 'Mishing Ali-Ai-Ligang folk dance']::TEXT[], 'Riverfront open-air stages host continuous performances; artisans demonstrate traditional clay and bamboo mask-making.', ARRAY['Purang Apin (rice wrapped in special leaves)', 'Smoked river fish', 'Namsing (fermented fish chutney)', 'Apin boiled sweet potatoes']::TEXT[], 'Tribal women in colorful Mishing Gero and Ege; Vaishnavite monks in pure white cotton Dhotis and Chadors.', 'Khol (terracotta two-faced drum), Taal (large brass cymbals), flute, and soulful Borgeet vocal compositions.', ARRAY['Mukha (traditional theatrical masks from Samaguri Satra)', 'Khol drum', 'Brahmaputra wooden ferry', 'Monastic prayer flag']::TEXT[], '4 Days', 'Gregorian (Tourism Calendar)', 'Held annually in the pleasant post-monsoon winter month of November.', 'November', 'ORGANIZER_ANNOUNCED', 'Third or fourth weekend of November announced by Majuli District Administration', '2026-11-20 to 2026-11-23', '2027-11-19 to 2027-11-22', 'Majuli District Administration & Assam Tourism', ARRAY['Assam']::TEXT[], ARRAY['Majuli Island', 'Jorhat']::TEXT[], ARRAY['Garumur Festival Grounds', 'Samaguri Satra', 'Kamalabari Satra', 'Dakhinpat Satra']::TEXT[], 'Afternoons for artisan workshops at Samaguri Satra, evenings for theatrical Bhaona dramas under stage lights.', 3, 'Atmospheric island journey by ferry across the mighty Brahmaputra, arriving in an enchanted world of serene monasteries and mask artisans.', 'Ferry from Nimati Ghat (Jorhat) to Kamalabari/Aphalamukh Ghat; island e-rickshaws and rented bicycles.', 'Charming stilt bamboo eco-lodges run by Mishing hosts or guest cottages inside Satras.', 'Moderate cultural audience, gentle and contemplative atmosphere.', 'Remove shoes when entering Satra sanctums; monks are greeted with folded hands (Pranam).', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('jonbeel-mela-assam', 'Jonbeel Mela', ARRAY['Barter System Fair of Assam']::TEXT[], 'FOLK_COMMUNITY', 'Tiwa Tribal & Plain Communities Inter-exchange', 'A historic 500-year-old three-day tribal fair where goods are traded strictly through an ancient barter system without money.', 'Initiated in the 15th century by the Gobha Kingdom to foster peaceful trade and brotherhood between hills and plains tribes.', 'Centered beside the crescent-shaped Jonbeel lake (Jon = Moon, Beel = Wetland) in Morigaon district.', 'To sustain ancestral fraternal ties between hill tribes (Karbis, Khasis, Tiwas) and plains communities through reciprocal gift-giving.', 'Demonstrates a non-commercialized, cooperative human economy founded on mutual respect, trust, and shared earth bounty.', 'One of the very few surviving ancient barter economies active in the modern world, inaugurated by the traditional Gobha King.', ARRAY['Royal community fishing in Jonbeel lake', 'Ceremonial court of the Gobha Raja receiving token taxes', 'Barter exchange ritual (Vinimoy) at crack of dawn', 'Sacred fire prayer for peace and harvest']::TEXT[], 'Hill tribes arrive with ginger, turmeric, and herbs; plains folk bring rice, pitha, and dried fish to barter at sunrise.', ARRAY['Bamboo shoot smoked pork', 'Til Pitha', 'Roasted fresh catch from Jonbeel lake', 'Panta bhat with mustard oil']::TEXT[], 'Tiwa handwoven Tagla jackets, Karbi Phoroi turbans, and Assamese handloom cottons.', 'Tribal flute melodies, Tiwa folk drums, and spontaneous communal dance around embers.', ARRAY['Crescent Jonbeel lake', 'Balance scale devoid of money', 'Ginger root and dried fish barter token', 'Crown of Gobha Raja']::TEXT[], '3 Days', 'Assamese Calendar (Magh month weekend)', 'Takes place on the first weekend following Magh Bihu in mid-January.', 'January', 'COMMUNITY_SPECIFIC', 'First Thursday through Saturday after Magh Bihu', '2026-01-22 to 2026-01-24', '2027-01-21 to 2027-01-23', 'Tiwa Autonomous Council & Morigaon District Administration', ARRAY['Assam']::TEXT[], ARRAY['Jagiroad', 'Morigaon', 'Guwahati']::TEXT[], ARRAY['Jonbeel Lake Field, Dayang Belguri, Jagiroad']::TEXT[], 'Friday sunrise (5:00 AM to 8:00 AM) when the historic barter exchange takes place with hill tribes.', 2, 'Uniquely moving human experience: witness people trading a basket of mountain ginger for a basket of handmade pitha cakes with joyful smiles.', '60 km drive east from Guwahati via NH27; auto-rickshaws available from Jagiroad railway station.', 'Guwahati hotels or local guest houses in Morigaon.', 'Vibrant, friendly rural fair; busy early in the morning.', 'Do not offer cash to hill traders during barter hours; bring biscuits, tea leaves, or clothing if you wish to barter.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ali-ai-ligang-assam', 'Ali-Ai-Ligang', ARRAY['Mishing Spring Seed Sowing Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mishing Tribal Tradition (Donyi-Polo)', 'A picturesque spring festival of the Mishing community celebrating the sowing of Ahu paddy with Gumrag dance.', 'Practiced since ancestral migrations into the riverine tracts of the Brahmaputra, honoring father sky and mother earth.', 'Ali means root/seed, Ai means fruit, and Ligang means sowing; commemorates the initiation of the agrarian season.', 'To invoke blessings of mother earth (Karsing Kartak) and ancestors for abundant crops and protection from floods.', 'Joyful expression of indigenous riverine tribal identity, collective agricultural labor, and spring renewal.', 'Preserves original Mishing musical traditions, community feasting ethics, and deep ecological harmony with rivers.', ARRAY['Ligangeba (ceremonial ceremonial sowing of paddy seeds in corners of fields)', 'Purang Apin ritual packing', 'Ancestral libation ceremonies', 'Gumrag So:man circle dancing']::TEXT[], 'Villagers clean courtyards, don vibrant colorful handwovens, and perform the swaying Gumrag dance moving house to house.', ARRAY['Purang Apin (steamed sticky rice in Tupula leaves)', 'Namsing (fermented fish paste)', 'Pork with bamboo shoot', 'Apong (traditional rice beer)']::TEXT[], 'Women in exquisite striped red-yellow-black Ege, Gero, and Gaseng; men in Gonro Ugon dhoti, Mibu Galuk sleeveless jacket, and Pagroo turbans.', 'Gumrag dance music powered by Oenitom songs, the energetic Dumdum drum, Marbang brass gong, and Denki flutes.', ARRAY['Tupula leaf parcel', 'Sprouting paddy shoot', 'Dumdum drum', 'Mibu Galuk embroidered vest']::TEXT[], '5 Days (main festivities on first Wednesday)', 'Assamese Luni-Solar Calendar (Phagun month)', 'Always commences on the first Wednesday (Lakhimi Baar) of the month of Phagun (mid-February).', 'February', 'COMMUNITY_SPECIFIC', 'First Wednesday of Assamese month Phagun', '2026-02-18 to 2026-02-22', '2027-02-17 to 2027-02-21', 'Mising Autonomous Council (MAC) & Assam Directorate of Tourism', ARRAY['Assam']::TEXT[], ARRAY['Dhemaji', 'Lakhimpur', 'Majuli', 'Jorhat']::TEXT[], ARRAY['Mishing village stilt-house settlements across Majuli and Dhemaji']::TEXT[], 'Wednesday afternoon and evening when youth perform Gumrag dance in every stilt-house courtyard.', 2, 'Authentic warmth of tribal hospitality: invited into traditional Chang Ghar stilt homes for fresh fragrant rice and uplifting music.', 'Accessible via ferry to Majuli or by road to North Lakhimpur and Dhemaji.', 'Stilt eco-lodges along river Luit in Majuli.', 'Community-focused, exuberant, warm, and highly hospitable.', 'Always take off your footwear before climbing the notched log ladder into a Chang Ghar.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('dehing-patkai-festival-assam', 'Dehing Patkai Festival', ARRAY['Rainforest and Heritage Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Assam Cultural Integration & Eco-Tourism', 'A premier eco-cultural carnival celebrating Assam''s only lowland rainforest, tea heritage, and ethnic diversity.', 'Initiated in 2002 by the Government of Assam to promote eco-tourism, rainforest conservation, and World War II heritage.', 'Named after the meandering Dehing river and the undulating Patkai mountain range on the Indo-Myanmar frontier.', 'To spotlight rainforest preservation, heritage tea plantations, oil mining history, and ethnic tribal crafts.', 'Confluence of biodiversity conservation, indigenous tribal solidarity, and historic heritage exploration.', 'Encompasses historical trails including the World War II Stilwell Road (Ledo Road) and Asia''s oldest operating oil refinery at Digboi.', ARRAY['Inaugural parade featuring 18 ethnic communities', 'Tea garden heritage walks', 'Birdwatching excursions inside Dehing Patkai National Park', 'Craft exhibitions']::TEXT[], 'Cultural troupes perform Singpho, Tangsa, Tai-Phake, Moran, and Tea-tribe folk dances along the river banks.', ARRAY['Singpho herbal bamboo smoked meat', 'Tai-Phake Paa-Sa (herbal raw fish soup)', 'Assamese thali', 'Finest CTC & orthodox Assam tea']::TEXT[], 'Spectacular showcase of ethnic handlooms: Singpho check sarongs, Tai-Phake silk waistcoats, and colourful tea tribe sarees.', 'Ethnic fusion, brass bands, tribal drum beats, and tea garden Jhumur dance rhythm.', ARRAY['Hoolock Gibbon', 'White-winged Wood Duck', 'Tea bush with two leaves and a bud', 'Stilwell Road milestone']::TEXT[], '3 to 4 Days', 'Gregorian (Tourism Calendar)', 'Organized during the peak winter tourism season in January.', 'January', 'ORGANIZER_ANNOUNCED', 'Second or third weekend of January', '2026-01-16 to 2026-01-19', '2027-01-15 to 2027-01-18', 'Assam Tourism Development Corporation & Tinsukia District Administration', ARRAY['Assam']::TEXT[], ARRAY['Digboi', 'Tinsukia', 'Margherita', 'Ledo']::TEXT[], ARRAY['Dehing Patkai National Park periphery', 'Margherita Golf Grounds', 'Digboi Centenary Oil Museum']::TEXT[], 'Morning wildlife birding walks followed by evening ethnic cultural showcases.', 3, 'A multidimensional expedition combining dense emerald rainforest walks, historical WWII memorials, and exotic ethnic culinary experiences.', 'Dibrugarh Airport (75 km away); Tinsukia railway junction; private taxis.', 'Tea bungalow heritage stays in Dibrugarh/Tinsukia and government eco-resorts.', 'Family and eco-traveler friendly; well-regulated.', 'Do not litter inside national park boundaries; respect forest conservation guidelines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('me-dam-me-phi-assam', 'Me-Dam-Me-Phi', ARRAY['Ahom Ancestor Worship Day']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tai-Ahom Religious Tradition', 'A revered Tai-Ahom religious festival honoring ancestors and departed kings with solemn prayers for cosmic peace.', 'Celebrated by the Ahom kings who ruled Assam for 600 years (1228–1826 CE), initiated by the first Ahom king Chao Lung Siu-Ka-Pha.', 'Me means offerings, Dam means ancestors, and Phi means gods; an integral ancestral communion ritual of the Tai people.', 'To pay homage to ancestral spirits, invoke their eternal protection, and pray for peace and prosperity for humanity.', 'Reverence for lineage, historic remembrance of the valorous Ahom kingdom, and preservation of Tai liturgy.', 'The Ahom dynasty''s unifying state ritual that solidified sovereign strength and communal cohesion across the Brahmaputra valley.', ARRAY['Construction of ancestral Me-Dam shrine (Dam-Phi)', 'Chanting of sacred hymns from ancient Ahom scriptures by Deodhai priests', 'Offering of rice wine, meat, and betel leaves to spirits', 'Public pledge of cultural integrity']::TEXT[], 'Solemn public functions held at historic Ahom capitals; priests in pure white conduct rites with incense and brass urns.', ARRAY['Lao-pani (traditional rice beverage)', 'Luk-lao', 'Traditional pork with elephant apple', 'Sticky Bora rice preparations']::TEXT[], 'Traditional Tai-Ahom white handloom attire, golden turban (Pha-khet), and silk wrappers.', 'Solemn chanting of Tai hymns, sacred bronze bells, and stately ritual drums.', ARRAY['Chao-Phi emblem', 'Ahom winged lion (Kha-rai-fa)', 'Hengdang sacred sword', 'Betel nut brass vessel']::TEXT[], '1 Day', 'Solar Calendar (Fixed Date)', 'Observed annually on January 31 as a gazetted public holiday across Assam.', 'January', 'FIXED', 'January 31 every year', '2026-01-31', '2027-01-31', 'Government of Assam Gazetted Holiday List & Tai Ahom Yuba Parishad', ARRAY['Assam']::TEXT[], ARRAY['Sivasagar', 'Charaideo', 'Jorhat', 'Guwahati']::TEXT[], ARRAY['Charaideo Maidams (UNESCO World Heritage Site)', 'Rang Ghar premises Sivasagar', 'Sivasagar Tai Cultural Complex']::TEXT[], '10:00 AM to 1:00 PM when Deodhai priests conduct the grand ancestral prayer ceremony at Charaideo Maidams.', 1, 'Rare, profound opportunity to witness an intact 800-year-old royal ancestral ritual set against the monumental burial mounds of Charaideo.', 'Buses and hired cars from Dibrugarh or Jorhat to Sivasagar and Charaideo.', 'Hotels in Sivasagar town or Jorhat heritage tea estates.', 'Solemn and respectful public gathering of historians, elders, and families.', 'Maintain silence during scriptural readings; do not step on ritual altar perimeters.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('brahmaputra-beach-festival-assam', 'Brahmaputra Beach Festival', ARRAY['Guwahati River Beach Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Modern Cultural & Adventure Tourism', 'A vibrant river-beach carnival held on the seasonal white sandbanks of the Brahmaputra River in Guwahati.', 'Initiated in the 1990s by the Assam Tourism Development Corporation to leverage seasonal dry-bed sand islands for tourism.', 'The mighty Brahmaputra exposes vast, pristine white sand beaches during the low-water winter months, creating a natural amphitheater.', 'To celebrate outdoor life, promote traditional indigenous sports, and showcase Northeast rock and folk music.', 'Youthful energy, adventurous river sports, winter sunshine, and contemporary riverine celebration.', 'Bridges ancestral indigenous games with modern youth adventure culture against the backdrop of one of the world''s greatest rivers.', ARRAY['Sand art competitions', 'Traditional Assamese kite flying', 'Elephant races and beach volleyball matches', 'Rock and folk music concerts at sundown']::TEXT[], 'Crowds flock to the temporary sandy island via ferry; open-air food courts, craft stalls, and adventure rides line the beach.', ARRAY['Assamese duck roast', 'Bamboo hollow chicken', 'Fish pitika', 'Momos', 'Kaji Nemu lemonade']::TEXT[], 'Casual winter streetwear, comfortable beach shoes, and vibrant Assamese handloom mufflers.', 'Northeast indie rock, Assamese folk-fusion, acoustic guitar sessions, and modern Bihu pop.', ARRAY['White sand dune', 'Ferry steamer silhouette', 'Colorful kites', 'Rising river sunrise']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized in January during the lowest water level of the river.', 'January', 'ORGANIZER_ANNOUNCED', 'Announced by Assam Tourism for a mid-January weekend', '2026-01-23 to 2026-01-25', '2027-01-22 to 2027-01-24', 'Assam Tourism Development Corporation', ARRAY['Assam']::TEXT[], ARRAY['Guwahati']::TEXT[], ARRAY['Bharalumukh Beach / Sukreswar Ghat sandbanks, Brahmaputra River, Guwahati']::TEXT[], 'Late afternoon (3:30 PM) until starry night under bonfire illumination.', 2, 'Sipping hot tea on soft river sands while listening to live acoustic music as river barges glide across the golden twilight.', 'Country boats and motor ferries from Fancy Bazar and Sukreswar Ghats.', 'Guwahati city hotels (Paltan Bazar, Uzan Bazar, Panbazar).', 'Youthful, lively, family-friendly riverside crowd.', 'Do not venture into unauthorized deep water currents of the Brahmaputra; dispose of all trash responsibly.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('baishagu-festival-assam', 'Baishagu', ARRAY['Bodo Spring New Year Festival']::TEXT[], 'HARVEST_SEASONAL', 'Bodo Community / Bathouism', 'The spirited spring festival of the Bodo people celebrating the New Year with the enchanting Bagurumba butterfly dance.', 'Celebrated by the Bodo community, the largest indigenous group in Assam, welcoming the Baisakh month with deep spiritual reverence.', 'Rooted in worship of the supreme Bathou deity (symbolized by the sacred Sijou cactus) and nature''s spring awakening.', 'To welcome the new agricultural year, venerate cattle, honor household deities, and celebrate youth with graceful dances.', 'Affirmation of Bodo cultural heritage, nature worship, and breathtaking feminine grace through dance.', 'The Bagurumba dance, mimicking the flutter of butterflies, is recognized globally as one of India''s most poetic folk dance forms.', ARRAY['Bathou Puja at the courtyard Sijou altar', 'Mwsou Gusu (washing and decorating cattle)', 'Paying homage to parents and community elders', 'Young women performing Bagurumba dance']::TEXT[], 'Courtyards resonate with rhythmic drum beats; families offer sacred rice beer (Jou) and visit relatives across villages.', ARRAY['Oma Bedor (Bodo pork curry with black sesame)', 'Sobai jwng Daosri (chicken with black lentils)', 'Jou Gishi (traditional rice beverage)', 'Maize cakes']::TEXT[], 'Women wear dazzling yellow Dokhona with red borders (Aronai scarves draped elegantly); men wear Gamsha and Aronai around neck.', 'Enchanting melodies on the Sifung (long bamboo flute), Kham (long drum), Serja (violin-like instrument), and Jotha (cymbals).', ARRAY['Sijou cactus plant (Bathou symbol)', 'Aronai scarf', 'Yellow Dokhona', 'Sifung flute']::TEXT[], '7 Days', 'Assamese/Bodo Solar Calendar', 'Begins in mid-April coinciding with Bohag Bihu (Baisakh 1).', 'April', 'SOLAR', 'April 14/15 annually coinciding with Spring Equinox calendar change', '2026-04-14 to 2026-04-20', '2027-04-14 to 2027-04-20', 'Bodoland Territorial Council (BTC) & Assam Cultural Affairs', ARRAY['Assam']::TEXT[], ARRAY['Kokrajhar', 'Baksa', 'Udalguri', 'Chirang', 'Guwahati']::TEXT[], ARRAY['Kokrajhar Town Hall & village courtyards across Bodoland']::TEXT[], 'Afternoons when community Bagurumba dance circles form under village shade trees.', 3, 'Mesmerizing sight of dozens of women dressed in brilliant yellow swaying like butterflies to the soothing tones of the long Sifung flute.', 'Kokrajhar railway station on the main Assam corridor; shared sumos and autos.', 'Government circuit houses and guest houses in Kokrajhar; hotels in Bongaigaon.', 'Warm, village-based community celebration; respectful visitors are treated like royal guests.', 'Do not touch the Bathou altar (Sijou cactus encircled with bamboo rings) without permission.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('dihing-tea-festival-assam', 'Dihing Tea Festival', ARRAY['Assam Tea Tourism Carnival', 'Chah Parba']::TEXT[], 'CULTURAL_NATIONAL', 'Tea Heritage & Colonial Planters History', 'A premier tea tourism festival showcasing Assam''s legendary heritage tea estates, tea-tasting sessions, and golf.', 'Celebrates Assam''s 200-year-old tea industry, founded after Robert Bruce discovered wild Camellia sinensis assamica in 1823.', 'Conceived to blend historic colonial bungalow lifestyle with indigenous tea-tribes'' vibrant folklore.', 'To promote world-class Assam tea, celebrate the hardworking tea garden community, and promote heritage estate tourism.', 'Appreciation for the world''s most popular beverage at its historic global origin in the lush Brahmaputra valley.', 'Assam is the world''s largest contiguous tea-growing region; the festival preserves century-old planter clubs and historic courses.', ARRAY['Professional tea tasting sessions with tea sommeliers', 'Exhibition Jhumur dance by tea tribe troupes', 'Vintage golf tournaments at century-old clubs', 'Factory tours observing orthodox and CTC processing']::TEXT[], 'Guests stay in sprawling colonial-era tea bungalows, take early morning tea plucking masterclasses, and attend evening garden galas.', ARRAY['Freshly steeped Single Estate First Flush teas', 'Smoked pork with local herbs', 'Tea garden samosas and cakes', 'Assamese bamboo shoot chicken']::TEXT[], 'Semi-formal planters attire, safari hats, and vibrant Jhumur dance handlooms.', 'Tea tribe Jhumur songs driven by Madal drums, traditional bagpipes, and live acoustic music.', ARRAY['Two leaves and a bud tea shoot', 'Classic porcelain teacup', 'Wicker plucking basket', 'Madal drum']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized during the pleasant winter month of November or December.', 'November', 'ORGANIZER_ANNOUNCED', 'Announced by Department of Tourism, Government of Assam', '2026-11-27 to 2026-11-29', '2027-11-26 to 2027-11-28', 'Assam Tourism & Tea Board of India', ARRAY['Assam']::TEXT[], ARRAY['Jorhat', 'Dibrugarh']::TEXT[], ARRAY['Tocklai Tea Research Institute Jorhat', 'Jorhat Gymkhana Club', 'Mancotta Tea Estate Dibrugarh']::TEXT[], 'Morning tea-plucking and cupping sessions followed by afternoon tea on manicured bungalow lawns.', 2, 'Relaxed, aristocratic luxury combined with authentic grassroots cultural encounters among the green carpets of Assam''s iconic estates.', 'Dibrugarh/Jorhat airports connect directly to Delhi and Kolkata; private chauffeur cars recommended.', 'Heritage tea estate bungalows (e.g., Mancotta, Chowkidinghee, Thengal Manor).', 'Refined, boutique traveler atmosphere.', 'Follow tea garden safety norms; refrain from walking off designated plucking rows without guides.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('losar-festival-tawang', 'Losar Festival Tawang', ARRAY['Monpa New Year', 'Tibetan-Monpa Buddhist New Year']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tibetan Buddhism (Gelugpa School)', 'The glorious 15-day Buddhist New Year festival celebrated with solemn monastery prayers and Cham mask dances across snow-clad Tawang.', 'Celebrated by the Monpa people for centuries, intertwined with the sacred founding of Tawang Monastery (Galden Namgey Lhatse) in 1680 CE.', 'Pre-Buddhist Tibetan Bon winter purification rites incorporated into Buddhist celebration by Guru Padmasambhava.', 'To purge evil influences of the departing year, welcome auspicious new beginnings, and pray for world peace and enlightenment.', 'Deep spiritual purification, filial piety, compassion for all sentient beings, and monastic grandeur.', 'Tawang Monastery is India''s largest Buddhist monastery and the second largest in the world after the Potala Palace in Lhasa.', ARRAY['Guthuk soup consumption on the 29th day of the 12th month for symbolic cleansing', 'Lighting butter lamps in family shrines at midnight', 'Raising fresh lungta windhorse prayer flags on mountain passes', 'Monastic Cham dances at Tawang Monastery']::TEXT[], 'Families offer Khata silk scarves, paste auspicious flour emblems on house pillars, and gather in monastery courtyards.', ARRAY['Guthuk (nine-ingredient noodle soup with symbolic dumplings)', 'Khapse (fried festival pastries)', 'Yak butter tea (Po Cha)', 'Zan (buckwheat porridge)']::TEXT[], 'Monpa Chuba woollen robes tied with red sashes, Shingka gowns, and traditional felt boots.', 'Deep harmonic chanting of Buddhist lamas, Dungchen long horns, Gyaling oboes, and rhythmic monastic cymbals.', ARRAY['Eight Auspicious Symbols (Ashtamangala)', 'Windhorse prayer flags', 'Butter sculptures (Torma)', 'Khapse pastry']::TEXT[], '15 Days (first 3 days are primary)', 'Tibetan Lunar Calendar (First month, day 1)', 'Calculated based on the Tibetan Lunisolar calendar; usually coincides with the new moon in February or early March.', 'February', 'LUNAR', 'First Day of first month of Tibetan Lunar Calendar', '2026-02-18 to 2026-02-20', '2027-02-07 to 2027-02-09', 'Tawang Monastery Administration & Arunachal Tourism', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Tawang', 'Bomdila', 'Dirang']::TEXT[], ARRAY['Tawang Monastery (Galden Namgey Lhatse)', 'Urgelling Monastery', 'Dirang Dzong']::TEXT[], 'Early morning prayers at dawn followed by monastery courtyard gatherings.', 4, 'Unearthly visual beauty: snow-covered mountain valleys wrapped in fluttering prayer flags while lamas sound 10-foot alpine horns.', 'Inner Line Permit (ILP) required; Sumo/Innova drives from Guwahati or Tezpur via Sela Pass (13,700 ft).', 'Cozy homestays in Tawang or monastery guest lodges; heavy winter heating essential.', 'Peaceful, devoted monastic and community gathering.', 'Always walk clockwise (Pradakshina) around monasteries and chortens; do not touch monks'' ceremonial robes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('torgya-festival-tawang', 'Torgya Festival', ARRAY['Tawang Monastery Torgya', 'Dungjur Festival (every 3rd year)']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tibetan Buddhism', 'A spectacular 3-day monastic festival at Tawang featuring esoteric Cham sacred mask dances and the burning of the Torgya effigy.', 'Celebrated annually for over three centuries according to ancient Gelugpa tantric monastic treatises.', 'Designed to appease protective deities, ward off pestilence and natural disasters, and foster tranquility in the realm.', 'To destroy evil spirits and karmic obstacles before the advent of the new agricultural year.', 'Triumph of dharma and wisdom over ignorance, fear, and demonic disruptions.', 'The Cham dances performed here are preserved unchanged from 17th-century tantric manuals.', ARRAY['Performing sacred Cham mask dances by initiated lamas in elaborate brocade robes', 'Consecration of the towering Torgya ritual dough pyramid', 'Ceremonial procession to the outskirts of Tawang to burn the effigy in a sacred bonfire', 'Lama blessings with holy ambrosia']::TEXT[], 'Thousands of Monpa villagers in finest regalia descend on the snowy monastery courtyard; lamas dance with swords and skull cups.', ARRAY['Khapse festive biscuits', 'Butter tea (Po Cha)', 'Steamed Tingmo buns with yak meat curry', 'Thukpa']::TEXT[], 'Vivid monastic silk brocades with wrathful deity masks (Mahakala, Yamantaka, Garuda); spectators wear thick wool Chuba.', 'Roaring Dungchen horns, Nga drums, Rolmo cymbals, and sacred tantric incantations.', ARRAY['Torgya sacrificial cake (Torma)', 'Yamantaka mask', 'Dorje (vajra) and Bell (drilbu)', 'Butter lamp flames']::TEXT[], '3 Days', 'Tibetan Lunar Calendar (11th month, 28th-30th days)', 'Falls towards the end of the 11th Tibetan lunar month, corresponding to late January in the Gregorian calendar.', 'January', 'LUNAR', '28th day of 11th Tibetan lunar month', '2026-01-16 to 2026-01-18', '2027-01-15 to 2027-01-17', 'Tawang Monastery Council & Department of Tourism Arunachal Pradesh', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Tawang']::TEXT[], ARRAY['Inner Courtyard of Tawang Monastery (Galden Namgey Lhatse)']::TEXT[], '10:00 AM to 2:00 PM when the theatrical Cham mask dances reach peak dramatic intensity.', 3, 'One of Asia''s most authentic monastic festivals: watching masked lamas spin against a backdrop of towering Himalayan snow peaks.', 'Shared sumos or private SUVs from Bomdila or Tezpur; require Indian ILP or Foreign PAP permit.', 'Hotels and family homestays in Tawang town.', 'High local attendance; highly respectful, silent audience during sacred dances.', 'Maintain silence during the dances; never walk across the central sacred performance circle.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ziro-festival-of-music-arunachal', 'Ziro Festival of Music', ARRAY['ZFM', 'Eco-Music Festival Ziro']::TEXT[], 'MUSIC_DANCE_ARTS', 'Independent Music, Eco-Art & Apatani Culture', 'India''s premier outdoor indie music festival set in the scenic pine-fringed rice valley of Ziro, built entirely of zero-waste bamboo.', 'Founded in 2012 by Anup Kutty and Bobby Hano, it has evolved into a world-famous gathering of independent musicians and travelers.', 'Created to put Northeast India''s vibrant indie talent on the global music map while honoring the sustainable ethos of the Apatani tribe.', 'To celebrate musical creativity, promote eco-friendly zero-plastic tourism, and foster cultural exchange between indie artists and indigenous tribes.', 'Uninhibited indie artistic freedom, environmental harmony, community camaraderie, and pristine Himalayan mountain vibes.', 'Pioneered 100% sustainable bamboo stage architecture, locally sourced rice beers, and waste recycling models in Indian festival tourism.', ARRAY['Apatani village walkarounds and elder blessings', 'Day stage acoustic performances (Danyii Stage)', 'Night high-energy rock/electronic stage (Pwlo Stage)', 'Campfire jam sessions under clear star-filled skies']::TEXT[], 'Music lovers camp in pine groves, sample authentic smoked pork, sip golden kiwi and millet wine, and dance to international indie acts.', ARRAY['Pike Pila (Apatani bamboo shoot delicacy)', 'Smoked pork with local greens', 'Ziro Kiwi wine', 'Marua millet beer', 'Steamed momos']::TEXT[], 'Bohemian festival casuals, rubber mud boots (essential), warm evening jackets, and Apatani handmade beaded necklaces.', 'Independent folk, rock, funk, electronica, post-rock, jazz, and traditional Apatani vocal polyphony.', ARRAY['Monumental bamboo stage structure', 'Apatani terraced paddy field', 'Kiwi fruit vine', 'Campfire glow']::TEXT[], '4 Days', 'Gregorian (Autumn Calendar)', 'Held on the last weekend of September every year during golden pre-harvest season.', 'September', 'ORGANIZER_ANNOUNCED', 'Last Thursday through Sunday of September annually', '2026-09-24 to 2026-09-27', '2027-09-23 to 2027-09-26', 'Ziro Festival Official Foundation & Arunachal Pradesh Tourism', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Ziro', 'Hapoli']::TEXT[], ARRAY['Biiri Village Meadows, Ziro Valley']::TEXT[], 'Late afternoons on Danyii Stage as the sunset illuminates golden paddy terraces.', 4, 'Unrivaled bohemian festival magic: crisp mountain air, golden sunlit rice fields, soulful indie bands, and warm camaraderie around midnight fires.', 'Guwahati to Naharlagun by overnight Donyi Polo Express train, followed by 3.5 hour scenic taxi drive to Ziro.', 'Festival pine-grove campsites (tents provided) or traditional Apatani homestays.', 'Global music travelers, creative artists, and local Apatani youth; remarkably eco-conscious and safe.', 'Leave No Trace policy is strictly enforced; carry personal reusable water bottles; respect village elders.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('nyokum-yullo-arunachal', 'Nyokum Yullo', ARRAY['Nyishi Harvest and Sowing Festival']::TEXT[], 'HARVEST_SEASONAL', 'Nyishi Tribal Tradition (Donyi-Polo)', 'The premier agricultural festival of the Nyishi tribe celebrating cosmic harmony, prosperity, and plentiful harvests.', 'Celebrated by the Nyishi people, the largest tribal group in Arunachal Pradesh, worshipping Donyi (Sun) and Polo (Moon).', 'Nyok means land/earth and Kum means togetherness; an ancestral prayer to protect human beings and livestock from catastrophe.', 'To pray for bountiful harvests, ward off crop epidemics, and preserve harmony between mankind and the supernatural spirits of nature.', 'Unity of the Nyishi community, pride in ancestral indigenous customs, and veneration of cosmic celestial forces.', 'Demonstrates unbroken animist priesthood (Nyibu) traditions and ecological ethics handed down across millenniums.', ARRAY['Erection of the sacred Yugang prayer altar made of fresh bamboo poles and leaves', 'Chanting of epic creation hymns by the head priest (Nyibu)', 'Ceremonial mithun or bull offering for community blessing', 'Rikham Pada folk dance']::TEXT[], 'Villagers dress in breathtaking woven garb, link arms in expansive circle dances, and share rice delicacies in community grounds.', ARRAY['Wungw (traditional rice dish)', 'Boiled smoked mithun meat with bamboo shoot', 'Chamin fermented seed chutney', 'Opo (fermented rice beverage)']::TEXT[], 'Men wear Bopia cane helmets adorned with hornbill beaks, cotton waistcoats, and long dao swords; women wear Paro woven skirts with brass disc belts.', 'Rikham Pada and Buya folk songs performed in unison with stamping bamboo rhythm and brass bells.', ARRAY['Yugang bamboo sacrificial altar', 'Hornbill beak helmet (Bopia)', 'Donyi-Polo sun-moon symbol', 'Dao long sword']::TEXT[], '2 Days (main day Feb 26)', 'Solar Calendar (Fixed Dates)', 'Celebrated consistently across Arunachal Pradesh with state-wide holidays on February 26.', 'February', 'FIXED', 'February 26 annually (celebrations from Feb 24 to 27)', '2026-02-24 to 2026-02-27', '2027-02-24 to 2027-02-27', 'Nyokum Yullo Celebration Committee & Govt of Arunachal Pradesh Holiday List', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Yazali', 'Itanagar', 'Naharlagun', 'Seppa', 'Sagalee']::TEXT[], ARRAY['Nyokum Lapang grounds Itanagar', 'Yazali festival fields']::TEXT[], 'Morning of February 26 during the sacred Nyibu prayer invocations at the Yugang altar.', 2, 'Electrifying display of indigenous tribal pride, hypnotic rhythmic chanting, and striking warrior headgear in lush Himalayan hills.', 'Fly to Donyi Polo Airport (Itanagar) or take train to Naharlagun.', 'Hotels in Itanagar and Naharlagun, or heritage homestays in Yazali.', 'Thousands of community members; vibrant and welcoming.', 'Show deep respect to the Nyibu shaman; never cross between the priest and the Yugang altar during rites.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('dree-festival-arunachal', 'Dree Festival', ARRAY['Apatani Agricultural Festival']::TEXT[], 'HARVEST_SEASONAL', 'Apatani Tribal Tradition (Donyi-Polo)', 'The most significant agricultural festival of the Apatani valley, celebrated with rituals to protect crops from pests and famine.', 'Formalized as a collective community festival in 1967 to preserve the unique ancestral farming ethos of the Apatani plateau.', 'Centuries of agricultural experience where farmers pray to deities Tamu, Harniang, Metii, and Danyi during the vulnerable flowering phase of rice.', 'To appease the spirits of nature, prevent crop diseases, pray for abundant food, and foster community brotherhood.', 'Scientific agrarian wisdom blended with sacred ritual, solidarity among valley villages, and celebration of hospitality.', 'The Apatanis are world-renowned for their exceptionally efficient, UNESCO-tentative wetland rice-fish agricultural system.', ARRAY['Sacred chanting by traditional Apatani priests', 'Installation of ritual bamboo effigies in green paddy fields', 'Offering cucumber, beer, and sweets to guests', 'Daminda folk dance and traditional wrestling contests']::TEXT[], 'Families prepare large batches of rice beer, distribute fresh sweet cucumbers, and gather at Hapoli festival ground for cultural pageants.', ARRAY['Fresh sweet cucumbers (symbol of cooling bounty)', 'Pike Pila', 'Smoked pork with green leafy herbs', 'O (Apatani rice and millet beer)']::TEXT[], 'Women wear dark blue and orange bordered Galuk skirts with bamboo nose plugs (Yaping Hullo) and facial tattoos; men wear woven Apatani shawls.', 'Daminda rhythmic chorus songs, chanting by priestly bards, and traditional bamboo percussion.', ARRAY['Tamu ritual bamboo structure', 'Fresh green cucumber', 'Apatani bamboo nose plug', 'Terraced valley view']::TEXT[], '3 Days', 'Solar Calendar (Fixed Date)', 'Celebrated annually with peak ceremonies on July 5.', 'July', 'FIXED', 'July 4 to July 7 annually (main day July 5)', '2026-07-04 to 2026-07-07', '2027-07-04 to 2027-07-07', 'Central Dree Festival Committee & Arunachal Pradesh Tourism', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Ziro', 'Hapoli']::TEXT[], ARRAY['Central Dree Ground Hapoli, Ziro Valley']::TEXT[], 'July 5 morning (9:00 AM to 1:00 PM) for ceremonial dances and distribution of auspicious cucumbers.', 3, 'Witnessing the emerald green Ziro valley at its peak lushness, greeted by smiling elders who offer cucumber slices and millet wine as tokens of love.', 'Shared sumos from Naharlagun or Guwahati; ensure inner line permits are approved.', 'Village homestays in Hong, Hari, or Siiro villages of Ziro.', 'Pleasant, joyful valley-wide community congregation.', 'Accept cucumber and beer offerings with both hands; ask permission before photographing elderly tattooed women.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('mopin-festival-arunachal', 'Mopin Festival', ARRAY['Galo Harvest and Fertility Carnival']::TEXT[], 'HARVEST_SEASONAL', 'Galo Tribal Tradition (Donyi-Polo)', 'A joyous harvest festival of the Galo tribe where celebrants smear white rice flour (Ette) on each other''s faces in joyful blessings.', 'Celebrated for generations by the Galo people across West Siang district to welcome the goddess of wealth and wisdom, Mopin.', 'Mythological tale of goddess Mopin who bestowed seeds of agriculture to humanity, teaching them how to sow and harvest.', 'To drive away evil spirits, eradicate diseases, seek divine agricultural blessings, and foster communal harmony.', 'Pure joy, social cohesion, mutual blessings with sacred white flour, and vibrant feminine round dances.', 'Known colloquially as the ''Holi of Arunachal Pradesh'', yet uniquely celebrated with fragrant ground white rice powder.', ARRAY['Smearing sacred Ette (rice powder) on faces of family and visitors', 'Popir dance performed in circles by women led by the Nyibu priest', 'Sacred mithun offering at the festival shrine', 'Distribution of blessed Apong drink']::TEXT[], 'Towns and villages are painted in cheerful white; lines of women in dazzling white and black dresses move rhythmically across lawns.', ARRAY['Ette rice cakes', 'Amin (thick porridge of rice, minced meat, and bamboo shoot)', 'Smoked pork', 'Poka (sweet fermented rice wine)']::TEXT[], 'Spectacular pure white cotton Galuk tops with intricate black geometric bordered skirts (Gale) and heavy multi-layered bead necklaces.', 'Popir geet songs sung in call-and-response by the shaman and dancing women with graceful hand claps.', ARRAY['White Ette rice flour on cheeks', 'Mopin effigy', 'Gale geometric skirt pattern', 'Galo brass bead jewelry']::TEXT[], '5 Days (main day April 5)', 'Solar Calendar (Fixed Date)', 'Observed officially across Arunachal Pradesh with state holiday on April 5.', 'April', 'FIXED', 'April 5 annually (festivities April 4 to 8)', '2026-04-04 to 2026-04-08', '2027-04-04 to 2027-04-08', 'Central Mopin Celebration Committee Along & Arunachal Tourism', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Aalo (Along)', 'Basar', 'Itanagar', 'Pasighat']::TEXT[], ARRAY['Aalo Mopin Ground, West Siang', 'Itanagar Festival Grounds']::TEXT[], 'Morning of April 5 when the Ette flour smearing and Popir dances start.', 2, 'Unrestricted warmth and laughter as locals warmly dab your face with cool, fragrant white rice powder while welcoming you into dance circles.', 'Overnight bus or taxi from Dibrugarh crossing the Bogibeel bridge into Pasighat and Aalo.', 'Eco-resorts and homestays along the Yomgo River in Aalo.', 'Extremely lively, high-spirited, and welcoming.', 'Expect to get rice powder on your clothes and face; wear easily washable clothing.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('solung-festival-arunachal', 'Solung Festival', ARRAY['Adi Agricultural and Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Adi Tribal Tradition (Donyi-Polo)', 'The grand post-sowing socio-religious festival of the Adi tribe celebrated with Ponung dance and mythic rhapsodies.', 'Celebrated by the Adi people of the Siang valley, commemorating the creation of crops, cattle, and humankind.', 'Rooted in the myth of Pedong Nane, mother of all creatures; celebrated when weed-clearing of the summer paddy fields is finished.', 'To invoke divine blessings for a rich harvest, immunity from natural pests, protection of livestock, and longevity of the clan.', 'Community solidarity, reverence for the miraculous origins of agricultural grain, and poetic storytelling.', 'The Miri shaman recites the entire Adi genesis and history of human migration entirely from memory over nights of singing.', ARRAY['Sopi-Yekkei (mithun and animal sacrifices for protection)', 'Binyat (ritual propitiation of the goddess of crops, Kine Nane)', 'Ekop (preparation of bows and arrows to ward off malevolent spirits)', 'Ponung dance performed by women led by the Miri sword-shaman']::TEXT[], 'The entire village gathers in the open field; young women form a majestic circle swaying to the sword-wielding Miri singer.', ARRAY['Apong (fermented millet and rice beer)', 'Ettin (steamed rice cake wrapped in leaves)', 'Smoked pork with bamboo shoots', 'Boiled mountain tubers']::TEXT[], 'Adi women wear Gale wrap skirts with striking red and blue horizontal stripes; men wear woven coats and bear-fur caps.', 'Miri sacred chants sung while rhythmically shaking the Yoksha (sacred iron sword with jingling discs), echoed by Ponung women.', ARRAY['Yoksha sword with rattling rings', 'Mithun horns', 'Kine Nane crop symbol', 'Gale handloom pattern']::TEXT[], '5 to 7 Days (commencing Sept 1)', 'Solar Calendar (Fixed Date)', 'Observed officially beginning on September 1 annually across the Adi heartland.', 'September', 'FIXED', 'September 1 annually (festivities Sept 1 to 5)', '2026-09-01 to 2026-09-05', '2027-09-01 to 2027-09-05', 'Central Solung Festival Committee Pasighat & Arunachal Tourism', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Pasighat', 'Yingkiong', 'Roing', 'Itanagar']::TEXT[], ARRAY['Giidi Notko Pasighat', 'Yingkiong festival grounds']::TEXT[], 'Late afternoon into twilight when the hypnotic Ponung sword dance commences.', 3, 'Mesmerizing rhythmic acoustics of the Miri''s sword rattling in unison with hundreds of women singing ancient verses along the mighty Siang river.', 'Accessible by road from Dibrugarh (3.5 hours via Bogibeel bridge) to Pasighat.', 'Riverside eco-lodges along the Siang at Pasighat.', 'Enthusiastic, welcoming tribal gathering.', 'Never interrupt the Miri shaman when reciting sacred creation verses.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('siang-river-festival-arunachal', 'Siang River Festival', ARRAY['Yomgo River Festival', 'Brahmaputra Adventure and Cultural Fest']::TEXT[], 'MUSIC_DANCE_ARTS', 'Ecology, Adventure Sports & Siang Heritage', 'A thrilling adventure and cultural festival on the roaring banks of the mighty Siang River featuring white-water rafting and tribal arts.', 'Initiated to celebrate the majestic Siang (the principal stream of the Brahmaputra) and foster international eco-tourism.', 'Conceived by the state government to showcase the pristine river valleys, cascading rapids, and indigenous riverine cultures.', 'To promote international white-water rafting, spotlight tribal arts and crafts, and highlight ecological conservation of Himalayan rivers.', 'High-octane adventure sports, natural grandeur of deep gorges, and vibrant communal celebration.', 'The Siang is revered as the cradle of Adi civilization and one of the world''s most formidable big-water expedition rivers.', ARRAY['Inaugural river blessing ceremony by village elders', 'Whitewater kayaking and rafting regattas', 'Traditional boat racing', 'Ethnic culinary contests']::TEXT[], 'International rafters, cultural troupes, and travelers camp along clean sandy river beaches, attending nightly music concerts.', ARRAY['Pike Pila', 'River fish wrapped in banana leaves and roasted over open coals', 'Wild forest mushrooms', 'Bamboo steamed sticky rice']::TEXT[], 'Adventure outdoor wear by day, traditional Adi, Galo, and Memba handloom shawls around night bonfires.', 'Folk fusion bands, tribal acoustic groups, and modern indie music under starry river skies.', ARRAY['Class V river rapid white-water', 'Rafting paddle', 'Adi cane suspension bridge', 'Siang river confluence']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized during the clear winter waters of December or January.', 'December', 'ORGANIZER_ANNOUNCED', 'Announced by Arunachal Pradesh Tourism for a December weekend', '2026-12-18 to 2026-12-20', '2027-12-17 to 2027-12-19', 'Department of Tourism, Government of Arunachal Pradesh', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Pasighat', 'Tuting', 'Pangin']::TEXT[], ARRAY['Siang Riverbanks, Pasighat & Pangin confluence']::TEXT[], 'Midday for exhilarating whitewater rafting; evenings for riverside acoustic performances.', 3, 'Unmatched rush of adrenaline watching elite kayakers navigate Himalayan rapids followed by evenings under warm beach tents.', 'Nearest airport is Pasighat or Dibrugarh; 4WD vehicles recommended for upstream stretches.', 'Riverside luxury tents and local homestays in Pasighat.', 'Outdoor adventurers, nature enthusiasts, and tribal families.', 'Wear certified lifejackets whenever boarding river crafts; do not enter rapids unsupervised.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('sanken-festival-arunachal', 'Sanken Festival', ARRAY['Sangken', 'Water Splashing Festival of the Khamtis']::TEXT[], 'RELIGIOUS_TEMPLE', 'Theravada Buddhism', 'A joyous 3-day Buddhist water-splashing festival of the Khamti and Singpho people marking the Buddhist New Year.', 'Celebrated since antiquity by the Tai-Khamti and Singpho communities of eastern Arunachal Pradesh, sharing roots with Songkran.', 'Theravada Buddhist New Year tradition signifying physical and spiritual cleansing before entering the new calendar year.', 'To clean holy Buddha statues, wash away sins of the old year, earn spiritual merit, and spread joy through mutual water spraying.', 'Purity, loving-kindness (Metta), renewal, and merry community celebration without malice.', 'Direct cultural and religious link connecting Arunachal Pradesh with the wider Theravada Buddhist civilizations of Southeast Asia.', ARRAY['Procession bringing the Buddha idol to a ceremonial pavilion (Kyongfra)', 'Ritual bathing of Buddha statues with pure scented water', 'Sprinkling blessed water on monks, elders, and peers', 'Final day returning of idols to monasteries']::TEXT[], 'People joyfully splash water on everyone with buckets, squirt guns, and bowls, followed by community feasting.', ARRAY['Tongtep (steamed rice cake wrapped in leaves)', 'Khao Puk (black sesame rice cake)', 'Khamti herbal soup', 'Paa-Sa (traditional raw fish soup with herbs)']::TEXT[], 'Theravada Buddhist white and saffron wraps; women wear exquisite Tai-Khamti silk Siu shirts and dark Pha-Sin skirts.', 'Beating of grand Kong-Pat drums, bronze Mong cymbals, and joyful Tai folk chants.', ARRAY['Scented water in brass bowl', 'Buddha bathing fountain (Kyongfra)', 'Kong-Pat drum', 'White orchid garland']::TEXT[], '3 Days', 'Tai Solar Calendar (Mid-April)', 'Celebrated consistently from April 13 to 15, matching Songkran and Mesha Sankranti.', 'April', 'SOLAR', 'April 13 to 15 annually', '2026-04-13 to 2026-04-15', '2027-04-13 to 2027-04-15', 'Tai Khamti Heritage Society & Namsai District Administration', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Namsai', 'Chongkham']::TEXT[], ARRAY['Golden Pagoda (Kongmu Kham) at Tengapani, Namsai', 'Chongkham Monastery']::TEXT[], 'Mid-morning around 10:30 AM at the Golden Pagoda during the ceremonial water pouring on Buddha images.', 2, 'Drenching water-splashing merriment in front of the gleaming Southeast Asian architecture of the magnificent Golden Pagoda.', 'Fly to Dibrugarh; 2.5 hour smooth drive on NH15 to Namsai.', 'Resort accommodations at the Golden Pagoda complex or hotels in Namsai town.', 'High-energy, exuberant, friendly water-splashing crowd.', 'Never splash monks, elderly people, or infants aggressively; keep electronic devices in waterproof bags.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('chalo-loku-arunachal', 'Chalo Loku', ARRAY['Nocte Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Nocte Tribal Tradition', 'The grand pre-harvest festival of the Nocte tribe of Tirap district celebrating victory, harvest, and brotherhood.', 'Celebrated by the Nocte people after clearing paddy fields, traditionally lasting three distinct days: Phamlamja, Chamkatja, and Thanlangja.', 'Chalo means harvest season, and Loku means festival; observed to thank the supreme deity Jauban for safeguarding fields.', 'To drive away evil spirits, initiate youth into warrior rites, and pray for peace, health, and bountiful paddy.', 'Valor, ancestral connection, colorful pageantry, and community camaraderie in the Patkai foothills.', 'The Noctes were renowned warriors who converted to Neo-Vaishnavism in the 18th century, creating a unique syncretic culture.', ARRAY['Chamkat ritual (initiation of youth into adulthood)', 'Chanting prayers to supreme god Jauban', 'Pang soman (traditional war dance around the village pillar)', 'Sharing of roasted meat and millet beer']::TEXT[], 'Villagers assemble at the local chief''s palace; men don dazzling feathered crowns, brandish swords, and dance in rhythmic formation.', ARRAY['Smoked wild pork', 'Kham (steamed millet bread)', 'Boiled colocasia leaves with chili', 'Jum (fermented rice beer)']::TEXT[], 'Magnificent headgear adorned with hornbill feathers and wild boar tusks, beaded necklaces, and colorful woven armbands.', 'Hypnotic beats on monumental log drums (Tham) kept in the Morung youth dormitory, accompanied by war chants.', ARRAY['Great village log drum (Tham)', 'Hornbill feather headdress', 'Boar tusk adornment', 'Village ceremonial pillar']::TEXT[], '3 Days', 'Solar Calendar (Fixed Date)', 'Observed officially every year with peak celebrations on November 25.', 'November', 'FIXED', 'November 25 annually (Nov 24 to 26)', '2026-11-24 to 2026-11-26', '2027-11-24 to 2027-11-26', 'Tirap District Administration & Nocte Cultural Society', ARRAY['Arunachal Pradesh']::TEXT[], ARRAY['Khonsa', 'Deomali']::TEXT[], ARRAY['Khonsa Nehru Stadium & Lazu village grounds, Tirap']::TEXT[], 'November 25 morning for the dramatic warrior circle dances.', 2, 'Unrivaled sensory spectacle: the thunderous boom of hollowed-out log drums reverberating across misty Patkai mountain ridges.', 'Accessible via Dibrugarh by road (3 hours) through Khonsa; restricted area permit precautions apply.', 'Circuit houses and local homestays in Khonsa.', 'Traditional village audience; warm and respectful.', 'Respect local tribal customs; do not touch ceremonial warrior regalia without asking.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('hornbill-festival-nagaland', 'Hornbill Festival', ARRAY['Festival of Festivals', 'Nagaland Hornbill Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Naga Heritage / Pan-Tribal Cultural Union', 'India''s most famous cultural extravaganza bringing together all 17 major Naga tribes at Kisama Heritage Village for 10 unforgettable days.', 'Conceived in the year 2000 by the Government of Nagaland to revive, protect, and sustain the rich tribal heritage of the state.', 'Named after the Great Indian Hornbill, a bird revered in Naga folklore and tribal songs for its beauty and vigilance.', 'To celebrate Naga tribal unity, preserve ancient folk traditions, promote cultural tourism, and foster world peace.', 'Unmatched tribal spectacle, fierce cultural pride, hospitality, rock music vibrancy, and spectacular artisan heritage.', 'Has become one of the premier cultural tourism festivals on the global calendar, drawing visitors from over 60 countries.', ARRAY['Daily grand tribal parades featuring all 17 Naga tribes in full traditional regalia', 'Traditional fire-making and archery competitions', 'Naga chilli-eating and pork-fat eating contests', 'Hornbill International Rock Concert and Night Carnival']::TEXT[], 'Kisama turns into a living museum where each tribe inhabits its authentic tribal Morung house, singing, dancing, and serving local cuisine.', ARRAY['Smoked pork cooked with fermented soybean (Akhuni)', 'Bamboo shoot pork curry', 'Naga King Chilli (Bhut Jolokia) chutney', 'Galho (savory Naga khichdi)', 'Zutho (frothy Naga rice beer)']::TEXT[], 'Distinctive woven shawls and warrior costumes for all 17 tribes; hornbill feathers, wild boar tusks, brass necklaces, and red cane leggings.', 'War chants, rhythmic foot-stamping choruses, log drum beating, and high-octane rock performances by international bands.', ARRAY['Great Indian Hornbill feather', 'Carved wooden Morung pillars', 'Naga spear and dao', 'Bhut Jolokia chilli']::TEXT[], '10 Days', 'Solar Calendar (Fixed Dates)', 'Held strictly every year from December 1 to December 10 at Naga Heritage Village Kisama.', 'December', 'FIXED', 'December 1 to 10 annually', '2026-12-01 to 2026-12-10', '2027-12-01 to 2027-12-10', 'Department of Tourism, Government of Nagaland', ARRAY['Nagaland']::TEXT[], ARRAY['Kohima', 'Kisama']::TEXT[], ARRAY['Naga Heritage Village Kisama (12 km south of Kohima)', 'Kohima Night Bazaar']::TEXT[], 'Morning session from 9:30 AM to 12:30 PM for main arena dances; evening 6 PM for rock music and Kohima night market.', 5, 'One of the world''s greatest cultural spectacles: sitting in an open-air mountain amphitheater surrounded by warriors in feathered crowns chanting epic songs.', 'Dimapur railway/airport is 70 km away; shared sumos and taxis ply to Kohima; shuttle buses connect Kohima to Kisama.', 'Kohima hotels and homestays book out 6 months ahead; glamping tent villages set up near Kisama.', 'Vibrant international and domestic audience; safe, festive, friendly.', 'Ask before photographing individuals; respect Morung traditions; stay warm as winter temperatures drop sharply at night.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('moatsu-mong-nagaland', 'Moatsu Mong', ARRAY['Ao Naga Post-Sowing Festival']::TEXT[], 'HARVEST_SEASONAL', 'Ao Naga Tribal Tradition', 'A vibrant post-sowing spring festival of the Ao Naga tribe celebrated with traditional songs, dances, and fire-making rites.', 'Celebrated for centuries by the Ao people in Mokokchung district after clearing fields and sowing seeds.', 'A period of relaxation and joy (Mong) after rigorous field labor; asking the supreme creator Lijaba for protection of young crops.', 'To foster community bonds, instill moral values in youth, honor elders, and pray for healthy crop growth.', 'Relaxation, friendship, chivalry, romantic courtship, and artistic expression among the Ao people.', 'Mokokchung is the intellectual and cultural cradle of the Ao Nagas; Moatsu showcases pristine forms of indigenous council debates.', ARRAY['Sangpangtu (lighting ceremonial community bonfires where young men and women sit in circles)', 'Tug-of-war contests', 'Recitation of epic love ballads and warrior tales', 'Traditional fire-making competition using dry wood and cane rope']::TEXT[], 'Villagers dress in striking black, red, and white Tsungkotepsu shawls; youths feast, sing into midnight, and express mutual affection.', ARRAY['Pork cooked with fermented bamboo shoots', 'Smoked beef with crushed perilla seeds', 'Ao ginger chutney', 'Rice wine']::TEXT[], 'Men wear Tsungkotepsu shawls displaying warrior motifs; women wear exquisitely embroidered Achan shawls and heavy brass collars.', 'Melodious Ao folk choruses, rhythmic chanting, and resonant beats on village log drums.', ARRAY['Tsungkotepsu warrior shawl', 'Sangpangtu bonfire', 'Dry cane fire-saw', 'Mokokchung mountain skyline']::TEXT[], '3 to 6 Days (primary celebrations May 1 to 3)', 'Solar Calendar (Fixed Dates)', 'Celebrated during the first week of May annually across Mokokchung.', 'May', 'FIXED', 'May 1 to 3 annually', '2026-05-01 to 2026-05-03', '2027-05-01 to 2027-05-03', 'Ao Senden (Ao Tribal Council) & Nagaland Tourism', ARRAY['Nagaland']::TEXT[], ARRAY['Mokokchung', 'Chuchuyimlang', 'Ungma']::TEXT[], ARRAY['Chuchuyimlang Village Ground', 'Ungma Village', 'Mokokchung Town Park']::TEXT[], 'May 2 afternoon when the central community dances and fire-making rituals are held at Chuchuyimlang.', 3, 'Unrivaled scenic beauty of Mokokchung''s ridge-top villages, greeted by the legendary hospitality of Ao families around crackling fires.', 'Shared sumos or private SUVs from Kohima (5 hours) or Jorhat/Mariani in Assam (3 hours).', 'Village homestays in Chuchuyimlang and Ungma or hotels in Mokokchung town.', 'Enthusiastic, welcoming village gathering.', 'Accept hospitality graciously; participate politely if invited into tug-of-war.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('sekrenyi-festival-nagaland', 'Sekrenyi', ARRAY['Phousanyi', 'Angami Naga Purification Festival']::TEXT[], 'RELIGIOUS_TEMPLE', 'Angami Naga Indigenous Tradition / Tenyidie Rites', 'A 10-day sacred purification festival of the Angami Nagas, cleansing the body, soul, and community of past sins.', 'Celebrated for generations by the Angami people inhabiting Kohima and Dimapur districts, marking the winter solstice renewal.', 'Phousanyi or Sekrenyi literally means ''sanctification festival''; focused on renewing spiritual strength and warrior virtue.', 'To wash away all illnesses and misfortunes, initiate young boys into manhood, and seek divine blessings for the upcoming year.', 'Spiritual cleansing, discipline, ancestral bonding, and communal rejuvenation before sowing.', 'Khonoma and Kohima village, the epicenters of Sekrenyi, are historic centers of Naga resistance and ecological sustainability.', ARRAY['Kizie (ritual washing of the body with clean well water in the dead of night)', 'Thekra Hie (young men and women sitting together singing traditional songs)', 'Making of new hunting weapons', 'Community feasts where meat is distributed among kinsfolk']::TEXT[], 'Men wake up before dawn to bathe in sacred springs, fetch unpolluted water, and perform solitary ancestral sacrifices.', ARRAY['Pork cooked with crushed mustard leaves', 'Galho with wild greens', 'Steamed rice cakes', 'Freshly brewed rice beer (Zutho)']::TEXT[], 'Angami black Loramhoushu shawls with bright red borders, green stone bead necklaces, and wild boar tusk armlets.', 'Haunting polyphonic Tenyidie choruses, acoustic folk melodies, and rhythmic clapping.', ARRAY['Sacred village spring well', 'White rooster', 'Angami green stone beads', 'Zutho horn cup']::TEXT[], '10 Days (main rituals days 1 to 5)', 'Solar Calendar (Fixed Date Window)', 'Begins on the 25th day of the Angami month of Kezei (commencing February 25 annually).', 'February', 'FIXED', 'February 25 to March 3 annually', '2026-02-25 to 2026-03-03', '2027-02-25 to 2027-03-03', 'Angami Public Organisation (APO) & Nagaland Tourism', ARRAY['Nagaland']::TEXT[], ARRAY['Kohima', 'Khonoma', 'Touphema']::TEXT[], ARRAY['Khonoma Green Village', 'Kohima Village (Bara Basti)', 'Touphema Tourist Village']::TEXT[], 'Days 2 and 4 when young people gather in traditional attire at village gates for Thekra Hie singing.', 3, 'A deeply authentic cultural encounter in Asia''s first green village (Khonoma), witnessing ancient water purification rites and listening to ancient polyphonic harmonies.', 'Kohima to Khonoma is 20 km (45-minute scenic mountain drive by taxi).', 'Village homestays in Khonoma and Touphema community chalets.', 'Intimate, dignified village community environment.', 'Do not touch the sacred village water spring during purification days; respect private morning family prayer hours.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('aoleang-monyu-nagaland', 'Aoleang Monyu', ARRAY['Konyak Naga Spring Festival']::TEXT[], 'HARVEST_SEASONAL', 'Konyak Naga Tribal Tradition', 'The premier spring festival of the legendary tattooed Konyak headhunters of Mon, welcoming the new year with warrior dances.', 'Celebrated since antiquity by the Konyak Nagas of Mon district along the Patkai range on the Myanmar border.', 'Marks the conclusion of the harsh winter, clearing of jungle tracts, and invoking the sky deity Gwang for rich autumn harvest.', 'To pray for abundant crops, foster brotherly reconciliation, and celebrate the warrior heritage of the Konyak clan.', 'Raw warrior pride, living ancient history, vibrant hospitality, and colorful Patkai mountain pageantry.', 'Mon is famous worldwide for the last surviving tattooed Konyak headhunter elders who wear bronze head trophies and facial markings.', ARRAY['Sacrificial invocation to supreme deity Gwang', 'Firing of ancient muzzle-loader guns in synchronized salute', 'Fierce warrior line dances brandishing brass daos', 'Feasting in the grand palaces of the Anghs (hereditary kings)']::TEXT[], 'The entire district of Mon erupts with rhythmic gunshots; elders with facial tattoos dance side by side with young warriors.', ARRAY['Smoked wild boar cooked with black sesame', 'Boiled colocasia with fiery King Chilli', 'Millet beer in bamboo flagons', 'Sticky rice parcels']::TEXT[], 'Spectacular traditional Konyak warrior gear: hornbill feathers, brass head necklaces, boar tusk headpieces, red cane leggings, and handwoven shawls.', 'Deep rhythmic warrior stomping, thunderous gun salutes, and ancient Konyak war chants echoing across valleys.', ARRAY['Tattooed facial markings', 'Bronze head pendant necklace', 'Hornbill plume headgear', 'Angh royal palace']::TEXT[], '6 Days', 'Solar Calendar (Fixed Dates)', 'Celebrated consistently across Mon district from April 1 to April 6 every year.', 'April', 'FIXED', 'April 1 to 6 annually', '2026-04-01 to 2026-04-06', '2027-04-01 to 2027-04-06', 'Konyak Union & Department of Tourism Nagaland', ARRAY['Nagaland']::TEXT[], ARRAY['Mon', 'Longwa', 'Shangnyu']::TEXT[], ARRAY['Mon Town Ground', 'Longwa Village (straddling India-Myanmar border)', 'Shangnyu Village']::TEXT[], 'April 3 and 4 (Gonyi and Goki days) when the warrior gun salutes and community dances peak in Longwa village.', 4, 'One of the most extraordinary cultural encounters on Earth: meeting legendary tattooed elders in the palace of the King of Longwa whose house sits right on the international border.', 'Train to Sonari/Bhojo in Assam, followed by 3-hour hill drive to Mon; 4WD vehicle strongly recommended.', 'Basic rustic homestays in Longwa and Mon town; advance planning essential.', 'Fiercely proud, warm, welcoming village crowds.', 'Always ask permission before taking close-up portraits of elderly tattooed warriors; offer small gift/tobacco respectfully when entering the Angh''s palace.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('tokhu-emong-nagaland', 'Tokhu Emong', ARRAY['Lotha Naga Post-Harvest Thanksgiving']::TEXT[], 'HARVEST_SEASONAL', 'Lotha Naga Tribal Tradition', 'The grand 9-day post-harvest thanksgiving festival of the Lotha Nagas of Wokha, celebrating forgiveness, peace, and reconciliation.', 'Celebrated following the harvest when granaries are filled, signaling an end to field toil and opening a period of joyous leisure.', 'Tokhu means feasting and eating; Emong means rest. Instituted to heal past quarrels, forgive old debts, and unite the community.', 'To give thanks for a bountiful harvest, resolve interpersonal conflicts, pray for the souls of the departed, and rest from hard labor.', 'Peace, forgiveness, brotherly reconciliation, overflowing generosity, and culinary abundance.', 'Known for its strict code of social forgiveness: anyone with a grievance must forgive their neighbor before partaking in the feast.', ARRAY['Lighting of the ceremonial hearth fires', 'Collection of village contributions by the village priest', 'Reconciliation visits between estranged neighbors', 'Grand community feast and folk song exchanges']::TEXT[], 'Villagers dress in breathtaking black and gold Lotha shawls, sing songs of lineage, and share pots of meat and wine across courtyards.', ARRAY['Lotha bamboo shoot pork', 'Smoked beef with crushed wild coriander', 'Fermented dry bamboo shoot soup', 'Lotha sweet rice brew']::TEXT[], 'Magnificent Lotha Champo and Pangden shawls with distinctive horizontal striped bands and cowrie shell trims.', 'Melodious, slow-tempo Lotha harvest ballads, rhythmic chanting, and traditional wooden clappers.', ARRAY['Lotha handwoven shawl pattern', 'Granary filled with paddy', 'Cowrie shell adornment', 'Mount Tiyi silhouette']::TEXT[], '9 Days (main celebrations Nov 7)', 'Solar Calendar (Fixed Date)', 'Observed officially every year on November 7 across Wokha district.', 'November', 'FIXED', 'November 7 annually', '2026-11-04 to 2026-11-09', '2027-11-04 to 2027-11-09', 'Lotha Hoho & Department of Tourism Nagaland', ARRAY['Nagaland']::TEXT[], ARRAY['Wokha', 'Pangti']::TEXT[], ARRAY['Wokha Local Ground', 'Pangti Village (near Doyang Amur Falcon roosting sites)']::TEXT[], 'November 7 morning for traditional cultural dances, followed by afternoon visits to Doyang reservoir for the Amur Falcon migration.', 2, 'A sublime combination of rich cultural thanksgiving in Wokha town and the awe-inspiring sight of millions of migrating Amur Falcons over Doyang lake.', 'Wokha is 75 km from Kohima (2.5 hour scenic mountain drive).', 'Homestays in Wokha town or eco-camps at Pangti village.', 'Warm, peaceful, and family-oriented community celebration.', 'Respect the spirit of reconciliation; do not display arrogance or ill temper in the festival arena.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('tuluni-festival-nagaland', 'Tuluni', ARRAY['Sumi Naga Mid-Year Festival']::TEXT[], 'HARVEST_SEASONAL', 'Sumi Naga Tribal Tradition', 'The premier mid-year festival of the Sumi Nagas of Zunheboto celebrating agricultural abundance, betrothal, and community feasts.', 'Celebrated when the rice crops stand tall in the fields, providing a joyful interlude before the final ripening phase.', 'Tuluni literally means ''feasting with rice beer''; centered on honoring betrothed couples and strengthening clan alliances.', 'To pray for abundant grain, celebrate matrimonial betrothals, exchange gifts between in-laws, and honor cultivating youth.', 'Romance, generosity, valor, martial sports, and joyful hospitality.', 'The Sumis are renowned for their martial heritage, agility, and fierce warrior dances preserved through generations.', ARRAY['Anni (slaughtering of livestock and sharing meat)', 'Exchange of gift baskets (Tulutsuku) with betrothed fiancées', 'Traditional high-jump and war-dance exhibitions', 'Blessing by village elders for healthy crops']::TEXT[], 'The entire town gathers in full red-black-white regalia; young couples exchange gifts while warriors perform energetic jumping dances.', ARRAY['Axone (fermented soybean paste cooked with smoked pork)', 'Chili chutney', 'Steamed sticky rice balls', 'Zutho and rice wine']::TEXT[], 'Sumi warriors wear red and black woven skirts, cowrie chest-cross bands, wild boar tusk collars, and feather caps.', 'Vigorous rhythmic warrior cries (Aphi Lhou), dynamic leaping stomps, and traditional Sumi courtship songs.', ARRAY['Axone paste pot', 'Wild boar tusk collar', 'Sumi cowrie warrior cross', 'Betrothal gift basket']::TEXT[], '3 Days', 'Solar Calendar (Fixed Date)', 'Celebrated across Nagaland with a state gazetted holiday on July 8 annually.', 'July', 'FIXED', 'July 8 annually', '2026-07-07 to 2026-07-09', '2027-07-07 to 2027-07-09', 'Sumi Hoho & Nagaland Tourism', ARRAY['Nagaland']::TEXT[], ARRAY['Zunheboto', 'Dimapur', 'Kohima']::TEXT[], ARRAY['Zunheboto Town Ground', 'Sumi Baptist Church grounds']::TEXT[], 'July 8 morning for the breathtaking Sumi warrior jumping dances and marital pageantry.', 2, 'Witnessing the unmatched athletic grace of Sumi warriors leaping several feet into the air in full armor while sampling rich Axone-infused pork.', 'Shared sumos from Kohima or Dimapur to Zunheboto.', 'Local guest houses in Zunheboto or Dimapur hotels.', 'High-energy, joyous, and celebratory.', 'Taste the famous Axone with an open culinary mind; it possesses an intense, earthy, Umami-rich aroma.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ngada-festival-nagaland', 'Ngada', ARRAY['Rengma Naga Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Rengma Naga Tribal Tradition', 'An eight-day thanksgiving and harvest festival of the Rengma tribe of Tseminyu, celebrating peace and peace-pacts.', 'Celebrated at the conclusion of the harvest season, marking the end of the agricultural calendar.', 'Instituted to remember the souls of deceased ancestors, celebrate agricultural fruitfulness, and conclude peaceful alliances.', 'To thank the supreme creator for a fruitful harvest, share bounty with the less fortunate, and renew friendships.', 'Generosity, sharing of agricultural wealth, peaceful coexistence, and remembrance of departed relatives.', 'Tseminyu, the newly created 13th district of Nagaland, is the historic heartland of the master-weaver Rengma tribe.', ARRAY['Lighting new fire in every household', 'Solemn visits to ancestral graves offering food and wine', 'Procession through the village by warrior elders', 'Feast of forgiveness where all debts are cleared']::TEXT[], 'Villagers clean streets, wear their famous black and red Rhikho shawls, and visit house to house singing ancient rhapsodies.', ARRAY['Smoked beef with local dry greens', 'Pork cooked with crushed wild herbs', 'Pounded sticky rice cakes', 'Lush rice wine']::TEXT[], 'Famous Rengma Rhikho and Teri Phikhu shawls decorated with white and red motifs; beaded necklaces and brass wristbands.', 'Melodic polyphonic hymns, rhythmic Rengma walking songs, and synchronized warrior foot-stamping.', ARRAY['Rhikho handwoven shawl', 'Freshly sparked fire flint', 'Ancestral remembrance cup', 'Paddy bundle']::TEXT[], '8 Days (main celebrations late November)', 'Solar Calendar (Fixed Date Window)', 'Celebrated annually during the last week of November (typically November 27-28).', 'November', 'FIXED', 'November 27 to 28 annually', '2026-11-27 to 2026-11-28', '2027-11-27 to 2027-11-28', 'Rengma Hoho & Tseminyu District Administration', ARRAY['Nagaland']::TEXT[], ARRAY['Tseminyu', 'Kohima']::TEXT[], ARRAY['Tseminyu Town Ground', 'Phenshunyu village']::TEXT[], 'Morning of November 28 for community dancing and traditional wrestling matches.', 2, 'Intimate glimpse into ancient Naga hospitality and refined handloom aesthetics in the tranquil hills of Tseminyu.', 'Tseminyu is located 50 km north of Kohima on the Kohima-Mokokchung highway (1.5 hours).', 'Homestays in Tseminyu or hotels in Kohima.', 'Warm, dignified, village community gathering.', 'Maintain decorum when passing near ancestral cemetery memorials during morning visitation hours.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('hega-festival-nagaland', 'Hega Festival', ARRAY['Zeliang Naga New Year Festival']::TEXT[], 'HARVEST_SEASONAL', 'Zeliangrong Indigenous Tradition', 'A vibrant New Year and spring festival of the Zeliang people of Peren, invoking divine blessings for wealth and matrimonial joy.', 'Celebrated for generations by the Zeliang people in southwestern Nagaland, marking the onset of spring and the agricultural year.', 'A sacred occasion to thank the supreme God Tingwang for protecting the clan throughout the past year.', 'To seek divine blessings, solemnize new marriages, initiate young people into youth dormitories, and plan farming activities.', 'Joyful matrimonial celebration, optimism for spring, youthful vigor, and deep cultural continuity.', 'Peren is the cultural bastion of the Zeliangrong people, renowned for their intricate synchronized group dancing.', ARRAY['Invocation to Tingwang by the village elder', 'Blessing of newly wedded couples', 'Competitive high jumping and shot put using heavy river stones', 'Hypnotic group circle dances with synchronized clapping']::TEXT[], 'Youth dress in striking black and white embroidered kilts, forming concentric dance rings while elders toast them with horn cups.', ARRAY['Pork cooked with fermented bamboo shoots', 'Millet dumplings', 'Fresh river fish with chili relish', 'Frothy rice beer']::TEXT[], 'Zeliang traditional attire: black kilts with cowrie shells, white headbands with hornbill feathers, and colorful beaded sashes.', 'Incredible rhythmic chanting without instruments, maintaining flawless tempo through footwork and clapping.', ARRAY['Zeliang hornbill headband', 'Cowrie-trimmed warrior kilt', 'Tingwang sun symbol', 'Peren valley mist']::TEXT[], '3 Days', 'Solar Calendar (Fixed Dates)', 'Celebrated annually from February 10 to February 12 across Peren district.', 'February', 'FIXED', 'February 10 to 12 annually', '2026-02-10 to 2026-02-12', '2027-02-10 to 2027-02-12', 'Zeliang People''s Organisation & Peren District Administration', ARRAY['Nagaland']::TEXT[], ARRAY['Peren', 'Jalukie']::TEXT[], ARRAY['Peren Town Ground', 'Benreu Tourist Village']::TEXT[], 'February 11 for the world-famous synchronized Zeliang circle dances.', 2, 'Mesmerizing sight of dozens of dancers moving in flawless unison with mathematical precision against the emerald peaks of Peren.', 'Accessible by road from Dimapur (2.5 hours) or Kohima (3 hours).', 'Heritage homestays in Benreu village or eco-lodges in Peren.', 'Vibrant, hospitable, community-centered.', 'Remove hats when entering sacred elder council squares.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('naknyulem-festival-nagaland', 'Naknyulem', ARRAY['Chang Naga Mid-Summer Festival']::TEXT[], 'HARVEST_SEASONAL', 'Chang Naga Tribal Tradition', 'A joyous 3-day mid-summer festival of the Chang Nagas of Tuensang, celebrating peace, archery, and music on the bamboo Jew''s harp.', 'Celebrated by the Chang people of eastern Nagaland during the waxing moon of July to mark the completion of weeding fields.', 'Instituted to thank God for healthy standing crops, celebrate the triumph of light over darkness, and foster inter-village peace.', 'To ward off malevolent spirits, test youthful agility in traditional games, and fill the village with the melodies of the Jew''s harp.', 'Musical creativity, youthful joy, marksmanship, and peace in the rugged eastern mountains.', 'Tuensang is one of Nagaland''s most remote and authentic cultural regions, preserving ancient Chang woodcarving and textile crafts.', ARRAY['Lighting pine torches to banish dark forces', 'Playing the Kongkei (traditional bamboo Jew''s harp) by men and women', 'Top-spinning and tug-of-war competitions', 'Exchange of baked meat rolls and rice wine']::TEXT[], 'The town fills with the delicate twanging hum of hundreds of bamboo Jew''s harps, while warriors demonstrate archery skills.', ARRAY['Smoked pork with local dried herbs', 'Steamed maize patties', 'Wild mountain honey with roasted tubers', 'Rice wine']::TEXT[], 'Exquisite Chang Mohney shawls with intricate red, blue, and black diamond geometric bands; brass tiger-tooth necklaces.', 'Enchanting music of the Kongkei (bamboo jaw harp), Chang warrior chants, and rhythmic drum stomping.', ARRAY['Kongkei (bamboo Jew''s harp)', 'Chang Mohney geometric shawl', 'Pine torch flame', 'Tuensang mountain peak']::TEXT[], '3 Days', 'Solar Calendar (Fixed Dates)', 'Celebrated annually during the second week of July (typically July 11-13).', 'July', 'FIXED', 'July 11 to 13 annually', '2026-07-11 to 2026-07-13', '2027-07-11 to 2027-07-13', 'Chang Tribal Council & Tuensang District Administration', ARRAY['Nagaland']::TEXT[], ARRAY['Tuensang']::TEXT[], ARRAY['Tuensang Parade Ground & Chang village squares']::TEXT[], 'Afternoon of July 12 when the Kongkei musical performances and top-spinning games take place.', 2, 'Discovering the ethereal acoustic soundscape of the bamboo jaw harp echoing through pristine, cloud-kissed mountain villages.', 'Shared sumos from Mokokchung (4 hours) or Dimapur (10 hours); rugged terrain.', 'Circuit house and local homestays in Tuensang.', 'Welcoming, curious, and hospitable rural gathering.', 'Listen politely to solo instrumentalists playing the delicate Kongkei without loud conversation.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('yemshe-festival-nagaland', 'Yemshe', ARRAY['Pochury Naga Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Pochury Naga Tribal Tradition', 'The grand post-harvest festival of the Pochury Nagas of Meluri, celebrated with solemn rituals, unity feasts, and traditional games.', 'Celebrated by the Pochury people inhabiting the Saramati mountain borders, commemorating the arrival of the new harvest.', 'Divided into Great Yemshe and Small Yemshe; observed to thank the spirits of nature and sanitize the entire village.', 'To express gratitude for abundant food, strengthen village defense, and welcome the arrival of the new agricultural grain.', 'Purity, discipline, brotherly love, culinary generosity, and community renewal.', 'Meluri is situated near Mount Saramati (Nagaland''s highest peak at 3,841m), preserving pristine Pochury textile traditions.', ARRAY['Sanitization of village springs and footpaths', 'Family blessing ceremonies at granaries', 'Grand community feast where youths serve village elders', 'Solemn warrior line dance in traditional black attire']::TEXT[], 'Villagers assemble in striking attire; elders bless the harvest while youth compete in high jumps and stone-lifting games.', ARRAY['Pork cooked with dry tree-tomato and wild bamboo shoots', 'Millet beer', 'Pounded sticky rice cakes', 'Smoked fish']::TEXT[], 'Distinctive Pochury black shawls trimmed with brilliant red embroidery and cowrie shell fringes.', 'Soulful Pochury folk singing, steady rhythmic stomping, and festive brass gong chimes.', ARRAY['Saramati mountain peak', 'Pochury cowrie shawl', 'Granary threshold', 'Bamboo rice flagon']::TEXT[], '4 Days', 'Solar Calendar (Fixed Date Window)', 'Celebrated annually during the first week of October (peak day October 5).', 'October', 'FIXED', 'October 5 annually (festivities Oct 3 to 6)', '2026-10-03 to 2026-10-06', '2027-10-03 to 2027-10-06', 'Pochury Hoho & Meluri Sub-Divisional Administration', ARRAY['Nagaland']::TEXT[], ARRAY['Meluri', 'Phek']::TEXT[], ARRAY['Meluri Local Ground, Phek District']::TEXT[], 'October 5 morning for the formal community dances and elderly blessings.', 2, 'Off-the-beaten-path mountain expedition witnessing ancient harvest customs under the shadow of majestic Mount Saramati.', 'Accessible via Kohima to Phek and onward to Meluri (7-hour hill drive).', 'Local homestays and government rest houses in Meluri.', 'Intimate, warm, and highly hospitable.', 'Dress warmly; respect elder blessings with bowed head and folded hands.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('sangai-festival-manipur', 'Manipur Sangai Festival', ARRAY['Grand Tourism Festival of Manipur']::TEXT[], 'MUSIC_DANCE_ARTS', 'Manipur Cultural Unity & Heritage', 'Manipur''s premier state tourism festival celebrating Manipuri classical dance, indigenous martial arts (Thang-Ta), and Polo.', 'Initiated in 2010 by the Government of Manipur to showcase the state''s rich art, culture, handlooms, and adventure sports to the world.', 'Named after the state animal, the critically endangered Brow-antlered Deer (Sangai), found exclusively at Keibul Lamjao National Park.', 'To promote international tourism, showcase Manipur''s status as the birthplace of modern Polo, and celebrate composite ethnic arts.', 'Artistic perfection, elegance of Manipuri Raas Leela, athletic prowess of Thang-Ta, and environmental preservation.', 'Manipur gifted modern Sagol Kangjei (Polo) to the world; the festival showcases historic polo matches at Mapal Kangjeibung, world''s oldest living polo ground.', ARRAY['Inauguration with traditional Penna string invocation', 'Polo exhibition matches played on indigenous Manipuri ponies', 'Thang-Ta martial arts demonstrations', 'Manipuri classical Raas Leela performances']::TEXT[], 'Multiple venues across Imphal and Loktak Lake host exhibitions, food courts, boat races, and evening international cultural galas.', ARRAY['Kangshoi (vegetable stew with dry fish)', 'Chak-hao Kheer (purple black rice pudding)', 'Eromba (mashed potato, fish, and chili)', 'Singju (fiery vegetable salad)', 'Nga Thongba (fish curry)']::TEXT[], 'Incomparable elegance: women in pink and green silk Phanek and Innaphi with gold jewelry; polo players in white dhotis with red Kokyet turbans.', 'Haunting melody of the Penna (single-string bowed instrument), classical Pung (terracotta drum), and flute.', ARRAY['Sangai deer antlers', 'Phumdi floating island on Loktak Lake', 'Penna musical instrument', 'Sagol Kangjei polo stick']::TEXT[], '10 Days', 'Solar Calendar (Fixed Dates)', 'Celebrated strictly every year from November 21 to November 30 across Manipur.', 'November', 'FIXED', 'November 21 to 30 annually', '2026-11-21 to 2026-11-30', '2027-11-21 to 2027-11-30', 'Department of Tourism, Government of Manipur', ARRAY['Manipur']::TEXT[], ARRAY['Imphal', 'Moirang', 'Bishnupur']::TEXT[], ARRAY['Hapta Kangjeibung & BOAT Palace Compound Imphal', 'Loktak Lake Moirang', 'Mapal Kangjeibung Polo Ground']::TEXT[], 'Late afternoon polo matches at Mapal Kangjeibung followed by 6:00 PM classical dance recitals at the Bhagyachandra Open Air Theatre (BOAT).', 4, 'Unrivaled aesthetic wonder: watching world-class Raas Leela dancers glisten in mirror-work skirts under starry skies, followed by purple black-rice kheer.', 'Bir Tikendrajit International Airport (Imphal) connects directly to Delhi, Kolkata, and Guwahati; taxis in Imphal.', 'Classic Hotel, Classic Grande, and boutique homestays in Imphal; floating lake cottages at Loktak.', 'Enthusiastic, cosmopolitan, family-friendly; well-managed security.', 'Maintain silence during classical Raas Leela performances; remove shoes when entering traditional performance pavilions.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('yaoshang-festival-manipur', 'Yaoshang', ARRAY['Manipuri Spring Festival', 'Festival of Thabal Chongba']::TEXT[], 'HARVEST_SEASONAL', 'Meitei Vaishnavism & Sanamahism', 'Manipur''s grandest 5-day spring festival blending traditional Vaishnavite devotion, sports olympiads, and the mesmerizing Thabal Chongba moonlight dance.', 'Celebrated since the 18th century reign of King Garib Niwaj, integrating ancient Meitei spring rites with Gaudiya Vaishnavism.', 'Commences on the full moon day of Phalguna with the burning of the Yaoshang thatched straw hut at sunset.', 'To celebrate the arrival of spring, invoke blessings of Lord Chaitanya, promote youth fitness through grassroots sports, and kindle courtship through dance.', 'Uniquely energetic blend of spiritual singing, state-wide sports competitions, playful splashing of colors, and romantic moonlight dancing.', 'Manipur''s sports revolution stems directly from Yaoshang: every locality suspends business to conduct 5-day mini-Olympics for all ages.', ARRAY['Yaoshang Mei Thaba (ceremonial burning of straw hut at dusk)', 'Holi Sankirtan singing in temple courtyards', 'Neighborhood sports olympiads (athletics, football, tug-of-war)', 'Night-long Thabal Chongba (moonlight circle dance)']::TEXT[], 'Children collect token donations; by day every ground hosts athletic tournaments; by night thousands dance hand-in-hand under the full moon.', ARRAY['Chak-hao Kheer', 'Singju (raw vegetable and fermented fish salad)', 'Khabey (fried flour sweet)', 'Bora savory fritters', 'Kanghou sauteed vegetables']::TEXT[], 'Pure traditional elegance: girls in pastel silk Phanek, Innaphi shawls with jasmine flowers; boys in white Kurta and Dhoti.', 'Ecstatic Pung Cholom drumming, kartal cymbals, modern brass bands, and energetic Dholak rhythms during Thabal Chongba.', ARRAY['Burning straw hut (Yaoshang)', 'Thabal Chongba circle under moon', 'Pung drum', 'Sports baton']::TEXT[], '5 Days', 'Meitei Luni-Solar Calendar (Phalguna Full Moon)', 'Begins on the full moon day (Purnima) of the month of Phalguna (February/March).', 'March', 'LUNISOLAR', 'Full moon of Phalguna month', '2026-03-03 to 2026-03-07', '2027-03-22 to 2027-03-26', 'Govt of Manipur Gazetted Holidays & Govindajee Temple Board', ARRAY['Manipur']::TEXT[], ARRAY['Imphal', 'Moirang', 'Kakching', 'Thoubal']::TEXT[], ARRAY['Shree Govindajee Temple Imphal', 'Kangla Fort lawns', 'Community grounds in every Imphal locality']::TEXT[], 'Evening 8:00 PM to midnight when the magnificent Thabal Chongba moonlight dance circles form across Imphal.', 3, 'Electrifying community joy: walking into an open field bathed in moonlight where hundreds of youth in pastel silks hold hands in a giant dancing circle.', 'Auto-rickshaws and rental cabs in Imphal; most shops close during daytime sports matches.', 'Hotels across central Imphal (Kanglapat, Sanjenthong).', 'City-wide, vibrant, joyful family participation.', 'Ask respectfully before joining a Thabal Chongba dance ring; observe local modest dress norms.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ningol-chakouba-manipur', 'Ningol Chakouba', ARRAY['Sister Honoring Day of Manipur']::TEXT[], 'FOLK_COMMUNITY', 'Meitei Heritage & Pan-Manipuri Brotherhood', 'A heartwarming family festival where married daughters and sisters are invited back to their parental home for a sumptuous feast.', 'Legend traces back to Queen Laisana and King Nongda Lairen Pakhangba in the 1st century CE; later institutionalized across the kingdom.', 'Originally celebrated between brothers and sisters; later expanded to all married daughters (Ningols) returning home.', 'To revive and strengthen parental and brotherly bonds with married daughters, showers them with blessings and gifts.', 'Love, filial affection, family reunion, generous hospitality, and gender respect.', 'A profound social unifier in Manipur that transcends ethnic boundaries, today celebrated across Meitei, Naga, and Pangal communities.', ARRAY['Parents sending formal betel nut invitations to married daughters', 'Preparation of elaborate traditional multi-course fish feast', 'Blessing of daughters and grandchildren by parents', 'Gifting of handloom Phaneks and gifts to sisters']::TEXT[], 'Streets bustle with elegantly dressed women carrying brass trays covered with silk cloths returning to their childhood homes.', ARRAY['Sareng Thongba (royal freshwater fish curry)', 'Nga Atoiba Thongba', 'Singju', 'Iromba with lotus root', 'Chak-hao Kheer']::TEXT[], 'Married women wear their finest silk handwoven Rani Phi and gold-embroidered Phanek; brothers wear traditional white Dhoti and Kurta.', 'Joyful conversation, laughter, acoustic guitar tunes, and radio broadcast of classic Manipuri family songs.', ARRAY['Sareng fish', 'Brass gift tray with banana leaf cover', 'Rani Phi silk shawl', 'Family dining circle']::TEXT[], '1 Day', 'Meitei Luni-Solar Calendar (Hiyangei month)', 'Celebrated on the second lunar day (Nongma Panba) of the Meitei calendar month of Hiyangei (October/November).', 'November', 'LUNISOLAR', 'Second day of the new moon of Hiyangei month', '2026-11-11', '2027-10-31', 'Government of Manipur Gazetted Holiday List', ARRAY['Manipur']::TEXT[], ARRAY['Imphal', 'Bishnupur', 'Thoubal']::TEXT[], ARRAY['Family households across Manipur', 'Ema Keithel (Mother''s Market) Imphal for pre-festival shopping']::TEXT[], 'Morning shopping at Ema Keithel market followed by lunch gatherings in traditional Manipuri homes.', 1, 'Touching social warmth: watching sisters glowing in brilliant silks welcomed with folded hands, tears of joy, and feasts fit for royalty.', 'Pre-festival days see heavy traffic around markets; early taxi booking recommended.', 'Hotels in Imphal.', 'Private domestic celebrations across homes; bustling markets.', 'If invited to a local home, bring sweets or fruits; remove shoes before entering the dining area.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('cheiraoba-festival-manipur', 'Cheiraoba', ARRAY['Sajibu Cheiraoba', 'Meitei Lunar New Year']::TEXT[], 'HARVEST_SEASONAL', 'Sanamahism & Meitei Tradition', 'The traditional Meitei New Year festival celebrated with home-cooked culinary offerings to deities and the ritual climbing of sacred hills.', 'Celebrated since the dawn of Meitei civilization, documented in the ancient royal chronicle Cheitharol Kumbaba.', 'Sajibu is the first month of the Meitei calendar; Cheiraoba literally means ''announcement by stick'' (proclamation of the new year).', 'To welcome the new year, offer gratitude to ancestral household spirits (Sanamahi and Leimarel), and climb hills for spiritual elevation.', 'Spiritual renewal, household cleanliness, filial devotion, and triumphing over physical obstacles.', 'Preserves ancient Sanamahi indigenous altar rituals alongside royal astronomical traditions.', ARRAY['Deep cleaning of the home and courtyard', 'Cooking elaborate traditional vegetarian dishes by the family', 'Offering food on broad green banana leaves at house gates to spirits', 'Climbing the sacred Cheiraoching or Baruni hills in the afternoon']::TEXT[], 'After offering sanctified food at thresholds, entire families in new clothes trek up sacred hilltops to signify rising to greater life heights.', ARRAY['Eromba', 'Kangsoi', 'Singju', 'Sareng fish (in non-Sajibu Hindu Cheiraoba)', 'Chak-hao Kheer', 'Paknam (steamed banana-leaf savory cake)']::TEXT[], 'New traditional attire: men in pristine Dhoti and Kurta; women in exquisite striped Phanek and Innaphi.', 'Traditional devotional hymns, conch shell blowing, and joyous flute tunes on hilltrails.', ARRAY['Sacred banana leaf offering at door threshold', 'Cheiraoching hill summit', 'Lainingthou Sanamahi altar', 'Fresh seasonal bamboo shoot']::TEXT[], '1 Day', 'Meitei Luni-Solar Calendar (Sajibu 1)', 'Falls on the first day of the Meitei month Sajibu (March/April, coinciding with Ugadi/Gudi Padwa).', 'April', 'LUNISOLAR', 'First day of Sajibu month (New Moon)', '2026-03-20', '2027-04-07', 'Sanamahi Temple Board & Govt of Manipur Holiday List', ARRAY['Manipur']::TEXT[], ARRAY['Imphal']::TEXT[], ARRAY['Cheiraoching Hill, Chingmeirong, Imphal', 'Sanamahi Temple Haying Khongbal']::TEXT[], 'Late afternoon (3:00 PM to 6:00 PM) climbing Cheiraoching hill alongside thousands of locals for a panoramic sunset over Imphal valley.', 1, 'Panoramic views over the entire valley of Imphal from the hill summit, surrounded by cheerful families celebrating life and renewal.', 'Taxis to the base of Cheiraoching hill; walking trail to the summit.', 'Hotels in Imphal.', 'Substantial, cheerful crowds climbing hill pathways; very safe and festive.', 'Step carefully around food offerings placed on banana leaves outside domestic gates.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('kang-rath-yatra-manipur', 'Kang Rath Yatra', ARRAY['Manipur Chariot Festival', 'Kang Chingba']::TEXT[], 'RELIGIOUS_TEMPLE', 'Gaudiya Vaishnavism / Meitei Vaishnava Tradition', 'A 10-day grand chariot festival honoring Lord Jagannath, featuring towering wooden chariots, Pung Cholom, and night Sankirtan.', 'Introduced during the reign of King Gambhir Singh in 1832 CE at the Shree Govindajee Temple in Imphal.', 'Modeled on the Puri Rath Yatra, infused with the incomparable classical grace of Manipuri Vaishnavite dance and percussion.', 'To accompany Lord Jagannath, Balabhadra, and Subhadra on their journey, pulling the chariot ropes for spiritual liberation.', 'Ecstatic devotional love (Bhakti), communal pulling of sacred chariots, and peerless percussive arts.', 'Demonstrates Manipur''s unique synthesis of Vedic Vaishnavite liturgy with indigenous artistic expressions.', ARRAY['Pulling the massive wooden Kang chariot from Shree Govindajee Temple', 'Jayadeva''s Gita Govinda singing by temple ensembles', 'Bhog offerings of fresh seasonal fruits and sweets', 'Daily Jayadeva Sankirtan performances']::TEXT[], 'Devotees gather in thousands outside the palace gates, pulling the thick coir ropes with chants of ''Hari Bol!'' amidst crashing cymbals.', ARRAY['Kang Bhog (seasonal fruits, soaked gram, coconut)', 'Khichuri mahaprasad', 'Utti (alkaline yellow pea curry)', 'Payas pudding']::TEXT[], 'Devotees wear traditional white attire with Chandan Tilak on foreheads; priests in saffron silk.', 'Unmatched Pung Cholom (acrobatic drum dance), Kartal cymbals, conch shells, and Padavali Kirtan.', ARRAY['Kang wooden chariot', 'Lord Jagannath wooden murti', 'Pung drum', 'Coir chariot rope']::TEXT[], '10 Days', 'Luni-Solar Calendar (Ashadha Shukla Dwitiya)', 'Begins on the second day of the waxing moon of Ashadha (June/July), matching Puri Rath Yatra.', 'July', 'LUNISOLAR', 'Ashadha Shukla Dwitiya', '2026-07-16 to 2026-07-25', '2027-07-06 to 2027-07-15', 'Shree Shree Govindajee Temple Board, Imphal', ARRAY['Manipur']::TEXT[], ARRAY['Imphal']::TEXT[], ARRAY['Shree Shree Govindajee Temple & Palace Compound, Imphal']::TEXT[], 'Opening day afternoon (2:00 PM to 5:00 PM) for the grand chariot procession.', 2, 'Incredible fusion of Puri''s devotional grandeur with the lyrical, acrobatic elegance of Manipuri Pung Cholom drum dancers.', 'Accessible across central Imphal; roads around palace compound closed to vehicles during procession.', 'Hotels in Imphal.', 'Dense, peaceful, highly devotional crowd.', 'Participate in pulling chariot ropes with bare feet; accept prasadam with right hand.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('lui-ngai-ni-manipur', 'Lui-Ngai-Ni', ARRAY['Naga Seed Sowing Festival of Manipur']::TEXT[], 'HARVEST_SEASONAL', 'Naga Heritage of Manipur (Pan-Naga)', 'The premier seed-sowing festival unifying all Naga tribes of Manipur with spectacular cultural dances, fire-making, and folk blessing.', 'Conceived and unified in 1986 to consolidate the seasonal seed-sowing festivals of various Naga tribes under one collective banner.', 'Lui-Ngai-Ni is an acronym derived from seed-sowing terms across Tangkhul, Mao, Maram, and Rongmei languages.', 'To invoke the blessings of the supreme creator upon newly sown seeds, pray for peace, and celebrate Naga fraternity.', 'Unity, agrarian renewal, indigenous cultural preservation, and youthful vigor across hill tribes.', 'A gazetted state holiday in Manipur, symbolizing solidarity between various hill communities.', ARRAY['Lighting of the sacred festival torch using ancient flint/wood technique', 'Seed blessing invocation by tribal elders', 'Traditional war dances, spear dances, and ho-hoing choruses', 'Cultural showcase of handloom weaving and woodwork']::TEXT[], 'Representatives of over 15 Naga tribes in dazzling feathered headgear parade into the stadium, performing traditional choreographies.', ARRAY['Boiled pork with bamboo shoot', 'Roasted beef with local herbs', 'Sticky rice cakes', 'Wild honey and traditional rice beer']::TEXT[], 'Fabulous mosaic of Naga hill costumes: Tangkhul Luirim shawls, Mao woven wraps, hornbill feathers, and brass neckrings.', 'Deep rhythmic warrior chants, thunderous foot stomping, buffalo horn trumpets, and traditional acoustic guitars.', ARRAY['Sacred seed basket', 'Flint-struck fire torch', 'Hornbill plume', 'Naga spear']::TEXT[], '2 Days (main day Feb 15)', 'Solar Calendar (Fixed Date)', 'Celebrated annually on February 15 as a gazetted state holiday in Manipur.', 'February', 'FIXED', 'February 15 annually', '2026-02-14 to 2026-02-15', '2027-02-14 to 2027-02-15', 'United Naga Council (UNC) & Manipur Tourism', ARRAY['Manipur']::TEXT[], ARRAY['Ukhrul', 'Senapati', 'Tamenglong', 'Chandel']::TEXT[], ARRAY['Rotates annually between Ukhrul, Senapati, and Tamenglong district headquarters']::TEXT[], 'Morning of February 15 for the grand ceremonial parade and lighting of the sacred seed-sowing torch.', 2, 'Breathtaking hill celebration showcasing the vibrant diversity and living martial heritage of Manipur''s Naga tribes.', 'Shared sumos or private SUVs from Imphal to Ukhrul or Senapati (2.5 to 3.5 hours).', 'Homestays and district guest lodges in Ukhrul or Senapati.', 'Enthusiastic, welcoming hill community audience.', 'Respect local tribal customs; do not touch ceremonial warrior spears or shields without permission.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('heikru-hidongba-manipur', 'Heikru Hidongba', ARRAY['Manipuri Royal Boat Race Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Sanamahism & Meitei Heritage', 'A 240-year-old historic royal boat race festival held along the sacred Thangapat canal of Bijoy Govinda in Imphal.', 'Instituted in 1779 CE during the reign of King Bheigyachandra, dedicated to the deity Bijoy Govinda.', 'Heikru means Indian Gooseberry (Amla) and Hidongba means boat race; held to seek divine protection from disasters and diseases.', 'To pray for state welfare, test nautical agility, and offer garlanded gooseberries to the deities.', 'Competitive athletic spirit, royal nautical heritage, religious devotion, and community pride.', 'Preserves ancient Meitei royal naval traditions where long twin dugout boats race along narrow palace moats.', ARRAY['Garlanding Lord Bijoy Govinda with 108 hand-picked Heikru (amla) fruits', 'Purification rites of the racing longboats', 'Astrological divination by royal Brahmins', 'Thrilling twin boat race along the canal']::TEXT[], 'Thousands line the narrow canal embankments, cheering wildly as synchronized rowers plunge their carved paddles into the water.', ARRAY['Heikru fruit prasad', 'Steamed sweet rice cakes', 'Singju spicy salad', 'Seasonal fruits']::TEXT[], 'Rowers wear traditional white dhotis with red and green sashes; steersmen wear ceremonial turbans.', 'Roaring cheers of spectators, rhythm-setting whistles, and ceremonial conch shells.', ARRAY['Long dugout racing boat (Hi)', 'Garland of 108 Heikru (amla) fruits', 'Bijoy Govinda idol', 'Thangapat canal']::TEXT[], '1 Day', 'Meitei Luni-Solar Calendar (Langban 11)', 'Held on the 11th day of the Meitei month Langban (September).', 'September', 'LUNISOLAR', '11th day of Langban month', '2026-09-22', '2027-09-11', 'Bijoy Govinda Sevayet Committee & Manipur Cultural Affairs', ARRAY['Manipur']::TEXT[], ARRAY['Imphal']::TEXT[], ARRAY['Thangapat Canal, Bijoy Govinda, Sagolband, Imphal']::TEXT[], '1:00 PM to 4:00 PM when the ceremonial boat race takes place on the canal.', 1, 'Thrilling spectacle of vintage dugout wooden boats surging through narrow canal waters amidst roaring crowds under the autumn sun.', 'Accessible via auto-rickshaw or taxi in Sagolband, Imphal.', 'Hotels in Imphal.', 'Extremely lively, high-density local crowd lining the canal banks.', 'Arrive early to secure a safe vantage point along the moat; avoid leaning dangerously over the water.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('chumpha-festival-manipur', 'Chumpha Festival', ARRAY['Tangkhul Naga Post-Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Tangkhul Naga Tradition', 'A 7-day post-harvest festival of the Tangkhul Nagas of Ukhrul, uniquely centered around honoring women and securing granaries.', 'Celebrated by the Tangkhul people of the high Ukhrul hills following the paddy harvest in December.', 'Chumpha celebrates the entry of newly harvested paddy into the family granary; women play the pre-eminent role in this ritual.', 'To celebrate female stewardship of agricultural wealth, thank Mother Earth, and usher in winter leisure.', 'Gender equality, reverence for maternal leadership, family bonding, and festive rejoicing.', 'One of the rare indigenous harvest festivals where women lead the domestic rituals and opening of the sacred granary.', ARRAY['Women performing the ceremonial opening of the granary', 'Special feast prepared exclusively for the women of the village', 'Night-long singing of romantic and humorous folk songs', 'Community dancing on the final night']::TEXT[], 'The village of Ukhrul celebrates with joy; men cook special dishes for women, followed by youth singing competitions.', ARRAY['Pork cooked with dried mustard leaves', 'Smoked beef with fiery Ukhrul chilies', 'Steamed sticky rice bread', 'Tangkhul rice wine']::TEXT[], 'Tangkhul Luirim and Haora shawls with vivid red, black, and white bands; brass ornaments and bead necklaces.', 'Soulful Tangkhul acoustic ballads, four-part harmony singing, and traditional bamboo flutes.', ARRAY['Paddy granary door', 'Tangkhul Luirim shawl', 'Shirui Kashong peak silhouette', 'Bamboo wine cup']::TEXT[], '7 Days', 'Solar Calendar (Fixed Date Window)', 'Celebrated annually during the second week of December (typically December 10-16).', 'December', 'FIXED', 'December 10 to 16 annually', '2026-12-10 to 2026-12-16', '2027-12-10 to 2027-12-16', 'Tangkhul Naga Long & Ukhrul District Administration', ARRAY['Manipur']::TEXT[], ARRAY['Ukhrul']::TEXT[], ARRAY['Ukhrul Town Ground & Hunphun village, Ukhrul']::TEXT[], 'Evenings when community bonfires are lit and four-part harmony choral songs echo across the hills.', 3, 'Crisp winter mountain breezes, majestic pine-scented hills, and heartwarming hospitality celebrating women in the home of the Shirui Lily.', 'Ukhrul is 84 km from Imphal (3-hour mountain drive by taxi or shared sumo).', 'Homestays and hillside eco-lodges in Ukhrul town.', 'Warm, dignified, family-centered community.', 'Dress warmly in layers as December nights in Ukhrul are very cold; show utmost respect to female village elders.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('wangala-festival-meghalaya', 'Wangala Festival', ARRAY['100 Drums Wangala', 'Garo Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Garo Indigenous Tradition (Songsarek)', 'Meghalaya''s premier post-harvest festival of the Garo tribe where 100 long nagara drums beat in thunderous unison during the Great Dance.', 'Celebrated since antiquity by the Garo (A.chik) people to offer first-fruits of the harvest to the sun god Saljong.', 'Saljong, the sun god and supreme benefactor, is thanked for blessing the fields with bountiful crops of paddy and millet.', 'To express gratitude for fertility, offer thanks to the sun deity, and showcase the rhythm, stamina, and grace of Garo culture.', 'Thunderous percussive energy, agrarian thanksgiving, athletic stamina, and colorful tribal elegance.', 'The ''100 Drums Festival'' at Asanang near Tura brings together 10 troupes of 10 drummers each, creating an earth-shaking acoustic spectacle.', ARRAY['Rugala (ritual offering of rice beer and cooked food to Saljong)', 'Sasat So.a (burning of aromatic incense at the chief''s house)', 'The 100-Drums synchronized dance parade', 'Kotta Dokka (rhythmic recitation of epic verses)']::TEXT[], 'Men in feathered headgear play long cylindrical Dama drums; women in colorful sashes dance behind them with bird-like arm movements.', ARRAY['Minil sticky rice', 'Pork cooked with bamboo shoot and alkaline ash water (Kachi)', 'Dry fish chutney (Tapa)', 'Bitchi (sweet fermented rice beer)']::TEXT[], 'Men wear Kotip headdress with hornbill plumes and Gando dhotis; women wear dazzling Dakmanda wrap skirts with intricate shell beads.', 'Hypnotic thunder of 100 Dama drums beaten simultaneously, accompanied by the soulful bray of buffalo horn trumpets (Adil).', ARRAY['100 Dama drums', 'Adil buffalo horn trumpet', 'Kotip feathered crown', 'Dakmanda handloom motif']::TEXT[], '3 Days', 'Solar Calendar (Fixed Date Window)', 'Held on the second weekend of November annually at Asanang near Tura.', 'November', 'FIXED', 'Second Thursday to Saturday of November annually', '2026-11-12 to 2026-11-14', '2027-11-11 to 2027-11-13', '100 Drums Wangala Festival Committee & Meghalaya Tourism', ARRAY['Meghalaya']::TEXT[], ARRAY['Tura', 'Asanang']::TEXT[], ARRAY['Asanang Wangala Ground, West Garo Hills (15 km from Tura)']::TEXT[], 'Final day morning from 9:30 AM to 1:30 PM for the world-famous synchronized 100-Drums dance.', 3, 'One of India''s most exhilarating acoustic spectacles: feeling the ground beneath your feet physically vibrate as 100 long drums strike in unison.', 'Fly to Guwahati; drive 4.5 hours to Tura via Goalpara; local taxis ply between Tura and Asanang.', 'Hotels in Tura town or tent campsites near the Asanang festival ground.', 'Enthusiastic, welcoming crowd of over 30,000 tribal and global visitors.', 'Do not cross the main performance circle during the synchronized 100-drums line dance; accept Bitchi beer politely.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('shad-suk-mynsiem-meghalaya', 'Shad Suk Mynsiem', ARRAY['Dance of Peaceful Hearts', 'Khasi Spring Thanksgiving Dance']::TEXT[], 'HARVEST_SEASONAL', 'Khasi Indigenous Faith (Niam Khasi / Seng Khasi)', 'The most beloved spring thanksgiving festival of the Khasi people, celebrated with graceful open-air circle dances in golden silks.', 'Celebrated annually since the inception of the Seng Khasi movement in 1899 to protect and preserve ancestral Khasi rites.', 'Shad means dance, Suk means peaceful, and Mynsiem means heart/mind; a thanksgiving to God (U Blei) for life, health, and crops.', 'To celebrate the renewal of nature in spring, demonstrate modesty and purity of maidens, and chivalry of male warriors.', 'Peace, inner serenity, chivalric protection of women by men, and thankfulness for nature''s blessings.', 'Exemplifies the matrilineal social structure of the Khasi society where women occupy the central sacred circle.', ARRAY['Solemn morning prayer invocation at the Seng Khasi hall', 'Unmarried maidens dancing in the inner circle with downcast eyes', 'Men dancing in the outer circle with fly-whisks and swords symbolizing protection', 'Beating of sacred Tangmuri and Nakra instruments']::TEXT[], 'Shillong''s Weiking ground is filled with dazzling gold ornaments; women in heavy silver crowns dance gracefully to slow pipe rhythms.', ARRAY['Ja Doh (rice cooked with meat)', 'Dohneiiong (pork with black sesame)', 'Tungrymbai (fermented soybean)', 'Pukhlein (sweet fried rice cakes)']::TEXT[], 'Unmatched royal splendour: maidens in pure silk Jainsem, wearing solid gold crowns (Pansngiat) and coral necklaces; men in silk turbans and velvet waistcoats.', 'Soulful tunes on the Tangmuri (wooden oboe/pipe), rhythmic beats of the Nakra (kettledrum) and Padiah.', ARRAY['Pansngiat (solid silver/gold maiden crown)', 'Tangmuri pipe', 'Chammar (yak-tail fly-whisk)', 'Coral and gold bead collar']::TEXT[], '3 Days', 'Solar Calendar (Spring Season)', 'Celebrated on the second or third weekend of April annually at Weiking Ground, Shillong.', 'April', 'COMMUNITY_SPECIFIC', 'Second weekend of April annually', '2026-04-11 to 2026-04-13', '2027-04-10 to 2027-04-12', 'Seng Khasi Kmie & Department of Tourism, Govt of Meghalaya', ARRAY['Meghalaya']::TEXT[], ARRAY['Shillong']::TEXT[], ARRAY['Weiking Ground, Jaiaw, Shillong']::TEXT[], 'Final day afternoon (1:30 PM to 5:00 PM) when over 500 dancers in heirloom gold and silk fill the Weiking amphitheater.', 2, 'Sublime aesthetic elegance: seeing hundreds of maidens in glittering solid gold crowns glide with delicate steps under clear Shillong spring skies.', 'Taxis within Shillong city; 15-minute drive from Police Bazar to Weiking ground.', 'Hotels and guest houses in Shillong (Police Bazar, Laitumkhrah).', 'Cultured, peaceful, dignified audience; highly respectful.', 'Dancers must not be touched or interrupted; maintain quiet decorum on the spectator grass slopes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('nongkrem-dance-meghalaya', 'Nongkrem Dance Festival', ARRAY['Shad Nongkrem', 'Pomblang Nongkrem']::TEXT[], 'RELIGIOUS_TEMPLE', 'Khasi Religion (Niam Tynrai) / Khyrim State', 'A 5-day ancient royal religious festival of the Hima Khyrim state at Smit, featuring goat sacrifices and royal court dances.', 'Celebrated continuously for centuries at the royal seat of Smit, the traditional capital of the Syiem (King) of Khyrim.', 'Pomblang means goat sacrifice; held to propitiate the supreme goddess Ka Blei Synshar for royal prosperity and good governance.', 'To pray for peace and prosperity for the Khyrim kingdom, rich harvest, and divine protection of the royal lineage.', 'Monarchical dignity, sacred covenant between the king, high priestess, and citizens, and ancestral Khasi ritual preservation.', 'Preserves one of the world''s few surviving functioning constitutional tribal kingdoms with an intact thatched royal palace (Iing Sad).', ARRAY['Pomblang goat sacrifice ceremony conducted by high priests', 'Royal prayer by the Syiem (King) and his High Priestess (Ka Syiem Sad)', 'Procession to the sacred hillock (Lum Pomblang)', 'Unmarried royal princesses performing sacred circle dances']::TEXT[], 'Thousands gather at the iconic thatch-roofed Iing Sad royal palace in Smit; maidens in solid gold crowns dance gracefully before the king.', ARRAY['Ja Doh', 'Doh Khleh (pork salad with onions)', 'Traditional Khasi wild honey cake', 'Kwai (betel nut and leaf)']::TEXT[], 'Heirloom Khasi royal finery: maidens in pure silk Jainsem with heavy gold chains and tiaras; men with silver arrows and feathered turbans.', 'Royal tunes on the Tangmuri oboe, deep booms of the Nakra drums, and bronze gong chimes.', ARRAY['Iing Sad (thatched palace built without a single iron nail)', 'Silver quiver and arrows', 'Gold Pansngiat crown', 'Sacrificial sword']::TEXT[], '5 Days', 'Solar/Autumn Season (Late Autumn)', 'Held annually in November; exact dates proclaimed by the Syiem of Khyrim according to Khasi divination.', 'November', 'COMMUNITY_SPECIFIC', 'Proclaimed by the Syiem of Khyrim for mid-November (usually 2nd or 3rd week)', '2026-11-09 to 2026-11-13', '2027-11-08 to 2027-11-12', 'Hima Khyrim Royal Council & Meghalaya Tourism', ARRAY['Meghalaya']::TEXT[], ARRAY['Smit', 'Shillong']::TEXT[], ARRAY['Iing Sad Royal Palace Grounds, Smit (15 km from Shillong)']::TEXT[], 'Final two days (Thursday & Friday) from 12:00 PM to 4:30 PM for the public royal court dances.', 2, 'Stepping back centuries into a living tribal kingdom: watching royal princesses in ancient gold crowns dance outside an exquisite nail-free thatch palace.', 'Shared taxis and hired cabs from Shillong (35 minutes scenic drive through pine groves to Smit).', 'Hotels in Shillong.', 'High cultural gathering of Khasi elders, royalty, and international researchers.', 'Do not enter the inner sanctum of the Iing Sad palace without royal permission; dress conservatively.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('behdienkhlam-meghalaya', 'Behdienkhlam', ARRAY['Jowai Behdienkhlam', 'Chasing Away the Plague']::TEXT[], 'RELIGIOUS_TEMPLE', 'Pnarr Indigenous Faith (Niamtre)', 'Meghalaya''s most dramatic monsoon festival of the Jaintia people, featuring towering colorful chariots (Roths) submerged in sacred muddy pools.', 'Celebrated since antiquity by the Pnar people in Jowai, West Jaintia Hills, to chase away pestilence following monsoon sowing.', 'Beh means chase, Dien means stick/tree trunk, and Khlam means plague or cholera; divine ritual to cleanse the town of demons.', 'To drive away evil spirits and epidemics, pray for good health, and ensure a rich harvest through divine intervention.', 'Fierce spiritual purification, community defiance of illness, exuberant youth energy, and ritual aquatic revelry.', 'The towering Rot structures, up to 30 feet tall and constructed of bamboo and paper, are masterpieces of indigenous papercraft.', ARRAY['Beating the roofs of houses with long peeled bamboo poles (Khnorknock) to drive away demons', 'Carrying towering colorful Rot structures into the sacred pool (Aitnar)', 'Vigorous dancing and splashing in the muddy water pool', 'Dad-mawliang (traditional football match played with a wooden ball)']::TEXT[], 'Hundreds of young men rush into the sacred Aitnar pool, dancing waist-deep in water while towering paper chariots are ceremonially immersed.', ARRAY['Ja Doh', 'Doh Snam (sausage with blood and pork)', 'Pukhlein sweet bread', 'Ki Kjat (Pnar rice wine)']::TEXT[], 'Men wear traditional dhotis with warm jackets and caps; elders wear ceremonial turbans and silk shawls.', 'Thunderous beats of Ka Bom and Ka Bih drums, blowing of copper horns, and jubilant victory shouts.', ARRAY['Towering 30-ft paper Rot chariot', 'Aitnar sacred muddy pool', 'Deinkhlam round wooden ball', 'Bamboo beating poles']::TEXT[], '4 Days', 'Solar Calendar (Mid-July)', 'Held annually in mid-July following the sowing season in Jowai.', 'July', 'COMMUNITY_SPECIFIC', 'Second or third weekend of July annually', '2026-07-09 to 2026-07-12', '2027-07-08 to 2027-07-11', 'Sein Raij Jowai & West Jaintia Hills District Administration', ARRAY['Meghalaya']::TEXT[], ARRAY['Jowai', 'Shillong']::TEXT[], ARRAY['Aitnar Sacred Pool, Jowai, West Jaintia Hills']::TEXT[], 'Final day (Sunday) from 1:00 PM to 4:30 PM at the Aitnar pool for the dramatic chariot immersion.', 2, 'Unrivaled adrenaline and visual frenzy: watching dozens of 30-foot colorful chariots sway into a cheering sea of thousands dancing in the sacred water.', 'Jowai is 64 km from Shillong (2-hour smooth drive on NH6).', 'Hotels in Jowai town or day-trip from Shillong.', 'Extremely dense, high-energy, electrifying local crowd.', 'Wear waterproof gear and shoes with good grip; do not stand on the slippery edge of the Aitnar pool without assistance.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('autumn-festival-shillong', 'Shillong Autumn Festival', ARRAY['Meghalaya Tourism Autumn Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Contemporary Arts, Tourism & Music', 'A stylish lakeside festival celebrating Meghalaya''s world-famous music scene, craft beers, gastronomy, and adventure sports at Umiam Lake.', 'Founded by Meghalaya Tourism to celebrate the glorious autumn season when skies turn azure and cherry blossoms begin blooming.', 'Conceived to establish Shillong''s reputation as the ''Rock Capital of India'' and showcase creative fashion and culinary arts.', 'To boost autumn tourism, provide a platform for Northeast bands and fashion designers, and celebrate scenic lakefront living.', 'Cosmopolitan creativity, legendary rock guitar riffs, scenic lakeside beauty, and hip youth culture.', 'Shillong is renowned across Asia for its deep rock music heritage and virtuoso guitar culture.', ARRAY['Opening rock concert by international headliners', 'Fashion pageant showcasing Khasi and Garo eri-silk couture', 'Craft brewery and wine tasting exhibitions', 'Water sports regattas on Umiam Lake']::TEXT[], 'Crowds lounge on rolling emerald lawns by the vast lake, listening to live rock and indie bands while savoring gourmet food.', ARRAY['Artisan burgers with local smoked pork', 'Ja Doh', 'Pineapple and strawberry wines', 'Khasi pork momos', 'Assorted artisanal bakery treats']::TEXT[], 'Chic autumn fashion, leather jackets, woollen berets, and stylish handloom Eri silk stoles.', 'High-energy rock, indie pop, blues, acoustic folk, and electronic dance music.', ARRAY['Umiam Lake waters', 'Electric guitar silhouette', 'Pink cherry blossom branch', 'Lakefront stage lights']::TEXT[], '2 to 3 Days', 'Gregorian (Tourism Calendar)', 'Organized during the peak autumn weekend of October or early November.', 'October', 'ORGANIZER_ANNOUNCED', 'Announced by Meghalaya Tourism for late October or early November', '2026-10-24 to 2026-10-25', '2027-10-23 to 2027-10-24', 'Meghalaya Tourism Development Corporation (MTDC)', ARRAY['Meghalaya']::TEXT[], ARRAY['Shillong', 'Umiam']::TEXT[], ARRAY['Umiam Water Sports Complex / Orchid Lake Resort Grounds, Umiam']::TEXT[], 'Late afternoon (3:30 PM) until 10:00 PM for scenic sunset views over Umiam Lake followed by headline music concerts.', 2, 'Pure rock ''n'' roll bliss: listening to roaring electric guitar solos under starry skies with the cool breeze blowing off Umiam Lake.', '15 km north of Shillong on Guwahati-Shillong road (GS Road); shuttle cabs operate from Police Bazar.', 'Ri Kynjai luxury resort at Umiam or hotels in Shillong.', 'Youthful, stylish, music-loving crowd; very safe and cheerful.', 'Carry a warm jacket as temperatures drop quickly after sunset near the lake.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('strawberry-festival-meghalaya', 'Meghalaya Strawberry Festival', ARRAY['Ri Bhoi Strawberry Carnival']::TEXT[], 'HARVEST_SEASONAL', 'Agri-Tourism & Local Farming', 'A delightful springtime agri-tourism festival celebrating the sweet, sun-ripened organic strawberries of Ri Bhoi district.', 'Launched to celebrate Meghalaya''s rapid rise as one of India''s premier high-altitude strawberry producing states.', 'Pioneered by organic farming cooperatives in Sohliya and Syntung villages whose red volcanic soils yield exceptionally sweet berries.', 'To encourage agro-tourism, support rural farming families, and offer travelers hands-on berry-picking experiences.', 'Sweet pastoral joy, community empowerment, organic farming pride, and family-friendly outdoor picnics.', 'Demonstrates how high-value organic horticulture has transformed the livelihoods of thousands of rural Khasi households.', ARRAY['Hands-on strawberry picking in sprawling green berry fields', 'Artisan strawberry wine and jam-making workshops', 'Acoustic open-air jam sessions among berry groves', 'Culinary competitions featuring strawberry pastries']::TEXT[], 'Families and tourists stroll through terraced strawberry patches with wicker baskets, plucking ruby-red fruit in crisp spring sunshine.', ARRAY['Freshly picked strawberries with cream', 'Artisan strawberry wine', 'Strawberry crumbles and tarts', 'Khasi savory pukhlein', 'Smoked meats']::TEXT[], 'Casual picnic outdoor wear, straw hats, and comfortable walking shoes.', 'Acoustic guitars, Khasi folk ballads, and upbeat indie pop.', ARRAY['Ruby-red strawberry', 'Wicker picking basket', 'Terraced pine farm', 'Artisan wine bottle']::TEXT[], '3 Days', 'Gregorian (Harvest Calendar)', 'Held in late March or early April during peak strawberry harvest.', 'April', 'ORGANIZER_ANNOUNCED', 'First weekend of April annually', '2026-04-03 to 2026-04-05', '2027-04-02 to 2027-04-04', 'Department of Agriculture & Meghalaya Tourism', ARRAY['Meghalaya']::TEXT[], ARRAY['Nongpoh', 'Sohliya', 'Umsning']::TEXT[], ARRAY['Sohliya & Syntung Strawberry Villages, Ri Bhoi District']::TEXT[], 'Morning from 9:30 AM to 1:00 PM for the freshest berry plucking in warm morning sun.', 1, 'Idyllic spring day: picking sweet, fragrant strawberries straight from the bush against a backdrop of whispering pine hills.', 'Located 35 km from Shillong on the Guwahati highway; accessible by day taxi.', 'Farm homestays in Sohliya or hotels in Shillong/Nongpoh.', 'Delightful family and nature-lover gathering.', 'Handle strawberry bushes gently; follow farmer guidance when plucking.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ranikor-river-festival-meghalaya', 'Ranikor River Festival', ARRAY['Kynshi Beach and Angling Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Adventure Eco-Tourism & Golden Mahseer Conservation', 'An exotic beach and adventure festival on the emerald waters of the Kynshi River at Ranikor, famous for angling and white sand dunes.', 'Initiated by Meghalaya Tourism to highlight the pristine river ecosystems near the international Bangladesh border.', 'Ranikor is legendary among global anglers as one of the last sanctuaries of the mighty Golden Mahseer fish.', 'To promote catch-and-release sport angling, river conservation, beach camping, and tribal borderland tourism.', 'Unspoiled natural wilderness, thrilling sport fishing, golden beach bonfires, and river sports.', 'The Kynshi River is among the cleanest and most biodiversity-rich rivers in South Asia, cutting through dramatic limestone gorges.', ARRAY['Catch-and-release Golden Mahseer angling competition', 'Kayaking and traditional country boat races', 'Beach volleyball on white river sands', 'Riverside acoustic music concerts around campfires']::TEXT[], 'Travelers camp in luxury safari tents on wide sandbanks, kayak across glass-clear jade waters, and feast on local delicacies.', ARRAY['Fresh river fish cooked in bamboo hollows', 'Khasi Ja Doh', 'Roasted yam and sweet potatoes', 'Smoked pork with bamboo shoots']::TEXT[], 'Casual beachwear, sun protection gear, and warm evening fleece jackets.', 'Acoustic folk, country music, and Khasi guitar melodies echoing off limestone canyon walls.', ARRAY['Golden Mahseer fish', 'Emerald green river water', 'White sand beach', 'Traditional dugout canoe']::TEXT[], '2 Days', 'Gregorian (Tourism Calendar)', 'Held during the warm, sunny dry season of February or early March.', 'February', 'ORGANIZER_ANNOUNCED', 'Last weekend of February annually', '2026-02-27 to 2026-02-28', '2027-02-26 to 2027-02-27', 'South West Khasi Hills District Administration & Meghalaya Tourism', ARRAY['Meghalaya']::TEXT[], ARRAY['Ranikor', 'Mawkyrwat', 'Shillong']::TEXT[], ARRAY['Ranikor Beach along the Kynshi River, South West Khasi Hills']::TEXT[], 'Early morning 6:30 AM for mist-covered river angling; late afternoon for sunset kayaking.', 2, 'Unbelievable natural paradise: paddling a kayak on emerald jade water so clear you can see river pebbles 20 feet below.', 'Ranikor is 115 km from Shillong (4 hours through dramatic mountain terrain via Mawkyrwat); 4WD SUV recommended.', 'Riverside tent camps and inspection bungalow in Ranikor.', 'Adventure travelers, anglers, and nature enthusiasts; peaceful and uncrowded.', 'Catch-and-release fishing rules are strictly enforced; carry all plastic waste back.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('bob-dylan-tribute-shillong', 'Bob Dylan Birthday Tribute Shillong', ARRAY['Lou Majaw Dylan Fest']::TEXT[], 'MUSIC_DANCE_ARTS', 'Rock Music Culture & Global Acoustic Poetry', 'Shillong''s legendary musical tradition founded by rocker Lou Majaw, celebrating Bob Dylan''s birthday with day-long acoustic and rock concerts.', 'Founded in 1972 by Indian rock icon Lou Majaw, who has celebrated Bob Dylan''s birthday on May 24 without interruption for over 50 years.', 'Born out of Lou Majaw''s personal reverence for Bob Dylan''s poetry, lyrics, and humanitarian message of peace and freedom.', 'To celebrate the timeless poetry of Bob Dylan, unite generations of music lovers, and celebrate Shillong''s unquenchable rock soul.', 'Unpretentious rock ''n'' roll joy, bohemian freedom, poetic camaraderie, and ageless youthful spirit.', 'Recognized globally by music historians and journalists as one of the world''s most enduring, genuine musical tributes.', ARRAY['Morning poetry recitals of Dylan lyrics', 'Lou Majaw performing in his trademark denim shorts and boots', 'Generations of musicians jamming Dylan classics', 'Cutting the ceremonial birthday cake']::TEXT[], 'Musicians of all ages gather at iconic cafes and open-air venues, singing ''Blowin'' in the Wind'' and ''Like a Rolling Stone'' into the night.', ARRAY['Shillong pork momos', 'Ginger tea and cookies', 'Khasi Ja Doh', 'Local draft beer']::TEXT[], 'Vintage denim jackets, graphic music tees, leather boots, and rock festival casuals.', 'Legendary Dylan songs rendered in acoustic, blues, hard rock, and reggae styles.', ARRAY['Acoustic guitar and harmonica rack', 'Denim jacket', 'Peace sign', 'Shillong pine tree']::TEXT[], '1 Day', 'Solar Calendar (Fixed Date)', 'Celebrated strictly on May 24 every year, marking Bob Dylan''s birthday.', 'May', 'FIXED', 'May 24 annually', '2026-05-24', '2027-05-24', 'Lou Majaw Foundation & Shillong Music Community', ARRAY['Meghalaya']::TEXT[], ARRAY['Shillong']::TEXT[], ARRAY['Cafes and concert halls across Shillong (e.g., Cloud 9, Cafe Shillong, State Central Library)']::TEXT[], '5:00 PM to 10:00 PM when Lou Majaw and his band take the stage for the main headline set.', 1, 'Pure, infectious musical joy: watching legendary 78-year-old rocker Lou Majaw leap across the stage singing Dylan with roaring crowds.', 'Taxis within Shillong city.', 'Hotels and guest houses in Shillong.', 'Music lovers, artists, travelers, and friendly locals.', 'Sing along to your heart''s content; celebrate with peace and love.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('chapchar-kut-mizoram', 'Chapchar Kut', ARRAY['Mizo Spring Festival', 'Grand Bamboo Dance Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mizo Indigenous Heritage & Cultural Union', 'Mizoram''s grandest, most colorful spring carnival celebrating the completion of jungle clearing with the world-famous Cheraw bamboo dance.', 'Celebrated since antiquity by the Mizo people after clearing hill forests for jhum cultivation and waiting for the slash to dry under the March sun.', 'Chapchar refers to the drying of felled bamboo and trees (Chap); Kut means festival. A joyous holiday of feasting before burning fields.', 'To give thanks for safe clearing of forests, enjoy leisure before cultivation, celebrate Mizo unity, and dance in colorful traditional attire.', 'Incomparable aesthetic harmony, unity under ''Tlawmngaihna'' (Mizo moral code of selflessness), joyful music, and breathtaking synchronized dance.', 'The Cheraw bamboo dance performed by thousands of dancers at AR Ground Aizawl holds the Guinness World Record for the largest bamboo dance.', ARRAY['Ceremonial opening prayer by the state''s cultural elders', 'Mass Cheraw dance where thousands of bamboo poles clack in rhythm', 'Khai-chawi-zawn (parade of traditional Mizo heroes and heroines)', 'Public feast showcasing ancient Mizo cuisine']::TEXT[], 'The entire capital of Aizawl erupts in joyful colors; women in striking Puan skirts and headdresses perform graceful synchronized leaps between clacking poles.', ARRAY['Bai (pork stew with mustard leaves and bamboo shoots)', 'Sawhchiar (flavorful chicken and rice porridge)', 'Chhangban (sticky rice cakes)', 'Smoked beef with local chilies']::TEXT[], 'Stunning traditional Mizo attire: women wear Puanchei wrap skirts with vivid geometric patterns and Vakiria headbands made of parrot feathers and brass; men wear white dhotis with red-bordered shawls.', 'Rhythmic clacking of long green bamboo poles, beating of brass gongs (Dar), Khuang drums, and modern four-part Mizo gospel choir harmonies.', ARRAY['Cheraw green bamboo poles', 'Vakiria parrot-feather headdress', 'Puanchei geometric skirt', 'Khuang drum']::TEXT[], '2 Days (main day first Friday of March)', 'Solar Calendar (First Friday of March)', 'Celebrated on the first Friday of March annually as a gazetted public holiday across Mizoram.', 'March', 'FIXED', 'First Friday of March annually', '2026-03-06', '2027-03-05', 'Central Chapchar Kut Committee & Mizoram Tourism', ARRAY['Mizoram']::TEXT[], ARRAY['Aizawl', 'Lunglei', 'Champhai']::TEXT[], ARRAY['Assam Rifles Ground (Lammual), Aizawl']::TEXT[], '9:30 AM to 2:30 PM at AR Ground Lammual for the mass Cheraw bamboo dance and grand cultural parade.', 2, 'One of the most photogenic cultural sights in the world: thousands of dancers in vivid geometric silks leaping with pinpoint agility between rhythmic bamboo poles.', 'Lengpui Airport connects Aizawl to Kolkata and Guwahati; city taxis in Aizawl; traffic is strictly disciplined.', 'Hotels and guest houses in Aizawl (Zarkawt, Chanmari, Treasury Square).', 'Exemplary discipline: tens of thousands fill the stadium without any pushing or disorder; remarkably clean and welcoming.', 'Mizo society values quiet courtesy and order; do not litter; remove footwear if entering performance areas.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('mim-kut-mizoram', 'Mim Kut', ARRAY['Mizo Maize Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mizo Ancestral Tradition', 'A solemn autumn harvest festival dedicated to the maize harvest and paying homage to departed ancestors.', 'Celebrated for centuries after the harvesting of maize (Mim), the first crop to ripen before the main rice harvest.', 'Rooted in the ancient mythological love story of a husband visiting the underworld of the dead (Mithi Khua) to bring food to his departed wife.', 'To offer first-fruits of the maize harvest to departed ancestors and express grief, gratitude, and remembrance.', 'Poignant remembrance, familial love spanning beyond death, quiet gratitude, and sharing of seasonal bounty.', 'Demonstrates ancient Mizo beliefs in life after death and ancestral communion prior to 19th-century Christianization.', ARRAY['Offering of freshly boiled maize and beer on family tables for the spirits', 'Ceremonial consumption of bread made from fresh corn', 'Traditional lamentation ballads sung by village elders', 'Community feasts uniting neighboring clans']::TEXT[], 'Families gather quietly to honor departed relatives, prepare special sweet corn dishes, and share meals with neighbors.', ARRAY['Fresh boiled sweet maize', 'Chhangban (cornmeal and sticky rice cake)', 'Bai', 'Smoked meat broth']::TEXT[], 'Simple traditional handwoven Puan shawls in subdued elegant tones.', 'Solemn Mizo folk ballads, soft gong chimes, and acoustic guitar accompaniments.', ARRAY['Golden maize cob', 'Mizo ancestral bowl', 'Khuang drum', 'Smouldering autumn hearth']::TEXT[], '2 Days', 'Solar/Autumn Season (August/September)', 'Observed in August or September following the harvesting of the maize crop.', 'September', 'COMMUNITY_SPECIFIC', 'First week of September annually', '2026-09-04 to 2026-09-05', '2027-09-03 to 2027-09-04', 'Mizo Cultural Association & Mizoram Tourism', ARRAY['Mizoram']::TEXT[], ARRAY['Aizawl', 'Serchhip', 'Champhai']::TEXT[], ARRAY['Community halls and villages across Mizoram']::TEXT[], 'Evening when families gather for quiet musical remembrance sessions.', 1, 'A moving, gentle cultural encounter experiencing the deep soulfulness and poetic introspection of the Mizo people.', 'Taxis and shared sumos across Mizoram.', 'Hotels in Aizawl or tourist lodges in Champhai.', 'Intimate, tranquil family environment.', 'Maintain respectful silence during prayer and remembrance moments.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('pawl-kut-mizoram', 'Pawl Kut', ARRAY['Mizo Post-Harvest Children''s Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mizo Traditional Heritage', 'A joyful 2-day winter festival celebrating the completion of the main rice harvest, focused on children and family feasts.', 'Celebrated when the rice harvest (Pawl = straw) is completed and safely stored inside village granaries.', 'Historically followed three years of severe famine (Thingpui Tam); instituted as a joyful thanksgiving for surviving winter.', 'To celebrate the successful gathering of grain, pamper children with treats, and celebrate family happiness.', 'Parental affection, joyful feasting, gratitude for surviving hardships, and community solidarity.', 'Highlights the supreme value placed on family welfare, children, and social insurance in traditional Mizo villages.', ARRAY['Chawnghnawt (children being specially seated and fed choice morsels of meat and eggs by their mothers)', 'Grand community feast where youths cook for the entire village', 'Traditional games including spinning tops and wrestling', 'Folk dances in the village square']::TEXT[], 'Children wear their finest clothes and sit on raised platforms while parents feed them; families feast and dance together.', ARRAY['Sawhchiar', 'Bai', 'Boiled chicken and eggs', 'Chhangban', 'Smoked pork with local beans']::TEXT[], 'Colorful handwoven Puan wrap skirts, bright children''s sweaters, and traditional woven sashes.', 'Lively Mizo children''s songs, Khuang drumming, and joyful acoustic guitar tunes.', ARRAY['Golden straw sheaves (Pawl)', 'Mother feeding child (Chawnghnawt)', 'Granary full of rice', 'Brass gong']::TEXT[], '2 Days', 'Solar Calendar (December Window)', 'Observed in December after the winter paddy harvest, often integrating into Christmas season celebrations.', 'December', 'FIXED', 'First weekend of December annually', '2026-12-04 to 2026-12-05', '2027-12-03 to 2027-12-04', 'Department of Art & Culture, Government of Mizoram', ARRAY['Mizoram']::TEXT[], ARRAY['Aizawl', 'Champhai', 'Lunglei']::TEXT[], ARRAY['Vanapa Hall Aizawl & rural village squares across Mizoram']::TEXT[], 'Afternoon when the heartwarming Chawnghnawt child-feeding rituals take place.', 2, 'Heartwarming family celebration filled with the laughter of children dressed in vibrant handwoven silks being lovingly fed choice delicacies.', 'Aizawl city cabs; sumos for outstation travel.', 'Hotels in Aizawl.', 'Delightful family and community atmosphere.', 'Compliment the traditional Puan handlooms worn by families; ask politely before photographing children.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('thalfavang-kut-mizoram', 'Thalfavang Kut', ARRAY['Mizo Pre-Harvest Weeding Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mizo Traditional Culture', 'A vibrant cultural festival held in November after weeding the autumn fields, showcasing folk dances and tourism.', 'Initiated in its modern tourism format to preserve ancestral customs and showcase Mizo dance forms to the outside world.', 'Historically observed when weeding of the paddy crops was accomplished, giving farmers a brief rest before the winter harvest.', 'To celebrate progress in farming, showcase the rich variety of Mizo dances (Cheraw, Khuallam, Chheihlam), and promote tourism.', 'Artistic expression, scenic mountain beauty, athletic grace, and welcoming warmth.', 'Presents the complete spectrum of Mizo folk dances, each representing historical migrations, hunts, and social bonds.', ARRAY['Khuallam dance (dance of guests performed by travelers entering a village)', 'Chheihlam dance (joyful dance accompanied by rhythmic clapping and drum beats)', 'Cheraw bamboo dance performances', 'Exhibition of traditional cane and bamboo handicrafts']::TEXT[], 'Dancers in traditional costumes gather on mountain ridges, moving in intricate geometric formations under the crisp autumn sun.', ARRAY['Sawhchiar', 'Bai with fermented pork', 'Smoked beef with fiery Mizo bird''s eye chilies', 'Rice cakes']::TEXT[], 'Men wear white Puan with black-and-red striped borders; women wear striking Puanchei and Kawrchei embroidered blouses.', 'Synchronized beating of Khuang drums, clanging of Dar gongs, bamboo rhythm sticks, and melodious folk choruses.', ARRAY['Khuallam guest shawl', 'Carved bamboo flagon', 'Khuang drum', 'Rolling blue mountain ridges']::TEXT[], '2 Days', 'Solar Calendar (November Window)', 'Celebrated during the second or third week of November annually.', 'November', 'ORGANIZER_ANNOUNCED', 'Announced by Mizoram Tourism for mid-November', '2026-11-13 to 2026-11-14', '2027-11-12 to 2027-11-13', 'Mizoram Tourism Development Authority', ARRAY['Mizoram']::TEXT[], ARRAY['Aizawl']::TEXT[], ARRAY['Aizawl Peace Ground & Falkawn Model Village']::TEXT[], '10:00 AM to 3:00 PM at Falkawn Model Village for traditional dance showcases.', 2, 'Discovering authentic traditional Mizo village life, watching graceful dances against breathtaking panoramas of rolling blue hills.', 'Falkawn is 18 km south of Aizawl; hired taxis available in town.', 'Hotels in Aizawl.', 'Pleasant, friendly, cultural audience.', 'Enjoy the performances seated; applaud with genuine warmth.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('anthurium-festival-mizoram', 'Anthurium Festival', ARRAY['Reiek Anthurium Tourism Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Horticulture, Music & Eco-Tourism', 'A spectacular floriculture and tourism festival held at the misty base of Reiek Mountain amidst thousands of blooming red anthuriums.', 'Launched by the Government of Mizoram to celebrate the booming anthurium floriculture industry led primarily by women farmers.', 'Mizoram''s sub-tropical mountain climate produces some of the world''s most prized export-quality anthurium flowers.', 'To promote floriculture, support rural women entrepreneurs, and showcase Mizo rock, folk, and culinary arts at scenic Reiek.', 'Vibrant floral beauty, empowerment of women growers, misty mountain adventure, and high-energy music.', 'Mizoram is India''s leading anthurium-exporting state, shipping blooms to Japan, Singapore, and Europe.', ARRAY['Anthurium flower competition judging exotic varieties', 'Trekking to the dizzying Reiek cliff summit', 'Traditional costume fashion shows', 'Night rock and acoustic concerts']::TEXT[], 'Reiek tourist village is transformed into a sea of scarlet and white anthuriums; travelers hike misty cliffs and attend concerts.', ARRAY['Mizo bamboo-cooked chicken', 'Bai with local forest greens', 'Freshly baked mountain bread', 'Aizawl street food snacks']::TEXT[], 'Outdoor trekking gear by day, vibrant Mizo handlooms and rock-band hoodies by night.', 'Northeast indie rock, Mizo gospel pop, acoustic folk, and traditional Khuang drumming.', ARRAY['Scarlet Anthurium blossom', 'Reiek precipice rock cliff', 'Mizo cane basket', 'Trekking boot']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized in late September or early October when anthuriums reach peak bloom.', 'September', 'ORGANIZER_ANNOUNCED', 'Last weekend of September annually', '2026-09-25 to 2026-09-27', '2027-09-24 to 2027-09-26', 'Tourism Department, Government of Mizoram', ARRAY['Mizoram']::TEXT[], ARRAY['Aizawl', 'Reiek']::TEXT[], ARRAY['Reiek Tourist Resort Grounds, Reiek Tlang (30 km from Aizawl)']::TEXT[], 'Morning trek to the breathtaking Reiek cliff summit followed by afternoon flower exhibitions.', 2, 'Standing atop the sheer vertical cliff of Reiek peering down into vast misty valleys, surrounded by vibrant scarlet anthuriums and live acoustic music.', 'Reiek is a 1-hour scenic mountain drive from Aizawl; taxis and shared cabs available.', 'Reiek Tourist Resort cottages or hotels in Aizawl.', 'Youthful, outdoorsy, family-friendly.', 'Stay behind safety railings on the Reiek cliff summit; do not pluck blooming anthurium flowers.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('lyuva-khutla-mizoram', 'Lyuva Khutla', ARRAY['Mara Post-Harvest Festival']::TEXT[], 'HARVEST_SEASONAL', 'Mara Autonomous Tribe Tradition', 'The grandest cultural festival of the Mara people of southern Mizoram, celebrating harvest completion with the Awkhachipa dance.', 'Celebrated by the Mara people inhabiting the southernmost tip of Mizoram in the Mara Autonomous District Council (Siaha).', 'Lyuva means field labor; Khutla means festival. Marks the joyous conclusion of jhum cultivation in the remote southern hills.', 'To give thanks to the almighty for a rich harvest, preserve distinctive Mara language and music, and promote inter-tribal peace.', 'Distinctive Mara cultural pride, fierce vitality, joyful feasting, and dazzling tribal headwear.', 'The Mara community preserves distinct customs, linguistic roots, and social structures within their autonomous district council.', ARRAY['Ceremonial prayer of thanksgiving by Mara church and cultural elders', 'The spectacular Awkhachipa bamboo dance performed at frantic speeds', 'Traditional wrestling and stone-lifting games', 'Grand community feast featuring traditional smoked meats']::TEXT[], 'Siaha town turns into a spectacle of color; dancers in unique Mara headdresses leap between poles, followed by community feasting.', ARRAY['Mara smoked pork with bamboo shoot', 'Boiled chicken with indigenous herbs', 'Sawhchiar', 'Steamed rice cakes']::TEXT[], 'Exquisite Mara traditional attire: women wear Rhaphi and Zeikao handlooms adorned with cowrie shells and silver ornaments; men wear striking woven jackets.', 'Thunderous beats of hollowed wooden drums, brass gongs, and unique Mara polyphonic ballads.', ARRAY['Awkhachipa bamboo poles', 'Mara cowrie-trimmed shawl', 'Siaha mountain ridge', 'Palak Lake lotus']::TEXT[], '3 Days', 'Solar Calendar (March Window)', 'Celebrated annually during the third week of March in Siaha.', 'March', 'FIXED', 'Third Tuesday to Thursday of March annually', '2026-03-17 to 2026-03-19', '2027-03-16 to 2027-03-18', 'Mara Autonomous District Council (MADC) & Mizoram Tourism', ARRAY['Mizoram']::TEXT[], ARRAY['Siaha']::TEXT[], ARRAY['Siaha Town Ground, Mara Autonomous District']::TEXT[], 'Midday for the electrifying Awkhachipa bamboo dance performances.', 2, 'Off-the-beaten-track adventure to Mizoram''s deep south: experiencing the distinct, vibrant folklore of the Mara tribe near Palak Lake.', 'Siaha is 300 km south of Aizawl (10 to 11-hour mountain drive by sumo); helicopter service operates on select days.', 'Tourist lodge and local homestays in Siaha town.', 'Warm, vibrant, enthusiastic tribal community gathering.', 'Respect local Mara customs; greet elders with warmth and humility.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('losar-festival-sikkim', 'Sikkimese Losar', ARRAY['Tibetan & Bhutia New Year']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tibetan Buddhism (Nyingma & Kagyu)', 'The grand Buddhist New Year celebrated with monastery butter lamps, prayer flags, family banquets, and Cham sacred dances across Sikkim.', 'Celebrated for centuries by the Bhutia, Sherpa, and Tibetan Buddhist communities of Sikkim, intertwining with royal Namgyal history.', 'Commemorates the triumph of light over dark, marked by the arrival of the first day of the first lunar month.', 'To cleanse the sins and misfortunes of the old year, welcome divine fortune, and pray for the longevity of all living beings.', 'Deep spiritual renewal, loving family reunion, monastic grandeur, and mountain serenity.', 'Rumtek and Enchey monasteries host ancient monastic Cham dances that survived the Chinese annexation of Tibet.', ARRAY['Consuming Guthuk noodle soup on the 29th day of the 12th month for symbolic cleansing', 'Erecting Lungta prayer flags on mountain tops', 'Butter lamp offerings at Rumtek and Pemayangtse monasteries', 'Visiting elders with Khata silk scarves']::TEXT[], 'Homes are decorated with auspicious eight symbols; families in silk robes share Khapse pastries and visit monasteries.', ARRAY['Guthuk (nine-ingredient noodle soup with fortune dumplings)', 'Khapse (twisted fried pastries)', 'Yak butter tea (Suja)', 'Steamed momos with chili dip', 'Chhang (fermented millet beer in bamboo tubes)']::TEXT[], 'Bhutia Bakhu silk robes tied with Hanju blouses and gold-embroidered Kera sashes; married women wear dazzling striped Pangden aprons.', 'Resonant monastic Dungchen horns, Gyaling oboes, beating of temple drums, and soft acoustic damyan lute songs.', ARRAY['Ashtamangala (Eight Auspicious Symbols)', 'Khata white silk scarf', 'Butter lamp', 'Lungta prayer flags on snowy pass']::TEXT[], '15 Days (first 3 days are primary)', 'Tibetan Lunar Calendar (First month, day 1)', 'Calculated using the Tibetan lunisolar calendar; occurs between late January and early March.', 'February', 'LUNAR', 'First day of the first Tibetan lunar month', '2026-02-18 to 2026-02-20', '2027-02-07 to 2027-02-09', 'Ecclesiastical Affairs Department, Govt of Sikkim & Rumtek Monastery', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok', 'Pelling', 'Ravangla', 'Rumtek']::TEXT[], ARRAY['Rumtek Dharma Chakra Centre', 'Enchey Monastery Gangtok', 'Pemayangtse Monastery Pelling']::TEXT[], 'Morning of Day 1 for family prayer and butter lamp offerings, Day 2 for monastery visits.', 4, 'A Himalayan wonderland of peace: fluttering windhorse flags against the snows of Kanchenjunga while monks sound ancient alpine horns.', 'Fly to Pakyong Airport or Bagdogra (4.5 hours drive to Gangtok); shared cabs and private taxis.', 'Hotels across Gangtok (MG Marg, Paljor Stadium road) or heritage resorts in Pelling.', 'Serene, dignified, family and monastic environment.', 'Offer Khata silk scarves with both hands palms up; always circumambulate Buddhist shrines in a clockwise direction.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('saga-dawa-sikkim', 'Saga Dawa', ARRAY['Triple Blessed Day', 'Sikkim Buddha Purnima']::TEXT[], 'RELIGIOUS_TEMPLE', 'Mahayana Buddhism', 'The holiest Buddhist festival in Sikkim commemorating the Birth, Enlightenment, and Parinirvana of Gautama Buddha with sacred processions.', 'Celebrated across the Mahayana Buddhist world for over two millennia; in Sikkim, celebrated with immense state-wide reverence.', 'Saga Dawa is the fourth month of the Tibetan lunar calendar; the full moon day marks all three milestone events of Lord Buddha''s life.', 'To accumulate extraordinary spiritual merit (merits are believed to multiply 100,000 times during Saga Dawa) through charity and prayer.', 'Supreme compassion, non-violence, accumulation of spiritual merit, meditation, and world peace.', 'The holy procession carrying the 108 volumes of the sacred Kangyur scriptures through the streets of Gangtok is an iconic cultural institution.', ARRAY['Lighting thousands of butter lamps in monasteries', 'Procession carrying 108 volumes of Kangyur scriptures across Gangtok', 'Strict vegetarianism and releasing captured fish or animals (Tsethar)', 'Monks chanting the Prajnaparamita sutras']::TEXT[], 'Monks and thousands of devotees in white robes walk silently through Gangtok carrying sacred texts on their heads, spinning prayer wheels.', ARRAY['Strictly vegetarian and sattvic meals', 'Khichuri', 'Vegetable thukpa and tingmo', 'Butter tea (Suja)']::TEXT[], 'Pure traditional Bhutia, Lepcha, and Tibetan attire, predominantly in pristine white and golden silks.', 'Deep rhythmic chanting of ''Om Mani Padme Hum'', ringing of handheld prayer bells, and low-drone monastic horns.', ARRAY['Lotus flower', '108 volumes of Kangyur', 'Dharma Wheel (Dharmachakra)', 'Butter lamp ocean']::TEXT[], '1 Month (peak ceremonies on Full Moon day)', 'Tibetan Lunar Calendar (4th month, 15th day)', 'Falls on the full moon day of the fourth Tibetan lunar month (May/June).', 'May', 'LUNAR', 'Full moon of the fourth Tibetan lunar month', '2026-05-31', '2027-05-20', 'Ecclesiastical Affairs Department, Govt of Sikkim', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok', 'Pelling', 'Yuksom']::TEXT[], ARRAY['Tsuklakhang Royal Palace Monastery Gangtok', 'Rumtek Monastery', 'Tashiding Monastery']::TEXT[], 'Early morning 7:30 AM for the Kangyur scripture street procession starting from Tsuklakhang Palace Monastery in Gangtok.', 2, 'Deeply peaceful, meditative experience: walking alongside thousands of serene devotees carrying sacred scriptures on their heads through the misty streets.', 'Gangtok city cabs; roads along the procession route are pedestrianized during morning hours.', 'Hotels around MG Marg, Gangtok.', 'Deeply devoted, peaceful, dignified crowd.', 'Observe strict vegetarianism on this day; do not walk between a devotee and their prayer wheel.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('pang-lhabsol-sikkim', 'Pang Lhabsol', ARRAY['Kanchenjunga Reverence Festival', 'Blood Brotherhood Commemoration']::TEXT[], 'RELIGIOUS_TEMPLE', 'Sikkimese Buddhism & Indigenous Lore', 'A uniquely Sikkimese festival honoring Mount Kanchenjunga as the guardian deity, featuring the thrilling Warrior Dance (Pangtoed Cham).', 'Introduced by the third Chogyal of Sikkim, Chakdor Namgyal, in the early 18th century, celebrating the historic treaty between Lepchas and Bhutias.', 'Commemorates the blood brotherhood treaty signed at Kabi Lungchok in the 13th century between the Lepcha chief Thekong Tek and Bhutia prince Khye Bumsa.', 'To honor Mount Kanchenjunga for protecting Sikkim, invoke peace and prosperity, and celebrate the unity of all Sikkimese ethnic groups.', 'Heroic warrior valor, mountain mysticism, solemn blood oaths, and harmonious inter-ethnic brotherhood.', 'Features the rare Pangtoed Cham dance where dancers represent warrior attendants of the mountain god, brandishing gleaming swords.', ARRAY['Performing the martial Pangtoed Cham dance with real swords and shields', 'Ritual invocation of Mount Kanchenjunga (Dzonga) and Mount Yalapshing', 'Offerings at the historic blood brotherhood site of Kabi Lungchok', 'State prayers for the preservation of Sikkim''s environment']::TEXT[], 'Monks and warrior dancers in blazing red-and-gold armor leap across the Tsuklakhang courtyard, watched by thousands including state dignitaries.', ARRAY['Traditional Sikkimese vegetarian feast', 'Tibetan bread (Balep)', 'Suja (butter tea)', 'Steamed vegetable dumplings']::TEXT[], 'Dramatic warrior attire: helmets with peacock plumes, red silk tunics, chainmail chest armor, and long curved swords.', 'Thrilling battle rhythms: rapid drumming on big Nga drums, crashing cymbals, piercing Gyaling blasts, and heroic warrior shouts.', ARRAY['Mount Kanchenjunga snowy silhouette', 'Warrior sword and shield', 'Red Mahakala mask', 'Kabi Lungchok treaty stone']::TEXT[], '1 Day', 'Tibetan Lunar Calendar (7th month, 15th day)', 'Celebrated on the 15th day of the seventh Tibetan lunar month (August/September).', 'September', 'LUNAR', '15th day of the 7th Tibetan lunar month', '2026-08-27', '2027-09-15', 'Ecclesiastical Affairs Department, Govt of Sikkim & Tsuklakhang Trust', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok', 'Kabi Lungchok']::TEXT[], ARRAY['Tsuklakhang Royal Chapel Courtyard, Gangtok', 'Kabi Lungchok sacred grove']::TEXT[], '9:30 AM to 1:30 PM at Tsuklakhang Royal Chapel for the extraordinary Pangtoed Cham warrior sword dance.', 2, 'Unmatched Himalayan drama: watching fierce warrior dancers in red armor perform acrobatic leaps with flashing swords against the backdrop of Kanchenjunga.', 'Accessible in central Gangtok; local taxis to Tsuklakhang palace.', 'Hotels in Gangtok.', 'High-profile state and cultural audience; orderly and respectful.', 'Maintain silence during the sword dance; avoid standing in front of invited royal and monastic dignitaries.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('bumchu-festival-sikkim', 'Bumchu Festival', ARRAY['Tashiding Sacred Water Vase Ceremony']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tibetan Buddhism (Nyingma Tradition)', 'A miraculous holy water vase festival at sacred Tashiding Monastery predicting the annual destiny and fortunes of Sikkim.', 'Originated in the 8th century when Guru Padmasambhava consecrated the sacred vase (Bum) during his consecration of Sikkim (Beyul Demazong).', 'Bum means pot or vase, and Chu means water; holy water sealed in an ancient urn is measured to divine the future of the land.', 'To receive drops of the blessed miraculous water, foretell the year''s peace, prosperity, or calamities, and attain spiritual liberation.', 'Miraculous faith, profound pilgrimage, sacred divination, and spiritual purification in the mountain heartland.', 'Tashiding is the spiritual navel of Sikkim; the water level in the unsealed vase is believed to predict rains, crops, and state tranquility.', ARRAY['Unsealing the sacred urn at midnight by high lamas', 'Measuring the depth and clarity of the holy water to divine the annual omen', 'Distributing drops of the sacred water to hundreds of thousands of waiting pilgrims', 'Resealing the vase with fresh river water for the next year']::TEXT[], 'Hundreds of thousands of pilgrims brave freezing mountain passes, camping under stars along the Tashiding ridge waiting for their sip of holy water.', ARRAY['Simple monastery khichuri', 'Hot butter tea (Suja)', 'Steamed tingmo buns', 'Warm noodle soup']::TEXT[], 'Pilgrims in heavy winter woollen Bakhu robes, down jackets, woollen mufflers, and sturdy trekking shoes.', 'Continuous chanting of the Padmasambhava mantra ''Om Ah Hum Vajra Guru Padma Siddhi Hum'' echoing over mountain ridges.', ARRAY['Sacred Bumchu water urn', 'Tashiding Chorten', 'Guru Padmasambhava statue', 'Conch shell']::TEXT[], '2 Days', 'Tibetan Lunar Calendar (1st month, 14th-15th days)', 'Falls on the 14th and 15th days of the first Tibetan lunar month (February/March).', 'March', 'LUNAR', '14th and 15th days of the first Tibetan lunar month', '2026-03-03 to 2026-03-04', '2027-02-21 to 2027-02-22', 'Tashiding Monastery Council & Ecclesiastical Department Govt of Sikkim', ARRAY['Sikkim']::TEXT[], ARRAY['Tashiding', 'Pelling', 'Yuksom', 'Gyalshing']::TEXT[], ARRAY['Tashiding Monastery atop sacred hill between Rathong and Rangeet rivers, West Sikkim']::TEXT[], 'Midnight of the 14th lunar day when the sacred vase is officially unsealed by high lamas.', 3, 'One of the most extraordinary spiritual pilgrimages in Asia: joining thousands of devout mountain people under starry skies atop a sacred ridge.', 'Shared sumos or private SUVs from Pelling or Geyzing; 4WD vehicle recommended for the final steep climb.', 'Basic pilgrim homestays and tent camps in Tashiding village; advance booking essential.', 'Enormous crowd of pilgrims from Sikkim, Bhutan, Nepal, and Ladakh; patient, peaceful, and devoted.', 'Stand patiently in the darshan queue; receive the holy water drops in the palm of your right hand supported by your left.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('losoong-namsoong-sikkim', 'Losoong / Namsoong', ARRAY['Sikkimese Farmers New Year', 'Bhutia & Lepcha New Year']::TEXT[], 'HARVEST_SEASONAL', 'Bhutia & Lepcha Indigenous Traditions / Buddhism', 'The festive New Year carnival of the Bhutia and Lepcha farmers celebrating the end of the harvest with monastic Cham dances and archery.', 'Celebrated for centuries at the end of the 10th Tibetan lunar month, marking the conclusion of agricultural labor.', 'Losoong (Bhutia) and Namsoong (Lepcha) mark the moment when farmers celebrate filled granaries and pray for the new year.', 'To rejoice in the fruits of harvest, drive away evil spirits of the departing year, and celebrate with archery competitions.', 'Agricultural triumph, relaxation after hard labor, monastic mask dancing, and community archery merriment.', 'Phodong, Rumtek, and Enchey monasteries perform legendary Black Hat and deity mask dances during Losoong.', ARRAY['Performing Chaam dances by lamas depicting the subjugation of evil forces', 'Archery competitions between villages', 'Lighting sacred bonfires to purge misfortune', 'Feasting with home-brewed Chhang']::TEXT[], 'Villagers don their finest traditional silk dresses; monasteries resonate with the boom of long trumpets while archery arrows fly in contests.', ARRAY['Gya Thuk (noodle soup)', 'Steamed pork and cheese momos', 'Balep bread', 'Pork cooked with radish', 'Chhang (warm millet beer)']::TEXT[], 'Bhutias wear vibrant silk Bakhu and Honju; Lepchas wear authentic handwoven Dumvum and Dum-pra with woven bamboo hats.', 'Melodious Lepcha flutes, traditional archery cheering choruses, and monastic cymbals and trumpets.', ARRAY['Archery target and arrow', 'Monastic Cham mask', 'Chhang bamboo mug (Pipcha)', 'Granary sheaf']::TEXT[], '5 to 7 Days', 'Tibetan Lunar Calendar (10th month, 28th-29th days)', 'Falls at the end of the tenth Tibetan lunar month (December).', 'December', 'LUNAR', '28th day of the 10th Tibetan lunar month', '2026-12-08 to 2026-12-14', '2027-12-27 to 2028-01-02', 'Ecclesiastical Affairs Department & Tourism Dept, Govt of Sikkim', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok', 'Phodong', 'Rumtek', 'Mangan']::TEXT[], ARRAY['Phodong Monastery, North Sikkim', 'Enchey Monastery Gangtok', 'Rumtek Monastery']::TEXT[], 'Morning 9:30 AM to 1:30 PM at Phodong Monastery for the most authentic Black Hat Cham dances.', 3, 'Pure winter mountain magic: watching masked lamas spin against snow-capped peaks followed by sampling warm, bubbly millet beer with village archers.', 'Shared sumos and private taxis from Gangtok to Phodong (1 hour) or Rumtek (45 minutes).', 'Hotels in Gangtok.', 'Joyful, welcoming mix of monks, village elders, and travelers.', 'Do not enter the archery shooting line; dress warmly against winter mountain chill.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('tendong-lho-rum-faat-sikkim', 'Tendong Lho Rum Faat', ARRAY['Lepcha Mount Tendong Worship Festival']::TEXT[], 'HARVEST_SEASONAL', 'Lepcha Indigenous Faith (Mun & Bongthingism)', 'An ancient indigenous festival of the Lepcha people paying homage to sacred Mount Tendong, which saved their ancestors from a great deluge.', 'Rooted in the ancient mythological deluge legend of the Lepcha people, the original indigenous inhabitants of Sikkim (Mayel Lyang).', 'According to Lepcha lore, when cosmic waters submerged the earth, Mount Tendong (''the raised horn'') miraculously rose above the flood to save humanity.', 'To offer prayers of gratitude to Mount Tendong, preserve ancestral Lepcha animist identity, and pray for world peace.', 'Indigenous pride, environmental reverence, profound respect for mountain ecology, and communal thanksgiving.', 'The Lepchas are recognized as the aboriginal inhabitants of Sikkim with an encyclopedic botanical knowledge of Himalayan flora.', ARRAY['Trek to the summit of Mount Tendong by Lepcha elders and youth', 'Solemn prayer rituals conducted by Bongthing (male priests) and Mun (female shamans)', 'Exhibition of indigenous Lepcha wild herbs, foods, and bamboo craft', 'Folk dances enacting the receding of the cosmic waters']::TEXT[], 'Lepchas dress in exquisite handloom attire, climb to Tendong peak to offer prayers, and gather for cultural conferences in Namchi.', ARRAY['Khuri (buckwheat rolls stuffed with wild herbs)', 'Pork cooked with indigenous forest roots', 'Local cheese soup', 'Traditional Chi millet beer']::TEXT[], 'Stunning handwoven Lepcha attire: men wear white-and-black woven Dum-pra blankets fastened with pins; women wear graceful Dumvum robes.', 'Soulful melodies on the traditional bamboo flute (Palit-Keng) and traditional Tungbuk lute.', ARRAY['Mount Tendong peak', 'Lepcha bamboo hat (Sambat)', 'Palit-Keng flute', 'Medicinal forest herb bundle']::TEXT[], '3 Days (main day August 8)', 'Solar Calendar (Fixed Date)', 'Celebrated annually on August 8 as a gazetted state holiday in Sikkim.', 'August', 'FIXED', 'August 8 annually', '2026-08-07 to 2026-08-09', '2027-08-07 to 2027-08-09', 'Sikkim Lepcha Youth Association & Department of Cultural Affairs', ARRAY['Sikkim']::TEXT[], ARRAY['Namchi', 'Damthang', 'Gangtok']::TEXT[], ARRAY['Mount Tendong Peak, Damthang, South Sikkim', 'Namchi Cultural Ground']::TEXT[], 'Morning of August 8 for the summit prayer ceremony at Mount Tendong, followed by afternoon cultural events in Namchi.', 2, 'Unique cultural immersion into one of the world''s most ancient mountain cultures, surrounded by lush rain-soaked cloud forests and mist.', 'Namchi is 78 km from Gangtok (2.5 hours by taxi); trail to Tendong summit starts at Damthang (6 km trek).', 'Hotels in Namchi or eco-resorts in Damthang.', 'Respectful, community-centered, eco-conscious.', 'Carry rain gear as August is peak monsoon; do not harvest wild plants along the sacred Tendong trail.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('kagyed-dance-sikkim', 'Kagyed Dance', ARRAY['Monastic Cham of Kagyed']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tibetan Buddhism', 'A mesmerizing 2-day Buddhist Cham dance festival performed by monks to destroy negative cosmic energies before the new year.', 'Celebrated annually in the 10th Tibetan month, based on the eight sacred esoteric teachings (Kagyed) revealed by Guru Padmasambhava.', 'The dances enact the subjugation of evil forces and demonic obstacles by Mahakala and enlightened wrathful protector deities.', 'To burn away negative karma, protect the state from wars and diseases, and usher in peace and prosperity for the coming year.', 'Triumph of enlightened wisdom over ignorance, hypnotic visual majesty, and sacred monastic discipline.', 'Preserves ancient 8th-century tantric mudras and choreographed circular movements unchanged across centuries.', ARRAY['Performing wrathful deity Cham dances in massive wooden masks', 'Consecration of the sacred dough effigy (Tor) representing evil forces', 'Solemn burning of the effigy in a blazing bonfire outside monastery gates', 'Monastic blessing of the gathered public']::TEXT[], 'The stone courtyards of Enchey and Tsuklakhang echo with music; monks in terrifying masks twirl with swords while crowds watch in awe.', ARRAY['Vegetarian monastery stew', 'Steamed Tibetan buns (Tingmo)', 'Hot butter tea (Suja)', 'Sweet saffron rice']::TEXT[], 'Incomparable silk brocade costumes imported from ancient looms, terrifying wrathful deity masks, and black hats with skull crowns.', 'Deep harmonic drone of Dungchen horns, crashing Rolmo cymbals, piercing Gyaling oboes, and rhythmic hand-drum beats.', ARRAY['Wrathful Mahakala mask', 'Burning Tor effigy', 'Phurba ritual dagger', 'Enchey monastery courtyard']::TEXT[], '2 Days', 'Tibetan Lunar Calendar (10th month, 28th-29th days)', 'Held on the 28th and 29th days of the tenth Tibetan lunar month (December).', 'December', 'LUNAR', '28th and 29th days of the 10th Tibetan lunar month', '2026-12-07 to 2026-12-08', '2027-12-26 to 2027-12-27', 'Enchey Monastery Management & Ecclesiastical Affairs Department Sikkim', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok']::TEXT[], ARRAY['Enchey Monastery Courtyard, Gangtok']::TEXT[], '10:00 AM to 2:00 PM for the core Cham dances, culminating in the burning of the effigy.', 2, 'Hypnotic and otherworldly: watching monks in terrifying multi-colored wrathful masks twirl in slow, cosmic circles amidst incense clouds.', 'Enchey Monastery is 3 km from central Gangtok (10 minutes by taxi).', 'Hotels in Gangtok.', 'Fascinated audience of local Buddhists and international travelers; respectful and quiet.', 'Maintain silence during the performances; do not step into the chalk-marked performance circle.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('red-panda-winter-carnival-sikkim', 'Red Panda Winter Carnival', ARRAY['Sikkim Winter Tourism Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Eco-Tourism & Contemporary Sikkim Culture', 'Gangtok''s signature winter festival celebrating the state animal (Red Panda) with parades, organic food feasts, and indie music on MG Marg.', 'Launched by the Department of Tourism, Government of Sikkim, to showcase the state''s cultural mosaic and promote winter tourism.', 'Named in honor of the endangered Himalayan Red Panda, which finds safe haven in the temperate forests of Sikkim.', 'To promote eco-friendly tourism, celebrate Sikkim''s 100% organic state status, and showcase the music and fashion of Himalayan youth.', 'Festive winter joy, environmental conservation pride, organic culinary excellence, and vibrant rock music.', 'Sikkim is the world''s first 100% certified organic state (awarded by the UN FAO Future Policy Gold Award).', ARRAY['Grand carnival street parade down the famous pedestrian MG Marg in Gangtok', 'Tasting of 100% certified organic Himalayan cuisine', 'Winter rock concert series featuring top Indian bands', 'Traditional handicraft and handloom masterclasses']::TEXT[], 'The pedestrian MG Marg is illuminated with fairy lights; flower shows, street food stalls, and live acoustic music fill the street.', ARRAY['Organic Sikkimese pork momos', 'Gundruk (fermented leafy greens) soup', 'Sel Roti with potato curry', 'Chhurpi (yak cheese) soup', 'Fresh mountain bakery treats']::TEXT[], 'Trendy winter fashion: puffer jackets, stylish woollen berets, and traditional Bhutia, Lepcha, and Nepali handloom shawls.', 'Rock, indie pop, Nepali folk fusion, and traditional Buddhist chanting performances.', ARRAY['Red Panda mascot', 'Flower-filled pedestrian MG Marg', 'Organic green seal', 'Kanchenjunga winter glow']::TEXT[], '9 Days', 'Gregorian (Winter Calendar)', 'Organized during the peak winter holiday season in December/January.', 'December', 'ORGANIZER_ANNOUNCED', 'Last week of December through New Year', '2026-12-24 to 2027-01-01', '2027-12-24 to 2028-01-01', 'Tourism & Civil Aviation Department, Government of Sikkim', ARRAY['Sikkim']::TEXT[], ARRAY['Gangtok']::TEXT[], ARRAY['MG Marg Pedestrian Promenade & Ridge Park, Gangtok']::TEXT[], 'Late afternoon (4:00 PM) to 8:30 PM when MG Marg lights up with carnival parades and open-air concerts.', 3, 'Strolling down the spotless, vehicle-free MG Marg lined with flowers, sipping hot spiced tea while listening to live rock bands under winter fairy lights.', 'Accessible directly in central Gangtok; fully pedestrian promenade.', 'Hotels directly on or adjacent to MG Marg, Gangtok.', 'Vibrant, cosmopolitan, cheerful holiday crowds.', 'MG Marg is a strict no-smoking and no-littering zone; heavy fines apply for spitting or littering.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('kharchi-puja-tripura', 'Kharchi Puja', ARRAY['Fourteen Gods Festival', 'Chaturdash Devata Puja']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tripuri Indigenous Tradition & Hinduism', 'Tripura''s royal festival worshipping the Fourteen Gods (Chaturdash Devata) at Old Agartala, cleansing the earth after her menstrual cycle.', 'Practiced since antiquity by the Manikya kings of Tripura; later shifted from the ancient capital of Udaipur to Old Agartala (Puran Agartala).', 'Kharchi is derived from ''Khya'' (earth) and ''Chi'' (cleansing). Earth is believed to rest during Ambubachi; Kharchi cleanses the land thereafter.', 'To cleanse the mother earth, wash away all sins, ward off evil spirits, and pray for the health and prosperity of all citizens.', 'Harmonious fusion of indigenous tribal (Kokborok) animist priesthood with royal Hindu Vedic worship.', 'Conducted exclusively by the hereditary royal tribal high priest (Chantai) and his fourteen assistants (Narayan).', ARRAY['Chantai carrying the fourteen brass deities to the sacred Howrah river for ceremonial dawn bathing', 'Grand royal procession back to the Chaturdash Devata temple', 'Offering of buffalo, goats, and pigeons to the deities', 'Week-long vibrant public fair']::TEXT[], 'Hundreds of thousands of tribal and non-tribal devotees throng Old Agartala; the Chantai anoints the deities while fairs buzz with handicrafts.', ARRAY['Awang Bangwi (Tripuri rice cake wrapped in Lairu leaves)', 'Chakhwi (pork cooked with bamboo shoot and alkaline water)', 'Muya Awandru', 'Bhangui sweets']::TEXT[], 'Tribal women in beautiful handwoven Rignai and Risa; royal priests in pure white silk Dhotis with sacred red marks.', 'Beating of traditional tribal Kham drums, brass gongs, conch shells, and sacred Kokborok chants.', ARRAY['Fourteen golden and brass deity heads', 'Sacred Howrah river waters', 'Risa handloom cloth', 'Temple dome of Old Agartala']::TEXT[], '7 Days', 'Luni-Solar Calendar (Ashadha Shukla Ashtami)', 'Falls on the eighth day of the waxing moon of the Hindu month of Ashadha (June/July).', 'July', 'LUNISOLAR', 'Ashadha Shukla Ashtami (eighth lunar day of bright fortnight of Ashadha)', '2026-07-22 to 2026-07-28', '2027-07-11 to 2027-07-17', 'Chaturdash Devata Temple Trust & Tripura Information & Cultural Affairs', ARRAY['Tripura']::TEXT[], ARRAY['Agartala', 'Old Agartala']::TEXT[], ARRAY['Chaturdash Devata Temple, Puran Agartala (Old Agartala, 8 km from capital)']::TEXT[], 'Opening day dawn (5:30 AM to 8:30 AM) when the Chantai carries the 14 deities to the Howrah river for their sacred ablution.', 3, 'Deeply impressive synthesis of royal history and tribal mysticism: watching the royal tribal priest carry 14 golden heads amidst blowing conches.', 'Old Agartala is 8 km from central Agartala; shared autos, city buses, and app cabs available.', 'Hotels in Agartala city.', 'Extremely large crowd (over 500,000 visitors over 7 days); well-managed queues.', 'Maintain decorum near the sanctum; avoid stepping on the river ghat path during the holy deity procession.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ker-puja-tripura', 'Ker Puja', ARRAY['Sacred Boundary Protection Ritual']::TEXT[], 'RELIGIOUS_TEMPLE', 'Tripuri Tribal Tradition & Royal State Ritual', 'Tripura''s most extraordinary boundary lockdown ritual: a 30-hour total seclusion of a designated area to protect the capital from harm.', 'Instituted by the Manikya dynasty centuries ago; funded and managed by the state government as part of the 1949 Tripura Merger Agreement.', 'Ker literally means a boundary or enclosure. The deity Vastu Devata is propitiated to protect the realm from natural calamities and epidemics.', 'To seal the realm against evil spirits, prevent pestilence, protect newborns and pregnant mothers, and ensure state peace.', 'Sacred discipline, absolute seclusion, communal obedience to spiritual law, and ancient state protection.', 'A living treaty tradition: under the 1949 accession pact, the Government of India is legally bound to fund and facilitate this royal ritual.', ARRAY['Chantai (high priest) planting a sacred green bamboo pole to establish the Ker boundary', 'Strict 30-hour lockdown: no fire lighting, no wearing of shoes, no vehicles, no birth/death within perimeters', 'Chanting of protective mantras in Kokborok', 'Sacrificial offering to Vastu Devata']::TEXT[], 'Absolute pin-drop silence envelops the royal palace zone; no one enters or leaves until the Chantai officially dissolves the Ker boundary.', ARRAY['Simple fruits and uncooked prasad consumed prior to the lighting restriction', 'Strict fasting during the peak ritual hours']::TEXT[], 'Barefoot, simple traditional handloom white wraps.', 'Complete, profound silence; musical instruments are strictly forbidden during the lockdown.', ARRAY['Sacred bent bamboo boundary pole (Ker)', 'Royal Chantai staff', 'Ujjayanta Palace gate', 'Sacred fire altar']::TEXT[], '2.5 Days (30 hours of continuous lockdown)', 'Luni-Solar Calendar (Ashadha/Shravana month)', 'Held exactly two weeks after Kharchi Puja, on the first Tuesday or Saturday of the dark fortnight.', 'August', 'LUNISOLAR', 'Two weeks after Kharchi Puja (Tuesday/Saturday alignment)', '2026-08-04 to 2026-08-06', '2027-07-27 to 2027-07-29', 'Revenue Department, Government of Tripura & Royal Palace Council', ARRAY['Tripura']::TEXT[], ARRAY['Agartala']::TEXT[], ARRAY['Ker Puja Enclosure, Royal Palace Compound, Agartala']::TEXT[], 'Witnessing the planting of the bamboo pole marking the boundary or the post-lockdown reopening ceremonies.', 1, 'Unprecedented cultural experience: witnessing a modern state capital enforce absolute silence and lockdown for a sacred ancestral ritual.', 'All vehicular movement inside the marked Ker zone is banned; plan movement outside the palace perimeter.', 'Hotels in Agartala outside the designated Ker perimeter.', 'No public crowd permitted inside the sealed zone; solemn and deeply respected by citizens.', 'Absolute compliance with lockdown rules is legally required: do not enter the marked zone, do not take photographs, do not make noise.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('garia-puja-tripura', 'Garia Puja', ARRAY['Tripuri Spring Agricultural Festival']::TEXT[], 'HARVEST_SEASONAL', 'Tripuri Indigenous Tradition (Baba Garia Worship)', 'A joyous 7-day spring festival of the Tripuri and Jamatia tribes worshipping Baba Garia (god of livestock and wealth) with Garia dance.', 'Celebrated since antiquity by indigenous tribes (Tripuri, Reang, Jamatia, Noatia) to welcome the new agricultural cycle.', 'Baba Garia is the supreme benefactor deity who protects livestock, blesses the jhum fields, and grants prosperity to children.', 'To seek blessings for cattle, bountiful harvest from jhum slash-and-burn farming, and protection from wild predators.', 'Infectious joy, rhythmic vigor, community feasting, and celebration of indigenous agrarian life.', 'Features the Garia dance where male and female youths mimic the sowing of seeds and harvesting of crops in energetic lines.', ARRAY['Erecting the sacred bamboo pole of Baba Garia decorated with garlands and cotton thread', 'Sacrificial offering of roosters by the Ochai priest', 'Performing the Garia dance house to house across the village', 'Sharing of consecrated rice beer and cakes']::TEXT[], 'Youth dance through village lanes led by the beating of drums; every household showers them with rice, eggs, and homemade sweets.', ARRAY['Awang Bangwi (rice cake)', 'Chakhwi', 'Mosodeng (spicy smoked fish chutney with chilies)', 'Garia consecrated prasad']::TEXT[], 'Women wear dazzling handwoven Rignai and bright yellow Risa; men wear white turbans and woven dhotis.', 'Vigorous beating of the Kham drum, piping tunes on the Sumui (bamboo flute), and cheerful call-and-response choruses.', ARRAY['Sacred Baba Garia bamboo pole', 'White cotton thread coils', 'Kham drum', 'Rooster sacrifice emblem']::TEXT[], '7 Days', 'Solar Calendar (Chaitra Sankranti / Baisakh 1)', 'Begins on the last day of Chaitra (April 14) and continues for seven days into the month of Baisakh.', 'April', 'SOLAR', 'Commences on April 14 (Chaitra Sankranti) annually', '2026-04-14 to 2026-04-20', '2027-04-14 to 2027-04-20', 'Tripura Tribal Areas Autonomous District Council (TTAADC) & ICA Tripura', ARRAY['Tripura']::TEXT[], ARRAY['Agartala', 'Khowai', 'Udaipur', 'Ambassa']::TEXT[], ARRAY['Garia Temple Agartala & tribal villages across Tripura']::TEXT[], 'Day 1 and Day 7 when the grand community Garia dance circles assemble in village squares.', 3, 'Pure grassroots joy: watching entire tribal villages dance together with infectious smiles behind the garlanded bamboo pole of Baba Garia.', 'Shared sumos and autos across Tripura; local cabs in Agartala.', 'Hotels in Agartala.', 'High-spirited, friendly, hospitable village community gatherings.', 'Offer a small token coin or rice if the Garia dance troupe enters the courtyard where you are visiting.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('neermahal-water-festival-tripura', 'Neermahal Water Festival', ARRAY['Rudrasagar Lake Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Royal Architecture & Water Sports Tourism', 'A romantic water carnival held on Rudrasagar Lake surrounding the fairy-tale floating lake palace of Neermahal.', 'Celebrates the royal architectural masterpiece Neermahal (Water Palace), built by Maharaja Bir Bikram Kishore Manikya in 1930 CE.', 'Conceived by Tripura Tourism to combine royal palace heritage with traditional boat races and swimming competitions.', 'To promote royal lake palace tourism, showcase traditional boatmanship, and celebrate the rich aquatic biodiversity of Rudrasagar Lake.', 'Royal nostalgia, shimmering water beauty, thrilling boat race competition, and twilight cultural pageantry.', 'Neermahal is the largest water palace in eastern India and one of only two floating lake palaces in the entire country.', ARRAY['Traditional boat-racing competition on Rudrasagar Lake', 'Open-water swimming marathons across the lake', 'Lighting of the floating Neermahal palace with thousands of lamps', 'Evening classical and folk music concerts on palace balconies']::TEXT[], 'Thousands watch from lake embankments as decorated longboats slice through water; motorboats shuttle visitors to the lit-up palace.', ARRAY['Awang Bangwi', 'Fresh Rudrasagar lake fish curry', 'Kheer', 'Tripuri bamboo shoot chicken', 'Sweet pithe']::TEXT[], 'Casual leisure wear, sunglasses, and traditional Tripuri Risa handloom stoles.', 'Folk songs on Dotara and flute, boatmen''s Bhatiali songs, and evening Rabindra Sangeet concerts.', ARRAY['Neermahal marble white palace dome', 'Rudrasagar lake waters', 'Racing longboat', 'Lotus blossom']::TEXT[], '3 Days', 'Gregorian (Autumn Calendar)', 'Organized in late September or October during the pleasant post-monsoon full water level.', 'October', 'ORGANIZER_ANNOUNCED', 'Announced by Tripura Tourism for an October weekend', '2026-10-09 to 2026-10-11', '2027-10-08 to 2027-10-10', 'Tripura Tourism Development Corporation (TTDC)', ARRAY['Tripura']::TEXT[], ARRAY['Melaghar', 'Agartala']::TEXT[], ARRAY['Rudrasagar Lake & Neermahal Palace, Melaghar (53 km from Agartala)']::TEXT[], 'Late afternoon (3:00 PM) for the boat race heats followed by sunset boat ride to the illuminated palace.', 2, 'Magical fairy-tale evening: gliding on a boat across shimmering waters towards an illuminated white marble palace glowing like a jewel under twilight.', 'Melaghar is 53 km south of Agartala (1.5 hours drive by taxi or bus).', 'Sagar Mahal Tourist Lodge directly on the lake shore or hotels in Agartala.', 'Cheerful, family-friendly, lakeside crowds.', 'Wear life jackets on all lake ferry rides; do not litter inside the historical palace.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('pilak-festival-tripura', 'Pilak Archaeological & Cultural Festival', ARRAY['Pilak Heritage Festival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Buddhist-Hindu Archaeological Heritage', 'A unique heritage festival held amidst the 8th-century archaeological ruins, colossal rock sculptures, and stupas of Pilak.', 'Celebrates the ancient 8th–12th century Buddhist and Hindu civilization that flourished at Pilak in South Tripura.', 'Pilak was a major crossroads of Mahayana Buddhist and Hindu art on the historic route to Southeast Asia.', 'To promote archaeological tourism, spotlight ancient stone sculptures, and foster cultural integration across communities.', 'Antiquity, archaeological wonder, spiritual syncretism, and pride in Tripura''s deep historical roots.', 'Pilak features massive terracotta plaques, colossal stone images of Avalokiteshvara, Surya, and Narasimha dating to the Pala period.', ARRAY['Archaeological heritage guided tours among ancient stupa basements', 'Seminars on ancient Southeast Asian trade routes', 'Traditional dance recitals by Reang and Chakma troupes', 'Artisan exhibitions of stone and terracotta crafts']::TEXT[], 'The ancient excavated brick stupas are illuminated with spotlights; classical dancers perform against the backdrop of 1,200-year-old stone reliefs.', ARRAY['Traditional Tripuri thali', 'Chakma pork with bamboo shoot', 'Awang Bangwi', 'Local village sweets']::TEXT[], 'Traditional tribal handlooms (Reang, Chakma, Tripuri) and smart casual travel wear.', 'Classical sitar and flute, Chakma acoustic folk songs, and rhythmic Reang Hojagiri dancing beats.', ARRAY['Avalokiteshvara stone sculpture', 'Excavated terracotta plaque', 'Ancient brick stupa', 'Archaeological trowel']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized during the pleasant winter month of December or January.', 'December', 'ORGANIZER_ANNOUNCED', 'Third weekend of December annually', '2026-12-18 to 2026-12-20', '2027-12-17 to 2027-12-19', 'Tourism Department, Govt of Tripura & Archaeological Survey of India', ARRAY['Tripura']::TEXT[], ARRAY['Jolaibari', 'Santirbazar', 'Agartala']::TEXT[], ARRAY['Pilak Archaeological Site, Jolaibari, South Tripura (100 km from Agartala)']::TEXT[], 'Late afternoon (3:00 PM to 6:30 PM) when the setting sun illuminates the ancient stone carvings.', 2, 'Fascinating journey into antiquity: witnessing graceful Hojagiri balancing dances performed beside monumental 1,200-year-old Buddhist sculptures.', 'Pilak is 100 km from Agartala (2.5 hours by taxi via NH8); train stops at nearby Jolaibari station.', 'Pilak Tourist Lodge or government inspection bungalows in Santirbazar.', 'Heritage enthusiasts, history buffs, and local community members.', 'Do not touch or climb on ancient terracotta plaques and protected stone sculptures.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('orange-tourism-festival-tripura', 'Orange & Tourism Festival', ARRAY['Jampui Hills Orange Festival']::TEXT[], 'HARVEST_SEASONAL', 'Agro-Tourism & Mizo Heritage of Tripura', 'A scenic mountain festival in the emerald Jampui Hills celebrating sweet golden winter oranges and Mizo folk culture.', 'Launched to celebrate Jampui Hills, known as the ''Seat of Spring'' and Tripura''s prime orange-growing mountain ridge.', 'The crisp, cool climate and mist-shrouded elevations (3,000 ft) of the Jampui ridge produce exceptionally sweet, golden mandarins.', 'To promote hill tourism, support orange orchard farmers, and showcase the distinct culture of the Mizo community in Tripura.', 'Misty mountain freshness, citrus sweetness, gentle Mizo hospitality, and panoramic Himalayan vistas.', 'Jampui Hills is home to a vibrant Mizo community within Tripura, known for high literacy and model village cleanliness.', ARRAY['Visits to sprawling orange orchards with direct plucking', 'Orange eating and juicing competitions', 'Cheraw bamboo dance performances by village youth', 'Sunset watching from the Betlingchhip mountain watchtower']::TEXT[], 'Villagers set up decorated orange stalls; visitors trek along the ridge from Vanghmun to Phuldungsei, tasting fresh juice and honey.', ARRAY['Fresh sweet Jampui oranges and fresh juice', 'Sawhchiar (Mizo chicken porridge)', 'Bai (vegetable pork stew)', 'Wild mountain honey', 'Freshly baked cookies']::TEXT[], 'Warm winter jackets, mufflers, and colorful handwoven Mizo Puan skirts.', 'Melodious four-part choral singing, acoustic guitar ballads, and joyful Cheraw bamboo clacking.', ARRAY['Golden mandarin orange', 'Betlingchhip watchtower (Tripura''s highest peak)', 'Cheraw bamboo poles', 'Misty valley panorama']::TEXT[], '3 Days', 'Gregorian (Harvest Calendar)', 'Organized in late November or early December during peak orange harvest season.', 'November', 'ORGANIZER_ANNOUNCED', 'Last weekend of November annually', '2026-11-27 to 2026-11-29', '2027-11-26 to 2027-11-28', 'Department of Tourism, Government of Tripura & Jampui Hills BAC', ARRAY['Tripura']::TEXT[], ARRAY['Vanghmun', 'Phuldungsei', 'Dharmanagar']::TEXT[], ARRAY['Vanghmun Model Village & Eden Tourist Lodge Grounds, Jampui Hills']::TEXT[], 'Morning 8:30 AM to 1:00 PM for scenic orchard walks and panoramic views towards the Chittagong Hill Tracts.', 2, 'Idyllic mountain getaway: breathing crisp, pine-scented air while eating juicy sweet oranges and watching clouds float through clean model villages.', 'Jampui Hills is 200 km from Agartala (6 hours drive); closest railhead is Dharmanagar (70 km away).', 'Eden Tourist Lodge in Vanghmun or village homestays.', 'Relaxed, eco-traveler and family-friendly gathering.', 'Keep the pristine hill villages clean; follow designated paths when entering private orchards.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('island-tourism-festival-andaman', 'Island Tourism Festival', ARRAY['ITF Port Blair', 'Andaman Cultural Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Island Heritage & Multi-Cultural Integration', 'A vibrant 10-day mega-carnival at Port Blair showcasing the diverse cultural kaleidoscope, music, and cuisine of the Andaman & Nicobar Islands.', 'Initiated by the Andaman and Nicobar Administration to promote tourism and celebrate the harmonious ''Mini-India'' character of the islands.', 'The Andaman islands represent a harmonious synthesis of settlers from Bengal, Tamil Nadu, Kerala, Andhra Pradesh, and mainland India alongside indigenous tribes.', 'To celebrate composite island culture, promote marine and island tourism, and showcase national performing artists.', 'Cosmopolitan island harmony, tropical breeze, musical joy, and cross-cultural brotherhood.', 'Port Blair''s Cellular Jail and surrounding islands represent India''s profound freedom struggle; the festival honors this resilient national spirit.', ARRAY['Grand inaugural parade featuring cultural troupes from all Indian states', 'Traditional boat races and water sports regattas at Marina Park', 'Dog shows and baby shows', 'Nightly concerts by renowned mainland vocalists and bands']::TEXT[], 'The historic Netaji Stadium and ITF grounds fill with stalls, amusement rides, and open-air stages with thousands enjoying the sea breezes.', ARRAY['Fresh Andaman grilled red snapper', 'Crab curry', 'Lobster thermidor', 'South Indian coconut delicacies', 'Bengali fish curry']::TEXT[], 'Casual island resort wear, linen shirts, cotton dresses, and colorful ethnic handlooms.', 'Carnatic and Hindustani classical recitals, Bollywood orchestras, South Indian percussion, and live indie rock.', ARRAY['Sea shell ornament', 'Cellular Jail silhouette', 'Coconut palm by the ocean', 'Dolphin motif']::TEXT[], '10 Days', 'Gregorian (Winter Calendar)', 'Organized annually in January during the peak winter tourist season.', 'January', 'ORGANIZER_ANNOUNCED', 'First or second week of January annually', '2026-01-05 to 2026-01-14', '2027-01-05 to 2027-01-14', 'Directorate of Tourism, Andaman & Nicobar Administration', ARRAY['Andaman and Nicobar Islands']::TEXT[], ARRAY['Port Blair']::TEXT[], ARRAY['ITF Grounds VIP Road Port Blair', 'Netaji Stadium', 'Marina Park Port Blair']::TEXT[], 'Evenings from 5:30 PM to 9:30 PM for stage performances and street food markets.', 4, 'Balmy tropical nights, fresh oceanic breeze, spectacular seafood stalls, and lively music under the swaying palms of Port Blair.', 'Veer Savarkar International Airport connects Port Blair to Chennai, Kolkata, Delhi, and Bangalore; autos and taxis in town.', 'Hotels and resorts across Port Blair (Marine Hill, Corbyn''s Cove, Phoenix Bay).', 'Vibrant, family-friendly, celebratory island crowd.', 'Respect local environmental laws: strictly no collection of live corals or sea shells from beaches.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('subhash-mela-havelock', 'Subhash Mela', ARRAY['Netaji Subhash Chandra Bose Jayanti Fair']::TEXT[], 'CULTURAL_NATIONAL', 'Patriotic Heritage & Bengali Island Community', 'A patriotic one-week festival celebrated on Swaraj Dweep (Havelock Island) commemorating Netaji Subhash Chandra Bose''s historic flag hoisting.', 'Commemorates Netaji Subhash Chandra Bose''s historic hoisting of the Indian Tricolour at Port Blair on 30 December 1943, declaring the islands free.', 'Celebrated with tremendous fervor by the Bengali settler community of Swaraj Dweep and Neil Island around Netaji''s birth anniversary on January 23.', 'To honor the supreme sacrifice of Netaji and the Indian National Army (INA) and celebrate island cultural arts.', 'Patriotic fervor, historical pride, folk camaraderie, and beachside cultural celebration.', 'The Andaman Islands were the first territory of India liberated from British colonial control during World War II under the Azad Hind Government.', ARRAY['Flag hoisting and national anthem parade on January 23', 'Patriotic drama competitions and recitation of Netaji''s speeches', 'Folk dances including Baul and Rabindra Sangeet', 'Volleyball and kabaddi beach tournaments']::TEXT[], 'Swaraj Dweep''s village center is decorated with tricolour bunting; families visit food stalls and attend cultural shows after sunset.', ARRAY['Bengali fish fry', 'Luchi with alur dom', 'Sandesh and Rasgulla', 'Fresh green tender coconuts', 'Prawn malai curry']::TEXT[], 'Traditional Bengali handloom Dhotis, Kurtas, and Tant cotton sarees; students in school parade uniforms.', 'Patriotic songs (Kadam Kadam Badhaye Ja), Baul folk music, and Rabindra Sangeet.', ARRAY['Tricolour National Flag', 'Netaji Subhash Chandra Bose portrait', 'INA cap', 'Radhanagar beach wave']::TEXT[], '7 Days', 'Solar Calendar (Fixed Date Window)', 'Centered around January 23 (Parakram Diwas) annually.', 'January', 'FIXED', 'January 20 to 26 annually (main day January 23)', '2026-01-20 to 2026-01-26', '2027-01-20 to 2027-01-26', 'Subhash Mela Committee Swaraj Dweep & A&N Administration', ARRAY['Andaman and Nicobar Islands']::TEXT[], ARRAY['Swaraj Dweep (Havelock Island)']::TEXT[], ARRAY['Village No. 1 Community Ground, Swaraj Dweep (Havelock)']::TEXT[], 'January 23 morning for the patriotic parade; evenings for open-air cultural theatre.', 2, 'Warm village fair atmosphere on a tropical paradise island: listening to stirring patriotic songs under starry skies near world-class beaches.', 'Catamaran ferries (Makruzz, Nautika, Green Ocean) or government ferry from Port Blair to Swaraj Dweep (90 minutes to 2.5 hours).', 'Beach resorts along Govind Nagar and Vijay Nagar beaches in Swaraj Dweep.', 'Friendly island community and curious international backpackers.', 'Show respect during national anthem and flag ceremonies; dress modestly in the village center.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('monsoon-music-festival-andaman', 'Monsoon Music Festival', ARRAY['Music of the Rain Andaman']::TEXT[], 'MUSIC_DANCE_ARTS', 'Ecology, Rain Celebration & Arts', 'A romantic celebration of the arrival of the Southwest Monsoon in the tropical Andaman archipelago with rain songs and jazz.', 'Launched by Andaman Tourism to dispel the myth that islands are unvisitable during the monsoon and highlight the romantic beauty of tropical downpours.', 'The Andaman and Nicobar Islands are the first territory of the Indian subcontinent to receive the life-giving Southwest Monsoon in late May.', 'To celebrate the arrival of the monsoon, promote rain tourism, and offer indoor and seaside musical retreats.', 'Romantic contemplation, dramatic rain-lashed seascapes, soothing melodies, and tropical lushness.', 'Marks the astronomical and meteorological arrival of the monsoon that sustains agriculture across the entire Indian subcontinent.', ARRAY['Rain song vocal performances (Megh Malhar ragas and island folk songs)', 'Seaside photography contests capturing monsoon surf', 'Indoor craft workshops using driftwoods', 'Rain poetry reading circles']::TEXT[], 'Concerts are held in covered amphitheaters overlooking turbulent turquoise waves; visitors enjoy hot snacks while watching tropical rain curtains.', ARRAY['Piping hot onion and fish pakoras', 'Chai infused with island spices (cinnamon, clove, cardamom)', 'Crab masala', 'Steamed momos']::TEXT[], 'Light waterproof rain jackets, casual breathable cottons, and comfortable waterproof sandals.', 'Indian classical ragas dedicated to rain (Malhar, Megh), blues, acoustic guitar, and gentle percussion.', ARRAY['Raindrop ripples on turquoise sea', 'Dark monsoon clouds over lighthouse', 'Steaming teacup', 'Swaying wet coconut fronds']::TEXT[], '3 Days', 'Solar Calendar (Late May / Early June)', 'Organized to coincide with the official declaration of monsoon onset (typically late May).', 'May', 'ORGANIZER_ANNOUNCED', 'Last weekend of May or first weekend of June annually', '2026-05-29 to 2026-05-31', '2027-05-28 to 2027-05-30', 'Department of Information, Publicity & Tourism, A&N Islands', ARRAY['Andaman and Nicobar Islands']::TEXT[], ARRAY['Port Blair']::TEXT[], ARRAY['Corbyn''s Cove Beach & Megapode Resort Amphitheatre, Port Blair']::TEXT[], 'Late afternoon watching heavy rain curtains sweep across the ocean horizon while sipping hot masala chai.', 2, 'Unrivaled sensory romance: watching dramatic monsoon clouds roll over the vast Indian Ocean to the soulful strains of sitar and flute.', 'Taxis within Port Blair; ferry services to outlying islands may operate on restricted weather schedules.', 'Sea-facing resort rooms with balconies at Corbyn''s Cove or Marine Hill.', 'Serene, music-loving, contemplative travelers.', 'Never attempt swimming in the sea during heavy monsoon surf warnings; adhere to lifeguard instructions.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('beach-festival-andaman', 'Andaman Beach Festival', ARRAY['Corbyn''s Cove Beach Carnival']::TEXT[], 'MUSIC_DANCE_ARTS', 'Coastal Tourism, Youth & Water Sports', 'A fun-filled beach carnival at Corbyn''s Cove featuring sand sculpture competitions, beach volleyball, jet-ski stunts, and DJ nights.', 'Created to promote beach lifestyle, sports, and coastal recreation among both residents and tourists.', 'Celebrated along the crescent-shaped coconut-fringed beach of Corbyn''s Cove, Port Blair''s most accessible coastal strip.', 'To encourage youth fitness, spotlight eco-friendly water sports, and provide evening entertainment along the beach.', 'Sunny energy, water thrills, creative sand art, and breezy seaside leisure.', 'Spotlights the transition of the islands from a penal colony to a world-class recreational marine tourism destination.', ARRAY['Sand art sculpture competition judged by national artists', 'Beach volleyball and tug-of-war tournaments', 'Jet ski and water-skiing exhibitions', 'Sunset live acoustic bands and DJ music']::TEXT[], 'The beach comes alive with colorful canopies, food trucks serving grilled seafood, and families watching dynamic water sports.', ARRAY['Grilled lobster and jumbo prawns', 'Fish tikka', 'Coconut water', 'Chaat and kulfi', 'Biryani']::TEXT[], 'Beach shorts, floral print shirts, sun hats, UV sunglasses, and flip-flops.', 'Reggae, upbeat indie pop, tropical house music, and live Bollywood hits.', ARRAY['Crescent coconut beach', 'Sand sculpture dolphin', 'Jet-ski spray', 'Golden tropical sunset']::TEXT[], '3 Days', 'Gregorian (Tourism Calendar)', 'Organized during the clear, sunny spring month of April.', 'April', 'ORGANIZER_ANNOUNCED', 'Third weekend of April annually', '2026-04-17 to 2026-04-19', '2027-04-16 to 2027-04-18', 'Tourism Department, Andaman and Nicobar Administration', ARRAY['Andaman and Nicobar Islands']::TEXT[], ARRAY['Port Blair']::TEXT[], ARRAY['Corbyn''s Cove Beach, Port Blair']::TEXT[], 'Late afternoon (3:30 PM) until sunset and into the breezy evening.', 2, 'Relaxed tropical festival fun: watching master sculptors carve giant sea turtles from beach sand while listening to island beats with a cold fresh coconut.', 'Corbyn''s Cove is 7 km from central Port Blair (15 minutes by auto-rickshaw or taxi).', 'Peerless Sarovar Portico or hotels in Port Blair.', 'Youthful, cheerful, family-friendly beach gathering.', 'Use trash cans for coconut shells and packaging; swim only in designated safe swimming zones.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('diwali-deepavali-pan-india', 'Diwali', ARRAY['Deepavali', 'Festival of Lights', 'Divali']::TEXT[], 'RELIGIOUS_TEMPLE', 'Hinduism, Jainism, Sikhism & Pan-Indian Cultural Tradition', 'India''s grandest festival of lights celebrating the triumph of light over darkness, good over evil, and wisdom over ignorance with millions of lamps.', 'Celebrated for over three millennia across the Indian subcontinent; documented in Vedic texts, the Ramayana, Mahabharata, and Jain scriptures.', 'Celebrates Lord Rama''s triumphant return to Ayodhya with Sita and Lakshmana after 14 years in exile and slaying Ravana; Jains celebrate Lord Mahavira''s Nirvana; Sikhs celebrate Bandi Chhor Divas.', 'To welcome Goddess Lakshmi into illuminated homes, celebrate ethical triumph, begin new business account books (Chopda Pujan), and foster familial love.', 'Supreme joy, renewal, generosity, radiant illumination, reconciliation, and cosmic auspiciousness.', 'Unites over a billion people across every corner of India; Ayodhya sets Guinness World Records with over 2.5 million earthen lamps along the Sarayu river.', ARRAY['Lighting millions of earthen Diyas with mustard or sesame oil', 'Elaborate multi-colored Rangoli at doorsteps', 'Lakshmi-Ganesha Puja at twilight with lotus and gold coins', 'Exchanging handcrafted sweets and gifts with family and friends', 'Bursting eco-friendly green firecrackers']::TEXT[], 'Every street, house, temple, and monument across India glows with warm oil lamps and fairy lights; families feast in brand-new clothes.', ARRAY['Kaju Katli', 'Besan Ladoo', 'Gulab Jamun', 'Gujiya', 'Chivda savory mix', 'Mawa Barfi', 'Mathri', 'Chhena Poda']::TEXT[], 'Finest traditional silk attire: women in Banarasi, Kanjeevaram, and Paithani sarees with gold jewelry; men in embroidered Kurta-Pajama with Nehru jackets.', 'Devotional Lakshmi Aarti (''Om Jai Lakshmi Mata''), festive shehnai melodies, joyous dholak rhythms, and Bollywood celebration songs.', ARRAY['Earthen Diya oil lamp with flame', 'Rangoli floral pattern', 'Lotus flower', 'Lakshmi-Ganesha idols', 'Swastika auspicious emblem']::TEXT[], '5 Days (Dhanteras, Naraka Chaturdashi, Lakshmi Pujan, Govardhan Puja, Bhai Dooj)', 'Hindu Luni-Solar Calendar (Kartika Amavasya)', 'Peak day (Lakshmi Pujan) occurs on the Amavasya (new moon) of the Hindu month of Kartika (October/November).', 'November', 'LUNISOLAR', 'Amavasya of Kartika month (darkest night of the lunar month)', '2026-11-08', '2027-10-29', 'Rashtriya Panchang & Ministry of Home Affairs Gazetted Holidays', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Ayodhya', 'Varanasi', 'Vrindavan', 'Jaipur', 'Kolkata', 'Amritsar', 'Delhi', 'Mumbai', 'Madurai']::TEXT[], ARRAY['Ram Ki Paidi Ghats Ayodhya (Deepotsav)', 'Dashashwamedh Ghat Varanasi', 'Golden Temple Amritsar (Bandi Chhor Divas)', 'Chhatrapati Shivaji Terminus Mumbai']::TEXT[], 'Dusk (6:00 PM to 9:30 PM) on Lakshmi Pujan night when millions of lamps flicker across every rooftop.', 5, 'One of the most awe-inspiring visual spectacles on Earth: standing on the riverbanks of Ayodhya or Varanasi watching millions of golden flames turn the dark night into a shimmering cosmic galaxy.', 'Advance booking of flights and trains 3-4 months ahead is essential; major city transport operates special services.', 'Book heritage hotels and riverside havelis well in advance across prime pilgrimage centers.', 'Extremely massive nation-wide celebration; safe, welcoming, and hospitable everywhere.', 'Wear elegant traditional clothes; accept sweets with right hand; do not walk over Rangoli designs at house thresholds.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('holi-festival-of-colours', 'Holi', ARRAY['Festival of Colours', 'Dol Jatra', 'Dhulandi', 'Phagwah']::TEXT[], 'HARVEST_SEASONAL', 'Hinduism & Pan-Indian Cultural Celebration', 'India''s exuberant spring carnival of colors celebrating the victory of devotion over arrogance, the onset of spring, and unconditional love.', 'Celebrated since antiquity; referenced in 7th-century Sanskrit drama Ratnavali by King Harsha and ancient murals at Ajanta and Ellora.', 'Legend of young Bhakt Prahlad''s survival while demoness Holika burned in fire; also celebrates divine eternal romance of Radha and Lord Krishna in Braj.', 'To celebrate the end of winter, welcome the spring harvest (wheat and gram), forgive past grievances, and play with colorful herbal powders (Gulal).', 'Uninhibited social equality, forgiveness, spontaneous joy, playful mischief, and breaking of all social barriers.', 'Braj region (Mathura, Vrindavan, Barsana, Nandgaon) preserves ancient distinct traditions like Lathmar Holi where women playfully beat men with sticks.', ARRAY['Holika Dahan (lighting massive community bonfires on the eve with coconut and barley offerings)', 'Rangwali Holi / Dhulandi (smearing herbal gulal and splashing colored water)', 'Lathmar Holi in Barsana and Nandgaon', 'Consuming traditional cooling Thandai infused with fragrant spices']::TEXT[], 'Streets turn into kaleidoscopic clouds of pink, turquoise, and yellow powder; people dance to drum beats, drenching friends and strangers in joy.', ARRAY['Gujiya (crisp pastry stuffed with sweet khoya and nuts)', 'Thandai (cooling milk drink with almonds and saffron)', 'Malpua with rabdi', 'Dahi Vada', 'Kachori with spicy potato curry']::TEXT[], 'Old white cotton kurtas, t-shirts, and pants that can be happily sacrificed to colorful dyes; hair oiled generously with coconut oil.', 'Thunderous Dhol beats, energetic folk songs (Faag, Chaiti), Braj Dham kirtans, and high-energy Bollywood dance tracks.', ARRAY['Pichkari water gun', 'Clay bowls of Gulal color powder', 'Holika bonfire flames', 'Gujiya sweet']::TEXT[], '2 Days (Holika Dahan on eve, Dhulandi on main day; up to 10 days in Braj)', 'Hindu Luni-Solar Calendar (Phalguna Purnima)', 'Celebrated on the full moon day (Purnima) of the Hindu month of Phalguna (February/March).', 'March', 'LUNISOLAR', 'Phalguna Purnima (full moon of Phalguna month)', '2026-03-03 to 2026-03-04', '2027-03-22 to 2027-03-23', 'Rashtriya Panchang & Govt of India Gazetted Holiday Calendar', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Mathura', 'Vrindavan', 'Barsana', 'Varanasi', 'Jaipur', 'Udaipur', 'Delhi', 'Shantiniketan']::TEXT[], ARRAY['Bankey Bihari Temple Vrindavan', 'Radha Rani Temple Barsana', 'Assi Ghat Varanasi', 'City Palace Jaipur']::TEXT[], 'Morning 9:30 AM to 1:30 PM on Dhulandi for the color playing, followed by a warm bath and feasting on sweet gujiyas.', 3, 'Unforgettable explosion of sheer joy: being drenched in bright magenta and turquoise powders amidst dancing crowds laughing under the warm spring sun.', 'Public transit often pauses until 2 PM on Holi day; arrange transport or join celebrations within walking distance of your stay.', 'Book well in advance in Mathura, Vrindavan, and Jaipur.', 'Energetic, boisterous, exuberant; play in recognized family or heritage venues with organic colors.', 'Apply coconut oil to hair and moisturizer to skin before playing; use only skin-safe herbal colors (Gulal); say ''Bura Na Mano, Holi Hai!''', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('maha-shivratri-pan-india', 'Maha Shivratri', ARRAY['The Great Night of Shiva', 'Shivaratri']::TEXT[], 'RELIGIOUS_TEMPLE', 'Shaivism / Hinduism', 'The great night of Lord Shiva celebrating cosmic consciousness, his sacred marriage to Goddess Parvati, and the cosmic dance of Tandava.', 'Celebrated since Vedic times; described extensively in the Shiva Purana, Linga Purana, and classical Sanskrit scriptures.', 'The night Shiva performed the cosmic dance of creation, preservation, and destruction (Tandava); also the night the Jyotirlinga manifested as an infinite column of light.', 'To conquer ignorance, meditate on inner divine awareness, observe fasting to cleanse bodily toxins, and seek Shiva''s grace.', 'Deep meditative introspection, yogic awakening, transcendence of ego, devotion, and cosmic silence.', 'Observed simultaneously at all 12 sacred Jyotirlinga shrines across India (Somnath, Kashi Vishwanath, Mahakaleshwar, Kedarnath, etc.).', ARRAY['Nishita Kaal Puja (sacred midnight worship in four Prahars)', 'Abhishekam with milk, honey, yogurt, ghee, and holy Ganga water', 'Offering sacred Bel leaves (Bilva Patra) and Dhatura flowers to the Shiva Lingam', 'Jaagran (night-long vigil of meditation, chanting, and classical music)']::TEXT[], 'Millions of devotees observe waterless or fruit fasts, wait in serene queues at Shiva temples, and chant ''Om Namah Shivaya'' through the night.', ARRAY['Sattvic fasting cuisine: Sabudana Khichdi', 'Kuttu (buckwheat) Puri', 'Makhana roasted in ghee', 'Singhara halwa', 'Bhang Thandai']::TEXT[], 'Modest traditional attire: men in white or saffron Dhoti/Kurta; women in simple sarees with Rudraksha beads and holy ashes (Bhasma).', 'Continuous chanting of ''Om Namah Shivaya'', Shiva Tandava Stotram, classical dhrupad, and night-long classical music concerts.', ARRAY['Shiva Lingam with Bel leaf', 'Trishul (trident) and Damru', 'Crescent moon and Snake', 'Three horizontal Bhasma lines (Tripundra)']::TEXT[], '1 Day (night-long vigil)', 'Hindu Luni-Solar Calendar (Phalguna Krishna Chaturdashi)', 'Observed on the 14th night of the dark fortnight of Phalguna (February/March).', 'February', 'LUNISOLAR', 'Krishna Chaturdashi of Phalguna month', '2026-02-15 to 2026-02-16', '2027-03-06 to 2027-03-07', 'Rashtriya Panchang & Kashi Vishwanath Temple Trust', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Varanasi', 'Ujjain', 'Haridwar', 'Rishikesh', 'Nashik', 'Mandi', 'Coimbatore']::TEXT[], ARRAY['Kashi Vishwanath Temple Varanasi', 'Mahakaleshwar Jyotirlinga Ujjain', 'Isha Yoga Centre Coimbatore', 'Bhootnath Temple Mandi']::TEXT[], 'Midnight (Nishita Kaal) from 11:45 PM to 12:45 AM for the profound midnight lingam abhishekam.', 2, 'Sublime spiritual power: sitting in meditation amidst thousands of devotees chanting the primordial sound of Shiva under a velvet night sky.', 'City traffic around Jyotirlinga shrines is heavy; pedestrian access zones near temples.', 'Hotels and ashrams in Varanasi, Ujjain, Rishikesh, and Coimbatore.', 'Intensely spiritual, patient, quiet, and disciplined queues.', 'Offer Bel leaves with the smooth stalk-side facing up; maintain meditative quiet inside sanctums; remove leather belts and shoes.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('krishna-janmashtami-pan-india', 'Krishna Janmashtami', ARRAY['Gokulashtami', 'Ashtami Rohini', 'Dahi Handi', 'Krishna Jayanti']::TEXT[], 'RELIGIOUS_TEMPLE', 'Vaishnavism / Hinduism', 'The joyful midnight celebration of the birth of Lord Krishna featuring cradle worship, fasts, Raas Leela, and thrilling Dahi Handi human pyramids.', 'Celebrated for thousands of years; described in the Srimad Bhagavatam and Mahabharata, marking the eighth avatar of Lord Vishnu.', 'Born at midnight in a prison cell in Mathura to Devaki and Vasudeva during a torrential storm to vanquish the tyrant king Kamsa.', 'To celebrate divine love, cosmic dharma, the mischievous childhood of Krishna, and the profound wisdom of the Bhagavad Gita.', 'Parental affection (Vatsalya Bhava), joyful ecstatic devotion, daring athletic teamwork (Dahi Handi), and midnight jubilation.', 'Mathura and Vrindavan are the historic birth and playground of Krishna; Mumbai hosts massive multi-tier human pyramid competitions.', ARRAY['Midnight Abhishekam of Baby Krishna (Bal Gopal) with Panchamrita', 'Gently rocking the decorated floral swing (Palna)', 'Fast broken at midnight with Makhan-Mishri prasad', 'Dahi Handi human pyramid breaking competitions next afternoon']::TEXT[], 'Devotees decorate temples with flowers and peacock feathers; children dress as Krishna and Radha; youths build 9-tier human pyramids in Mumbai.', ARRAY['Makhan-Mishri (freshly churned white butter with rock sugar)', 'Panjiri', 'Gopalkala (pressed rice with curd and cucumber)', 'Pedas of Mathura', 'Kheer']::TEXT[], 'Dhoti and Kurta in yellow (Pitambara); children wearing peacock feather crowns (Mor Mukut) with flutes.', 'Ecstatic chanting of ''Hare Krishna Hare Rama'', ''Govinda Ala Re'', soulful flute melodies, and classical Raas Leela songs.', ARRAY['Peacock feather', 'Bamboo flute (Bansuri)', 'Clay butter pot (Matki)', 'Decorated baby swing (Palna)']::TEXT[], '2 Days (midnight Janmashtami puja followed by daytime Dahi Handi)', 'Hindu Luni-Solar Calendar (Bhadrapada Krishna Ashtami)', 'Falls on the eighth day (Ashtami) of the dark fortnight of Bhadrapada month (August/September), under Rohini Nakshatra.', 'September', 'LUNISOLAR', 'Bhadrapada Krishna Ashtami with Rohini Nakshatra', '2026-09-03 to 2026-09-04', '2027-08-25 to 2027-08-26', 'Rashtriya Panchang & Sri Krishna Janmabhoomi Trust Mathura', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Mathura', 'Vrindavan', 'Mumbai', 'Dwarka', 'Puri', 'Udupi', 'Imphal']::TEXT[], ARRAY['Sri Krishna Janmabhoomi Temple Mathura', 'Prem Mandir Vrindavan', 'Dadar and Thane street arenas Mumbai', 'Dwarkadhish Temple Dwarka']::TEXT[], 'Midnight (12:00 AM) for the divine birth abhishekam in Mathura; next afternoon (2:00 PM to 6:00 PM) for Dahi Handi human pyramids in Mumbai.', 2, 'Unrivaled sensory joy: hearing temple bells toll at midnight amidst joyous conch shells, followed by watching nine-tier human pyramids reach into the sky in Mumbai.', 'Suburban trains and metros in Mumbai; dedicated pilgrim shuttles between Mathura and Vrindavan.', 'Hotels and dharmashalas in Mathura/Vrindavan; hotels across Mumbai.', 'Joyful, euphoric, highly festive family crowd.', 'Accept sweet white butter prasad with right hand; do not carry bulky backpacks into crowded midnight shrines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('ganesh-chaturthi-pan-india', 'Ganesh Chaturthi', ARRAY['Vinayaka Chavithi', 'Ganeshotsav', 'Vinayagar Chaturthi']::TEXT[], 'RELIGIOUS_TEMPLE', 'Hinduism & Pan-Indian Cultural Heritage', 'The magnificent 10-day festival honoring Lord Ganesha, the remover of obstacles, celebrated with clay murtis and monumental Visarjan processions.', 'Celebrated since antiquity; transformed into a massive public social movement by freedom fighter Lokmanya Bal Gangadhar Tilak in Pune in 1893.', 'Celebrates the rebirth and earthly arrival of Ganesha, created by Goddess Parvati and granted the supreme boon of prior worship.', 'To invoke divine wisdom, remove obstacles before new ventures, celebrate artistic creativity, and foster patriotic community unity.', 'Artistic brilliance, community solidarity, thunderous drumming, joyous hospitality, and poignant farewell.', 'Tilak used public Sarvajanik Ganeshotsav to unite all strata of Indian society against colonial British rule, forging modern community festivals.', ARRAY['Prana Pratishtha (invoking the divine spirit into clay idol)', 'Shodashopachara worship with 21 blades of Durva grass and red Hibiscus flowers', 'Offering 21 sweet Modaks to the deity', 'Anant Chaturdashi Visarjan (grand musical immersion procession into the sea)']::TEXT[], 'Every neighborhood constructs grand artistic pandals; millions welcome eco-friendly clay Ganeshas into their homes before dancing to the sea.', ARRAY['Ukadiche Modak (steamed rice-flour dumplings stuffed with fresh coconut and jaggery)', 'Fried Modak', 'Puran Poli', 'Sundal', 'Sheera']::TEXT[], 'Traditional Maharashtrian attire: women in Navvari nine-yard sarees with pearl nose pins (Nath); men in Kurta-Pajama with saffron Feta turbans.', 'Thunderous beats of Dhol-Tasha pathak troupes, Lezim folk dance clanking, conch shells, and the roaring chant ''Ganpati Bappa Morya!''', ARRAY['Ganesha clay idol', 'Ukadiche Modak', 'Durva grass blades', 'Red Hibiscus (Jaswand) flower', 'Dhol drum']::TEXT[], '10 Days (commencing Ganesh Chaturthi to Anant Chaturdashi)', 'Hindu Luni-Solar Calendar (Bhadrapada Shukla Chaturthi)', 'Begins on the fourth day of the waxing moon of Bhadrapada (August/September) and ends on the 14th day (Anant Chaturdashi).', 'September', 'LUNISOLAR', 'Bhadrapada Shukla Chaturthi to Anant Chaturdashi', '2026-09-14 to 2026-09-24', '2027-09-04 to 2027-09-14', 'Rashtriya Panchang & Brihanmumbai Sarvajanik Ganeshotsav Samiti', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Mumbai', 'Pune', 'Hyderabad', 'Bengaluru', 'Goa', 'Chennai']::TEXT[], ARRAY['Lalbaugcha Raja Pandal Mumbai', 'Girgaon Chowpatty Mumbai (Visarjan)', 'Shreemant Dagdusheth Halwai Temple Pune', 'Khairatabad Hyderabad']::TEXT[], 'Morning darshan at Lalbaugcha Raja, and the final day (Anant Chaturdashi) from 2:00 PM to midnight at Girgaon Chowpatty for the sea immersion.', 4, 'Earth-shaking percussive euphoria: watching 200 youths in orange turbans play massive brass-ringed Dhol drums in rhythm while millions cheer ''Pudhchya Varshi Laukariya!''', 'Mumbai local trains run all night on Visarjan day; coastal roads pedestrianized for processions.', 'Hotels in Mumbai (South Mumbai or central suburbs) and Pune.', 'Millions of ecstatic, disciplined, family-friendly celebrants.', 'Offer Durva grass in bunches of 21; do not wear footwear inside pandals; opt for eco-friendly clay idols.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('durga-puja-navratri-pan-india', 'Sharad Navratri & Durga Puja', ARRAY['Navaratri', 'Dussehra', 'Vijayadashami', 'Durgotsav']::TEXT[], 'RELIGIOUS_TEMPLE', 'Shaktism / Hinduism (UNESCO Intangible Cultural Heritage)', 'India''s grand 10-day celebration of the Divine Mother (Durga) vanquishing Mahishasura, featuring public art pandals and Garba circle dances.', 'Celebrated since antiquity; Durga Puja in Kolkata was inscribed on the UNESCO Intangible Cultural Heritage of Humanity list in 2021.', 'Durga''s nine divine forms (Navadurga) vanquishing the buffalo-demon Mahishasura over nine epic battles; in North India, Lord Rama slaying Ravana on Dussehra.', 'To celebrate the victory of cosmic righteousness (Dharma) over tyranny, invoke feminine strength (Shakti), and celebrate art and dance.', 'Unrivaled artistic installation architecture, vibrant musical ecstasy, collective feminine celebration, and joyous cultural inclusivity.', 'Kolkata transforms into the world''s largest open-air contemporary art biennial, while Gujarat hosts the world''s longest dance festival with Garba.', ARRAY['Bodhon (awakening of the goddess on Shasthi)', 'Nabapatrika Snan (bathing of nine sacred plants on Saptami)', 'Sandhi Puja at the transition between Ashtami and Navami with 108 lotus flowers', 'Dhunuchi Naach dance with smoking clay censers to frantic Dhaak drum beats', 'Sindoor Khela (married women smearing vermilion on Dashami)', 'Burning of 100-foot Ravana effigies on Dussehra']::TEXT[], 'Millions in Kolkata go ''pandal hopping'' all night; millions in Gujarat dance Garba and Dandiya until dawn in illuminated stadiums.', ARRAY['Khichuri Bhog with Labra and Chutney', 'Mishti Doi', 'Rosogolla', 'Kolkata Egg Roll', 'Fafda and Jalebi on Dussehra']::TEXT[], 'Traditional elegance: women in red-and-white border Lal Paar sarees or dazzling mirror-work Chaniya Cholis; men in Kurta and Dhoti.', 'Thunderous Dhaak drums of Bengal with Kasor gong, energetic Dhol beats of Garba, and conch shells.', ARRAY['Durga idol slaying Mahishasura with trident', 'Dhunuchi smoking clay burner', 'Dhaak feather-trimmed drum', 'Garba earthen pierced pot with lamp']::TEXT[], '10 Days', 'Hindu Luni-Solar Calendar (Ashwin Shukla Pratipada to Dashami)', 'Begins on the first lunar day of the bright fortnight of Ashwin (September/October), culminating on Vijayadashami.', 'October', 'LUNISOLAR', 'Ashwin Shukla Pratipada to Dashami', '2026-10-11 to 2026-10-20', '2027-10-01 to 2027-10-10', 'UNESCO Intangible Cultural Heritage Registry & Rashtriya Panchang', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Kolkata', 'Ahmedabad', 'Vadodara', 'Delhi', 'Mysuru', 'Varanasi']::TEXT[], ARRAY['Maddox Square, Bagbazar & College Square Pandals Kolkata', 'GMDC Ground Ahmedabad', 'Mysuru Palace Grounds (Mysuru Dasara)']::TEXT[], 'Late night (8:00 PM to 3:00 AM) in Kolkata for pandal hopping; evening 9:00 PM to 2:00 AM in Ahmedabad for Garba dancing.', 5, 'Sensory overload of the best kind: walking through miles of astonishing public art pavilions in Kolkata, surrounded by fragrant smoke, smiling crowds, and the primal thunder of Dhaak drums.', 'Kolkata Metro runs overnight during Puja; dedicated app cabs and auto services.', 'Hotels across Kolkata and Ahmedabad book out months in advance.', 'Millions of joyful, polite, culturally sophisticated revelers.', 'Pandal hopping requires extensive walking: wear comfortable shoes; queue patiently; dress stylishly yet respectfully.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('raksha-bandhan-pan-india', 'Raksha Bandhan', ARRAY['Rakhi', 'Rakhi Purnima', 'Kajari Purnima']::TEXT[], 'FOLK_COMMUNITY', 'Hinduism & Pan-Indian Cultural Tradition', 'A beloved festival celebrating the sacred bond of mutual love, protection, and trust between brothers and sisters with ceremonial threads.', 'Celebrated since antiquity; referenced in the Mahabharata when Draupadi tied a strip of her silk saree to Lord Krishna''s bleeding finger.', 'Historically used as a symbol of protection and covenant; Rabindranath Tagore popularized mass Rakhi tying during the 1905 Partition of Bengal to foster Hindu-Muslim brotherhood.', 'To reaffirm lifelong love and protection between siblings, pray for each other''s prosperity, and exchange thoughtful gifts.', 'Pure filial love, mutual protection, familial bonding, sweet nostalgia, and social harmony.', 'Tagore transformed Rakhi into a powerful socio-political instrument of non-violent anti-colonial solidarity and communal harmony in Bengal.', ARRAY['Sister applying vermilion tilak and unbroken rice (Akshat) on brother''s forehead', 'Tying the decorative sacred thread (Rakhi) on his right wrist', 'Aarti performed with a brass lamp tray', 'Feeding the brother sweets with prayers for his long life', 'Brother presenting gifts and a pledge of lifelong support']::TEXT[], 'Families gather in the morning; markets overflow with thousands of varieties of decorative Rakhi threads; sisters feed brothers sweets.', ARRAY['Ghevar (disc-shaped sweet from Rajasthan)', 'Kaju Katli', 'Rasgulla', 'Besan Ladoo', 'Peda', 'Chivda']::TEXT[], 'New festive traditional clothes: sisters in vibrant sarees or Anarkali suits; brothers in Kurta-Pajama.', 'Classic sibling celebration songs, acoustic shehnai, and family laughter.', ARRAY['Decorative Rakhi thread', 'Puja Thali with Roli and Akshat', 'Ghevar honeycomb sweet', 'Tied wrist with red thread']::TEXT[], '1 Day', 'Hindu Luni-Solar Calendar (Shravana Purnima)', 'Celebrated on the full moon day (Purnima) of the holy Hindu month of Shravana (August).', 'August', 'LUNISOLAR', 'Shravana Purnima (full moon of Shravana month)', '2026-08-28', '2027-08-17', 'Rashtriya Panchang & Government of India Gazetted Holiday Calendar', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Delhi', 'Jaipur', 'Lucknow', 'Kolkata', 'Mumbai', 'Patna', 'Indore']::TEXT[], ARRAY['Homes and family gatherings across India', 'Postal counters delivering Rakhis across borders']::TEXT[], 'Morning auspicious Muhurat (between 9:00 AM and 1:30 PM) for the Rakhi tying ceremony.', 1, 'Touching domestic warmth: witnessing sisters lovingly tie shimmering threads on brothers'' wrists while sharing plates of golden Ghevar sweets.', 'Heavy inter-city and suburban transit demand as siblings travel to meet; plan morning transport early.', 'Hotels across all major Indian cities.', 'Gentle domestic celebrations in homes; bustling sweet and gift markets.', 'Tie Rakhi on the right wrist; brothers should present gifts with both hands; accept sweets with right hand.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('eid-ul-fitr-pan-india', 'Eid-ul-Fitr', ARRAY['Meethi Eid', 'Ramzan Eid', 'Eid-al-Fitr']::TEXT[], 'RELIGIOUS_TEMPLE', 'Islam & Composite Indian Ganga-Jamuni Tehzeeb', 'The joyful festival of breaking the Ramadan fast, celebrated with congregational Eid prayers, charity (Zakat), hugs, and sweet Sheer Khurma.', 'Celebrated by India''s 200 million Muslims since the advent of Islam in the 7th century; integrated deeply into India''s syncretic culture.', 'Marks the conclusion of the holy month of Ramadan, during which the Quran was revealed to Prophet Muhammad, and believers observed dawn-to-dusk fasting.', 'To thank Allah for spiritual strength during fasting, dispense charity to the needy (Fitrana), forgive past grudges, and share joy.', 'Spiritual gratitude, boundless charity, communal fraternity, universal forgiveness, and gastronomic celebration.', 'Historic congregational prayers at Delhi''s Jama Masjid, Taj Mahal, and Lucknow''s Asifi Imambara showcase India''s magnificent Islamic architectural heritage.', ARRAY['Dispensing Fitrana charity before the morning prayer', 'Attending the massive Eid-ul-Fitr Namaz at historic Eidgahs and mosques', 'Exchanging warm threefold fraternal hugs (Eid Mubarak)', 'Children receiving Eidi (cash gifts and blessings from elders)', 'Serving Sheer Khurma to visiting neighbors of all faiths']::TEXT[], 'Historic old quarters of Delhi, Hyderabad, and Lucknow are draped in lights; millions gather in pristine white kurtas for prayers, followed by day-long open-house feasts.', ARRAY['Sheer Khurma (sweet vermicelli milk pudding with dates and pistachios)', 'Seviyan (vermicelli dessert)', 'Hyderabadi and Lucknowi Dum Biryani', 'Mutton Korma', 'Shami Kebab', 'Nalli Nihari']::TEXT[], 'Pristine white Kurta-Pajama with embroidered Chikankari or gold-trimmed Nehru jackets; skullcaps (Topi); women in exquisite pastel Anarkali and Sharara suits with henna (Mehndi).', 'Soulful Sufi Qawwalis, Naat poetry, shehnai melodies, and cheerful greetings of ''Eid Mubarak!''.', ARRAY['Crescent Moon (Hilal)', 'Bowl of Sheer Khurma', 'Intricate Mehndi henna designs on palms', 'Historic mosque minaret silhouette']::TEXT[], '1 to 3 Days', 'Islamic Hijri Lunar Calendar (Shawwal 1)', 'Begins upon the sighting of the new crescent moon on the final evening of Ramadan, marking the first day of Shawwal.', 'March', 'LUNAR', 'First day of Shawwal following moon sighting (Ruyat-e-Hilal)', '2026-03-20 to 2026-03-21', '2027-03-10 to 2027-03-11', 'Central Moon Sighting Committee & Government of India Gazetted Holidays', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Delhi', 'Hyderabad', 'Lucknow', 'Mumbai', 'Kolkata', 'Srinagar', 'Bhopal']::TEXT[], ARRAY['Jama Masjid Old Delhi', 'Charminar & Mecca Masjid Hyderabad', 'Aasifi Imambara Eidgah Lucknow', 'Taj Mahal Mosque Agra']::TEXT[], 'Morning 7:30 AM to 9:30 AM for the awe-inspiring congregational Eid prayers at Jama Masjid or Charminar.', 2, 'Breathtaking visual harmony: tens of thousands of worshippers bowing in absolute unison on the stone courtyards of historic mosques under the morning sun, followed by warm embraces.', 'Roads around major Eidgahs and grand mosques are pedestrianized during morning prayer hours; metro rail services run smoothly.', 'Heritage hotels in Old Delhi (Chandni Chowk), Charminar Hyderabad, and Lucknow.', 'Enormous, peaceful, highly disciplined, and welcoming crowds.', 'Dress modestly in traditional attire; remove footwear before stepping onto mosque courtyards; accept Sheer Khurma graciously.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('eid-ul-adha-pan-india', 'Eid-ul-Adha', ARRAY['Bakrid', 'Eid-al-Adha', 'Feast of the Sacrifice']::TEXT[], 'RELIGIOUS_TEMPLE', 'Islam & Pan-Indian Cultural Observance', 'The Feast of Sacrifice honoring Prophet Ibrahim''s willingness to sacrifice his son in obedience to God, observed with prayers and charity.', 'Celebrated for over 1,400 years; coincides with the culmination of the annual Hajj pilgrimage to the holy city of Mecca.', 'Commemorates Prophet Ibrahim (Abraham) whose devotion was tested by God, who miraculously replaced his son Ismail with a ram at the point of sacrifice.', 'To submit to divine will, practice selfless charity, ensure no poor person goes hungry, and celebrate brotherhood.', 'Supreme self-sacrifice, submission to God, generous sharing of meat with the underprivileged, and hospitality.', 'The meat of the sacrifice is strictly divided into three equal portions: one-third for the family, one-third for relatives and friends, and one-third for the poor.', ARRAY['Special morning Eid-ul-Adha congregational prayers at Eidgahs', 'Ritual sacrifice (Qurbani) of goat or sheep performed humanely according to Islamic law', 'Three-way division and distribution of meat to the needy', 'Visiting elder relatives and sharing festive lunches']::TEXT[], 'Worshippers dress in festive attire, attend morning sermon and prayer, perform the Qurbani, and distribute meat packets to the underprivileged across the neighborhood.', ARRAY['Mutton Biryani', 'Galouti Kebab', 'Nalli Nihari', 'Mutton Rogan Josh', 'Sheer Khurma', 'Shahi Tukda']::TEXT[], 'Fine handloom Kurta-Pajamas, Pathani suits, embroidered waistcoats, and traditional caps; women in elegant salwar kameez with delicate jewelry.', 'Sufi devotional singing, recitation of the Takbir Tashriq, and warm family conversation.', ARRAY['Crescent and star', 'Traditional weighing scale of charity', 'Festive silver tray of Biryani', 'Eidgah archway']::TEXT[], '3 Days', 'Islamic Hijri Lunar Calendar (Dhu al-Hijjah 10)', 'Falls on the tenth day of the Islamic lunar month of Dhu al-Hijjah, concluding the Hajj pilgrimage.', 'May', 'LUNAR', '10th day of Islamic month Dhu al-Hijjah', '2026-05-27 to 2026-05-29', '2027-05-17 to 2027-05-19', 'Central Moon Sighting Committee & Government of India Gazetted Holiday List', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Delhi', 'Hyderabad', 'Lucknow', 'Mumbai', 'Kozhikode', 'Bhopal']::TEXT[], ARRAY['Old Delhi Jama Masjid', 'Mecca Masjid Hyderabad', 'Eidgah Lucknow', 'Nakhoda Mosque Kolkata']::TEXT[], 'Morning 8:00 AM for the serene Eid prayer and sermon at major historic Eidgahs.', 2, 'Profound lesson in charity and sharing: witnessing extensive community food networks ensuring every underprivileged home receives fresh meat and feast delicacies.', 'Accessible across all Indian cities; private transport recommended during post-prayer family visits.', 'Hotels across major urban hubs.', 'Solemn, dignified, generous, and community-centered.', 'Show sensitivity around designated animal sacrifice areas; participate warmly in shared meals if invited.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('guru-nanak-gurpurab-pan-india', 'Guru Nanak Jayanti', ARRAY['Gurpurab', 'Guru Nanak Prakash Utsav']::TEXT[], 'RELIGIOUS_TEMPLE', 'Sikhism & Universal Humanist Heritage', 'The sacred celebration of the birth of Guru Nanak Dev Ji, founder of Sikhism, marked by Prabhat Pheris, Akhand Path, and 24-hour Guru ka Langar.', 'Celebrated since the 15th century, honoring Guru Nanak (1469–1539 CE) who preached the oneness of God (''Ik Onkar'') and universal equality of humankind.', 'Guru Nanak was born at Rai Bhoi di Talwandi (Nankana Sahib); his teachings rejected caste distinctions, superstition, and religious intolerance.', 'To honor the founder of Sikhism, reflect on his teachings of selfless service (Seva), honest labor (Kirat Karo), and sharing with others (Vand Chhako).', 'Selfless service, humility, universal brotherhood, devotional singing, and boundless hospitality at Langar.', 'The Golden Temple (Sri Harmandir Sahib) in Amritsar is illuminated with 100,000 lamps and fireworks, creating one of the most sublime sights in Asia.', ARRAY['Akhand Path (continuous 48-hour unbroken reading of Sri Guru Granth Sahib Ji)', 'Prabhat Pheri (early morning singing processions through neighborhood lanes)', 'Nagar Kirtan (grand devotional street parade led by the Panj Pyare and Nishan Sahib)', 'Gatka (traditional Sikh martial arts) demonstrations', 'Guru ka Langar serving free hot meals to all people irrespective of religion or status']::TEXT[], 'Gurdwaras are illuminated with lights; millions sit side-by-side on the floor sharing hot daal and rotis; fireworks light up the night sky at Amritsar.', ARRAY['Guru ka Langar mahaprasad: Dal Makhani, Langar wali Daal, hot Rotis, mixed sabzi, Rice, and warm Karah Parshad (sacred wheat halwa made with pure ghee)']::TEXT[], 'Traditional Sikh attire: men in Kurta-Pajama with colorful Turbans (Dastar); women in elegant Salwar-Kameez with dupatta covering heads.', 'Sublime Gurbani Kirtan sung with harmonium, tabla, rabab, and dilruba, filling gurdwaras with divine peace.', ARRAY['Khanda emblem', 'Nishan Sahib triangular saffron flag', 'Karah Parshad halwa', 'Illuminated Golden Temple reflecting in Sarovar']::TEXT[], '3 Days (preceded by 48-hour Akhand Path)', 'Hindu/Sikh Luni-Solar Calendar (Kartika Purnima)', 'Celebrated on the full moon day (Purnima) of the month of Kartika (October/November).', 'November', 'LUNISOLAR', 'Kartika Purnima (full moon of Kartika month)', '2026-11-24', '2027-11-14', 'Shiromani Gurdwara Parbandhak Committee (SGPC) & Govt of India Holiday Calendar', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Amritsar', 'Delhi', 'Anandpur Sahib', 'Patna', 'Nanded', 'Chandigarh']::TEXT[], ARRAY['Sri Harmandir Sahib (Golden Temple) Amritsar', 'Gurdwara Bangla Sahib Delhi', 'Takht Sri Patna Sahib', 'Gurdwara Sis Ganj Sahib Delhi']::TEXT[], 'Dusk to 10:00 PM at the Golden Temple Amritsar to witness the breathtaking deepmala illumination and fireworks reflecting in the sacred pool.', 2, 'Life-affirming experience of unconditional human equality: sitting on the marble floor of a gurdwara eating piping hot Karah Parshad amidst heavenly Gurbani hymns.', 'Amritsar is connected by international airport and high-speed Vande Bharat trains; free SGPC shuttle buses operate from the station to the Golden Temple.', 'SGPC Sarai guest houses and hotels near the Golden Temple Amritsar.', 'Vast, peaceful, deeply devoted, and exceptionally organized crowds.', 'Cover your head with a scarf or rumal before entering gurdwara premises; wash feet at the water trough; strictly no tobacco or alcohol permitted anywhere near gurdwaras.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('mahavir-jayanti-pan-india', 'Mahavir Jayanti', ARRAY['Mahavira Janma Kalyanak']::TEXT[], 'RELIGIOUS_TEMPLE', 'Jainism & Ancient Shramana Heritage', 'The most auspicious festival of Jainism celebrating the birth of Bhagwan Mahavira, the 24th Tirthankara, with solemn chariot processions and Ahimsa.', 'Celebrated since the 6th century BCE, commemorating the birth of Vardhamana Mahavira in Kundalpur/Vaishali in Bihar.', 'Born to King Siddhartha and Queen Trishala; renounced royal luxury at age 30 to attain Kevala Jnana (omniscience) and formulate the vows of Ahimsa (non-violence).', 'To honor the prophet of universal compassion, practice strict non-violence toward all living beings, and reflect on Truth (Satya) and Non-possession (Aparigraha).', 'Supreme non-violence (Ahimsa Paramo Dharma), forgiveness, detachment, peace, and spiritual asceticism.', 'Mahavira''s teachings on absolute non-violence influenced Mahatma Gandhi and shaped India''s core civilizational ethos.', ARRAY['Abhisheka of Mahavira idols with fragrant water and milk', 'Rath Yatra (grand silent procession carrying the Tirthankara murti in a silver chariot)', 'Recitation of sacred Navkar Mantra and Jain scriptures', 'Charity drives feeding animals, birds, and supporting orphanages']::TEXT[], 'Jains visit marble temples adorned with flags, listen to sermons on compassion, give alms to the needy, and release birds from cages.', ARRAY['Strictly vegetarian Jain sattvic food (no root vegetables, onions, or garlic): Dal Baati Churma, Moong Dal Halwa, Puri with Aloo-free curry, and sweet Kheer']::TEXT[], 'Pure white traditional attire: men in white Kurta-Dhoti; women in white or yellow sarees with gold trims.', 'Soulful Navkar Mantra chanting, traditional Jain Stavans sung with harmonium, and soft temple cymbals.', ARRAY['Jain Prateek Ahimsa Hand symbol with wheel', 'Ashtamangala symbols', 'Silver chariot (Rath)', 'Swastika with three dots and crescent']::TEXT[], '1 Day', 'Jain Luni-Solar Calendar (Chaitra Shukla Trayodashi)', 'Celebrated on the 13th day of the waxing moon of the Hindu month of Chaitra (March/April).', 'March', 'LUNISOLAR', 'Chaitra Shukla Trayodashi (13th day of bright fortnight of Chaitra)', '2026-03-31', '2027-04-19', 'Jain Mahasabha & Government of India Gazetted Holiday List', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Vaishali', 'Pawapuri', 'Palitana', 'Ranakpur', 'Shravanabelagola', 'Delhi', 'Jaipur']::TEXT[], ARRAY['Dilwara Temples Mount Abu', 'Ranakpur Jain Temple', 'Palitana Shatrunjaya Hill Gujarat', 'Shravanabelagola Karnataka']::TEXT[], 'Morning 8:00 AM to 11:30 AM for the grand silver chariot procession and abhisheka ceremony.', 1, 'An oasis of serenity: admiring the breathtaking filigree marble carvings of Jain temples while listening to peaceful chants preaching peace to all creatures.', 'Accessible in all major cities; pilgrimage centers like Ranakpur and Palitana reached via Udaipur and Ahmedabad.', 'Jain Dharamshalas and tourist hotels in pilgrimage towns.', 'Serene, peaceful, dignified, and highly charitable.', 'No leather items (belts, wallets, bags) permitted inside Jain temple sanctums; follow strict vegetarian and non-violence norms.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('buddha-purnima-pan-india', 'Buddha Purnima', ARRAY['Vesak', 'Buddha Jayanti']::TEXT[], 'RELIGIOUS_TEMPLE', 'Buddhism & Pan-Asian Peace Heritage', 'The triple-blessed full moon day celebrating the Birth, Enlightenment, and Mahaparinirvana of Gautama Buddha with prayer flags and meditation.', 'Celebrated across Buddhist nations for over 2,500 years; recognized internationally by the United Nations as the Day of Vesak.', 'Prince Siddhartha Gautama was born in Lumbini, attained Supreme Enlightenment under the Bodhi Tree in Bodh Gaya, and entered Parinirvana in Kushinagar, all on the same full moon day.', 'To honor the Awakened One, practice the Noble Eightfold Path, meditate for inner peace, and spread loving-kindness (Metta) to all beings.', 'Supreme compassion, mindfulness, non-violence, meditation, and harmony among all faiths.', 'Bodh Gaya''s Mahabodhi Temple (UNESCO World Heritage Site) is the supreme pilgrimage center of world Buddhism.', ARRAY['Bathing the sacred Bodhi Tree at Bodh Gaya with scented water', 'Lighting thousands of earthen and butter lamps around the Mahabodhi Mahavihara', 'Silent Vipassana meditation sessions at dawn', 'Monastic chants of the Dhammacakkappavattana Sutta by monks from Sri Lanka, Japan, Thailand, Tibet, and Myanmar']::TEXT[], 'Monks in diverse robes (Theravada saffron, Tibetan maroon, Zen black) gather under the sacred Bodhi tree; peace processions wind through pilgrimage towns.', ARRAY['Strictly vegetarian sattvic fare', 'Kheer (sweet rice pudding reminiscent of the kheer offered by Sujata to the Buddha)', 'Fresh fruits and tea']::TEXT[], 'Pure white clothing symbolizing peace and purity; Buddhist monks in traditional robes.', 'Deep harmonic chanting of the Triple Gem (''Buddham Saranam Gacchami''), gentle ringing of temple gongs, and serene silence.', ARRAY['Dharmachakra (Eight-spoked Wheel of Law)', 'Bodhi Tree leaf', 'Lotus blossom', 'Five-coloured Buddhist flag']::TEXT[], '1 Day', 'Luni-Solar Calendar (Vaisakha Purnima)', 'Falls on the full moon day of the Hindu/Buddhist month of Vaisakha (April/May).', 'May', 'LUNISOLAR', 'Vaisakha Purnima (full moon of Vaisakha month)', '2026-05-31', '2027-05-20', 'Bodh Gaya Temple Management Committee (BTMC) & Govt of India Holidays', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Bodh Gaya', 'Sarnath', 'Kushinagar', 'Dharamshala', 'Gangtok', 'Ladakh']::TEXT[], ARRAY['Mahabodhi Temple Complex Bodh Gaya (UNESCO Site)', 'Dhamek Stupa Sarnath', 'Tsuglagkhang Temple McLeod Ganj']::TEXT[], 'Dawn (5:30 AM) for sunrise meditation beneath the sacred Bodhi Tree, and dusk (6:30 PM) when thousands of butter lamps illuminate the stone temple.', 2, 'Unrivaled spiritual serenity: sitting silently in the cool evening breeze beneath the actual descendant of the sacred tree where the Buddha sat 2,500 years ago.', 'Gaya International Airport is 12 km from Bodh Gaya; trains connect Gaya Junction to Kolkata, Delhi, and Varanasi.', 'Boutique heritage hotels and international Buddhist monastery guest houses in Bodh Gaya.', 'Serene, contemplative, international crowd of monks and seekers.', 'Maintain silence near the Bodhi Tree; remove shoes; walk clockwise around stupas and shrines.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('christmas-in-india', 'Christmas in India', ARRAY['Bada Din', 'Nativity Feast']::TEXT[], 'RELIGIOUS_TEMPLE', 'Christianity & Pan-Indian Cultural Celebration', 'A joyous celebration of the birth of Jesus Christ, marked by midnight masses in historic basilicas, illuminated streets, and plum cakes.', 'Celebrated in India since the arrival of Saint Thomas the Apostle in Kerala in 52 CE; celebrated with distinctive regional flavors across India.', 'Celebrates the birth of Jesus Christ in Bethlehem to Virgin Mary; embraces unique Indian traditions like star lanterns and mango-tree decorations.', 'To celebrate the incarnation of Christ, spread peace and goodwill, share festive meals with friends of all communities, and exchange gifts.', 'Warmth, peace on earth, boundless charity, joyful caroling, and glowing winter illumination.', 'Goa''s Se Cathedral and Basilica of Bom Jesus, Kerala''s ancient Syrian churches, and Kolkata''s historic Park Street host legendary celebrations.', ARRAY['Decorating houses with glowing paper Christmas Star lanterns', 'Midnight Mass in heritage cathedrals with choral hymns in English, Hindi, Konkani, and Malayalam', 'Blessing the Nativity Crib (crib displays depicting the Bethlehem manger)', 'Exchanging rich dark plum cakes and sweets with neighbors']::TEXT[], 'Kolkata''s Park Street transforms into an illuminated pedestrian carnival; Goa''s beach villages glow with star lanterns; choirs sing in mist-shrouded churches.', ARRAY['Traditional rich dark rum-soaked plum cake', 'Rose cookies (Achappam)', 'Goan pork vindaloo and sorpotel', 'Kulkuls sweet dough twists', 'Duck roast with appam in Kerala']::TEXT[], 'Finest winter festive attire: suits, evening gowns, crisp formal shirts; women in red-and-gold sarees or festive western wear.', 'Beloved Christmas carols (''Silent Night'', ''O Holy Night'') sung by magnificent four-part church choirs, brass bands, and acoustic guitars.', ARRAY['Paper Star lantern (Akashathara)', 'Nativity crib with infant Jesus', 'Decorated Christmas tree', 'Rich plum cake']::TEXT[], '1 to 8 Days (Christmas Eve to New Year''s Day)', 'Solar Calendar (Fixed Date)', 'Celebrated strictly on December 25 annually (with Christmas Eve midnight masses on Dec 24).', 'December', 'FIXED', 'December 25 annually', '2026-12-24 to 2026-12-26', '2027-12-24 to 2027-12-26', 'Catholic Bishops'' Conference of India (CBCI) & Govt of India Holiday Calendar', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Kolkata', 'Goa', 'Kochi', 'Shillong', 'Mumbai', 'Kohima', 'Bengaluru']::TEXT[], ARRAY['Park Street Kolkata', 'Basilica of Bom Jesus Old Goa', 'St. Paul''s Cathedral Kolkata', 'Mount Mary Church Bandra Mumbai']::TEXT[], 'Midnight (11:30 PM on Dec 24) for the cathedral Midnight Mass; evening on Dec 25 for the festive carnival on Kolkata''s Park Street.', 3, 'Enchanting winter celebration: walking down Kolkata''s dazzling fairy-lit Park Street listening to live jazz carols while eating freshly baked fruitcake from Flurys.', 'Park Street in Kolkata is pedestrianized; transport runs late in Goa, Mumbai, and Kolkata.', 'Hotels in central Kolkata (Park Street), Panaji/Baga in Goa, and Fort Kochi.', 'Cosmopolitan, joyous, festive, family and music-loving crowd.', 'Dress semi-formally for midnight cathedral services; maintain respectful silence during the consecration rites.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('makar-sankranti-pan-india', 'Makar Sankranti', ARRAY['Uttarayan', 'Maghi', 'Khichdi', 'Sankranthi']::TEXT[], 'HARVEST_SEASONAL', 'Solar Astronomy & Pan-Indian Harvest Tradition', 'The pan-Indian solar harvest festival marking the transition of the Sun into Capricorn (Makara) and the northward journey (Uttarayan) with kite flying.', 'Celebrated since antiquity; uniquely based on solar astronomical transit (Sankranti) rather than lunar tithi.', 'Astronomical moment when the sun moves into the northern celestial hemisphere (Makara Rashi), signaling longer days, warmth, and harvest bounty.', 'To thank the Sun God (Surya), celebrate the winter grain harvest, fly kites in the warm sunshine, and eat sesame-jaggery sweets.', 'Warm sunshine, celestial alignment, sportsmanship of aerial kite duels, sharing of sweetness, and holy river ablution.', 'Gujarat hosts the International Kite Festival; millions bathe at the sacred Sangam in Prayagraj for the sacred Magh Mela.', ARRAY['Early morning holy dip in sacred rivers (Ganga, Yamuna, Godavari)', 'Offering water (Arghya) and sesame seeds to the rising Sun', 'Flying kites from rooftops from dawn to dusk (Uttarayan in Gujarat)', 'Exchanging Til-Gul sweets with the blessing ''Til-Gul Ghya, God-God Bola'' (Accept sesame-jaggery and speak sweetly)']::TEXT[], 'Rooftops in Ahmedabad and Jaipur erupt with shouts of ''Kai Po Che!'' as millions of colorful kites battle in the sky; bonfires lit in Punjab (Lohri).', ARRAY['Til ke Ladoo (sesame jaggery sweets)', 'Khichdi cooked with fresh new rice, lentils, vegetables, and pure desi ghee', 'Undhiyu (Gujarat seasonal pot stew) with Jalebi', 'Gajak and Chikki']::TEXT[], 'Comfortable cotton Kurtas, sunglasses, and caps for day-long rooftop kite flying.', 'High-energy rooftop party music, dhol beats, festive folk songs, and the soaring cry ''Kai Po Che!'' echoing over city skylines.', ARRAY['Diamond paper kite (Patang) and spool (Firki)', 'Til-Gul sweet balls', 'Sun chariot (Surya Ratha)', 'Steaming pot of Khichdi']::TEXT[], '1 to 4 Days (coinciding with Lohri, Pongal, and Magh Bihu)', 'Solar Calendar (Fixed Date Window)', 'Occurs on January 14 or 15 annually when the Sun enters Makara Rashi.', 'January', 'SOLAR', 'Sun transit into Makara Rashi (January 14/15 annually)', '2026-01-14 to 2026-01-15', '2027-01-14 to 2027-01-15', 'Rashtriya Panchang & Gujarat Tourism', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Ahmedabad', 'Jaipur', 'Prayagraj', 'Varanasi', 'Surat', 'Patna', 'Hyderabad']::TEXT[], ARRAY['Sabarmati Riverfront Ahmedabad', 'Triveni Sangam Prayagraj', 'Rooftops of Old Ahmedabad and Jaipur']::TEXT[], 'All day on January 14 from sunrise to sunset on an old-city rooftop in Ahmedabad or Jaipur, followed by nighttime illuminated lantern kites (Tukkals).', 2, 'Unrivaled rooftop energy: looking up at an azure sky filled with tens of thousands of dancing kites while delicious winter Undhiyu and jalebi are served on the terrace.', 'Advance booking for Ahmedabad and Jaipur; rooftop homestays provide the best immersion.', 'Heritage havelis in the Old City of Ahmedabad or hotels in Jaipur.', 'Rooftop-based family and youth celebrations; open-air festival grounds.', 'Never use harmful glass-coated nylon strings (Chinese manjha); use cotton string; watch foot placement near rooftop edges.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.festivals_master (id, name, alternate_names, category, religious_or_cultural_association, short_description, historical_background, origin_and_traditional_stories, why_celebrated, cultural_and_spiritual_significance, historical_significance, important_rituals, how_people_celebrate, traditional_food_and_sweets, traditional_clothing, music_dance_performances, important_symbols_and_decorations, typical_duration, calendar_system, date_calculation_rule, usual_month, date_type, date_rule, date_2026, date_2027, date_source, major_states, major_cities, famous_venues, best_time_to_visit, recommended_duration_days, tourist_experience, local_transportation, accommodation_considerations, crowd_and_safety, visitor_etiquette, accessibility_considerations, official_website, sources, data_confidence_status) VALUES ('muharram-ashura-pan-india', 'Muharram', ARRAY['Ashura', 'Yaum-e-Ashura']::TEXT[], 'RELIGIOUS_TEMPLE', 'Islam (Shia & Sunni Observance)', 'A solemn month of remembrance commemorating the martyrdom of Imam Hussain at the Battle of Karbala, observed with Majlis and Tazia processions.', 'Observed for over 1,300 years; commemorated in India with monumental Tazia bamboo-and-paper architectural shrines.', 'Commemorates the 680 CE martyrdom of Imam Hussain (grandson of Prophet Muhammad) and his 72 companions at Karbala defending justice and truth against tyranny.', 'To mourn the martyrs of Karbala, reflect on moral integrity against injustice, fast in atonement (Sunni tradition), and demonstrate communal solidarity.', 'Profound solemnity, grief, moral fortitude, ethical defiance against oppression, and selfless compassion.', 'Lucknow and Hyderabad host the world''s most intricate Tazia processions, where artists spend months building multi-tiered silver-and-paper mausoleum replicas.', ARRAY['Majlis (mourning congregations) reciting elegies (Marsiya and Soz) in Imambaras', 'Carrying intricate towering Tazia replicas in solemn street processions', 'Matam (ritual mourning expressions of grief)', 'Distributing free sweet water and milk drinks (Sabeel) to all passersby', 'Burial of Tazias at sacred Karbala burial grounds on Ashura']::TEXT[], 'Streets in old Lucknow, Delhi, and Hyderabad see silent, black-clad mourners carrying magnificent illuminated Tazias to Karbala grounds.', ARRAY['Haleem (slow-cooked wheat, meat, and lentil stew)', 'Tabarruk (blessed sweet bread and sherbet)', 'Khichda', 'Milk and rosewater sherbet from street Sabeels']::TEXT[], 'Solemn mourning attire: black or dark green Kurtas and Salwar-Kameez; mourners walk barefoot in processions.', 'Heartrending elegiac chants (Marsiya), rhythmic breast-beating chants of ''Ya Hussain!'', and solemn funeral drums.', ARRAY['Tazia architectural mausoleum replica', 'Alam (sacred standards/flags)', 'Zuljanah (ceremonial white horse)', 'Sabeel water cup']::TEXT[], '10 Days (culminating on the 10th day, Ashura)', 'Islamic Hijri Lunar Calendar (Muharram 10)', 'Falls on the 10th day of the first Islamic lunar month of Muharram.', 'June', 'LUNAR', '10th day of Muharram (Ashura)', '2026-06-25 to 2026-06-26', '2027-06-15 to 2027-06-16', 'Central Moon Sighting Committee & Government of India Gazetted Holidays', ARRAY['All States and Union Territories of India']::TEXT[], ARRAY['Lucknow', 'Hyderabad', 'Delhi', 'Amroha', 'Kolkata', 'Mumbai']::TEXT[], ARRAY['Bara Imambara & Chhota Imambara Lucknow', 'Karbala Talkatora Lucknow', 'Bibi Ka Alawa Hyderabad']::TEXT[], 'Ashura day (10th Muharram) from 10:00 AM to 4:00 PM for the historic Tazia processions in Old Lucknow.', 2, 'Deeply poignant and aesthetically profound: witnessing hundreds of magnificent handmade silver-and-paper Tazia monuments carried through the solemn, historic streets of Lucknow.', 'Roads in old quarters of Lucknow and Hyderabad are closed to vehicles during Tazia processions; walk on foot.', 'Hotels in Hazratganj Lucknow or central Hyderabad.', 'Solemn, deeply mourning, respectful, and dignified crowds.', 'Wear dark, conservative clothing (preferably black); maintain somber decorum; do not applaud or display overt festive cheer during processions.', 'Partially wheelchair accessible; assistance recommended for uneven heritage steps.', 'https://www.incredibleindia.gov.in', ARRAY['Ministry of Tourism, Government of India (Incredible India)', 'State Tourism Corporation', 'Archaeological & Cultural Survey of India']::TEXT[], 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();


-- 2. INSERT UNESCO WORLD HERITAGE
INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-taj-mahal', 'Taj Mahal', ARRAY['Taj', 'Rauza-i-Munawwara', 'Crown of the Palace']::TEXT[], 'Cultural', 'Uttar Pradesh', 'Agra', 'Agra', 1983, ARRAY['(i)']::TEXT[], 'Commissioned in 1631 by Mughal Emperor Shah Jahan to house the tomb of his favorite wife Mumtaz Mahal; completed in 1648 CE with surrounding gardens and outbuildings completed by 1653 CE.', 'Peak jewel of Indo-Islamic Mughal architecture utilizing pristine white Makrana marble with Pietra Dura pietra-inlay work, octagonal chamber, symmetrical minarets, and bulbous central dome.', 'Globally revered symbol of eternal devotion and the quintessential architectural icon of India.', 'Built by an estimated 20,000 artisans under chief architect Ustad Ahmad Lahori. Shah Jahan was later imprisoned in Agra Fort by his son Aurangzeb, gazing at the Taj across the Yamuna River.', ARRAY['Main Mausoleum', 'Charbagh Gardens', 'Mosque (Masjid)', 'Mehman Khana (Assembly Hall)', 'Jawab Gateway', 'Taj Museum']::TEXT[], 'Breathtaking symmetrical vistas, ethereal white marble changing hue with sunlight from golden at dawn to silver by moonlight.', 'October to March; sunrise and sunset provide the most photogenic views.', '3 to 4 hours', 'Agra Cantt Railway Station (AGC) - 6 km', 'Agra Kheria Airport (AGR) - 13 km; Indira Gandhi International Airport Delhi (DEL) - 220 km', ARRAY['Mathura (58 km)', 'Fatehpur Sikri (38 km)', 'Delhi (210 km)']::TEXT[], ARRAY['Agra Fort', 'Fatehpur Sikri', 'Itmad-ud-Daulah', 'Mehtab Bagh']::TEXT[], ARRAY['Fatehabad Road', 'Tajganj', 'Cantt Area']::TEXT[], ARRAY['Agra Petha (Angoori, Kesar)', 'Bedmi Puri with Aloo Sabzi', 'Mughlai Biryani', 'Dalmoth']::TEXT[], 'Battery-operated golf carts and electric eco-rickshaws connect outer security gates to entry gates; Yamuna Expressway connects directly from Delhi in 3 hours.', 27.1751, 78.0421, 'https://whc.unesco.org/en/list/252', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-agra-fort', 'Agra Fort', ARRAY['Red Fort of Agra', 'Qila-i-Akbari']::TEXT[], 'Cultural', 'Uttar Pradesh', 'Agra', 'Agra', 1983, ARRAY['(iii)']::TEXT[], 'Constructed in red sandstone by Emperor Akbar in 1565 CE on the banks of the Yamuna River; served as the primary imperial residence of Mughal emperors until 1638 CE.', 'Crescent-shaped fortress with 2.5 km long double walls of red sandstone rising 70 feet, integrating defensive bastions with delicate marble palaces.', 'Core epicenter of Mughal governance and monumental history for over a century.', 'Where Shah Jahan spent his final 8 years under house arrest in the Musamman Burj, observing the Taj Mahal.', ARRAY['Jahangiri Mahal', 'Khas Mahal', 'Sheesh Mahal', 'Diwan-i-Aam', 'Diwan-i-Khas', 'Musamman Burj', 'Moti Masjid']::TEXT[], 'Grand royal pavilions, panoramic views of the Yamuna and Taj Mahal, intricate sandstone carvings.', 'October to March', '2 to 3 hours', 'Agra Fort Railway Station (AF) - 1.5 km', 'Agra Airport - 8 km; Delhi International Airport - 215 km', ARRAY['Mathura', 'Fatehpur Sikri', 'Bharatpur']::TEXT[], ARRAY['Taj Mahal (2.5 km)', 'Jama Masjid Agra', 'Itmad-ud-Daulah']::TEXT[], ARRAY['Fatehabad Road', 'Agra Cantt']::TEXT[], ARRAY['Agra Petha', 'Bedmi Puri', 'Mughlai Kebabs']::TEXT[], 'Pre-paid taxis and auto-rickshaws available outside gate.', 27.1795, 78.0211, 'https://whc.unesco.org/en/list/251', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-ajanta-caves', 'Ajanta Caves', ARRAY['Ajanta Buddhist Rock-Cut Caves']::TEXT[], 'Cultural', 'Maharashtra', 'Chhatrapati Sambhajinagar (Aurangabad)', 'Lenapur / Aurangabad', 1983, ARRAY['(i)', '(ii)', '(iii)', '(vi)']::TEXT[], 'Rock-cut Buddhist cave monuments excavated in two phases: the early Hinayana phase (2nd century BCE to 1st century CE) and the Mahayana phase (5th century CE under the Vakatakas).', 'Horse-shoe shaped gorge along the Waghur River containing 30 rock-cut chaityas (prayer halls) and viharas (monasteries) adorned with masterwork fresco tempera paintings.', 'Crown zenith of classical ancient Indian painting and Buddhist sacred narrative art (Jataka tales).', 'Discovered by British cavalry officer John Smith in 1819 while hunting tigers along the ravine.', ARRAY['Cave 1 (Padmapani and Vajrapani Bodhisattvas)', 'Cave 2 (Ceiling Frescoes)', 'Cave 19 (Sculpted Chaitya)', 'Cave 26 (Colossal Reclining Buddha)']::TEXT[], 'Ancient serene monasteries carved out of sheer basalt rock, illuminated frescoes showing expressive royal and divine life.', 'November to March; monsoon season (July to September) reveals lush green waterfalls.', '4 to 6 hours', 'Jalgaon Railway Station - 60 km; Aurangabad Railway Station - 100 km', 'Chhatrapati Sambhajinagar Airport (IXU) - 105 km', ARRAY['Chhatrapati Sambhajinagar (Aurangabad)', 'Jalgaon', 'Bhusawal']::TEXT[], ARRAY['Ellora Caves (100 km)', 'Daulatabad Fort', 'Bibi Ka Maqbara']::TEXT[], ARRAY['Fardapur (MTDC Resort)', 'Aurangabad City']::TEXT[], ARRAY['Naan Qalia', 'Maharashtrian Thali', 'Pithla Bhakri', 'Puran Poli']::TEXT[], 'MSRTC green electric shuttle buses operate from T-point parking to the cave foot entrance.', 20.5519, 75.7033, 'https://whc.unesco.org/en/list/242', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-ellora-caves', 'Ellora Caves', ARRAY['Verul Leni', 'Elapura']::TEXT[], 'Cultural', 'Maharashtra', 'Chhatrapati Sambhajinagar (Aurangabad)', 'Verul / Aurangabad', 1983, ARRAY['(i)', '(iii)', '(vi)']::TEXT[], 'Complex of 34 major rock-cut monasteries and temples excavated sequentially between 600 and 1000 CE under the Rashtrakuta and Yadava dynasties.', 'Harmonious coexistence of 12 Buddhist, 17 Hindu, and 5 Jain monuments side-by-side; contains Cave 16 (Kailasa Temple), the largest monolithic rock excavation on Earth carved top-down from a single cliff.', 'Demonstrates ancient India''s supreme spirit of religious tolerance and architectural daring.', 'Kailasa Temple was commissioned by Rashtrakuta King Krishna I (c. 756-773 CE). Over 200,000 tonnes of basalt were chiselled out without cranes or mortar.', ARRAY['Cave 16 (Kailasa Temple)', 'Cave 10 (Vishvakarma Carpenter''s Cave)', 'Cave 15 (Dashavatara Cave)', 'Cave 32 (Indra Sabha)']::TEXT[], 'Awe-inspiring view of multi-storey rock-carved pavilions, monolithic elephants, and mythological friezes.', 'October to March', '4 to 5 hours', 'Aurangabad Railway Station (AWB) - 30 km', 'Chhatrapati Sambhajinagar Airport (IXU) - 35 km', ARRAY['Chhatrapati Sambhajinagar', 'Pune (240 km)', 'Nashik (180 km)']::TEXT[], ARRAY['Grishneshwar Jyotirlinga (1 km)', 'Daulatabad Fort (15 km)', 'Ajanta Caves (100 km)']::TEXT[], ARRAY['Ellora Village', 'Aurangabad Station Road']::TEXT[], ARRAY['Hurda', 'Shev Bhaji', 'Misal Pav', 'Solkadhi']::TEXT[], 'Regular MSRTC buses and private cabs from Aurangabad central bus stand; battery cars inside site.', 20.0268, 75.1792, 'https://whc.unesco.org/en/list/243', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-sun-temple-konark', 'Sun Temple, Konark', ARRAY['Black Pagoda', 'Arka Kshetra']::TEXT[], 'Cultural', 'Odisha', 'Puri', 'Konark', 1984, ARRAY['(i)', '(iii)', '(vi)']::TEXT[], 'Constructed in 1250 CE by King Narasimhadeva I of the Eastern Ganga Dynasty to celebrate military triumphs and honor Surya, the Sun God.', 'Designed as a colossal chariot of the Sun God drawn by 7 horses with 24 carved stone wheels that function as precise astronomical sundials; Kalinga architectural mastery.', 'Crown jewel of Kalinga temple architecture and India''s finest sun worship shrine.', 'Legend of Dharmapada, the 12-year-old son of chief architect Bisu Maharana, who successfully placed the heavy kalasha crowning stone to save the artisans'' lives.', ARRAY['Jagamohana (Audience Hall)', '24 Sundial Chariot Wheels', 'Natamandira (Dancing Hall)', 'War Horse Sculptures', 'Elephant Friezes']::TEXT[], 'Intricately detailed stone carvings of celestial musicians, astronomical chronometers, and maritime life.', 'October to March; Konark Dance Festival in December.', '2 to 3 hours', 'Puri Railway Station (PURI) - 35 km; Bhubaneswar (BBS) - 65 km', 'Biju Patnaik International Airport Bhubaneswar (BBI) - 65 km', ARRAY['Puri (35 km)', 'Bhubaneswar (65 km)']::TEXT[], ARRAY['Jagannath Temple Puri', 'Chandrabhaga Beach', 'Pipili Applique Village']::TEXT[], ARRAY['Konark Marine Drive', 'OTDC Panthanivas Konark', 'Puri Beach']::TEXT[], ARRAY['Dalma', 'Chhena Poda', 'Chhenagaja', 'Odisha Coastal Fish Curry']::TEXT[], 'Scenic Marine Drive highway connects directly from Puri and Bhubaneswar.', 19.8876, 86.0945, 'https://whc.unesco.org/en/list/246', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-mahabalipuram', 'Group of Monuments at Mahabalipuram', ARRAY['Mamallapuram Monuments', 'Seven Pagodas']::TEXT[], 'Cultural', 'Tamil Nadu', 'Chengalpattu', 'Mamallapuram', 1984, ARRAY['(i)', '(ii)', '(iii)', '(vi)']::TEXT[], 'Founded by the Pallava king Narasimhavarman I (Mamalla) in the 7th and 8th centuries CE as an ancient maritime trading port connected to Southeast Asia.', 'Contains world-famous monolithic rathas (chariots), rock-cut mandapas, structural beachside shrines, and the colossal open-air bas-relief ''Descent of the Ganges''.', 'Birthplace of South Indian Dravidian structural temple architecture.', 'Known to early European mariners as the ''Seven Pagodas''; survived the 2004 Indian Ocean tsunami which temporarily exposed submerged ancient temple walls.', ARRAY['Shore Temple', 'Descent of the Ganges (Arjuna''s Penance)', 'Pancha Rathas (Five Chariots)', 'Krishna''s Butterball', 'Varaha Cave']::TEXT[], 'Sea breeze mingling with granitic monolithic temples, living stone sculptors chiselling statues along town lanes.', 'November to February; Mamallapuram Dance Festival in December-January.', '1 full day', 'Chengalpattu Junction (CGL) - 30 km; Chennai Central (MAS) - 55 km', 'Chennai International Airport (MAA) - 50 km', ARRAY['Chennai (55 km)', 'Kanchipuram (65 km)', 'Puducherry (95 km)']::TEXT[], ARRAY['Kanchipuram Silk City', 'Sadras Dutch Fort', 'DakshinaChitra']::TEXT[], ARRAY['East Coast Road (ECR)', 'Othavadai Street']::TEXT[], ARRAY['Fresh Coastal Seafood Fry', 'Tamil Banana Leaf Meals', 'Kanchipuram Idli', 'Filter Coffee']::TEXT[], 'Frequent air-conditioned buses and taxis via East Coast Road (ECR).', 12.6269, 80.1927, 'https://whc.unesco.org/en/list/249', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-kaziranga', 'Kaziranga National Park', ARRAY['Kaziranga Tiger Reserve']::TEXT[], 'Natural', 'Assam', 'Golaghat and Nagaon', 'Kohora / Bokakhat', 1985, ARRAY['(ix)', '(x)']::TEXT[], 'Proposed as a reserve forest in 1905 by Mary Curzon, wife of the Viceroy Lord Curzon, to protect remaining one-horned rhinos; declared a National Park in 1974.', 'Vast expanse of tall elephant grass, marshland, and tropical moist broadleaf forest nourished by the Brahmaputra River floodplains; hosts two-thirds of the world''s Great One-Horned Rhinoceros population.', 'Global gold-standard triumph of wildlife conservation.', 'Population grew from fewer than 20 rhinos in 1905 to over 2,600 today through dedicated anti-poaching forest ranger patrols.', ARRAY['One-Horned Rhinoceros', 'Royal Bengal Tigers', 'Wild Water Buffalo', 'Eastern Swamp Deer', 'Elephant Safaris in Kohora and Bagori ranges']::TEXT[], 'Early dawn elephant safari through morning mist encountering rhinos grazing close by in tall grassland.', 'November to April (park closed May to October due to monsoon floods).', '2 to 3 days', 'Furkating Junction - 75 km; Guwahati - 215 km', 'Jorhat Airport (JRH) - 95 km; Guwahati Airport (GAU) - 225 km', ARRAY['Jorhat', 'Tezpur', 'Guwahati']::TEXT[], ARRAY['Majuli River Island', 'Tea Gardens of Golaghat', 'Kakochang Waterfalls']::TEXT[], ARRAY['Kohora Central Range', 'Bagori Western Range']::TEXT[], ARRAY['Assamese Thali', 'Masor Tenga (Tangy Fish Curry)', 'Khar', 'Pitha']::TEXT[], 'Regular state buses and tourist vehicles along NH-715 (old NH-37).', 26.5775, 93.1711, 'https://whc.unesco.org/en/list/337', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-keoladeo', 'Keoladeo National Park', ARRAY['Bharatpur Bird Sanctuary']::TEXT[], 'Natural', 'Rajasthan', 'Bharatpur', 'Bharatpur', 1985, ARRAY['(x)']::TEXT[], 'Originally created as a duck-hunting reserve for the Maharaja of Bharatpur in 1850; converted into a bird sanctuary in 1956 and designated a Ramsar site in 1981.', '29 sq km man-made wetland complex hosting over 370 bird species; critical wintering ground for migratory waterfowl on the Central Asian Flyway.', 'Renowned pilgrimage site for global ornithologists and avian researchers.', 'Historical hunting stones still display record duck tallies shot by visiting British dignitaries before conservation laws halted hunting.', ARRAY['Painted Storks Heronry', 'Sarus Cranes', 'Pelicans', 'Bicycle and Cycle-Rickshaw Bird Tours', 'Keoladeo Shiva Temple']::TEXT[], 'Silent morning cycle-rickshaw rides driven by certified naturalist guides identifying rare calls and nesting colonies.', 'October to March for migratory species; August to November for indigenous nesting.', '1 to 2 days', 'Bharatpur Junction (BTE) - 5 km', 'Agra Airport - 55 km; Delhi Airport - 180 km; Jaipur Airport - 185 km', ARRAY['Agra (55 km)', 'Mathura (38 km)', 'Fatehpur Sikri (22 km)']::TEXT[], ARRAY['Lohagarh Fort Bharatpur', 'Deeg Palace', 'Fatehpur Sikri']::TEXT[], ARRAY['Saras Chauraha', 'Fatehpur Road']::TEXT[], ARRAY['Dal Baati Churma', 'Gatte ki Sabzi', 'Ker Sangri', 'Mawa Kachori']::TEXT[], 'Eco-friendly non-motorized cycle-rickshaws, rented bicycles, and battery vehicles inside.', 27.1594, 77.5204, 'https://whc.unesco.org/en/list/340', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-manas', 'Manas Wildlife Sanctuary', ARRAY['Manas National Park', 'Manas Biosphere Reserve']::TEXT[], 'Natural', 'Assam', 'Baksa and Chirang (Bodoland)', 'Barpeta Road', 1985, ARRAY['(vii)', '(ix)', '(x)']::TEXT[], 'Former royal hunting reserve of the Cooch Behar royal family and King of Gauripur; declared a Project Tiger reserve in 1973 and a National Park in 1990.', 'Located at the foothills of the Eastern Himalayas contiguous with Royal Manas National Park in Bhutan; home to endemic species including the Pygmy Hog, Golden Langur, and Hispid Hare.', 'Critical transboundary biodiversity corridor in the Eastern Himalayan biodiversity hotspot.', 'Successfully removed from the ''World Heritage in Danger'' list in 2011 following post-conflict community conservation leadership.', ARRAY['Manas River Rapids', 'Golden Langurs', 'Pygmy Hog Conservation Breeding Center', 'Wild Water Buffalo', 'River Rafting']::TEXT[], 'Spectacular forested foothill scenery against Himalayan peaks, gentle river rafting with elephant sightings.', 'October to April', '2 to 3 days', 'Barpeta Road Railway Station (BPRD) - 40 km', 'Lokpriya Gopinath Bordoloi International Airport Guwahati (GAU) - 145 km', ARRAY['Barpeta Road', 'Bongaigaon', 'Guwahati']::TEXT[], ARRAY['Barpeta Satra (Neo-Vaishnavite monastery)', 'Bhutan Border check-post']::TEXT[], ARRAY['Bansbari Eco Range', 'Barpeta Road']::TEXT[], ARRAY['Bodo Tribal Dishes', 'Pitha', 'Smoked Pork with Bamboo Shoots', 'Local Assam Tea']::TEXT[], 'Pre-booked 4x4 safari jeeps required for park exploration.', 26.6594, 91.0011, 'https://whc.unesco.org/en/list/338', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-churches-goa', 'Churches and Convents of Goa', ARRAY['Velha Goa Monuments', 'Old Goa Heritage Complex']::TEXT[], 'Cultural', 'Goa', 'North Goa', 'Old Goa (Velha Goa)', 1986, ARRAY['(ii)', '(iv)', '(vi)']::TEXT[], 'Constructed between the 16th and 18th centuries by Portuguese colonial rulers and religious orders (Jesuits, Franciscans, Augustinians) in the former capital of Portuguese India.', 'Manueline, Baroque, and Mannerist architectural styles rendered in local laterite stone plastered with lime; influenced the spread of Baroque art across Asia.', 'Epicenter of Asian Christian evangelization and home to the sacred relics of St. Francis Xavier.', 'Basilica of Bom Jesus has housed the non-decomposed sacred body of St. Francis Xavier for over 450 years.', ARRAY['Basilica of Bom Jesus', 'Sé Cathedral (Cathedral of Santa Catarina)', 'Church of St. Francis of Assisi', 'Ruins of St. Augustine Tower', 'Church of Divine Providence (St. Cajetan)']::TEXT[], 'Towering gilded altars, resonant Golden Bell, deeply historic sacred art and centuries of spiritual reverence.', 'November to February; Feast of St. Francis Xavier on December 3.', '3 to 4 hours', 'Karmali Railway Station (KRMI) - 3 km', 'Manohar International Airport Mopa (GOX) - 35 km; Dabolim Airport (GOI) - 25 km', ARRAY['Panaji (10 km)', 'Vasco da Gama (30 km)', 'Margao (32 km)']::TEXT[], ARRAY['Fontainhas Latin Quarter Panaji', 'Reis Magos Fort', 'Divar Island']::TEXT[], ARRAY['Panaji City', 'Candolim', 'Bambolim']::TEXT[], ARRAY['Goan Fish Curry Rice', 'Bebinca', 'Pork Vindaloo', 'Feni', 'Poi Bread']::TEXT[], 'Short 15-minute taxi or bus ride from Panaji central bus terminus.', 15.5009, 73.9116, 'https://whc.unesco.org/en/list/234', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-khajuraho', 'Khajuraho Group of Monuments', ARRAY['Khajuraho Temples', 'Kharjuravahaka']::TEXT[], 'Cultural', 'Madhya Pradesh', 'Chhatarpur', 'Khajuraho', 1986, ARRAY['(i)', '(iii)']::TEXT[], 'Constructed between 950 and 1050 CE during the zenith of the Chandela dynasty; of the original 85 temples, 25 survive across Western, Eastern, and Southern groups.', 'Peak expression of Nagara-style temple architecture in sandstone with curvilinear shikharas evoking Mount Meru; famous for sculptural depictions of dharma, artha, kama, and moksha.', 'Transcendent monument to human expression, celebration of life, and tantric philosophy.', 'Survived hidden in dense teak forests for centuries until rediscovered by British surveyor T.S. Burt in 1838.', ARRAY['Kandariya Mahadeva Temple', 'Lakshmana Temple', 'Chausath Yogini', 'Parshvanatha Temple', 'Matangeshwar Temple']::TEXT[], 'Awe-inspiring stone artistry depicting gods, celestial nymphs (apsaras), warriors, musicians, and everyday medieval life.', 'October to March; Khajuraho Dance Festival in February.', '1 to 2 days', 'Khajuraho Railway Station (KURJ) - 6 km', 'Khajuraho Airport (HJR) - 4 km', ARRAY['Chhatarpur (45 km)', 'Jhansi (175 km)', 'Satna (115 km)']::TEXT[], ARRAY['Panna National Park (25 km)', 'Raneh Falls', 'Orchha (170 km)']::TEXT[], ARRAY['Sevagram', 'Airport Road Khajuraho']::TEXT[], ARRAY['Bundelkhandi Thali', 'Mawa Baati', 'Dal Bafla', 'Chironji Kheer']::TEXT[], 'Compact walkable town; bicycles, auto-rickshaws, and e-rickshaws readily available.', 24.8318, 79.9199, 'https://whc.unesco.org/en/list/383', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-hampi', 'Group of Monuments at Hampi', ARRAY['Hampi Vijayanagara', 'Kishkindha']::TEXT[], 'Cultural', 'Karnataka', 'Vijayanagara', 'Hampi / Hosapete', 1986, ARRAY['(i)', '(iii)', '(iv)']::TEXT[], 'Magnificent capital of the Vijayanagara Empire from 1336 to 1565 CE, visited and described by Persian and European travelers as one of the richest cities on Earth before its sack in 1565.', 'Surreal landscape of giant granite boulders along the Tungabhadra River containing over 1,600 surviving monuments: grand stepped tanks, market bazaars, pillared halls, and stone chariot shrines.', 'Preserves the pinnacle of South Indian Vijayanagara architecture and culture.', 'The musical pillars of the Vittala Temple resonate with distinct musical tones when tapped.', ARRAY['Virupaksha Temple', 'Vittala Temple and Stone Chariot', 'Lotus Mahal', 'Elephant Stables', 'Queen''s Bath', 'Matanga Hill']::TEXT[], 'Climbing Matanga Hill for sunrise over boulder-strewn ruins, walking ancient stone chariot bazaars, and Coracle rides on the Tungabhadra River.', 'October to March; Hampi Utsav cultural festival in November/January.', '2 to 3 days', 'Hosapete Junction (HPT) - 13 km', 'Jindal Vijayanagar Airport Bellary (VDY) - 35 km; Hubballi Airport (HBX) - 145 km', ARRAY['Hosapete (13 km)', 'Ballari (65 km)', 'Hubballi (145 km)']::TEXT[], ARRAY['Anegundi', 'Badami (140 km)', 'Aihole & Pattadakal (135 km)']::TEXT[], ARRAY['Hampi Bazaar', 'Hosapete Town', 'Sanapur / Hippie Island']::TEXT[], ARRAY['Karnataka Banana Leaf Meals', 'Benne Dosa', 'Jolada Rotti', 'Filter Coffee']::TEXT[], 'Rental scooters, bicycles, auto-rickshaws, and electric carts at Vittala complex.', 15.335, 76.46, 'https://whc.unesco.org/en/list/241', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-fatehpur-sikri', 'Fatehpur Sikri', ARRAY['City of Victory']::TEXT[], 'Cultural', 'Uttar Pradesh', 'Agra', 'Fatehpur Sikri', 1986, ARRAY['(ii)', '(iii)', '(iv)']::TEXT[], 'Built in 1571 CE by Mughal Emperor Akbar to serve as his new imperial capital in honor of Sufi saint Sheikh Salim Chishti; served as capital until abandoned in 1585 CE due to water shortages.', 'Remarkably preserved planned city of red sandstone fusing Hindu, Jain, Gujarati, and Persian architectural idioms; contains Buland Darwaza (Gate of Magnificence), the highest gateway in the world at 54 meters.', 'Physical embodiment of Akbar''s eclectic cultural synthesis and Din-i Ilahi interfaith dialogue.', 'Akbar walked barefoot from Agra to Sikri to seek blessings from saint Salim Chishti for a male heir. Jahangir was born here.', ARRAY['Buland Darwaza', 'Tomb of Sheikh Salim Chishti', 'Jama Masjid', 'Panch Mahal', 'Diwan-i-Khas (Central Pillar)', 'Jodha Bai Palace']::TEXT[], 'Walking through vast sandstone courtyards, tying sacred thread (mannat) on the delicate marble jali screens of Chishti''s shrine.', 'October to March', '3 to 4 hours', 'Fatehpur Sikri Railway Station (FTS) - 2 km; Agra Cantt - 38 km', 'Agra Airport - 35 km; Delhi Airport - 230 km', ARRAY['Agra (38 km)', 'Bharatpur (22 km)']::TEXT[], ARRAY['Keoladeo National Park (22 km)', 'Taj Mahal', 'Agra Fort']::TEXT[], ARRAY['Agra City', 'Fatehpur Sikri Bypass']::TEXT[], ARRAY['Khatai Sweets', 'Bedmi Aloo', 'Mughlai Pulao']::TEXT[], 'Regular direct buses and tourist cabs from Agra bus terminus.', 27.0945, 77.6679, 'https://whc.unesco.org/en/list/255', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-pattadakal', 'Group of Monuments at Pattadakal', ARRAY['Pattadakallu', 'Raktapura']::TEXT[], 'Cultural', 'Karnataka', 'Bagalkot', 'Pattadakal / Badami', 1987, ARRAY['(iii)', '(iv)']::TEXT[], 'Holy coronation site (''Pattada Kisuvolal'') of the Chalukya dynasty in the 7th and 8th centuries CE on the banks of the Malaprabha River.', 'Pioneering architectural crucible where North Indian Nagara and South Indian Dravida temple styles were harmonized side by side; Virupaksha Temple served as the model for the Kailasa Temple at Ellora.', 'Foundational milestone in the evolution of classical Indian temple architecture.', 'Virupaksha Temple was built in 740 CE by Queen Lokamahadevi to commemorate King Vikramaditya II''s victory over the Pallavas of Kanchipuram.', ARRAY['Virupaksha Temple', 'Mallikarjuna Temple', 'Sangameshwara Temple', 'Galaganatha Temple', 'Papanatha Temple', 'Jain Narayana Temple']::TEXT[], 'Serene riverside temple complex of red sandstone glowing in afternoon sunlight.', 'October to March', '2 to 3 hours', 'Badami Railway Station (BDM) - 22 km', 'Hubballi Airport (HBX) - 130 km; Belagavi Airport - 150 km', ARRAY['Badami (22 km)', 'Bagalkot (40 km)', 'Hubballi (130 km)']::TEXT[], ARRAY['Badami Cave Temples (22 km)', 'Aihole Cradle of Architecture (13 km)', 'Mahakuta']::TEXT[], ARRAY['Badami Town', 'KSTDC Hotel Mayura Chalukya Badami']::TEXT[], ARRAY['North Karnataka Jolada Rotti Oota', 'Shenga Chutney', 'Yenne Gai (Stuffed Brinjal)', 'Dharwad Pedha']::TEXT[], 'Easily explored as part of the famous Badami-Pattadakal-Aihole circuit by taxi.', 15.949, 75.816, 'https://whc.unesco.org/en/list/239', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-elephanta', 'Elephanta Caves', ARRAY['Gharapuri', 'City of Caves']::TEXT[], 'Cultural', 'Maharashtra', 'Raigad', 'Gharapuri Island / Mumbai', 1987, ARRAY['(i)', '(iii)']::TEXT[], 'Rock-cut cave temples carved between the mid-5th and 6th centuries CE, attributed to the Konkan Mauryas and Kalachuris, dedicated primarily to Lord Shiva.', 'Magnificent rock-hewn pillars and colossal high-relief sculptures, dominated by the 20-foot tall three-headed ''Trimurti'' (Sadashiva) representing creator, preserver, and destroyer.', 'Among the most profound sculpted masterpieces of Shaivite iconography and Indian rock-cut art.', 'Named ''Elephanta'' by 16th-century Portuguese navigators who discovered a colossal stone elephant near the island''s dock.', ARRAY['Main Cave (Cave 1)', 'Trimurti Sadashiva', 'Ardhanarishvara', 'Gangadhara Shiva', 'Nataraja Relief', 'Ravana Shaking Mount Kailash']::TEXT[], 'Scenic 1-hour ferry ride from Gateway of India past Mumbai harbor followed by climb up stone steps lined with craft stalls.', 'November to March (ferry services can be suspended during heavy monsoon storms).', '4 to 5 hours including ferry travel', 'Chhatrapati Shivaji Maharaj Terminus (CSMT) Mumbai - 3 km to ferry point', 'Chhatrapati Shivaji Maharaj International Airport Mumbai (BOM) - 25 km', ARRAY['Mumbai', 'Navi Mumbai']::TEXT[], ARRAY['Gateway of India', 'Kanheri Caves', 'Chhatrapati Shivaji Maharaj Vastu Sangrahalaya']::TEXT[], ARRAY['Colaba', 'Fort', 'Marine Drive']::TEXT[], ARRAY['Mumbai Street Food', 'Vada Pav', 'Pav Bhaji', 'Bombay Duck Fry']::TEXT[], 'Regular tourist ferries operate every 30 minutes from Gateway of India jetty; toy train on jetty.', 18.9633, 72.9315, 'https://whc.unesco.org/en/list/244', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-great-chola-temples', 'Great Living Chola Temples', ARRAY['Brihadisvara Temples', 'Chola Temple Architecture']::TEXT[], 'Cultural', 'Tamil Nadu', 'Thanjavur, Ariyalur, and Thanjavur', 'Thanjavur, Gangaikonda Cholapuram, and Darasuram', 1987, ARRAY['(ii)', '(iii)']::TEXT[], 'Constructed during the Chola Empire: Brihadisvara at Thanjavur by Rajaraja I (1010 CE), Brihadisvara at Gangaikonda Cholapuram by Rajendra I (1035 CE), and Airavatesvara at Darasuram by Rajaraja II (12th century).', 'Peak realization of Dravidian architecture; Thanjavur vimana rises 66 meters with an 80-tonne monolithic granite cupola capstone; living temples with unceasing rituals for over 1,000 years.', 'Testament to Chola maritime empire, bronze casting, classical Bharatanatyam, and enduring spiritual practice.', 'Shadow of the 66-meter high vimana at Thanjavur was engineered to demonstrate profound astronomical precision.', ARRAY['Brihadisvara Temple Thanjavur', 'Gangaikonda Cholapuram Temple', 'Airavatesvara Temple Darasuram', 'Colossal Monolithic Nandi', 'Chola Frescoes']::TEXT[], 'Awe-inspiring granite architecture of immense scale, evening lamps illuminating centuries-old bronze icons and continuous chanting.', 'October to March', '1 to 2 days across all three temple sites', 'Thanjavur Junction (TJ) - 2 km', 'Tiruchirappalli International Airport (TRZ) - 55 km', ARRAY['Thanjavur', 'Kumbakonam (40 km)', 'Tiruchirappalli (55 km)']::TEXT[], ARRAY['Thanjavur Maratha Palace & Saraswathi Mahal Library', 'Srirangam Temple', 'Chettinad']::TEXT[], ARRAY['South Rampart Road Thanjavur', 'Kumbakonam']::TEXT[], ARRAY['Thanjavur Sambar', 'Kumbakonam Degree Coffee', 'Ashoka Halwa', 'Tamil Thali']::TEXT[], 'Regular direct trains and buses from Trichy and Chennai.', 10.7828, 79.1318, 'https://whc.unesco.org/en/list/250', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-sundarbans', 'Sundarbans National Park', ARRAY['Sundarban Tiger Reserve', 'Ganges Mangrove Forest']::TEXT[], 'Natural', 'West Bengal', 'South 24 Parganas', 'Gosaba / Canning', 1987, ARRAY['(ix)', '(x)']::TEXT[], 'Created as a wildlife sanctuary in 1977, designated a national park in 1984, and inscribed as a World Heritage site in 1987; forms the largest mangrove forest in the world on the delta of the Ganga, Brahmaputra, and Meghna rivers.', 'Intertidal mangrove ecosystem with pneumatophores (breathing roots) hosting the world''s only mangrove-dwelling Royal Bengal Tigers, saltwater crocodiles, and Ganges river dolphins.', 'Vital natural biosheild protecting the Bengal coast against tropical cyclones and sea storms.', 'Devotion to Bonbibi (goddess of the forest) shared by both Hindu and Muslim honey-gatherers (Mowalis) and fishermen entering the deep forest.', ARRAY['Boat Safaris through Tidal Creeks', 'Sajnekhali Watch Tower and Mangrove Interpretation Centre', 'Dobanki Canopy Walk', 'Sudhanyakhali Tiger Watch Tower', 'Netidhopani Ruins']::TEXT[], 'Gliding on motorized wooden boats through narrow mangrove channels surrounded by silent mudflats and watching for swimming tigers.', 'October to March (pleasant cool weather).', '2 to 3 days', 'Canning Railway Station - 30 km to ferry point; Sealdah Kolkata - 100 km', 'Netaji Subhash Chandra Bose International Airport Kolkata (CCU) - 110 km', ARRAY['Kolkata (110 km)', 'Canning']::TEXT[], ARRAY['Kolkata Heritage Core', 'Bakkhali Beach']::TEXT[], ARRAY['Pakhiralay', 'Dayapur Island Eco Resorts']::TEXT[], ARRAY['Fresh Bhetki Fish Curry', 'Chingri Malai Curry', 'Kolkata Biryani', 'Sundarbans Wild Honey']::TEXT[], 'Road journey from Kolkata to Godkhali ghat (3 hours), then motorized boat transfer.', 21.9497, 89.1833, 'https://whc.unesco.org/en/list/452', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-nanda-devi', 'Nanda Devi and Valley of Flowers National Parks', ARRAY['Nanda Devi Biosphere Reserve', 'Valley of Flowers']::TEXT[], 'Natural', 'Uttarakhand', 'Chamoli and Pithoragarh', 'Joshimath / Govindghat', 1988, ARRAY['(vii)', '(x)']::TEXT[], 'Nanda Devi National Park established in 1982 around India''s second-highest peak (7,816 m); Valley of Flowers discovered by mountaineer Frank Smythe in 1931 was inscribed as an extension in 2005.', 'Pristine alpine transition zone with high diversity of threatened flora including Brahma Kamal, blue poppy, and edelweiss, home to snow leopard, Asiatic black bear, and blue sheep.', 'Nanda Devi peak is venerated as a sacred goddess across Garhwal and Kumaon folk traditions.', 'Frank Smythe stumbled upon the alpine paradise in 1931 while returning from Mount Kamet, publishing his classic book ''The Valley of Flowers''.', ARRAY['Valley of Flowers Alpine Meadows', 'Pushpawati River', 'Hemkund Sahib (Nearby Sikh pilgrimage)', 'Brahma Kamal Blooms', 'Ghangaria Basecamp']::TEXT[], 'Trek through a kaleidoscope of millions of alpine wildflowers blooming in lush mountain mist under snow-capped peaks.', 'July to September (peak bloom season); park closed in winter.', '4 to 6 days including trek', 'Rishikesh Railway Station (RKSH) - 275 km; Haridwar - 300 km', 'Jolly Grant Airport Dehradun (DED) - 290 km', ARRAY['Joshimath (30 km)', 'Rishikesh (275 km)', 'Badrinath (45 km)']::TEXT[], ARRAY['Badrinath Temple', 'Hemkund Sahib', 'Mana Village (First Village of India)']::TEXT[], ARRAY['Ghangaria', 'Govindghat', 'Joshimath']::TEXT[], ARRAY['Garhwali Thali', 'Kafli', 'Chainsoo', 'Bal Mithai', 'Mandua Roti']::TEXT[], 'Drive to Govindghat, then 14 km trek or pony/helicopter ride to Ghangaria basecamp, then 3 km trek into the Valley.', 30.728, 79.6053, 'https://whc.unesco.org/en/list/335', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-sanchi', 'Buddhist Monuments at Sanchi', ARRAY['Sanchi Stupa', 'Great Stupa']::TEXT[], 'Cultural', 'Madhya Pradesh', 'Raisen', 'Sanchi / Vidisha', 1989, ARRAY['(i)', '(ii)', '(iii)', '(iv)', '(vi)']::TEXT[], 'Oldest surviving stone structure in India, originally commissioned by Emperor Ashoka the Great in the 3rd century BCE to enshrine relics of Gautama Buddha; enlarged under the Shungas and Satavahanas.', 'Hemispherical stone dome surmounting a terrace with chatra umbrella, surrounded by high balustrades with four elaborately carved ceremonial gateways (toranas) depicting Jataka tales.', 'Foundational monument of Buddhist art and monumental stone architecture in Asia.', 'Ashoka''s queen Devi was from nearby Vidisha; their children Mahendra and Sanghamitta departed from Sanchi to propagate Buddhism in Sri Lanka.', ARRAY['Great Stupa 1', 'Four Torana Gateways', 'Stupa 2 (Floral carvings)', 'Stupa 3 (Sariputra Relics)', 'Ashoka Pillar Edicts', 'Sanchi Archaeological Museum']::TEXT[], 'Serene hilltop setting surrounded by ancient monastic ruins, admiring 2,200-year-old stone reliefs carved with the delicacy of ivory.', 'October to March; Chetiyagiri Vihara Festival in November.', '3 to 4 hours', 'Sanchi Railway Station (SCI) - 1.5 km; Vidisha - 10 km; Bhopal Junction - 46 km', 'Raja Bhoj Airport Bhopal (BHO) - 52 km', ARRAY['Vidisha (10 km)', 'Bhopal (46 km)']::TEXT[], ARRAY['Udayagiri Caves (13 km)', 'Heliodorus Pillar Vidisha', 'Bhimbetka (90 km)']::TEXT[], ARRAY['MP Tourism Gateway Retreat Sanchi', 'Bhopal']::TEXT[], ARRAY['Poha Jalebi', 'Bhopali Gosht Korma', 'Bhutte ka Kees', 'Dal Bafla']::TEXT[], 'Regular trains from Bhopal and local buses; easy 1-hour drive along NH-146.', 23.4795, 77.7397, 'https://whc.unesco.org/en/list/524', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-humayuns-tomb', 'Humayun''s Tomb, Delhi', ARRAY['Maqbara-i-Humayun', 'Dormitory of the Mughals']::TEXT[], 'Cultural', 'Delhi', 'South East Delhi', 'New Delhi (Nizamuddin East)', 1993, ARRAY['(ii)', '(iv)']::TEXT[], 'Commissioned in 1565 CE by Humayun''s senior widow Empress Bega Begum (Haji Begum) and designed by Persian architect Mirak Mirza Ghiyas; completed in 1572 CE.', 'First monumental garden-tomb on the Indian subcontinent, introducing the Charbagh geometric quadrilateral garden and high double-dome, directly inspiring the architectural conception of the Taj Mahal.', 'Landmark synthesis of Persian garden geometry with Indian red sandstone and white marble craftsmanship.', 'Last Mughal Emperor Bahadur Shah Zafar took refuge here before his capture by British officer William Hodson during the 1857 Rebellion.', ARRAY['Main Mausoleum', 'Charbagh Water Channels', 'Isa Khan''s Tomb and Mosque', 'Bu Halima''s Garden', 'Afsarwala Tomb', 'Barber''s Tomb (Nai ka Gumbad)']::TEXT[], 'Immaculately restored paradise gardens with flowing water channels, grand vaulted arches, and glowing red sandstone.', 'October to March; late afternoon for golden hour photography.', '2 to 3 hours', 'Hazrat Nizamuddin Railway Station (NZM) - 1.5 km', 'Indira Gandhi International Airport (DEL) - 18 km', ARRAY['Noida', 'Gurugram', 'Faridabad']::TEXT[], ARRAY['Hazrat Nizamuddin Dargah (500 m)', 'Sunder Nursery (Adjacent)', 'India Gate (4 km)']::TEXT[], ARRAY['Nizamuddin', 'Lutyens Delhi', 'Connaught Place']::TEXT[], ARRAY['Delhi Street Chaat', 'Nizamuddin Kebabs and Biryani', 'Mughlai Korma', 'Kulfi Falooda']::TEXT[], 'JLN Stadium Metro Station (Violet Line) is 1.5 km away; battery rickshaws abundant.', 28.5933, 77.2507, 'https://whc.unesco.org/en/list/633', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-qutb-minar', 'Qutb Minar and its Monuments, Delhi', ARRAY['Qutub Minar', 'Vijay Stambha of Mehrauli']::TEXT[], 'Cultural', 'Delhi', 'South Delhi', 'Mehrauli, New Delhi', 1993, ARRAY['(iv)']::TEXT[], 'Commenced in 1199 CE by Qutb-ud-din Aibak to mark the establishment of the Delhi Sultanate; added to by Shams-ud-din Iltutmish (1220 CE) and Firoz Shah Tughlaq (1368 CE).', 'Highest brick minaret in the world at 72.5 meters, tapering with projecting balconies supported by stalactite-like corbels; complex contains the 4th-century CE rust-resistant Iron Pillar of Chandragupta II.', 'Foundational architectural monument of the Delhi Sultanate and Indo-Islamic building art.', 'The 1,600-year-old Iron Pillar has withstood monsoons and weathering for over sixteen centuries without showing corrosion, a marvel of ancient Indian metallurgy.', ARRAY['Qutb Minar', 'Quwwat-ul-Islam Mosque', 'Iron Pillar of Delhi', 'Alai Darwaza', 'Tomb of Iltutmish', 'Alai Minar (Unfinished minaret)']::TEXT[], 'Towering red sandstone fluted minaret covered in delicate Arabic calligraphy and geometric bands set against manicured green lawns.', 'October to March', '2 to 3 hours', 'New Delhi Railway Station (NDLS) - 15 km; Hazrat Nizamuddin - 14 km', 'Indira Gandhi International Airport (DEL) - 12 km', ARRAY['Gurugram (18 km)', 'Noida (22 km)']::TEXT[], ARRAY['Mehrauli Archaeological Park', 'Jamali Kamali Mosque', 'Hauz Khas Complex']::TEXT[], ARRAY['Saket', 'Mehrauli', 'Aerocity']::TEXT[], ARRAY['Chole Bhature', 'Parathas', 'Kebabs of Old Delhi', 'Rabri Falooda']::TEXT[], 'Qutab Minar Metro Station (Yellow Line) is 1.5 km away with direct connectivity from central Delhi.', 28.5245, 77.1855, 'https://whc.unesco.org/en/list/642', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-mountain-railways', 'Mountain Railways of India', ARRAY['Darjeeling Himalayan Railway', 'Nilgiri Mountain Railway', 'Kalka Shimla Railway']::TEXT[], 'Cultural', 'West Bengal, Tamil Nadu, Himachal Pradesh', 'Darjeeling, Nilgiris, Shimla', 'Darjeeling, Ooty, Shimla', 1999, ARRAY['(ii)', '(iv)']::TEXT[], 'Serial inscription encompassing three historic 19th and early 20th-century narrow-gauge mountain railways: Darjeeling (1881), Nilgiri (1908, with unique rack and pinion system), and Kalka-Shimla (1903).', 'Bold engineering triumphs navigating extreme mountain gradients with loops, ''Z''-reverses, multi-arched viaducts, and tunnels through Himalayan and Western Ghat terrains.', 'Transformed social, economic, and cultural connectivity in India''s mountainous tea and forest regions.', 'The Darjeeling Himalayan Railway introduced the innovative ''Loop'' and ''Reverse'' systems to conquer steep gradients without heavy tunneling.', ARRAY['Steam Locomotive Runs', 'Batasia Loop (Darjeeling)', 'Barog Tunnel (Kalka-Shimla)', 'Rack and Pinion Climb (Nilgiri)', 'Mountain Scenery']::TEXT[], 'Unforgettable nostalgic journey chugging past tea plantations, pine forests, and misty valleys with whistle echoes.', 'March to June and October to December', 'Full day scenic rail ride', 'New Jalpaiguri (DHR); Mettupalayam (NMR); Kalka (KSR)', 'Bagdogra (IXB) for Darjeeling; Coimbatore (CJB) for Nilgiri; Chandigarh (IXC) for Shimla', ARRAY['Siliguri', 'Coimbatore', 'Chandigarh']::TEXT[], ARRAY['Viceregal Lodge Shimla', 'Tea Estates Darjeeling', 'Botanical Gardens Ooty']::TEXT[], ARRAY['The Mall Shimla', 'Chowrasta Darjeeling', 'Charring Cross Ooty']::TEXT[], ARRAY['Momos and Thukpa (Darjeeling)', 'Himachali Dham (Shimla)', 'Ooty Homemade Chocolates']::TEXT[], 'Book toy train tickets well in advance on IRCTC official portal.', 27.036, 88.2627, 'https://whc.unesco.org/en/list/944', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-mahabodhi', 'Mahabodhi Temple Complex at Bodh Gaya', ARRAY['Bodh Gaya Temple', 'Vajrasana Temple']::TEXT[], 'Cultural', 'Bihar', 'Gaya', 'Bodh Gaya', 2002, ARRAY['(i)', '(ii)', '(iii)', '(iv)', '(vi)']::TEXT[], 'First temple built by Emperor Ashoka in the 3rd century BCE around the sacred Bodhi Tree where Siddhartha Gautama attained supreme Enlightenment (Buddhatva) in c. 531 BCE; present grand brick temple dates to the 5th-6th century CE (Gupta period).', 'One of the earliest temple structures built entirely in brick still standing in India, towering 55 meters with classic sikhara and chaitya niches.', 'The holiest pilgrimage site in the Buddhist world, venerated across Theravada, Mahayana, and Vajrayana traditions.', 'The current sacred Bodhi Tree is a direct descendant of the original tree under which the Buddha meditated, nurtured from a sapling brought back from Sri Lanka.', ARRAY['Sacred Bodhi Tree (Sri Maha Bodhi)', 'Vajrasana (Diamond Throne)', 'Main Mahabodhi Sanctuary', 'Muchalinda Lake', 'Chankramana (Jewelled Cloister)', '7 Sacred Enlightenment Meditation Spots']::TEXT[], 'Deep serene spiritual ambiance, saffron-robed monks chanting under the rustling leaves of the Bodhi Tree, thousands of glowing butter lamps at dusk.', 'October to March; Buddha Purnima in May is intensely auspicious.', '1 full day', 'Gaya Junction (GAYA) - 16 km', 'Gaya International Airport (GAY) - 10 km; Patna Airport (PAT) - 110 km', ARRAY['Gaya (16 km)', 'Patna (110 km)', 'Varanasi (250 km)']::TEXT[], ARRAY['Vishnupad Temple Gaya (15 km)', 'Dungeshwari Cave Temples (12 km)', 'Nalanda (85 km)', 'Rajgir (70 km)']::TEXT[], ARRAY['Temple Road Bodh Gaya', 'International Monasteries Sector']::TEXT[], ARRAY['Litti Chokha', 'Gaya Tilkut', 'Anarsa', 'Sattu Sharbat', 'Khaja']::TEXT[], 'Pre-paid taxis and auto-rickshaws run continuously from Gaya railway station and airport.', 24.6961, 84.9913, 'https://whc.unesco.org/en/list/1056', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-bhimbetka', 'Rock Shelters of Bhimbetka', ARRAY['Bhimbetka Caves', 'Bhim Baithak']::TEXT[], 'Cultural', 'Madhya Pradesh', 'Raisen', 'Bhojpur / Obaidullaganj', 2003, ARRAY['(iii)', '(v)']::TEXT[], 'Naturally sculpted sandstone rock shelters in the foothills of the Vindhyan Mountains showing continuous human occupation from the Lower Paleolithic to the medieval era (spanning over 100,000 years).', 'Over 750 rock shelters spread across seven hills containing prehistoric rock paintings dating from the Upper Paleolithic and Mesolithic (10,000 BCE) with mineral pigments of ochre and white.', 'Among the oldest documented records of human artistic expression, hunting rituals, and dance on Earth.', 'Discovered in 1957 by Indian archaeologist Dr. V. S. Wakankar who noticed the natural stone formations from a train window and began excavations.', ARRAY['Auditorium Cave (Cave 3)', 'Zoo Rock Shelter (Animal scenes)', 'Boar Rock (Colossal mythological beast)', 'Mesolithic Hunting Friezes']::TEXT[], 'Walking through prehistoric forested natural rock amphitheatres viewing vibrant paintings of elephants, bisons, and dancing hunters.', 'October to March', '2 to 3 hours', 'Obaidullaganj - 15 km; Bhopal Junction - 45 km', 'Raja Bhoj Airport Bhopal (BHO) - 55 km', ARRAY['Bhopal (45 km)', 'Hoshangabad (35 km)']::TEXT[], ARRAY['Bhojeshwar Shiva Temple Bhojpur (28 km)', 'Sanchi (90 km)', 'Bhopal Tribal Museum']::TEXT[], ARRAY['MP Tourism Highway Treat Bhimbetka', 'Bhopal']::TEXT[], ARRAY['Bhopali Poha', 'Dal Bafla', 'Shahi Tukda']::TEXT[], 'Conveniently reached by taxi or bus from Bhopal along the Bhopal-Hoshangabad highway (NH-46).', 22.9372, 77.6127, 'https://whc.unesco.org/en/list/925', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-csmt', 'Chhatrapati Shivaji Maharaj Terminus (formerly Victoria Terminus)', ARRAY['CSMT', 'Victoria Terminus (VT)']::TEXT[], 'Cultural', 'Maharashtra', 'Mumbai City', 'Fort, Mumbai', 2004, ARRAY['(ii)', '(iv)']::TEXT[], 'Designed by British architect F. W. Stevens and constructed between 1878 and 1887 to commemorate the Golden Jubilee of Queen Victoria; renamed in 1996 in honor of Chhatrapati Shivaji Maharaj.', 'Outstanding masterpiece of Victorian Italianate Gothic Revival architecture fused with traditional Indian palace motifs, stone domes, turrets, and pointed arches.', 'Beating heart of Mumbai''s suburban rail lifeline and commercial dynamism.', 'The high central octagonal ribbed dome is crowned by a colossal 4-meter bronze figure of ''Progress'' holding a torch in her right hand and a wheel in her left.', ARRAY['Central Grand Dome and Grand Staircase', 'Stained Glass Windows', 'Carved Peacocks and Gargoyles', 'Heritage Rail Gallery', 'Nocturnal LED Illumination']::TEXT[], 'Dramatic Victorian gothic facade bustling with thousands of daily commuters, illuminated brilliantly in tricolour and heritage lights each evening.', 'October to March; best viewed externally at dusk when lit.', '1 to 2 hours', 'CSMT is itself the premier terminus of Central Railway', 'Chhatrapati Shivaji Maharaj International Airport (BOM) - 22 km', ARRAY['Navi Mumbai', 'Thane', 'Pune']::TEXT[], ARRAY['BMC Headquarters (Opposite)', 'Flora Fountain', 'Gateway of India (2.5 km)', 'Marine Drive']::TEXT[], ARRAY['Fort', 'Colaba', 'Marine Lines']::TEXT[], ARRAY['Mumbai Vada Pav at Aram Canteen', 'Bombay Duck', 'Parsi Berry Pulao at Britannia', 'Bun Maska Chai']::TEXT[], 'Directly connected to suburban local train lines (Central and Harbour lines) and upcoming Metro 3.', 18.94, 72.8353, 'https://whc.unesco.org/en/list/945', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-champaner-pavagadh', 'Champaner-Pavagadh Archaeological Park', ARRAY['Champaner Heritage Site', 'Pavagadh Hill']::TEXT[], 'Cultural', 'Gujarat', 'Panchmahal', 'Champaner / Halol', 2004, ARRAY['(iii)', '(iv)', '(v)', '(vi)']::TEXT[], 'Founded as the capital of Sultan Mahmud Begada in the late 15th century, built upon an 8th-century Rajput hill fortress; complete unexcavated medieval pre-Mughal city.', 'Remarkable transition of regional Hindu and Jain craftsmanship into Indo-Islamic architectural idioms; includes water harvesting systems, stepped wells, palaces, and mosques.', 'The only complete and unchanged pre-Mughal Islamic city site in India.', 'Kalika Mata Temple atop the summit of Pavagadh Hill (800 meters) is an ancient Shakti Peetha venerated for over a thousand years.', ARRAY['Jami Masjid', 'Sahar ki Masjid', 'Kevada Masjid', 'Nagina Masjid', 'Pavagadh Ropeway and Kalika Mata Temple', 'Vada Talav']::TEXT[], 'Majestic isolated mosques with fine stone jali work set against Pavagadh volcanic hill, ropeway ride to the sacred summit.', 'October to March; monsoon season is breathtakingly green.', '4 to 5 hours', 'Vadodara Junction (BRC) - 45 km', 'Vadodara Airport (BDQ) - 42 km; Ahmedabad Airport (AMD) - 145 km', ARRAY['Vadodara (45 km)', 'Godhra (40 km)', 'Ahmedabad (140 km)']::TEXT[], ARRAY['Laxmi Vilas Palace Vadodara', 'Statue of Unity (115 km)', 'Dabhoi Fort']::TEXT[], ARRAY['Halol', 'Vadodara City']::TEXT[], ARRAY['Gujarati Kathiyawadi Thali', 'Sev Usal', 'Khaman Dhokla', 'Fafda Jalebi']::TEXT[], 'Convenient day-trip from Vadodara by car or GSRTC state bus.', 22.4833, 73.5333, 'https://whc.unesco.org/en/list/1101', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-red-fort', 'Red Fort Complex', ARRAY['Lal Qila', 'Qila-i-Mubarak']::TEXT[], 'Cultural', 'Delhi', 'North East / Central Delhi', 'Old Delhi (Shahjahanabad)', 2007, ARRAY['(ii)', '(iii)', '(vi)']::TEXT[], 'Constructed by Mughal Emperor Shah Jahan between 1639 and 1648 CE when he shifted the imperial capital from Agra to his new city of Shahjahanabad.', 'Peak of Mughal palace architecture in red sandstone and white marble; innovative octagonal grid layout, Persian garden canals (Nahr-i-Bihisht or Stream of Paradise), and chhatri pavilions.', 'The national symbol of Indian sovereignty where the Prime Minister unfurls the national tricolour each Independence Day (15 August).', 'The famous Peacock Throne once stood in the Diwan-i-Khas until looted by Nadir Shah of Persia in 1739. In 1945, the historic INA trials were held here.', ARRAY['Lahori Gate', 'Diwan-i-Aam', 'Diwan-i-Khas', 'Rang Mahal', 'Moti Masjid', 'Mumtaz Mahal Museum', 'Sound and Light Show']::TEXT[], 'Walking through grand octagonal gates, exploring covered Chhatta Chowk bazaar, and standing in the grand audience halls of the Mughals.', 'October to March', '2 to 3 hours', 'Old Delhi Railway Station (DLI) - 1.5 km; New Delhi (NDLS) - 4 km', 'Indira Gandhi International Airport (DEL) - 20 km', ARRAY['Noida', 'Gurugram', 'Ghaziabad']::TEXT[], ARRAY['Jama Masjid Delhi (500 m)', 'Chandni Chowk', 'Raj Ghat', 'Fatehpuri Masjid']::TEXT[], ARRAY['Daryaganj', 'Connaught Place', 'Karol Bagh']::TEXT[], ARRAY['Chandni Chowk Parathe Wali Gali', 'Karim''s Mutton Korma', 'Old Delhi Jalebi', 'Daulat ki Chaat']::TEXT[], 'Lal Quila Metro Station (Heritage Violet Line) is directly outside the gate.', 28.6562, 77.241, 'https://whc.unesco.org/en/list/231', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-jantar-mantar-jaipur', 'The Jantar Mantar, Jaipur', ARRAY['Jaipur Observatory', 'Yantra Mantra']::TEXT[], 'Cultural', 'Rajasthan', 'Jaipur', 'Jaipur', 2010, ARRAY['(iii)', '(iv)']::TEXT[], 'Completed in 1734 CE by Maharaja Sawai Jai Singh II, founder of Jaipur, who constructed five astronomical observatories across northern India.', 'Collection of nineteen architectural astronomical instruments built of stone and local marble, including the Vrihat Samrat Yantra, the world''s largest stone sundial measuring time to an accuracy of 2 seconds.', 'Masterpiece of late medieval Indian astronomical innovation and scientific synthesis combining Hindu, Islamic, and European astronomical systems.', 'Jai Singh sent scholarly emissaries to Portugal, Arabia, and Persia to collect astronomical tables before designing these monumental naked-eye calculation instruments.', ARRAY['Vrihat Samrat Yantra (Gigantic Sundial)', 'Jai Prakash Yantra', 'Rama Yantra', 'Misra Yantra', 'Rashivalaya (Zodiac instruments)']::TEXT[], 'Fascinating experience observing real-time shadows casting exact Jaipur solar time and planetary alignments on giant geometric stone arcs.', 'October to March; midday (11:30 AM to 1:30 PM) is best to observe the sundials in active overhead sunlight.', '1.5 to 2 hours', 'Jaipur Junction (JP) - 5 km', 'Jaipur International Airport (JAI) - 13 km', ARRAY['Ajmer (135 km)', 'Pushkar (145 km)', 'Delhi (260 km)']::TEXT[], ARRAY['City Palace Jaipur (Adjacent)', 'Hawa Mahal (400 m)', 'Amer Fort (10 km)', 'Nahargarh Fort']::TEXT[], ARRAY['Old Pink City', 'MI Road', 'Bani Park']::TEXT[], ARRAY['Ghevar (LMB Sweet Shop)', 'Pyaaz Kachori (Rawat)', 'Dal Baati Churma', 'Laal Maas']::TEXT[], 'Chhoti Chaupar Metro Station is within easy walking distance.', 26.9248, 75.8246, 'https://whc.unesco.org/en/list/1338', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-western-ghats', 'Western Ghats', ARRAY['Sahyadri Mountain Range', 'Western Ghats Serial Site']::TEXT[], 'Natural', 'Maharashtra, Goa, Karnataka, Tamil Nadu, Kerala, Gujarat', 'Multiple mountain districts across 6 states', 'Agumbe, Munnar, Mahabaleshwar, Silent Valley', 2012, ARRAY['(ix)', '(x)']::TEXT[], 'Ancient 1,600 km mountain chain older than the Himalayas, inscribed as a serial property comprising 39 individual protected reserves, national parks, and wildlife sanctuaries across six states.', 'One of the world''s eight ''hottest hotspots'' of biological diversity; mediates the Indian southwest monsoon; hosts over 5,000 flowering plant species, 139 mammal species, and 508 bird species with extraordinary endemism.', 'Lifeline of South India giving birth to major peninsular rivers: Godavari, Krishna, and Kaveri.', 'Home to the rare Kurinji shrub (Strobilanthes kunthiana) that blooms once every 12 years in Munnar, turning entire hillsides purple-blue.', ARRAY['Agumbe Rainforest (Cobra capital)', 'Silent Valley National Park', 'Periyar Tiger Reserve', 'Eravikulam National Park (Nilgiri Tahr)', 'Kudremukh National Park']::TEXT[], 'Lush emerald tea slopes, cascading waterfalls, tropical evergreen rainforests, and calls of the lion-tailed macaque.', 'September to March for general travel; June to August for dramatic monsoon landscapes.', '3 to 5 days depending on sub-cluster', 'Kochi, Mangaluru, Coimbatore, or Pune depending on cluster', 'Cochin International Airport (COK); Mangaluru (IXE); Coimbatore (CJB)', ARRAY['Kochi', 'Coimbatore', 'Mangaluru', 'Mysuru']::TEXT[], ARRAY['Wayanad Petroglyphs', 'Madikeri Fort Coorg', 'Bekal Fort']::TEXT[], ARRAY['Munnar', 'Wayanad', 'Coorg', 'Thekkady']::TEXT[], ARRAY['Kerala Appam with Stew', 'Coorg Pandi Curry', 'Malabar Parotta', 'Filter Coffee']::TEXT[], 'Well-connected scenic ghat mountain highways (NH-183, NH-766, NH-275).', 10.15, 77.06, 'https://whc.unesco.org/en/list/1342', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-hill-forts-rajasthan', 'Hill Forts of Rajasthan', ARRAY['Rajasthan Hill Forts Serial Site', 'Rajput Forts']::TEXT[], 'Cultural', 'Rajasthan', 'Chittorgarh, Rajsamand, Sawai Madhopur, Jhalawar, Jaipur, Jaisalmer', 'Chittorgarh, Kumbhalgarh, Ranthambore, Gagron, Amer, Jaisalmer', 2013, ARRAY['(ii)', '(iii)']::TEXT[], 'Serial inscription of six monumental Rajput hill forts built between the 8th and 18th centuries CE representing the zenith of Rajput princely military architecture.', 'Ingenious integration of sheer natural rocky terrain, massive defensive stone bastions, urban settlements, and sophisticated water harvesting reservoirs inside fortifications.', 'Epicenter of Rajput chivalry, martial legends (Jauhar and Saka), and courtly arts.', 'Kumbhalgarh features the second-longest continuous defensive wall on Earth (36 km), second only to the Great Wall of China.', ARRAY['Chittorgarh Fort (Vijay Stambha)', 'Kumbhalgarh Fort (Great Wall)', 'Ranthambore Fort (Tigers and Trinetra Ganesha)', 'Gagron Fort (Water-protected hill fort)', 'Amer Fort (Sheesh Mahal)', 'Jaisalmer Fort (Living Golden Fort)']::TEXT[], 'Stepping into living medieval worlds with panoramic desert and mountain views, royal palaces, and ancient temple spires.', 'October to March', '4 to 7 days to cover multiple forts', 'Jaipur, Udaipur, Chittorgarh, or Jaisalmer depending on fort', 'Jaipur (JAI); Udaipur (UDR); Jaisalmer (JSA)', ARRAY['Jaipur', 'Udaipur', 'Jodhpur', 'Jaisalmer']::TEXT[], ARRAY['City Palace Udaipur', 'Mehrangarh Fort Jodhpur', 'Ranakpur Jain Temples']::TEXT[], ARRAY['Heritage havelis in Jaipur, Udaipur, and Jaisalmer']::TEXT[], ARRAY['Dal Baati Churma', 'Laal Maas', 'Gatte ki Sabzi', 'Ker Sangri', 'Mirchi Vada']::TEXT[], 'Rajasthan State Road Transport Corporation (RSRTC) and excellent state highways.', 24.8879, 74.6453, 'https://whc.unesco.org/en/list/247', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-great-himalayan-national-park', 'Great Himalayan National Park Conservation Area', ARRAY['GHNP', 'Kullu Himalayan Sanctuary']::TEXT[], 'Natural', 'Himachal Pradesh', 'Kullu', 'Banjar / Sainj', 2014, ARRAY['(x)']::TEXT[], 'Established in 1984 in the Western Himalayas and declared a national park in 1999; protects 905 sq km of alpine meadows, glaciers, and river catchments of the Tirthan and Sainj valleys.', 'Located at the junction of Indomalayan and Palearctic ecozones; essential refuge for the Western Tragopan (Himachal''s state bird), snow leopard, Himalayan musk deer, and blue sheep.', 'Exemplary model of participatory biodiversity conservation working in harmony with local devta (deity) sacred forest traditions.', 'Successfully protected through a ban on commercial livestock grazing and joint community forestry cooperatives.', ARRAY['Tirthan Valley River Trek', 'Rolla Waterfall', 'Shilt Hut Trek', 'Snow Leopard Habitat', 'Trout Fishing in Eco-zone']::TEXT[], 'Unspoiled Himalayan wilderness, crystal clear glacier rivers, pine and deodar forests with zero motorized roads inside the core zone.', 'April to June (blooming rhododendrons) and September to November (crisp autumn skies).', '3 to 5 days trekking', 'Chandigarh Railway Station (CDG) - 240 km', 'Bhuntar Airport Kullu (KUU) - 50 km; Chandigarh Airport - 245 km', ARRAY['Kullu (50 km)', 'Mandi (70 km)', 'Manali (90 km)']::TEXT[], ARRAY['Chehni Kothi (Tall timber fort)', 'Shringi Rishi Temple', 'Naggar Castle']::TEXT[], ARRAY['Gushaini', 'Jibhi', 'Sai Ropa Eco-Tourism Centre']::TEXT[], ARRAY['Siddu with Ghee', 'Himachali Dham', 'Fresh Himalayan Rainbow Trout', 'Chha Gosht']::TEXT[], 'Road access to Gushaini or Neuli, then trekking permits required from park authorities.', 31.7333, 77.55, 'https://whc.unesco.org/en/list/1406', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-rani-ki-vav', 'Rani-ki-Vav (the Queen’s Stepwell) at Patan, Gujarat', ARRAY['Queen''s Stepwell', 'Rani ni Vav']::TEXT[], 'Cultural', 'Gujarat', 'Patan', 'Patan', 2014, ARRAY['(i)', '(iv)']::TEXT[], 'Constructed in 1063 CE by Queen Udayamati as a loving memorial to her deceased husband King Bhima I of the Solanki/Chaulukya dynasty on the banks of the Saraswati River.', 'Pinnacle of Maru-Gurjara stepwell architecture; designed as an inverted subterranean temple with seven levels of stairs descending to water, adorned with over 500 principal sculptures.', 'Featured on the modern Indian 100-rupee currency note; celebrated as water conservation elevated to divine art.', 'Submerged by flood silts of the Saraswati River in the 13th century, preserving its delicate sandstone carvings pristine until excavated by the ASI in the 1980s.', ARRAY['Sheshashayi Vishnu (Reclining on Ananta)', 'Dashavatara Sculptures', 'Apsaras and Mahishasuramardini', 'Seven Subterranean Stepped Pavilions']::TEXT[], 'Descending down cool subterranean pillared stone galleries into the earth surrounded by breathtaking carved deities.', 'October to March', '2 to 3 hours', 'Patan Railway Station (PTN) - 3 km; Mehsana Junction - 50 km', 'Sardar Vallabhbhai Patel International Airport Ahmedabad (AMD) - 125 km', ARRAY['Patan', 'Mehsana (50 km)', 'Ahmedabad (125 km)']::TEXT[], ARRAY['Sun Temple Modhera (35 km)', 'Patan Patola Saree Weaving Center', 'Sahastralinga Talav']::TEXT[], ARRAY['Patan Town', 'Mehsana']::TEXT[], ARRAY['Patan Devda Sweet', 'Gujarati Thali', 'Khaman', 'Handvo']::TEXT[], 'Direct 2.5-hour highway drive from Ahmedabad; combined easily with Modhera Sun Temple.', 23.8589, 72.1017, 'https://whc.unesco.org/en/list/1301', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-nalanda-mahavihara', 'Archaeological Site of Nalanda Mahavihara at Nalanda, Bihar', ARRAY['Nalanda University Ruins', 'Ancient Nalanda']::TEXT[], 'Cultural', 'Bihar', 'Nalanda', 'Nalanda / Rajgir', 2016, ARRAY['(iv)', '(vi)']::TEXT[], 'World''s most illustrious ancient residential university, flourishing from the 5th century CE (under the Guptas) to 1200 CE (under the Palas); hosted over 10,000 students and 2,000 scholars from across Asia.', 'Unrivalled architectural ensemble of red brick monasteries (viharas) and grand stupa temples arranged symmetrically with advanced drainage, lecture halls, and dormitories.', 'Epicenter of Buddhist philosophy, logic, mathematics, astronomy, and medicine; celebrated by Chinese pilgrims Xuanzang and Yijing.', 'The famous library ''Dharmaganja'' housed hundreds of thousands of sacred manuscripts across three multi-storey towers named Ratnasagara, Ratnodadhi, and Ratnaranjaka.', ARRAY['Temple Site 3 (Sariputra Stupa)', 'Monastery 1 (Courtyard and meditation cells)', 'Nalanda Archaeological Museum', 'Xuanzang Memorial Hall', 'Nav Nalanda Mahavihara']::TEXT[], 'Walking through expansive manicured gardens exploring the red brick foundations of lecture halls where ancient scholars debated world philosophy.', 'October to March', '3 to 4 hours', 'Nalanda Railway Station (NLD) - 2 km; Rajgir - 12 km; Patna Junction - 90 km', 'Gaya Airport - 95 km; Jay Prakash Narayan Airport Patna (PAT) - 90 km', ARRAY['Rajgir (12 km)', 'Bihar Sharif (15 km)', 'Patna (90 km)', 'Gaya (95 km)']::TEXT[], ARRAY['Rajgir Vulture Peak & Ropeway (12 km)', 'Ghora Katora Lake', 'Bodh Gaya (85 km)', 'Pawapuri (25 km)']::TEXT[], ARRAY['Rajgir Town (Hot spring resort hub)', 'Nalanda']::TEXT[], ARRAY['Silao Khaja (GI Tagged multi-layered sweet)', 'Litti Chokha', 'Sattu Paratha', 'Tilkut']::TEXT[], 'Easily accessible via four-lane highway from Patna (2 hours) and Rajgir (15 minutes).', 25.1357, 85.4449, 'https://whc.unesco.org/en/list/1502', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-khangchendzonga', 'Khangchendzonga National Park', ARRAY['Kanchenjunga National Park', 'KNP Sikkim']::TEXT[], 'Mixed', 'Sikkim', 'North and West Sikkim', 'Yuksom / Chungthang', 2016, ARRAY['(iii)', '(vi)', '(vii)', '(x)']::TEXT[], 'Established in 1977 and inscribed in 2016 as India''s first and only ''Mixed'' World Heritage site, recognizing both its superlative natural wilderness and profound cultural sacredness.', 'Dominated by Mount Khangchendzonga (8,586 m), the world''s third-highest peak; encompasses 18 glaciers including Zemu Glacier, pristine alpine lakes, and rhododendron forests.', 'Core sacred landscape of the ''Beyul'' (hidden sacred valley) in Tibetan Buddhism, venerated as the protective guardian deity of the Sikkimese people.', 'The sacred covenant between the guardian mountain deity Khangchendzonga and the Lepcha and Bhutia communities is celebrated annually in the Pang Lhabsol festival.', ARRAY['Mount Khangchendzonga Views', 'Goechala Pass Trek', 'Dzongri Viewpoint', 'Samiti Lake', 'Red Panda and Snow Leopard Habitat', 'Yuksom (Historical Coronation Throne)']::TEXT[], 'High-altitude trek through pristine rhododendron forests emerging into amphitheaters of towering Himalayan ice giants.', 'March to May (rhododendron blooms) and September to November (crystal-clear skies).', '7 to 10 days for full high-altitude trek', 'New Jalpaiguri (NJP) - 150 km to Yuksom', 'Pakyong Airport Gangtok (PYG) - 130 km; Bagdogra Airport (IXB) - 160 km', ARRAY['Yuksom', 'Pelling', 'Gangtok (140 km)']::TEXT[], ARRAY['Dubdi Monastery (Oldest in Sikkim)', 'Pemayangtse Monastery', 'Rabdentse Ruins']::TEXT[], ARRAY['Yuksom Basecamp', 'Pelling']::TEXT[], ARRAY['Sikkimese Momos', 'Thukpa', 'Gundruk Soup', 'Chhurpi Cheese', 'Tongba (Millet Beer)']::TEXT[], 'Trekking permits from Sikkim Forest Department and Home Department required at Yuksom.', 27.6719, 88.2044, 'https://whc.unesco.org/en/list/1513', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-le-corbusier-chandigarh', 'The Architectural Work of Le Corbusier, an Outstanding Contribution to the Modern Movement', ARRAY['Chandigarh Capitol Complex', 'Le Corbusier Complex']::TEXT[], 'Cultural', 'Chandigarh', 'Chandigarh (UT)', 'Chandigarh Sector 1', 2016, ARRAY['(i)', '(ii)', '(vi)']::TEXT[], 'Part of a transnational serial inscription across seven countries; the Capitol Complex in Chandigarh was designed in the 1950s by Swiss-French master architect Le Corbusier as the governmental seat of post-independence Punjab and Haryana.', 'Triumph of modern exposed concrete (béton brut) architecture integrating climate-responsive brise-soleil sunshades, monumental geometric pylons, and the iconic Open Hand Monument.', 'Symbol of independent India''s embrace of modern urban planning, secular democracy, and architectural boldness.', 'Commissioned by Prime Minister Jawaharlal Nehru who proclaimed: ''Let this be a new town, symbolic of the freedom of India, unfettered by the traditions of the past.''', ARRAY['Palace of Assembly (Legislative Assembly)', 'Secretariat Building', 'High Court of Punjab and Haryana', 'Open Hand Monument (Symbol of peace)', 'Tower of Shadows', 'Geometric Hill']::TEXT[], 'Stunning monumental modern architecture framed against the Shivalik Hills, feeling the raw poetic rhythm of concrete forms.', 'October to March', '2 to 3 hours (prior online tourist permit recommended)', 'Chandigarh Railway Station (CDG) - 10 km', 'Shaheed Bhagat Singh International Airport Chandigarh (IXC) - 18 km', ARRAY['Panchkula', 'Mohali', 'Ambala']::TEXT[], ARRAY['Rock Garden of Nek Chand (Adjacent)', 'Sukhna Lake', 'Zakir Hussain Rose Garden']::TEXT[], ARRAY['Sector 17', 'Sector 35', 'Madhya Marg']::TEXT[], ARRAY['Amritsari Kulcha', 'Makki di Roti with Sarson da Saag', 'Butter Chicken', 'Patiala Lassi']::TEXT[], 'Located in Sector 1; visitor center at the entrance provides guided architecture tours.', 30.7589, 76.8056, 'https://whc.unesco.org/en/list/1321', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-ahmadabad', 'Historic City of Ahmadabad', ARRAY['Old Ahmedabad', 'Amdavad Walled City']::TEXT[], 'Cultural', 'Gujarat', 'Ahmedabad', 'Ahmedabad', 2017, ARRAY['(ii)', '(v)']::TEXT[], 'Founded in 1411 CE by Sultan Ahmad Shah on the eastern bank of the Sabarmati River; India''s first UNESCO World Heritage City.', 'Densely packed traditional urban settlements known as ''pols'' with self-contained gates, intricately carved wooden havelis, community bird-feeders (chabutras), and exquisite Indo-Islamic sultanate mosques.', 'Demonstrates centuries of community harmony, textile merchant heritage, and Mahatma Gandhi''s freedom struggle.', 'Sidi Saiyyed Mosque''s ''Tree of Life'' stone jali window carved in 1573 CE is an international symbol of artistic perfection.', ARRAY['Bhadra Fort', 'Jami Masjid', 'Sidi Saiyyed Mosque (Tree of Life Jali)', 'Heritage Pols and Chabutras', 'Hutheesing Jain Temple', 'Sabarmati Ashram']::TEXT[], 'Early morning guided heritage walk through narrow winding pols smelling freshly fried fafda, observing multi-storey wooden bracketed havelis.', 'October to March; International Kite Festival (Uttarayan) in January.', '1 to 2 days', 'Ahmedabad Junction / Kalupur Station (ADI) - In the old city', 'Sardar Vallabhbhai Patel International Airport (AMD) - 10 km', ARRAY['Gandhinagar (28 km)', 'Vadodara (110 km)']::TEXT[], ARRAY['Adalaj Stepwell (18 km)', 'Sabarmati Ashram', 'Sarkhej Roza (12 km)']::TEXT[], ARRAY['Old City Heritage Havelis', 'Ashram Road', 'Ellisbridge']::TEXT[], ARRAY['Gujarati Thali (Agashiye)', 'Fafda Jalebi at Chandravilas', 'Khaman Dhokla', 'Maskabun Chai']::TEXT[], 'Ahmedabad Metro Line 1 connects the old city; walking is best inside the pols.', 23.0225, 72.5714, 'https://whc.unesco.org/en/list/1551', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-mumbai-victorian-art-deco', 'Victorian Gothic and Art Deco Ensembles of Mumbai', ARRAY['Mumbai Heritage Ensembles', 'Oval Maidan Precinct']::TEXT[], 'Cultural', 'Maharashtra', 'Mumbai City', 'Fort / Marine Drive, Mumbai', 2018, ARRAY['(ii)', '(iv)']::TEXT[], 'Ensemble of 19th-century Victorian Neo-Gothic public buildings facing early 20th-century Art Deco residential and commercial buildings across the historic Oval Maidan.', 'Second-largest concentration of Art Deco buildings in the world after Miami, creating an extraordinary confrontation between 19th-century Victorian Gothic and 20th-century streamlined nautical Art Deco.', 'Captures Mumbai''s historic transformation into the premier international financial and maritime metropolis of modern India.', 'The Art Deco buildings along Marine Drive feature ''nautical modern'' elements: porthole windows, ship bow balconies, and sweeping aerodynamic waves.', ARRAY['Bombay High Court', 'University of Mumbai and Rajabai Clock Tower', 'Old Secretariat', 'Eros Cinema', 'Marine Drive Art Deco Promenade', 'Regal Cinema']::TEXT[], 'Strolling along the sea breeze of Marine Drive at sunset, admiring pastel-toned Art Deco facades on one side and the Arabian Sea on the other.', 'October to March', '2 to 3 hours', 'Churchgate Railway Station - 500 m; CSMT - 1.5 km', 'Chhatrapati Shivaji Maharaj International Airport (BOM) - 22 km', ARRAY['Navi Mumbai', 'Thane']::TEXT[], ARRAY['Gateway of India (1.5 km)', 'Kala Ghoda Arts Precinct', 'Prince of Wales Museum']::TEXT[], ARRAY['Marine Drive', 'Colaba', 'Churchgate']::TEXT[], ARRAY['Coastal Seafood at Trishna', 'Irani Chai at Kyani & Co.', 'Bhelpuri at Chowpatty', 'Parsi Akuri']::TEXT[], 'Walking along Oval Maidan and Marine Drive is best; convenient access via Churchgate station.', 18.9298, 72.8296, 'https://whc.unesco.org/en/list/1480', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-jaipur-city', 'Jaipur City, Rajasthan', ARRAY['The Pink City', 'Walled City of Jaipur']::TEXT[], 'Cultural', 'Rajasthan', 'Jaipur', 'Jaipur', 2019, ARRAY['(ii)', '(iv)', '(vi)']::TEXT[], 'Founded in 1727 CE by astronomer-king Maharaja Sawai Jai Singh II as India''s first planned city in the modern period, designed in collaboration with Bengali architect Vidyadhar Bhattacharya.', 'Gridiron street plan derived from ancient Vedic Vastu Shastra (nine-square mandala); distinctive pink-terracotta facades mandated in 1876 CE to welcome the Prince of Wales.', 'Living world center of traditional artisan crafts: gemstone cutting, block printing, Kundan-Meena jewellery, and blue pottery.', 'The iconic Hawa Mahal (Palace of Winds) with its 953 jharokha honeycomb windows allowed royal women to observe street processions without being seen from outside.', ARRAY['Hawa Mahal', 'City Palace Jaipur', 'Jantar Mantar', 'Albert Hall Museum', 'Bapu Bazaar and Johari Bazaar', 'Nahargarh Fort']::TEXT[], 'Vibrant pink bazaar streets filled with camel carts, jewelers, colorful block-printed textiles, and historical gateways.', 'October to March; Jaipur Literature Festival in January.', '2 to 3 days', 'Jaipur Junction (JP) - 4 km', 'Jaipur International Airport (JAI) - 12 km', ARRAY['Ajmer (130 km)', 'Delhi (260 km)', 'Agra (240 km)']::TEXT[], ARRAY['Amer Fort (10 km)', 'Jaigarh Fort', 'Galtaji Monkey Temple', 'Sanganer']::TEXT[], ARRAY['Heritage Havelis in Old City', 'MI Road', 'Civil Lines']::TEXT[], ARRAY['Dal Baati Churma', 'Pyaaz Kachori', 'Ghevar', 'Ker Sangri', 'Laal Maas']::TEXT[], 'Jaipur Metro runs directly to Badi Chaupar and Chhoti Chaupar inside the walled city.', 26.9124, 75.7873, 'https://whc.unesco.org/en/list/1605', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-ramappa-temple', 'Kakatiya Rudreshwara (Ramappa) Temple, Telangana', ARRAY['Ramappa Temple', 'Rudreshwara Temple Palampet']::TEXT[], 'Cultural', 'Telangana', 'Mulugu', 'Palampet / Mulugu', 2021, ARRAY['(i)', '(iii)']::TEXT[], 'Constructed in 1213 CE during the reign of Kakatiya ruler Ganapati Deva under his general Recharla Rudra; uniquely named after its chief master sculptor, Ramappa.', 'Stands on a 6-foot high star-shaped platform with sandbox foundations to absorb seismic shocks; pyramidical sikhara constructed with porous ''floating bricks'' so light they float on water; exquisite black basalt bracket figures (madhanikas).', 'The crowning architectural achievement of the medieval Kakatiya Dynasty.', 'Italian explorer Marco Polo visited the Kakatiya kingdom and described the temple as the ''brightest star in the galaxy of medieval temples''.', ARRAY['Main Rudreshwara Sanctum', 'Black Basalt Dancing Bracket Figures (Madanikas)', 'Intricately Carved Nandi Mandapa', 'Floating Brick Shikhara', 'Ramappa Lake (Kakatiya water reservoir)']::TEXT[], 'Marveling at the lustrous polish of black basalt sculptures carved with breathtaking movement, gazing across the tranquil waters of Ramappa Lake.', 'October to March', '2 to 3 hours', 'Warangal Railway Station (WL) - 70 km; Kazipet Junction - 75 km', 'Rajiv Gandhi International Airport Hyderabad (HYD) - 215 km', ARRAY['Warangal (70 km)', 'Hyderabad (210 km)']::TEXT[], ARRAY['Warangal Fort (70 km)', 'Thousand Pillar Temple Hanamkonda (65 km)', 'Laknavaram Lake']::TEXT[], ARRAY['Haritha Lake View Resort Ramappa', 'Warangal City']::TEXT[], ARRAY['Telangana Thali', 'Sarva Pindi', 'Gongura Mutton', 'Sakinalu', 'Hyderabadi Biryani']::TEXT[], 'Scenic drive from Warangal via NH-163 (approx. 1.5 hours).', 18.2636, 79.9408, 'https://whc.unesco.org/en/list/1570', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-dholavira', 'Dholavira: a Harappan City', ARRAY['Kotada Timba', 'Dholavira Indus Valley Site']::TEXT[], 'Cultural', 'Gujarat', 'Kutch', 'Khadir Bet / Bhachau', 2021, ARRAY['(iii)', '(iv)']::TEXT[], 'One of the most remarkable and best-preserved urban settlements of the Harappan (Indus Valley) Civilization, thriving from 3000 to 1500 BCE on the island of Khadir Bet in the Great Rann of Kutch.', 'Tripartite city plan consisting of a fortified Citadel, Middle Town, and Lower Town built of dressed stone (unlike the mud-brick of Mohenjo-daro); world''s most sophisticated ancient water management and stormwater reservoir system.', 'Foundational testament to the origins of South Asian urban planning, hydrology, and ancient trade networks.', 'The northern gateway revealed the world-famous ''Dholavira Signboard'', one of the longest known inscriptions of the Indus script featuring 10 large glyphs made of crystalline gypsum.', ARRAY['Massive Rock-Cut Reservoirs', 'Citadel Fortifications and Ceremonial Grounds', 'Ancient Indus Signboard Gateway', 'Dholavira Archaeological Museum', 'Scenic Great Rann of Kutch Road']::TEXT[], 'Walking among the 4,500-year-old stone streets, reservoirs, and drainage canals surrounded by the stark white salt plains of the Rann.', 'November to February', '3 to 4 hours', 'Bhachau Railway Station - 140 km; Bhuj - 215 km', 'Bhuj Airport (BHJ) - 215 km; Ahmedabad Airport - 340 km', ARRAY['Bhuj (215 km)', 'Gandhidham (180 km)', 'Rapar (95 km)']::TEXT[], ARRAY['White Desert of Dhordo', 'Kala Dungar (Black Hill)', 'Bhuj Aina Mahal']::TEXT[], ARRAY['Dholavira Village Homestays', 'Toran Resort Dholavira', 'Rapar']::TEXT[], ARRAY['Kutchi Thali', 'Bajra no Rotlo with Ringna no Oro', 'Kutchi Dabeli', 'Fresh Chhas (Buttermilk)']::TEXT[], 'Approached via the newly built scenic ''Road to Heaven'' highway slicing directly across the white salt flats.', 23.8864, 70.2131, 'https://whc.unesco.org/en/list/1645', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-santiniketan', 'Santiniketan', ARRAY['Visva-Bharati', 'Abode of Peace']::TEXT[], 'Cultural', 'West Bengal', 'Birbhum', 'Bolpur / Santiniketan', 2023, ARRAY['(iv)', '(vi)']::TEXT[], 'Founded in 1863 by Maharshi Debendranath Tagore as an ashram, and transformed in 1901 by Nobel laureate Rabindranath Tagore into an experimental open-air school and university (Visva-Bharati) exploring pan-Asian universal humanism.', 'Open-air classrooms under spreading banyan trees, modernist mud and relief-sculpted architectural houses (Kala Bhavana, Uttarayan complex) designed by Tagore, Nandalal Bose, and Ramkinkar Baij.', 'Birthplace of the Bengal School of Art, modern Indian ecological education, and global cultural dialogue.', 'Tagore utilized his Nobel Prize in Literature funds to expand Visva-Bharati into an international learning center where ''the world makes its home in a single nest'' (Yatra Visvam Bhavatyekanidam).', ARRAY['Uttarayan Complex (Udayan, Konarka, Shyamali, Punashcha)', 'Rabindra Bhavana Museum', 'Kala Bhavana Murals', 'Chhatimtala Meditation Spot', 'Upasana Griha (Glass Prayer Hall)', 'Amar Kutir Artisan Center']::TEXT[], 'Peaceful strolls along red soil pathways shaded by sal trees, listening to students practicing Rabindra Sangeet and Baul folk songs.', 'October to March; Poush Mela in December and Basanta Utsav (Holi) in spring.', '1 to 2 days', 'Bolpur Shantiniketan Railway Station (BHP) - 2.5 km', 'Kazi Nazrul Islam Airport Durgapur (RGH) - 60 km; Netaji Subhash Chandra Bose Airport Kolkata (CCU) - 160 km', ARRAY['Bolpur', 'Suri', 'Kolkata (160 km)']::TEXT[], ARRAY['Kankalitala Shaktipeeth (8 km)', 'Terracotta Temples of Ilambazar', 'Khoai Shonibarer Haat (Saturday Market)']::TEXT[], ARRAY['Shantiniketan Town', 'Prantik', 'Bolpur']::TEXT[], ARRAY['Bengali Thali', 'Luchi Cholar Dal', 'Posto Bora', 'Mishti Doi', 'Rosogolla']::TEXT[], 'Frequent express trains from Howrah and Sealdah in Kolkata (2 to 2.5 hours); cycle-rickshaws and toto e-rickshaws in town.', 23.68, 87.69, 'https://whc.unesco.org/en/list/1675', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO public.unesco_world_heritage (id, official_unesco_name, alternate_names, category, state, district, city_or_nearest_settlement, inscription_year, unesco_criteria, historical_background, architectural_or_ecological_significance, cultural_importance, historical_events_stories, major_attractions, visitor_experience, best_time_to_visit, recommended_visit_duration, nearest_railway_station, nearest_airport, nearby_cities, nearby_heritage_destinations, nearby_hotels_areas, local_cuisine, transportation_information, latitude, longitude, official_unesco_url, data_verification_status) VALUES ('unesco-sacred-ensembles-hoysalas', 'Sacred Ensembles of the Hoysalas', ARRAY['Hoysala Temples of Belur, Halebidu and Somanathapura']::TEXT[], 'Cultural', 'Karnataka', 'Hassan and Mysuru', 'Belur, Halebidu, and Somanathapura', 2023, ARRAY['(i)', '(ii)', '(iv)']::TEXT[], 'Serial inscription of three supreme 12th and 13th-century temples built by the Hoysala Empire: the Chennakeshava Temple at Belur (1117 CE), the Hoysaleswara Temple at Halebidu (1121 CE), and the Keshava Temple at Somanathapura (1268 CE).', 'Carved from soft chloritic schist (soapstone) allowing extraordinary microscopic precision, featuring star-shaped (stellate) plans, stepped friezes of thousands of elephants and horses, and signed sculptor masterworks.', 'Peak realization of medieval Karnata Dravida temple art and soapstone sculptural virtuosity.', 'Sculptors like Mallitamma, Dasoja, and Chavana proudly signed their individual stone panels, an exceptional demonstration of recognized artist identity in ancient India.', ARRAY['Chennakeshava Temple Belur (Madanika bracket figures)', 'Hoysaleswara Temple Halebidu (Endless mythological friezes)', 'Keshava Temple Somanathapura (Pristine triple-shrined trikuta)', 'Monolithic Nandi Pavilions']::TEXT[], 'Gazing in astonishment at intricate soapstone friezes where lace, jewelry, and fingernails are carved in stone with jewel-like delicacy.', 'October to March', '2 days to cover Belur, Halebidu, and Somanathapura', 'Hassan Railway Station (HAS) - 38 km for Belur/Halebidu; Mysuru Junction (MYS) - 35 km for Somanathapura', 'Mangaluru Airport (IXE) - 150 km; Kempegowda International Airport Bengaluru (BLR) - 220 km', ARRAY['Hassan (38 km)', 'Mysuru (35 km from Somanathapura)', 'Bengaluru (215 km)']::TEXT[], ARRAY['Shravanabelagola (Monolithic Gommateshwara statue)', 'Mysore Palace', 'Halebidu Archaeological Museum']::TEXT[], ARRAY['Hassan City', 'Belur KSTDC Hotel Mayura Velapuri', 'Mysuru']::TEXT[], ARRAY['Mysore Masala Dosa', 'Akki Rotti', 'Bisi Bele Bath', 'Mysore Pak', 'Filter Coffee']::TEXT[], 'Excellent four-lane highway from Bengaluru to Hassan (3.5 hours); convenient local taxis for the circuit.', 13.1623, 75.8596, 'https://whc.unesco.org/en/list/1670', 'VERIFIED_OFFICIAL')
ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

